INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013854,69,40,1,1,'Yesu Kristo alikuwa mzawa wa Daudi, mzawa wa Abrahamu. Hii ndiyo orodha ya ukoo wake:'),
(2013855,69,40,1,2,'Abrahamu alimzaa Isaka, Isaka alimzaa Yakobo, Yakobo alimzaa Yuda na ndugu zake,'),
(2013856,69,40,1,3,'Yuda alimzaa Faresi na Zera (mama yao alikuwa Tamari), Faresi alimzaa Hesroni, Hesroni alimzaa Rami,'),
(2013857,69,40,1,4,'Rami alimzaa Aminadabu, Aminadabu alimzaa Nashoni, Nashoni alimzaa Salmoni,'),
(2013858,69,40,1,5,'Salmoni alimzaa Boazi (mama yake Boazi alikuwa Rahabu). Boazi na Ruthi walikuwa wazazi wa Obedi, Obedi alimzaa Yese,'),
(2013859,69,40,1,6,'naye Yese alimzaa Mfalme Daudi. Daudi alimzaa Solomoni (mama yake Solomoni alikuwa mke wa Uria).'),
(2013860,69,40,1,7,'Solomoni alimzaa Rehoboamu, Rehoboamu alimzaa Abiya, Abiya alimzaa Asa,'),
(2013861,69,40,1,8,'Asa alimzaa Yehoshafati, Yehoshafati alimzaa Yoramu, Yoramu alimzaa Uzia,'),
(2013862,69,40,1,9,'Uzia alimzaa Yothamu, Yothamu alimzaa Ahazi, Ahazi alimzaa Hezekia,'),
(2013863,69,40,1,10,'Hezekia alimzaa Manase, Manase alimzaa Amoni, Amoni alimzaa Yosia,'),
(2013864,69,40,1,11,'Yosia alimzaa Yekonia na ndugu zake. Huo ulikuwa wakati Wayahudi walipopelekwa uhamishoni Babuloni.'),
(2013865,69,40,1,12,'Baada ya Wayahudi kupelekwa uhamishomi Babuloni: Yekonia alimzaa Shealtieli, Shealtieli alimzaa Zerobabeli,'),
(2013866,69,40,1,13,'Zerobabeli alimzaa Abiudi, Abiudi alimzaa Eliakimu, Eliakimu alimzaa Azori,'),
(2013867,69,40,1,14,'Azori alimzaa Zadoki, Zadoki alimzaa Akimu, Akimu alimzaa Eliudi,'),
(2013868,69,40,1,15,'Eliudi alimzaa Eleazeri, Eleazeri alimzaa Mathani, Mathani alimzaa Yakobo,'),
(2013869,69,40,1,16,'Yakobo alimzaa Yosefu, aliyekuwa mume wake Maria, mama yake Yesu, aitwaye Kristo.'),
(2013870,69,40,1,17,'Basi, kulikuwa na vizazi kumi na vinne tangu Abrahamu mpaka Daudi, vizazi kumi na vinne tangu Daudi mpaka Wayahudi walipochukuliwa mateka Babuloni, na vizazi kumi na vinne tangu kuchukuliwa mateka mpaka wakati wa Kristo.'),
(2013871,69,40,1,18,'Basi, hivi ndivyo Yesu Kristo alivyozaliwa: Maria, mama yake, alikuwa ameposwa na Yosefu. Lakini kabla hawajakaa pamoja kama mume na mke, alionekana kuwa mja mzito kwa uwezo wa Roho Mtakatifu.'),
(2013872,69,40,1,19,'Yosefu, mumewe, kwa vile alikuwa mwadilifu, hakutaka kumwaibisha hadharani; hivyo alikusudia kumwacha kwa siri.'),
(2013873,69,40,1,20,'Alipokuwa bado anawaza jambo hilo, malaika wa Bwana alimtokea katika ndoto, akamwambia, "Yosefu, mwana wa Daudi, usiogope kumchukua Maria awe mke wako, maana amekuwa mja mzito kwa uwezo wa Roho Mtakatifu.'),
(2013874,69,40,1,21,'Atajifungua mtoto wa kiume, nawe utampa jina Yesu, kwa kuwa yeye atawaokoa watu wake kutoka katika dhambi zao."'),
(2013875,69,40,1,22,'Basi, haya yote yalitukia ili litimie lile neno Bwana alilosema kwa njia ya nabii:'),
(2013876,69,40,1,23,'"Bikira atachukua mimba, atamzaa mtoto wa kiume, naye ataitwa Emanueli" (maana yake, "Mungu yu pamoja nasi").'),
(2013877,69,40,1,24,'Hivyo, Yosefu alipoamka usingizini alifanya kama malaika huyo alivyomwambia, akamchukua mke wake nyumbani.'),
(2013878,69,40,1,25,'Lakini hakumjua kamwe kimwili hata Maria alipojifungua mtoto wa kiume. Naye Yosefu akampa jina Yesu.'),
(2013879,69,40,2,1,'Yesu alizaliwa mjini Bethlehemu, mkoani Yudea, wakati Herode alipokuwa mfalme. Punde tu baada ya kuzaliwa kwake, wataalamu wa nyota kutoka mashariki walifika Yerusalemu,'),
(2013880,69,40,2,2,'wakauliza, "Yuko wapi mtoto, Mfalme wa Wayahudi, aliyezaliwa? Tumeiona nyota yake ilipotokea mashariki, tukaja kumwabudu."'),
(2013881,69,40,2,3,'Mfalme Herode aliposikia hayo, alifadhaika, yeye pamoja na wakazi wote wa Yerusalemu.'),
(2013882,69,40,2,4,'Basi akawaita pamoja makuhani wakuu wote na walimu wa Sheria, akawauliza, "Kristo atazaliwa wapi?"'),
(2013883,69,40,2,5,'Nao wakamjibu, "Mjini Bethlehemu, mkoani Yudea. Ndivyo nabii alivyoandika:'),
(2013884,69,40,2,6,'`Ewe Bethlehemu katika nchi ya Yuda, kwa vyovyote wewe si mdogo kabisa kati ya viongozi wa Yuda; maana kwako atatokea kiongozi atakayewaongoza watu wangu, Israeli."`'),
(2013885,69,40,2,7,'Hapo, Herode aliwaita faraghani hao wataalamu wa nyota, akawauliza wakati hasa ile nyota ilipowatokea.'),
(2013886,69,40,2,8,'Kisha akawatuma Bethlehemu akisema, "Nendeni mkachunguze kwa makini habari za mtoto huyo. Mkisha mpata nileteeni habari ili nami niende nikamwabudu."'),
(2013887,69,40,2,9,'Baada ya kumsikiliza mfalme, hao wataalamu wa nyota wakaenda. Kumbe ile nyota waliyokuwa wameiona upande wa mashariki iliwatangulia hata ikaenda kusimama juu ya mahali pale alipokuwa mtoto.'),
(2013888,69,40,2,10,'Walipoiona hiyo nyota, walifurahi mno.'),
(2013889,69,40,2,11,'Basi, wakaingia nyumbani, wakamwona yule mtoto pamoja na Maria mama yake; wakapiga magoti, wakamsujudia. Kisha wakafungua hazina zao, wakampa zawadi: dhahabu, ubani na manemane. ic'),
(2013890,69,40,2,12,'Mungu aliwaonya katika ndoto wasimrudie Herode; hivyo wakarudi makwao kwa njia nyingine.'),
(2013891,69,40,2,13,'Baada ya wale wageni kuondoka, malaika wa Bwana alimtokea Yosefu katika ndoto, akamwambia, "Amka! Mchukue mtoto pamoja na mama yake, mkimbilie Misri. Kaeni huko mpaka nitakapokwambia, maana Herode anakusudia kumwua huyu mtoto."'),
(2013892,69,40,2,14,'Hivyo, Yosefu aliamka, akamchukua mtoto pamoja na mama yake, akaondoka usiku, akaenda Misri.'),
(2013893,69,40,2,15,'Akakaa huko mpaka Herode alipokufa. Jambo hilo lilifanyika ili neno alilosema Bwana kwa njia ya nabii litimie: "Nilimwita Mwanangu kutoka Misri."'),
(2013894,69,40,2,16,'Herode alipogundua kwamba wale wataalamu wa nyota walikuwa wamemhadaa, alikasirika sana. Akaamuru watoto wote wa kiume mjini Bethlehemu na kandokando yake wenye umri wa miaka miwili na chini yake wauawe. Alifanya hivyo kufuatana na muda aliopata kujua kutoka kwa wale wataalamu wa nyota.'),
(2013895,69,40,2,17,'Ndivyo yalivyotimia maneno yaliyosemwa kwa njia ya nabii Yeremia:'),
(2013896,69,40,2,18,'"Sauti imesikika mjini Rama, kilio na maombolezo mengi. Raheli anawalilia watoto wake, wala hataki kutulizwa, maana wote wamefariki."'),
(2013897,69,40,2,19,'Baada ya kifo cha Herode, malaika wa Bwana alimtokea Yosefu katika ndoto kule Misri,'),
(2013898,69,40,2,20,'akamwambia, "Amka! Mchukue mtoto pamoja na mama yake, urudi tena katika nchi ya Israeli, maana wale waliotaka kumwua mtoto huyo wamekwisha kufa."'),
(2013899,69,40,2,21,'Basi, Yosefu aliamka, akamchukua mtoto pamoja na mama yake, akarejea katika nchi ya Israeli.'),
(2013900,69,40,2,22,'Lakini Yosefu aliposikia kwamba Arkelao mwanawe Herode alikuwa mfalme wa Yudea mahali pa baba yake, aliogopa kwenda huko. Naye baada ya kuonywa katika ndoto, alikwenda katika mkoa wa Galilaya,'),
(2013901,69,40,2,23,'akahamia katika mji uitwao Nazareti. Ndivyo yalivyotimia maneno yaliyonenwa kwa njia ya manabii: "Ataitwa Mnazare."'),
(2013902,69,40,3,1,'Siku hizo Yohane Mbatizaji alitokea, akaanza kuhubiri katika jangwa la Yudea:'),
(2013903,69,40,3,2,'"Tubuni, maana Ufalme wa mbinguni umekaribia."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013904,69,40,3,3,'Huyu Yohane ndiye yule ambaye nabii Isaya alinena juu yake aliposema: "Sauti ya mtu imesikika jangwani: `Mtayarishieni Bwana njia yake, nyoosheni vijia vyake."`'),
(2013905,69,40,3,4,'Yohane alivaa vazi lililoshonwa kwa manyoya ya ngamia, na ukanda wa ngozi kiunoni mwake. Chakula chake kilikuwa nzige na asali ya mwituni.'),
(2013906,69,40,3,5,'Basi, watu kutoka Yerusalemu, kutoka mkoa wote wa Yudea na sehemu zote za kandokando ya mto Yordani, walimwendea,'),
(2013907,69,40,3,6,'wakaziungama dhambi zao, naye akawabatiza katika mto Yordani.'),
(2013908,69,40,3,7,'Lakini alipowaona Mafarisayo wengi na Masadukayo wanamjia ili awabatize, aliwaambia, "Enyi kizazi cha nyoka! Ni nani aliyewadokezea kwamba mnaweza kuiepuka ghadhabu inayokuja?'),
(2013909,69,40,3,8,'Onyesheni basi kwa matendo, kwamba mmetubu kweli.'),
(2013910,69,40,3,9,'Msidhani kwamba mtaweza kujitetea kwa kusema, `Baba yetu ni Abrahamu!` Nawaambieni hakika, Mungu anaweza kuyafanya mawe haya yawe watoto wa Abrahamu.'),
(2013911,69,40,3,10,'Basi, shoka liko tayari kuikata mizizi ya miti; hivyo, kila mti usiozaa matunda mazuri, utakatwa na kutupwa motoni.'),
(2013912,69,40,3,11,'Mimi ninawabatizeni kwa maji kuonyesha kwamba mmetubu. Lakini yule anayekuja baada yangu ana uwezo kuliko mimi. Mimi sistahili hata kubeba viatu vyake. Yeye atawabatizeni kwa Roho Mtakatifu na kwa moto.'),
(2013913,69,40,3,12,'Yeye anashika mkononi chombo cha kupuria nafaka, ili aipure nafaka yake; akusanye ngano ghalani, na makapi ayachome kwa moto usiozimika." ic'),
(2013914,69,40,3,13,'Wakati huo Yesu alitoka Galilaya akafika katika mto Yordani, akamwendea Yohane ili abatizwe naye.'),
(2013915,69,40,3,14,'Lakini Yohane alijaribu kumzuia akisema, "Je, wewe unakuja kwangu? Mimi hasa ndiye ninayehitaji kubatizwa nawe."'),
(2013916,69,40,3,15,'Lakini Yesu akamjibu, "Acha tu iwe hivyo kwa sasa, maana kwa namna hii inafaa tuyatekeleze yale yote Mungu anayotaka." Hapo Yohane akakubali.'),
(2013917,69,40,3,16,'Mara tu Yesu alipokwisha batizwa, alitoka majini; na ghafla mbingu zikafunguka, akaona Roho wa Mungu akishuka kama njiwa na kutua juu yake.'),
(2013918,69,40,3,17,'Sauti kutoka mbinguni ikasema, "Huyu ndiye Mwanangu mpendwa, nimependezwa naye."'),
(2013919,69,40,4,1,'Kisha Roho alimwongoza Yesu mpaka jangwani ili ajaribiwe na Ibilisi.'),
(2013920,69,40,4,2,'Akafunga siku arubaini mchana na usiku, na mwishowe akaona njaa.'),
(2013921,69,40,4,3,'Basi, mshawishi akamjia, akamwambia, "Ikiwa wewe ni Mwana wa Mungu, amuru mawe haya yawe mikate."'),
(2013922,69,40,4,4,'Yesu akamjibu, "Imeandikwa katika Maandiko Matakatifu: `Binadamu hataishi kwa mikate tu, ila kwa kila neno asemalo Mungu."`'),
(2013923,69,40,4,5,'Kisha Ibilisi akamchukua mpaka Yerusalemu, mji mtakatifu, akamweka juu ya mnara wa hekalu,'),
(2013924,69,40,4,6,'akamwambia, "Ikiwa wewe ni Mwana wa Mungu, jitupe chini; maana imeandikwa: `Mungu atawaamuru malaika wake kwa ajili yako; watakuchukua mikononi mwao, usije ukajikwaa kwenye jiwe."`'),
(2013925,69,40,4,7,'Yesu akamwambia, "Imeandikwa pia: `Usimjaribu Bwana, Mungu wako."`'),
(2013926,69,40,4,8,'Kisha Ibilisi akamchukua mpaka juu ya mlima mrefu, akamwonyesha falme zote za ulimwengu na fahari zake,'),
(2013927,69,40,4,9,'akamwambia, "Hivi vyote nitakupa kama tu ukipiga magoti na kuniabudu."'),
(2013928,69,40,4,10,'Hapo, Yesu akamwambia, "Nenda zako Shetani! Imeandikwa: `Utamwabudu Bwana Mungu wako na kumtumikia yeye peke yake."`'),
(2013929,69,40,4,11,'Basi, Ibilisi akamwacha, na malaika wakaja, wakamhudumia.'),
(2013930,69,40,4,12,'Yesu aliposikia kwamba Yohane ametiwa gerezani alikwenda Galilaya.'),
(2013931,69,40,4,13,'Aliondoka Nazareti, akaenda Kafarnaumu, mji ulio kando ya bahari ya Genesareti, mpakani mwa wilaya za Zabuloni na Naftali, akakaa huko.'),
(2013932,69,40,4,14,'Ndivyo lilivyotimia lile neno lililosemwa kwa njia ya nabii Isaya:'),
(2013933,69,40,4,15,'"Nchi ya Zabuloni na nchi ya Naftali, kuelekea baharini ng`ambo ya mto Yordani, Galilaya nchi ya watu wa Mataifa!'),
(2013934,69,40,4,16,'Watu waliokaa gizani wameona mwanga mkubwa. Nao walioishi katika nchi ya giza na kivuli cha kifo, mwanga umewaangazia!"'),
(2013935,69,40,4,17,'Tangu wakati huo Yesu alianza kuhubiri akisema, "Tubuni, maana ufalme wa mbinguni umekaribia!"'),
(2013936,69,40,4,18,'Yesu alipokuwa anatembea kando ya ziwa Galilaya, aliwaona ndugu wawili wavuvi; Simoni (aitwae Petro) na Andrea, ndugu yake; walikuwa wakivua samaki kwa nyavu ziwani.'),
(2013937,69,40,4,19,'Basi, akawaambia, "Nifuateni, nami nitawafanya ninyi wavuvi wa watu."'),
(2013938,69,40,4,20,'Mara wakaziacha nyavu zao, wakamfuata. ic'),
(2013939,69,40,4,21,'Alipokwenda mbele kidogo, aliwaona ndugu wengine wawili: Yakobo na Yohane, wana wa Zebedayo. Hao walikuwa ndani ya mashua pamoja na baba yao Zebedayo, wakitengeneza nyavu zao. Basi Yesu akawaita,'),
(2013940,69,40,4,22,'nao mara wakaiacha mashua pamoja na baba yao, wakamfuata.'),
(2013941,69,40,4,23,'Yesu alikuwa anakwenda kila mahali wilayani Galilaya, akifundisha katika masunagogi na kuhubiri Habari Njema juu ya ufalme wa Mungu. Aliponya kila namna ya maradhi na magonjwa waliyokuwa nayo watu.'),
(2013942,69,40,4,24,'Habari zake zikaenea katika mkoa wote wa Siria. Wagonjwa wote wenye maradhi ya kila namna na wale waliosumbuliwa na kila namna ya taabu: waliopagawa na pepo, wenye kifafa na watu waliokuwa wamelemaa, walipelekwa kwake; naye akawaponya wote.'),
(2013943,69,40,4,25,'Makundi mengi ya watu kutoka Galilaya, Dekapoli, Yerusalemu, Yudea na ng`ambo ya mto Yordani, walimfuata.'),
(2013944,69,40,5,1,'Yesu alipoyaona makundi ya watu, alipanda mlimani, akaketi. Wanafunzi wake wakamwendea,'),
(2013945,69,40,5,2,'naye akaanza kuwafundisha:'),
(2013946,69,40,5,3,'"Heri walio maskini rohoni, maana ufalme wa mbinguni ni wao.'),
(2013947,69,40,5,4,'Heri walio na huzuni, maana watafarijiwa.'),
(2013948,69,40,5,5,'Heri walio wapole, maana watairithi nchi.'),
(2013949,69,40,5,6,'Heri wenye njaa na kiu ya kufanya atakavyo Mungu, maana watashibishwa.'),
(2013950,69,40,5,7,'Heri walio na huruma, maana watahurumiwa.'),
(2013951,69,40,5,8,'Heri wenye moyo safi, maana watamwona Mungu.'),
(2013952,69,40,5,9,'Heri wenye kuleta amani, maana wataitwa watoto wa Mungu.'),
(2013953,69,40,5,10,'Heri wanaoteswa kwa sababu ya kufanya atakavyo Mungu, maana ufalme wa mbinguni ni wao.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013954,69,40,5,11,'"Heri yenu ninyi watu wakiwatukana, wakiwadhulumu na kuwasingizia kila aina ya uovu kwa ajili yangu.'),
(2013955,69,40,5,12,'Furahini na kushangilia maana tuzo lenu ni kubwa mbinguni. Hivyo ndivyo walivyowadhulumu manabii waliokuwako kabla yenu.'),
(2013956,69,40,5,13,'"Ninyi ni chumvi ya dunia! Lakini chumvi ikipoteza ladha yake itakolezwa na nini? Haifai kitu tena, ila hutupwa nje na kukanyagwa na watu.'),
(2013957,69,40,5,14,'"Ninyi ni mwanga wa ulimwengu! Mji uliojengwa juu ya mlima hauwezi kufichika.'),
(2013958,69,40,5,15,'Wala watu hawawashi taa na kuifunika kwa chungu, ila huiweka juu ya kinara ili iwaangazie wote waliomo nyumbani.'),
(2013959,69,40,5,16,'Vivyo hivyo, ni lazima mwanga wenu uangaze mbele ya watu, ili wayaone matendo yenu mema, wamtukuze Baba yenu aliye mbinguni."'),
(2013960,69,40,5,17,'"Msidhani ya kuwa nimekuja kutangua Sheria ya Mose na mafundisho ya manabii. Sikuja kutangua bali kukamilisha.'),
(2013961,69,40,5,18,'Kweli nawaambieni, mpaka hapo mbingu na dunia zitakapopita, hakuna hata nukta moja au sehemu ndogo kabisa ya Sheria itakayoondolewa, mpaka yote yametimia.'),
(2013962,69,40,5,19,'Basi, yeyote atakayevunja hata amri moja ndogo kuliko zote, na kuwafundisha wengine wafanye hivyo, huyo atakuwa mdogo kabisa katika Ufalme wa mbiguni. Lakini yule atakayezishika na kuwafundisha wengine, huyo atakuwa mkubwa katika Ufalme wa mbinguni.'),
(2013963,69,40,5,20,'Ndiyo maana nawaambieni, wema wenu usipozidi ule wa Mafarisayo na walimu wa Sheria, hamtaingia kamwe katika Ufalme wa mbinguni.'),
(2013964,69,40,5,21,'"Mmekwisha sikia ya kuwa watu wa kale waliambiwa: `Usiue! Atakayeua lazima ahukumiwe.`'),
(2013965,69,40,5,22,'Lakini mimi nawaambieni, yeyote anayemkasirikia ndugu yake, lazima ahukumiwe. Anayemdharau ndugu yake atapelekwa mahakamani. Anayemwita ndugu yake: `Pumbavu` atastahili kuingia katika moto wa Jehanamu.'),
(2013966,69,40,5,23,'Basi, ukipeleka sadaka yako mbele ya madhabahu na hapo ukakumbuka kwamba ndugu yako ana ugomvi nawe,'),
(2013967,69,40,5,24,'iache sadaka yako mbele ya madhabahu, nenda kwanza ukapatane na ndugu yako, ndipo urudi ukatoe sadaka yako.'),
(2013968,69,40,5,25,'"Patana na mshtaki wako upesi mkiwa bado njiani, kwenda mahakamani. La sivyo, mshtaki wako atakukabidhi kwa hakimu, naye hakimu atakukabidhi kwa askari, nawe utafungwa gerezani.'),
(2013969,69,40,5,26,'Kweli nakwambia, hutatoka humo mpaka umemaliza kulipa senti ya mwisho.'),
(2013970,69,40,5,27,'"Mmesikia ya kuwa watu waliambiwa: `Usizini!`'),
(2013971,69,40,5,28,'Lakini mimi nawaambieni, atakayemtazama mwanamke kwa kumtamani, amekwisha zini naye moyoni mwake.'),
(2013972,69,40,5,29,'Basi, kama jicho lako la kulia linakukosesha, ling`oe ukalitupe mbali. Afadhali zaidi kwako kupoteza kiungo kimoja cha mwili wako, kuliko mwili wako wote kutupwa katika moto wa Jehanamu.'),
(2013973,69,40,5,30,'Na kama mkono wako wa kulia unakukosesha, ukate ukautupe mbali. Afadhali zaidi kupoteza kiungo kimoja cha mwili, kuliko mwili wako wote uende katika moto wa Jehanamu.'),
(2013974,69,40,5,31,'"Ilikwisha semwa pia: `Anayemwacha mke wake, yampasa ampe hati ya talaka.`'),
(2013975,69,40,5,32,'Lakini mimi nawaambieni, anayempa mkewe talaka, isipokuwa kwa sababu ya uzinzi, anamfanya azini; na mtu akimwoa mwanamke aliyepewa talaka, anazini.'),
(2013976,69,40,5,33,'"Tena mmesikia kuwa watu wa kale waliambiwa: `Usivunje kiapo chako, bali ni lazima utimize kiapo chako kwa Bwana.`'),
(2013977,69,40,5,34,'Lakini mimi nawaambieni, msiape kamwe; wala kwa mbingu, maana ni kiti cha enzi cha Mungu;'),
(2013978,69,40,5,35,'wala kwa dunia, maana ni kiti chake cha kuwekea miguu; wala kwa Yerusalemu, maana ni mji wa Mfalme mkuu.'),
(2013979,69,40,5,36,'Wala usiape kwa kichwa chako, maana huwezi kuufanya hata unywele mmoja kuwa mweupe au mweusi.'),
(2013980,69,40,5,37,'Ukisema, `Ndiyo`, basi iwe `Ndiyo`; ukisema `Siyo`, basi iwe kweli `Siyo`. Chochote kinachozidi hayo hutoka kwa yule Mwovu.'),
(2013981,69,40,5,38,'"Mmesikia kwamba ilisemwa: `Jicho kwa jicho, jino kwa jino.`'),
(2013982,69,40,5,39,'Lakini mimi nawaambieni, usimlipize kisasi mtu mbaya. Mtu akikupiga kofi shavu la kulia, mgeuzie pia shavu la pili.'),
(2013983,69,40,5,40,'Mtu akikupeleka mahakamani kutaka kukuchukulia shati lako, mwache achukue pia koti lako.'),
(2013984,69,40,5,41,'Mtu akikulazimisha kubeba mzigo wake kilomita moja, ubebe kilomita mbili.'),
(2013985,69,40,5,42,'Akuombaye mpe, na mtu akitaka kukukopa kitu usimnyime.'),
(2013986,69,40,5,43,'"Mmesikia kwamba ilisemwa: `Mpende jirani yako na kumchukia adui yako.`'),
(2013987,69,40,5,44,'Lakini mimi nawaambieni, wapendeni adui zenu na kuwaombea wale wanaowadhulumu ninyi'),
(2013988,69,40,5,45,'ili mpate kuwa watoto wa Baba yenu aliye mbinguni. Kwa maana yeye huwaangazia jua lake watu wabaya na wema, na kuwanyeshea mvua watu wanyofu na waovu.'),
(2013989,69,40,5,46,'Je, mtapata tuzo gani kwa kuwapenda tu wale wanaowapenda ninyi? Hakuna! Kwa maana hata watoza ushuru hufanya hivyo!'),
(2013990,69,40,5,47,'Kama mkiwasalimu ndugu zenu tu, je, mmefanya kitu kisicho cha kawaida? Hata watu wasiomjua Mungu nao hufanya vivyo hivyo.'),
(2013991,69,40,5,48,'Basi, muwe wakamilifu kama Baba yenu wa mbinguni alivyo mkamilifu.'),
(2013992,69,40,6,1,'"Jihadharini msije mkafanya matendo yenu mema mbele ya watu kusudi mwonekane nao. La sivyo, Baba yenu aliye mbinguni hatawapeni tuzo.'),
(2013993,69,40,6,2,'"Basi, unapomsaidia maskini, usijitangaze. Usifanye kama wanafiki wafanyavyo katika masunagogi na njiani ili watu wawasifu. Kweli nawaambieni, hao wamekwisha pata tuzo lao.'),
(2013994,69,40,6,3,'Lakini wewe unapomsaidia maskini, fanya hivyo kwamba hata rafiki yako asijue ufanyalo.'),
(2013995,69,40,6,4,'Toa msaada wako kwa siri, na Baba yako aonaye yaliyofichika, atakutuza.'),
(2013996,69,40,6,5,'"Mnaposali, msifanye kama wanafiki. Wao hupenda kusimama na kusali katika masunagogi na katika pembe za njia ili watu wawaone. Kweli nawaambieni, hao wamekwisha pata tuzo lao.'),
(2013997,69,40,6,6,'Lakini wewe unaposali, ingia chumbani mwako, funga mlango, kisha umwombe Baba yako asiyeonekana. Naye Baba yako aonaye yaliyofichika, atakutuza.'),
(2013998,69,40,6,7,'"Mnaposali, msipayuke maneno kama watu wasiomjua Mungu. Wao hudhani kwamba Mungu atawasikiliza ati kwa sababu ya maneno mengi.'),
(2013999,69,40,6,8,'Msiwe kama wao. Baba yenu anajua mnayoyahitaji hata kabla ya kumwomba.'),
(2014000,69,40,6,9,'Basi, hivi ndivyo mnavyopaswa kusali: `Baba yetu uliye mbinguni: Jina lako litukuzwe.'),
(2014001,69,40,6,10,'Ufalme wako ufike. Utakalo lifanyike duniani kama mbinguni.'),
(2014002,69,40,6,11,'Utupe leo chakula chetu tunachohitaji.'),
(2014003,69,40,6,12,'Utusamehe makosa yetu, kama nasi tunavyowasamehe waliotukosea.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014004,69,40,6,13,'Usitutie katika majaribu, lakini utuokoe na yule Mwovu.`*fa* na utukufu, hata milele. Amina.'),
(2014005,69,40,6,14,'"Maana mkiwasamehe watu makosa yao, Baba yenu wa mbinguni atawasamehe ninyi pia.'),
(2014006,69,40,6,15,'Lakini msipowasamehe watu makosa yao, naye Baba yenu hatawasamehe ninyi makosa yenu.'),
(2014007,69,40,6,16,'"Mnapofunga, msiwe na huzuni kama wanafiki. Wao hukunja nyuso zao wapate kuonekana na watu kuwa wanafunga. Nawaambieni hakika, hao wamekwisha pata tuzo lao.'),
(2014008,69,40,6,17,'Wewe lakini unapofunga, paka kichwa chako mafuta, nawa uso wako,'),
(2014009,69,40,6,18,'ili mtu yeyote asijue kwamba unafunga, ila ujulikane tu kwa Baba yako asiyeonekana. Naye Baba yako aonaye yaliyofichika atakutuza.'),
(2014010,69,40,6,19,'"Msijiwekee hazina hapa duniani ambako nondo na kutu huharibu, na wezi huingia na kuiba.'),
(2014011,69,40,6,20,'Jiwekeeni hazina mbinguni ambako nondo na kutu hawawezi kuiharibu, wala wezi hawaingii wakaiba.'),
(2014012,69,40,6,21,'Maana pale ilipo hazina yako, ndipo pia utakapokuwa moyo wako.'),
(2014013,69,40,6,22,'"Jicho ni taa ya mwili. Kama jicho lako ni zima, mwili wako wote utakuwa katika mwanga.'),
(2014014,69,40,6,23,'Lakini ikiwa jicho lako ni bovu, mwili wako wote utakuwa katika giza. Basi, ikiwa mwanga ulioko ndani yako ni giza, basi, hilo ni giza la kutisha mno.'),
(2014015,69,40,6,24,'"Hakuna mtu awezaye kutumikia mabwana wawili. Maana atamchukia mmoja na kumpenda huyo wa pili; au ataambatana na mmoja na kumdharau huyo mwingine. Hamwezi kumtumikia Mungu na mali pamoja.'),
(2014016,69,40,6,25,'"Ndiyo maana nawaambieni, msiwe na wasiwasi juu ya chakula na kinywaji mnavyohitaji ili kuishi, wala juu ya mavazi mnayohitaji kwa ajili ya miili yenu. Je, maisha ni chakula tu au zaidi? Na mwili, je, si zaidi ya mavazi?'),
(2014017,69,40,6,26,'Waangalieni ndege wa mwituni: hawapandi, hawavuni, wala hawana ghala yoyoye. Hata hivyo, Baba yenu wa mbinguni huwalisha. Je, ninyi si wa thamani kuliko hao?'),
(2014018,69,40,6,27,'Ni nani miongoni mwenu kwa kuwa na wasiwasi sana anaweza kuuongeza muda wa maisha yake?'),
(2014019,69,40,6,28,'"Na kuhusu mavazi, ya nini kuwa na wasiwasi? Tazameni maua ya porini jinsi yanavyostawi. Hayafanyi kazi wala hayasokoti.'),
(2014020,69,40,6,29,'Lakini nawaambieni, hata Solomoni mwenyewe na fahari zake zote hakupata kuvikwa vizuri kama ua mojawapo.'),
(2014021,69,40,6,30,'Ikiwa basi Mungu hulivika hivyo jani la shambani ambalo leo liko na kesho latupwa motoni, je, hatafanya zaidi kwenu ninyi? Enyi watu wenye imani haba!'),
(2014022,69,40,6,31,'"Basi, msiwe na wasiwasi: `Tutakula nini, tutakunywa nini, tutavaa nini!`'),
(2014023,69,40,6,32,'Maana hayo yote yanahangaikiwa na watu wasiomjua Mungu. Baba yenu wa mbinguni anajua kwamba mnahitaji vitu hivyo vyote.'),
(2014024,69,40,6,33,'Bali, zingatieni kwanza Ufalme wa Mungu na matakwa yake, na hayo mengine yote mtapewa kwa ziada.'),
(2014025,69,40,6,34,'Basi, msiwe na wasiwasi juu ya kesho; kesho inayo yake. Matatizo ya siku moja yanawatosheni kwa siku hiyo.'),
(2014026,69,40,7,1,'"Msiwahukumu wengine, msije nanyi mkahukumiwa na Mungu;'),
(2014027,69,40,7,2,'kwa maana jinsi mnavyowahukumu wengine, ndivyo nanyi mtakavyohukumiwa; na kipimo kilekile mnachotumia kwa wengine ndicho Mungu atakachotumia kwenu.'),
(2014028,69,40,7,3,'Kwa nini wakiona kibanzi kilicho jichoni mwa ndugu yako, na papo hapo huioni boriti iliyoko jichoni mwako?'),
(2014029,69,40,7,4,'Au, wawezaje kumwambia ndugu yako, `Ndugu, ngoja nikuondoe kibanzi jichoni mwako`, wakati wewe mwenyewe unayo boriti jichoni mwako?'),
(2014030,69,40,7,5,'Mnafiki wewe! Ondoa kwanza boriti iliyoko jichoni mwako na hapo ndipo utaona waziwazi kiasi cha kuweza kuondoa kibanzi kilichoko jichoni mwa ndugu yako.'),
(2014031,69,40,7,6,'"Msiwape mbwa vitu vitakatifu wasije wakageuka na kuwararua ninyi; wala msiwatupie nguruwe lulu zenu wasije wakazikanyaga.'),
(2014032,69,40,7,7,'"Ombeni, nanyi mtapewa; tafuteni, nanyi mtapata; bisheni, nanyi mtafunguliwa.'),
(2014033,69,40,7,8,'Maana, aombaye hupewa, atafutaye hupata, na abishaye hufunguliwa.'),
(2014034,69,40,7,9,'Je, kuna yeyote miongoni mwenu ambaye mtoto wake akimwomba mkate, atampa jiwe?'),
(2014035,69,40,7,10,'Au je, akimwomba samaki, atampa nyoka?'),
(2014036,69,40,7,11,'Kama basi ninyi, ingawa ni waovu, mwajua kuwapa watoto wenu vitu vizuri, hakika Baba yenu wa mbinguni atafanya zaidi: atawapa mema wale wanaomwomba.'),
(2014037,69,40,7,12,'"Watendeeni wengine yale mnayotaka wao wawatendee ninyi. Hii ndiyo maana ya Sheria ya Mose na mafundisho ya manabii.'),
(2014038,69,40,7,13,'"Ingieni kwa kupitia mlango mwembamba. Kwa maana njia inayoongoza kwenye maangamizi ni pana, na mlango wa kuingilia humo ni mpana; waendao njia hiyo ni wengi.'),
(2014039,69,40,7,14,'Lakini njia inayoongoza kwenye uzima ni nyembamba, na mlango wa kuingilia humo ni mwembamba; ni watu wachache tu wanaoweza kuigundua njia hiyo.'),
(2014040,69,40,7,15,'"Jihadharini na manabii wa uongo. Wao huja kwenu wakionekana kama kondoo kwa nje, lakini kwa ndani ni mbwa mwitu wakali.'),
(2014041,69,40,7,16,'Mtawatambua kwa matendo yao. Je, watu huchuma zabibu katika miti ya miiba, au tini katika mbigili? La!'),
(2014042,69,40,7,17,'Basi, mti mwema huzaa matunda mema, na mti mbaya huzaa matunda mabaya.'),
(2014043,69,40,7,18,'Mti mwema hauwezi kuzaa matunda mabaya, wala mti mbaya hauwezi kuzaa matunda mema.'),
(2014044,69,40,7,19,'Kila mti usiozaa matunda mema utakatwa na kutupwa motoni.'),
(2014045,69,40,7,20,'Kwa hiyo, mtawatambua kwa matendo yao. ic'),
(2014046,69,40,7,21,'"Si kila aniambiaye, `Bwana, Bwana,` ataingia katika Ufalme wa mbinguni; ila ni yule tu anayetimiza mapenzi ya Baba yangu aliye mbinguni.'),
(2014047,69,40,7,22,'Wengi wataniambia Siku ile ya hukumu: `Bwana, Bwana! kwa jina lako tulitangaza ujumbe wako, na kwa jina lako tuliwatoa pepo na kufanya miujiza mingi.`'),
(2014048,69,40,7,23,'Hapo nitawaambia: `Sikuwajua ninyi kamwe; ondokeni mbele yangu, enyi watenda maovu.`'),
(2014049,69,40,7,24,'"Kwa sababu hiyo, kila mtu anayeyasikia maneno yangu na kuyazingatia, anafanana na mtu mwenye busara, aliyejenga nyumba yake juu ya mwamba.'),
(2014050,69,40,7,25,'Mvua ikanyesha, mito ikafurika, pepo kali zikavuma na kuipiga nyumba hiyo. Lakini haikuanguka kwa sababu ilikuwa imejengwa juu ya mwamba.'),
(2014051,69,40,7,26,'"Lakini yeyote anayesikia maneno yangu haya bila kuyazingatia, anafanana na mtu mpumbavu aliyejenga nyumba yake juu ya mchanga.'),
(2014052,69,40,7,27,'Mvua ikanyesha, mito ikafurika, pepo kali zikavuma na kuipiga nyumba hiyo, nayo ikaanguka; tena kwa kishindo kikubwa."'),
(2014053,69,40,7,28,'Yesu alipomaliza kusema maneno hayo, umati wa watu ukashangazwa na mafundisho yake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014054,69,40,7,29,'Hakuwa kama walimu wao wa Sheria, bali alifundisha kwa mamlaka.'),
(2014055,69,40,8,1,'Yesu aliposhuka kutoka mlimani, makundi mengi ya watu yalimfuata.'),
(2014056,69,40,8,2,'Basi, akaja mtu mmoja mwenye ukoma, akamsujudia akisema, "Bwana, ukitaka, waweza kunitakasa!"'),
(2014057,69,40,8,3,'Yesu akanyosha mkono wake, akamgusa na kusema, "Nataka! Takasika." Mara huyo mtu akapona ukoma wake.'),
(2014058,69,40,8,4,'Kisha Yesu akamwambia, "Sikiliza, usimwambie mtu yeyote, ila nenda ukajionyeshe kwa kuhani, na ukatoe sadaka iliyoamriwa na Mose kuwathibitishia kwamba umepona."'),
(2014059,69,40,8,5,'Yesu alipokuwa anaingia mjini Kafarnaumu, ofisa mmoja Mroma alimwendea, akamsihi'),
(2014060,69,40,8,6,'akisema, "Mheshimiwa, mtumishi wangu amelala nyumbani, mgonjwa wa kupooza na anaumwa sana."'),
(2014061,69,40,8,7,'Yesu akamwambia, "Nitakuja kumponya."'),
(2014062,69,40,8,8,'Huyo ofisa akamwambia, "Mheshimiwa, sistahili uingie nyumbani mwangu. Lakini sema tu neno, na mtumishi wangu atapona.'),
(2014063,69,40,8,9,'Maana, hata mimi niliye mtu chini ya mamlaka ya wengine, ninao askari chini yangu. Namwambia mmoja, `Nenda!` naye huenda; na mwingine, `Njoo!` naye huja; na mtumishi wangu, `Fanya kitu hiki!` naye hufanya."'),
(2014064,69,40,8,10,'Yesu aliposikia hayo, alistaajabu, akawaambia watu waliokuwa wanamfuata, "Kweli nawaambieni, sijapata kumwona mtu yeyote katika Israeli aliye na imani kama hii.'),
(2014065,69,40,8,11,'Basi, nawaambieni kwamba watu wengi watakuja kutoka mashariki na magharibi, nao wataketi karamuni pamoja na Abrahamu, Isaka na Yakobo katika Ufalme wa mbinguni.'),
(2014066,69,40,8,12,'Lakini wale ambao wangalipaswa kuwa katika Ufalme huo watatupwa nje, gizani, ambako watalia na kusaga meno."'),
(2014067,69,40,8,13,'Kisha Yesu akamwambia huyo ofisa Mroma, "Nenda nyumbani; na iwe kama ulivyoamini." Na mtumishi wake akapona saa ileile.'),
(2014068,69,40,8,14,'Yesu alifika nyumbani kwa Petro, akamkuta mama mkwe wa Petro amelala kitandani, ana homa kali.'),
(2014069,69,40,8,15,'Basi, Yesu akamgusa huyo mama mkono, na homa ikamwacha; akasimama, akamtumikia.'),
(2014070,69,40,8,16,'Ilipokuwa jioni, walimletea watu wengi waliokuwa wamepagawa na pepo; naye, kwa kusema neno tu, akawafukuza hao pepo. Aliwaponya pia watu wote waliokuwa wagonjwa.'),
(2014071,69,40,8,17,'Alifanya hivyo ili yale aliyosema nabii Isaya yatimie: "Yeye mwenyewe ameondoa udhaifu wetu, ameyachukua magonjwa yetu."'),
(2014072,69,40,8,18,'Yesu alipoona kundi la watu limemzunguka, aliwaamuru wanafunzi wake waende ng`ambo ya ziwa.'),
(2014073,69,40,8,19,'Mwalimu mmoja wa Sheria akamwendea, akamwambia, "Mwalimu, mimi nitakufuata kokote uendako."'),
(2014074,69,40,8,20,'Yesu akamjibu, "Mbweha wana mapango, na ndege wana viota; lakini Mwana wa Mtu hana mahali pa kupumzikia."'),
(2014075,69,40,8,21,'Kisha mtu mwingine miongoni mwa wanafunzi wake akamwambia, "Bwana, niruhusu kwanza niende nikamzike baba yangu."'),
(2014076,69,40,8,22,'Lakini Yesu akamwambia, "Nifuate! Waache wafu wazike wafu wao."'),
(2014077,69,40,8,23,'Yesu alipanda mashua, na wanafunzi wake wakaenda pamoja naye.'),
(2014078,69,40,8,24,'Ghafla, dhoruba kali ikatokea ziwani, hata mawimbi yakaanza kuifunika mashua. Yesu alikuwa amelala usingizi.'),
(2014079,69,40,8,25,'Wanafunzi wakamwendea, wakamwamsha wakisema, "Bwana, tuokoe, tunaangamia!"'),
(2014080,69,40,8,26,'Yesu akawaambia, "Enyi watu wenye imani haba; mbona mnaogopa?" Basi, akainuka, akazikemea pepo na mawimbi; kukawa shwari kabisa.'),
(2014081,69,40,8,27,'Watu wakashangaa, wakasema, "Ni mtu wa namna gani huyu? Hata pepo na mawimbi vinamtii!"'),
(2014082,69,40,8,28,'Yesu alifika katika nchi ya Wagerasi,*fb* ng`ambo ya ziwa, na huko watu wawili waliopagawa na pepo wakakutana naye wakitokea makaburini. Watu hawa walikuwa wenye kutisha mno, hata hakuna mtu aliyethubutu kupita katika njia hiyo.'),
(2014083,69,40,8,29,'Nao wakaanza kupiga kelele, "Una shauri gani nasi, wewe Mwana wa Mungu? Je, umekuja kututesa kabla ya wakati wake?"'),
(2014084,69,40,8,30,'Karibu na mahali hapo kulikuwa na nguruwe wengi wakichungwa.'),
(2014085,69,40,8,31,'Basi, hao pepo wakamsihi, "Ikiwa utatutoa, basi uturuhusu tuwaingie nguruwe wale."'),
(2014086,69,40,8,32,'Yesu akawaambia, "Haya, nendeni." Hapo wakawatoka watu hao, wakawaingia nguruwe. Kundi lote la nguruwe likaporomoka kwenye ule mteremko mkali, likatumbukia ziwani; nguruwe wote wakafa maji.'),
(2014087,69,40,8,33,'Wachungaji wa hao nguruwe walikimbia, wakaenda mjini. Huko walitoa habari zote na mambo yaliyowapata wale watu waliokuwa wamepagawa.'),
(2014088,69,40,8,34,'Basi, watu wote katika mji ule walitoka, wakamwendea Yesu; na walipomwona, wakamsihi aondoke katika nchi yao.'),
(2014089,69,40,9,1,'Yesu alipanda mashua, akavuka ziwa na kufika katika mji wake.'),
(2014090,69,40,9,2,'Hapo watu walimletea mtu mmoja aliyepooza mwili, amelazwa juu ya kitanda. Yesu alipoona imani yao, akamwambia huyo mtu aliyepooza, "Jipe moyo mwanangu! Umesamehewa dhambi zako."'),
(2014091,69,40,9,3,'Baadhi ya walimu wa Sheria wakaanza kufikiri, "Mtu huyu anamkufuru Mungu!"'),
(2014092,69,40,9,4,'Yesu aliyajua mawazo yao, akasema, "Kwa nini mnawaza mabaya mioyoni mwenu?'),
(2014093,69,40,9,5,'Ni lipi lililo rahisi zaidi: kusema, `Umesamehewa dhambi zako`, au kusema, `Simama, utembee`?'),
(2014094,69,40,9,6,'Basi, nataka mjue kwamba Mwana wa Mtu anao uwezo wa kuwasamehe watu dhambi duniani." Hapo akamwambia huyo mtu aliyepooza, "Inuka, chukua kitanda chako, uende nyumbani kwako."'),
(2014095,69,40,9,7,'Huyo mtu aliyekuwa amepooza akainuka, akaenda nyumbani kwake.'),
(2014096,69,40,9,8,'Watu wote katika ule umati walipoona hayo, walishangaa na kuogopa; wakamtukuza Mungu aliyewapa binadamu uwezo wa namna hiyo.'),
(2014097,69,40,9,9,'Yesu aliondoka hapo, na alipokuwa anakwenda zake, alimwona mtu mmoja aitwaye Mathayo, ameketi katika ofisi ya ushuru. Basi, Yesu akamwambia, "Nifuate." Naye Mathayo akainuka, akamfuata.'),
(2014098,69,40,9,10,'Yesu alipokuwa nyumbani*fc* ameketi kula chakula, watoza ushuru wengi na wahalifu walikuja wakaketi pamoja naye na wanafunzi wake.'),
(2014099,69,40,9,11,'Mafarisayo walipoona hayo, wakawaambia wanafunzi wake, "Mbona mwalimu wenu anakula pamoja na watoza ushuru na wenye dhambi?"'),
(2014100,69,40,9,12,'Yesu aliwasikia, akasema, "Watu wenye afya hawahitaji daktari; wanaomhitaji ni wale walio wagonjwa. Sikuja kuwaita watu wema, ila wenye dhambi.'),
(2014101,69,40,9,13,'Basi, kajifunzeni maana ya maneno haya: `Nataka huruma, wala si dhabihu.` Sikuja kuwaita watu wema, bali wenye dhambi."'),
(2014102,69,40,9,14,'Kisha wanafunzi wa Yohane mbatizaji walimwendea Yesu, wakamwuliza, "Sisi na Mafarisayo hufunga mara nyingi; mbona wanafunzi wako hawafungi?"'),
(2014103,69,40,9,15,'Yesu akawajibu, "Je, walioalikwa arusini wanaweza kuomboleza wakati bwana arusi yupo pamoja nao? La hasha! Lakini wakati utafika ambapo bwana arusi ataondolewa kati yao; wakati huo ndipo watakapofunga.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014104,69,40,9,16,'"Hakuna mtu atiaye kiraka cha nguo mpya katika vazi kuukuu. Maana kiraka hicho kitararua hilo vazi kuukuu, na pale palipokuwa pameraruka pataongezeka.'),
(2014105,69,40,9,17,'Wala hakuna mtu awekaye divai mpya katika viriba vikuukuu. Akifanya hivyo, viriba hupasuka na divai ikamwagika, navyo viriba vikaharibika. Ila divai mpya hutiwa katika viriba vipya, na vyote viwili, viriba na divai, vikahifadhiwa salama."'),
(2014106,69,40,9,18,'Yesu alipokuwa akisema hayo, ofisa mmoja Myahudi alifika, akamwinamia na kusema, "Binti yangu amekufa sasa hivi. Lakini, tafadhali njoo umwekee mkono wako naye ataishi."'),
(2014107,69,40,9,19,'Yesu akaondoka pamoja na wanafunzi wake, akamfuata.'),
(2014108,69,40,9,20,'Mama mmoja, mgonjwa wa kutokwa damu kwa muda wa miaka kumi na miwili, alimfuata Yesu nyuma, akagusa pindo la vazi lake.'),
(2014109,69,40,9,21,'Alifanya hivyo kwani alifikiri moyoni: "Nikigusa tu vazi lake, nitapona."'),
(2014110,69,40,9,22,'Basi, Yesu akageuka akamwona, akamwambia, "Binti, jipe moyo! Imani yako imekuponya." Mama huyo akapona saa ileile.'),
(2014111,69,40,9,23,'Kisha Yesu akaingia nyumbani kwa yule ofisa. Na alipowaona wapiga filimbi na umati wa watu wanaofanya matanga,'),
(2014112,69,40,9,24,'akasema, "Ondokeni hapa! Msichana huyu hakufa, amelala tu." Nao wakamcheka.'),
(2014113,69,40,9,25,'Basi, umati wa watu ulipoondolewa, Yesu aliingia ndani, akamshika huyo msichana mkono, naye akasimama.'),
(2014114,69,40,9,26,'Habari hiyo ikavuma sana katika nchi ile yote.'),
(2014115,69,40,9,27,'Yesu aliondoka hapo, na alipokuwa anakwenda, vipofu wawili walimfuata wakipiga kelele, "Mwana wa Daudi, utuhurumie!"'),
(2014116,69,40,9,28,'Yesu alipoingia nyumbani, vipofu hao wawili wakamwendea, naye akawauliza, "Je, mnaamini kwamba naweza kuwafanyia jambo hilo?" Nao wakamjibu, "Naam, Mheshimiwa."'),
(2014117,69,40,9,29,'Hapo Yesu akayagusa macho yao, akasema, "Na iwe kwenu kama mnavyoamini."'),
(2014118,69,40,9,30,'Macho yao yakafunguliwa. Naye Yesu akawaonya kwa ukali: "Msimwambie mtu yeyote jambo hili."'),
(2014119,69,40,9,31,'Lakini wao wakaondoka, wakaeneza habari za Yesu katika nchi ile yote.'),
(2014120,69,40,9,32,'Watu walipokuwa wanakwenda zao, wengine walimletea Yesu mtu mmoja aliyekuwa bubu kwa sababu alikuwa amepagawa na pepo.'),
(2014121,69,40,9,33,'Mara tu huyo pepo alipotolewa, mtu huyo aliyekuwa bubu akaanza kuongea tena. Watu wakashangaa na kusema, "Jambo kama hili halijapata kuonekana katika Israeli!"'),
(2014122,69,40,9,34,'Lakini Mafarisayo wakawa wanasema, "Anawatoa pepo kwa nguvu ya mkuu wa pepo wabaya."'),
(2014123,69,40,9,35,'Yesu alitembelea miji yote na vijiji, akafundisha katika masunagogi yao akihubiri Habari Njema ya Ufalme wa Mungu, na kuponya magonjwa yote na udhaifu wa kila namna.'),
(2014124,69,40,9,36,'Basi, alipowaona watu, makundi kwa makundi, aliwaonea huruma kwa sababu walikuwa hoi na wenye wasiwasi kama kondoo wasio na mchungaji.'),
(2014125,69,40,9,37,'Hapo akawaambia wanafunzi wake, "Mavuno ni mengi, lakini wavunaji ni wachache.'),
(2014126,69,40,9,38,'Kwa hivyo mwombeni mwenye shamba atume wavunaji shambani mwake."'),
(2014127,69,40,10,1,'Yesu aliwaita wanafunzi wake kumi na wawili, akawapa uwezo wa kutoa pepo wachafu na kuponya magonjwa na maradhi yote.'),
(2014128,69,40,10,2,'Majina ya hao mitume kumi na wawili ni haya: wa kwanza ni Simoni aitwae Petro, na Andrea ndugu yake; Yakobo mwana wa Zebedayo, na Yohane ndugu yake;'),
(2014129,69,40,10,3,'Filipo na Bartholomayo, Thoma na Mathayo aliyekuwa mtoza ushuru; Yakobo mwana wa Alfayo, na Thadayo;'),
(2014130,69,40,10,4,'Simoni Mkanaani, na Yuda Iskarioti ambaye alimsaliti Yesu.'),
(2014131,69,40,10,5,'Yesu aliwatuma hao kumi na wawili na kuwapa maagizo haya: "Msiende kwa watu wa mataifa mengine, wala msiingie katika mji wa Wasamaria.'),
(2014132,69,40,10,6,'Ila nendeni kwa watu wa Israeli waliopotea kama kondoo.'),
(2014133,69,40,10,7,'Mnapokwenda hubirini hivi: `Ufalme wa mbinguni umekaribia.`'),
(2014134,69,40,10,8,'Ponyeni wagonjwa, fufueni wafu, takaseni wenye ukoma, toeni pepo. Mmepewa bure, toeni bure.'),
(2014135,69,40,10,9,'Msichukue mifukoni mwenu dhahabu, wala fedha, wala sarafu za shaba.'),
(2014136,69,40,10,10,'Msichukue mkoba wa kuombea njiani, wala koti la ziada, wala viatu, wala fimbo. Maana mfanyakazi anastahili riziki yake.'),
(2014137,69,40,10,11,'"Mkiingia katika mji wowote au kijiji, tafuteni humo mtu yeyote aliye tayari kuwakaribisheni, na kaeni naye mpaka mtakapoondoka mahali hapo.'),
(2014138,69,40,10,12,'Mnapoingia nyumbani wasalimuni wenyeji wake.'),
(2014139,69,40,10,13,'Kama wenyeji wa nyumba hiyo wakiipokea salamu hiyo, basi, amani yenu itakaa pamoja nao. Lakini ikiwa hawaipokei, basi amani yenu itawarudia ninyi.'),
(2014140,69,40,10,14,'Kama mtu yeyote atakataa kuwakaribisheni au kuwasikilizeni, basi mtokapo katika nyumba hiyo au mji huo, yakung`uteni mavumbi miguuni mwenu kama onyo kwao.'),
(2014141,69,40,10,15,'Kweli nawaambieni, Siku ya hukumu mji huo utapata adhabu kubwa kuliko ile iliyoipata miji ya Sodoma na Gomora.'),
(2014142,69,40,10,16,'"Sasa, mimi nawatuma ninyi kama kondoo kati ya mbwa mwitu. Muwe na busara kama nyoka, na wapole kama njiwa.'),
(2014143,69,40,10,17,'Jihadharini na watu, maana watawapeleka ninyi mahakamani na kuwapiga viboko katika masunagogi yao.'),
(2014144,69,40,10,18,'Mtapelekwa mbele ya watawala na wafalme kwa sababu yangu, mpate kutangaza Habari Njema kwao na kwa mataifa.'),
(2014145,69,40,10,19,'Basi, watakapowapeleka ninyi mahakamani, msiwe na wasiwasi mtasema nini au namna gani; wakati utakapofika, mtapewa la kusema.'),
(2014146,69,40,10,20,'Maana si ninyi mtakaosema, bali ni Roho wa Baba yenu asemaye ndani yenu.'),
(2014147,69,40,10,21,'"Ndugu atamsaliti ndugu yake auawe, na baba atamsaliti mwanawe, nao watoto watawashambulia wazazi wao na kuwaua.'),
(2014148,69,40,10,22,'Watu wote watawachukieni kwa sababu ya jina langu. Lakini atakayevumilia mpaka mwisho, ataokolewa.'),
(2014149,69,40,10,23,'"Watu wakiwadhulumu katika mji mmoja, kimbilieni mji mwingine. Kweli nawaambieni, hamtamaliza ziara yenu katika miji yote ya Israeli kabla Mwana wa Mtu hajafika.'),
(2014150,69,40,10,24,'"Mwanafunzi si mkuu kuliko mwalimu wake, wala mtumishi si mkuu kuliko bwana wake.'),
(2014151,69,40,10,25,'Yatosha mwanafunzi kuwa kama mwalimu wake, na mtumishi kuwa kama bwana wake. Ikiwa wamemwita mkubwa wa jamaa Beelzebuli, je hawatawaita watu wengine wa jamaa hiyo majina mabaya zaidi?'),
(2014152,69,40,10,26,'"Basi, msiwaogope watu hao. Kila kilichofunikwa kitafunuliwa, na kila kilichofichwa kitafichuliwa.'),
(2014153,69,40,10,27,'Ninalowaambieni ninyi katika giza, lisemeni katika mwanga; na jambo mlilosikia likinong`onezwa, litangazeni hadharani.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014154,69,40,10,28,'Msiwaogope wale wauao mwili, lakini hawawezi kuiua roho. Afadhali zaidi kumwogopa yule awezaye kuuangamiza mwili pamoja na roho katika moto wa Jehanamu.'),
(2014155,69,40,10,29,'Shomoro wawili huuzwa kwa senti tano. Lakini hata mmoja wao haanguki chini bila kibali cha Baba yenu.'),
(2014156,69,40,10,30,'Lakini kwa upande wenu, hata nywele za vichwa vyenu zimehesabiwa zote.'),
(2014157,69,40,10,31,'Kwa hiyo msiogope; ninyi mu wa thamani kuliko shomoro wengi. ic'),
(2014158,69,40,10,32,'"Kila mtu anayekiri hadharani kwamba yeye ni wangu, mimi pia nitamkiri mbele ya Baba yangu aliye mbinguni.'),
(2014159,69,40,10,33,'Lakini yeyote atakayenikana hadharani, nami nitamkana mbele ya Baba yangu aliye mbinguni.'),
(2014160,69,40,10,34,'"Msidhani kwamba nimekuja kuleta amani duniani. Sikuja kuleta amani bali upanga.'),
(2014161,69,40,10,35,'Maana nimekuja kuleta mafarakano kati ya mtu na baba yake, kati ya binti na mama yake, kati ya mkwe na mkwe wake.'),
(2014162,69,40,10,36,'Na maadui wa mtu ni watu wa nyumbani mwake.'),
(2014163,69,40,10,37,'"Ampendaye baba au mama yake kuliko anipendavyo mimi, hanistahili. Ampendaye mwana au binti kuliko mimi, hanistahili.'),
(2014164,69,40,10,38,'Mtu asiyechukua msalaba wake na kunifuata, hanistahili.'),
(2014165,69,40,10,39,'Anayeyashikilia maisha yake, atayapoteza; lakini anayeyapoteza maisha yake kwa ajili yangu, atayapata.'),
(2014166,69,40,10,40,'"Anayewakaribisha ninyi, ananikaribisha mimi; na anayenikaribisha mimi, anamkaribisha yule aliyenituma.'),
(2014167,69,40,10,41,'Anayemkaribisha nabii kwa sababu ni nabii, atapokea tuzo la nabii. Anayemkaribisha mtu mwema kwa sababu ni mtu mwema, atapokea tuzo la mtu mwema.'),
(2014168,69,40,10,42,'Kweli nawaambieni, yeyote atakayempa mmojawapo wa wadogo hawa kikombe cha maji baridi kwa sababu ni mfuasi wangu, hatakosa kamwe kupata tuzo lake."'),
(2014169,69,40,11,1,'Yesu alipomaliza kuwapa wanafunzi kumi na wawili maagizo, alitoka hapo, akaenda kufundisha na kuhubiri katika miji yao.'),
(2014170,69,40,11,2,'Yohane mbatizaji akiwa gerezani alipata habari juu ya matendo ya Kristo. Basi, Yohane akawatuma wanafunzi wake,'),
(2014171,69,40,11,3,'wamwulize: "Je, wewe ni yule anayekuja, au tumngoje mwingine?"'),
(2014172,69,40,11,4,'Yesu akawajibu, "Nendeni mkamwambie Yohane mambo mnayoyasikia na kuyaona:'),
(2014173,69,40,11,5,'vipofu wanaona, viwete wanatembea, wenye ukoma wanatakaswa na viziwi wanasikia, wafu wanafufuliwa na maskini wanahubiriwa Habari Njema.'),
(2014174,69,40,11,6,'Heri mtu yule asiyekuwa na mashaka nami."'),
(2014175,69,40,11,7,'Basi, hao wajumbe wa Yohane walipokuwa wanakwenda zao, Yesu alianza kuyaambia makundi ya watu habari za Yohane: "Mlikwenda kutazama nini kule jangwani? Je, mlitaka kuona mwanzi unaotikiswa na upepo?'),
(2014176,69,40,11,8,'Lakini mlikwenda kuona nini? Mlikwenda kumtazama mtu aliyevaa mavazi maridadi? Watu wanaovaa mavazi maridadi hukaa katika nyumba za wafalme.'),
(2014177,69,40,11,9,'Basi, mlikwenda kuona nini? Nabii? Naam, hakika ni zaidi ya nabii.'),
(2014178,69,40,11,10,'"Huyu ndiye anayesemwa katika Maandiko Matakatifu: `Tazama, hapa namtuma mjumbe wangu, asema Bwana, akutangulie na kukutayarishia njia yako.`'),
(2014179,69,40,11,11,'Kweli nawaambieni, miongoni mwa watoto wote wa watu, hajatokea aliye mkuu kuliko Yohane mbatizaji. Hata hivyo, yule aliye mdogo kabisa katika Ufalme wa mbinguni, ni mkubwa kuliko yeye.'),
(2014180,69,40,11,12,'Tangu wakati wa Yohane mbatizaji mpaka leo hii, Ufalme wa mbinguni unashambuliwa vikali, na watu wakali wanajaribu kuunyakua kwa nguvu.'),
(2014181,69,40,11,13,'Mafundisho yote ya manabii na sheria yalibashiri juu ya nyakati hizi.'),
(2014182,69,40,11,14,'Kama mwaweza kukubali basi, Yohane ndiye Eliya ambaye angekuja.'),
(2014183,69,40,11,15,'Mwenye masikio na asikie!'),
(2014184,69,40,11,16,'"Basi, nitakifananisha kizazi hiki na kitu gani? Ni kama vijana waliokuwa wamekaa uwanjani, wakawa wakiambiana kikundi kimoja kwa kingine:'),
(2014185,69,40,11,17,'`Tumewapigieni ngoma lakini hamkucheza; tumeimba nyimbo za huzuni lakini hamkulia!`'),
(2014186,69,40,11,18,'Kwa maana Yohane alikuja, akafunga na wala hakunywa divai, nao wakasema: `Amepagawa na pepo.`'),
(2014187,69,40,11,19,'Mwana wa Mtu akaja, anakula na kunywa, nao wakasema: `Mtazameni huyu, mlafi na mlevi, rafiki yao watoza ushuru na wahalifu!` Hata hivyo, hekima ya Mungu inathibitishwa kuwa njema kutokana na matendo yake."'),
(2014188,69,40,11,20,'Kisha Yesu akaanza kuilaumu miji ambayo, ingawaje alifanya miujiza mingi humo, watu wake hawakutaka kubadili nia zao mbaya:'),
(2014189,69,40,11,21,'"Ole wako Korazini! Ole wako Bethsaida! Maana, kama miujiza iliyofanyika kwako ingalifanyika kule Tiro na Sidoni, watu wake wangalikwisha vaa mavazi ya gunia na kujipaka majivu zamani, ili kuonyesha kwamba wametubu.'),
(2014190,69,40,11,22,'Hata hivyo nawaambieni, Siku ya hukumu, ninyi mtapata adhabu kubwa kuliko Tiro na Sidoni.'),
(2014191,69,40,11,23,'Na wewe Kafarnaumu, je, utajikweza mpaka mbinguni? Utaporomoshwa mpaka Kuzimu! Maana, kama miujiza iliyofanyika kwako ingalifanyika kule Sodoma, mji huo ungalikuwako mpaka hivi leo.'),
(2014192,69,40,11,24,'Lakini nawaambieni, Siku ya hukumu itakuwa nafuu zaidi kwa watu wa Sodoma, kuliko kwako wewe."'),
(2014193,69,40,11,25,'Wakati huo Yesu alisema, "Nakushukuru ee Baba, Bwana wa mbingu na dunia, maana umewaficha wenye hekima mambo haya, ukawafumbulia watoto wadogo.'),
(2014194,69,40,11,26,'Naam Baba, ndivyo ilivyokupendeza.'),
(2014195,69,40,11,27,'"Baba yangu amenikabidhi vitu vyote. Hakuna amjuaye Mwana ila Baba, wala amjuaye Baba ila Mwana, na yeyote yule ambaye Mwana atapenda kumjulisha.'),
(2014196,69,40,11,28,'Njoni kwangu ninyi nyote msumbukao na kulemewa na mizigo, nami nitawapumzisha.'),
(2014197,69,40,11,29,'Jifungeni nira yangu, mkajifunze kwangu, maana mimi ni mpole na mnyenyekevu wa moyo, nanyi mtatulizwa rohoni mwenu.'),
(2014198,69,40,11,30,'Maana, nira niwapayo mimi ni laini, na mzigo wangu ni mwepesi."'),
(2014199,69,40,12,1,'Wakati huo, Yesu alikuwa anapita katika mashamba ya ngano siku ya Sabato. Basi, wanafunzi wake wakaona njaa, wakaanza kukwanyua masuke ya ngano, wakala punje zake.'),
(2014200,69,40,12,2,'Mafarisayo walipoona hayo, wakamwambia Yesu, "Tazama, wanafunzi wako wanafanya jambo ambalo si halali siku ya Sabato."'),
(2014201,69,40,12,3,'Yesu akawajibu, "Je, hamjasoma alivyofanya Daudi pamoja na wenzake wakati walipokuwa na njaa?'),
(2014202,69,40,12,4,'Yeye aliingia katika Nyumba ya Mungu pamoja na wenzake, wakala ile mikate iliyowekwa mbele ya Mungu. Yeye wala hao wenzake hawakuruhusiwa kula mikate hiyo isipokuwa tu makuhani peke yao.'),
(2014203,69,40,12,5,'Au je, hamjasoma katika Sheria kwamba kila siku ya Sabato makuhani huivunja Sheria Hekaluni, lakini hawafikiriwi kuwa na hatia?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014204,69,40,12,6,'Basi, nawaambieni kwamba hapa pana kikuu*fd* kuliko Hekalu.'),
(2014205,69,40,12,7,'Kama tu mngejua maana ya maneno haya: `Nataka huruma wala si dhabihu`, hamngewahukumu watu wasio na hatia.'),
(2014206,69,40,12,8,'Maana Mwana wa Mtu ni Bwana wa Sabato."'),
(2014207,69,40,12,9,'Yesu alitoka hapo, akaenda katika sunagogi lao.'),
(2014208,69,40,12,10,'Kulikuwa na mtu mmoja mwenye mkono uliopooza. Basi, watu wakamwuliza Yesu, "Je, ni halali kumponya mtu siku ya Sabato?" Walimwuliza hivyo wapate kisa cha kumshtaki.'),
(2014209,69,40,12,11,'Lakini Yesu akawaambia, "Tuseme mmoja wenu ana kondoo wake ambaye ametumbukia shimoni; je, hatamshika na kumtoa humo siku ya Sabato?'),
(2014210,69,40,12,12,'Mtu ana thamani kuliko kondoo! Basi, ni halali kutenda mema siku ya Sabato."'),
(2014211,69,40,12,13,'Kisha akamwambia yule mtu, "Nyosha mkono wako." Akaunyosha, nao ukawa mzima kabisa kama ule mwingine.'),
(2014212,69,40,12,14,'Basi, Mafarisayo wakatoka nje, wakashauriana jinsi watakavyomwangamiza Yesu.'),
(2014213,69,40,12,15,'Lakini Yesu alipojua jambo hilo, akatoka mahali pale. Watu wengi walimfuata, akawaponya wagonjwa wote,'),
(2014214,69,40,12,16,'akawaamuru wasiwaambie watu habari zake,'),
(2014215,69,40,12,17,'ili yale aliyosema nabii Isaya yatimie:'),
(2014216,69,40,12,18,'"Hapa ni mtumishi wangu niliyemteua, mpendwa wangu anipendezaye moyoni. Nitaiweka Roho yangu juu yake, naye atatangaza hukumu yangu kwa mataifa yote.'),
(2014217,69,40,12,19,'Hatakuwa na ubishi wala kupiga kelele, wala sauti yake haitasikika barabarani.'),
(2014218,69,40,12,20,'Mwanzi uliopondeka hatauvunja, wala utambi ufukao moshi hatauzima, mpaka atakapoifanya hukumu ya haki itawale.'),
(2014219,69,40,12,21,'Katika jina lake mataifa yatakuwa na tumaini."'),
(2014220,69,40,12,22,'Hapo watu wakamletea Yesu kipofu mmoja ambaye alikuwa bubu kwa sababu alikuwa amepagawa na pepo. Yesu akamponya hata, akaweza kusema na kuona.'),
(2014221,69,40,12,23,'Umati wote wa watu ulishangaa ukasema, "Je, huenda ikawa huyu ndiye Mwana wa Daudi?"'),
(2014222,69,40,12,24,'Lakini Mafarisayo waliposikia hayo, wakasema, "Mtu huyu anawafukuza pepo kwa uwezo wa Beelzebuli, mkuu wa pepo."'),
(2014223,69,40,12,25,'Yesu, akiwa anayajua mawazo yao, akawaambia, "Ufalme wowote uliogawanyika makundimakundi yanayopingana, hauwezi kudumu, na mji wowote au jamaa yoyote iliyogawanyika makundimakundi yanayopingana, itaanguka.'),
(2014224,69,40,12,26,'Ikiwa Shetani anamfukuza Shetani, anajipinga mwenyewe. Basi, ufalme wake utasimamaje?'),
(2014225,69,40,12,27,'Ninyi mnasema ati nawafukuza pepo kwa uwezo wa Beelzebuli; je, watoto wenu huwafukuza kwa uwezo wa nani? Kwa sababu hiyo wao ndio watakaowahukumu ninyi.'),
(2014226,69,40,12,28,'Lakini ikiwa ninawafukuza pepo kwa nguvu ya Roho wa Mungu, basi jueni kwamba Ufalme wa Mungu umekwisha fika kwenu.'),
(2014227,69,40,12,29,'"Au, anawezaje mtu kuivamia nyumba ya mtu mwenye nguvu na kumnyang`anya mali yake, bila kwanza kumfunga huyo mtu mwenye nguvu? Hapo ndipo atakapoweza kumnyang`anya mali yake.'),
(2014228,69,40,12,30,'"Yeyote asiyejiunga nami, anapingana nami; na yeyote asiyekusanya pamoja nami, hutawanya.'),
(2014229,69,40,12,31,'Kwa sababu hiyo, nawaambieni, watu watasamehewa dhambi na kufuru zao zote, lakini hawatasamehewa dhambi ya kumkufuru Roho Mtakatifu.'),
(2014230,69,40,12,32,'Tena, asemaye neno la kumpinga Mwana wa Mtu atasamehewa, lakini yule asemaye neno la kumpinga Roho Mtakatifu, hatasamehewa, wala katika ulimwengu huu, wala katika ulimwengu ujao.'),
(2014231,69,40,12,33,'"Ufanyeni mti kuwa mzuri na matunda yake yatakuwa mema; ufanyeni kuwa mbaya na matunda yake yatakuwa mabaya. Mti hujulikana kwa matunda yake.'),
(2014232,69,40,12,34,'Enyi kizazi cha nyoka! Mnawezaje kusema mambo mema hali ninyi ni waovu? Maana mtu husema kutokana na yale yaliyojaa moyoni.'),
(2014233,69,40,12,35,'Mtu mwema hutoa mambo mema katika hazina yake njema; na mtu mbaya hutoa mambo mabaya katika hazina yake mbaya.'),
(2014234,69,40,12,36,'"Basi, nawaambieni, Siku ya hukumu watu watapaswa kujibu juu ya kila neno lisilofaa wanalosema.'),
(2014235,69,40,12,37,'Maana kwa maneno yako, utakubaliwa kuwa mwadilifu, na kwa maneno yako, utahukumiwa kuwa na hatia."'),
(2014236,69,40,12,38,'Kisha baadhi ya walimu wa Sheria na Mafarisayo wakamwambia Yesu, "Mwalimu, tunataka kuona ishara kutoka kwako."'),
(2014237,69,40,12,39,'Naye akawajibu, "Kizazi kiovu kisicho na uaminifu! Mnataka ishara; hamtapewa ishara nyingine, ila tu ile ishara ya nabii Yona.'),
(2014238,69,40,12,40,'Jinsi Yona alivyokaa siku tatu kutwa kucha tumboni mwa nyangumi, ndivyo naye Mwana wa Mtu atakavyokaa ndani ya ardhi siku tatu kutwa kucha.'),
(2014239,69,40,12,41,'Watu wa Ninewi watatokea siku ya hukumu, nao watakihukumu kizazi hiki kwamba kina hatia. Maana Waninewi walitubu kwa sababu ya mahubiri ya Yona, na kumbe hapa kuna kikuu kuliko Yona!'),
(2014240,69,40,12,42,'Malkia wa kusini atatokea wakati kizazi hiki kitakapohukumiwa, naye atakihukumu kwamba kina hatia. Maana yeye alisafiri kutoka mbali akaja kusikiliza maneno ya hekima ya Solomoni, na kumbe hapa kuna kikuu*fe* kuliko Solomoni.'),
(2014241,69,40,12,43,'"Pepo mchafu akifukuzwa kwa mtu, huzururazurura jangwani akitafuta mahali pa kupumzika asipate.'),
(2014242,69,40,12,44,'Hapo hujisemea: `Nitarudi nyumbani kwangu nilikotoka.` Lakini anaporudi na kuikuta tupu, imefagiwa na kupambwa,'),
(2014243,69,40,12,45,'huenda kuwachukua pepo wengine saba, wabaya kuliko yeye; na wote huja wakamwingia huyo mtu. Na hali ya mtu huyo sasa huwa mbaya kuliko hapo mwanzo. Ndivyo itakavyokuwa kwa watu hawa waovu."'),
(2014244,69,40,12,46,'Yesu alikuwa bado anasema na umati wa watu wakati mama yake na ndugu zake walipofika na kusimama nje, wakitaka kusema naye.'),
(2014245,69,40,12,47,'Basi, mtu mmoja akamwambia, "Mama yako na ndugu zako wako nje, wanataka kusema nawe."'),
(2014246,69,40,12,48,'Lakini Yesu akamjibu mtu huyo, "Mama yangu ni nani? Na ndugu zangu ni kina nani?"'),
(2014247,69,40,12,49,'Kisha akaunyosha mkono wake kuelekea wanafunzi wake, akasema, "Hawa ndio mama yangu na ndugu zangu!'),
(2014248,69,40,12,50,'Maana yeyote anayefanya anavyotaka Baba yangu aliye mbinguni, huyo ndiye ndugu yangu, dada yangu na mama yangu."'),
(2014249,69,40,13,1,'Siku hiyohiyo, Yesu alitoka katika ile nyumba, akaenda na kuketi kando ya ziwa.'),
(2014250,69,40,13,2,'Makundi makubwa ya watu yalimzunguka hata Yesu akapanda mashua, akaketi. Hao watu walisimama kwenye ukingo wa ziwa,'),
(2014251,69,40,13,3,'naye Yesu akawaambia mambo mengi kwa mifano. "Sikilizeni! Mpanzi alikwenda kupanda mbegu.'),
(2014252,69,40,13,4,'Alipokuwa akipanda, nyingine zilianguka njiani, ndege wakaja wakazila.'),
(2014253,69,40,13,5,'Nyingine zilianguka penye mawe pasipokuwa na udongo mwingi. Zikaota mara kwa kuwa udongo haukuwa na kina.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014254,69,40,13,6,'Jua lilipochomoza, zilichomeka; na kwa kuwa mizizi yake haikuwa na nguvu, zikanyauka.'),
(2014255,69,40,13,7,'Nyingine zilianguka kwenye miti ya miiba, nayo ikakua na kuzisonga.'),
(2014256,69,40,13,8,'Lakini nyingine zilianguka penye udongo mzuri, zikaota, zikazaa: nyingine punje mia moja, nyingine sitini na nyingine thelathini.'),
(2014257,69,40,13,9,'Mwenye masikio na asikie!"'),
(2014258,69,40,13,10,'Wanafunzi wake wakamwendea, wakamwuliza, "Kwa nini unasema na watu kwa mifano?"'),
(2014259,69,40,13,11,'Yesu akawajibu, "Ninyi mmejaliwa kuzijua siri za Ufalme wa mbinguni, lakini wao hawakujaliwa.'),
(2014260,69,40,13,12,'Maana, aliye na kitu atapewa na kuzidishiwa; lakini yule asiye na kitu, hata kile alicho nacho kitachukuliwa.'),
(2014261,69,40,13,13,'Ndiyo maana ninasema nao kwa mifano, kwa sababu wanatazama lakini hawaoni, wanasikiliza lakini hawasikii, wala hawaelewi.'),
(2014262,69,40,13,14,'Kwao yametimia yale aliyosema nabii Isaya: `Kusikia mtasikia, lakini hamtaelewa; Kutazama mtatazama, lakini hamtaona.'),
(2014263,69,40,13,15,'Maana akili za watu hawa zimepumbaa, wameyaziba masikio yao, wameyafumba macho yao. La sivyo, wangeona kwa macho yao. wangesikia kwa masikio yao, wangeelewa kwa akili zao, na kunigeukia, asema Bwana, nami ningewaponya.`'),
(2014264,69,40,13,16,'"Lakini heri yenu ninyi, maana macho yenu yanaona na masikio yenu yanasikia.'),
(2014265,69,40,13,17,'Kweli nawaambieni, manabii na watu wengi wema walitamani kuyaona yale mnayoyaona, wasiyaone, na kuyasikia yale mnayoyasikia, wasiyasikie.'),
(2014266,69,40,13,18,'"Basi, ninyi sikilizeni maana ya mfano huo wa mpanzi.'),
(2014267,69,40,13,19,'Yeyote asikiaye ujumbe wa ufalme bila kuuelewa, ni kama zile mbegu zilizoanguka njiani; yule Mwovu huja na kunyakua kile kilichopandwa moyoni mwake.'),
(2014268,69,40,13,20,'Ile mbegu iliyopandwa penye mawe ni mfano wa mtu asikiaye ujumbe huo na mara akaupokea kwa furaha.'),
(2014269,69,40,13,21,'Lakini haumwingii na kuwa na mizizi ndani yake; huendelea kuuzingatia ujumbe huo kwa kitambo tu, na wakati taabu au udhalimu vinapotokea kwa sababu ya ujumbe huo, anakata tamaa mara.'),
(2014270,69,40,13,22,'Ile mbegu iliyoanguka kati ya miti ya miiba, ni mfano wa mtu asikiaye huo ujumbe, lakini wasiwasi wa ulimwengu huu na anasa za mali huusonga ujumbe huo, naye hazai matunda.'),
(2014271,69,40,13,23,'Ile mbegu iliyopandwa katika udongo mzuri ni mfano wa mtu ausikiaye ujumbe huo na kuuelewa, naye huzaa matunda; mmoja mia, mwingine sitini na mwingine thelathini."'),
(2014272,69,40,13,24,'Yesu akawaambia watu mfano mwingine: "Ufalme wa mbinguni unafanana na mtu aliyepanda mbegu nzuri katika shamba lake.'),
(2014273,69,40,13,25,'Lakini watu wakiwa wamelala, adui yake akaja akapanda magugu kati ya ngano, akaenda zake.'),
(2014274,69,40,13,26,'Basi, mimea ilipoota na kuanza kuchanua, magugu pia yakaanza kuonekana.'),
(2014275,69,40,13,27,'Watumishi wa yule mwenye shamba wakamwendea, wakamwambia, `Mheshimiwa, bila shaka ulipanda mbegu nzuri katika shamba lako. Sasa magugu yametoka wapi?`'),
(2014276,69,40,13,28,'Yeye akawajibu, `Adui ndiye aliyefanya hivyo.` Basi, watumishi wake wakamwuliza, `Je, unataka twende tukayang`oe`'),
(2014277,69,40,13,29,'Naye akawajibu, `La, msije labda mnapokusanya magugu, mkang`oa na ngano pia.'),
(2014278,69,40,13,30,'Acheni vikue pamoja mpaka wakati wa mavuno. Wakati huo nitawaambia wavunaji: kusanyeni kwanza magugu mkayafunge mafungumafungu ya kuchomwa. Lakini ngano ikusanyeni mkaiweke ghalani mwangu."`'),
(2014279,69,40,13,31,'Yesu akawaambia watu mfano mwingine: "Ufalme wa mbinguni unafanana na mbegu ya haradali aliyotwaa mtu mmoja, akaipanda katika shamba lake.'),
(2014280,69,40,13,32,'Yenyewe ni ndogo kuliko mbegu zote, lakini ikishaota huwa kubwa kuliko mimea yote. Hukua ikawa mti, na ndege wa angani huja na kujenga viota katika matawi yake."'),
(2014281,69,40,13,33,'Yesu akawaambia mfano mwingine: "Ufalme wa mbinguni umefanana na chachu aliyotwaa mama mmoja, akaichanganya na unga pishi tatu, hata unga wote ukaumuka."'),
(2014282,69,40,13,34,'Yesu aliwaambia watu hayo yote kwa mifano. Hakuwaambia chochote bila kutumia mifano,'),
(2014283,69,40,13,35,'ili jambo lililonenwa na nabii litimie: "Nitasema kwa mifano; nitawaambia mambo yaliyofichika tangu kuumbwa ulimwengu."'),
(2014284,69,40,13,36,'Kisha Yesu aliwaaga wale watu, akaingia nyumbani. Wanafunzi wake wakamwendea, wakamwambia, "Tufafanulie ule mfano wa magugu shambani."'),
(2014285,69,40,13,37,'Yesu akawaambia, "Mpanzi wa zile mbegu nzuri ni Mwana wa Mtu.'),
(2014286,69,40,13,38,'Lile shamba ni ulimwengu. Zile mbegu nzuri ni watu wale ambao Ufalme ni wao. Lakini yale magugu ni wale watu wa yule Mwovu.'),
(2014287,69,40,13,39,'Adui aliyepanda yale magugu ni Ibilisi. Mavuno ni mwisho wa nyakati na wavunaji ni malaika.'),
(2014288,69,40,13,40,'Kama vile magugu yanavyokusanywa kuchomwa moto, ndivyo itakavyokuwa mwishoni mwa nyakati;'),
(2014289,69,40,13,41,'Mwana wa Mtu atawatuma malaika wake wawakusanye kutoka katika Ufalme wake wale wote wenye kusababisha dhambi, na wote wenye kutenda maovu,'),
(2014290,69,40,13,42,'na kuwatupa katika tanuru ya moto, na huko watalia na kusaga meno.'),
(2014291,69,40,13,43,'Kisha, wale wema watang`ara kama jua katika Ufalme wa Baba yao. Sikieni basi, kama mna masikio!'),
(2014292,69,40,13,44,'"Ufalme wa mbinguni umefanana na hazina iliyofichika shambani. Mtu mmoja aliigundua, akaificha tena. Alifurahi sana hata akaenda kuuza yote aliyokuwa nayo, akalinunua shamba lile.'),
(2014293,69,40,13,45,'"Tena, Ufalme wa mbinguni umefanana na mfanyabiashara mmoja mwenye kutafuta lulu nzuri.'),
(2014294,69,40,13,46,'Alipopata lulu moja ya thamani kubwa, alienda akauza yote aliyokuwa nayo, akainunua lulu ile.'),
(2014295,69,40,13,47,'"Tena, Ufalme wa mbinguni unafanana na wavu uliotupwa baharini, ukanasa samaki wa kila aina.'),
(2014296,69,40,13,48,'Ulipojaa, watu waliuvuta pwani, wakaketi, wakachagua samaki wazuri wakawaweka ndani ya vikapu vyao, na wabaya wakawatupa.'),
(2014297,69,40,13,49,'Ndivyo itakavyokuwa mwishoni mwa nyakati: malaika watatokea, watawatenganisha watu wabaya na watu wema,'),
(2014298,69,40,13,50,'na kuwatupa hao wabaya katika tanuru ya moto. Huko watalia na kusaga meno."'),
(2014299,69,40,13,51,'Yesu akawauliza, "Je, mmeelewa mambo haya yote?" Wakamjibu, "Naam."'),
(2014300,69,40,13,52,'Naye akawaambia, "Hivyo basi, kila mwalimu wa Sheria aliye mwanafunzi wa Ufalme wa mbinguni anafanana na mwenye nyumba atoaye katika hazina yake vitu vipya na vya kale."'),
(2014301,69,40,13,53,'Yesu alipomaliza kusema mifano hiyo alitoka mahali hapo,'),
(2014302,69,40,13,54,'akaenda kijijini kwake. Huko akawa anawafundisha watu katika sunagogi hata wakashangaa, wakasema, "Huyu amepata wapi hekima hii na maajabu?'),
(2014303,69,40,13,55,'Je, huyu si yule mwana wa seremala? Je, mama yake si anaitwa Maria, na ndugu zake si kina Yakobo, Yosefu, Simoni na Yuda?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014304,69,40,13,56,'Na dada zake je, si wote wako hapa pamoja nasi? Basi amepata wapi haya yote?"'),
(2014305,69,40,13,57,'Basi, wakawa na mashaka naye. Lakini Yesu akawaambia, "Nabii hakosi kuheshimiwa, isipokuwa katika nchi yake na nyumbani mwake!"'),
(2014306,69,40,13,58,'Kwa hiyo, hakutenda miujiza mingi pale kwa sababu ya kutoamini kwao.'),
(2014307,69,40,14,1,'Wakati huo, mtawala Herode alisikia sifa za Yesu.'),
(2014308,69,40,14,2,'Basi, akawaambia watumishi wake, "Mtu huyu ni Yohane mbatizaji, amefufuka kutoka wafu; ndiyo maana nguvu za miujiza zinafanya kazi ndani yake."'),
(2014309,69,40,14,3,'Herode ndiye aliyekuwa amemtia Yohane nguvuni, akamfunga minyororo na kumtia gerezani kwa sababu ya Herodia, mke wa Filipo, ndugu yake. Sababu hasa ni'),
(2014310,69,40,14,4,'kwamba alikuwa amemwambia Herode, "Si halali kwako kuishi na huyo mwanamke!"'),
(2014311,69,40,14,5,'Herode alitaka kumwua Yohane, lakini aliogopa watu kwa sababu kwao Yohane alikuwa nabii.'),
(2014312,69,40,14,6,'Katika sherehe za sikukuu ya kuzaliwa kwake Herode, binti ya Herodia alicheza mbele ya wageni. Herode alifurahiwa,'),
(2014313,69,40,14,7,'hata akaahidi kwa kiapo kumpa huyo msichana chochote atakachoomba.'),
(2014314,69,40,14,8,'Naye, huku akichochewa na mama yake, akaomba, "Nipe papahapa katika sinia kichwa cha Yohane mbatizaji."'),
(2014315,69,40,14,9,'Mfalme alihuzunika, lakini kwa sababu ya kile kiapo chake na kwa sababu ya wale wageni karamuni, akaamuru apewe.'),
(2014316,69,40,14,10,'Basi, Herode akatuma mtu gerezani amkate kichwa Yohane.'),
(2014317,69,40,14,11,'Kichwa chake kikaletwa katika sinia, wakampa yule msichana, naye akampelekea mama yake.'),
(2014318,69,40,14,12,'Wanafunzi wa Yohane wakaja, wakauchukua mwili wake, wakauzika. Kisha wakaenda kumpasha habari Yesu.'),
(2014319,69,40,14,13,'Yesu alipopata habari hiyo, aliondoka mahali pale kwa mashua, akaenda mahali pa faragha peke yake. Lakini watu walipata habari, wakamfuata kwa miguu toka mijini.'),
(2014320,69,40,14,14,'Basi, aliposhuka pwani, aliona umati mkubwa wa watu, akawaonea huruma, akawaponya wagonjwa wao.'),
(2014321,69,40,14,15,'Kulipokuwa jioni, wanafunzi wake walimwendea wakamwambia, "Mahali hapa ni nyikani, na saa zimepita. Basi, uwaage watu ili waende vijijini wakajinunulie chakula."'),
(2014322,69,40,14,16,'Yesu akawaambia, "Si lazima waende, wapeni ninyi chakula."'),
(2014323,69,40,14,17,'Lakini wao wakamwambia, "Tunayo mikate mitano tu na samaki wawili."'),
(2014324,69,40,14,18,'Yesu akawaambia, "Nileteeni hapa."'),
(2014325,69,40,14,19,'Akawaamuru watu waketi katika nyasi. Kisha akaitwaa ile mikate mitano na wale samaki wawili, akatazama juu mbinguni, akamshukuru Mungu. Halafu akaimega hiyo mikate, akawapa wanafunzi wake, nao wakawapa watu.'),
(2014326,69,40,14,20,'Watu wote wakala, wakashiba. Kisha wanafunzi wakakusanya mabaki, wakajaza vikapu kumi na viwili.'),
(2014327,69,40,14,21,'Jumla ya waliokula ilikuwa wanaume wapatao elfu tano, bila kuhesabu wanawake na watoto.'),
(2014328,69,40,14,22,'Mara, Yesu akawaamuru wanafunzi wake wapande mashua, wamtangulie ng`ambo ya ziwa wakati yeye anawaaga watu.'),
(2014329,69,40,14,23,'Baada ya kuwaaga, alipanda mlimani peke yake kusali. Ilipokuwa jioni, yeye alikuwa huko peke yake,'),
(2014330,69,40,14,24,'na wakati huo ile mashua ilikwishafika karibu katikati ya ziwa, lakini ilikuwa inakwenda mrama kwa sababu upepo ulikuwa unaipinga.'),
(2014331,69,40,14,25,'Usiku, karibu na mapambazuko, Yesu aliwaendea wanafunzi akitembea juu ya maji.'),
(2014332,69,40,14,26,'Wanafunzi wake walipomwona akitembea juu ya maji waliingiwa na hofu, wakasema, "Ni mzimu!" Wakapiga kelele kwa hofu.'),
(2014333,69,40,14,27,'Mara, Yesu akasema nao, "Tulieni, ni mimi. Msiogope!"'),
(2014334,69,40,14,28,'Petro akamwambia, "Bwana, ikiwa ni wewe kweli, amuru nitembee juu ya maji nije kwako."'),
(2014335,69,40,14,29,'Yesu akasema, "Haya, njoo." Basi, Petro akashuka kutoka ile mashua, akatembea juu ya maji, akamwendea Yesu.'),
(2014336,69,40,14,30,'Lakini alipouona ule upepo, aliogopa, akaanza kuzama; akalia kwa sauti, "Bwana, niokoe!"'),
(2014337,69,40,14,31,'Hapo, Yesu akaunyosha mkono wake, akamshika na kumwambia, "Ewe mwenye imani haba! Kwa nini uliona shaka?"'),
(2014338,69,40,14,32,'Basi, wakapanda mashuani, na upepo ukatulia.'),
(2014339,69,40,14,33,'Wote waliokuwa ndani ya mashua walimsujudia, wakasema, "Hakika wewe ni Mwana wa Mungu."'),
(2014340,69,40,14,34,'Walivuka ziwa, wakafika nchi ya Genesareti.'),
(2014341,69,40,14,35,'Watu wa huko walipomtambua, wakaeneza habari pote katika sehemu hizo. Basi, wakamletea Yesu wagonjwa wote,'),
(2014342,69,40,14,36,'wakamwomba awaruhusu waguse tu pindo la vazi lake; wote waliomgusa walipona.'),
(2014343,69,40,15,1,'Kisha Mafarisayo na walimu wa Sheria wakafika kutoka Yerusalemu, wakamwendea Yesu, wakamwuliza,'),
(2014344,69,40,15,2,'"Kwa nini wanafunzi wako hawajali mapokeo tuliyopokea kutoka kwa wazee wetu? Hawanawi mikono yao kama ipasavyo kabla ya kula!"'),
(2014345,69,40,15,3,'Yesu akawajibu, "Kwa nini nanyi mnapendelea mapokeo yenu wenyewe na hamuijali Sheria ya Mungu?'),
(2014346,69,40,15,4,'Mungu amesema: `Waheshimu baba yako na mama yako,` na `Anayemkashifu baba yake au mama yake, lazima auawe`.'),
(2014347,69,40,15,5,'Lakini ninyi mwafundisha ati mtu akiwa na kitu ambacho angeweza kuwasaidia nacho baba au mama yake, lakini akasema: `Kitu hiki nimemtolea Mungu,`'),
(2014348,69,40,15,6,'basi, hapaswi tena kumheshimu baba yake! Ndivyo mnavyodharau neno la Mungu kwa kufuata mafundisho yenu wenyewe.'),
(2014349,69,40,15,7,'Enyi wanafiki! Isaya alitabiri sawa kabisa juu yenu:'),
(2014350,69,40,15,8,'`Watu hawa, asema Mungu, huniheshimu kwa maneno tu, lakini mioyoni mwao wako mbali nami.'),
(2014351,69,40,15,9,'Kuniabudu kwao hakufai, maana mambo wanayofundisha ni maagizo ya kibinadamu tu."`'),
(2014352,69,40,15,10,'Yesu aliuita ule umati wa watu, akawaambia, "Sikilizeni na muelewe!'),
(2014353,69,40,15,11,'Kitu kinachomtia mtu najisi si kile kiingiacho kinywani, bali kile kitokacho kinywani. Hicho ndicho kimtiacho mtu najisi."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014354,69,40,15,12,'Kisha wanafunzi wakamwendea, wakamwambia, "Je, unajua kwamba Mafarisayo walichukizwa waliposikia maneno yako?"'),
(2014355,69,40,15,13,'Lakini yeye akawajibu, "Kila mmea ambao Baba yangu aliye mbinguni hakuupanda, utang`olewa.'),
(2014356,69,40,15,14,'Waacheni wenyewe! Wao ni vipofu, viongozi wa vipofu; na kipofu akimwongoza kipofu, wote wawili hutumbukia shimoni."'),
(2014357,69,40,15,15,'Petro akadakia, "Tufafanulie huo mfano."'),
(2014358,69,40,15,16,'Yesu akasema, "Hata nyinyi hamwelewi?'),
(2014359,69,40,15,17,'Je, hamwelewi kwamba kila kinachoingia kinywani huenda tumboni na baadaye hutupwa nje chooni?'),
(2014360,69,40,15,18,'Lakini yale yatokayo kinywani hutoka moyoni, na hayo ndiyo yanayomtia mtu najisi.'),
(2014361,69,40,15,19,'Maana moyoni hutoka mawazo maovu yanayosababisha uuaji, uzinzi, uasherati, wizi, ushahidi wa uongo na kashfa.'),
(2014362,69,40,15,20,'Hayo ndiyo yanayomtia mtu najisi. Lakini kula chakula bila kunawa mikono hakumtii mtu najisi."'),
(2014363,69,40,15,21,'Yesu aliondoka mahali hapo akaenda kukaa katika sehemu za Tiro na Sidoni.'),
(2014364,69,40,15,22,'Basi, mama mmoja Mkaanani wa nchi hiyo alimjia, akapaaza sauti: "Mheshimiwa, Mwana wa Daudi, nionee huruma! Binti yangu anasumbuliwa na pepo."'),
(2014365,69,40,15,23,'Lakini Yesu hakumjibu neno. Basi, wanafunzi wake wakamwendea, wakamwambia, "Mwambie aende zake kwa maana anatufuatafuata akipiga kelele."'),
(2014366,69,40,15,24,'Yesu akajibu, "Sikutumwa ila kwa watu wa Israeli waliopotea kama kondoo."'),
(2014367,69,40,15,25,'Hapo huyo mama akaja, akapiga magoti mbele yake, akasema, "Mheshimiwa, nisaidie."'),
(2014368,69,40,15,26,'Yesu akamjibu, "Si sawa kuchukua chakula cha watoto na kuwatupia mbwa."'),
(2014369,69,40,15,27,'Huyo mama akajibu, "Ni kweli, Mheshimiwa; lakini hata mbwa hula makombo yanayoanguka kutoka meza ya bwana wao."'),
(2014370,69,40,15,28,'Hapo Yesu akamjibu, "Mama, imani yako ni kubwa; basi, ufanyiwe kama unavyotaka." Yule binti yake akapona tangu saa hiyo wakati huohuo.'),
(2014371,69,40,15,29,'Yesu alitoka hapo akaenda kando ya ziwa Galilaya, akapanda mlimani, akaketi.'),
(2014372,69,40,15,30,'Watu wengi sana wakamjia wakiwaleta vilema, vipofu, viwete, bubu na wengine wengi waliokuwa wagonjwa, wakawaweka mbele ya miguu yake, naye Yesu akawaponya.'),
(2014373,69,40,15,31,'Umati ule wa watu ulishangaa sana ulipoona bubu wakiongea, waliokuwa wamelemaa wamepona, viwete wakitembea na vipofu wakiona; wakamsifu Mungu wa Israeli.'),
(2014374,69,40,15,32,'Basi, Yesu aliwaita wanafunzi wake, akasema, "Nawaonea watu hawa huruma kwa sababu kwa siku tatu wamekuwa nami, wala hawana chakula. Sipendi kuwaacha waende bila kula wasije wakazimia njiani."'),
(2014375,69,40,15,33,'Wanafunzi wakamwambia, "Hapa tuko nyikani; tutapata wapi chakula cha kuwatosha watu wengi hivi?"'),
(2014376,69,40,15,34,'Yesu akawauliza, "Mnayo mikate mingapi?" Wakamjibu, "Saba na visamaki vichache."'),
(2014377,69,40,15,35,'Basi, Yesu akawaamuru watu wakae chini.'),
(2014378,69,40,15,36,'Akaitwaa ile mikate saba na vile visamaki, akamshukuru Mungu, akavimega, akawapa wanafunzi, nao wakawagawia watu.'),
(2014379,69,40,15,37,'Wote wakala, wakashiba. Kisha wakakusanya makombo, wakajaza vikapu saba.'),
(2014380,69,40,15,38,'Hao waliokula walikuwa wanaume elfu nne, bila kuhesabu wanawake na watoto.'),
(2014381,69,40,15,39,'Basi, Yesu akawaaga watu, akapanda mashua, akaenda katika eneo la Magadani.'),
(2014382,69,40,16,1,'Mafarisayo na Masadukayo walimwendea Yesu, na kwa kumjaribu, wakamwomba afanye ishara itokayo mbinguni.'),
(2014383,69,40,16,2,'Lakini Yesu akawajibu, "Wakati wa jioni ukifika ninyi husema: `Hali ya hewa itakuwa nzuri kwa maana anga ni jekundu!`'),
(2014384,69,40,16,3,'Na alfajiri mwasema: `Leo hali ya hewa itakuwa ya dhoruba, maana anga ni jekundu na tena mawingu yametanda!` Basi, ninyi mnajua sana kusoma majira kwa kuangalia anga, lakini kutambua dalili za nyakati hizi hamjui.'),
(2014385,69,40,16,4,'Kizazi kiovu kisicho na uaminifu! Mnataka ishara, lakini hamtapewa ishara yoyote isipokuwa tu ile ya Yona." Basi, akawaacha, akaenda zake.'),
(2014386,69,40,16,5,'Wanafunzi wake walipokwisha vukia upande wa pili wa ziwa, walijikuta wamesahau kuchukua mikate.'),
(2014387,69,40,16,6,'Yesu akawaambia, "Muwe macho na mjihadhari na chachu ya Mafarisayo na Masadukayo!"'),
(2014388,69,40,16,7,'Lakini wao wakawa wanajadiliana: "Anasema hivyo kwa kuwa hatukuchukua mikate."'),
(2014389,69,40,16,8,'Yesu alijua mawazo yao, akawaambia, "Enyi watu wenye imani haba! Mbona mnajadiliana juu ya kutokuwa na mikate?'),
(2014390,69,40,16,9,'Je, hamjaelewa bado? Je, hamkumbuki nilipoimega ile mikate mitano kwa ajili ya wale watu elfu tano? Je, mlijaza vikapu vingapi vya makombo?'),
(2014391,69,40,16,10,'Au, ile mikate saba waliyogawiwa wale watu elfu nne, je, mlikusanya vikapu vingapi vya mabaki?'),
(2014392,69,40,16,11,'Inawezekanaje hamwelewi ya kwamba sikuwa nikisema juu ya mikate? Jihadharini na chachu ya Mafarisayo na Masadukayo!"'),
(2014393,69,40,16,12,'Hapo wanafunzi wakafahamu kwamba aliwaambia wajihadhari siyo na chachu ya mikate, bali na mafundisho ya Mafarisayo na Masadukayo.'),
(2014394,69,40,16,13,'Yesu alipofika pande za Kaisarea Filipi, aliwauliza wanafunzi wake, "Watu wanasema Mwana wa Mtu kuwa ni nani?"'),
(2014395,69,40,16,14,'Wakamjibu, "Wengine wanasema kuwa ni Yohane mbatizaji, wengine Eliya, wengine Yeremia au mmojawapo wa manabii."'),
(2014396,69,40,16,15,'Yesu akawauliza, "Na ninyi je, mwasema mimi ni nani?"'),
(2014397,69,40,16,16,'Simoni Petro akajibu, "Wewe ndiwe Kristo, Mwana wa Mungu aliye hai."'),
(2014398,69,40,16,17,'Yesu akasema, "Heri wewe Simoni mwana wa Yona, kwa maana si binadamu aliyekufunulia ukweli huu, ila Baba yangu aliye mbinguni.'),
(2014399,69,40,16,18,'Nami nakwambia: wewe ni Petro, na juu ya mwamba*ff* huu nitalijenga kanisa langu; wala kifo chenyewe hakitaweza kulishinda.'),
(2014400,69,40,16,19,'Nitakupa funguo za Ufalme wa mbinguni; kila utakachofunga duniani, kitafungwa pia mbinguni; kila utakachofungua duniani, kitafunguliwa pia mbinguni."'),
(2014401,69,40,16,20,'Kisha akawaonya wanafunzi wasimwambie mtu yeyote kwamba yeye ndiye Kristo.'),
(2014402,69,40,16,21,'Tangu wakati huo Yesu alianza kuwajulisha waziwazi wanafunzi wake: "Ni lazima mimi niende Yerusalemu, na huko nikapate mateso mengi yatakayosababishwa na wazee, makuhani wakuu na walimu wa Sheria. Nitauawa, na siku ya tatu nitafufuliwa."'),
(2014403,69,40,16,22,'Hapo Petro akamchukua kando, akaanza kumkemea: "Isiwe hivyo Bwana! Jambo hili halitakupata!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014404,69,40,16,23,'Lakini Yesu akageuka, akamwambia Petro, "Ondoka mbele yangu Shetani! Wewe ni kikwazo kwangu. Mawazo yako si ya mungu bali ni ya kibinadamu!"'),
(2014405,69,40,16,24,'Kisha Yesu akawaambia wanafunzi wake, "Kama mtu yeyote anataka kuwa mfuasi wangu, ni lazima ajikane mwenyewe, auchukue msalaba wake, anifuate.'),
(2014406,69,40,16,25,'Maana, mtu anayetaka kuyaokoa maisha yake mwenyewe, atayapoteza;'),
(2014407,69,40,16,26,'lakini mtu anayeyapoteza maisha yake kwa ajili yangu, atayapata. Je, mtu atafaidi nini akiupata utajiri wote wa ulimwengu na hali amepoteza maisha yake? Au, mtu atatoa kitu gani kiwe badala ya maisha yake?'),
(2014408,69,40,16,27,'Maana, Mwana wa Mtu atakuja katika utukufu wa Baba yake pamoja na malaika wake, na hapo ndipo atakapomlipa kila mtu kadiri ya matendo yake.'),
(2014409,69,40,16,28,'Kweli nawaambieni, wako wengine papahapa ambao hawatakufa kabla ya kumwona Mwana wa Mtu akija katika Ufalme wake."'),
(2014410,69,40,17,1,'Baada ya siku sita, Yesu aliwachukua Petro, Yakobo na Yohane nduguye, akaenda nao peke yao juu ya mlima mrefu.'),
(2014411,69,40,17,2,'Huko, wakiwa wanamtazama, akageuka sura, uso wake ukang`aa kama jua na mavazi yake yakawa meupe kama nuru.'),
(2014412,69,40,17,3,'Mose na Eliya wakawatokea, wakawa wanazungumza naye.'),
(2014413,69,40,17,4,'Hapo Petro akamwambia Yesu, "Bwana, ni vizuri sana kwamba tupo hapa! Ukipenda nitajenga vibanda vitatu: kimoja chako, kimoja cha Mose na kimoja cha Eliya."'),
(2014414,69,40,17,5,'Alipokuwa bado anasema hivyo, wingu jeupe likawafunika, na sauti ikasikika kutoka katika hilo wingu: "Huyu ni Mwanangu mpendwa, ninayependezwa naye, msikilizeni."'),
(2014415,69,40,17,6,'Wanafunzi waliposikia hivyo wakaanguka kifudifudi, wakaogopa sana.'),
(2014416,69,40,17,7,'Yesu akawaendea, akawagusa, akasema, "Simameni, msiogope!"'),
(2014417,69,40,17,8,'Walipoinua macho yao hawakumwona mtu, ila Yesu peke yake.'),
(2014418,69,40,17,9,'Basi, walipokuwa wanashuka mlimani, Yesu akawaonya: "Msimwambie mtu mambo mliyoyaona mpaka Mwana wa Mtu atakapofufuliwa kutoka wafu."'),
(2014419,69,40,17,10,'Kisha wanafunzi wakamwuliza, "Mbona walimu wa Sheria wanasema ati ni lazima kwanza Eliya aje?"'),
(2014420,69,40,17,11,'Yesu akawajibu, "Kweli, Eliya atakuja kutayarisha mambo yote.'),
(2014421,69,40,17,12,'Lakini nawaambieni, Eliya amekwisha kuja nao hawakumtambua, bali walimtendea jinsi walivyotaka. Mwana wa Mtu atateswa vivyo hivyo mikononi mwao."'),
(2014422,69,40,17,13,'Hapo hao wanafunzi wakafahamu kwamba alikuwa akiwaambia juu ya Yohane mbatizaji.'),
(2014423,69,40,17,14,'Walipojiunga tena na ule umati wa watu, mtu mmoja alimwendea Yesu, akampigia magoti,'),
(2014424,69,40,17,15,'akasema, "Mheshimiwa, mwonee huruma mwanangu kwa kuwa ana kifafa, tena anateseka sana; mara nyingi yeye huanguka motoni na majini.'),
(2014425,69,40,17,16,'Nilimleta kwa wanafunzi wako lakini hawakuweza kumponya."'),
(2014426,69,40,17,17,'Yesu akajibu, "Enyi kizazi kisicho na imani, kilichopotoka! Nitakaa nanyi mpaka lini? Nitawavumilia ninyi mpaka lini? Mleteni hapa huyo mtoto."'),
(2014427,69,40,17,18,'Basi, Yesu akamkemea huyo pepo, naye akamtoka, na yule mtoto akapona wakati huohuo.'),
(2014428,69,40,17,19,'Kisha wanafunzi wakamwendea Yesu kwa faragha, wakamwuliza, "Kwa nini sisi hatukuweza kumtoa yule pepo?"'),
(2014429,69,40,17,20,'Yesu akawajibu, "Kwa sababu ya imani yenu haba. Nawaambieni kweli, kama tu mkiwa na imani, hata iwe ndogo kama mbegu ya haradali, mtaweza kuuambia mlima huu: `Toka hapa uende pale,` nao utakwenda. Hakuna chochote ambacho hakingewezekana kwenu."*fg* kuondolewa ila kwa sala na kufunga."'),
(2014430,69,40,17,21,'missing'),
(2014431,69,40,17,22,'Walipokuwa pamoja huko Galilaya, Yesu aliwaambia, "Mwana wa Mtu atakabidhiwa kwa watu.'),
(2014432,69,40,17,23,'Watamuua, lakini siku ya tatu atafufuliwa." Wanafunzi wakahuzunika mno.'),
(2014433,69,40,17,24,'Walipofika Kafarnaumu watu wenye kukusanya fedha ya zaka ya Hekalu walimwendea Petro, wakamwuliza, "Je, mwalimu wenu hulipa fedha ya zaka?"'),
(2014434,69,40,17,25,'Petro akajibu, "Naam, hulipa." Basi, Petro alipoingia ndani ya nyumba, kabla hata hajasema neno, Yesu akamwuliza, "Simoni, wewe unaonaje? Wafalme wa dunia hukusanya ushuru au kodi kutoka kwa kina nani? Kutoka kwa wananchi ama kutoka kwa wageni?"'),
(2014435,69,40,17,26,'Petro akajibu, "Kutoka kwa wageni." Yesu akamwambia, "Haya basi, wananchi hawahusiki.'),
(2014436,69,40,17,27,'Lakini kusudi tusiwakwaze, nenda ziwani ukatupe ndoana; chukua samaki wa kwanza atakayenaswa, fungua kinywa chake, na ndani utakuta fedha taslimu ya zaka. Ichukue ukawape kwa ajili yangu na kwa ajili yako."'),
(2014437,69,40,18,1,'Wakati ule wanafunzi walimwendea Yesu, wakamwuliza, "Ni nani aliye mkuu katika Ufalme wa mbinguni?"'),
(2014438,69,40,18,2,'Yesu akamwita mtoto mmoja, akamsimamisha kati yao,'),
(2014439,69,40,18,3,'kisha akasema, "Nawaambieni kweli, msipogeuka na kuwa kama watoto, hamtaingia kamwe katika Ufalme wa mbinguni.'),
(2014440,69,40,18,4,'Yeyote anayejinyenyekesha kama mtoto huyu, huyo ndiye aliye mkubwa katika Ufalme wa mbinguni.'),
(2014441,69,40,18,5,'Yeyote anayemkaribisha mtoto mmoja kama huyu kwa jina langu, ananikaribisha mimi.'),
(2014442,69,40,18,6,'"Yeyote atakayemkosesha mmoja wa hawa wadogo wanaoniamini, ingekuwa afadhali afungwe shingoni jiwe kubwa la kusagia na kuzamishwa kwenye kilindi cha bahari.'),
(2014443,69,40,18,7,'Ole wake ulimwengu kwa sababu ya vikwazo vinavyowaangusha wengine. Vikwazo hivyo ni lazima vitokee lakini ole wake mtu yule atakayevisababisha.'),
(2014444,69,40,18,8,'"Kama mkono au mguu wako ukikukosesha, ukate na kuutupa mbali nawe. Ni afadhali kwako kuingia katika uzima bila mkono au mguu, kuliko kutupwa katika moto wa milele ukiwa na mikono miwili na miguu yako miwili.'),
(2014445,69,40,18,9,'Na kama jicho lako likikukosesha, ling`oe na kulitupa mbali nawe. Ni afadhali kwako kuingia katika uzima ukiwa chongo, kuliko kutupwa katika moto wa Jehanamu ukiwa na macho yako yote mawili.'),
(2014446,69,40,18,10,'"Jihadharini! Msimdharau mmojawapo wa wadogo hawa. Nawaambieni, malaika wao huko mbinguni wako daima mbele ya Baba yangu aliye mbinguni.*fh*'),
(2014447,69,40,18,11,'missing'),
(2014448,69,40,18,12,'Mnaonaje? Mtu akiwa na kondoo mia, akimpoteza mmoja, hufanyaje? Huwaacha wale tisini na tisa mlimani, na huenda kumtafuta yule aliyepotea.'),
(2014449,69,40,18,13,'Akimpata, nawaambieni kweli, humfurahia huyo kuliko awafurahiavyo wale tisini na tisa ambao hawakupotea.'),
(2014450,69,40,18,14,'Hali kadhalika, Baba yenu wa mbinguni hapendi hata mmoja wa hawa wadogo apotee.'),
(2014451,69,40,18,15,'"Ndugu yako akikukosea, mwendee ukamwonye mkiwa ninyi peke yenu. Akikusikia utakuwa umempata ndugu yako.'),
(2014452,69,40,18,16,'Asipokusikia, chukua mtu mmoja au wawili pamoja nawe, ili kwa mawaidha ya mashahidi wawili au watatu, kila tatizo litatuliwe.'),
(2014453,69,40,18,17,'Asipowasikia hao, liambie kanisa. Na kama hatalisikia kanisa, na awe kwako kama watu wasiomjua Mungu na watoza ushuru.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014454,69,40,18,18,'"Nawaambieni kweli, mtakachofunga duniani kitafungwa mbinguni, na mtakachofungua duniani kitafunguliwa mbinguni.'),
(2014455,69,40,18,19,'Tena nawaambieni, wawili miongoni mwenu wakikubaliana hapa duniani kuhusu jambo lolote la kuomba, Baba yangu wa mbinguni atawafanyia jambo hilo.'),
(2014456,69,40,18,20,'Kwa maana popote pale wanapokusanyika wawili au watatu kwa jina langu, mimi nipo hapo kati yao."'),
(2014457,69,40,18,21,'Kisha Petro akamwendea Yesu, akamwuliza, "Je, ndugu yangu akinikosea, nimsamehe mara ngapi? Mara saba?"'),
(2014458,69,40,18,22,'Yesu akamjibu, "Sisemi mara saba tu, bali sabini mara saba.'),
(2014459,69,40,18,23,'Ndiyo maana Ufalme wa mbinguni umefanana na mfalme mmoja aliyeamua kukagua hesabu za watumishi wake.'),
(2014460,69,40,18,24,'Ukaguzi ulipoanza, akaletewa mtu mmoja aliyekuwa na deni la fedha talanta elfu kumi.'),
(2014461,69,40,18,25,'Mtu huyo hakuwa na chochote cha kulipa; hivyo bwana wake aliamuru wauzwe, yeye, mke wake, watoto wake na vitu vyote alivyokuwa navyo, ili deni lilipwe.'),
(2014462,69,40,18,26,'Basi, huyo mtumishi akapiga magoti mbele yake, akasema, `Unisubiri nami nitakulipa deni lote.`'),
(2014463,69,40,18,27,'Yule bwana alimwonea huruma, akamsamehe lile deni, akamwacha aende zake.'),
(2014464,69,40,18,28,'"Lakini huyo mtumishi akaondoka, akamkuta mmoja wa watumishi wenzake aliyekuwa na deni lake fedha denari mia moja. Akamkamata, akamkaba koo akisema, `Lipa deni lako!`'),
(2014465,69,40,18,29,'Huyo mtumishi mwenzake akapiga magoti, akamwomba, `Unisubiri nami nitalipa deni langu lote.`'),
(2014466,69,40,18,30,'Lakini yeye hakutaka, bali alimtia gerezani mpaka hapo atakapolipa lile deni.'),
(2014467,69,40,18,31,'"Basi, watumishi wenzake walipoona jambo hilo walisikitika sana, wakaenda kumpasha habari bwana wao juu ya mambo hayo yaliyotukia.'),
(2014468,69,40,18,32,'Hapo yule bwana alimwita huyo mtumishi, akamwambia, `Wewe ni mtumishi mbaya sana! Uliniomba, nami nikakusamehe deni lako lote.'),
(2014469,69,40,18,33,'Je, haikukupasa nawe kumhurumia mtumishi mwenzako kama nilivyokuhurumia?`'),
(2014470,69,40,18,34,'"Basi, huyo bwana alikasirika sana, akamtoa huyo mtumishi aadhibiwe mpaka hapo atakapolipa deni lote.'),
(2014471,69,40,18,35,'Na baba yangu aliye mbinguni atawafanyieni vivyo hivyo kama kila mmoja wenu hatamsamehe ndugu yake kwa moyo wake wote."'),
(2014472,69,40,19,1,'Yesu alipomaliza kusema maneno hayo, alitoka Galilaya, akaenda katika mkoa wa Yudea, ng`ambo ya mto Yordani.'),
(2014473,69,40,19,2,'Watu wengi walimfuata huko, naye akawaponya.'),
(2014474,69,40,19,3,'Mafarisayo kadhaa walimjia, wakamwuliza kwa kumtega, "Je, ni halali mume kumpa talaka mkewe kwa kisa chochote?"'),
(2014475,69,40,19,4,'Yesu akawajibu, "Je, hamkusoma katika Maandiko Matakatifu kwamba Mungu aliyemuumba mtu tangu mwanzo alimfanya mwanamume na mwanamke,'),
(2014476,69,40,19,5,'na akasema: `Kwa sababu hiyo mwanamume atamwacha baba yake na mama yake, ataungana na mke wake, nao wawili watakuwa mwili mmoja?`'),
(2014477,69,40,19,6,'Kwa hiyo wao si wawili tena, bali mwili mmoja. Basi, alichounganisha Mungu, binadamu asikitenganishe."'),
(2014478,69,40,19,7,'Lakini wao wakamwuliza, "Kwa nini basi, Mose alituagiza mwanamke apewe hati ya talaka na kuachwa?"'),
(2014479,69,40,19,8,'Yesu akawajibu, "Mose aliwaruhusu kuwaacha wake zenu kwa sababu ya ugumu wa mioyo yenu.'),
(2014480,69,40,19,9,'Lakini haikuwa hivyo tangu mwanzo. Basi nawaambieni, yeyote atakayemwacha mke wake isipokuwa kwa sababu ya uzinzi, akaoa mke mwingine, anazini."'),
(2014481,69,40,19,10,'Wanafunzi wake wakamwambia, "Ikiwa mambo ya mume na mkewe ni hivyo, ni afadhali kutooa kabisa."'),
(2014482,69,40,19,11,'Yesu akawaambia, "Si wote wanaoweza kulipokea fundisho hili, isipokuwa tu wale waliojaliwa na Mungu.'),
(2014483,69,40,19,12,'Maana kuna sababu kadhaa za kutoweza kuoa: wengine ni kwa sababu wamezaliwa hivyo, wengine kwa sababu wamefanywa hivyo na watu, na wengine wameamua kutooa kwa ajili ya Ufalme wa mbinguni. Awezaye kulipokea fundisho hili na alipokee."'),
(2014484,69,40,19,13,'Kisha watu wakamletea Yesu watoto wadogo ili awawekee mikono na kuwaombea. Lakini wanafunzi wakawakemea.'),
(2014485,69,40,19,14,'Yesu akasema, "Waacheni hao watoto waje kwangu, wala msiwazuie; maana Ufalme wa mbinguni ni wa watu walio kama watoto hawa."'),
(2014486,69,40,19,15,'Basi, akawawekea mikono, kisha akaondoka mahali hapo.'),
(2014487,69,40,19,16,'Mtu mmoja alimjia Yesu, akamwuliza, "Mwalimu, nifanye kitu gani chema ili niupate uzima wa milele?"'),
(2014488,69,40,19,17,'Yesu akamwambia, "Mbona unaniuliza kuhusu jambo jema? Kuna mmoja tu aliye mwema. Ukitaka kuingia katika uzima, shika amri."'),
(2014489,69,40,19,18,'Yule mtu akamwuliza, "Amri zipi?" Yesu akasema, "Usiue, usizini, usiibe, usitoe ushahidi wa uongo,'),
(2014490,69,40,19,19,'waheshimu baba yako na mama yako; na, mpende jirani yako kama unavyojipenda mwenyewe."'),
(2014491,69,40,19,20,'Huyo kijana akamwambia, "Hayo yote nimeyazingatia tangu utoto wangu; sasa nifanye nini zaidi?"'),
(2014492,69,40,19,21,'Yesu akamwambia, "Kama unapenda kuwa mkamilifu, nenda ukauze mali yako uwape maskini hiyo fedha, nawe utakuwa na hazina mbinguni, kisha njoo unifuate."'),
(2014493,69,40,19,22,'Huyo kijana aliposikia hayo, alienda zake akiwa mwenye huzuni, maana alikuwa na mali nyingi.'),
(2014494,69,40,19,23,'Hapo Yesu akawaambia wanafunzi wake, "Kweli nawaambieni, itakuwa vigumu sana kwa tajiri kuingia katika Ufalme wa mbinguni.'),
(2014495,69,40,19,24,'Tena nawaambieni, ni rahisi zaidi kwa ngamia kupita katika tundu la sindano, kuliko kwa tajiri kuingia katika Ufalme wa mbinguni."'),
(2014496,69,40,19,25,'Wale wanafunzi waliposikia hivyo walishangaa, wakamwuliza, "Ni nani basi, awezaye kuokoka?"'),
(2014497,69,40,19,26,'Yesu akawatazama, akasema, "Kwa binadamu jambo hili haliwezekani, lakini kwa Mungu mambo yote huwezekana."'),
(2014498,69,40,19,27,'Kisha Petro akasema, "Na sisi je? Tumeacha yote tukakufuata; tutapata nini basi?"'),
(2014499,69,40,19,28,'Yesu akawaambia, "Nawaambieni kweli, Mwana wa Mtu atakapoketi katika kiti cha enzi cha utukufu wake katika ulimwengu mpya, ninyi mlionifuata mtaketi katika viti kumi na viwili mkiyahukumu makabila kumi na mawili ya Israeli.'),
(2014500,69,40,19,29,'Na kila aliyeacha nyumba, au ndugu, au dada, au baba, au mama, au watoto, au mashamba, kwa ajili yangu, atapokea mara mia zaidi, na kupata uzima wa milele.'),
(2014501,69,40,19,30,'Lakini walio wa kwanza watakuwa wa mwisho, na walio wa mwisho watakuwa wa kwanza.'),
(2014502,69,40,20,1,'"Ufalme wa mbinguni unafanana na mtu mwenye shamba la mizabibu, ambaye alitoka asubuhi na mapema kuwaajiri wafanyakazi katika shamba lake.'),
(2014503,69,40,20,2,'Akapatana nao kuwalipa dinari moja kwa siku, kisha akawapeleka katika shamba lake la mizabibu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014504,69,40,20,3,'Akatoka mnamo saa tatu asubuhi, akaona watu wengine wamesimama sokoni, hawana kazi.'),
(2014505,69,40,20,4,'Akawaambia, `Nendeni nanyi mkafanye kazi katika shamba la mizabibu, nami nitawapeni haki yenu.`'),
(2014506,69,40,20,5,'Basi, wakaenda. Huyo mwenye shamba akatoka tena mnamo saa sita na saa tisa, akafanya vivyo hivyo.'),
(2014507,69,40,20,6,'Hata mnamo saa kumi na moja jioni, akatoka tena; akakuta watu wengine wamesimama pale sokoni. Basi, akawauliza, `Mbona mmesimama hapa mchana kutwa bila kazi?`'),
(2014508,69,40,20,7,'Wakamjibu: `Kwa sababu hakuna mtu aliyetuajiri.` Yeye akawaambia, `Nendeni nanyi mkafanye kazi katika shamba la mizabibu.`'),
(2014509,69,40,20,8,'"Kulipokuchwa, huyo mwenye shamba alimwambia mtunza hazina wake, `Waite wafanyakazi ukawalipe mshahara wao, ukianzia na wale walioajiriwa mwisho, na kumalizia na wale wa kwanza.`'),
(2014510,69,40,20,9,'Basi, wakaja wale walioajiriwa mnamo saa kumi na moja, wakapokea kila mmoja dinari moja.'),
(2014511,69,40,20,10,'Wale wa kwanza walipofika, walikuwa wanadhani watapewa zaidi; lakini hata wao wakapewa kila mmoja dinari moja.'),
(2014512,69,40,20,11,'Wakazipokea fedha zao, wakaanza kumnung`unikia yule bwana.'),
(2014513,69,40,20,12,'Wakasema, `Watu hawa walioajiriwa mwisho walifanya kazi kwa muda wa saa moja tu, mbona umetutendea sawa na wao hali sisi tumevumilia kazi ngumu kutwa na jua kali?`'),
(2014514,69,40,20,13,'"Hapo yule bwana akamjibu mmoja wao, `Rafiki, sikukupunja kitu! Je, hukupatana nami mshahara wa denari moja?'),
(2014515,69,40,20,14,'Chukua haki yako, uende zako. Napenda kumpa huyu wa mwisho sawa na wewe.'),
(2014516,69,40,20,15,'Je, sina haki ya kufanya na mali yangu nipendavyo? Je, unaona kijicho kwa kuwa mimi ni mwema?"`'),
(2014517,69,40,20,16,'Yesu akamaliza kwa kusema, "Hivyo, walio wa mwisho watakuwa wa kwanza na wa kwanza watakuwa wa mwisho."'),
(2014518,69,40,20,17,'Yesu alipokuwa anakwenda Yerusalemu, aliwachukua wale wanafunzi kumi na wawili faraghani, na njiani akawaambia,'),
(2014519,69,40,20,18,'"Sikilizeni! Tunakwenda Yerusalemu, na huko Mwana wa Mtu atakabidhiwa kwa makuhani wakuu na walimu wa Sheria, nao watamhukumu auawe.'),
(2014520,69,40,20,19,'Watamkabidhi kwa watu wa mataifa mengine ili adhihakiwe, apigwe viboko na kusulubiwa; lakini siku ya tatu atafufuliwa."'),
(2014521,69,40,20,20,'Hapo mama yao wana wa Zebedayo alimjia Yesu pamoja na wanawe, akapiga magoti mbele yake na kumwomba kitu.'),
(2014522,69,40,20,21,'Yesu akamwuliza, "Unataka nini?" Huyo mama akamwambia, "Ahidi kwamba katika Ufalme wako, hawa wanangu wawili watakaa mmoja upande wako wa kulia na mwingine upande wako wa kushoto."'),
(2014523,69,40,20,22,'Yesu akajibu, "Hamjui mnaomba nini. Je, mnaweza kunywa kikombe nitakachokunywa mimi?" Wakamjibu, "Tunaweza."'),
(2014524,69,40,20,23,'Yesu akawaambia, "Kweli mtakunywa kikombe changu, lakini kuketi kulia au kushoto kwangu si kazi yangu kupanga; jambo hilo watapewa wale waliowekewa tayari na Baba yangu."'),
(2014525,69,40,20,24,'Wale wanafunzi wengine kumi waliposikia hayo, wakawakasirikia hao ndugu wawili.'),
(2014526,69,40,20,25,'Hivyo Yesu akawaita, akawaambia, "Mnajua kwamba watawala wa mataifa hutawala watu wao kwa mabavu na wakuu hao huwamiliki watu wao.'),
(2014527,69,40,20,26,'Lakini kwenu isiwe hivyo, ila yeyote anayetaka kuwa mkuu kati yenu sharti awe mtumishi wa wote;'),
(2014528,69,40,20,27,'na anayetaka kuwa wa kwanza kati yenu sharti awe mtumishi wenu.'),
(2014529,69,40,20,28,'Jinsi hiyohiyo, Mwana wa Mtu hakuja kutumikiwa, bali kutumikia na kutoa maisha yake kuwa fidia ya watu wengi."'),
(2014530,69,40,20,29,'Yesu alipokuwa anaondoka mjini Yeriko, umati wa watu ulimfuata.'),
(2014531,69,40,20,30,'Basi, kulikuwa na vipofu wawili wameketi kando ya njia, na waliposikia kwamba Yesu alikuwa anapitia hapo, walipaaza sauti: "Mheshimiwa, Mwana wa Daudi, utuhurumie!"'),
(2014532,69,40,20,31,'Ule umati wa watu ukawakemea na kuwaambia wanyamaze. Lakini wao wakazidi kupaaza sauti: "Mheshimiwa, Mwana wa Daudi, utuhurumie!"'),
(2014533,69,40,20,32,'Yesu akasimama, akawaita na kuwauliza, "Mnataka niwafanyie nini?"'),
(2014534,69,40,20,33,'Wakamjibu, "Mheshimiwa, tunaomba macho yetu yafumbuliwe."'),
(2014535,69,40,20,34,'Basi, Yesu akawaonea huruma, akawagusa macho yao, na papo hapo wakaweza kuona, wakamfuata.'),
(2014536,69,40,21,1,'Yesu na wanafunzi wake walipokaribia Yerusalemu na kufika Bethfage katika mlima wa Mizeituni, aliwatuma wanafunzi wake wawili,'),
(2014537,69,40,21,2,'akawaambia, "Nendeni hadi kijiji kilicho mbele yenu na mtamkuta punda amefungwa na mtoto wake. Wafungueni mkawalete kwangu.'),
(2014538,69,40,21,3,'Kama mtu akiwauliza sababu, mwambieni, `Bwana anawahitaji,` naye atawaachieni mara."'),
(2014539,69,40,21,4,'Jambo hili lilifanyika ili yale yaliyosemwa na nabii yatimie:'),
(2014540,69,40,21,5,'"Uambieni mji wa Sioni: Tazama, Mfalme wako anakujia! Ni mpole na amepanda punda, mwana punda, mtoto wa punda."'),
(2014541,69,40,21,6,'Hivyo, wale wanafunzi walienda wakafanya kama Yesu alivyowaagiza.'),
(2014542,69,40,21,7,'Wakamleta yule punda na mtoto wake, wakatandika nguo zao juu yao na Yesu akaketi juu yake.'),
(2014543,69,40,21,8,'Umati mkubwa wa watu ukatandaza nguo zao barabarani, na watu wengine wakakata matawi ya miti wakayatandaza barabarani.'),
(2014544,69,40,21,9,'Makundi ya watu waliomtangulia na wale waliomfuata wakapaaza sauti: "Hosana Mwana wa Daudi! Abarikiwe huyo ajaye kwa jina la Bwana! Hosana Mungu juu mbinguni!"'),
(2014545,69,40,21,10,'Yesu alipokuwa anaingia Yerusalemu, mji wote ukajaa ghasia. Watu wakawa wanauliza, "Huyu ni nani?"'),
(2014546,69,40,21,11,'Watu katika ule umati wakasema, "Huyu ni nabii Yesu, kutoka Nazareti katika mkoa wa Galilaya."'),
(2014547,69,40,21,12,'Basi, Yesu akaingia Hekaluni, akawafukuza nje watu waliokuwa wanauza na kununua vitu ndani ya Hekalu; akazipindua meza za wale waliokuwa wanavunja fedha, na viti vya wale waliokuwa wanauza njiwa.'),
(2014548,69,40,21,13,'Akawaambia, "Imeandikwa katika Maandiko Matakatifu: `Nyumba yangu itaitwa nyumba ya sala.` Lakini ninyi mmeifanya kuwa pango la wanyang`anyi."'),
(2014549,69,40,21,14,'Vipofu na vilema walimwendea huko Hekaluni, naye Yesu akawaponya.'),
(2014550,69,40,21,15,'Basi, makuhani wakuu na walimu wa Sheria walipoyaona maajabu aliyoyafanya Yesu, na pia watoto walipokuwa wanapaaza sauti zao Hekaluni wakisema: "Sifa kwa Mwana wa Daudi," wakakasirika.'),
(2014551,69,40,21,16,'Hivyo wakamwambia, "Je, husikii wanachosema?" Yesu akawajibu, "Naam, nasikia! Je hamjasoma Maandiko haya Matakatifu? `Kwa vinywa vya watoto wadogo na wanyonyao unajipatia sifa kamilifu."`'),
(2014552,69,40,21,17,'Basi, akawaacha, akatoka nje ya mji na kwenda Bethania, akalala huko.'),
(2014553,69,40,21,18,'Yesu alipokuwa anarudi mjini asubuhi na mapema, aliona njaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014554,69,40,21,19,'Akauona mtini mmoja kando ya njia, akauendea; lakini aliukuta hauma chochote ila majani matupu. Basi akauambia, "Usizae tena matunda milele!" Papo hapo huo mtini ukanyauka.'),
(2014555,69,40,21,20,'Wanafunzi walipouona walishangaa wakisema, "Kwa nini mtini huu umenyauka ghafla?"'),
(2014556,69,40,21,21,'Yesu akawajibu, "Kweli nawaambieni, kama mkiwa na imani bila kuwa na mashaka, mnaweza si tu kufanya hivyo, bali hata mkiuambia mlima huu: `Ng`oka ukajitose baharini,` itafanyika hivyo.'),
(2014557,69,40,21,22,'Na mkiwa na imani, chochote mtakachoomba katika sala, mtapata."'),
(2014558,69,40,21,23,'Yesu aliingia Hekaluni, akawa anafundisha. Alipokuwa akifundisha, makuhani wakuu na wazee wa watu wakamwuliza, "Unafanya mambo haya kwa mamlaka gani? Nani amekupa mamlaka haya?"'),
(2014559,69,40,21,24,'Yesu akawajibu, "Na mimi nitawaulizeni swali moja; mkinijibu, basi nami nitawaambieni ninafanya mambo haya kwa mamlaka gani.'),
(2014560,69,40,21,25,'Je, mamlaka ya Yohane ya kubatiza yalitoka kwa nani? Je, yalitoka mbinguni ama kwa watu?" Lakini wakajadiliana wao kwa wao hivi: "Tukisema, `Yalitoka mbinguni`, atatuuliza, `Basi, mbona hamkumsadiki?`'),
(2014561,69,40,21,26,'Na tukisema, `Yalitoka kwa watu,` tunaogopa umati wa watu maana wote wanakubali kwamba Yohane ni nabii."'),
(2014562,69,40,21,27,'Basi, wakamjibu, "Hatujui!" Naye Yesu akawaambia, "Nami pia sitawaambieni ninafanya mambo haya kwa mamlaka gani.'),
(2014563,69,40,21,28,'"Ninyi mnaonaje; mtu mmoja alikuwa na wana wawili. Akamwambia yule wa kwanza, `Mwanangu, leo nenda ukafanye kazi katika shamba la mizabibu.`'),
(2014564,69,40,21,29,'Yule kijana akamwambia, `Sitaki!` Lakini baadaye akabadili nia, akaenda kufanya kazi.'),
(2014565,69,40,21,30,'Yule baba akamwambia mtoto wake wa pili vivyo hivyo, naye akamjibu, `Naam baba!` Lakini hakwenda kazini.'),
(2014566,69,40,21,31,'Je, ni nani kati ya hawa wawili aliyetimiza matakwa ya baba yake?" Wakamjibu, "Yule mtoto wa kwanza." Basi, Yesu akawaambia, "Kweli nawaambieni, watoza ushuru na waasherati wataingia katika Ufalme wa Mungu kabla yenu.'),
(2014567,69,40,21,32,'Maana Yohane alikuja kwenu akawaonyesha njia njema ya kuishi, nanyi hamkumwamini; lakini watoza ushuru na waasherati walimwamini. Hata baada ya kuona hayo yote ninyi hamkubadili mioyo yenu, na hamkusadiki."'),
(2014568,69,40,21,33,'Yesu akasema, "Sikilizeni mfano mwingine. Mtu mmoja mwenye nyumba alilima shamba la mizabibu; akalizungushia ukuta, akachimba kisima cha kusindikia divai, akajenga humo mnara pia. Kisha akalikodisha kwa wakulima, akasafiri kwenda nchi ya mbali.'),
(2014569,69,40,21,34,'Wakati wa mavuno ulipofika, aliwatuma watumishi wake kwa wale wakulima, ili wakachukue sehemu ya mavuno yake.'),
(2014570,69,40,21,35,'Wale wakulima wakawakamata hao watumishi; mmoja wakampiga, mwingine wakamwua na mwingine wakampiga mawe.'),
(2014571,69,40,21,36,'Huyo mtu akawatuma tena watumishi wengine, wengi kuliko wa safari ya kwanza. Wale wakulima wakawatendea namna ileile.'),
(2014572,69,40,21,37,'Mwishowe akamtuma mwanawe huku akifikiri: `Watamheshimu mwanangu.`'),
(2014573,69,40,21,38,'Lakini wale wakulima walipomwona mwanawe wakasemezana wao kwa wao: `Huyu ndiye mrithi; na tumuue ili tuuchukue urithi wake!`'),
(2014574,69,40,21,39,'Basi, wakamkamata, wakamtoa nje ya lile shamba la mizabibu, wakamwua.'),
(2014575,69,40,21,40,'"Sasa, huyo mwenye shamba la mizabibu atakapokuja, atawafanyaje hao wakulima?"'),
(2014576,69,40,21,41,'Wao wakamjibu, "Atawaangamiza vibaya hao waovu, na lile shamba atawapa wakulima wengine ambao watampa sehemu ya mavuno wakati wa mavuno."'),
(2014577,69,40,21,42,'Hapo Yesu akawaambia, "Je, hamkusoma jambo hili katika Maandiko Matakatifu? `Jiwe walilokataa waashi sasa limekuwa jiwe kuu la msingi. Bwana ndiye aliyefanya jambo hili, nalo ni la ajabu sana kwetu!`'),
(2014578,69,40,21,43,'"Kwa hiyo nawaambieni, Ufalme wa Mungu utaondolewa kwenu na kupewa watu wa mataifa mengine wenye kutoa matunda yake."*fi* likimwangukia mtu yeyote, litamponda."'),
(2014579,69,40,21,44,'missing'),
(2014580,69,40,21,45,'Makuhani wakuu na Mafarisayo waliposikia hiyo mifano yake walitambua kwamba alikuwa anawasema wao.'),
(2014581,69,40,21,46,'Kwa hiyo wakawa wanatafuta njia ya kumtia nguvuni, lakini waliwaogopa watu kwa sababu wao walimtambua yeye kuwa nabii.'),
(2014582,69,40,22,1,'Kisha Yesu akauambia umati wa watu pamoja na wanafunzi wake,'),
(2014583,69,40,22,2,'"Walimu wa Sheria na Mafarisayo wana mamlaka ya kufafanua Sheria ya Mose.'),
(2014584,69,40,22,3,'Kwa hiyo shikeni na kutekeleza chochote watakachowaambieni. Lakini msiyaige matendo yao, maana hawatekelezi yale wanayoyahubiri.'),
(2014585,69,40,22,4,'Hufunga mizigo mizito na kuwatwika watu mabegani, lakini wao wenyewe hawataki kunyosha hata kidole wapate kuibeba.'),
(2014586,69,40,22,5,'Wao hufanya matendo yao yote ili watu wawaone. Huvaa tepe zenye maandishi ya Sheria juu ya panda la uso na mikononi na hupanua pindo za makoti yao.'),
(2014587,69,40,22,6,'Hupenda nafasi za heshima katika karamu na viti vya heshima katika masunagogi.'),
(2014588,69,40,22,7,'Hupenda kusalimiwa kwa heshima sokoni na kupendelea kuitwa na watu: `Mwalimu.`'),
(2014589,69,40,22,8,'Lakini ninyi msiitwe kamwe `Mwalimu,` maana mwalimu wenu ni mmoja tu, nanyi nyote ni ndugu.'),
(2014590,69,40,22,9,'Wala msimwite mtu yeyote `Baba` hapa duniani, maana Baba yenu ni mmoja tu aliye mbinguni.'),
(2014591,69,40,22,10,'Wala msiitwe `Viongozi,` maana kiongozi wenu ni mmoja tu, ndiye Kristo.'),
(2014592,69,40,22,11,'Aliye mkubwa miongoni mwenu ni lazima awe mtumishi wenu.'),
(2014593,69,40,22,12,'Anayejikweza atashushwa, na anayejishusha atakwezwa.'),
(2014594,69,40,22,13,'"Ole wenu walimu wa Sheria na Mafarisayo, wanafiki! Mnaufunga mlango wa Ufalme wa mbinguni mbele ya macho ya watu. Ninyi wenyewe hamwingii ndani, wala hamwaruhusu wanaotaka kuingia waingie.*fj* wajane na kujisingizia kuwa watu wema kwa kusali sala ndefu. Kwa sababu hiyo mtapata adhabu kali.'),
(2014595,69,40,22,14,'missing'),
(2014596,69,40,22,15,'"Ole wenu walimu wa Sheria na Mafarisayo, wanafiki! Mnasafiri baharini na nchi kavu ili kumpata mtu mmoja afuate dini yenu. Mnapompata, mnamfanya astahili maradufu kwenda katika moto wa Jehanamu kuliko ninyi wenyewe.'),
(2014597,69,40,22,16,'"Ole wenu viongozi vipofu! Ninyi mwasema ati mtu akiapa kwa Hekalu, kiapo hicho si kitu; lakini akiapa kwa dhahabu ya Hekalu, kiapo hicho kinamshika.'),
(2014598,69,40,22,17,'Enyi vipofu wapumbavu! Kipi kilicho cha maana zaidi: dhahabu au Hekalu linalofanya hiyo dhahabu kuwa takatifu?'),
(2014599,69,40,22,18,'Tena mwasema ati mtu akiapa kwa madhabahu si kitu; lakini akiapa kwa zawadi iliyowekwa juu ya madhabahu, kiapo hicho humshika.'),
(2014600,69,40,22,19,'Enyi vipofu! Ni kipi kilicho cha maana zaidi: ile zawadi, au madhabahu ambayo hufanya hiyo zawadi kuwa takatifu?'),
(2014601,69,40,22,20,'Anayeapa kwa madhabahu ameapa kwa hiyo madhabahu, na kwa chochote kilichowekwa juu yake.'),
(2014602,69,40,22,21,'Na anayeapa kwa Hekalu ameapa kwa hilo Hekalu na pia kwa yule akaaye ndani yake.'),
(2014603,69,40,22,22,'Na anayeapa kwa mbingu ameapa kwa kiti cha enzi cha Mungu, na kwa huyo aketiye juu yake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014604,69,40,22,23,'Ole wenu walimu wa Sheria na Mafarisayo, wanafiki! Mnatoza watu zaka, hata juu ya majani yenye harufu nzuri, bizari na jira, na huku mnaacha mambo muhimu ya Sheria kama vile haki, huruma na imani. Haya ndiyo hasa mliyopaswa kuyazingatia bila kusahau yale mengine.'),
(2014605,69,40,22,24,'Viongozi vipofu! Mnatoa nzi katika kinywaji, lakini mnameza ngamia! ic'),
(2014606,69,40,22,25,'"Ole wenu walimu wa Sheria na Mafarisayo, wanafiki! Mnasafisha kikombe na bakuli kwa nje, lakini ndani mnaacha kumejaa vitu mlivyopata kwa unyang`anyi na uchoyo.'),
(2014607,69,40,22,26,'Mfarisayo kipofu! Kisafishe kikombe ndani kwanza na nje kutakuwa safi pia.'),
(2014608,69,40,22,27,'"Ole wenu walimu wa Sheria na Mafarisayo, wanafiki! Mko kama makaburi yaliyopakwa chokaa ambayo kwa nje yanaonekana kuwa mazuri, lakini ndani yamejaa mifupa ya maiti na kila namna ya uchafu.'),
(2014609,69,40,22,28,'Hali kadhalika ninyi mnaonekana na watu kwa nje kuwa wema, lakini kwa ndani mmejaa unafiki na uovu.'),
(2014610,69,40,22,29,'"Ole wenu walimu wa Sheria na Mafarisayo, wanafiki! Mnajenga makaburi ya manabii na kuyapamba makaburi ya watu wema.'),
(2014611,69,40,22,30,'Mwasema: `Kama sisi tungaliishi nyakati za wazee wetu hatungalishirikiana nao katika mauaji ya manabii!`'),
(2014612,69,40,22,31,'Hivyo mnathibitisha ninyi wenyewe kwamba ninyi ni watoto wa watu waliowaua manabii.'),
(2014613,69,40,22,32,'Haya, kamilisheni ile kazi wazee wenu waliyoianza!'),
(2014614,69,40,22,33,'Enyi kizazi cha nyoka wenye sumu! Mnawezaje kuiepa hukumu ya moto wa Jehanamu?'),
(2014615,69,40,22,34,'Ndiyo maana mimi ninawapelekea ninyi manabii, watu wenye hekima na walimu; mtawaua na kuwasulubisha baadhi yao, na wengine mtawapiga viboko katika masunagogi yenu na kuwasaka katika kila mji.'),
(2014616,69,40,22,35,'Hivyo lawama yote itawapateni kwa ajili ya damu yote ya watu wema iliyomwagwa juu ya ardhi. Naam, tangu kuuawa kwa Abeli ambaye hakuwa na hatia, mpaka kuuawa kwa Zakariya, mwana wa Barakia, ambaye mlimuua Hekaluni kati ya patakatifu na madhabahu.'),
(2014617,69,40,22,36,'Nawaambieni kweli, kizazi hiki kitapata adhabu kwa sababu ya mambo haya.'),
(2014618,69,40,22,37,'"Yerusalemu, Ee Yerusalemu! Unawaua manabii na kuwapiga mawe wale waliotumwa kwako. Mara ngapi nimejaribu kuwakusanya watoto wako kwangu, kama vile kuku anavyokusanya vifaranga vyake chini ya mabawa yake, lakini hukutaka.'),
(2014619,69,40,22,38,'Haya basi, nyumba yako itaachwa mahame.'),
(2014620,69,40,22,39,'Nakwambia kweli, hutaniona tena mpaka wakati utakaposema: `Abarikiwe huyo ajaye kwa jina la Bwana."` ic'),
(2014621,69,40,22,40,'Sheria yote ya Mose na mafundisho ya manabii vinategemea amri hizi mbili."'),
(2014622,69,40,22,41,'Mafarisayo walipokusanyika pamoja, Yesu aliwauliza,'),
(2014623,69,40,22,42,'"Ninyi mwaonaje juu ya Kristo? Je, ni mwana wa nani?" Wakamjibu, "Wa Daudi."'),
(2014624,69,40,22,43,'Yesu akawaambia, "Basi, inawezekanaje kwamba kwa nguvu ya Roho Mtakatifu Daudi anamwita yeye Bwana? Maana alisema:'),
(2014625,69,40,22,44,'`Bwana alimwambia Bwana wangu: keti upande wangu wa kulia, mpaka niwaweke adui zako chini ya miguu yako.`'),
(2014626,69,40,22,45,'Basi, ikiwa Daudi anamwita Kristo `Bwana,` anawezaje kuwa mwanawe?"'),
(2014627,69,40,22,46,'Hakuna mtu yeyote aliyeweza kumjibu neno. Na tangu siku hiyo hakuna aliyethubutu tena kumwuliza swali.'),
(2014628,69,40,24,1,'Yesu alitoka Hekaluni, na alipokuwa akienda zake, wanafunzi wake walimwendea, wakamwonyesha majengo ya Hekalu.'),
(2014629,69,40,24,2,'Yesu akawaambia, "Sawa, mnaweza kuyatazama haya yote! Kweli nawaambieni, hakuna hata jiwe moja litakalosalia hapa juu ya lingine; kila kitu kitaharibiwa."'),
(2014630,69,40,24,3,'Yesu alipokuwa ameketi juu ya mlima wa Mizeituni, wanafunzi walimwendea faraghani, wakamwuliza, "Twambie mambo haya yatatukia lini? Ni ishara gani itakayoonyesha kuja kwako na mwisho wa nyakati?"'),
(2014631,69,40,24,4,'Yesu akawajibu, "Jihadharini msije mkadanganywa na mtu.'),
(2014632,69,40,24,5,'Maana wengi watatokea na kulitumia jina langu wakisema: `Mimi ndiye Kristo,` nao watawapotosha watu wengi.'),
(2014633,69,40,24,6,'Mtasikia juu ya vita na fununu za vita; lakini msifadhaike, maana hayo hayana budi kutokea, lakini mwisho wenyewe ungali bado.'),
(2014634,69,40,24,7,'Taifa moja litapigana na taifa lingine; ufalme mmoja utapigana na ufalme mwingine. Hapa na pale patakuwa na njaa na mitetemeko ya ardhi.'),
(2014635,69,40,24,8,'Yote hayo ni kama mwanzo wa maumivu ya kujifungua mtoto.'),
(2014636,69,40,24,9,'"Kisha watawatoeni ili mteswe na kuuawa. Mataifa yote yatawachukieni kwa ajili ya jina langu.'),
(2014637,69,40,24,10,'Tena, wengi wataiacha imani yao, watasalitiana na kuchukiana.'),
(2014638,69,40,24,11,'Watatokea manabii wengi wa uongo watakaowapotosha watu wengi.'),
(2014639,69,40,24,12,'Kwa sababu ya ongezeko la uhalifu, upendo wa watu wengi utafifia.'),
(2014640,69,40,24,13,'Lakini atakayevumilia mpaka mwisho, ataokoka.'),
(2014641,69,40,24,14,'Ila, kabla ya mwisho kufika, hii Habari Njema ya Ufalme wa Mungu itahubiriwa ulimwenguni kote kama ushuhuda kwa mataifa yote.'),
(2014642,69,40,24,15,'"Basi, mtakapoona `Chukizo Haribifu` lililonenwa na nabii Danieli limesimama mahali patakatifu, (msomaji na atambue maana yake),'),
(2014643,69,40,24,16,'hapo, walioko Yudea na wakimbilie milimani.'),
(2014644,69,40,24,17,'Aliye juu ya paa la nyumba yake asishuke kuchukua kitu nyumbani mwake.'),
(2014645,69,40,24,18,'Aliye shambani asirudi nyuma kuchukua vazi lake.'),
(2014646,69,40,24,19,'Ole wao kina mama waja wazito na wanaonyonyesha siku hizo!'),
(2014647,69,40,24,20,'Ombeni ili kukimbia kwenu kusiwe siku za baridi au siku ya Sabato!'),
(2014648,69,40,24,21,'Maana wakati huo kutakuwa na dhiki kuu ambayo haijapata kuwako tangu mwanzo wa ulimwengu mpaka leo, wala haitapata kutokea tena.'),
(2014649,69,40,24,22,'Kama siku hizo hazingalipunguzwa, hakuna binadamu yeyote ambaye angeokoka; lakini siku hizo zitapunguzwa kwa ajili ya wale walioteuliwa.'),
(2014650,69,40,24,23,'"Basi, mtu akiwaambieni siku hizo: `Kristo yuko hapa` au `Yuko pale,` msimsadiki.'),
(2014651,69,40,24,24,'Maana watatokea kina Kristo wa uongo na manabii wa uongo. Watafanya ishara kubwa na maajabu ya kuweza kuwapotosha ikiwezekana hata wateule wa Mungu.'),
(2014652,69,40,24,25,'Sikilizeni, nimekwisha kuwaonya kabla ya wakati.'),
(2014653,69,40,24,26,'Basi, wakiwaambieni, `Tazameni, yuko jangwani,` msiende huko; au, `Tazameni, amejificha ndani,` msisadiki;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014654,69,40,24,27,'maana, kama vile umeme uangazavyo toka mashariki hadi magharibi, ndivyo kutakavyokuwa kuja kwake Mwana wa Mtu.'),
(2014655,69,40,24,28,'Pale ulipo mzoga, ndipo watakapokusanyika tai.'),
(2014656,69,40,24,29,'"Mara baada ya dhiki ya siku hizo, jua litatiwa giza, mwezi hautaangaza, nyota zitaanguka kutoka angani, na nguvu za mbingu zitatikiswa.'),
(2014657,69,40,24,30,'Kisha, ishara ya Mwana wa Mtu itaonekana angani, na hapo makabila yote duniani yatalalamika; watamwona Mwana wa Mtu akija juu ya mawingu ya angani mwenye nguvu na utukufu mwingi.'),
(2014658,69,40,24,31,'Naye atawatuma malaika wake wenye tarumbeta la kuvuma sana, nao watawakusanya wateule wake kutoka pande zote nne za dunia, toka mwisho huu wa mbingu hadi mwisho huu.'),
(2014659,69,40,24,32,'"Kwa mtini jifunzeni mfano huu: Mara tu matawi yake yanapoanza kuwa laini na kuchanua majani, mnajua kwamba wakati wa kiangazi umekaribia.'),
(2014660,69,40,24,33,'Hali kadhalika nanyi mtakapoona mambo haya yote yakitendeka, jueni kwamba yuko karibu sana.*fk*'),
(2014661,69,40,24,34,'Nawaambieni kweli, kizazi hiki hakitapita kabla ya mambo hayo yote kutukia.'),
(2014662,69,40,24,35,'Naam, mbingu na dunia zitapita, lakini maneno yangu hayatapita kamwe.'),
(2014663,69,40,24,36,'"Lakini, juu ya siku au saa hiyo, hakuna mtu ajuaye itakuja lini; wala malaika wa mbinguni, wala Mwana, ila Baba peke yake ndiye ajuaye.'),
(2014664,69,40,24,37,'Kwa maana kama ilivyokuwa nyakati za Noa, ndivyo itakavyokuwa kuja kwake Mwana wa Mtu.'),
(2014665,69,40,24,38,'Maana nyakati hizo, kabla ya gharika kuu, watu walikuwa wakila na kunywa, wakioa na kuolewa, mpaka Noa alipoingia ndani ya ile safina.'),
(2014666,69,40,24,39,'Hawakujua kuna nini mpaka ile gharika ilipotokea, ikawakumba wote. Ndivyo itakavyokuwa wakati Mwana wa Mtu atakapokuja.'),
(2014667,69,40,24,40,'Wakati huo watu wawili watakuwa shambani; mmoja atachukuliwa na mwingine ataachwa.'),
(2014668,69,40,24,41,'Kina mama wawili watakuwa wanasaga nafaka, mmoja atachukuliwa na mwingine ataachwa.'),
(2014669,69,40,24,42,'Basi, kesheni, kwa maana hamjui siku atakayokuja Bwana wenu.'),
(2014670,69,40,24,43,'Lakini kumbukeni jambo hili: kama mwenye nyumba angejua siku mwizi atakapofika, angekesha, wala hangeiacha nyumba yake ivunjwe.'),
(2014671,69,40,24,44,'Kwa hiyo, nanyi pia muwe tayari, kwa maana Mwana wa Mtu atakuja saa msiyoitazamia."'),
(2014672,69,40,24,45,'Yesu akaendelea kusema, "Ni nani basi mtumishi mwaminifu na mwenye busara, ambaye bwana wake atamweka juu ya watu wake, awape chakula kwa wakati wake?'),
(2014673,69,40,24,46,'Heri mtumishi yule ambaye bwana wake atakapokuja atamkuta akifanya hivyo.'),
(2014674,69,40,24,47,'Kweli nawaambieni, atamweka mtumishi huyo aisimamie mali yake yote.'),
(2014675,69,40,24,48,'Lakini kama mtumishi mbaya akijisemea moyoni: `Bwana wangu anakawia kurudi,`'),
(2014676,69,40,24,49,'kisha akaanza kuwapiga watumishi wenzake, akaanza kula na kunywa pamoja na walevi,'),
(2014677,69,40,24,50,'bwana wake atakuja siku asiyoitazamia na saa asiyoijua.'),
(2014678,69,40,24,51,'Atamkatilia mbali na kumweka kundi moja na wanafiki. Huko kutakuwa na kilio na kusaga meno.'),
(2014679,69,40,25,1,'"Wakati huo, Ufalme wa mbinguni utafanana na wasichana kumi waliochukua taa zao, wakaenda kumlaki bwana arusi.'),
(2014680,69,40,25,2,'Watano miongoni mwao walikuwa wapumbavu na watano walikuwa wenye busara.'),
(2014681,69,40,25,3,'Wale wapumbavu walichukua taa zao, lakini hawakuchukua akiba ya mafuta.'),
(2014682,69,40,25,4,'Lakini wale wenye busara walichukua mafuta katika chupa pamoja na taa zao.'),
(2014683,69,40,25,5,'Kwa kuwa bwana arusi alikawia kuja, wale wanawali wote wote walisinzia, wakalala.'),
(2014684,69,40,25,6,'Usiku wa manane kukawa na kelele: `Haya, haya! Bwana arusi anakuja; nendeni kumlaki.`'),
(2014685,69,40,25,7,'Hapo wale wanawali wote wakaamka, wakazitayarisha taa zao.'),
(2014686,69,40,25,8,'Wale wapumbavu wakawaambia wale wenye busara: `Tupeni mafuta yenu kidogo maana taa zetu zinazimika.`'),
(2014687,69,40,25,9,'Lakini wale wenye busara wakawaambia, `Hayatatutosha sisi na ninyi! Afadhali mwende dukani mkajinunulie wenyewe!`'),
(2014688,69,40,25,10,'Basi, wale wanawali wapumbavu walipokwenda kununua mafuta, bwana arusi akafika, na wale wanawali waliokuwa tayari wakaingia pamoja naye katika jumba la arusi, kisha mlango ukafungwa.'),
(2014689,69,40,25,11,'Baadaye wale wanawali wengine wakaja, wakaita: `Bwana, bwana, tufungulie!`'),
(2014690,69,40,25,12,'Lakini yeye akawajibu, `Nawaambieni kweli, siwajui ninyi."`'),
(2014691,69,40,25,13,'Kisha Yesu akasema, "Kesheni basi, kwa maana hamjui siku wala saa.'),
(2014692,69,40,25,14,'"Itakuwa kama mtu mmoja aliyetaka kusafiri ng`ambo: aliwaita watumishi wake, akawakabidhi mali yake.'),
(2014693,69,40,25,15,'Alimpa kila mmoja kadiri ya uwezo wake: mmoja sarafu tano za fedha ziitwazo talanta, mwingine talanta mbili na mwingine talanta moja, kisha akasafiri.'),
(2014694,69,40,25,16,'Mara yule aliyekabidhiwa talanta tano akafanya kazi nazo akapata faida talanta tano.'),
(2014695,69,40,25,17,'Hali kadhalika na yule aliyekabidhiwa talanta mbili akapata faida talanta mbili.'),
(2014696,69,40,25,18,'Lakini yule aliyekabidhiwa talanta moja akaenda akachimba shimo ardhini, akaificha fedha ya bwana wake.'),
(2014697,69,40,25,19,'"Baada ya muda mrefu, yule bwana alirudi, akaanza kukagua hesabu ya matumizi na mapato ya fedha yake.'),
(2014698,69,40,25,20,'Mtumishi aliyekabidhiwa talanta tano akaja amechukua zile talanta tano faida, akamwambia, `Bwana, ulinikabidhi talanta tano, hapa pana talanta tano zaidi faida niliyopata.`'),
(2014699,69,40,25,21,'Bwana wake akamwambia, `Vema, mtumishi mwema na mwaminifu. Umekuwa mwaminifu katika mambo madogo nitakukabidhi makubwa. Njoo ufurahi pamoja na bwana wako.`'),
(2014700,69,40,25,22,'"Mtumishi aliyekabidhiwa talanta mbili akaja, akatoa talanta mbili faida, akisema, `Bwana, ulinikabidhi talanta mbili. Chukua talanta mbili zaidi faida niliyopata.`'),
(2014701,69,40,25,23,'Bwana wake akamwambia, `Vema, mtumishi mwema na mwaminifu. Umekuwa mwaminifu katika mambo madogo, nitakukabidhi makubwa. Njoo ufurahi pamoja na bwana wako.`'),
(2014702,69,40,25,24,'"Lakini yule aliyekabidhiwa talanta moja akaja, akasema, `Bwana, najua wewe ni mtu mgumu; wewe huvuna pale ambapo hukupanda, na kukusanya pale ambapo hukutawanya.'),
(2014703,69,40,25,25,'Niliogopa, nikaificha fedha yako katika ardhi. Chukua basi mali yako.`');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014704,69,40,25,26,'"Bwana wake akamwambia, `Wewe ni mtumishi mwovu na mvivu! Unajua kuwa mimi huvuna mahali ambapo sikupanda, na hukusanya pale ambapo sikutawanya.'),
(2014705,69,40,25,27,'Ilikupasa basi, kuiweka fedha yangu katika benki, nami ningelichukua mtaji wangu na faida yake!'),
(2014706,69,40,25,28,'Basi, mnyang`anyeni hiyo fedha mkampe yule mwenye talanta kumi.'),
(2014707,69,40,25,29,'Maana, aliye na kitu atapewa na kuzidishiwa. Lakini yule asiye na kitu, hata kile alicho nacho kitachukuliwa.'),
(2014708,69,40,25,30,'Na kuhusu huyu mtumishi asiye na faida, mtupeni nje gizani! Huko kutakuwa na kilio na kusaga meno.`'),
(2014709,69,40,25,31,'"Wakati Mwana wa Mtu atakapokuja katika utukufu wake na malaika wote wakiwa pamoja naye, hapo ataketi juu ya kiti chake cha enzi kitukufu,'),
(2014710,69,40,25,32,'na mataifa yote yatakusanyika mbele yake, naye atawatenganisha watu kama mchungaji anavyotenganisha kondoo na mbuzi.'),
(2014711,69,40,25,33,'Atawaweka kondoo upande wake wa kulia na mbuzi upande wake wa kushoto.'),
(2014712,69,40,25,34,'"Kisha Mfalme atawaambia wale walio upande wake wa kulia, `Njoni enyi mliobarikiwa na Baba yangu; pokeeni Ufalme mliotayarishiwa tangu kuumbwa kwa ulimwengu.'),
(2014713,69,40,25,35,'Maana nilikuwa na njaa nanyi mkanipa chakula; nilikuwa na kiu nanyi mkanipa maji; nilikuwa mgeni nanyi mkanikaribisha;'),
(2014714,69,40,25,36,'nilikuwa uchi, mkanivika; nilikuwa mgonjwa nanyi mkaja kunitazama; nilikuwa gerezani nanyi mkaja kunitembelea.`'),
(2014715,69,40,25,37,'Hapo, hao watu wema watamjibu mfalme `Bwana, ni lini tulikuona mwenye njaa nasi tukakupa chakula, au ukiwa na kiu nasi tukakunywesha maji?'),
(2014716,69,40,25,38,'Ni lini tulikuona ukiwa mgeni nasi tukakukaribisha, au bila nguo nasi tukakuvika?'),
(2014717,69,40,25,39,'Ni lini tulikuona ukiwa mgonjwa au mfungwa nasi tukaja kukutazama?`'),
(2014718,69,40,25,40,'Mfalme atawajibu, `Kweli nawaambieni, kila kitu mlichomtendea mmojawapo wa hawa ndugu zangu wadogo, mlinitendea mimi.`'),
(2014719,69,40,25,41,'"Kisha atawaambia wale walio upande wake wa kushoto, `Ondokeni mbele yangu enyi mliolaaniwa! Nendeni katika moto wa milele aliotayarishiwa Ibilisi na malaika wake.'),
(2014720,69,40,25,42,'Maana nilikuwa na njaa nanyi hamkunipa chakula; nilikuwa na kiu nanyi hamkunipa maji.'),
(2014721,69,40,25,43,'Nilikuwa mgeni nanyi hamkunikaribisha; nilikuwa mgonjwa na mfungwa nanyi hamkuja kunitazama.`'),
(2014722,69,40,25,44,'"Hapo nao watajibu, `Bwana, ni lini tulikuona ukiwa na njaa au kiu, ukiwa mgeni au bila nguo, ukiwa mgonjwa au mfungwa, nasi hatukuja kukuhudumia?`'),
(2014723,69,40,25,45,'Naye atawajibu, `Nawaambieni kweli, kila mlipokataa kumtendea mambo haya mmojawapo wa hawa wadogo, mlikataa kunitendea mimi.`'),
(2014724,69,40,25,46,'Basi, hawa watakwenda kwenye adhabu ya milele, lakini wale waadilifu watakwenda kwenye uzima wa milele."'),
(2014725,69,40,26,1,'Yesu alipomaliza kusema hayo yote, aliwaambia wanafunzi wake,'),
(2014726,69,40,26,2,'"Mnajua kwamba baada ya siku mbili tutakuwa na sikukuu ya Pasaka, na Mwana wa Mtu atatolewa ili asulubiwe."'),
(2014727,69,40,26,3,'Wakati huo makuhani wakuu na wazee wa watu walikutana pamoja katika ukumbi wa Kayafa, Kuhani Mkuu.'),
(2014728,69,40,26,4,'Wakashauriana jinsi ya kumtia Yesu nguvuni kwa hila wamuue.'),
(2014729,69,40,26,5,'Lakini wakaamua jambo hilo lisifanyike wakati wa sikukuu, kusije kukatokea ghasia kati ya watu.'),
(2014730,69,40,26,6,'Yesu alipokuwa Bethania, nyumbani kwa Simoni, aitwaye Mkoma,'),
(2014731,69,40,26,7,'mama mmoja aliyekuwa na chupa ya alabasta yenye marashi ya thamani kubwa, alimjia pale mezani alipokuwa amekaa kula chakula, akammiminia hayo marashi kichwani.'),
(2014732,69,40,26,8,'Wanafunzi wake walipoona hayo wakakasirika, wakasema, "Ya nini hasara hii?'),
(2014733,69,40,26,9,'Marashi haya yangaliweza kuuzwa kwa bei kubwa, maskini wakapewa hizo fedha."'),
(2014734,69,40,26,10,'Yesu alitambua mawazo yao, akawaambia, "Mbona mnamsumbua huyu mama? Yeye amenitendea jambo jema.'),
(2014735,69,40,26,11,'Maskini mnao daima pamoja nanyi, lakini mimi sitakuwapo pamoja nanyi daima.'),
(2014736,69,40,26,12,'Huyu mama amenimiminia marashi ili kunitayarisha kwa maziko.'),
(2014737,69,40,26,13,'Nawaambieni kweli, popote ambapo hii Habari Njema itahubiriwa ulimwenguni, kitendo hiki alichofanya mama huyu kitatajwa kwa kumkumbuka yeye."'),
(2014738,69,40,26,14,'Kisha, Yuda Iskarioti, mmoja wa wale kumi na wawili, akaenda kwa makuhani wakuu,'),
(2014739,69,40,26,15,'akawaambia, "Mtanipa kitu gani kama nikimkabidhi Yesu kwenu?" Wakamhesabia sarafu thelathini za fedha;'),
(2014740,69,40,26,16,'na tangu wakati huo Yuda akawa anatafuta nafasi ya kumsaliti.'),
(2014741,69,40,26,17,'Siku ya kwanza kabla ya Sikukuu ya Mikate Isiyotiwa Chachu, wanafunzi walimwendea Yesu wakamwuliza, "Unataka tukuandalie wapi chakula cha Pasaka?"'),
(2014742,69,40,26,18,'Yeye akawajibu, "Nendeni mjini kwa mtu fulani, mkamwambie: `Mwalimu anasema, wakati wangu umefika; kwako nitakula Pasaka pamoja na wanafunzi wangu."`'),
(2014743,69,40,26,19,'Wanafunzi wakafanya kama Yesu alivyowaagiza, wakaandaa Pasaka.'),
(2014744,69,40,26,20,'Kulipokuwa jioni, Yesu akakaa mezani pamoja na wanafunzi wake kumi na wawili.'),
(2014745,69,40,26,21,'Walipokuwa wakila, Yesu akasema, "Nawaambieni kweli, mmoja wenu atanisaliti."'),
(2014746,69,40,26,22,'Wanafunzi wakahuzunika sana, wakaanza kuuliza mmojammoja, "Bwana! Je, ni mimi?"'),
(2014747,69,40,26,23,'Yesu akajibu, "Atakayechovya mkate pamoja nami katika bakuli ndiye atakayenisaliti.*fm*'),
(2014748,69,40,26,24,'Naam, Mwana wa Mtu anakwenda zake kama Maandiko Matakatifu yasemavyo, lakini ole wake mtu yule atakayemsaliti Mwana wa Mtu! Ingalikuwa afadhali kwa mtu huyo kama hangalizaliwa."'),
(2014749,69,40,26,25,'Yuda, ambaye ndiye aliyetaka kumsaliti, akamwuliza, "Mwalimu! Je, ni mimi?" Yesu akamjibu, "Wewe umesema."'),
(2014750,69,40,26,26,'Walipokuwa wanakula, Yesu akatwaa mkate, akashukuru, akaumega, akawapa wanafunzi wake akisema, "Twaeni mle; huu ni mwili wangu."'),
(2014751,69,40,26,27,'Kisha akatwaa kikombe, akamshukuru Mungu, akawapa akisema, "Nyweni nyote;'),
(2014752,69,40,26,28,'maana hii ni damu yangu inayothibitisha agano,*fn* damu inayomwagwa kwa ajili ya watu wengi ili kuwaondolea dhambi.'),
(2014753,69,40,26,29,'Nawaambieni, sitakunywa tena divai ya zabibu mpaka siku ile nitakapoinywa mpya pamoja nanyi katika Ufalme wa Baba yangu."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014754,69,40,26,30,'Baada ya kuimba wimbo, wakaondoka, wakaenda katika mlima wa Mizeituni.'),
(2014755,69,40,26,31,'Kisha Yesu akawaambia, "Usiku huu wa leo, ninyi nyote mtakuwa na mashaka nami, maana Maandiko Matakatifu yasema: `Nitampiga mchungaji, na kondoo wa kundi watatawanyika.`'),
(2014756,69,40,26,32,'Lakini baada ya kufufuka kwangu, nitawatangulieni Galilaya."'),
(2014757,69,40,26,33,'Petro akamwambia Yesu "Hata kama wote watakuwa na mashaka nawe na kukuacha, mimi sitakuacha kamwe."'),
(2014758,69,40,26,34,'Yesu akamwambia, "Kweli nakwambia, usiku huu kabla jogoo hajawika, utanikana mara tatu."'),
(2014759,69,40,26,35,'Petro akamwambia, "Hata kama ni lazima nife pamoja nawe, sitakukana kamwe." Wale wanafunzi wengine wote wakasema vivyo hivyo.'),
(2014760,69,40,26,36,'Kisha Yesu akaenda pamoja nao bustanini Gethsemane, akawaambia wanafunzi wake, "Kaeni hapa nami niende pale mbele kusali."'),
(2014761,69,40,26,37,'Akawachukua Petro na wana wawili wa Zebedayo, akaanza kuwa na huzuni na mahangaiko.'),
(2014762,69,40,26,38,'Hapo akawaambia, "Nina huzuni kubwa moyoni hata karibu kufa. Kaeni hapa mkeshe pamoja nami."'),
(2014763,69,40,26,39,'Basi, akaenda mbele kidogo, akaanguka kifudifudi, akasali: "Baba yangu, kama inawezekana, aacha kikombe*fo* hiki cha mateso kinipite; lakini isiwe nitakavyo mimi, ila utakavyo wewe."'),
(2014764,69,40,26,40,'Akawaendea wale wanafunzi, akawakuta wamelala. Akamwambia Petro, "Ndiyo kusema hamkuweza kukesha pamoja nami hata saa moja?'),
(2014765,69,40,26,41,'Kesheni na kusali ili msije mkaingia katika majaribu. Roho i tayari lakini mwili ni dhaifu."'),
(2014766,69,40,26,42,'Akaenda tena mara ya pili akasali: "Baba yangu, kama haiwezekani kikombe*fp* hiki kinipite bila mimi kukinywa, basi, mapenzi yako yafanyike."'),
(2014767,69,40,26,43,'Akawaendea tena, akawakuta wamelala, maana macho yao yalikuwa yamebanwa na usingizi.'),
(2014768,69,40,26,44,'Basi, akawaacha, akaenda tena kusali mara ya tatu kwa maneno yaleyale.'),
(2014769,69,40,26,45,'Kisha akawaendea wale wanafunzi, akawaambia, "Je, mngali mmelala na kupumzika? Tazameni! Saa yenyewe imefika, na Mwana wa Mtu atatolewa kwa watu wenye dhambi.'),
(2014770,69,40,26,46,'Amkeni, twendeni zetu. Tazameni! Anakuja yule atakayenisaliti."'),
(2014771,69,40,26,47,'Basi, Yesu alipokuwa bado anasema nao, mara akaja Yuda, mmoja wa wale kumi na wawili. Pamoja naye walikuja watu wengi wenye mapanga na marungu ambao walitumwa na makuhani wakuu na wazee wa watu.'),
(2014772,69,40,26,48,'Huyo aliyetaka kumsaliti Yesu, alikuwa amekwisha wapa ishara akisema: "Yule nitakayembusu ndiye; mkamateni."'),
(2014773,69,40,26,49,'Basi, Yuda akamkaribia Yesu, akamwambia, "Shikamoo, Mwalimu!" Kisha akambusu.'),
(2014774,69,40,26,50,'Yesu akamwambia, "Rafiki, fanya ulichokuja kufanya." Hapo wale watu wakaja, wakamkamata Yesu, wakamtia nguvuni.'),
(2014775,69,40,26,51,'Mmoja wa wale waliokuwa pamoja na Yesu akanyosha mkono, akauchomoa upanga wake, akampiga mtumishi wa Kuhani Mkuu, akamkata sikio.'),
(2014776,69,40,26,52,'Hapo Yesu akamwambia, "Rudisha upanga wako alani, maana yeyote anayeutumia upanga, atakufa kwa upanga.'),
(2014777,69,40,26,53,'Je, hamjui kwamba ningeweza kumwomba Baba yangu naye mara angeniletea zaidi ya majeshi kumi na mawili ya malaika?'),
(2014778,69,40,26,54,'Lakini yatatimiaje Maandiko Matakatifu yasemayo kwamba ndivyo inavyopaswa kuwa?"'),
(2014779,69,40,26,55,'Wakati huohuo Yesu akauambia huo umati wa watu waliokuja kumtia nguvuni, "Je, mmekuja kunikamata kwa mapanga na marungu kama kwamba mimi ni mnyang`anyi? Kila siku nilikuwa Hekaluni nikifundisha, na hamkunikamata!'),
(2014780,69,40,26,56,'Lakini haya yote yametendeka ili Maandiko ya manabii yatimie." Kisha wanafunzi wote wakamwacha, wakakimbia.'),
(2014781,69,40,26,57,'Basi, hao watu waliomkamata Yesu walimpeleka nyumbani kwa Kayafa, Kuhani Mkuu, walikokusanyika walimu wa Sheria na wazee.'),
(2014782,69,40,26,58,'Petro alimfuata kwa mbali mpaka uani kwa Kuhani Mkuu, akaingia ndani pamoja na walinzi ili apate kuona mambo yatakavyokuwa.'),
(2014783,69,40,26,59,'Basi, makuhani wakuu na Baraza lote wakatafuta ushahidi wa uongo dhidi ya Yesu wapate kumwua,'),
(2014784,69,40,26,60,'lakini hawakupata ushahidi wowote, ingawa walikuja mashahidi wengi wa uongo. Mwishowe wakaja mashahidi wawili,'),
(2014785,69,40,26,61,'wakasema, "Mtu huyu alisema: `Ninaweza kuliharibu Hekalu la Mungu na kulijenga tena kwa siku tatu."`'),
(2014786,69,40,26,62,'Kuhani Mkuu akasimama, akamwuliza Yesu, "Je, hujibu neno? Watu hawa wanashuhudia nini dhidi yako?"'),
(2014787,69,40,26,63,'Lakini Yesu akakaa kimya. Kuhani Mkuu akamwambia, "Nakuapisha kwa Mungu aliye hai, twambie kama wewe ndiwe Kristo, Mwana wa Mungu!"'),
(2014788,69,40,26,64,'Yesu akamwambia, "Wewe umesema! Lakini nawaambieni, tangu sasa mtamwona Mwana wa Mtu ameketi upande wa kulia wa Mwenyezi, akija juu ya mawingu ya mbinguni."'),
(2014789,69,40,26,65,'Hapo, Kuhani Mkuu akararua mavazi yake, akasema, "Amekufuru! Tuna haja gani tena ya mashahidi? Sasa mmesikia kufuru yake.'),
(2014790,69,40,26,66,'Ninyi mwaonaje?" Wao wakamjibu, "Anastahili kufa!"'),
(2014791,69,40,26,67,'Kisha wakamtemea mate usoni, wakampiga makofi. Wengine wakiwa wanampiga makofi,'),
(2014792,69,40,26,68,'wakasema, "Haya Kristo, tutabirie; ni nani amekupiga!"'),
(2014793,69,40,26,69,'Petro alikuwa ameketi nje uani. Basi, mtumishi mmoja wa kike akamwendea, akasema, "Wewe ulikuwa pamoja na Yesu wa Galilaya."'),
(2014794,69,40,26,70,'Petro akakana mbele ya wote akisema, "Sijui hata unasema nini."'),
(2014795,69,40,26,71,'Alipokuwa akitoka mlangoni, mtumishi mwingine wa kike akamwona, akawaambia wale waliokuwa pale, "Mtu huyu alikuwa pamoja na Yesu wa Nazareti."'),
(2014796,69,40,26,72,'Petro akakana tena kwa kiapo: "Simjui mtu huyo."'),
(2014797,69,40,26,73,'Baadaye kidogo, watu waliokuwa pale wakamwendea Petro, wakamwambia, "Hakika, wewe pia ni mmoja wao, maana msemo wako unakutambulisha."'),
(2014798,69,40,26,74,'Hapo Petro akaanza kujilaani na kuapa akisema, "Simjui mtu huyo!" Mara jogoo akawika.'),
(2014799,69,40,26,75,'Petro akakumbuka maneno aliyoambiwa na Yesu: "Kabla jogoo hajawika, utanikana mara tatu." Basi, akatoka nje akalia sana.'),
(2014800,69,40,27,1,'Kulipopambazuka, makuhani wakuu wote na wazee wa watu walifanya mashauri juu ya Yesu wapate kumwua.'),
(2014801,69,40,27,2,'Wakamfunga pingu, wakamchukua, wakamkabidhi kwa Pilato, mkuu wa mkoa.'),
(2014802,69,40,27,3,'Hapo, Yuda ambaye ndiye aliyemsaliti, alipoona kwamba wamekwisha mhukumu Yesu, akajuta, akawarudishia makuhani wakuu zile sarafu thelathini za fedha.'),
(2014803,69,40,27,4,'Akawaambia, "Nimekosa kwa kumtoa mtu asiye na hatia auawe." Lakini wao wakasema, "Yatuhusu nini sisi? Hilo ni shauri lako."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014804,69,40,27,5,'Naye akazitupa zile fedha Hekaluni, akatoka nje, akaenda akajinyonga.'),
(2014805,69,40,27,6,'Makuhani wakuu wakazichukua zile fedha, wakasema, "Haifai kuziweka katika hazina ya Hekalu kwa maana ni fedha za damu."'),
(2014806,69,40,27,7,'Basi, wakashauriana, wakazitumia kununua shamba la mfinyanzi liwe mahali pa kuzika wageni.'),
(2014807,69,40,27,8,'Ndiyo maana mpaka leo shamba hilo linaitwa Shamba la Damu.'),
(2014808,69,40,27,9,'Hivyo maneno ya nabii Yeremia yakatimia: "Walizichukua sarafu thelathini za fedha, thamani ya yule ambaye watu wa Israeli walipanga bei,'),
(2014809,69,40,27,10,'wakanunua nazo shamba la mfinyanzi, kama Bwana alivyoniagiza."'),
(2014810,69,40,27,11,'Yesu alisimamishwa mbele ya mkuu wa mkoa. Basi, mkuu wa mkoa akamwuliza, "Je, wewe ndiwe Mfalme wa Wayahudi?" Yesu akamwambia, "Wewe umesema."'),
(2014811,69,40,27,12,'Lakini makuhani wakuu na wazee walipokuwa wanamshtaki, hakujibu neno.'),
(2014812,69,40,27,13,'Hivyo Pilato akamwuliza, "Je, husikii mashtaka hayo yote wanayotoa juu yako?"'),
(2014813,69,40,27,14,'Lakini Yesu hakumjibu hata neno moja; hata huyo mkuu wa mkoa akashangaa sana.'),
(2014814,69,40,27,15,'Ilikuwa kawaida wakati wa Sikukuu ya Pasaka mkuu wa mkoa kuwafungulia Wayahudi mfungwa mmoja waliyemtaka.'),
(2014815,69,40,27,16,'Wakati huo kulikuwa na mfungwa mmoja, jina lake Baraba.'),
(2014816,69,40,27,17,'Hivyo, watu walipokusanyika pamoja, Pilato akawauliza, "Mwataka nimfungue yupi kati ya wawili hawa, Baraba*fq* ama Yesu aitwae Kristo?"'),
(2014817,69,40,27,18,'Alisema hivyo maana alijua wazi kwamba walimleta kwake kwa sababu ya wivu.'),
(2014818,69,40,27,19,'Pilato alipokuwa amekaa katika kiti cha hukumu, mke wake akampelekea ujumbe: "Usijitie katika shauri la mtu huyu mwema, maana leo nimeteseka sana katika ndoto kwa sababu yake."'),
(2014819,69,40,27,20,'Lakini makuhani wakuu na wazee wakawashawishi watu waombe Baraba afunguliwe na Yesu auawe.'),
(2014820,69,40,27,21,'Mkuu wa mkoa akawauliza, "Ni yupi kati ya hawa wawili mnayetaka nimfungue?" Wakamjibu, "Baraba!"'),
(2014821,69,40,27,22,'Pilato akawauliza, "Sasa, nifanye nini na Yesu aitwaye Kristo?" Wote wakasema, "Asulubiwe!"'),
(2014822,69,40,27,23,'Pilato akauliza, "Kwa nini? Amefanya kosa gani?" Wao wakazidi kupaaza sauti: "Asulubiwe!"'),
(2014823,69,40,27,24,'Basi, Pilato alipotambua kwamba hafanikiwi chochote na kwamba maasi yalikuwa yanaanza, alichukua maji, akanawa mikono mbele ya ule umati wa watu, akasema, "Mimi sina lawama juu ya kifo cha mtu huyu; shauri lenu wenyewe."'),
(2014824,69,40,27,25,'Watu wote wakasema, "Damu yake na iwe juu yetu na juu ya watoto wetu!"'),
(2014825,69,40,27,26,'Hapo Pilato akawafungulia Baraba kutoka gerezani, lakini akamtoa Yesu asulubiwe.'),
(2014826,69,40,27,27,'Kisha askari wa mkuu wa mkoa wakamwingiza Yesu ndani ya ikulu, wakamkusanyikia kikosi kizima.'),
(2014827,69,40,27,28,'Wakamvua nguo zake, wakamvika joho la rangi nyekundu.'),
(2014828,69,40,27,29,'Kisha wakasokota taji ya miiba, wakamvika kichwani, wakamwekea pia mwanzi katika mkono wake wa kulia. Wakapiga magoti mbele yake, wakamdhihaki wakisema, "Shikamoo mfalme wa Wayahudi!"'),
(2014829,69,40,27,30,'Wakamtemea mate, wakauchukua ule mwanzi, wakampiga nao kichwani.'),
(2014830,69,40,27,31,'Baada ya kumdhihaki, wakamvua lile joho, wakamvika nguo zake, kisha wakampeleka kumsulubisha.'),
(2014831,69,40,27,32,'Walipokuwa wakienda, wakamkuta mtu mmoja jina lake Simoni, mwenyeji wa Kurene, wakamlazimisha kuuchukua msalaba wake Yesu.'),
(2014832,69,40,27,33,'Walipofika mahali paitwapo Golgotha, maana yake, "Mahali pa Fuvu la kichwa,"'),
(2014833,69,40,27,34,'wakampa mchanganyiko wa divai na nyongo. Lakini Yesu alipoonja akakataa kunywa.'),
(2014834,69,40,27,35,'Walimsulubisha, kisha wakagawana mavazi yake kwa kuyapigia kura.'),
(2014835,69,40,27,36,'Wakaketi, wakawa wanamchunga.'),
(2014836,69,40,27,37,'Juu ya kichwa chake wakaweka shtaka dhidi yake lilioandikwa, "Huyu ni Yesu, Mfalme wa Wayahudi."'),
(2014837,69,40,27,38,'Wanyang`anyi wawili walisulubishwa pia pamoja naye, mmoja upande wa kushoto na mwingine upande wa kulia.'),
(2014838,69,40,27,39,'Watu waliokuwa wanapita mahali hapo walimtukana wakitikisa vichwa vyao na kusema,'),
(2014839,69,40,27,40,'"Wewe! Si ulijidai kulivunja Hekalu na kulijenga kwa siku tatu? Sasa jiokoe mwenyewe. Kama wewe ni Mwana wa Mungu, basi shuka msalabani!"'),
(2014840,69,40,27,41,'Hali kadhalika na makuhani wakuu pamoja na walimu wa Sheria na wazee walimdhihaki wakisema,'),
(2014841,69,40,27,42,'"Aliwaokoa wengine, lakini kujiokoa mwenyewe hawezi! Eti yeye ni mfalme wa Wayahudi! Basi, sasa na ashuke msalabani, nasi tutamwamini.'),
(2014842,69,40,27,43,'Alimtumainia Mungu na kusema eti yeye ni Mwana wa Mungu; basi, Mungu na amwokoe kama anamtaka."'),
(2014843,69,40,27,44,'Hali kadhalika na wale waliosulubiwa pamoja naye wakamtukana.'),
(2014844,69,40,27,45,'Tangu saa sita mchana mpaka saa tisa, nchi yote ikawa katika giza.'),
(2014845,69,40,27,46,'Mnamo saa tisa Yesu akalia kwa sauti kubwa, "Eli, Eli, lema sabakthani?" Maana yake, "Mungu wangu, Mungu wangu, mbona umeniacha?"'),
(2014846,69,40,27,47,'Lakini wale waliosimama pale waliposikia hivyo wakasema, "Anamwita Eliya."'),
(2014847,69,40,27,48,'Mmoja wao akakimbia, akachukua sifongo, akaichovya katika siki, akaiweka juu ya mwanzi, akampa anywe.'),
(2014848,69,40,27,49,'Wengine wakasema, "Acha tuone kama Eliya anakuja kumwokoa."'),
(2014849,69,40,27,50,'Basi, Yesu akalia tena kwa sauti kubwa, akakata roho.'),
(2014850,69,40,27,51,'Hapo pazia la Hekalu likapasuka vipande viwili, toka juu mpaka chini; nchi ikatetemeka; miamba ikapasuka;'),
(2014851,69,40,27,52,'makaburi yakafunguka na watu wengi wa Mungu waliokufa wakafufuliwa;'),
(2014852,69,40,27,53,'nao, baada ya kufufuka kwake, wakatoka makaburini, wakaingia katika Mji Mtakatifu, wakaonekana na watu wengi.'),
(2014853,69,40,27,54,'Basi, jemadari na wale waliokuwa wakimlinda Yesu walipoona tetemeko la ardhi na yale mambo yaliyotukia, wakaogopa sana, wakasema, "Hakika mtu huyu alikuwa Mwana wa Mungu."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014854,69,40,27,55,'Mahali hapo walikuwapo wanawake wengi wakitazama kwa mbali. Hao ndio wale waliomfuata Yesu kutoka Galilaya wakimtumikia.'),
(2014855,69,40,27,56,'Miongoni mwao walikuwa Maria Magdalene, Maria mama yao Yakobo na Yosefu, pamoja na mama yao wana wa Zebedayo.'),
(2014856,69,40,27,57,'Ilipokuwa jioni, akaja mtu mmoja tajiri mwenyeji wa Armathaya, jina lake Yosefu. Yeye pia alikuwa mwanafunzi wa Yesu.'),
(2014857,69,40,27,58,'Akamwendea Pilato, akaomba apewe mwili wa Yesu. Basi, Pilato akaamuru apewe.'),
(2014858,69,40,27,59,'Yosefu akauchukua ule mwili akauzungushia sanda safi ya kitani,'),
(2014859,69,40,27,60,'akauweka ndani ya kaburi lake jipya alilokuwa amelichonga katika mwamba. Kisha akavingirisha jiwe kubwa mbele ya mlango wa kaburi, akaenda zake.'),
(2014860,69,40,27,61,'Maria Magdalene na yule Maria mwingine walikuwa wameketi kulielekea kaburi.'),
(2014861,69,40,27,62,'Kesho yake, yaani siku iliyofuata ile ya Maandalio, makuhani wakuu na Mafarisayo walimwendea Pilato,'),
(2014862,69,40,27,63,'Wakasema, "Mheshimiwa, tunakumbuka kwamba yule mdanganyifu alisema kabla ya kufa ati, `Baada ya siku tatu nitafufuka.`'),
(2014863,69,40,27,64,'Kwa hiyo amuru kaburi lilindwe mpaka siku ya tatu ili wanafunzi wake wasije wakamwiba na kuwaambia watu kwamba amefufuka. Uongo huu wa mwisho utakuwa mbaya kuliko ule wa awali."'),
(2014864,69,40,27,65,'Pilato akawaambia, "Haya, mnao walinzi; nendeni mkalinde kadiri mjuavyo."'),
(2014865,69,40,27,66,'Basi, wakaenda, wakalilinda kaburi, wakatia mhuri juu ya lile jiwe na kuacha hapo askari walinzi.'),
(2014866,69,40,28,1,'Baada ya Sabato, karibu na mapambazuko ya siku ile ya Jumapili, Maria Magdalene na yule Maria mwingine walikwenda kutazama lile kaburi.'),
(2014867,69,40,28,2,'Ghafla kutatokea tetemeko kubwa la nchi; malaika wa Bwana alishuka kutoka mbinguni, akalivingirisha lile jiwe, akalikalia.'),
(2014868,69,40,28,3,'Alionekana kama umeme na mavazi yake yalikuwa meupe kama theluji.'),
(2014869,69,40,28,4,'Walinzi wa lile kaburi wakatetemeka kwa hofu kubwa, hata wakawa kama wamekufa.'),
(2014870,69,40,28,5,'Lakini yule malaika akawaambia wale wanawake, "Ninyi msiogope! Najua kwamba mnamtafuta Yesu aliyesulubiwa.'),
(2014871,69,40,28,6,'Hayupo hapa maana amefufuka kama alivyosema. Njoni mkaone mahali alipokuwa amelala.'),
(2014872,69,40,28,7,'Basi, nendeni upesi mkawaambie wanafunzi wake kwamba amefufuka kutoka wafu, na sasa anawatangulieni kule Galilaya; huko mtamwona. Haya, mimi nimekwisha waambieni."'),
(2014873,69,40,28,8,'Wakiwa wenye hofu na furaha kubwa, hao wanawake walitoka upesi kaburini, wakakimbia kwenda kuwaambia wanafunzi wake.'),
(2014874,69,40,28,9,'Mara, Yesu akakutana nao, akawasalimu: "Salamu." Hao wanawake wakamwendea, wakapiga magoti mbele yake, wakashika miguu yake.'),
(2014875,69,40,28,10,'Kisha Yesu akawaambia, "Msiogope! Nendeni mkawaambie ndugu zangu waende Galilaya, na huko wataniona."'),
(2014876,69,40,28,11,'Wale wanawake walipokuwa wanakwenda zao, baadhi ya walinzi wa lile kaburi walikwenda mjini kutoa taarifa kwa makuhani wakuu juu ya mambo yote yaliyotukia.'),
(2014877,69,40,28,12,'Basi, wakakutana pamoja na wazee, na baada ya kushauriana, wakawapa wale askari kiasi kikubwa cha fedha'),
(2014878,69,40,28,13,'wakisema, "Ninyi mtasema hivi: `Wanafunzi wake walikuja usiku, wakamwiba sisi tukiwa tumelala.`'),
(2014879,69,40,28,14,'Na kama mkuu wa mkoa akijua jambo hili, sisi tutasema naye na kuhakikisha kuwa ninyi hamtapata matatizo."'),
(2014880,69,40,28,15,'Wale walinzi wakazichukua zile fedha, wakafanya kama walivyofundishwa. Habari hiyo imeenea kati ya Wayahudi mpaka leo.'),
(2014881,69,40,28,16,'Wale wanafunzi kumi na mmoja walikwenda Galilaya kwenye ule mlima aliowaagiza Yesu.'),
(2014882,69,40,28,17,'Walipomwona, wakamwabudu, ingawa wengine walikuwa na mashaka.'),
(2014883,69,40,28,18,'Yesu akaja karibu, akawaambia, "Nimepewa mamlaka yote mbinguni na duniani.'),
(2014884,69,40,28,19,'Nendeni basi, mkawafanye watu wa mataifa yote wawe wanafunzi wangu; mkiwabatiza kwa jina la Baba, na la Mwana, na la Roho Mtakatifu.'),
(2014885,69,40,28,20,'Wafundisheni kushika maagizo yote niliyowapeni. Nami nipo pamoja nanyi siku zote; naam, mpaka mwisho wa nyakati."'),
(2014886,69,41,1,1,'Habari Njema ya Yesu Kristo, Mwana wa Mungu.*fa*'),
(2014887,69,41,1,2,'Ilianza kama ilivyoandikwa katika kitabu cha nabii Isaya: "Tazama, namtuma mjumbe wangu akutangulie; yeye atakutayarishia njia yako.'),
(2014888,69,41,1,3,'Sauti ya mtu imesikika jangwani: `Mtayarishieni Bwana njia yake, nyoosheni mapito yake."`'),
(2014889,69,41,1,4,'Yohane Mbatizaji alitokea jangwani, akahubiri kwamba ni lazima watu watubu na kubatizwa ili Mungu awasamehe dhambi zao.'),
(2014890,69,41,1,5,'Watu kutoka sehemu zote za Yudea na wenyeji wote wa Yerusalemu walimwendea, wakaziungama dhambi zao, naye akawabatiza katika mto Yordani.'),
(2014891,69,41,1,6,'Yohane alikuwa amevaa vazi lililofumwa kwa manyoya ya ngamia, na mkanda wa ngozi kiunoni mwake. Chakula chake kilikuwa nzige na asali ya mwituni.'),
(2014892,69,41,1,7,'Naye alihubiri akisema, "Baada yangu anakuja mwenye uwezo zaidi kuliko mimi, ambaye mimi sistahili hata kuinama na kufungua kamba za viatu vyake.'),
(2014893,69,41,1,8,'Mimi ninawabatiza kwa maji, lakini yeye atawabatiza kwa Roho Mtakatifu."'),
(2014894,69,41,1,9,'Siku hizo, Yesu alifika kutoka Nazareti, mji wa Galilaya, akabatizwa na Yohane katika mto Yordani.'),
(2014895,69,41,1,10,'Mara tu alipotoka majini, aliona mbingu zimefunguliwa, na Roho akishuka juu yake kama njiwa.'),
(2014896,69,41,1,11,'Sauti ikasikika kutoka mbinguni: "Wewe ni Mwanangu mpendwa, nimependezwa nawe."'),
(2014897,69,41,1,12,'Mara akaongozwa na Roho kwenda jangwani,'),
(2014898,69,41,1,13,'akakaa huko siku arubaini akijaribiwa na Shetani. Alikuwa huko pamoja na wanyama wa porini, nao malaika wakawa wanamtumikia.'),
(2014899,69,41,1,14,'Yohane alipokwisha fungwa gerezani, Yesu alikwenda Galilaya, akahubiri Habari Njema ya Mungu, akisema,'),
(2014900,69,41,1,15,'"Wakati umetimia, na Ufalme wa Mungu umekaribia. Tubuni na kuiamini Habari Njema!"'),
(2014901,69,41,1,16,'Alipokuwa anapita kando ya ziwa Galilaya, aliwaona wavuvi wawili: Simoni na Andrea ndugu yake wakivua samaki kwa wavu.'),
(2014902,69,41,1,17,'Yesu akawaambia, "Nifuateni nami nitawafanya ninyi wavuvi wa watu."'),
(2014903,69,41,1,18,'Mara wakaziacha nyavu zao, wakamfuata.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014904,69,41,1,19,'Alipokwenda mbele kidogo, aliwaona Yakobo na Yohane, wana wa Zebedayo. Nao pia walikuwa ndani ya mashua yao wakizitengeneza nyavu zao.'),
(2014905,69,41,1,20,'Yesu akawaita mara, nao wakamwacha baba yao Zebedayo katika mashua pamoja na wafanyakazi, wakamfuata.'),
(2014906,69,41,1,21,'Wakafika mjini Kafarnaumu, na mara ilipofika Sabato, Yesu akaingia katika Sunagogi, akaanza kufundisha.'),
(2014907,69,41,1,22,'Watu wote waliomsikia walishangazwa na mafundisho yake, maana hakuwa anafundisha kama walimu wao wa Sheria, bali kama mtu mwenye mamlaka.'),
(2014908,69,41,1,23,'Mara akatokea mle ndani ya sunagogi mtu mmoja mwenye pepo mchafu,'),
(2014909,69,41,1,24,'akapaaza sauti, "Una nini nasi, wewe Yesu wa Nazareti? Je, umekuja kutuangamiza? Najua wewe ni nani: wewe ni Mtakatifu wa Mungu!"'),
(2014910,69,41,1,25,'Yesu akamkemea, "Nyamaza! Mtoke mtu huyu."'),
(2014911,69,41,1,26,'Basi, huyo pepo mchafu akamtikisatikisa mtu huyo, kisha akalia kwa sauti kubwa, akamtoka.'),
(2014912,69,41,1,27,'Watu wote wakashangaa, wakaulizana, "Ni mambo gani haya? Je, ni mafundisho mapya? Mtu huyu anayo mamlaka ya kuamuru hata pepo wachafu, nao wanamtii!"'),
(2014913,69,41,1,28,'Habari za Yesu zikaenea upesi kila mahali katika wilaya ya Galilaya.'),
(2014914,69,41,1,29,'Wakatoka katika sunagogi, wakaenda moja kwa moja hadi nyumbani kwa Simoni na Andrea; Yakobo na Yohane walikwenda pamoja nao.'),
(2014915,69,41,1,30,'Basi, mama mmoja, mkwewe Simoni, alikuwa kitandani ana homa kali. Wakamwarifu Yesu mara alipowasili.'),
(2014916,69,41,1,31,'Yesu akamwendea huyo mama, akamshika mkono, akamwinua. Na ile homa ikamwacha, akaanza kuwatumikia.'),
(2014917,69,41,1,32,'Jioni, jua lilipokwisha tua, wakamletea Yesu wagonjwa wote na watu waliopagawa na pepo.'),
(2014918,69,41,1,33,'Watu wote wa mji ule wakakusanyika nje ya mlango.'),
(2014919,69,41,1,34,'Naye Yesu akawaponya watu wengi waliokuwa na magonjwa mbalimbali; aliwafukuza pepo wengi, lakini hakuwaruhusu kusema kitu maana walikuwa wanamjua yeye ni nani.'),
(2014920,69,41,1,35,'Kesho yake, kabla ya mapambazuko, Yesu alitoka, akaenda mahali pa faragha kusali.'),
(2014921,69,41,1,36,'Simoni na wenzake wakaenda kumtafuta.'),
(2014922,69,41,1,37,'Walipomwona wakamwambia, "Kila mtu anakutafuta."'),
(2014923,69,41,1,38,'Yesu akawaambia, "Twendeni katika miji mingine ya jirani nikahubiri huko pia, maana nimekuja kwa sababu hiyo."'),
(2014924,69,41,1,39,'Basi, akaenda kila mahali Galilaya akihubiri katika masunagogi na kufukuza pepo.'),
(2014925,69,41,1,40,'Mtu mmoja mwenye ukoma alimwendea Yesu, akapiga magoti, akamwomba, "Ukitaka, waweza kunitakasa!"'),
(2014926,69,41,1,41,'Yesu akamwonea huruma, akanyosha mkono wake, akamgusa na kumwambia, "Nataka, takasika!"'),
(2014927,69,41,1,42,'Mara ukoma ukamwacha mtu huyo, akatakasika.'),
(2014928,69,41,1,43,'Kisha Yesu akamwambia aende zake upesi na kumwonya vikali,'),
(2014929,69,41,1,44,'"Usimwambie mtu yeyote jambo hili, ila nenda ukajionyeshe kwa kuhani; kisha utoe sadaka kwa ajili ya kutakasika kwako kama alivyoamuru Mose, iwe uthibitisho kwao kwamba umepona."'),
(2014930,69,41,1,45,'Lakini huyo mtu akaenda, akaanza kueneza habari hiyo kila mahali na kusema mambo mengi hata Yesu hakuweza tena kuingia katika mji wowote waziwazi; ikamlazimu kukaa nje, mahali pa faragha. Hata hivyo, watu wakamwendea kutoka kila upande.'),
(2014931,69,41,2,1,'Baada ya siku kadhaa, Yesu alirudi Kafarnaumu, watu wakapata habari kwamba alikuwa nyumbani.'),
(2014932,69,41,2,2,'Basi, wakaja watu wengi sana hata nafasi yoyote ikakosekana mlangoni. Yesu alikuwa akiwahubiria ujumbe wake,'),
(2014933,69,41,2,3,'wakati mtu mmoja aliyepooza alipoletwa kwake akiwa amechukuliwa na watu wanne.'),
(2014934,69,41,2,4,'Kwa sababu ya huo umati wa watu, hawakuweza kumpeleka karibu na Yesu. Basi, wakatoboa sehemu ya dari iliyokuwa juu ya mahali alipokuwa Yesu. Walipokwisha pata nafasi, wakamteremsha huyo mtu akiwa amelala juu ya mkeka.'),
(2014935,69,41,2,5,'Yesu alipoona imani yao, akamwambia huyo mtu aliyepooza, "Mwanangu, umesamehewa dhambi zako."'),
(2014936,69,41,2,6,'Baadhi ya walimu wa Sheria waliokuwa wameketi hapo wakawaza mioyoni mwao,'),
(2014937,69,41,2,7,'"Anathubutuje kusema hivyo? Anamkufuru Mungu! Hakuna mtu awezaye kusamehe dhambi isipokuwa Mungu peke yake."'),
(2014938,69,41,2,8,'Yesu alitambua mara mawazo yao, akawaambia, "Mbona mnawaza hivyo mioyoni mwenu?'),
(2014939,69,41,2,9,'Ni lipi lililo rahisi zaidi: kumwambia mtu huyu aliyepooza, `Umesamehewa dhambi zako`, au kumwambia, `Inuka! Chukua mkeka wako utembee?`'),
(2014940,69,41,2,10,'Basi, nataka mjue kwamba Mwana wa Mtu anayo mamlaka ya kuwasamehe watu dhambi duniani." Hapo akamwambia huyo mtu aliyepooza,'),
(2014941,69,41,2,11,'"Nakwambia simama, chukua mkeka wako uende nyumbani!"'),
(2014942,69,41,2,12,'Mara, watu wote wakiwa wanamtazama, huyo mtu akainuka, akauchukua mkeka wake, akaenda zake. Watu wote wakashangaa na kumtukuza Mungu wakisema, "Hatujapata kamwe kuona jambo kama hili."'),
(2014943,69,41,2,13,'Yesu alikwenda tena kando ya ziwa. Umati wa watu ukamwendea, naye akaanza kuwafundisha.'),
(2014944,69,41,2,14,'Alipokuwa akipita, akamwona Lawi mwana wa Alfayo, ameketi katika ofisi ya ushuru. Yesu akamwambia, "Nifuate!" Lawi akasimama, akamfuata.'),
(2014945,69,41,2,15,'Baadaye, Yesu alikuwa amekaa mezani, nyumbani kwa Lawi, kula chakula. Watoza ushuru wengi na wenye dhambi walikuwa wamemfuata Yesu na wengi wao wakawa wamekaa mezani pamoja naye na wanafunzi wake.'),
(2014946,69,41,2,16,'Basi, baadhi ya walimu wa Sheria ambao walikuwa Mafarisayo walipomwona Yesu akila pamoja na watu wenye dhambi na watoza ushuru, wakawauliza wanafunzi wake, "Kwa nini anakula pamoja na watoza ushuru na wenye dhambi?"'),
(2014947,69,41,2,17,'Yesu alipowasikia, akawaambia, "Watu wenye afya hawahitaji daktari; wanaomhitaji ni wale walio wagonjwa. Sikuja kuwaita watu wema, ila wenye dhambi."'),
(2014948,69,41,2,18,'Wakati mmoja wanafunzi wa Yohane na wanafunzi wa Mafarisayo walikuwa wanafunga. Basi, watu wakaja, wakamwuliza Yesu, "Kwa nini wanafunzi wa Yohane na wa Mafarisayo wanafunga, lakini wanafunzi wako hawafungi?"'),
(2014949,69,41,2,19,'Yesu akajibu, "Walioalikwa harusini wanawezaje kufunga kama bwana harusi yupo pamoja nao? Wakati wote wawapo pamoja na bwana harusi hawawezi kufunga.'),
(2014950,69,41,2,20,'Lakini wakati utafika ambapo bwana harusi ataondolewa kati yao; wakati huo ndipo watakapofunga.'),
(2014951,69,41,2,21,'"Hakuna mtu anayekata kiraka kutoka katika nguo mpya na kukishonea katika nguo kuukuu. Kama akifanya hivyo, hicho kiraka kipya kitararuka kutoka hilo vazi kuukuu, nalo litaharibika zaidi.'),
(2014952,69,41,2,22,'Wala hakuna mtu atiaye divai mpya katika viriba vikuukuu. Kama akifanya hivyo, divai itavipasua hivyo viriba, nayo divai pamoja na hivyo viriba vitaharibika. Divai mpya hutiwa katika viriba vipya!"'),
(2014953,69,41,2,23,'Siku moja ya Sabato, Yesu alikuwa anapita katika mashamba ya ngano. Walipokuwa wanatembea, wanafunzi wake wakaanza kukwanyua masuke ya ngano.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2014954,69,41,2,24,'Mafarisayo wakawaambia, "Tazama! Kwa nini wanafanya jambo ambalo si halali kufanya wakati wa Sabato?"'),
(2014955,69,41,2,25,'Yesu akawajibu, "Je, hamjapata kusoma juu ya kile alichofanya Daudi wakati alipohitaji chakula? Yeye pamoja na wenzake waliona njaa,'),
(2014956,69,41,2,26,'naye akaingia ndani ya Nyumba ya Mungu, akala ile mikate iliyowekwa mbele ya Mungu. Jambo hili lilifanyika wakati Abiathari alikuwa Kuhani Mkuu. Na ni makuhani tu peke yao waliokuwa wameruhusiwa kula mikate hiyo. Lakini Daudi aliila, tena akawapa na wenzake."'),
(2014957,69,41,2,27,'Basi, Yesu akawaambia, "Sabato iliwekwa kwa ajili ya binadamu na si binadamu kwa ajili ya Sabato!'),
(2014958,69,41,2,28,'Kwa hiyo, Mwana wa Mtu ni Bwana hata wa Sabato."'),
(2014959,69,41,3,1,'Yesu aliingia tena katika sunagogi na mle ndani mlikuwa na mtu aliyekuwa na mkono uliopooza.'),
(2014960,69,41,3,2,'Humo baadhi ya watu walimngojea amponye mtu huyo siku ya sabato ili wapate kumshtaki.'),
(2014961,69,41,3,3,'Yesu akamwambia huyo mtu aliyekuwa na mkono uliopooza, "Njoo hapa katikati."'),
(2014962,69,41,3,4,'Kisha, akawauliza, "Je, ni halali siku ya Sabato kutenda jambo jema au kutenda jambo baya; kuokoa maisha au kuua?" Lakini wao hawakusema neno.'),
(2014963,69,41,3,5,'Hapo akawatazama wote kwa hasira, akaona huzuni kwa sababu ya ugumu wa mioyo yao. Kisha akamwambia huyo mtu, "Nyosha mkono wako!" Naye akaunyosha mkono wake, ukawa mzima tena.'),
(2014964,69,41,3,6,'Mara Mafarisayo wakatoka nje, wakafanya shauri pamoja na watu wa kikundi cha Herode jinsi ya kumwangamiza Yesu.'),
(2014965,69,41,3,7,'Yesu aliondoka hapo pamoja na wanafunzi wake, akaenda kando ya ziwa, na umati wa watu ukamfuata. Watu hao walikuwa wametoka Yerusalemu, Yudea,'),
(2014966,69,41,3,8,'Idumea, ng`ambo ya mto Yordani, Tiro na Sidoni. Watu hao wengi walimwendea Yesu kwa sababu ya kusikia mambo mengi aliyokuwa ameyatenda.'),
(2014967,69,41,3,9,'Yesu akawaambia wanafunzi wake wamtayarishie mashua moja, ili umati wa watu usije ukamsonga.'),
(2014968,69,41,3,10,'Alikuwa amewaponya watu wengi, na wagonjwa wote wakawa wanamsonga ili wapate kumgusa.'),
(2014969,69,41,3,11,'Na watu waliokuwa wamepagawa na pepo wachafu walipomwona, walijitupa chini mbele yake na kupaaza sauti, "Wewe ni Mwana wa Mungu!"'),
(2014970,69,41,3,12,'Lakini Yesu akawaamuru kwa ukali wasimjulishe kwa watu.'),
(2014971,69,41,3,13,'Yesu alipanda kilimani, akawaita wale aliowataka. Basi, wakamwendea,'),
(2014972,69,41,3,14,'naye akawateua watu kumi na wawili ambao aliwaita mitume,*fb* wakae naye, awatume kuhubiri'),
(2014973,69,41,3,15,'na wawe na mamlaka ya kuwafukuza pepo.'),
(2014974,69,41,3,16,'Basi, hao kumi na wawili walioteuliwa ndio hawa: Simoni (ambaye Yesu alimpa jina, Petro),'),
(2014975,69,41,3,17,'Yakobo na Yohane, wana wa Zebedayo (Yesu aliwapa hawa ndugu wawili jina Boanerge, maana yake "wanangurumo"),'),
(2014976,69,41,3,18,'Andrea na Filipo, Batholomayo, Mathayo, Thoma, Yakobo mwana wa Alfayo, Thadayo, Simoni Mkanani na'),
(2014977,69,41,3,19,'Yuda Iskarioti ambaye alimsaliti Yesu.'),
(2014978,69,41,3,20,'Kisha Yesu alikwenda nyumbani. Umati wa watu ukakusanyika tena, hata Yesu na wafuasi wake wasiweze kupata nafasi ya kula chakula.'),
(2014979,69,41,3,21,'Basi, watu wa jamaa yake walipopata habari hiyo wakatoka kwenda kumchukua maana walikuwa wanasema kwamba amepatwa na wazimu.'),
(2014980,69,41,3,22,'Nao walimu wa Sheria waliokuwa wametoka Yerusalemu, wakasema, "Ana Beelzebuli! Tena, anawafukuza pepo kwa nguvu ya mkuu wa pepo."'),
(2014981,69,41,3,23,'Hapo Yesu akawaita, akawaambia kwa mifano,"Shetani anawezaje kumfukuza Shetani?'),
(2014982,69,41,3,24,'Ikiwa utawala mmoja umegawanyika makundimakundi yanayopigana, utawala huo hauwezi kudumu.'),
(2014983,69,41,3,25,'Tena, ikiwa jamaa moja imegawanyika makundimakundi yanayopingana, jamaa hiyo itaangamia.'),
(2014984,69,41,3,26,'Ikiwa basi, utawala wa Shetani umegawanyika vikundivikundi hauwezi kudumu, bali utaangamia kabisa.'),
(2014985,69,41,3,27,'"Hakuna mtu awezaye kuivamia nyumba ya mtu mwenye nguvu na kumnyang`anya mali yake, isipokuwa kwanza amemfunga huyo mtu mwenye nguvu; hapo ndipo atakapoweza kumnyang`anya mali yake.'),
(2014986,69,41,3,28,'"Kweli nawaambieni, watu watasamehewa dhambi zao zote na kufuru zao zote;'),
(2014987,69,41,3,29,'lakini anayesema mabaya dhidi ya Roho Mtakatifu, hatasamehewa kamwe; ana hatia ya dhambi ya milele."'),
(2014988,69,41,3,30,'Yesu alisema hivyo kwa sababu walikuwa wanasema, "Ana pepo mchafu.")'),
(2014989,69,41,3,31,'Mama yake Yesu na ndugu zake walifika hapo, wakasimama nje, wakampelekea ujumbe kutaka kumwona.'),
(2014990,69,41,3,32,'Umati wa watu ulikuwa umekaa hapo kumzunguka. Basi, wakamwambia, "Mama yako na ndugu zako wako nje, wanataka kukuona."'),
(2014991,69,41,3,33,'Yesu akawaambia, "Mama yangu na ndugu zangu ni kina nani?"'),
(2014992,69,41,3,34,'Hapo akawatazama watu waliokuwa wamemzunguka, akasema, "Tazameni! Hawa ndio mama yangu na ndugu zangu.'),
(2014993,69,41,3,35,'Mtu yeyote anayefanya anayotaka Mungu, huyo ndiye kaka yangu, dada yangu na mama yangu."'),
(2014994,69,41,4,1,'Yesu alianza kufundisha tena akiwa kando ya ziwa. Umati mkubwa wa watu ulimzunguka hata ikambidi aingie katika mashua na kuketi. Watu wakawa wamekaa katika nchi kavu, kando ya ziwa.'),
(2014995,69,41,4,2,'Aliwafundisha mambo mengi kwa mifano, na katika mafundisho yake aliwaambia,'),
(2014996,69,41,4,3,'"Sikilizeni! Mpanzi alikwenda kupanda mbegu.'),
(2014997,69,41,4,4,'Alipokuwa akipanda, nyingine zilianguka njiani, ndege wakaja wakazila.'),
(2014998,69,41,4,5,'Nyingine zilianguka penye mawe pasipokuwa na udongo mwingi. Mbegu hizo ziliota mara kwa kuwa udongo haukuwa na kina.'),
(2014999,69,41,4,6,'Jua lilipochomoza, zikachomeka; na kwa kuwa mizizi yake haikuwa na nguvu, zikanyauka.'),
(2015000,69,41,4,7,'Nyingine zilianguka kwenye miti ya miiba, nayo ikakua na kuzisonga, nazo hazikuzaa nafaka.'),
(2015001,69,41,4,8,'Nyingine zilianguka katika udongo mzuri, zikakua na kuzaa: moja punje thelathini, moja sitini na nyingine mia."'),
(2015002,69,41,4,9,'Kisha akawaambia, "Mwenye masikio na asikie!"'),
(2015003,69,41,4,10,'Yesu alipokuwa peke yake, baadhi ya wale waliomsikia walimwendea pamoja na wale kumi na wawili, wakamwuliza juu ya hiyo mifano.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015004,69,41,4,11,'Naye akawaambia, "Ninyi mmejaliwa kujua siri ya Utawala wa Mungu, lakini wale walio nje wataambiwa kila kitu kwa mifano,'),
(2015005,69,41,4,12,'ili, `Watazame kweli, lakini wasione. Wasikie kweli, lakini wasielewe. La sivyo, wangemgeukia Mungu, naye angewasamehe."`'),
(2015006,69,41,4,13,'Basi, Yesu akawauliza, "Je, ninyi hamwelewi mfano huu? Mtawezaje basi, kuelewa mfano wowote?'),
(2015007,69,41,4,14,'Mpanzi hupanda neno la Mungu.'),
(2015008,69,41,4,15,'Watu wengine ni kama wale walio njiani ambapo mbegu zilianguka. Hawa hulisikia hilo neno lakini mara Shetani huja na kuliondoa neno hilo lililopandwa ndani yao.'),
(2015009,69,41,4,16,'Watu wengine ni kama zile mbegu zilizopandwa penye mawe. Mara tu wanapolisikia hilo neno hulipokea kwa furaha.'),
(2015010,69,41,4,17,'Lakini haliwaingii na kuwa na mizizi ndani yao; huendelea kulizingatia kwa kitambo tu, na wakati taabu au udhalimu vinapotokea kwa sababu ya hilo neno mara wanakata tamaa.'),
(2015011,69,41,4,18,'Watu wengine ni kama zile mbegu zilizoanguka penye miti ya miiba. Huo ni mfano wa wale wanaolisikia hilo neno,'),
(2015012,69,41,4,19,'lakini wasiwasi wa ulimwengu huu, anasa za mali na tamaa za kila namna huwaingia na kulisonga hilo neno, nao hawazai matunda.'),
(2015013,69,41,4,20,'Lakini wengine ni kama zile mbegu zilizopandwa katika udongo mzuri. Hawa hulisikia hilo neno, wakalipokea, wakazaa matunda: wengine thelathini, wengine sitini na wengine mia moja."'),
(2015014,69,41,4,21,'Yesu akaendelea kuwaambia, "Je, watu huwasha taa wakaileta ndani na kuifunika kwa pishi au kuiweka mvunguni? La! Huiweka juu ya kinara.'),
(2015015,69,41,4,22,'Basi, kila kilichofichwa kitafichuliwa, na kila kilichofunikwa kitafunuliwa.'),
(2015016,69,41,4,23,'Mwenye masikio na asikie!"'),
(2015017,69,41,4,24,'Akawaambia pia, "Sikilizeni kwa makini mnachosikia! Kipimo kilekile mnachowapimia watu wengine, ndicho mtakachopimiwa; tena mtazidishiwa.'),
(2015018,69,41,4,25,'Aliye na kitu atapewa zaidi; asiye na kitu, hata kile alicho nacho kitachukuliwa."'),
(2015019,69,41,4,26,'Yesu akaendelea kusema, "Ufalme wa Mungu ni kama ifuatavyo. Mtu hupanda mbegu shambani.'),
(2015020,69,41,4,27,'Usiku hulala, mchana yu macho na wakati huo mbegu zinaota na kukua; yeye hajui inavyofanyika.'),
(2015021,69,41,4,28,'Udongo wenyewe huiwezesha mimea kukua na kuzaa matunda: kwanza huchipua jani changa, kisha suke, na mwishowe nafaka ndani ya suke.'),
(2015022,69,41,4,29,'Nafaka inapoiva, huyo mtu huanza kutumia mundu wake, maana wakati wa mavuno umefika."'),
(2015023,69,41,4,30,'Tena, Yesu akasema, "Tuufananishe Utawala wa Mungu na nini? Tuueleze kwa mifano gani?'),
(2015024,69,41,4,31,'Ni kama mbegu ya haradali ambayo ni ndogo kuliko mbegu zote.'),
(2015025,69,41,4,32,'Lakini ikisha pandwa, huota na kuwa mmea mkubwa kuliko mimea yote ya shambani. Matawi yake huwa makubwa hata ndege wa angani huweza kujenga viota vyao katika kivuli chake."'),
(2015026,69,41,4,33,'Yesu aliwahubiria ujumbe wake kwa mifano mingine mingi ya namna hiyo; aliongea nao kadiri walivyoweza kusikia.'),
(2015027,69,41,4,34,'Hakuongea nao chochote bila kutumia mifano; lakini alipokuwa pamoja na wanafunzi wake peke yao alikuwa akiwafafanulia kila kitu.'),
(2015028,69,41,4,35,'Jioni, siku hiyohiyo, Yesu aliwaambia wanafunzi wake, "Tuvuke ziwa, twende ng`ambo."'),
(2015029,69,41,4,36,'Basi, wakauacha ule umati wa watu, wakamchukua Yesu katika mashua alimokuwa. Palikuwapo pia mashua nyingine hapo.'),
(2015030,69,41,4,37,'Basi, dhoruba kali ikaanza kuvuma, mawimbi yakaipiga ile mashua hata ikaanza kujaa maji.'),
(2015031,69,41,4,38,'Yesu alikuwa sehemu ya nyuma ya mashua, amelala juu ya mto. Basi, wanafunzi wakamwamsha na kumwambia, "Mwalimu, je, hujali kwamba sisi tunaangamia?"'),
(2015032,69,41,4,39,'Basi, akaamka, akaukemea ule upepo na kuyaamrisha mawimbi ya ziwa, "Kimya! Tulia!" Hapo upepo ukakoma, kukawa shwari kabisa.'),
(2015033,69,41,4,40,'Kisha Yesu akawaambia wanafunzi wake, "Mbona mnaogopa? Je, bado hamna imani?"'),
(2015034,69,41,4,41,'Nao wakaogopa sana, wakawa wanaulizana, "Huyu ni nani basi, hata upepo na mawimbi vinamtii?"'),
(2015035,69,41,5,1,'Basi, wakafika katika nchi ya Wagerase, ng`ambo ya ziwa.'),
(2015036,69,41,5,2,'Mara tu Yesu aliposhuka mashuani, mtu mmoja aliyepagawa na pepo mchafu alitoka makaburini, akakutana naye.'),
(2015037,69,41,5,3,'Mtu huyo alikuwa akiishi makaburini wala hakuna mtu aliyeweza tena kumfunga kwa minyororo.'),
(2015038,69,41,5,4,'Mara nyingi walimfunga kwa pingu na minyororo lakini kila mara aliweza kuikata hiyo minyororo na kuzivunja hizo pingu, wala hakuna mtu aliyeweza kumzuia.'),
(2015039,69,41,5,5,'Mchana na usiku alikaa makaburini na milimani akipaaza sauti na kujikatakata kwa mawe.'),
(2015040,69,41,5,6,'Alipomwona Yesu kwa mbali, alimkimbilia, akamwinamia'),
(2015041,69,41,5,7,'akisema kwa sauti kubwa, "Una shauri gani nami, wewe Yesu Mwana wa Mungu aliye juu? Kwa jina la Mungu, nakusihi usinitese!"'),
(2015042,69,41,5,8,'Alisema hivyo kwa kuwa Yesu alikuwa amemwambia, "Pepo mchafu, mtoke mtu huyu.")'),
(2015043,69,41,5,9,'Basi, Yesu akamwuliza, "Jina lako nani?" Naye akajibu, "Jina langu ni `Jeshi`, maana sisi tu wengi."'),
(2015044,69,41,5,10,'Kisha akamsihi Yesu asiwafukuze hao pepo katika nchi ile.'),
(2015045,69,41,5,11,'Kulikuwa na kundi kubwa la nguruwe malishoni kwenye mteremko wa mlima.'),
(2015046,69,41,5,12,'Basi, hao pepo wakamsihi, "Utupeleke kwa hao nguruwe, tuwaingie."'),
(2015047,69,41,5,13,'Naye akawaruhusu. Basi, hao pepo wachafu wakatoka, wakawaingia wale nguruwe. Kundi lote la nguruwe wapatao elfu mbili likaporomoka kwenye ule mteremko mkali mpaka ziwani, likatumbukia majini.'),
(2015048,69,41,5,14,'Wachungaji wa hao nguruwe walikimbia, wakatangaza jambo hilo mjini na mashambani. Watu wakafika kuona yaliyotukia.'),
(2015049,69,41,5,15,'Wakamwendea Yesu, wakamwona na mtu yuleyule aliyekuwa amepagawa na jeshi la pepo ameketi chini, amevaa nguo na ana akili yake sawa, wakaogopa.'),
(2015050,69,41,5,16,'Watu walishuhudia tukio hilo wakaeleza wengine mambo yaliyompata huyo mtu aliyekuwa amepagawa na pepo na juu ya wale nguruwe.'),
(2015051,69,41,5,17,'Basi, wakaanza kumwomba aondoke katika nchi yao.'),
(2015052,69,41,5,18,'Yesu alipokuwa anapanda mashuani, yule mtu aliyekuwa amepagawa na pepo akamwomba amruhusu kwenda naye.'),
(2015053,69,41,5,19,'Lakini Yesu akamkatalia. Badala yake akamwambia, "Nenda nyumbani kwa jamaa yako, ukawaambie mambo yote Bwana aliyokutendea na jinsi alivyokuonea huruma."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015054,69,41,5,20,'Basi, huyo mtu akaenda, akaanza kutangaza huko Dekapoli mambo yote Yesu aliyomtendea; watu wote wakashangaa.'),
(2015055,69,41,5,21,'Yesu alivukia tena upande wa pili wa ziwa kwa mashua. Umati mkubwa wa watu ukakusanyika mbele yake, naye akawa amesimama kando ya ziwa.'),
(2015056,69,41,5,22,'Hapo akaja mmojawapo wa maofisa wa sunagogi, jina lake Yairo. Alipomwona Yesu, akajitupa mbele ya miguu yake,'),
(2015057,69,41,5,23,'akamsihi akisema, "Binti yangu mdogo ni mgonjwa karibu kufa. Twende tafadhali, ukamwekee mikono yako, apate kupona na kuishi."'),
(2015058,69,41,5,24,'Basi, Yesu akaondoka pamoja naye. Watu wengi sana wakamfuata, wakawa wanamsonga kila upande.'),
(2015059,69,41,5,25,'Mmojawapo alikuwa mwanamke mwenye ugonjwa wa kutokwa damu kwa muda wa miaka kumi na miwili.'),
(2015060,69,41,5,26,'Mwanamke huyo alikuwa amekwisha sumbuka sana kuwaendea waganga wengi. Na ingawa alikuwa amekwisha tumia mali yake yote, hakupata nafuu bali hali yake ilizidi kuwa mbaya.'),
(2015061,69,41,5,27,'Alikuwa amesikia habari za Yesu, na hivyo akaupenya msongamano wa watu kutoka nyuma, akagusa vazi lake.'),
(2015062,69,41,5,28,'Alifanya hivyo, maana alijisemea, "Nikigusa tu vazi lake, nitapona."'),
(2015063,69,41,5,29,'Mara chemchemi ya damu yake ikakauka, akajisikia mwilini mwake kwamba ameponywa ugonjwa wake.'),
(2015064,69,41,5,30,'Yesu alitambua mara kwamba nguvu imemtoka. Basi akaugeukia ule umati wa watu, akauliza, "Nani aliyegusa mavazi yangu?"'),
(2015065,69,41,5,31,'Wanafunzi wake wakamjibu, "Unaona jinsi watu wanavyokusonga; mbona wauliza nani aliyekugusa?"'),
(2015066,69,41,5,32,'Lakini Yesu akaendelea kutazama amwone huyo aliyefanya hivyo.'),
(2015067,69,41,5,33,'Hapo huyo mwanamke, akifahamu yaliyompata, akajitokeza akitetemeka kwa hofu, akajitupa chini mbele ya Yesu na kusema ukweli wote.'),
(2015068,69,41,5,34,'Yesu akamwambia, "Binti, imani yako imekuponya. Nenda kwa amani, upone kabisa ugonjwa wako."'),
(2015069,69,41,5,35,'Yesu alipokuwa bado anaongea, watu walifika kutoka nyumbani kwa yule ofisa wa sunagogi, wakamwambia, "Binti yako amekwisha kufa. Ya nini kuendelea kumsumbua Mwalimu?"'),
(2015070,69,41,5,36,'Lakini, bila kujali walichosema, Yesu akamwambia mkuu wa sunagogi, "Usiogope, amini tu."'),
(2015071,69,41,5,37,'Wala hakumruhusu mtu yeyote kufuatana naye ila Petro, Yakobo na Yohane nduguye Yakobo.'),
(2015072,69,41,5,38,'Wakafika nyumbani kwa ofisa wa sunagogi naye Yesu akasikia makelele, kilio na maombolezo mengi.'),
(2015073,69,41,5,39,'Akaingia ndani, akawaambia, "Mbona mnapiga kelele na kulia? Msichana hakufa, amelala tu."'),
(2015074,69,41,5,40,'Lakini wao wakamcheka. Basi, akawaondoa wote nje, akawachukua baba na mama ya huyo msichana na wale wanafunzi wake, wakaingia chumbani alimokuwa huyo msichana.'),
(2015075,69,41,5,41,'Kisha akamshika mkono, akamwambia, "Talitha, kumi," maana yake, "Msichana, nakwambia, amka!"'),
(2015076,69,41,5,42,'Mara msichana akasimama, akaanza kutembea. (Alikuwa na umri wa miaka kumi na miwili.) Hapo watu wakashangaa kupita kiasi.'),
(2015077,69,41,5,43,'Yesu akawakataza sana wasimjulishe mtu jambo hilo. Kisha akawaambia wampe huyo msichana chakula.'),
(2015078,69,41,6,1,'Yesu aliondoka hapo akaenda katika kijiji chake, akifuatwa na wanafunzi wake.'),
(2015079,69,41,6,2,'Siku ya Sabato ilipofika, alianza kufundisha katika sunagogi. Wengi waliomsikia walishangaa, wakasema, "Je, ameyapata wapi mambo haya? Ni hekima gani hii aliyopewa? Tena, anatendaje maajabu haya anayoyafanya?'),
(2015080,69,41,6,3,'Je, huyu si yule seremala mwana wa Maria, na ndugu yao kina Yakobo, Yose, Yuda na Simoni; Je, dada zake si wanaishi papa hapa kwetu?" Basi, wakawa na mashaka naye. ic\is Ndani ya Sunagogi (Marko 6:2)\ie'),
(2015081,69,41,6,4,'Yesu akawaambia, "Nabii hakosi heshima isipokuwa katika nchi yake, kwa jamaa zake na nyumbani mwake."'),
(2015082,69,41,6,5,'Hakuweza kutenda miujiza hapo, ila aliwawekea mikono wagonjwa wachache, akawaponya.'),
(2015083,69,41,6,6,'Alishangaa sana kwa sababu ya kutoamini kwao. Kisha Yesu alivitembelea vijiji vya pale karibu akiwafundisha watu.'),
(2015084,69,41,6,7,'Aliwaita wale wanafunzi kumi na wawili, akaanza kuwatuma wawiliwawili. Aliwapa uwezo wa kuwatoa pepo wachafu,'),
(2015085,69,41,6,8,'na kuwaamuru, "Msichukue chochote mnapokwenda isipokuwa fimbo tu. Msichukue mkate, wala mkoba, wala fedha kibindoni.'),
(2015086,69,41,6,9,'Vaeni viatu lakini msivae kanzu mbili."'),
(2015087,69,41,6,10,'Tena aliwaambia, "Popote mtakapokaribishwa nyumbani, kaeni humo mpaka mtakapoondoka mahali hapo.'),
(2015088,69,41,6,11,'Mahali popote ambapo watu watakataa kuwakaribisheni au kuwasikiliza, ondokeni hapo na kuyakung`uta mavumbi miguuni mwenu kama onyo kwao."'),
(2015089,69,41,6,12,'Basi, wakaondoka, wakahubiri watu watubu.'),
(2015090,69,41,6,13,'Waliwafukuza pepo wengi wabaya; wakawapaka mafuta wagonjwa wengi, wakawaponya.'),
(2015091,69,41,6,14,'Basi, mfalme Herode alisikia juu ya hayo yote, maana sifa za Yesu zilienea kila mahali. Baadhi ya watu walikuwa wakisema, "Yohane Mbatizaji amefufuka kutoka wafu, ndiyo maana nguvu za miujiza zinafanya kazi ndani yake."'),
(2015092,69,41,6,15,'Wengine walisema, "Mtu huyu ni Eliya." Wengine walisema, "Huyu ni nabii kama mmojawapo wa manabii wa kale."'),
(2015093,69,41,6,16,'Lakini Herode alipopata habari hizi alisema, "Huyu ni Yohane! Nilimkata kichwa, lakini amefufuka."'),
(2015094,69,41,6,17,'Hapo awali Herode mwenyewe alikuwa ameamuru Yohane atiwe nguvuni, akamfunga gerezani. Herode alifanya hivyo kwa sababu ya Herodia ambaye Herode alimwoa ingawaje alikuwa mke wa Filipo, ndugu yake.'),
(2015095,69,41,6,18,'Yohane alikuwa amemwambia Herode, "Si halali kwako kumchukua mke wa ndugu yako."'),
(2015096,69,41,6,19,'Basi Herodia alimchukia sana Yohane, akataka kumwua, asiweze.'),
(2015097,69,41,6,20,'Herode alimwogopa Yohane kwa maana alijua kwamba yeye ni mtu mwema na mtakatifu, na hivyo akamlinda. Herode alipenda kumsikiliza Yohane, ingawaje baada ya kumsikiliza, alifadhaika sana.'),
(2015098,69,41,6,21,'Ikapatikana nafasi, wakati wa sikukuu ya kuzaliwa kwake Herode. Herode aliwafanyia karamu wazee wa baraza lake, majemadari na viongozi wa Galilaya.'),
(2015099,69,41,6,22,'Basi, binti yake Herodia aliingia, akacheza, akawafurahisha sana Herode na wageni wake. Mfalme akamwambia huyo msichana, "Niombe chochote utakacho, nami nitakupa."'),
(2015100,69,41,6,23,'Tena akamwapia, "Chochote utakachoniomba, nitakupa: hata ikiwa ni nusu ya ufalme wangu."'),
(2015101,69,41,6,24,'Hapo huyo msichana akatoka, akamwuliza mama yake, "Niombe nini?" Naye akamjibu, "Kichwa cha Yohane mbatizaji."'),
(2015102,69,41,6,25,'Msichana akamrudia mfalme mbio akamwomba, "Nataka unipe sasa hivi katika sinia kichwa cha Yohane mbatizaji."'),
(2015103,69,41,6,26,'Mfalme akahuzunika sana, lakini kwa sababu ya kiapo chake, na kwa ajili ya wale wageni wake karamuni, hakutaka kumkatalia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015104,69,41,6,27,'Basi, mfalme akamwamuru askari kukileta kichwa cha Yohane. Askari akaenda, akamkata kichwa Yohane mle gerezani,'),
(2015105,69,41,6,28,'akakileta katika sinia, akampa msichana naye msichana akampa mama yake.'),
(2015106,69,41,6,29,'Wanafunzi wa Yohane walipopata habari, walikwenda wakachukua mwili wake, wakauzika kaburini.'),
(2015107,69,41,6,30,'Wale mitume walirudi, wakakusanyika mbele ya Yesu wakamwarifu yote waliyotenda na kufundisha.'),
(2015108,69,41,6,31,'Alisema hivyo kwa kuwa kulikuwa na watu wengi mno walikuwa wanafika hapo na kuondoka hata Yesu na wanafunzi wake hawakuweza kupata nafasi ya kula chakula. Basi, Yesu akawaambia, "Twendeni peke yetu mahali pa faragha kula chakula, mkapumzike kidogo."'),
(2015109,69,41,6,32,'Basi, Wakaondoka peke yao kwa mashua, wakaenda mahali pa faragha.'),
(2015110,69,41,6,33,'Lakini watu wengi waliwaona wakienda, wakawatambua. Hivyo wengi wakatoka katika kila mji, wakakimbilia huko Yesu na wanafunzi wake walikokuwa wanakwenda, wakawatangulia kufika.'),
(2015111,69,41,6,34,'Waliposhuka pwani, Yesu aliona umati mkubwa wa watu, akawahurumia, kwa sababu walikuwa kama kondoo wasio na mchungaji. Akaanza kuwafundisha mambo mengi.'),
(2015112,69,41,6,35,'Saa za mchana zilikwisha pita. Basi, wanafunzi wakamwendea Yesu, wakamwambia, "Hapa ni nyikani, na sasa kunakuchwa.'),
(2015113,69,41,6,36,'Afadhali uwaage watu waende mashambani na katika vijiji vya jirani, wanunue chakula."'),
(2015114,69,41,6,37,'Lakini Yesu akawaambia, "Wapeni ninyi chakula." Nao wakamwuliza, "Je, twende kununua mikate kwa fedha dinari mia mbili, na kuwapa chakula?"'),
(2015115,69,41,6,38,'Yesu akawauliza, "Mnayo mikate mingapi? Nendeni mkatazame." Walipokwisha tazama, wakamwambia, "Kuna mikate mitano na samaki wawili." ic\is Mikate na samaki (Marko 6:38)\ie'),
(2015116,69,41,6,39,'Basi, Yesu akawaamuru wanafunzi wawaketishe watu wote makundimakundi penye nyasi.'),
(2015117,69,41,6,40,'Nao wakaketi makundimakundi ya watu mia moja na ya watu hamsini.'),
(2015118,69,41,6,41,'Kisha Yesu akaitwaa ile mikate mitano na wale samaki wawili, akatazama juu mbinguni, akamshukuru Mungu, akaimega mikate, akawapa wanafunzi wake wawagawie watu. Na wale samaki wawili pia akawagawia wote.'),
(2015119,69,41,6,42,'Watu wote wakala, wakashiba.'),
(2015120,69,41,6,43,'Wakaokota mabaki ya mikate na samaki pia, wakajaza vikapu kumi na viwili.'),
(2015121,69,41,6,44,'Nao waliokula hiyo mikate walikuwa wanaume elfu tano.'),
(2015122,69,41,6,45,'Mara Yesu akawaamuru wanafunzi wake wapande mashua, wamtangulie kwenda Bethsaida, ng`ambo ya ziwa, wakati yeye anauaga umati wa watu.'),
(2015123,69,41,6,46,'Baada ya kuwaaga watu alikwenda mlimani kusali.'),
(2015124,69,41,6,47,'Ilipokuwa jioni, mashua ilikuwa katikati ya ziwa, naye alikuwa peke yake katika nchi kavu.'),
(2015125,69,41,6,48,'Basi, akawaona wanafunzi wake wakitaabika kwa kupiga makasia, maana upepo ulikuwa unawapinga. Karibu na mapambazuko, Yesu aliwaendea akitembea juu ya maji. Alitaka kuwapita.'),
(2015126,69,41,6,49,'Lakini walimwona akitembea juu ya maji, wakadhani ni mzimu, wakapiga yowe.'),
(2015127,69,41,6,50,'Maana wote walipomwona waliogopa sana. Mara Yesu akasema nao, "Tulieni, ni mimi. Msiogope!"'),
(2015128,69,41,6,51,'Kisha akapanda mashuani walimokuwa, na upepo ukatulia. Nao wakashangaa sana.'),
(2015129,69,41,6,52,'maana hawakuwa bado wameelewa maana ya ile mikate. Akili zao zilikuwa bado zimepumbazika.'),
(2015130,69,41,6,53,'Walivuka ziwa, wakafika nchi ya Genesareti, wakatia nanga.'),
(2015131,69,41,6,54,'Walipotoka mashuani, mara watu wakamtambua Yesu.'),
(2015132,69,41,6,55,'Basi, kwa haraka wakazunguka katika nchi ile yote, wakaanza kuwachukua wagonjwa wamelala juu ya mikeka yao, wakawapeleka kila mahali waliposikia Yesu yupo.'),
(2015133,69,41,6,56,'Kila mahali Yesu alipokwenda, vijijini, mijini, au mashambani, watu waliwaweka wagonjwa uwanjani, wakamsihi waguse walau pindo la vazi lake. Nao wote waliomgusa walipona.'),
(2015134,69,41,7,1,'Baadhi ya Mafarisayo na walimu wa Sheria waliokuwa wametoka Yerusalemu walikusanyika mbele ya Yesu.'),
(2015135,69,41,7,2,'Waliona kwamba baadhi ya wanafunzi wake walikula mikate kwa mikono najisi, yaani bila kunawa.'),
(2015136,69,41,7,3,'Maana Mafarisayo na Wayahudi wengine wote huzingatia mapokeo ya wazee wao: hawali kitu kabla ya kunawa mikono ipasavyo.'),
(2015137,69,41,7,4,'Tena hawali kitu chochote kutoka sokoni mpaka wamekiosha kwanza.*fc* Kuna pia desturi nyingine walizopokea kama vile namna ya kuosha vikombe, sufuria na vyombo vya shaba.'),
(2015138,69,41,7,5,'Basi, Mafarisayo na walimu wa Sheria wakamwuliza Yesu, "Mbona wanafunzi wako hawayajali mapokeo tuliyopokea kwa wazee wetu, bali hula chakula kwa mikono najisi?"'),
(2015139,69,41,7,6,'Yesu akawajibu, "Wanafiki ninyi! Nabii Isaya alitabiri ukweli juu yenu alipoandika: `Watu hawa, asema Mungu, huniheshimu kwa maneno matupu, lakini mioyoni mwao wako mbali nami.'),
(2015140,69,41,7,7,'Kuniabudu kwao hakufai, maana mambo wanayofundisha ni maagizo ya kibinadamu tu.`'),
(2015141,69,41,7,8,'Ninyi mnaiacha amri ya Mungu na kushikilia maagizo ya watu."'),
(2015142,69,41,7,9,'Yesu akaendelea kusema, "Ninyi mnajua kuepa kwa ujanja sheria ya Mungu kwa ajili ya kufuata mapokeo yenu.'),
(2015143,69,41,7,10,'Maana Mose aliamuru: `Waheshimu baba yako na mama yako,` na, `Anayemlaani baba au mama, lazima afe.`'),
(2015144,69,41,7,11,'Lakini ninyi mwafundisha, `Kama mtu anacho kitu ambacho angeweza kuwasaidia nacho baba au mama yake, lakini akasema kwamba kitu hicho ni Korbani (yaani ni zawadi kwa Mungu),'),
(2015145,69,41,7,12,'basi, halazimiki tena kuwasaidia wazazi wake.`'),
(2015146,69,41,7,13,'Hivyo ndivyo mnavyodharau neno la Mungu kwa ajili ya mafundisho mnayopokezana. Tena mnafanya mambo mengi ya namna hiyo."'),
(2015147,69,41,7,14,'Yesu aliuita tena ule umati wa watu, akawaambia, "Nisikilizeni nyote, mkaelewe.'),
(2015148,69,41,7,15,'Hakuna kitu kinachoingia ndani ya mtu toka nje ambacho chaweza kumtia mtu najisi. Lakini kinachotoka ndani ya mtu ndicho kinachomtia mtu najisi."*fd*'),
(2015149,69,41,7,16,'missing'),
(2015150,69,41,7,17,'Alipouacha umati wa watu na kuingia nyumbani, wanafunzi wake walimwuliza maana ya huo mfano.'),
(2015151,69,41,7,18,'Naye akawaambia, "Je, hata ninyi hamwelewi? Je, hamwelewi kwamba kitu kinachomwingia mtu toka nje hakiwezi kumtia unajisi,'),
(2015152,69,41,7,19,'kwa maana hakimwingii moyoni, ila tumboni, na baadaye hutolewa nje chooni?" (Kwa kusema hivyo, Yesu alivihalalisha vyakula vyote.)'),
(2015153,69,41,7,20,'Akaendelea kusema, "Kinachotoka ndani ya mtu ndicho kinachomtia najisi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015154,69,41,7,21,'Kwa maana kutoka ndani, katika moyo wa mtu, hutoka mawazo mabaya, uasherati, wizi, uuaji,'),
(2015155,69,41,7,22,'uzinzi, uchoyo, uovu, udanganyifu, ufisadi, wivu, kashfa, kiburi na upumbavu.'),
(2015156,69,41,7,23,'Maovu hayo yote yatoka ndani ya mtu, nayo humtia mtu najisi."'),
(2015157,69,41,7,24,'Yesu aliondoka hapo, akaenda hadi wilaya ya Tiro. Huko aliingia katika nyumba moja na hakutaka mtu ajue; lakini hakuweza kujificha.'),
(2015158,69,41,7,25,'Mwanamke mmoja ambaye binti yake alikuwa na pepo, alisikia habari za Yesu. Basi, akaja akajitupa chini mbele ya miguu yake.'),
(2015159,69,41,7,26,'Mama huyo alikuwa Mgiriki, mwenyeji wa Sirofoinike. Basi, akamwomba Yesu amtoe binti yake pepo mchafu.'),
(2015160,69,41,7,27,'Yesu akamwambia, "Kwanza watoto washibe; kwa maana si vizuri kuchukua chakula cha watoto na kuwatupia mbwa."'),
(2015161,69,41,7,28,'Lakini huyo mama akasema, "Sawa, Bwana, lakini hata mbwa walio chini ya meza hula makombo ya watoto."'),
(2015162,69,41,7,29,'Yesu akamwambia, "Kwa sababu ya neno hilo, nenda. Pepo amemtoka binti yako!"'),
(2015163,69,41,7,30,'Basi, akaenda nyumbani kwake, akamkuta mtoto amelala kitandani, na pepo amekwisha mtoka.'),
(2015164,69,41,7,31,'Kisha Yesu aliondoka wilayani Tiro, akapitia Sidoni, akafika ziwa Galilaya kwa kupitia nchi ya Dekapoli.'),
(2015165,69,41,7,32,'Basi, wakamletea bubu-kiziwi, wakamwomba amwekee mikono.'),
(2015166,69,41,7,33,'Yesu akamtenga na umati wa watu, akamtia vidole masikioni, akatema mate na kumgusa ulimi.'),
(2015167,69,41,7,34,'Kisha akatazama juu mbinguni, akapiga kite, akamwambia, "Efatha," maana yake, "Funguka."'),
(2015168,69,41,7,35,'Mara masikio yake yakafunguka na ulimi wake ukafunguliwa, akaanza kusema sawasawa.'),
(2015169,69,41,7,36,'Yesu akawaamuru wasimwambie mtu juu ya jambo hilo. Lakini kadiri alivyowakataza, ndivyo walivyozidi kutangaza habari hiyo.'),
(2015170,69,41,7,37,'Watu walishangaa sana, wakasema, "Amefanya yote vyema: amewajalia viziwi kusikia, na bubu kusema!"'),
(2015171,69,41,8,1,'Wakati huo umati mkubwa wa watu ulikusanyika tena, na hawakuwa na chakula. Basi, Yesu akawaita wanafunzi wake, akawaambia,'),
(2015172,69,41,8,2,'"Nawahurumia watu hawa kwa sababu wamekuwa nami kwa muda wa siku tatu, wala hawana chakula.'),
(2015173,69,41,8,3,'Nikiwaacha waende nyumbani wakiwa na njaa watazimia njiani, maana baadhi yao wametoka mbali."'),
(2015174,69,41,8,4,'Wanafunzi wake wakamwuliza, "Hapa nyikani itapatikana wapi mikate ya kuwashibisha watu hawa wote?"'),
(2015175,69,41,8,5,'Yesu akawauliza, "Mnayo mikate mingapi?" Nao wakamjibu, "Saba."'),
(2015176,69,41,8,6,'Basi, akawaamuru watu wakae chini. Akaitwaa ile mikate saba, akamshukuru Mungu, akaimega, akawapa wanafunzi wake wawagawie watu, nao wakawagawia.'),
(2015177,69,41,8,7,'Walikuwa pia na visamaki vichache. Yesu akavibariki, akaamuru vigawiwe watu vilevile.'),
(2015178,69,41,8,8,'Watu wakala, wakashiba. Wakaokota mabaki yaliyosalia wakajaza makapu saba.'),
(2015179,69,41,8,9,'Nao waliokula walikuwa watu wapatao elfu nne. Yesu akawaaga,'),
(2015180,69,41,8,10,'na mara akapanda mashua pamoja na wanafunzi wake, akaenda wilaya ya Dalmanutha.'),
(2015181,69,41,8,11,'Mafarisayo walikuja, wakaanza kujadiliana na Yesu. Kwa kumjaribu, wakamtaka awafanyie ishara kuonyesha anayo idhini kutoka mbinguni.'),
(2015182,69,41,8,12,'Yesu akahuzunika rohoni, akasema, "Mbona kizazi hiki kinataka ishara? Kweli nawaambieni, kizazi hiki hakitapewa ishara yoyote!"'),
(2015183,69,41,8,13,'Basi, akawaacha, akapanda tena mashua, akaanza safari kwenda ng`ambo ya pili ya ziwa.'),
(2015184,69,41,8,14,'Wanafunzi walikuwa wamesahau kuchukua mikate; walikuwa na mkate mmoja tu katika mashua.'),
(2015185,69,41,8,15,'Yesu akawaonya, "Angalieni sana! Jihadharini na chachu ya Mafarisayo na chachu ya Herode."'),
(2015186,69,41,8,16,'Wanafunzi wakaanza kujadiliana wao kwa wao, "Anasema hivyo kwa kuwa hatuna mikate."'),
(2015187,69,41,8,17,'Yesu alitambua hayo, akawaambia, "Mbona mnajadiliana juu ya kutokuwa na mikate? Je, bado hamjafahamu, wala hamjaelewa? Je, mioyo yenu imeshupaa?'),
(2015188,69,41,8,18,'Je, Mnayo macho na hamwoni? Mnayo masikio na hamsikii? Je, hamkumbuki'),
(2015189,69,41,8,19,'wakati ule nilipoimega ile mikate mitano na kuwapa watu elfu tano? Mlikusanya vikapu vingapi vya mabaki ya makombo?" Wakamjibu, "Kumi na viwili."'),
(2015190,69,41,8,20,'"Na nilipoimega ile mikate saba na kuwapa watu elfu nne, mlikusanya makapu mangapi ya makombo?" Wakamjibu, "Saba."'),
(2015191,69,41,8,21,'Basi, akawaambia, "Na bado hamjaelewa?"'),
(2015192,69,41,8,22,'Yesu alifika Bethsaida pamoja na wanafunzi wake. Huko watu wakamletea kipofu mmoja, wakamwomba amguse.'),
(2015193,69,41,8,23,'Yesu akamshika mkono huyo kipofu, akampeleka nje ya kijiji. Akamtemea mate machoni, akamwekea mikono, akamwuliza, "Je, unaweza kuona kitu?"'),
(2015194,69,41,8,24,'Huyo kipofu akatazama, akasema, "Ninawaona watu wanaoonekana kama miti inayotembea."'),
(2015195,69,41,8,25,'Kisha Yesu akamwekea tena mikono machoni, naye akakaza macho, uwezo wake wa kuona ukamrudia, akaona kila kitu sawasawa.'),
(2015196,69,41,8,26,'Yesu akamwambia aende zake nyumbani na kumwamuru, "Usirudi kijijini!"'),
(2015197,69,41,8,27,'Kisha Yesu na wanafunzi wake walikwenda katika vijiji vya Kaisarea Filipi. Walipokuwa njiani, Yesu aliwauliza wanafunzi wake, "Watu wanasema mimi ni nani?"'),
(2015198,69,41,8,28,'Wakamjibu, "Wengine wanasema wewe ni Yohane Mbatizaji, wengine Eliya na wengine mmojawapo wa manabii."'),
(2015199,69,41,8,29,'Naye akawauliza, "Na ninyi je, mnasema mimi ni nani?" Petro akamjibu, "Wewe ndiwe Kristo."'),
(2015200,69,41,8,30,'Kisha Yesu akawaonya wasimwambie mtu yeyote habari zake.'),
(2015201,69,41,8,31,'Yesu alianza kuwafundisha wanafunzi wake: "Ni lazima Mwana wa Mtu apatwe na mateso mengi na kukataliwa na wazee na makuhani wakuu na walimu wa Sheria. Atauawa na baada ya siku tatu atafufuka."'),
(2015202,69,41,8,32,'Yesu aliwaambia jambo hilo waziwazi. Basi, Petro akamchukua kando, akaanza kumkemea.'),
(2015203,69,41,8,33,'Lakini Yesu akageuka, akawatazama wanafunzi wake, akamkemea Petro akisema, "Ondoka mbele yangu, Shetani! Fikira zako si za kimungu ila ni za kibinadamu!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015204,69,41,8,34,'Kisha akauita umati wa watu pamoja na wanafunzi wake, akawaambia, "Mtu yeyote akitaka kuwa mfuasi wangu, lazima ajikane mwenyewe, auchukue msalaba wake, anifuate.'),
(2015205,69,41,8,35,'Maana mtu anayetaka kuyaokoa maisha yake mwenyewe, atayapoteza, lakini mtu atakayepoteza maisha yake kwa ajili yangu na kwa ajili ya Habari Njema, atayaokoa.'),
(2015206,69,41,8,36,'Je, kuna faida gani mtu kuupata ulimwengu wote na kuyapoteza maisha yake?'),
(2015207,69,41,8,37,'Ama mtu atatoa kitu gani badala ya maisha yake?'),
(2015208,69,41,8,38,'Mtu yeyote katika kizazi hiki kiovu na kisichomjali Mungu anayenionea aibu mimi na mafundisho yangu, Mwana wa Mtu atamwonea aibu mtu huyo wakati atakapokuja katika utukufu wa Baba yake pamoja na malaika watakatifu."'),
(2015209,69,41,9,1,'Yesu akaendelea kuwaambia, "Kweli nawaambieni, wako wengine papa hapa ambao hawatakufa kabla ya kuuona Ufalme wa Mungu ukija kwa enzi."'),
(2015210,69,41,9,2,'Baada ya siku sita, Yesu aliwachukua Petro, Yakobo na Yohane juu ya mlima mrefu peke yao. Huko, Yesu akageuka sura mbele yao,'),
(2015211,69,41,9,3,'mavazi yake yakang`aa, yakawa meupe sana, jinsi dobi yeyote duniani asingeweza kuyafanya meupe.'),
(2015212,69,41,9,4,'Eliya na Mose wakawatokea, wakazungumza na Yesu.'),
(2015213,69,41,9,5,'Petro akamwambia Yesu, "Mwalimu, ni vizuri sana kwamba tuko hapa. Basi, afadhali tujenge vibanda vitatu: kimoja chako, kimoja cha Mose na kimoja cha Eliya."'),
(2015214,69,41,9,6,'Yeye na wenzake waliogopa hata hakujua la kusema.'),
(2015215,69,41,9,7,'Kisha likatokea wingu likawafunika, na sauti ikasikika kutoka katika hilo wingu, "Huyu ni Mwanangu mpendwa, msikilizeni."'),
(2015216,69,41,9,8,'Mara wanafunzi hao wakatazama tena, lakini hawakumwona mtu mwingine, ila Yesu peke yake pamoja nao.'),
(2015217,69,41,9,9,'Walipokuwa wakishuka mlimani, Yesu aliwakataza wasimwambie mtu yeyote mambo waliyoyaona, mpaka Mwana wa Mtu atakapokuwa amefufuka kutoka wafu.'),
(2015218,69,41,9,10,'Basi, wakashika agizo hilo, lakini wakawa wanajadiliana wao kwa wao maana ya kufufuka kutoka wafu.'),
(2015219,69,41,9,11,'Wakamwuliza Yesu, "Mbona walimu wa Sheria wanasema kwamba ni lazima Eliya aje kwanza?"'),
(2015220,69,41,9,12,'Naye akawajibu, "Naam, Eliya anakuja kwanza kutayarisha yote. Hata hivyo, kwa nini basi imeandikwa katika Maandiko Matakatifu kwamba Mwana wa Mtu atapatwa na mateso mengi na kudharauliwa?'),
(2015221,69,41,9,13,'Lakini nawaambieni, Eliya amekwisha kuja, nao wakamtendea walivyotaka kama ilivyoandikwa juu yake."'),
(2015222,69,41,9,14,'Walipowafikia wale wanafunzi wengine, waliona umati mkubwa wa watu hapo. Na baadhi ya walimu wa Sheria walikuwa wanajadiliana nao.'),
(2015223,69,41,9,15,'Mara tu ule umati wa watu ulipomwona, wote walishangaa sana, wakamkimbilia wamsalimu.'),
(2015224,69,41,9,16,'Yesu akawauliza, "Mnajadiliana nini nao?"'),
(2015225,69,41,9,17,'Hapo mtu mmoja katika ule umati wa watu akamjibu, "Mwalimu, nimemleta mwanangu kwako, ana pepo aliyemfanya kuwa bubu.'),
(2015226,69,41,9,18,'Kila mara anapomvamia, humwangusha chini na kumfanya atokwe na povu kinywani, akisaga meno na kuwa mkavu mwili wote. Niliwaomba wanafunzi wako wamtoe huyo pepo lakini hawakuweza."'),
(2015227,69,41,9,19,'Yesu akawaambia, "Enyi kizazi kisicho na imani! Nitakaa nanyi mpaka lini? Nitawavumilia mpaka lini? Mleteni kwangu."'),
(2015228,69,41,9,20,'Wakampeleka. Mara tu huyo pepo alipomwona Yesu, alimtia mtoto kifafa, naye mtoto akaanguka chini, akagaagaa na kutoka povu kinywani. Yesu akamwuliza baba yake huyo mtoto,'),
(2015229,69,41,9,21,'"Amepatwa na mambo hayo tangu lini?" Naye akamjibu, "Tangu utoto wake.'),
(2015230,69,41,9,22,'Na mara nyingi pepo huyo amemwangusha motoni na majini, ili amwangamize kabisa. Basi, ikiwa waweza, utuhurumie na kutusaidia!"'),
(2015231,69,41,9,23,'Yesu akamwambia, "Eti ikiwa waweza! Mambo yote yanawezekana kwa mtu aliye na imani."'),
(2015232,69,41,9,24,'Hapo, huyo baba akalia kwa sauti, "Naamini! Lakini imani yangu haitoshi, nisaidie!"'),
(2015233,69,41,9,25,'Yesu alipouona umati wa watu unaongezeka upesi mbele yake, alimkemea yule pepo mchafu, "Pepo unayemfanya huyu mtoto kuwa bubu-kiziwi, nakuamuru, mtoke mtoto huyu wala usimwingie tena!"'),
(2015234,69,41,9,26,'Hapo huyo pepo alipaaza sauti, akamwangusha huyo mtoto chini, kisha akamtoka. Mtoto alionekana kama maiti, hata wengine walisema, "Amekufa!"'),
(2015235,69,41,9,27,'Lakini Yesu akamshika mkono, akamwinua, naye akasimama.'),
(2015236,69,41,9,28,'Yesu alipoingia nyumbani, wanafunzi wake walimwuliza kwa faragha, "Kwa nini sisi hatukuweza kumtoa?"'),
(2015237,69,41,9,29,'Naye akawaambia, "Pepo wa aina hii hawezi kutoka isipokuwa kwa sala tu."'),
(2015238,69,41,9,30,'Yesu na wanafunzi wake waliondoka hapo, wakaendelea na safari kupitia wilaya ya Galilaya. Yesu hakupenda watu wajue alipokuwa,'),
(2015239,69,41,9,31,'kwa sababu alikuwa anawafundisha wanafunzi wake. Aliwaambia, "Mwana wa Mtu atakabidhiwa kwa watu ambao watamuua; lakini siku ya tatu baada ya kuuawa atafufuka."'),
(2015240,69,41,9,32,'Wanafunzi hawakufahamu jambo hilo. Wakaogopa kumwuliza.'),
(2015241,69,41,9,33,'Basi, walifika Kafarnaumu. Na alipokuwa nyumbani, aliwauliza, "Mlikuwa mnajadiliana nini njiani?"'),
(2015242,69,41,9,34,'Lakini wao wakanyamaza, maana njiani walikuwa wamebishana ni nani aliye mkuu kati yao.'),
(2015243,69,41,9,35,'Yesu akaketi chini, akawaita wale kumi na wawili, akawaambia, "Yeyote anayetaka kuwa wa kwanza lazima awe wa mwisho na kuwa mtumishi wa wote."'),
(2015244,69,41,9,36,'Kisha akamchukua mtoto mdogo, akamsimamisha kati yao, akamku mbatia, halafu akawaambia,'),
(2015245,69,41,9,37,'"Anayempokea mtoto kama huyu kwa jina langu, ananipokea mimi; na anayenipokea mimi, hanipokei mimi tu, bali anampokea yule aliyenituma."'),
(2015246,69,41,9,38,'Yohane akamwambia, "Mwalimu, tumemwona mtu mmoja akitoa pepo kwa kulitumia jina lako, nasi tukajaribu kumkataza kwa kuwa yeye si mmoja wetu."'),
(2015247,69,41,9,39,'Lakini Yesu akasema, "Msimkataze, maana hakuna mtu anayefanya muujiza kwa jina langu, na papo hapo akaweza kusema mabaya juu yangu.'),
(2015248,69,41,9,40,'Maana, asiyepingana nasi, yuko upande wetu.'),
(2015249,69,41,9,41,'Mtu yeyote atakeyewapeni kikombe cha maji ya kunywa kwa sababu ninyi ni watu wake Kristo, hakika hatakosa kupata tuzo lake.'),
(2015250,69,41,9,42,'"Mtu yeyote atakayemfanya mmoja wa hawa wadogo wanaoniamini atende dhambi, ingekuwa afadhali kwa mtu huyo kufungiwa shingoni mwake jiwe kubwa la kusagia na kutupwa baharini.'),
(2015251,69,41,9,43,'Mkono wako ukikukosesha, ukate! Afadhali kuingia kwenye uzima bila mkono mmoja, kuliko kuwa na mikono miwili na kwenda katika moto wa Jehanamu.*fe*'),
(2015252,69,41,9,44,'missing'),
(2015253,69,41,9,45,'Na mguu wako ukikukosesha, ukate! Afadhali kuingia katika uzima bila mguu mmoja, kuliko kuwa na miguu yote miwili na kutupwa katika moto wa Jehanamu.*ff*');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015254,69,41,9,46,'missing'),
(2015255,69,41,9,47,'Na jicho lako likikukosesha, ling`oe! Afadhali kuingia katika utawala wa Mungu ukiwa na jicho moja tu, kuliko kuwa na macho yako yote mawili na kutupwa katika moto wa Jehanamu.'),
(2015256,69,41,9,48,'Humo wadudu wake hawafi, na moto hauzimiki. ic\is Mawe ya kusagia (Marko 9:42)\ie moto hauzimiki. moto hauzimiki.'),
(2015257,69,41,9,49,'"Maana kila mmoja atakolezwa kwa moto.'),
(2015258,69,41,9,50,'Chumvi ni nzuri, lakini ikipoteza ladha yake, itakolezwa na nini? Muwe na chumvi ndani yenu na kudumisha amani kati yenu."'),
(2015259,69,41,10,1,'Yesu alitoka hapo akaenda mkoani Yudea na hata ng`ambo ya mto Yordani. Umati wa watu ukamwendea tena, naye akawafundisha tena kama ilivyokuwa desturi yake.'),
(2015260,69,41,10,2,'Basi, Mafarisayo wakamwendea, na kwa kumjaribu wakamwuliza, "Je, ni halali mtu kumpa talaka mkewe?"'),
(2015261,69,41,10,3,'Yesu akawajibu, "Mose aliwapa maagizo gani?"'),
(2015262,69,41,10,4,'Nao wakasema, "Mose aliagiza mume kumpatia mkewe hati ya talaka na kumwacha."'),
(2015263,69,41,10,5,'Yesu akawaambia, "Mose aliwaandikia amri hiyo kwa sababu ya ugumu wa mioyo yenu.'),
(2015264,69,41,10,6,'Lakini tangu kuumbwa ulimwengu, Mungu aliumba mwanamume na mwanamke.'),
(2015265,69,41,10,7,'Hivyo mwanamume atawaacha baba yake na mama yake, ataungana na mkewe,'),
(2015266,69,41,10,8,'nao wawili watakuwa mwili mmoja. Kwa hiyo, wao si wawili tena bali mwili mmoja.'),
(2015267,69,41,10,9,'Basi, alichounganisha Mungu, binadamu asitenganishe."'),
(2015268,69,41,10,10,'Walipoingia tena ndani ya nyumba, wanafunzi wake walimwuliza juu ya jambo hilo.'),
(2015269,69,41,10,11,'Naye akawaambia, "Anayemwacha mkewe na kuoa mwingine, anazini dhidi ya mkewe.'),
(2015270,69,41,10,12,'Na mwanamke anayemwacha mumewe na kuolewa na mwingine anazini."'),
(2015271,69,41,10,13,'Watu walimletea Yesu watoto wadogo ili awaguse, lakini wanafunzi wakawakemea.'),
(2015272,69,41,10,14,'Yesu alipoona hivyo, alikasirika akawaambia, "Waacheni hao watoto waje kwangu, wala msiwazuie, kwa maana Ufalme wa Mungu ni kwa ajili ya watu walio kama watoto hawa.'),
(2015273,69,41,10,15,'Nawaambieni kweli, mtu yeyote asiyeupokea Ufalme wa Mungu kama mtoto mdogo hataingia katika Ufalme huo."'),
(2015274,69,41,10,16,'Kisha akawapokea watoto hao, akawawekea mikono, akawabariki.'),
(2015275,69,41,10,17,'Yesu alipoanza tena safari yake, mtu mmoja alimjia mbio, akapiga magoti mbele yake, akamwuliza, "Mwalimu mwema, nifanyeje ili niupate uzima wa milele?"'),
(2015276,69,41,10,18,'Yesu akamjibu, "Mbona unaniita mwema? Hakuna aliye mwema ila Mungu peke yake.'),
(2015277,69,41,10,19,'Unazijua amri: `Usizini; Usiue; Usiibe; Usitoe ushahidi wa uongo; Usidanganye; Waheshimu baba na mama yako."`'),
(2015278,69,41,10,20,'Naye akamjibu, "Mwalimu, hayo yote nimeyazingatia tangu ujana wangu."'),
(2015279,69,41,10,21,'Yesu akamtazama, akampenda, akamwambia, "Umepungukiwa na kitu kimoja: nenda ukauze vitu ulivyo navyo, uwape maskini, nawe utakuwa na hazina mbinguni; kisha njoo unifuate."'),
(2015280,69,41,10,22,'Aliposikia hayo, alisikitika, akaenda zake akiwa na huzuni, kwa maana alikuwa na mali nyingi.'),
(2015281,69,41,10,23,'Yesu akatazama pande zote, akawaambia wanafunzi wake, "Jinsi gani itakavyokuwa vigumu kwa matajiri kuingia katika Ufalme wa Mungu!"'),
(2015282,69,41,10,24,'Wanafunzi walishangazwa na maneno yake. Yesu akawaambia tena, "Watoto wangu, ni vigumu sana kuingia katika Ufalme wa Mungu!'),
(2015283,69,41,10,25,'Ni rahisi zaidi ngamia kupenya katika tundu la sindano, kuliko tajiri kuingia katika Ufalme wa Mungu."'),
(2015284,69,41,10,26,'Wanafunzi wake wakashangaa sana wakaulizana, "Ni nani basi, atakayeweza kuokoka?"'),
(2015285,69,41,10,27,'Yesu akawatazama, akawaambia, "Kwa binadamu haiwezekani, lakini kwa Mungu si hivyo, maana kwa Mungu mambo yote huwezekana."'),
(2015286,69,41,10,28,'Petro akamwambia, "Na sisi je? Tumeacha yote, tukakufuata!"'),
(2015287,69,41,10,29,'Yesu akasema, "Kweli nawaambieni, kila mtu aliyeacha nyumba, au ndugu, au dada, au mama, au baba, au watoto au mashamba kwa ajili yangu na kwa ajili ya Habari Njema,'),
(2015288,69,41,10,30,'atapokea mara mia zaidi wakati huu wa sasa nyumba, ndugu, dada, mama, watoto na mashamba pamoja na mateso; na katika wakati ujao atapokea uzima wa milele.'),
(2015289,69,41,10,31,'Lakini wengi walio wa kwanza watakuwa wa mwisho, na walio wa mwisho watakuwa wa kwanza."'),
(2015290,69,41,10,32,'Basi, walikuwa njiani kwenda Yerusalemu, na Yesu alikuwa anawatangulia. Wanafunzi wake walijawa na hofu, na watu waliofuata waliogopa. Yesu akawachukua tena kando wale kumi na wawili, akaanza kuwaambia yale yatakayompata:'),
(2015291,69,41,10,33,'"Sikilizeni! Tunakwenda Yerusalemu, na huko Mwana wa Mtu atakabidhiwa kwa makuhani wakuu na walimu wa Sheria, nao watamhukumu auawe na kumkabidhi kwa watu wa mataifa.'),
(2015292,69,41,10,34,'Nao watamdhihaki; watamtemea mate, watampiga mijeledi na kumwua. Na baada ya siku tatu atafufuka."'),
(2015293,69,41,10,35,'Yakobo na Yohane, wana wa Zebedayo, walimwendea Yesu wakamwambia, "Mwalimu, tunataka utufanyie kitu tutakachokuomba."'),
(2015294,69,41,10,36,'Yesu akawauliza, "Mnataka niwafanyie nini?"'),
(2015295,69,41,10,37,'Wakamjibu, "Uturuhusu tuketi mmoja upande wako wa kulia na mwingine upande wako wa kushoto katika utukufu wa Ufalme wako."'),
(2015296,69,41,10,38,'Yesu akawaambia, "Hamjui mnachoomba! Je, mnaweza kunywa kikombe nitakachokunywa, au kubatizwa kama nitakavyobatizwa?"'),
(2015297,69,41,10,39,'Wakamjibu, "Tunaweza." Yesu akawaambia, "Kikombe nitakachokunywa mtakinywa kweli, na mtabatizwa kama nitakavyobatizwa.'),
(2015298,69,41,10,40,'Lakini ni nani atakayeketi kulia au kushoto kwangu si wajibu wangu kupanga, bali nafasi hizo watapewa wale waliotayarishiwa."'),
(2015299,69,41,10,41,'Wale wanafunzi wengine kumi waliposikia hayo, walianza kuchukizwa na Yakobo na Yohane.'),
(2015300,69,41,10,42,'Yesu akawaita, akawaambia, "Mnajua kwamba wale wanaofikiriwa kuwa watawala wa mataifa huwatawala watu wao kwa mabavu, na wakuu hao huwamiliki watu wao.'),
(2015301,69,41,10,43,'Lakini kwenu isiwe hivyo, ila anayetaka kuwa mkuu kati yenu, sharti awe mtumishi wenu.'),
(2015302,69,41,10,44,'Anayetaka kuwa wa kwanza, sharti awe mtumishi wa wote.'),
(2015303,69,41,10,45,'Maana Mwana wa Mtu hakuja kutumikiwa, ila alikuja kutumikia, na kutoa maisha yake kuwa fidia ya watu wengi."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015304,69,41,10,46,'Basi, wakafika Yeriko, naye Yesu alipokuwa anatoka katika mji huo akiwa na wanafunzi wake pamoja na umati mkubwa wa watu, kipofu mwombaji aitwaye Bartimayo mwana wa Timayo alikuwa ameketi kando ya barabara.'),
(2015305,69,41,10,47,'Aliposikia kwamba ni Yesu wa Nazareti aliyekuwa anapita mahali hapo, alianza kupaaza sauti, "Yesu, Mwana wa Daudi, nihurumie!"'),
(2015306,69,41,10,48,'Watu wengi walimkemea ili anyamaze, lakini yeye akazidi kupaaza sauti, "Mwana wa Daudi, nihurumie!"'),
(2015307,69,41,10,49,'Yesu alisimama, akasema, "Mwiteni." Basi, wakamwita huyo kipofu, wakamwambia, "Jipe moyo! Simama, anakuita."'),
(2015308,69,41,10,50,'Naye akatupilia mbali vazi lake, akaruka juu, akamwendea Yesu.'),
(2015309,69,41,10,51,'Yesu akamwuliza, "Unataka nikufanyie nini?" Huyo kipofu akamwambia, "Mwalimu, naomba nipate kuona."'),
(2015310,69,41,10,52,'Yesu akamwambia, "Nenda, imani yako imekuponya." Mara huyo kipofu akaweza kuona, akamfuata Yesu njiani.'),
(2015311,69,41,11,1,'Walipokuwa wanakaribia Yerusalemu walifika Bethfage na Bethania, karibu na mlima wa Mizeituni. Hapo aliwatuma wawili wa wanafunzi wake,'),
(2015312,69,41,11,2,'akawaambia, "Nendeni katika kijiji kilicho mbele yenu. Mtakapokuwa mnaingia humo, mtakuta mwana punda amefungwa ambaye bado hajatumiwa na mtu. Mfungueni mkamlete.'),
(2015313,69,41,11,3,'Kama mtu akiwauliza, `Mbona mnafanya hivyo?` Mwambieni, `Bwana anamhitaji na atamrudisha hapa mara."` ic\is Bethania (Marko 11:1)\ie'),
(2015314,69,41,11,4,'Basi, wakaenda, wakamkuta mwana punda barabarani amefungwa mlangoni. Walipokuwa wakimfungua,'),
(2015315,69,41,11,5,'baadhi ya watu waliokuwa wamesimama hapo wakawauliza "Kwa nini mnamfungua huyo mwana punda?"'),
(2015316,69,41,11,6,'Wanafunzi wakajibu kama Yesu alivyokuwa amewaambia; nao wakawaacha waende zao.'),
(2015317,69,41,11,7,'Wakampelekea Yesu huyo mwana punda. Wakatandika mavazi yao juu ya huyo mwana punda, na Yesu akaketi juu yake.'),
(2015318,69,41,11,8,'Watu wengi wakatandaza mavazi yao barabarani; wengine wakatandaza matawi ya miti waliyoyakata mashambani.'),
(2015319,69,41,11,9,'Watu wote waliotangulia na wale waliofuata wakapaaza sauti zao wakisema, "Hosana! Abarikiwe huyo ajaye kwa jina la Bwana!'),
(2015320,69,41,11,10,'Ubarikiwe Ufalme ujao wa baba yetu Daudi. Hosana juu mbinguni!"'),
(2015321,69,41,11,11,'Yesu aliingia mjini Yerusalemu akaenda moja kwa moja mpaka Hekaluni, akatazama kila kitu kwa makini. Lakini kwa vile ilikwisha kuwa jioni, akaenda Bethania pamoja na wale kumi na wawili.'),
(2015322,69,41,11,12,'Kesho yake, walipokuwa wanatoka Bethania, Yesu aliona njaa.'),
(2015323,69,41,11,13,'Basi, akaona kwa mbali mtini wenye majani mengi. Akauendea ili aone kama ulikuwa na tunda lolote. Alipoufikia, aliukuta bila tunda lolote ila majani matupu, kwa vile hayakuwa majira ya mtini kuzaa matunda.'),
(2015324,69,41,11,14,'Hapo akauambia mtini, "Tangu leo hata milele mtu yeyote asile matunda kwako." Nao wanafunzi wake walisikia maneno hayo.'),
(2015325,69,41,11,15,'Basi, wakafika Yerusalemu. Yesu akaingia Hekaluni, akaanza kuwafukuza nje watu waliokuwa wanauza na kununua vitu humo ndani. Akazipindua meza za wale waliokuwa wakibadilishana fedha na viti vya wale waliokuwa wakiuza njiwa.'),
(2015326,69,41,11,16,'Hakumruhusu mtu yeyote kupitia Hekaluni akichukua kitu.'),
(2015327,69,41,11,17,'Kisha akawafundisha, "Imeandikwa: `Nyumba yangu itaitwa nyumba ya sala kwa ajili ya mataifa yote!` Lakini ninyi mmeifanya kuwa pango la wanyang`anyi!"'),
(2015328,69,41,11,18,'Makuhani wakuu na walimu wa Sheria waliposikia hayo, walianza kutafuta njia ya kumwangamiza. Lakini walimwogopa kwa sababu umati wa watu ulishangazwa na mafundisho yake.'),
(2015329,69,41,11,19,'Ilipokuwa jioni, Yesu na wanafunzi wake waliondoka mjini.'),
(2015330,69,41,11,20,'Asubuhi na mapema, walipokuwa wanapita, waliuona ule mtini umenyauka wote, hata mizizi.'),
(2015331,69,41,11,21,'Petro aliukumbuka, akamwambia Yesu, "Mwalimu, tazama! Ule mtini ulioulaani, umenyauka!"'),
(2015332,69,41,11,22,'Yesu akawaambia, "Mwaminini Mungu.'),
(2015333,69,41,11,23,'Nawaambieni kweli, mtu akiuambia mlima huu: `Ng`oka ukajitose baharini` bila kuona shaka moyoni mwake, ila akaamini kwamba mambo yote anayosema yanafanyika, atafanyiwa jambo hilo.'),
(2015334,69,41,11,24,'Kwa hiyo nawaambieni, mnaposali na kuomba kitu, aminini kwamba mmekipokea, nanyi mtapewa.'),
(2015335,69,41,11,25,'Mnaposimama kusali, sameheni kila mtu aliyewakosea chochote, ili Baba yenu aliye mbinguni awasamehe ninyi makosa yenu.*fg* hata Baba yenu aliye mbinguni hatawasamehe ninyi makosa yenu."'),
(2015336,69,41,11,26,'missing'),
(2015337,69,41,11,27,'Basi, wakafika tena Yerusalemu. Yesu alipokuwa akitembea Hekaluni, makuhani wakuu, walimu wa Sheria na wazee walimwendea,'),
(2015338,69,41,11,28,'wakamwuliza, "Unafanya mambo haya kwa mamlaka gani? Nani aliyekupa mamlaka ya kufanya mambo haya?"'),
(2015339,69,41,11,29,'Lakini Yesu akawaambia, "Nitawaulizeni swali moja; mkinijibu, na pia nitawaambieni ni kwa mamlaka gani ninafanya mambo haya.'),
(2015340,69,41,11,30,'Je, mamlaka ya Yohane ya kubatiza yalitoka mbinguni ama kwa watu? Nijibuni."'),
(2015341,69,41,11,31,'Wakaanza kujadiliana, "Tukisema, `Yalitoka mbinguni`, atatuuliza, `Basi, mbona hamkumsadiki?`'),
(2015342,69,41,11,32,'Na tukisema, `Yalitoka kwa watu..."` (Waliogopa umati wa watu maana wote waliamini kwamba Yohane alikuwa kweli nabii.)'),
(2015343,69,41,11,33,'Basi, wakamjibu Yesu, "Sisi hatujui." Naye Yesu akawaambia, "Nami pia sitawaambieni ninafanya mambo haya kwa mamlaka gani."'),
(2015344,69,41,12,1,'Yesu alianza kusema nao kwa mifano: "Mtu mmoja alilima shamba la mizabibu. Akalizungushia ukuta, na katikati yake akachimba kisima cha kusindikia divai, akajenga mnara pia. Akalikodisha shamba hilo kwa wakulima, akasafiri hadi nchi ya mbali.'),
(2015345,69,41,12,2,'Wakati wa mavuno, alimtuma mtumishi wake kwa wale wakulima akamletee sehemu ya mazao ya shamba lake.'),
(2015346,69,41,12,3,'Wale wakulima wakamkamata, wakampiga, wakamrudisha mikono mitupu.'),
(2015347,69,41,12,4,'Akatuma tena mtumishi mwingine; huyu wakamuumiza kichwa na kumtendea vibaya.'),
(2015348,69,41,12,5,'Mwenye shamba akatuma mtumishi mwingine tena, na huyo wakamuua. Wengine wengi waliotumwa, baadhi yao walipigwa, na wengi wakauawa.'),
(2015349,69,41,12,6,'Alibakiwa bado na mtu mmoja, yaani mwanawe mpendwa. Mwishowe akamtuma huyo akisema, `Watamheshimu mwanangu.`'),
(2015350,69,41,12,7,'Lakini hao wakulima wakaambiana, `Huyu ndiye mrithi, basi, tumuue ili urithi wake uwe wetu!`'),
(2015351,69,41,12,8,'Kwa hiyo wakamkamata, wakamuua na kumtupa nje ya lile shamba la mizabibu. ic Mnara ndani ya shamba la mizabibu (Marko 12:1)'),
(2015352,69,41,12,9,'"Basi, mwenye shamba atafanya nini? Atakuja kuwaangamiza hao wakulima na kulikodisha hilo shamba la mizabibu kwa watu wengine.'),
(2015353,69,41,12,10,'Je, hamjasoma Maandiko haya? `Jiwe walilokataa waashi sasa limekuwa jiwe kuu la msingi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015354,69,41,12,11,'Bwana ndiye aliyefanya jambo hili, nalo ni la ajabu sana kwetu."`'),
(2015355,69,41,12,12,'Makuhani wakuu, walimu wa Sheria na wazee walifahamu ya kwamba mfano huo ulikuwa unawahusu. Kwa hiyo walijaribu kumtia nguvuni, lakini waliogopa umati wa watu. Basi, wakamwacha wakaenda zao.'),
(2015356,69,41,12,13,'Basi, baadhi ya Mafarisayo na wafuasi wa kikundi cha Herode walitumwa ili wamtege Yesu kwa maneno yake.'),
(2015357,69,41,12,14,'Wakamwendea, wakamwambia, "Mwalimu, tunajua kwamba wewe ni mtu mwaminifu unayesema ukweli mtupu, wala humjali mtu yeyote. Wala cheo cha mtu si kitu kwako, lakini wafundisha ukweli kuhusu njia ya Mungu. Je, ni halali kulipa kodi kwa Kaisari, au la? Tulipe au tusilipe?"'),
(2015358,69,41,12,15,'Lakini Yesu alijua unafiki wao, akawaambia, "Mbona mnanijaribu? Nionyesheni sarafu."'),
(2015359,69,41,12,16,'Wakamwonyesha. Naye akawauliza, "Sura na chapa hii ni ya nani?" Wakamjibu, "Ni ya Kaisari."'),
(2015360,69,41,12,17,'Basi, Yesu akawaambia, "Mpeni Kaisari yaliyo yake Kaisari na Mungu yaliyo yake Mungu." Wakashangazwa sana naye.'),
(2015361,69,41,12,18,'Masadukayo wasemao kwamba hakuna ufufuo walimwendea Yesu, wakamwuliza,'),
(2015362,69,41,12,19,'"Mwalimu, Mose alituagiza hivi: `Mtu akifa na kuacha mke bila mtoto, ndugu yake lazima amchukue huyo mama mjane amzalie watoto ndugu yake marehemu.`'),
(2015363,69,41,12,20,'Basi, kulikuwa na ndugu saba. Wa kwanza alioa, akafa bila kuacha mtoto.'),
(2015364,69,41,12,21,'Ndugu wa pili akamwoa huyo mjane, naye pia akafa bila kuacha mtoto; na ndugu watatu hali kadhalika.'),
(2015365,69,41,12,22,'Wote saba walikufa bila kuacha mtoto. Mwishowe yule mama mjane naye akafa.'),
(2015366,69,41,12,23,'Basi, siku watu watakapofufuka, mama huyo atakuwa mke wa nani? Maana wote saba walikuwa wamemwoa."'),
(2015367,69,41,12,24,'Yesu akawaambia, "Ninyi mmekosea sana, kwa sababu hamjui Maandiko Matakatifu wala nguvu ya Mungu.'),
(2015368,69,41,12,25,'Maana wafu watakapofufuka, hawataoa wala kuolewa; watakuwa kama malaika wa mbinguni.'),
(2015369,69,41,12,26,'Lakini kuhusu kufufuliwa kwa wafu, je, hamjasoma kitabu cha Mose katika sehemu inayohusu kile kichaka kilichokuwa kinawaka moto? Mungu alimwambia Mose, `Mimi ni Mungu wa Abrahamu, Mungu wa Isaka, na Mungu wa Yakobo.`'),
(2015370,69,41,12,27,'Basi, yeye si Mungu wa wafu, bali ni Mungu wa walio hai. Ninyi mmekosea sana!"'),
(2015371,69,41,12,28,'Mmojawapo wa walimu wa Sheria alifika, akasikia mabishano yao. Alipoona kwamba Yesu aliwajibu vyema, akajitokeza akamwuliza, "Katika amri zote ni ipi iliyo ya kwanza?"'),
(2015372,69,41,12,29,'Yesu akamjibu, "Ya kwanza ndiyo hii: `Sikiliza, Israeli! Bwana Mungu wetu ndiye peke yake Bwana.'),
(2015373,69,41,12,30,'Mpende Bwana Mungu wako kwa moyo wako wote, kwa roho yako yote, kwa akili yako yote na kwa nguvu zako zote.`'),
(2015374,69,41,12,31,'Na ya pili ndiyo hii: `Mpende jirani yako kama unavyojipenda mwenyewe.` Hakuna amri nyingine iliyo kuu kuliko hizi."'),
(2015375,69,41,12,32,'Basi, yule mwalimu wa Sheria akamwambia, "Vyema Mwalimu! Umesema kweli kwamba Mungu ni mmoja tu wala hakuna mwingine ila yeye.'),
(2015376,69,41,12,33,'Na ni lazima mtu kumpenda Mungu kwa moyo wote, kwa akili yote, na kwa nguvu zote, na kumpenda jirani yake kama anavyojipenda mwenyewe. Jambo hili ni muhimu zaidi kuliko dhabihu na sadaka zote za kuteketezwa."'),
(2015377,69,41,12,34,'Yesu alipoona kwamba huyu mtu alimjibu kwa ujasiri, akamwambia, "Wewe huko mbali na Ufalme wa Mungu." Baada ya hayo, hakuna mtu aliyethubutu tena kumwuliza kitu.'),
(2015378,69,41,12,35,'Wakati Yesu alipokuwa akifundisha Hekaluni, aliuliza, "Mbona walimu wa Sheria wanasema ya kwamba Kristo ni mwana wa Daudi?'),
(2015379,69,41,12,36,'Daudi mwenyewe akiongozwa na Roho Mtakatifu alisema: `Bwana alimwambia Bwana wangu: Keti upande wangu wa kulia, Mpaka nitakapowaweka adui zako chini ya miguu yako."`'),
(2015380,69,41,12,37,'"Daudi mwenyewe anamwita Kristo Bwana. Basi, Kristo atakuwaje mwanae?" Umati wa watu ulikuwa ukimsikiliza kwa furaha.'),
(2015381,69,41,12,38,'Katika mafundisho yake, Yesu alisema, "Jihadharini na walimu wa Sheria ambao hupenda kupitapita wamejivalia kanzu ndefu na kusalimiwa na watu kwa heshima sokoni; hupenda kuketi mahali pa heshima katika masunagogi,'),
(2015382,69,41,12,39,'na kuchukua nafasi za heshima katika karamu.'),
(2015383,69,41,12,40,'Huwanyonya wajane huku wakijisingizia kusali sala ndefu. Siku ya hukumu watapata adhabu kali!"'),
(2015384,69,41,12,41,'Yesu alikuwa ameketi karibu na sanduku la hazina. Akawa anatazama jinsi watu wengi walivyokuwa wakitoa fedha na kuzitia katika hazina ya Hekalu. Matajiri wengi walitoa fedha nyingi.'),
(2015385,69,41,12,42,'Hapo akaja mama mmoja mjane maskini, akatoa sarafu mbili ndogo za fedha.'),
(2015386,69,41,12,43,'Yesu akawaita wanafunzi wake, akawaambia, "Kweli nawaambieni, huyu mama mjane maskini ametoa zaidi kuliko wengine wote waliotia fedha katika sanduku la hazina.'),
(2015387,69,41,12,44,'Maana wote walitoa kutokana na ziada ya mali zao, lakini huyu mama, ingawa ni maskini, ametoa yote aliyokuwa nayo, ametoa kila kitu alichohitaji kwa kuishi."'),
(2015388,69,41,13,1,'Yesu alipokuwa anatoka Hekaluni, mmoja wa wanafunzi wake alimwambia, "Mwalimu, tazama jinsi mawe haya na majengo haya yalivyo ya ajabu!"'),
(2015389,69,41,13,2,'Yesu akamwambia, "Je, unayaona majengo haya makubwa? Hakuna hata jiwe moja litakalosalia juu ya lingine; kila kitu kitabomolewa."'),
(2015390,69,41,13,3,'Yesu alipokuwa ameketi juu ya mlima wa Mizeituni akielekea Hekalu, Petro, Yakobo, Yohane na Andrea wakamwuliza kwa faragha,'),
(2015391,69,41,13,4,'"Twambie mambo haya yatatukia lini? Ni ishara gani itakayoonyesha kwamba mambo haya karibu yatimizwe?"'),
(2015392,69,41,13,5,'Yesu akaanza kuwaambia, "Jihadharini msije mkadanganywa na mtu.'),
(2015393,69,41,13,6,'Maana wengi watakuja wakilitumia jina langu, wakisema, `Mimi ndiye!` nao watawapotosha watu wengi.'),
(2015394,69,41,13,7,'Mtakaposikia juu ya vita na fununu za vita, msifadhaike. Mambo hayo lazima yatokee, lakini mwisho wenyewe ungali bado.'),
(2015395,69,41,13,8,'Taifa moja litapigana na taifa lingine; utawala mmoja utapigana na utawala mwingine; kila mahali kutakuwa na mitetemeko ya ardhi na njaa. Mambo haya ni kama tu maumivu ya kwanza ya kujifungua mtoto.'),
(2015396,69,41,13,9,'"Lakini ninyi jihadharini. Maana watu watawapelekeni mahakamani, na kuwapigeni katika masunagogi. Mtapelekwa mbele ya watawala na wafalme kwa sababu yangu ili mpate kunishuhudia kwao.'),
(2015397,69,41,13,10,'Lakini lazima kwanza Habari Njema ihubiriwe kwa mataifa yote.'),
(2015398,69,41,13,11,'Nao watakapowatieni nguvuni na kuwapeleka mahakamani, msiwe na wasiwasi juu ya yale mtakayosema; saa ile itakapofika, semeni chochote mtakachopewa, maana si ninyi mtakaosema, bali Roho Mtakatifu.'),
(2015399,69,41,13,12,'Ndugu atamsaliti ndugu yake auawe; baba atamsaliti mwanae; watoto watawashambulia wazazi wao na kuwaua.'),
(2015400,69,41,13,13,'Watu wote watawachukieni ninyi kwa sababu ya jina langu. Lakini atakayevumilia mpaka mwisho ndiye atakayeokolewa.'),
(2015401,69,41,13,14,'"Mtakapoona `Chukizo Haribifu` limesimama mahali ambapo si pake, (msomaji na atambue maana yake!) Hapo watu walioko Yudea wakimbilie milimani.'),
(2015402,69,41,13,15,'Mtu aliye juu ya paa la nyumba asishuke kuingia nyumbani mwake kuchukua kitu.'),
(2015403,69,41,13,16,'Aliye shambani asirudi nyuma kuchukua vazi lake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015404,69,41,13,17,'Ole wao waja wazito na wanaonyonyesha siku hizo!'),
(2015405,69,41,13,18,'Ombeni ili mambo hayo yasitukie nyakati za baridi.'),
(2015406,69,41,13,19,'Maana wakati huo kutakuwa na dhiki ambayo haijatokea tangu Mungu alipoumba ulimwengu mpaka leo, wala haitatokea tena.'),
(2015407,69,41,13,20,'Kama Bwana asingepunguza siku hizo, hakuna binadamu ambaye angeokolewa. Lakini kwa ajili ya wateule wake, Bwana amezipunguza siku hizo.'),
(2015408,69,41,13,21,'"Basi mtu akiwaambieni, `Tazama, Kristo yupo hapa!` au `Yupo pale!` msimsadiki.'),
(2015409,69,41,13,22,'Maana watatokea kina Kristo wa uongo na manabii wa uongo, watafanya ishara na maajabu, ili kuwapotosha wateule wa Mungu, kama ikiwezekana.'),
(2015410,69,41,13,23,'Lakini ninyi jihadharini. Mimi nimewaambieni mambo yote kabla hayajatokea.'),
(2015411,69,41,13,24,'"Basi, siku hizo baada ya dhiki hiyo, jua litatiwa giza na mwezi hautaangaza.'),
(2015412,69,41,13,25,'Nyota zitaanguka kutoka angani, na nguvu za mbingu zitatikiswa.'),
(2015413,69,41,13,26,'Hapo watamwona Mwana wa Mtu akija katika mawingu kwa nguvu nyingi na utukufu.'),
(2015414,69,41,13,27,'Kisha atawatuma malaika wake; atawakusanya wateule wake kutoka pande zote nne za dunia, kutoka mwisho wa dunia mpaka mwisho wa mbingu.'),
(2015415,69,41,13,28,'"Kwa mtini jifunzeni mfano huu: Mara tu matawi yake yanapoanza kuwa laini na kuchanua majani, mnajua kwamba wakati wa kiangazi umekaribia.'),
(2015416,69,41,13,29,'Hali kadhalika nanyi mtakapoona mambo hayo yakitendeka, jueni kwamba Mwana wa Mtu yuko karibu sana.'),
(2015417,69,41,13,30,'Nawaambieni kweli, kizazi hiki hakitapita kabla ya mambo hayo yote kutukia.'),
(2015418,69,41,13,31,'Mbingu na dunia zitapita, lakini maneno yangu hayatapita kamwe.'),
(2015419,69,41,13,32,'"Lakini hakuna mtu ajuaye siku au saa hiyo itakuja lini; wala malaika wa mbinguni, wala Mwana; Baba peke yake ndiye ajuaye.'),
(2015420,69,41,13,33,'Muwe waangalifu na kesheni, maana hamjui wakati huo utafika lini.'),
(2015421,69,41,13,34,'Itakuwa kama mtu anayeondoka nyumbani kwenda safari akiwaachia watumishi wake madaraka, kila mmoja na kazi yake; akamwambia mlinzi wa mlango awe macho.'),
(2015422,69,41,13,35,'Kesheni, basi, kwa maana hamjui mwenye nyumba atarudi lini; huenda ikawa jioni, usiku wa manane, alfajiri au asubuhi.'),
(2015423,69,41,13,36,'Kesheni ili akija ghafla asije akawakuta mmelala.'),
(2015424,69,41,13,37,'Ninayowaambieni ninyi, nawaambia wote: Kesheni!"'),
(2015425,69,41,14,1,'Ilikuwa siku mbili tu kabla ya sikukuu ya Pasaka na ya Mikate Isiyotiwa Chachu. Makuhani wakuu na walimu wa Sheria walikuwa wakitafuta njia ya kumtia Yesu nguvuni kwa hila wamuue.'),
(2015426,69,41,14,2,'Lakini walisema, "Tusimtie nguvuni wakati wa sikukuu, watu wasije wakafanya ghasia."'),
(2015427,69,41,14,3,'Yesu alikuwa Bethania, nyumbani kwa Simoni, Mkoma. Alipokuwa mezani kula chakula, mama mmoja aliyekuwa na chupa ya alabasta yenye marashi ya nardo safi ya thamani kubwa alikuja, akaivunja hiyo chupa, akammiminia Yesu marashi hayo kichwani.'),
(2015428,69,41,14,4,'Baadhi ya watu waliokuwa hapo walikasirika wakajisemea, "Kwa nini kupoteza ovyo marashi haya?'),
(2015429,69,41,14,5,'Yangaliweza kuuzwa kwa fedha kiasi cha denari mia tatu, wakapewa maskini!" Wakamkemea huyo mama.'),
(2015430,69,41,14,6,'Lakini Yesu akawaambia, "Mwacheni; kwa nini mnamsumbua? Amenitendea jambo jema.'),
(2015431,69,41,14,7,'Maskini mnao daima pamoja nanyi; mnaweza kuwasaidia wakati wowote mnaopenda. Lakini mimi sitakuwapo pamoja nanyi daima.'),
(2015432,69,41,14,8,'Yeye amefanya alivyoweza; ameupaka mwili wangu marashi kuutayarisha kwa maziko.'),
(2015433,69,41,14,9,'Nawaambieni kweli, popote ulimwenguni Habari Njema itakapohubiriwa, kitendo hiki alichofanya kitatajwa kwa ajili ya kumkumbuka."'),
(2015434,69,41,14,10,'Kisha Yuda Iskarioti, mmoja wa wale kumi na wawili, alienda kwa makuhani wakuu ili kumsaliti Yesu.'),
(2015435,69,41,14,11,'Makuhani wakuu waliposikia habari hiyo, walifurahi, wakaahidi kumpa fedha. Basi, Yuda akaanza kutafuta nafasi ya kumsaliti Yesu.'),
(2015436,69,41,14,12,'Siku ya kwanza ya sikukuu ya Mikate Isiyotiwa Chachu, wakati ambapo mwana kondoo wa Pasaka huchinjwa, wanafunzi wake walimwuliza, "Wataka tukuandalie wapi karamu ya Pasaka?"'),
(2015437,69,41,14,13,'Basi Yesu akawatuma wawili wa wanafunzi wake akiwaambia, "Nendeni mjini, nanyi mtakutana na mtu anayebeba mtungi wa maji. Mfuateni'),
(2015438,69,41,14,14,'mpaka katika nyumba atakayoingia, mkamwambie mwenye nyumba, `Mwalimu anasema: wapi chumba changu ambamo nitakula Pasaka pamoja na wanafunzi wangu?`'),
(2015439,69,41,14,15,'Naye atawaonyesha chumba kikubwa ghorofani kilichotayarishwa na kupambwa. Tuandalieni humo."'),
(2015440,69,41,14,16,'Wanafunzi wakaondoka, wakaenda mjini, wakakuta kila kitu sawa kama Yesu alivyokuwa amewaambia. Wakaandaa karamu ya Pasaka.'),
(2015441,69,41,14,17,'Ilipokuwa jioni, Yesu alifika pamoja na wanafunzi wake kumi na wawili.'),
(2015442,69,41,14,18,'Walipokuwa mezani wakila, Yesu alisema, "Kweli nawaambieni, mmoja wenu anayekula pamoja nami, atanisaliti."'),
(2015443,69,41,14,19,'Hapo wanafunzi wake wakaanza kuhuzunika, wakamwuliza mmojammoja, "Je, ni mimi?"'),
(2015444,69,41,14,20,'Yesu akawaambia, "Ni mmoja wenu ninyi kumi na wawili, anayechovya mkate pamoja nami katika bakuli.'),
(2015445,69,41,14,21,'Kweli Mwana wa Mtu anakwenda zake kama Maandiko Matakatifu yanavyosema juu yake; lakini, ole wake mtu yule anayemsaliti Mwana wa Mtu! Ingalikuwa afadhali kwa mtu huyo kama hangalizaliwa!"'),
(2015446,69,41,14,22,'Walipokuwa wanakula, Yesu alitwaa mkate, akashukuru, akaumega na kuwapa wanafunzi wake akisema, "Twaeni; huu ni mwili wangu."'),
(2015447,69,41,14,23,'Kisha akatwaa kikombe, akamshukuru Mungu, akawapa; nao wote wakanywa katika kikombe hicho.'),
(2015448,69,41,14,24,'Akawaambia, "Hii ni damu yangu inayothibitisha agano la Mungu, damu inayomwagwa kwa ajili ya watu wengi.'),
(2015449,69,41,14,25,'Kweli nawaambieni, sitakunywa tena divai ya zabibu mpaka siku ile nitakapoinywa upya katika Ufalme wa Mungu."'),
(2015450,69,41,14,26,'Kisha wakaimba wimbo, wakaondoka, wakaenda katika mlima wa Mizeituni.'),
(2015451,69,41,14,27,'Yesu akawaambia wanafunzi wake, "Ninyi nyote mtakuwa na mashaka nami; maana Maandiko Matakatifu yasema: `Nitampiga mchungaji nao kondoo watatawanyika.`'),
(2015452,69,41,14,28,'Lakini nikisha fufuka, nitawatangulieni kule Galilaya."'),
(2015453,69,41,14,29,'Petro akamwambia "Hata kama wote watakuwa na mashaka nawe na kukuacha, mimi sitakukana kamwe!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015454,69,41,14,30,'Yesu akamwambia, "Kweli nakwambia, usiku huu, kabla jogoo hajawika mara mbili, utanikana mara tatu."'),
(2015455,69,41,14,31,'Lakini Petro akasisitiza, "Hata kama ni lazima nife pamoja nawe, sitakuacha kamwe." Wanafunzi wote pia wakasema vivyo hivyo.'),
(2015456,69,41,14,32,'Basi, wakafika katika bustani iitwayo Gethsemane. Yesu akawaambia wanafunzi wake, "Kaeni hapa wakati mimi nasali."'),
(2015457,69,41,14,33,'Kisha akawachukua Petro, Yakobo na Yohane; akaanza kufadhaika sana na kuhangaika.'),
(2015458,69,41,14,34,'Akawaambia, "Nina huzuni kubwa moyoni hata karibu kufa. Kaeni hapa mkeshe."'),
(2015459,69,41,14,35,'Akaenda mbele kidogo, akajitupa chini kifudifudi, akasali kwamba, kama ingewezekana, asiipitie saa hiyo ya mateso.'),
(2015460,69,41,14,36,'Akasema, "Baba yangu, kwako mambo yote yanawezekana. Uniondolee kikombe hiki; lakini isiwe kama nitakavyo mimi, bali utakavyo wewe." ic\is Bustani ya Gethsemane (Marko 14:32)\ie'),
(2015461,69,41,14,37,'Kisha akarudi kwa wanafunzi wale watatu, akawakuta wamelala. Basi, akamwuliza Petro, "Simoni, je umelala? Hukuweza kukesha hata saa moja?"'),
(2015462,69,41,14,38,'Kisha akawaambia, "Kesheni na kusali ili msije mkaingia katika majaribu. Roho i radhi, lakini mwili ni dhaifu."'),
(2015463,69,41,14,39,'Akaenda kusali tena akirudia maneno yaleyale.'),
(2015464,69,41,14,40,'Kisha akarudi tena, akawakuta wamelala. Macho yao yalikuwa yamebanwa na usingizi. Hawakujua la kumjibu.'),
(2015465,69,41,14,41,'Alipowajia mara ya tatu aliwaambia, "Mnalala bado na kupumzika? Sasa imetosha! Saa imefika! Mwana wa Mtu anakabidhiwa kwa watu waovu.'),
(2015466,69,41,14,42,'Amkeni, twendeni zetu. Tazameni, yule atakayenisaliti amekaribia."'),
(2015467,69,41,14,43,'Yesu alipokuwa bado anasema, Yuda, mmoja wa wale kumi na wawili, akafika pamoja na umati wa watu wenye mapanga na marungu. Watu hao walikuwa wametumwa na makuhani wakuu, walimu wa Sheria na wazee.'),
(2015468,69,41,14,44,'Msaliti Yuda alikuwa amewapa ishara: "Yule nitakayembusu ndiye; mkamateni, mkampeleke chini ya ulinzi."'),
(2015469,69,41,14,45,'Yuda alipofika tu, alimwendea Yesu moja kwa moja, akasema, "Mwalimu!" Kisha akambusu.'),
(2015470,69,41,14,46,'Basi, hao watu wakamkamata Yesu, wakamtia nguvuni.'),
(2015471,69,41,14,47,'Mmoja wa wale waliokuwa wamesimama hapo pamoja na Yesu akauchomoa upanga wake, akampiga mtumishi wa Kuhani Mkuu, akamkata sikio.'),
(2015472,69,41,14,48,'Yesu akawaambia, "Je, mmekuja na mapanga na marungu kunikamata kana kwamba mimi ni mnyang`anyi?'),
(2015473,69,41,14,49,'Kila siku nilikuwa pamoja nanyi nikifundisha Hekaluni, wala hamkunikamata. Lakini sasa lazima Maandiko Matakatifu yatimie."'),
(2015474,69,41,14,50,'Hapo wanafunzi wote wakamwacha, wakakimbia.'),
(2015475,69,41,14,51,'Kulikuwa na kijana mmoja aliyekuwa anamfuata Yesu akiwa amevaa shuka. Nao wakajaribu kumkamata.'),
(2015476,69,41,14,52,'Lakini yeye akaponyoka, akaiachilia ile shuka, akakimbia uchi.'),
(2015477,69,41,14,53,'Basi, wakampeleka Yesu kwa Kuhani Mkuu ambapo makuhani wakuu wote, wazee na walimu wa Sheria walikuwa wamekutanika.'),
(2015478,69,41,14,54,'Petro alimfuata Yesu kwa mbali, akaingia ndani ya ya wa Kuhani Mkuu, akaketi pamoja na walinzi akiota moto.'),
(2015479,69,41,14,55,'Makuhani wakuu na Baraza lote wakatafuta ushahidi wa kumshtaki Yesu wapate kumwua, lakini hawakupata.'),
(2015480,69,41,14,56,'Watu wengi walitoa ushahidi wa uongo juu ya Yesu, lakini ushahidi wao haukupatana.'),
(2015481,69,41,14,57,'Kisha wengine walisimama, wakatoa ushahidi wa uongo wakisema:'),
(2015482,69,41,14,58,'"Tulimsikia mtu huyu akisema, `Nitaliharibu Hekalu hili lililojengwa kwa mikono, na kwa siku tatu nitajenga lingine lisilojengwa kwa mikono."`'),
(2015483,69,41,14,59,'Lakini hata hivyo, ushahidi wao haukupatana.'),
(2015484,69,41,14,60,'Basi, Kuhani Mkuu akasimama katikati yao, akamwuliza Yesu, "Je, hujibu neno? Watu hawa wanashuhudia nini dhidi yako?"'),
(2015485,69,41,14,61,'Lakini yeye akakaa kimya; hakusema hata neno moja. Kuhani Mkuu akamwuliza tena, "Je, wewe ndiwe Kristo, Mwana wa Mungu Mtukufu?"'),
(2015486,69,41,14,62,'Yesu akajibu, "Naam, mimi ndiye. Tena, mtamwona Mwana wa Mtu amekaa upande wa kulia wa Mwenyezi, akija katika mawingu ya mbinguni."'),
(2015487,69,41,14,63,'Hapo Kuhani Mkuu akararua joho lake, akasema, "Tuna haja gani tena ya mashahidi?'),
(2015488,69,41,14,64,'Mmesikia kufuru yake! Ninyi mwaonaje?" Wote wakaamua kwamba anastahili kuuawa.'),
(2015489,69,41,14,65,'Basi, baadhi yao wakaanza kumtemea mate, wakamfunika uso, wakampiga na kumwambia, "Bashiri ni nani aliyekupiga!" Hata watumishi wakamchukua, wakampiga makofi.'),
(2015490,69,41,14,66,'Petro alipokuwa bado chini ukumbini, mmoja wa wajakazi wa kuhani Mkuu alikuja.'),
(2015491,69,41,14,67,'Alipomwona Petro akiota moto, alimtazama, akamwambia, "Hata wewe ulikuwa pamoja na Yesu Mnazareti."'),
(2015492,69,41,14,68,'Lakini Petro akakana, "Sijui, wala sielewi unayosema!" Kisha Petro akaondoka, akaenda nje uani. Hapo jogoo akawika.'),
(2015493,69,41,14,69,'Yule mjakazi alipomwona tena Petro, akaanza tena kuwaambia watu waliokuwa wamesimama hapo, "Mtu huyu ni mmoja wao."'),
(2015494,69,41,14,70,'Petro akakana tena. Baadaye kidogo, watu waliokuwa wamesimama hapo wakamwambia Petro, "Hakika wewe ni mmoja wao, maana wewe ni Mgalilaya."'),
(2015495,69,41,14,71,'Lakini Petro akaanza kulaani na kuapa akisema, "Mimi simjui mtu huyu mnayesema habari zake."'),
(2015496,69,41,14,72,'Hapo jogoo akawika mara ya pili. Basi, Petro akakumbuka jinsi Yesu alivyokuwa amemwambia: "Kabla jogoo hajawika mara mbili, utanikana mara tatu." Petro akabubujika machozi.'),
(2015497,69,41,15,1,'Kulipopambazuka, makuhani wakuu walifanya shauri pamoja na wazee, walimu wa Sheria na Baraza lote, wakamfunga Yesu pingu, wakampeleka na kumkabidhi kwa Pilato.'),
(2015498,69,41,15,2,'Pilato akamwuliza Yesu, "Je, wewe ni mfalme wa Wayahudi?" Yesu akajibu, "Wewe umesema."'),
(2015499,69,41,15,3,'Makuhani wakuu wakamshtaki Yesu mambo mengi.'),
(2015500,69,41,15,4,'Pilato akamwuliza tena Yesu, "Je, hujibu neno? Tazama wanavyotoa mashtaka mengi juu yako."'),
(2015501,69,41,15,5,'Lakini Yesu hakujibu neno, hata pilato akashangaa.'),
(2015502,69,41,15,6,'Kila wakati wa sikukuu ya Pasaka, Pilato alikuwa na desturi ya kuwafungulia mfungwa mmoja waliyemtaka.'),
(2015503,69,41,15,7,'Basi, kulikuwa na mtu mmoja aitwaye Baraba, ambaye alikuwa amefungwa pamoja na waasi wengine kwa kusababisha uasi na mauaji.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015504,69,41,15,8,'Watu wengi wakamwendea Pilato wakamwomba awafanyie kama kawaida yake.'),
(2015505,69,41,15,9,'Pilato akawauliza, "Je, mwataka niwafungulieni Mfalme wa Wayahudi?"'),
(2015506,69,41,15,10,'Alisema hivyo kwa sababu alijua wazi kwamba makuhani wakuu walimkabidhi Yesu kwake kwa sababu ya wivu.'),
(2015507,69,41,15,11,'Lakini makuhani wakuu wakawachochea watu wamwombe Pilato awafungulie Baraba.'),
(2015508,69,41,15,12,'Pilato akawauliza tena, "Basi, sasa mwataka nifanye nini na mtu huyu mnayemwita Mfalme wa Wayahudi?"'),
(2015509,69,41,15,13,'Watu wote wakapaaza sauti tena: "Msulubishe!"'),
(2015510,69,41,15,14,'Lakini Pilato akawauliza, "Kwa nini! Amefanya kosa gani?" Lakini wao wakazidi kupaaza sauti, "Msulubishe!"'),
(2015511,69,41,15,15,'Pilato alitaka kuuridhisha huo umati wa watu; basi, akamwachilia Baraba kutoka gerezani. Akaamuru Yesu apigwe viboko, kisha akamtoa asulubiwe.'),
(2015512,69,41,15,16,'Kisha askari walimpeleka Yesu ndani ukumbini, katika ikulu, wakakusanya kikosi kizima cha askari.'),
(2015513,69,41,15,17,'Wakamvika vazi la rangi ya zambarau, wakasokota taji ya miiba, wakamwekea kichwani.'),
(2015514,69,41,15,18,'Wakaanza kumsalimu, "Shikamoo Mfalme wa Wayahudi!"'),
(2015515,69,41,15,19,'Wakampiga kichwani kwa mwanzi, wakamtemea mate; wakampigia magoti na kumsujudia.'),
(2015516,69,41,15,20,'Baada ya kumdhihaki, walimvua lile joho, wakamvika nguo zake, kisha wakampeleka kumsulubisha.'),
(2015517,69,41,15,21,'Walipokuwa njiani, walikutana na mtu mmoja aitwaye Simoni, mwenyeji wa Kurene. Yeye alikuwa baba wa Aleksanda na Rufo, na wakati huo alikuwa akitoka shambani. Basi, wakamlazimisha auchukue msalaba wa Yesu.'),
(2015518,69,41,15,22,'Kisha wakampeleka Yesu mpaka mahali palipoitwa Golgotha, maana yake, "Mahali pa Fuvu la Kichwa."'),
(2015519,69,41,15,23,'Wakampa divai iliyochanganywa na manemane, lakini yeye akaikataa.'),
(2015520,69,41,15,24,'Basi, wakamsulubisha, wakagawana mavazi yake kwa kuyapigia kura waamue nani angepata nini.'),
(2015521,69,41,15,25,'Ilikuwa saa tatu asubuhi walipomsulubisha.'),
(2015522,69,41,15,26,'Na mshtaka wake ulikuwa umeandikwa: "Mfalme wa Wayahudi."'),
(2015523,69,41,15,27,'Pamoja naye waliwasulubisha wanyang`anyi wawili, mmoja upande wake wa kulia na mwingine upande wake wa kushoto.*fh* Matakatifu yanayosema, "Aliwekwa kundi moja na waovu."'),
(2015524,69,41,15,28,'missing'),
(2015525,69,41,15,29,'Watu waliokuwa wanapita mahali hapo walimtukana, wakitikisa vichwa vyao na kusema, "Aha! Wewe mwenye kuvunja Hekalu na kulijenga kwa siku tatu!'),
(2015526,69,41,15,30,'Sasa, shuka msalabani ujiokoe mwenyewe!"'),
(2015527,69,41,15,31,'Nao makuhani wakuu pamoja na walimu wa Sheria walimdhihaki wakisema, "Aliwaokoa wengine, lakini kujiokoa mwenyewe hawezi!'),
(2015528,69,41,15,32,'Eti yeye ni Kristo, Mfalme wa Israeli! Basi, na ashuke msalabani ili tuone na kuamini." Hata watu wale waliosulubiwa pamoja naye walimtukana.'),
(2015529,69,41,15,33,'Tangu saa sita mchana mpaka saa tisa kulikuwa giza nchini kote.'),
(2015530,69,41,15,34,'Saa tisa alasiri Yesu akalia kwa sauti kubwa, "Eloi, Eloi, lema sabakthani?" Maana yake, "Mungu wangu, Mungu wangu, mbona umeniacha?"'),
(2015531,69,41,15,35,'Baadhi ya watu waliosimama pale waliposikia hivyo, walisema, "Sikiliza! Anamwita Eliya!"'),
(2015532,69,41,15,36,'Mtu mmoja akakimbia, akachovya sifongo katika siki, akaiweka juu ya mwanzi, akampa anywe akisema, "Hebu tuone kama Eliya atakuja kumteremsha msalabani!"'),
(2015533,69,41,15,37,'Yesu akapaaza sauti kubwa, akakata roho.'),
(2015534,69,41,15,38,'Basi, pazia la Hekalu likapasuka vipande viwili toka juu mpaka chini.'),
(2015535,69,41,15,39,'Jemadari mmoja aliyekuwa amesimama mbele yake aliona jinsi Yesu alivyolia kwa sauti na kukata roho, akasema, "Kweli mtu huyu alikuwa Mwana wa Mungu!"'),
(2015536,69,41,15,40,'Walikuwako pia wanawake waliotazama kwa mbali, miongoni mwao akiwa Maria toka mji wa Magdala, Salome, na Maria mama wa kina Yakobo mdogo na Yose.'),
(2015537,69,41,15,41,'Hawa walimfuata Yesu alipokuwa Galilaya na kumtumikia. Kulikuwa na wanawake wengine wengi waliokuja Yerusalemu pamoja naye.'),
(2015538,69,41,15,42,'Wakati wa jioni ulikuwa umekwisha fika. Hiyo ilikuwa siku ya Maandalio, yaani siku inayotangulia Sabato.'),
(2015539,69,41,15,43,'Hapo akaja Yosefu mwenyeji wa Armathaya, mjumbe wa Baraza Kuu, aliyeheshimika sana. Yeye pia alikuwa anatazamia kuja kwa Ufalme wa Mungu. Basi, alimwendea Pilato bila uoga, akaomba apewe mwili wa Yesu.'),
(2015540,69,41,15,44,'Pilato alishangaa kusikia kwamba Yesu alikuwa amekwisha kufa. Basi, akamwita jemadari, akamwuliza kama Yesu alikuwa amekufa kitambo.'),
(2015541,69,41,15,45,'Pilato alipoarifiwa na huyo jemadari kwamba Yesu alikuwa amekwisha kufa, akamruhusu Yosefu auchukue mwili wake.'),
(2015542,69,41,15,46,'Hapo Yosefu akanunua sanda ya kitani, akauteremsha chini huo mwili, akauzungushia sanda. Akauweka katika kaburi lililokuwa limechongwa mwambani, kisha akavingirisha jiwe kubwa mbele ya mlango.'),
(2015543,69,41,15,47,'Nao Maria Magdalene na Maria mama yake Yose walipaona hapo alipolazwa.'),
(2015544,69,41,16,1,'Baada ya siku ya Sabato, Maria Magdalene, Salome na Maria mama yake Yakobo walinunua manukato ili wakaupake mwili wa Yesu.'),
(2015545,69,41,16,2,'Basi, alfajiri na mapema siku ya Jumapili, jua lilipoanza kuchomoza, walienda kaburini.'),
(2015546,69,41,16,3,'Nao wakawa wanaambiana, "Nani atakayetuondolea lile jiwe mlangoni mwa kaburi?"'),
(2015547,69,41,16,4,'Lakini walipotazama, waliona jiwe limekwisha ondolewa. (Nalo lilikuwa kubwa mno.)'),
(2015548,69,41,16,5,'Walipoingia kaburini, walimwona kijana mmoja aliyevaa vazi jeupe, ameketi upande wa kulia; wakashangaa sana.'),
(2015549,69,41,16,6,'Lakini huyo kijana akawaambia, "Msishangae. Mnamtafuta Yesu wa Nazareti aliyesulubiwa. Amefufuka, hayumo hapa. Tazameni mahali walipokuwa wamemlaza.'),
(2015550,69,41,16,7,'Nendeni mkawaambie wanafunzi wake pamoja na Petro ya kwamba anawatangulieni kule Galilaya. Huko mtamwona kama alivyowaambieni."'),
(2015551,69,41,16,8,'Basi, wakatoka pale kaburini mbio, maana walitetemeka kwa hofu na kushangaa. Hawakumwambia mtu yeyote kitu, kwa sababu waliogopa mno. [[['),
(2015552,69,41,16,9,'Yesu alipofufuka mapema Jumapili, alijionyesha kwanza kwa Maria Magdalene, ambaye Yesu alikuwa amemtoa pepo saba.'),
(2015553,69,41,16,10,'Maria Magdalene akaenda, akawajulisha wale waliokuwa pamoja na Yesu, na wakati huo walikuwa wanaomboleza na kulia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015554,69,41,16,11,'Lakini waliposikia ya kwamba Yesu yu hai na kwamba Maria Magdalene amemwona, hawakuamini.'),
(2015555,69,41,16,12,'Baadaye Yesu aliwatokea wanafunzi wawili akiwa na sura nyingine. Wanafunzi hao walikuwa wanakwenda shambani.'),
(2015556,69,41,16,13,'Nao pia wakaenda wakawaambia wenzao. Hata hivyo hawakuamini.'),
(2015557,69,41,16,14,'Mwishowe, Yesu aliwatokea wanafunzi kumi na mmoja walipokuwa pamoja mezani. Akawakemea sana kwa sababu ya kutoamini kwao na ukaidi wao, maana hawakuwaamini wale waliokuwa wamemwona baada ya kufufuka.'),
(2015558,69,41,16,15,'Basi, akawaambia, "Nendeni ulimwenguni kote mkahubiri Habari Njema kwa kila mtu.'),
(2015559,69,41,16,16,'Anayeamini na kubatizwa ataokolewa; asiyeamini atahukumiwa.'),
(2015560,69,41,16,17,'Na ishara hizi zitaandamana na wale wanaoamini: kwa jina langu watatoa pepo na watasema kwa lugha mpya.'),
(2015561,69,41,16,18,'Wakishika nyoka au wakinywa kitu chochote chenye sumu, hakitawadhuru. Watawawekea wagonjwa mikono, nao watapona."'),
(2015562,69,41,16,19,'Basi, Bwana Yesu alipokwisha sema nao, akachukuliwa mbinguni, akaketi upande wa kulia wa Mungu.'),
(2015563,69,41,16,20,'Wanafunzi wakaenda wakihubiri kila mahali. Bwana akafanya kazi pamoja nao na kuimarisha ujumbe huo kwa ishara zilizoandamana nao.]*fi*'),
(2015564,69,42,1,1,'Mheshimiwa Theofilo: Watu wengi wamejitahidi kuandika juu ya mambo yale yaliyotendeka kati yetu.'),
(2015565,69,42,1,2,'Waliandika kama tulivyoelezwa na wale walioyaona kwa macho yao tangu mwanzo, na waliotangaza ujumbe huo.'),
(2015566,69,42,1,3,'Inafaa nami pia, Mheshimiwa, baada ya kuchunguza kwa makini mambo yote tangu mwanzo, nikuandikie kwa mpango,'),
(2015567,69,42,1,4,'ili nawe uweze kujionea mwenyewe ukweli wa mambo yale uliyofundishwa.'),
(2015568,69,42,1,5,'Wakati Herode alipokuwa mfalme wa Yudea, kulikuwa na kuhani mmoja jina lake Zakaria, wa kikundi cha Abia. Mke wake alikuwa anaitwa Elisabeti, naye alikuwa wa ukoo wa kuhani Aroni.'),
(2015569,69,42,1,6,'Wote wawili walikuwa wanyofu mbele ya Mungu, wakiishi kwa kufuata amri na maagizo yote ya Bwana bila lawama.'),
(2015570,69,42,1,7,'Lakini hawakuwa wamejaliwa watoto kwa vile Elisabeti alikuwa tasa, nao wote wawili walikuwa wazee sana.'),
(2015571,69,42,1,8,'Siku moja, ilipokuwa zamu yake ya kutoa huduma ya ukuhani mbele ya Mungu,'),
(2015572,69,42,1,9,'Zakariya alichaguliwa kwa kura, kama ilivyokuwa desturi, kuingia hekaluni ili afukize ubani.'),
(2015573,69,42,1,10,'Watu, umati mkubwa, walikuwa wamekusanyika nje wanasali wakati huo wa kufukiza ubani.'),
(2015574,69,42,1,11,'Malaika wa Bwana akamtokea humo ndani, akasimama upande wa kulia wa madhabahu ya kufukizia ubani.'),
(2015575,69,42,1,12,'Zakariya alipomwona alifadhaika, hofu ikamwingia.'),
(2015576,69,42,1,13,'Lakini malaika akamwambia, "Zakariya, usiogope, kwa maana sala yako imesikilizwa, na Elisabeti mkeo atakuzalia mtoto wa kiume, nawe utampa jina Yohane.'),
(2015577,69,42,1,14,'Utakuwa na furaha kubwa na watu wengi watashangilia kwa sababu ya kuzaliwa kwake.'),
(2015578,69,42,1,15,'Atakuwa mkuu mbele ya Bwana. Hatakunywa divai wala kileo, atajazwa Roho Mtakatifu tangu tumboni mwa mama yake.'),
(2015579,69,42,1,16,'Atawaelekeza wengi wa watu wa Israeli kwa Bwana Mungu wao.'),
(2015580,69,42,1,17,'Atamtangulia Bwana akiongozwa na nguvu na roho kama Eliya. Atawapatanisha kina baba na watoto wao; atawafanya wasiotii wawe na fikira za uadilifu, na hivyo amtayarishie Bwana watu wake."'),
(2015581,69,42,1,18,'Zakariya akamwambia huyo malaika, "Ni kitu gani kitakachonihakikishia jambo hilo? Mimi ni mzee, hali kadhalika na mke wangu."'),
(2015582,69,42,1,19,'Malaika akamjibu, "Mimi ni Gabrieli, nisimamaye mbele ya Mungu, na nimetumwa niseme nawe, nikuletee hii habari njema.'),
(2015583,69,42,1,20,'Sikiliza, utakuwa bubu kwa sababu huyasadiki haya maneno yatakayotimia kwa wakati wake. Hutaweza kusema mpaka hayo niliyokuambia yatakapotimia."'),
(2015584,69,42,1,21,'Wakati huo, wale watu walikuwa wanamngoja Zakariya huku wakishangaa juu ya kukawia kwake Hekaluni.'),
(2015585,69,42,1,22,'Alipotoka nje, hakuweza kusema nao. Ikawa dhahiri kwao kwamba alikuwa ameona maono Hekaluni. Lakini akawa anawapa ishara kwa mikono, akabaki bubu.'),
(2015586,69,42,1,23,'Zamu yake ya kuhudumu ilipokwisha, alirudi nyumbani.'),
(2015587,69,42,1,24,'Baadaye Elisabeti mkewe akapata mimba. Akajificha nyumbani kwa muda wa miezi mitano, akisema:'),
(2015588,69,42,1,25,'"Hivi ndivyo alivyonitendea Bwana; ameniangalia na kuniondolea aibu niliyokuwa nayo mbele ya watu."'),
(2015589,69,42,1,26,'Mnamo mwezi wa sita, malaika Gabrieli alitumwa na Mungu aende kwenye mji uitwao Nazareti huko Galilaya,'),
(2015590,69,42,1,27,'kwa msichana mmoja aitwaye Maria, mchumba wa mtu mmoja jina lake Yosefu, wa ukoo wa Daudi.'),
(2015591,69,42,1,28,'Malaika akamwendea, akamwambia, "Salamu Maria! Umejaliwa neema nyingi! Bwana yu pamoja nawe."'),
(2015592,69,42,1,29,'Maria aliposikia maneno hayo alifadhaika sana, akawaza: maneno haya yanamaanisha nini?'),
(2015593,69,42,1,30,'Malaika akamwambia, "Usiogope Maria, kwa maana Mungu amekujalia neema.'),
(2015594,69,42,1,31,'Utachukua mimba, utamzaa mtoto wa kiume na utampa jina Yesu.'),
(2015595,69,42,1,32,'Yeye atakuwa mkuu na ataitwa Mwana wa Mungu Mkuu. Bwana Mungu atampa kiti cha mfalme Daudi, babu yake.'),
(2015596,69,42,1,33,'Kwa hivyo atautawala ukoo wa Yakobo milele, na ufalme wake hautakuwa na mwisho."'),
(2015597,69,42,1,34,'Maria akamjibu, "Yatawezekanaje hayo, hali mimi ni bikira?"'),
(2015598,69,42,1,35,'Malaika akamjibu, "Roho Mtakatifu atakushukia, na uwezo wake Mungu Mkuu utakujia kama kivuli; kwa sababu hiyo, mtoto atakayezaliwa ataitwa Mtakatifu, Mwana wa Mungu.'),
(2015599,69,42,1,36,'Ujue pia kwamba hata Elisabeti, jamaa yako, naye amepata mimba ingawa ni mzee, na sasa ni mwezi wa sita kwake yeye ambaye watu walimfahamu kuwa tasa.'),
(2015600,69,42,1,37,'Kwa maana hakuna jambo lisilowezekana kwa Mungu."'),
(2015601,69,42,1,38,'Maria akasema, "Mimi ni mtumishi wa Bwana, nitendewe kama ulivyosema." Kisha yule malaika akaenda zake.'),
(2015602,69,42,1,39,'Siku kadhaa baadaye, Maria alifunga safari akaenda kwa haraka hadi mji mmoja ulioko katika milima ya Yuda.'),
(2015603,69,42,1,40,'Huko, aliingia katika nyumba ya Zakariya, akamsalimu Elisabeti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015604,69,42,1,41,'Mara tu Elisabeti aliposikia sauti ya Maria, mtoto mchanga tumboni mwake Elisabeti akaruka. Naye Elisabeti akajazwa Roho Mtakatifiu,'),
(2015605,69,42,1,42,'akasema kwa sauti kubwa, "Umebarikiwa kuliko wanawake wote, naye utakayemzaa amebarikiwa.'),
(2015606,69,42,1,43,'Mimi ni nani hata mama wa Bwana wangu afike kwangu?'),
(2015607,69,42,1,44,'Nakwambia, mara tu niliposikia sauti yako, mtoto mchanga tumboni mwangu aliruka kwa furaha.'),
(2015608,69,42,1,45,'Heri yako wewe uliyesadiki kwamba yatatimia yale Bwana aliyokwambia."'),
(2015609,69,42,1,46,'Naye Maria akasema,'),
(2015610,69,42,1,47,'"Moyo wangu wamtukuza Bwana, roho yangu inafurahi kwa sababu ya Mungu Mwokozi wangu.'),
(2015611,69,42,1,48,'Kwa kuwa amemwangalia kwa huruma mtumishi wake mnyenyekevu. Hivyo tangu sasa watu wote wataniita mwenye heri.'),
(2015612,69,42,1,49,'Kwa kuwa Mwenyezi Mungu amenitendea makuu, jina lake ni takatifu.'),
(2015613,69,42,1,50,'Huruma yake kwa watu wanaomcha hudumu kizazi hata kizazi.'),
(2015614,69,42,1,51,'Amefanya mambo makuu kwa mkono wake: amewatawanya wenye kiburi katika mawazo ya mioyo yao;'),
(2015615,69,42,1,52,'amewashusha wenye nguvu kutoka vitu vyao vya enzi, akawakweza wanyenyekevu.'),
(2015616,69,42,1,53,'Wenye njaa amewashibisha mema, matajiri amewaacha waende mikono mitupu.'),
(2015617,69,42,1,54,'Amemsaidia Israeli mtumishi wake, akikumbuka huruma yake.'),
(2015618,69,42,1,55,'Kama alivyowaahidia wazee wetu Abrahamu na wazawa wake hata milele."'),
(2015619,69,42,1,56,'Maria alikaa na Elisabeti kwa muda upatao miezi mitatu, halafu akarudi nyumbani kwake.'),
(2015620,69,42,1,57,'Wakati wa kujifungua kwake Elisabeti ulifika, akajifungua mtoto wa kiume.'),
(2015621,69,42,1,58,'Jirani na watu wa jamaa yake walipopata habari kwamba Bwana amemwonea huruma kubwa, walifurahi pamoja naye.'),
(2015622,69,42,1,59,'Halafu siku ya nane walifika kumtahiri mtoto, wakataka kumpa jina la baba yake, Zakariya.'),
(2015623,69,42,1,60,'Lakini mama yake akasema, "La, sivyo, bali ataitwa Yohane."'),
(2015624,69,42,1,61,'Wakamwambia, "Mbona hakuna yeyote katika ukoo wake mwenye jina hilo?"'),
(2015625,69,42,1,62,'Basi, wakamwashiria baba yake wapate kujua alitaka mtoto wake apewe jina gani.'),
(2015626,69,42,1,63,'Naye akaomba kibao cha kuandikia, akaandika hivi: "Yohane ndilo jina lake." Wote wakastaajabu.'),
(2015627,69,42,1,64,'Papo hapo midomo na ulimi wake Zakariya vikafunguliwa, akawa anaongea akimsifu Mungu.'),
(2015628,69,42,1,65,'Hofu ikawaingia jirani wote, na habari hizo zikaenea kila mahali katika milima ya Yudea.'),
(2015629,69,42,1,66,'Wote waliosikia mambo hayo waliyatafakari mioyoni mwao wakisema: "Mtoto huyu atakuwa mtu wa namna gani?" Maana, hakika nguvu ya Bwana ilikuwa pamoja naye.'),
(2015630,69,42,1,67,'Zakariya, baba yake mtoto, akajazwa Roho Mtakatifu, akatamka ujumbe wa Mungu:'),
(2015631,69,42,1,68,'"Asifiwe Bwana Mungu wa Israeli, kwani amekuja kuwasaidia na kuwakomboa watu wake.'),
(2015632,69,42,1,69,'Ametupatia Mwokozi shujaa, mzawa wa Daudi mtumishi wake.'),
(2015633,69,42,1,70,'Aliahidi hapo kale kwa njia ya manabii wake watakatifu,'),
(2015634,69,42,1,71,'kwamba atatuokoa mikononi mwa adui zetu na kutoka mikononi mwa wote wanaotuchukia.'),
(2015635,69,42,1,72,'Alisema atawahurumia wazee wetu, na kukumbuka agano lake takatifu.'),
(2015636,69,42,1,73,'Kiapo alichomwapia Abrahamu baba yetu, ni kwamba atatujalia sisi'),
(2015637,69,42,1,74,'tukombolewe kutoka adui zetu, tupate kumtumikia bila hofu,'),
(2015638,69,42,1,75,'kwa unyofu na uadilifu mbele yake, siku zote za maisha yetu.'),
(2015639,69,42,1,76,'Nawe mwanangu, utaitwa, nabii wa Mungu Mkuu, utamtangulia Bwana kumtayarishia njia yake;'),
(2015640,69,42,1,77,'kuwatangazia watu kwamba wataokolewa kwa kuondolewa dhambi zao.'),
(2015641,69,42,1,78,'Mungu wetu ni mpole na mwenye huruma. Atasababisha pambazuko angavu la ukombozi litujie kutoka juu,'),
(2015642,69,42,1,79,'na kuwaangazia wote wanaokaa katika giza kuu la kifo, aongoze hatua zetu katika njia ya amani."'),
(2015643,69,42,1,80,'Mtoto akakua, akapata nguvu rohoni. Alikaa jangwani mpaka alipojionyesha rasmi kwa watu wa Israeli.'),
(2015644,69,42,2,1,'Siku zile, tangazo rasmi lilitolewa na Kaisari Augusto kuwataka watu wote chini ya utawala wake wajiandikishe.'),
(2015645,69,42,2,2,'Kuandikishwa huku kulikuwa mara ya kwanza, wakati Kirenio alipokuwa mkuu wa mkoa wa Siria.'),
(2015646,69,42,2,3,'Basi, wote waliohusika walikwenda kujiandikisha, kila mtu katika mji wake.'),
(2015647,69,42,2,4,'Yosefu pia alifanya safari kutoka mjini Nazareti mkoani Galilaya. Kwa kuwa alikuwa wa jamaa na ukoo wa Daudi alikwenda mjini Bethlehemu mkoani Yuda alikozaliwa Mfalme Daudi.'),
(2015648,69,42,2,5,'Alikwenda kujiandikisha pamoja na mchumba wake Maria ambaye alikuwa mja mzito.'),
(2015649,69,42,2,6,'Walipokuwa huko, siku yake ya kujifungua ikawadia,'),
(2015650,69,42,2,7,'akajifungua mtoto wake wa kwanza wa kiume, akamvika nguo za kitoto, akamlaza horini kwa sababu hawakupata nafasi katika nyumba ya wageni.'),
(2015651,69,42,2,8,'Katika sehemu hizo, walikuwako wachungaji wakikesha usiku mbugani kulinda mifugo yao.'),
(2015652,69,42,2,9,'Malaika wa Bwana akawatokea ghafla, na utukufu wa Bwana ukawaangazia pande zote. Wakaogopa sana.'),
(2015653,69,42,2,10,'Malaika akawaambia, "Msiogope! Nimewaleteeni habari njema ya furaha kuu kwa watu wote.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015654,69,42,2,11,'Kwa maana, leo hii katika mji wa Daudi, amezaliwa Mwokozi kwa ajili yenu, ndiye Kristo Bwana.'),
(2015655,69,42,2,12,'Na hiki kitakuwa kitambulisho kwenu: mtamkuta mtoto mchanga amevikwa nguo za kitoto, amelazwa horini."'),
(2015656,69,42,2,13,'Mara kundi kubwa la jeshi la mbinguni likajiunga na huyo malaika, wakamsifu Mungu wakisema:'),
(2015657,69,42,2,14,'"Utukufu kwa Mungu juu mbinguni, na amani duniani kwa watu aliopendezwa nao!"'),
(2015658,69,42,2,15,'Baada ya hao malaika kuondoka na kurudi mbinguni, wachungaji wakaambiana: "Twendeni moja kwa moja mpaka Bethlehemu tukalione tukio hili Bwana alilotujulisha."'),
(2015659,69,42,2,16,'Basi, wakaenda mbio, wakamkuta Maria na Yosefu na yule mtoto mchanga amelazwa horini.'),
(2015660,69,42,2,17,'Hao wachungaji walipomwona mtoto huyo wakawajulisha wote habari waliyokuwa wamesikia juu yake.'),
(2015661,69,42,2,18,'Wote waliosikia hayo walishangaa juu ya habari walizoambiwa na wachungaji.'),
(2015662,69,42,2,19,'Lakini Maria aliyaweka na kuyatafakari mambo hayo yote moyoni mwake.'),
(2015663,69,42,2,20,'Wale wachungaji walirudi makwao huku wakimtukuza na kumsifu Mungu kwa yote waliyokuwa wamesikia na kuona; yote yalikuwa kama walivyokuwa wameambiwa.'),
(2015664,69,42,2,21,'Siku nane baadaye, wakati wa kumtahiri mtoto ulipofika, walimpa jina Yesu, jina ambalo alikuwa amepewa na malaika kabla hajachukuliwa mimba.'),
(2015665,69,42,2,22,'Siku zilipotimia za Yosefu na Maria kutakaswa kama walivyotakiwa na Sheria ya Mose, wazazi hao walimchukua mtoto, wakaenda naye Yerusalemu ili wamweke mbele ya Bwana.'),
(2015666,69,42,2,23,'Katika Sheria ya Bwana imeandikwa: "Kila mzaliwa wa kwanza wa kiume atawekwa wakfu kwa Bwana."'),
(2015667,69,42,2,24,'Pia walikwenda ili watoe sadaka: hua wawili au makinda wawili ya njiwa, kama ilivyotakiwa katika Sheria ya Bwana.'),
(2015668,69,42,2,25,'Wakati huo huko Yerusalemu kulikuwa na mtu mmoja, mwema na mcha Mungu, jina lake Simeoni. Yeye alikuwa akitazamia kwa hamu ukombozi wa Israeli. Roho Mtakatifu alikuwa pamoja naye.'),
(2015669,69,42,2,26,'Roho Mtakatifu alikuwa amemhakikishia kwamba hatakufa kabla ya kumwona Masiha wa Bwana.'),
(2015670,69,42,2,27,'Basi, akiongozwa na Roho Mtakatifu, Simeoni aliingia Hekaluni; na wazazi wa Yesu walipomleta Hekaluni mtoto wao ili wamfanyie kama ilivyotakiwa na Sheria,'),
(2015671,69,42,2,28,'Simeoni alimpokea mtoto Yesu mikononi mwake huku akimtukuza Mungu na kusema:'),
(2015672,69,42,2,29,'"Sasa Bwana, umetimiza ahadi yako, waweza kumruhusu mtumishi wako aende kwa amani.'),
(2015673,69,42,2,30,'Maana kwa macho yangu nimeuona wokovu utokao kwako,'),
(2015674,69,42,2,31,'ambao umeutayarisha mbele ya watu wote:'),
(2015675,69,42,2,32,'Mwanga utakaowaangazia watu wa mataifa, na utukufu kwa watu wako Israeli."'),
(2015676,69,42,2,33,'Baba na mama yake Yesu walikuwa wakistaajabia maneno aliyosema Simeoni juu ya mtoto.'),
(2015677,69,42,2,34,'Simeoni akawabariki, akamwambia Maria mama yake, "Mtoto huyu atakuwa sababu ya kupotea na kuokoka kwa watu wengi katika Israeli. Naye atakuwa ishara itakayopingwa na watu;'),
(2015678,69,42,2,35,'na hivyo mawazo ya watu wengi yataonekana wazi. Nawe mwenyewe, uchungu ulio kama upanga mkali utauchoma moyo wako."'),
(2015679,69,42,2,36,'Palikuwa na nabii mmoja mwanamke, mzee sana, jina lake Ana, binti Fanueli, wa kabila la Asheri. Alikuwa ameishi na mumewe kwa miaka saba tangu alipoolewa.'),
(2015680,69,42,2,37,'Halafu alibaki mjane hadi wakati huo akiwa mzee wa miaka themanini na minne. Wakati huo wote alikaa Hekaluni akifunga na kusali usiku na mchana.'),
(2015681,69,42,2,38,'Saa hiyohiyo alijitokeza mbele, akamshukuru Mungu, na akaeleza habari za huyo mtoto kwa watu wote waliokuwa wanatazamia ukombozi wa Yerusalemu.'),
(2015682,69,42,2,39,'Hao wazazi walipokwisha fanya yote yaliyoamriwa na Sheria ya Bwana, walirudi makwao Nazareti, mkoani Galilaya.'),
(2015683,69,42,2,40,'Mtoto akakua, akazidi kupata nguvu, akajaa hekima, na neema ya Mungu ilikuwa pamoja naye.'),
(2015684,69,42,2,41,'Wazazi wa Yesu walikuwa na desturi ya kwenda Yerusalemu kila mwaka wakati wa sikukuu ya Pasaka.'),
(2015685,69,42,2,42,'Mtoto alipokuwa na umri wa miaka kumi na miwili, wote walikwenda kwenye sikukuu hiyo kama ilivyokuwa desturi.'),
(2015686,69,42,2,43,'Baada ya sikukuu, walianza safari ya kurudi makwao, lakini Yesu alibaki Yerusalemu bila wazazi wake kuwa na habari.'),
(2015687,69,42,2,44,'Walidhani alikuwa pamoja na kundi la wasafiri, wakaenda mwendo wa kutwa, halafu wakaanza kumtafuta miongoni mwa jamaa na marafiki.'),
(2015688,69,42,2,45,'Kwa kuwa hawakumwona, walirudi Yerusalemu wakimtafuta.'),
(2015689,69,42,2,46,'Siku ya tatu walimkuta Hekaluni kati ya walimu, akiwasikiliza na kuwauliza maswali.'),
(2015690,69,42,2,47,'Wote waliosikia maneno yake walistaajabia akili yake na majibu yake ya hekima.'),
(2015691,69,42,2,48,'Wazazi wake walipomwona walishangaa. Maria, mama yake, akamwuliza, "Mwanangu, kwa nini umetutenda hivyo? Baba yako na mimi tumekuwa tukikutafuta kwa huzuni."'),
(2015692,69,42,2,49,'Yeye akawajibu, "Kwa nini mlinitafuta? Hamkujua kwamba inanipasa kuwa katika nyumba ya Baba yangu?"'),
(2015693,69,42,2,50,'Lakini wazazi wake hawakuelewa maana ya maneno aliyowaambia.'),
(2015694,69,42,2,51,'Basi, akarudi pamoja nao hadi Nazareti, akawa anawatii. Mama yake akaweka mambo hayo yote moyoni mwake.'),
(2015695,69,42,2,52,'Naye Yesu akaendelea kukua katika hekima na kimo; akazidi kupendwa na Mungu na watu.'),
(2015696,69,42,3,1,'Mwaka wa kumi na tano wa utawala wa Kaisari Tiberio, Pontio Pilato alikuwa anatawala mkoa wa Yudea. Herode alikuwa mkuu wa mkoa wa Galilaya, na Filipo, ndugu yake, alikuwa mkuu wa mikoa ya Iturea na Trakoniti. Lusania alikuwa mkuu wa mkoa wa Abilene,'),
(2015697,69,42,3,2,'na Anasi na Kayafa walikuwa makuhani wakuu mjini Yerusalem. Wakati huo ndipo neno la Mungu lilipomjia Yohane, mwana wa Zakariya, kule jangwani.'),
(2015698,69,42,3,3,'Basi, Yohane akaenda katika sehemu zote zilizopakana na mto Yordani, akihubiri watu watubu na kubatizwa ili Mungu awaondolee dhambi.'),
(2015699,69,42,3,4,'Ndivyo ilivyoandikwa katika kitabu cha nabii Isaya: "Sauti ya mtu imesikika jangwani: `Mtayarishieni Bwana njia yake; nyosheni mapito yake.'),
(2015700,69,42,3,5,'Kila bonde litafukiwa, kila mlima na kilima vitasawazishwa; palipopindika patanyooshwa, njia mbaya zitatengenezwa.'),
(2015701,69,42,3,6,'Na, watu wote watauona wokovu utokao kwa Mungu."`'),
(2015702,69,42,3,7,'Basi, Yohane akawa anawaambia watu wengi waliofika ili awabatize: "Enyi kizazi cha nyoka! Ni nani aliyewadokezea kwamba mngeweza kuiepuka ghadhabu inayokuja?'),
(2015703,69,42,3,8,'Basi, onyesheni kwa matendo kwamba mmetubu. Msianze sasa kusema: `Sisi ni watoto wa Abrahamu.` Nawaambieni hakika, Mungu anaweza kuyageuza mawe haya yawe watoto wa Abrahamu!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015704,69,42,3,9,'Lakini, sasa hivi shoka limewekwa tayari kukata mizizi ya miti. Kila mti usiozaa matunda mazuri utakatwa na kutupwa motoni."'),
(2015705,69,42,3,10,'Umati wa watu ukamwuliza, "Tufanye nini basi?"'),
(2015706,69,42,3,11,'Akawajibu, "Aliye na nguo mbili amgawie yule asiye na nguo; aliye na chakula afanye vivyo hivyo."'),
(2015707,69,42,3,12,'Nao watoza ushuru wakaja pia ili wabatizwe, wakamwuliza, "Mwalimu, tufanye nini?"'),
(2015708,69,42,3,13,'Naye akawaambia, "Msitoze ushuru zaidi ya kima kilichowekwa."'),
(2015709,69,42,3,14,'Nao askari wakamwuliza, "Na sisi tufanye nini?" Naye akawajibu, "Msichukue vitu vya mtu yeyote kwa nguvu wala kumshtaki yeyote kwa uongo. Toshekeni na mishahara yenu."'),
(2015710,69,42,3,15,'Wote walikuwa wanatazamia kitu fulani; basi, wakaanza kujiuliza mioyoni mwao kuhusu Yohane: kuwa labda yeye ndiye Kristo.'),
(2015711,69,42,3,16,'Hapo Yohane akawaambia wote, "Mimi ninawabatiza kwa maji, lakini anakuja mwenye uwezo zaidi kuliko mimi ambaye sistahili hata kumfungulia kamba za viatu vyake. Yeye atawabatizeni kwa Roho Mtakatifu na kwa moto.'),
(2015712,69,42,3,17,'Yeye ni kama mtu anayeshika mikononi mwake chombo cha kupuria nafaka, aipure nafaka yake, akusanye ngano ghalani mwake, na makapi ayachome kwa moto usiozimika."'),
(2015713,69,42,3,18,'Hivyo, pamoja na mawaidha mengine mengi, Yohane aliwahimiza watu akiwahubiria Habari Njema.'),
(2015714,69,42,3,19,'Lakini Yohane alimgombeza Herode, mkuu wa mkoa, kwa sababu alikuwa amemchukua Herodia, mke wa ndugu yake, na kumfanya mke wake; na pia kwa ajili ya mabaya yote aliyokuwa amefanya.'),
(2015715,69,42,3,20,'Kisha Herode akazidisha ubaya wake kwa kumtia Yohane gerezani.'),
(2015716,69,42,3,21,'Watu wote walipokuwa wamekwisha batizwa, Yesu naye alibatizwa. Na alipokuwa akisali, mbingu zilifunguka,'),
(2015717,69,42,3,22,'na Roho Mtakatifu akamshukia akiwa na umbo kama la njiwa. Sauti ikasikika kutoka mbinguni: "Wewe ndiwe Mwanangu mpendwa, nimependezwa nawe."'),
(2015718,69,42,3,23,'Yesu alipoanza kazi yake hadharani, alikuwa na umri upatao miaka thelathini, na watu walidhani yeye ni mwana wa Yosefu, mwana wa Heli.'),
(2015719,69,42,3,24,'Heli alikuwa mwana wa Mathati, mwana wa Lawi, mwana wa Melki, mwana wa Yanai, mwana wa Yosefu,'),
(2015720,69,42,3,25,'mwana wa Matathia, mwana wa Amosi, mwana wa Nahumu, mwana wa Hesli, mwana wa Nagai,'),
(2015721,69,42,3,26,'mwana wa Maathi, mwana wa Matathia, mwana wa Shemeni, mwana wa Yoseki, mwana wa Yuda,'),
(2015722,69,42,3,27,'mwana wa Yohanani, mwana wa Resa, mwana wa Zerubabeli, mwana wa Shealtieli, mwana wa Neri,'),
(2015723,69,42,3,28,'mwana wa Melki, mwana wa Adi, mwana wa Kosamu, mwana wa Elmadamu, mwana wa Eri,'),
(2015724,69,42,3,29,'mwana wa Yoshua, mwana wa Eliezeri, mwana wa Yorimu, mwana wa Mathati, mwana wa Lawi,'),
(2015725,69,42,3,30,'mwana wa Simeoni, mwana wa Yuda, mwana wa Yosefu, mwana wa Yonamu, mwana wa Eliakimu,'),
(2015726,69,42,3,31,'mwana wa Melea, mwana wa Mena, mwana wa Matatha, mwana wa Nathani, mwana wa Daudi,'),
(2015727,69,42,3,32,'mwana wa Yese, mwana wa Obedi, mwana wa Boazi, mwana wa Salmoni, mwana wa Nashoni,'),
(2015728,69,42,3,33,'mwana wa Aminadabu, mwana wa Admini, mwana wa Arni, mwana wa Hesroni, mwana wa Feresi, mwana wa Yuda,'),
(2015729,69,42,3,34,'mwana wa Yakobo, mwana wa Isaka, mwana wa Abrahamu, mwana wa Tera, mwana wa Nahori,'),
(2015730,69,42,3,35,'mwana wa Serugi, mwana wa Reu, mwana wa Pelegi, mwana wa Eberi, mwana wa Sala,'),
(2015731,69,42,3,36,'mwana wa Kainani, mwana wa Arfaksadi, mwana wa Shemu, mwana wa Noa, mwana wa Lameki,'),
(2015732,69,42,3,37,'mwana wa Mathusala, mwana wa Henoki, mwana wa Yaredi, mwana wa Mahalaleli, mwana wa Kenani,'),
(2015733,69,42,3,38,'mwana wa Enosi, mwana wa Sethi, mwana wa Adamu, aliyekuwa wa Mungu.'),
(2015734,69,42,4,1,'Yesu alitoka katika mto Yordani akiwa amejaa Roho Mtakatifu, akaongozwa na Roho mpaka jangwani.'),
(2015735,69,42,4,2,'Huko alijaribiwa na Ibilisi kwa muda wa siku arubaini. Wakati huo wote hakula chochote, na baada ya siku hizo akasikia njaa.'),
(2015736,69,42,4,3,'Ndipo Ibilisi akamwambia, "Kama wewe ni Mwana wa Mungu, amuru jiwe hili liwe mkate."'),
(2015737,69,42,4,4,'Yesu akamjibu, "Imeandikwa: `Mtu haishi kwa mkate tu."`'),
(2015738,69,42,4,5,'Kisha Ibilisi akamchukua hadi mahali pa juu, akamwonyesha kwa mara moja falme zote za ulimwengu. Huyo Shetani akamwambia,'),
(2015739,69,42,4,6,'"Nitakupa uwezo juu ya falme zote hizi na fahari zake, kwa maana nimepewa hivi vyote; nikitaka kumpa mtu ninaweza.'),
(2015740,69,42,4,7,'Hivi vyote vitakuwa mali yako wewe, kama ukiniabudu."'),
(2015741,69,42,4,8,'Yesu akamjibu, "Imeandikwa: `Utamwabudu Bwana Mungu wako, na utamtumikia yeye peke yake."`'),
(2015742,69,42,4,9,'Ibilisi akamchukua mpaka Yerusalemu, kwenye mnara wa Hekalu, akamwambia, "Kama wewe ni Mwana wa Mungu,'),
(2015743,69,42,4,10,'kwa maana imeandikwa: `Atawaamuru malaika wake wakulinde,`'),
(2015744,69,42,4,11,'na tena, `Watakuchukua mikononi mwao usije ukajikwaa mguu wako kwenye jiwe."`'),
(2015745,69,42,4,12,'Lakini Yesu akamjibu, "Imeandikwa: `Usimjaribu Bwana Mungu wako."`'),
(2015746,69,42,4,13,'Ibilisi alipokwishamjaribu kwa kila njia, akamwacha kwa muda.'),
(2015747,69,42,4,14,'Yesu alirudi Galilaya akiwa amejaa nguvu za Roho Mtakatifu, na habari zake zikaenea katika sehemu zote za jirani.'),
(2015748,69,42,4,15,'Naye akawa anawafundisha watu katika masunagogi yao, akasifiwa na wote.'),
(2015749,69,42,4,16,'Basi, Yesu alikwenda Nazareti, mahali alipolelewa, na siku ya Sabato, aliingia katika sunagogi, kama ilivyokuwa desturi yake. Akasimama ili asome Maandiko Matakatifu kwa sauti.'),
(2015750,69,42,4,17,'Akapokea kitabu cha nabii Isaya, akakifungua na akakuta mahali palipoandikwa:'),
(2015751,69,42,4,18,'"Roho wa Bwana yu juu yangu, kwani amenipaka mafuta niwahubirie maskini Habari Njema. Amenituma niwatangazie mateka watapata uhuru, vipofu watapata kuona tena; amenituma niwakomboe wanaoonewa,'),
(2015752,69,42,4,19,'na kutangaza mwaka wa neema ya Bwana."'),
(2015753,69,42,4,20,'Baada ya kusoma, akafunga kile kitabu, akampa mtumishi, kisha akaketi; watu wote wakamkodolea macho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015754,69,42,4,21,'Naye akaanza kuwaambia, "Andiko hili mlilosikia likisomwa, limetimia leo."'),
(2015755,69,42,4,22,'Wote wakavutiwa sana naye, wakastaajabia maneno mazuri aliyosema. Wakanena, "Je, huyu si mwana wa Yosefu?"'),
(2015756,69,42,4,23,'Naye akawaambia, "Bila shaka mtaniambia msemo huu: `Mganga jiponye mwenyewe`, na pia mtasema: `Yote tuliyosikia umeyafanya kule Kafarnaumu, yafanye hapa pia katika kijiji chako."`'),
(2015757,69,42,4,24,'Akaendelea kusema, "Hakika nawaambieni, nabii hatambuliwi katika kijiji chake.'),
(2015758,69,42,4,25,'Lakini, sikilizeni! Kweli kulikuwa na wajane wengi katika nchi ya Israeli nyakati za Eliya. Wakati huo mvua iliacha kunyesha kwa muda wa miaka mitatu na nusu; kukawa na njaa kubwa katika nchi yote.'),
(2015759,69,42,4,26,'Hata hivyo, Eliya hakutumwa kwa mjane yeyote ila kwa mwanamke mjane wa Sarepta, Sidoni.'),
(2015760,69,42,4,27,'Tena, katika nchi ya Israeli nyakati za Elisha kulikuwa na wenye ukoma wengi. Hata hivyo, hakuna yeyote aliyetakaswa ila tu Naamani, mwenyeji wa Siria."'),
(2015761,69,42,4,28,'Wote waliokuwa katika lile sunagogi waliposikia hayo walikasirika sana.'),
(2015762,69,42,4,29,'Wakasimama, wakamtoa nje ya mji wao uliokuwa umejengwa juu ya kilima, wakampeleka mpaka kwenye ukingo wa kilima hicho ili wamtupe chini.'),
(2015763,69,42,4,30,'Lakini Yesu akapita katikati yao, akaenda zake.'),
(2015764,69,42,4,31,'Kisha Yesu akashuka mpaka Kafarnaumu katika mkoa wa Galilaya, akawa anawafundisha watu siku ya Sabato.'),
(2015765,69,42,4,32,'Wakastaajabia uwezo aliokuwa nao katika kufundisha.'),
(2015766,69,42,4,33,'Na katika lile sunagogi kulikuwa na mtu aliyekuwa amepagawa na roho ya pepo mchafu; akapiga ukelele wa kuziba masikio:'),
(2015767,69,42,4,34,'"We! Yesu wa Nazareti! Kwa nini unatuingilia? Je, umekuja kutuangamiza? Ninakufahamu wewe ni nani. Wewe ni mjumbe Mtakatifu wa Mungu!"'),
(2015768,69,42,4,35,'Lakini Yesu akamkemea huyo pepo akisema: "Nyamaza! Mtoke mtu huyu!" Basi, huyo pepo baada ya kumwangusha yule mtu chini, akamtoka bila kumdhuru hata kidogo.'),
(2015769,69,42,4,36,'Watu wote wakashangaa, wakawa wanaambiana, "Hili ni jambo la ajabu, maana kwa uwezo na nguvu anawaamuru pepo wachafu watoke, nao wanatoka!"'),
(2015770,69,42,4,37,'Habari zake zikaenea mahali pote katika mkoa ule.'),
(2015771,69,42,4,38,'Yesu alitoka katika lile sunagogi, akaenda nyumbani kwa Simoni. Mama mmoja, mkwewe Simoni, alikuwa na homa kali; wakamwomba amponye.'),
(2015772,69,42,4,39,'Yesu akaenda akasimama karibu naye, akaikemea ile homa, nayo ikamwacha. Mara yule mama akainuka, akawatumikia.'),
(2015773,69,42,4,40,'Jua lilipokuwa linatua, wote waliokuwa na wagonjwa wao mbalimbali waliwaleta kwake; naye akaweka mikono yake juu ya kila mmoja wao, akawaponya wote.'),
(2015774,69,42,4,41,'Pepo waliwatoka watu wengi, wakapiga kelele wakisema: "Wewe u Mwana wa Mungu!" Lakini Yesu akawakemea, wala hakuwaruhusu kusema, maana walimfahamu kwamba yeye ndiye Kristo.'),
(2015775,69,42,4,42,'Kesho yake asubuhi Yesu aliondoka akaenda mahali pa faragha. Watu wakawa wanamtafuta, na walipofika mahali alipokuwa, wakajaribu kumzuia ili asiondoke kwao.'),
(2015776,69,42,4,43,'Lakini yeye akawaambia, "Ninapaswa kuhubiri Habari Njema za Ufalme wa Mungu katika miji mingine pia, maana nilitumwa kwa ajili hiyo."'),
(2015777,69,42,4,44,'Akawa anahubiri katika masunagogi ya Yudea.'),
(2015778,69,42,5,1,'Siku moja Yesu alikuwa amesimama kando ya ziwa Genesareti, na watu wengi walikuwa wamemzunguka wakisongana wanalisikiliza neno la Mungu.'),
(2015779,69,42,5,2,'Akaona mashua mbili ukingoni mwa ziwa; wavuvi wenyewe walikuwa wametoka, wanaosha nyavu zao.'),
(2015780,69,42,5,3,'Baada ya Yesu kuingia katika mashua moja, iliyokuwa ya Simoni, alimtaka Simoni aisogeze majini, mbali kidogo na ukingo wa ziwa. Akaketi, akafundisha umati wa watu akiwa ndani ya mashua.'),
(2015781,69,42,5,4,'Alipomaliza kufundisha, akamwambia Simoni, "Peleka mashua mpaka kilindini, mkatupe nyavu zenu mpate kuvua samaki."'),
(2015782,69,42,5,5,'Simoni akamjibu, "Bwana, tumejitahidi kuvua samaki usiku kucha bila kupata kitu, lakini kwa kuwa umesema, nitatupa nyavu."'),
(2015783,69,42,5,6,'Baada ya kufanya hivyo, wakavua samaki wengi, hata nyavu zao zikaanza kukatika.'),
(2015784,69,42,5,7,'Wakawaita wenzao waliokuwa katika mashua nyingine waje kuwasaidia. Wakaja, wakazijaza mashua zote mbili samaki, hata karibu zingezama.'),
(2015785,69,42,5,8,'Simoni Petro alipoona hayo, akapiga magoti mbele ya Yesu akisema, "Ondoka mbele yangu, ee Bwana, kwa kuwa mimi ni mwenye dhambi!"'),
(2015786,69,42,5,9,'Simoni pamoja na wenzake wote walishangaa kwa kupata samaki wengi vile.'),
(2015787,69,42,5,10,'Hali kadhalika Yakobo na Yohane, wana wa Zebedayo, waliokuwa wavuvi wenzake Simoni. Yesu akamwambia Simoni, "Usiogope; tangu sasa utakuwa ukivua watu."'),
(2015788,69,42,5,11,'Basi, baada ya kuzileta zile mashua ukingoni mwa ziwa, wakaacha yote, wakamfuata.'),
(2015789,69,42,5,12,'Ikawa, Yesu alipokuwa katika mmojawapo wa miji ya huko, mtu mmoja mwenye ukoma mwili mzima akamwona. Basi, mtu huyo akaanguka kifudifudi akamwomba Yesu: "Mheshimiwa, ukitaka, waweza kunitakasa."'),
(2015790,69,42,5,13,'Yesu akaunyosha mkono wake, akamgusa na kusema, "Nataka, takasika!" Mara ule ukoma ukamwacha.'),
(2015791,69,42,5,14,'Yesu akamwamuru: "Usimwambie mtu yeyote; bali nenda ukajionyeshe kwa kuhani, ukatoe sadaka kwa ajili ya kutakasika kwako kama inavyotakiwa na Sheria ya Mose, iwe uthibitisho kwao kwamba umepona."'),
(2015792,69,42,5,15,'Lakini habari za Yesu zilizidi kuenea kila mahali. Watu makundi mengi wakakusanyika ili kumsikiliza na kuponywa magonjwa yao.'),
(2015793,69,42,5,16,'Lakini yeye alikwenda zake mahali pasipo na watu, akawa anasali huko.'),
(2015794,69,42,5,17,'Siku moja Yesu alikuwa akifundisha. Mafarisayo na walimu wa Sheria kutoka katika kila kijiji cha Galilaya, Yudea na Yerusalemu, walikuwa wameketi hapo. Nguvu ya Bwana ilikuwa pamoja naye kwa ajili ya kuponyea wagonjwa.'),
(2015795,69,42,5,18,'Mara watu wakaja wamemchukua mtu mmoja aliyepooza maungo, amelala kitandani; wakajaribu kumwingiza ndani wamweke mbele ya Yesu.'),
(2015796,69,42,5,19,'Lakini kwa sababu ya wingi wa watu, hawakuweza kuingia ndani. Basi, wakapanda juu ya dari, wakaondoa vigae, wakamshusha huyo aliyepooza pamoja na kitanda chake, wakamweka mbele ya Yesu.'),
(2015797,69,42,5,20,'Yesu alipoona jinsi walivyokuwa na imani kubwa, akamwambia huyo mtu, "Rafiki, umesamehewa dhambi zako."'),
(2015798,69,42,5,21,'Walimu wa Sheria na Mafarisayo wakaanza kujiuliza: "Nani huyu anayemkufuru Mungu kwa maneno yake? Hakuna mtu awezaye kusamehe dhambi ila Mungu peke yake!"'),
(2015799,69,42,5,22,'Yesu alitambua mawazo yao, akawauliza, "Mnawaza nini mioyoni mwenu?'),
(2015800,69,42,5,23,'Ni lipi lililo rahisi zaidi: kusema, `Umesamehewa dhambi,` au kusema, `Simama utembee`?'),
(2015801,69,42,5,24,'Basi, nataka mjue kwamba Mwana wa Mtu anao uwezo wa kusamehe dhambi duniani." Hapo akamwambia huyo mtu aliyepooza, "Simama, chukua kitanda chako uende zako nyumbani."'),
(2015802,69,42,5,25,'Mara, huyo mtu aliyepooza akasimama mbele yao wote, akachukua kitanda chake akaenda zake nyumbani huku akimtukuza Mungu.'),
(2015803,69,42,5,26,'Wote wakashangaa na kushikwa na hofu; wakamtukuza Mungu wakisema: "Tumeona maajabu leo."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015804,69,42,5,27,'Baada ya hayo, Yesu akatoka nje, akamwona mtoza ushuru mmoja aitwaye Lawi, ameketi ofisini. Yesu akamwambia, "Nifuate!"'),
(2015805,69,42,5,28,'Lawi akaacha yote, akamfuata.'),
(2015806,69,42,5,29,'Kisha Lawi akamwandalia Yesu karamu kubwa nyumbani mwake; na kundi kubwa la watoza ushuru na watu wengine walikuwa wameketi pamoja nao.'),
(2015807,69,42,5,30,'Mafarisayo na walimu wa Sheria wakawanung`unikia wafuasi wake wakisema: "Mbona mnakula na kunywa pamoja na watoza ushuru na wenye dhambi?"'),
(2015808,69,42,5,31,'Yesu akawajibu, "Wenye afya hawahitaji daktari, lakini wanaomhitaji ni wale walio wagonjwa.'),
(2015809,69,42,5,32,'Sikuja kuwaita watu wema, bali wenye dhambi, ili wapate kutubu."'),
(2015810,69,42,5,33,'Watu wengine wakamwambia Yesu, "Wafuasi wa Yohane mbatizaji hufunga mara nyingi na kusali; hata wafuasi wa Mafarisayo hufanya vivyo hivyo. Lakini wafuasi wako hula na kunywa."'),
(2015811,69,42,5,34,'Yesu akawajibu, "Je, mnaweza kuwataka wale walioalikwa arusini wafunge hali bwana arusi yuko pamoja nao?'),
(2015812,69,42,5,35,'Lakini wakati utafika ambapo bwana arusi ataondolewa kati yao, na wakati huo ndipo watakapofunga."'),
(2015813,69,42,5,36,'Yesu akawaambia mfano huu: "Hakuna mtu akataye kiraka cha nguo mpya na kukitia katika vazi kuukuu; kama akifanya hivyo, atakuwa amelikata hilo vazi jipya, na hicho kiraka hakitachukuana na hilo vazi kuukuu.'),
(2015814,69,42,5,37,'Wala hakuna mtu atiaye divai mpya katika viriba vikuukuu; kwani hiyo divai mpya itavipasua hivyo viriba, divai itamwagika, na viriba vitaharibika.'),
(2015815,69,42,5,38,'Divai mpya hutiwa katika viriba vipya!'),
(2015816,69,42,5,39,'Wala hakuna mtu ambaye hutamani kunywa divai mpya baada ya kunywa ya zamani, kwani husema: `Ile ya zamani ni nzuri zaidi."`'),
(2015817,69,42,6,1,'Siku moja ya Sabato, Yesu alikuwa anapita katika mashamba ya ngano, na wanafunzi wake wakaanza kukwanyua masuke ya ngano, wakaondoa punje zake kwa mikono, wakala.'),
(2015818,69,42,6,2,'Baadhi ya Mafarisayo wakawauliza, "Mbona mnafanya jambo ambalo si halali siku ya Sabato?"'),
(2015819,69,42,6,3,'Yesu akawajibu, "Je, hamjasoma jinsi alivyofanya Daudi pamoja na wenzake wakati walipokuwa na njaa?'),
(2015820,69,42,6,4,'Yeye aliingia ndani ya nyumba ya Mungu, akachukua ile mikate iliyowekwa mbele ya Mungu, akala na kuwapa wenzake. Kisheria, ni makuhani tu peke yao ndio walioruhusiwa kula mikate hiyo."'),
(2015821,69,42,6,5,'Hivyo akawaambia, "Mwana wa Mtu ni Bwana wa Sabato."'),
(2015822,69,42,6,6,'Siku nyingine ya Sabato, Yesu aliingia katika sunagogi, akafundisha. Mle ndani mlikuwa na mtu ambaye mkono wake wa kuume ulikuwa umepooza.'),
(2015823,69,42,6,7,'Walimu wa Sheria na Mafarisayo walitaka kupata kisingizio cha kumshtaki Yesu na hivyo wakawa wanangojea waone kama angemponya mtu siku ya Sabato.'),
(2015824,69,42,6,8,'Lakini Yesu alijua mawazo yao, akamwambia yule mwenye mkono uliopooza, "Inuka, simama katikati." Yule mtu akaenda akasimama katikati.'),
(2015825,69,42,6,9,'Kisha Yesu akawaambia, "Nawaulizeni, je, ni halali siku ya Sabato kutenda jambo jema au kutenda jambo baya; kuokoa maisha au kuyaangamiza?"'),
(2015826,69,42,6,10,'Baada ya kuwatazama wote waliokuwa pale, akamwambia yule mtu, "Nyosha mkono wako." Naye akafanya hivyo, na mkono wake ukawa mzima tena.'),
(2015827,69,42,6,11,'Lakini wao wakakasirika sana, wakajadiliana jinsi ya kumtendea Yesu maovu.'),
(2015828,69,42,6,12,'Siku moja Yesu alikwenda mlimani kusali, akakesha huko usiku kucha akimwomba Mungu.'),
(2015829,69,42,6,13,'Kesho yake aliwaita wanafunzi wake, na miongoni mwao akachagua kumi na wawili ambao aliwaita mitume:'),
(2015830,69,42,6,14,'Simoni (ambaye Yesu alimpa jina Petro) na Andrea ndugu yake, Yakobo na Yohane, Filipo na Bartholomayo,'),
(2015831,69,42,6,15,'Mathayo na Thoma, Yakobo wa Alfayo na Simoni (aliyeitwa Zelote),'),
(2015832,69,42,6,16,'Yuda wa Yakobo na Yuda Iskarioti ambaye baadaye alikuwa msaliti.'),
(2015833,69,42,6,17,'Baada ya kushuka mlimani pamoja na mitume, Yesu alisimama mahali palipokuwa tambarare. Hapo palikuwa na kundi kubwa la wanafunzi wake na umati wa watu waliotoka pande zote za Yudea na Yerusalemu na pwani ya Tiro na Sidoni. Wote walifika kumsikiliza Yesu na kuponywa magonjwa yao.'),
(2015834,69,42,6,18,'Aliwaponya pia wote waliokuwa wanasumbuliwa na pepo wachafu.'),
(2015835,69,42,6,19,'Watu wote walitaka kumgusa, kwa maana nguvu ilikuwa inatoka ndani yake na kuwaponya wote.'),
(2015836,69,42,6,20,'Yesu akawageukia wanafunzi wake, akasema: "Heri ninyi mlio maskini, maana Ufalme wa Mungu ni wenu.'),
(2015837,69,42,6,21,'Heri ninyi mnaosikia njaa sasa, maana baadaye mtashiba. Heri ninyi mnaolia sasa, maana baadaye mtacheka kwa furaha.'),
(2015838,69,42,6,22,'"Heri yenu ninyi iwapo watu watawachukia, watawatenga, watawatukana na kuwaharibieni jina kwa ajili ya Mwana wa Mtu!'),
(2015839,69,42,6,23,'Wakati hayo yatakapotokea, furahini na kucheza, maana hakika tuzo lenu ni kubwa mbinguni. Kwa maana wazee wao waliwatendea manabii vivyo hivyo.'),
(2015840,69,42,6,24,'Lakini ole wenu ninyi mlio matajiri, maana mmekwisha pata faraja yenu.'),
(2015841,69,42,6,25,'Ole wenu ninyi mnaoshiba sasa, maana baadaye mtasikia njaa. Ole wenu ninyi mnaocheka kwa furaha sasa, maana baadaye mtaomboleza na kulia.'),
(2015842,69,42,6,26,'Ole wenu ninyi iwapo watu wote wanawasifu, maana wazee wao waliwafanyia manabii wa uongo vivyo hivyo.'),
(2015843,69,42,6,27,'"Lakini nawaambieni ninyi mnaonisikiliza: wapendeni adui zenu, watendeeni mema wale wanaowachukieni.'),
(2015844,69,42,6,28,'Watakieni baraka wale wanaowalaani, na waombeeni wale wanaowatendea vibaya.'),
(2015845,69,42,6,29,'Mtu akikupiga shavu moja mgeuzie na la pili. Mtu akikunyang`anya koti lako mwachie pia shati lako.'),
(2015846,69,42,6,30,'Yeyote anayekuomba mpe, na mtu akikunyang`anya mali yako usimtake akurudishie.'),
(2015847,69,42,6,31,'Watendeeni wengine kama mnavyotaka wawatendee ninyi.'),
(2015848,69,42,6,32,'"Na ikiwa mnawapenda tu wale wanaowapenda ninyi, je, mtapata tuzo gani? Hakuna! Kwa maana hata wenye dhambi huwapenda wale wanaowapenda wao.'),
(2015849,69,42,6,33,'Tena, kama mkiwatendea mema wale tu wanaowatendeeni mema, mtapata tuzo gani? Hata wenye dhambi hufanya vivyo hivyo!'),
(2015850,69,42,6,34,'Na kama mnawakopesha wale tu mnaotumaini watawalipeni, je, mtapata tuzo gani? Hata wenye dhambi huwakopesha wenye dhambi wenzao ili warudishiwe kima kilekile!'),
(2015851,69,42,6,35,'Ila nyinyi wapendeni adui zenu, na kuwatendea mema; kopesheni bila kutazamia malipo, na tuzo lenu litakuwa kubwa, nanyi mtakuwa watoto wa Mungu aliye juu. Kwa maana yeye ni mwema kwa wale wasio na shukrani na walio wabaya.'),
(2015852,69,42,6,36,'Muwe na huruma kama Baba yenu alivyo na huruma.'),
(2015853,69,42,6,37,'"Msiwahukumu wengine, nanyi hamtahukumiwa; msiwalaumu wengine, nanyi hamtalaumiwa; wasameheni wengine, nanyi mtasamehewa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015854,69,42,6,38,'Wapeni wengine wanavyohitaji, nanyi mtapewa. Naam, mtapokea mikononi mwenu kipimo kilichojaa, kikashindiliwa na kusukwasukwa hata kumwagika. Kwa maana kipimo kilekile mnachotumia kwa wengine ndicho ambacho Mungu atatumia kwenu."'),
(2015855,69,42,6,39,'Akawaambia mfano huu: "Je, kipofu anaweza kumwongoza kipofu mwenzake? La! Wote wataanguka shimoni.'),
(2015856,69,42,6,40,'Mwanafunzi hamshindi mwalimu wake, lakini kila mwanafunzi akisha hitimu huwa kama mwalimu wake.'),
(2015857,69,42,6,41,'Unawezaje kukiona kibanzi kilicho katika jicho la mwenzio, usione boriti iliyo katika jicho lako mwenyewe?'),
(2015858,69,42,6,42,'Au, unawezaje kumwambia mwenzako, `Ndugu, ngoja nikuondoe kibanzi katika jicho lako,` na huku huioni boriti iliyoko katika jicho lako mwenyewe? Mnafiki wewe! Toa kwanza boriti iliyoko jichoni mwako, na hivyo utaona sawasawa kiasi cha kuweza kuondoa kibanzi kilicho katika jicho la ndugu yako.'),
(2015859,69,42,6,43,'"Mti mwema hauzai matunda mabaya, wala mti mbaya hauzai matunda mazuri.'),
(2015860,69,42,6,44,'Watu huutambua mti kutokana na matunda yake. Ni wazi kwamba watu hawachumi tini katika michongoma, wala hawachumi zabibu katika mbigili.'),
(2015861,69,42,6,45,'Mtu mwema hutoa yaliyo mema kutoka katika hazina bora iliyo moyoni mwake; na mtu mbaya hutoa yaliyo mabaya katika hazina mbaya iliyo moyoni mwake, kwa maana mtu huongea kutokana na yale yaliyojaa moyoni mwake.'),
(2015862,69,42,6,46,'"Mbona mwaniita `Bwana, Bwana,` na huku hamtimizi yale ninayosema?'),
(2015863,69,42,6,47,'Nitawapeni mfano unaofaa kuonyesha alivyo yeyote yule anayekuja kwangu, akasikia maneno yangu na kuyatimiza:'),
(2015864,69,42,6,48,'Huyo anafanana na mtu ajengaye nyumba, ambaye amechimba chini na kuweka msingi wake juu ya mwamba; kukatokea mafuriko ya mto, mkondo wa maji ukaipiga nyumba ile, lakini haukuweza kuitikisa, kwa sababu ilikuwa imejengwa imara.'),
(2015865,69,42,6,49,'Lakini yeyote anayesikia maneno yangu lakini asifanye chochote, huyo anafanana na mtu aliyejenga nyumba juu ya udongo, bila msingi. Mafuriko ya mto yakatokea, mkondo wa maji ukaipiga nyumba ile, ikaanguka na kuharibika kabisa!"'),
(2015866,69,42,7,1,'Baada ya kusema yale aliyotaka watu wasikie, Yesu alikwenda Kafarnaumu.'),
(2015867,69,42,7,2,'Huko kulikuwa na jemadari mmoja Mroma ambaye alikuwa na mtumishi wake aliyempenda sana. Huyu mtumishi alikuwa mgonjwa karibu kufa.'),
(2015868,69,42,7,3,'Yule jemadari aliposikia habari za Yesu, aliwatuma wazee fulani Wayahudi waende kumwomba aje amponye mtumishi wake.'),
(2015869,69,42,7,4,'Walipofika kwa Yesu, walimsihi sana, wakasema: "Huyu anastahili afanyiwe jambo hilo,'),
(2015870,69,42,7,5,'maana analipenda taifa letu, na ndiye aliyetujengea lile sunagogi."'),
(2015871,69,42,7,6,'Basi, Yesu akaenda pamoja nao. Alipokuwa karibu kufika nyumbani kwa yule jemadari Mroma, yule jemadari aliwatuma marafiki zake wamwambie Yesu: "Bwana, usijisumbue zaidi, maana mimi sistahili uingie nyumbani mwangu.'),
(2015872,69,42,7,7,'Ndio maana sikujiona nastahili hata kuja kwako; amuru tu, na mtumishi wangu atapona.'),
(2015873,69,42,7,8,'Mimi pia ni mtu niliye chini ya mamlaka, na ninao askari chini yangu. Namwambia mmoja, `Nenda!`, naye huenda; namwambia mwingine, `Njoo!` naye huja; na nikimwambia mtumishi wangu, `Fanya hiki!`, hufanya."'),
(2015874,69,42,7,9,'Yesu aliposikia hayo, alishangaa; halafu akauelekea ule umati wa watu uliokuwa unamfuata, akasema, "Sijaona imani kubwa namna hii hata katika Israeli."'),
(2015875,69,42,7,10,'Wale watu walipowasili nyumbani walimkuta yule mtumishi hajambo kabisa.'),
(2015876,69,42,7,11,'Baadaye kidogo Yesu alikwenda katika mji mmoja uitwao Naini, na wafuasi wake pamoja na kundi kubwa la watu waliandamana naye.'),
(2015877,69,42,7,12,'Basi, alipokuwa anakaribia lango la mji, walitokea watu wamebeba maiti ya kijana mmoja, mtoto wa pekee wa mama mjane. Watu wengi wa mji ule walikuwa pamoja na huyo mama.'),
(2015878,69,42,7,13,'Bwana alipomwona mama huyo, alimwonea huruma, akamwambia, "Usilie."'),
(2015879,69,42,7,14,'Kisha akaenda, akaligusa lile jeneza, na wale waliokuwa wanalichukua wakasimama. Halafu akasema, "Kijana! Nakuamuru, amka!"'),
(2015880,69,42,7,15,'Yule aliyekufa akaketi, akaanza kuongea. Na Yesu akamkabidhi kwa mama yake.'),
(2015881,69,42,7,16,'Watu wote walishikwa na hofu, wakawa wanamtukuza Mungu wakisema: "Nabii mkuu ametokea kati yetu. Mungu amekuja kuwakomboa watu wake."'),
(2015882,69,42,7,17,'Habari hizo zikaenea kote katika Uyahudi na katika nchi za jirani.'),
(2015883,69,42,7,18,'Wanafunzi wa Yohane walimpa habari Yohane juu ya mambo hayo yote. Naye Yohane, baada ya kuwaita wawili kati ya wanafunzi wake,'),
(2015884,69,42,7,19,'aliwatuma kwa Bwana wamwulize: "Wewe ndiye yule ajaye, au tumtazamie mwingine?"'),
(2015885,69,42,7,20,'Wale wanafunzi walipomfikia Yesu wakamwambia, "Yohane Mbatizaji ametutuma kwako tukuulize: `Wewe ndiye yule ajaye, au tumtazamie mwingine?"`'),
(2015886,69,42,7,21,'Wakati huohuo, Yesu alikuwa anawaponya watu wengi waliokuwa wanateseka kwa magonjwa na waliopagawa na pepo wabaya, akawawezesha vipofu wengi kuona tena.'),
(2015887,69,42,7,22,'Basi, Yesu akawajibu, "Nendeni mkamwambie Yohane yale mliyojionea na kuyasikia: vipofu wanaona, viwete wanatembea, wenye ukoma wanatakaswa, viziwi wanasikia, wafu wanafufuliwa, na maskini wanahubiriwa Habari njema.'),
(2015888,69,42,7,23,'Heri mtu yule ambaye hana mashaka nami!"'),
(2015889,69,42,7,24,'Hapo wajumbe wa Yohane walipokwisha kwenda zao, Yesu alianza kuyaambia makundi ya watu juu ya Yohane: "Mlikwenda kule jangwani, hivi mlitaka kuona kitu gani? Mlitaka kuona unyasi unaotikiswa na upepo?'),
(2015890,69,42,7,25,'Basi, mlikwenda kuona nini? Mlikwenda kumwona mtu aliyevalia mavazi maridadi? La hasha! Wanaovaa mavazi maridadi na kuishi maisha ya anasa, hukaa katika majumba ya wafalme!'),
(2015891,69,42,7,26,'Basi, niambieni, mlikwenda kuona nini? Mlikwenda kumwona nabii? Naam, hakika ni zaidi ya nabii.'),
(2015892,69,42,7,27,'Huyu Yohane ndiye anayesemwa katika Maandiko Matakatifu: `Hapa ni mtumishi wangu, asema Bwana; ninamtuma akutangulie, akutayarishie njia."`'),
(2015893,69,42,7,28,'Yesu akamalizia kwa kusema, "Nawaambieni, kati ya binadamu wote hakuna aliye mkubwa zaidi kuliko Yohane Mbatizaji. Hata hivyo, yule aliye mdogo kabisa katika ufalme wa Mungu ni mkubwa zaidi kuliko yeye."'),
(2015894,69,42,7,29,'Waliposikia hayo watu wote na watoza ushuru waliusifu wema wa Mungu; hao ndio wale waliokuwa wameupokea ubatizo wa Yohane.'),
(2015895,69,42,7,30,'Lakini Mafarisayo na walimu wa Sheria walikataa mpango wa Mungu uliowahusu wakakataa kubatizwa na Yohane.'),
(2015896,69,42,7,31,'Yesu akaendelea kusema, "Basi, nitawafananisha watu wa kizazi hiki na kitu gani? Ni watu wa namna gani?'),
(2015897,69,42,7,32,'Ni kama vijana waliokuwa wamekaa sokoni na kuambiana, kikundi kimoja na kingine: `Tumewapigieni ngoma, lakini hamkucheza! Tumeomboleza, lakini hamkulia!`'),
(2015898,69,42,7,33,'Kwa maana Yohane alikuja, yeye alifunga na hakunywa divai, nanyi mkasema: `Amepagawa na pepo!`'),
(2015899,69,42,7,34,'Akaja Mwana wa Mtu; anakula na kunywa, mkasema: `Mwangalieni mlafi huyu na mlevi; rafiki ya watoza ushuru na wenye dhambi!`'),
(2015900,69,42,7,35,'Hata hivyo, hekima ya Mungu imethibitishwa kuwa njema na wote wale wanaoikubali."'),
(2015901,69,42,7,36,'Mfarisayo mmoja alimwalika Yesu kula chakula nyumbani kwake. Akaingia nyumbani mwa huyo Mfarisayo, akakaa kula chakula.'),
(2015902,69,42,7,37,'Basi, katika mji ule kulikuwa na mama mmoja aliyekuwa anaishi maisha mabaya. Alipopata habari kwamba Yesu yuko nyumbani kwa huyo Mfarisayo, alichukua chupa ya alabasta yenye marashi.'),
(2015903,69,42,7,38,'Akaja, akasimama karibu na miguu yake Yesu, akilia, na machozi yake yakamdondokea Yesu miguuni. Huyo mwanamke akaipangusa miguu ya Yesu kwa nywele zake. Kisha akaibusu na kuipaka yale marashi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015904,69,42,7,39,'Yule Mfarisayo aliyemwalika Yesu alipoona hayo, akawaza moyoni mwake, "Kama mtu huyu angekuwa kweli nabii angejua huyu mwanamke ni wa namna gani, ya kwamba ni mwenye dhambi."'),
(2015905,69,42,7,40,'Yesu akamwambia huyo Mfarisayo, "Simoni, ninacho kitu cha kukwambia." Naye Simoni akamwambia, "Ndio Mwalimu, sema." Yesu akasema,'),
(2015906,69,42,7,41,'"Watu wawili walikuwa wamemkopa mtu fedha: mmoja alikuwa amekopa dinari mia tano, na mwingine hamsini.'),
(2015907,69,42,7,42,'Waliposhindwa kulipa madeni yao, huyo mtu aliwasamehe wote wawili. Sasa ni yupi kati ya hao wawili atampenda zaidi huyo bwana?"'),
(2015908,69,42,7,43,'Simoni akamjibu, "Ni dhahiri kwamba yule aliyesamehewa deni kubwa zaidi atampenda zaidi yule bwana." Yesu akamwambia, "Sawa."'),
(2015909,69,42,7,44,'Halafu akamgeukia yule mwanamke na kumwambia Simoni, "Unamwona huyu mwanamke, sivyo? Basi, mimi nilipoingia hapa nyumbani kwako hukunipa maji ya kunawa miguu yangu; lakini mwanamke huyu ameniosha miguu yangu kwa machozi yake na kunipangusa kwa nywele zake.'),
(2015910,69,42,7,45,'Wewe hukunisalimu kwa kunibusu, lakini huyu mwanamke tangu nilipoingia hapa amekuwa akiibusu miguu yangu.'),
(2015911,69,42,7,46,'Wewe hukunionyesha ukarimu wako kwa kunipaka mafuta kichwani, lakini huyu mwanamke amefanya hivyo kwa kunipaka mafuta miguu yangu.'),
(2015912,69,42,7,47,'Kwa hiyo nakwambia amesamehewa dhambi zake nyingi kwa kuwa ameonyesha upendo mkubwa. Mwenye kusamehe kidogo, hupenda kidogo."'),
(2015913,69,42,7,48,'Basi, Yesu akamwambia yule mwanamke, "Umesamehewa dhambi zako."'),
(2015914,69,42,7,49,'Na hapo wale waliokuwa pamoja naye mezani wakaulizana, "Ni mtu wa namna gani huyu awezaye kusamehe dhambi?"'),
(2015915,69,42,7,50,'Naye Yesu akamwambia yule mwanamke, "Imani yako imekuokoa; nenda kwa amani."'),
(2015916,69,42,8,1,'Baada ya hayo, Yesu alipitia katika miji na vijiji akitangaza Habari Njema za Ufalme wa Mungu. Wale kumi na wawili waliandamana naye.'),
(2015917,69,42,8,2,'Pia wanawake kadhaa ambao Yesu alikuwa amewatoa pepo wabaya na kuwaponya magonjwa, waliandamana naye. Hao ndio akina Maria (aitwaye Magdalene), ambaye alitolewa pepo wabaya saba;'),
(2015918,69,42,8,3,'Yoana, mke wa Kuza, mfanyakazi mkuu wa Herode; Susana na wengine kadhaa. Hao wanawake walikuwa wakiwatumikia kwa mali yao wenyewe.'),
(2015919,69,42,8,4,'Kundi kubwa la watu lilikuwa linakusanyika, na watu walikuwa wanamjia Yesu kutoka kila mji. Naye akawaambia mfano huu:'),
(2015920,69,42,8,5,'"Mpanzi alikwenda kupanda mbegu zake. Alipokuwa akipanda zile mbegu, nyingine zilianguka njiani, na wapita njia wakazikanyaga, na ndege wakazila.'),
(2015921,69,42,8,6,'Nyingine zilianguka penye mawe, na baada ya kuota zikanyauka kwa kukosa maji.'),
(2015922,69,42,8,7,'Nyingine zilianguka kati ya miti ya miiba. Ile miti ya miiba ilipoota ikazisonga.'),
(2015923,69,42,8,8,'Nyingine zilianguka katika udongo mzuri, zikaota na kuzaa asilimia mia." Baada ya kusema hayo, akapaaza sauti, akasema, "Mwenye masikio na asikie!"'),
(2015924,69,42,8,9,'Wanafunzi wake wakamwuliza Yesu maana ya mfano huo.'),
(2015925,69,42,8,10,'Naye akajibu, "Ninyi mmejaliwa kujua siri za Ufalme wa Mungu, lakini hao wengine sivyo; ila hao huambiwa kwa mifano, ili wakitazama wasiweze kuona, na wakisikia wasifahamu.'),
(2015926,69,42,8,11,'"Basi, maana ya mfano huu ni hii: mbegu ni neno la Mungu.'),
(2015927,69,42,8,12,'Zile zilizoanguka njiani zinaonyesha watu wale wanaosikia lile neno, halafu Ibilisi akaja na kuliondoa mioyoni mwao wasije wakaamini na hivyo wakaokoka.'),
(2015928,69,42,8,13,'Zile zilizoanguka penye mawe zinaonyesha watu wale ambao wanaposikia juu ya lile neno hulipokea kwa furaha. Hata hivyo, kama zile mbegu, watu hao hawana mizizi maana husadiki kwa kitambo tu, na wanapojaribiwa hukata tamaa.'),
(2015929,69,42,8,14,'Zile zilizoanguka kwenye miti ya miiba ni watu wale wanaosikia lile neno, lakini muda si muda, wanapokwenda zao, husongwa na wasiwasi, mali na anasa za maisha, na hawazai matunda yakakomaa.'),
(2015930,69,42,8,15,'Na zile zilizoanguka kwenye udongo mzuri ndio watu wale wanaolisikia lile neno, wakalizingatia kwa moyo mwema na wa utii. Hao huvumilia mpaka wakazaa matunda.'),
(2015931,69,42,8,16,'"Watu hawawashi taa na kuifunika kwa chombo au kuiweka mvunguni. Lakini huiweka juu ya kinara ili watu wanapoingia ndani wapate kuona mwanga.'),
(2015932,69,42,8,17,'"Chochote kilichofichwa kitafichuliwa na siri yoyote itagunduliwa na kujulikana hadharani.'),
(2015933,69,42,8,18,'"Kwa hiyo, jihadharini jinsi mnavyosikia; maana aliye na kitu ataongezewa, lakini yule asiye na kitu, hata kile anachodhani kuwa anacho, kitachukuliwa."'),
(2015934,69,42,8,19,'Hapo mama na ndugu zake Yesu wakamjia, lakini hawakuweza kumkaribia kwa sababu ya umati wa watu.'),
(2015935,69,42,8,20,'Yesu akapewa habari kwamba mama na ndugu zake walikuwa nje, wanataka kumwona.'),
(2015936,69,42,8,21,'Lakini Yesu akawaambia watu wote, "Mama yangu na ndugu zangu ni wale wanaolisikia neno la Mungu na kulishika."'),
(2015937,69,42,8,22,'Siku moja, Yesu alipanda mashua pamoja na wanafunzi wake, akawaambia, "Tuvuke ziwa twende mpaka ng`ambo." Basi, wakaanza safari.'),
(2015938,69,42,8,23,'Walipokuwa wanasafiri kwa mashua, Yesu alishikwa na usingizi, akalala. Dhoruba kali ikaanza kuvuma, maji yakaanza kuingia ndani ya mashua, wakawa katika hatari.'),
(2015939,69,42,8,24,'Wale wanafunzi wakamwendea Yesu, wakamwamsha wakisema, "Bwana, Bwana! Tunaangamia!" Yesu akaamka, akaikemea dhoruba na mawimbi, navyo vikatulia, kukawa shwari.'),
(2015940,69,42,8,25,'Kisha akawaambia, "Iko wapi imani yenu?" Lakini wao walishangaa na kuogopa huku wakiambiana, "Huyu ni nani basi, hata anaamuru dhoruba na mawimbi, navyo vinamtii?"'),
(2015941,69,42,8,26,'Wakaendelea na safari, wakafika pwani ya nchi ya Wagerase inayokabiliana na Galilaya, ng`ambo ya ziwa.'),
(2015942,69,42,8,27,'Alipokuwa anashuka pwani, mtu mmoja aliyekuwa amepagawa na pepo alimjia kutoka mjini. Kwa muda mrefu mtu huyo, hakuwa anavaa nguo, wala hakuwa anaishi nyumbani bali makaburini.'),
(2015943,69,42,8,28,'Alipomwona Yesu, alipiga kelele na kujitupa chini mbele yake, na kusema kwa sauti kubwa "We, Yesu Mwana wa Mungu Aliye Juu una shauri gani nami? Ninakusihi usinitese!"'),
(2015944,69,42,8,29,'Alisema hivyo kwa kuwa Yesu alikwishamwambia huyo pepo mchafu amtoke mtu huyo. Pepo huyo mchafu alikuwa anamvamia mtu huyo mara nyingi, na ingawa watu walimweka ndani na kumfunga kwa minyororo na pingu, lakini kila mara alivivunja vifungo hivyo, akakimbizwa na pepo huyo mchafu hadi jangwani.'),
(2015945,69,42,8,30,'Basi, Yesu akamwuliza, "Jina lako nani?" Yeye akajibu, "Jina langu ni `Jeshi"`--kwa sababu pepo wengi walikuwa wamempagaa.'),
(2015946,69,42,8,31,'Hao pepo wakamsihi asiwaamuru wamtoke na kwenda kwenye shimo lisilo na mwisho. ic'),
(2015947,69,42,8,32,'Kulikuwa na kundi kubwa la nguruwe wakilisha mlimani. Basi, hao pepo wakamsihi awaruhusu wawaingie. Naye Yesu akawapa ruhusa.'),
(2015948,69,42,8,33,'Kwa hiyo pepo hao wakamtoka yule mtu, wakawaingia wale nguruwe, nao wakaporomoka kwenye ule mteremko mkali, wakatumbukia ziwani, wakazama majini.'),
(2015949,69,42,8,34,'Wale wachungaji walipoona yote yaliyotokea walikimbia, wakaenda kuwapa watu habari, mjini na mashambani.'),
(2015950,69,42,8,35,'Watu wakaja kuona yaliyotokea. Wakamwendea Yesu, wakamwona yule mtu aliyetokwa na pepo ameketi karibu na Yesu, amevaa nguo, ana akili zake, wakaogopa.'),
(2015951,69,42,8,36,'Wale watu walioshuhudia tukio hilo waliwaeleza hao jinsi yule mtu alivyoponywa.'),
(2015952,69,42,8,37,'Wakazi wa nchi ya Gerase walishikwa na hofu kubwa. Kwa hiyo wakamwomba Yesu aondoke, aende zake. Hivyo Yesu alipanda tena mashua, akaondoka.'),
(2015953,69,42,8,38,'Yule mtu aliyetokwa na wale pepo akamsihi aende pamoja naye. Lakini Yesu hakumruhusu, bali akamwambia,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2015954,69,42,8,39,'"Rudi nyumbani ukaeleze yote Mungu aliyokutendea." Basi, yule mtu akaenda akitangaza kila mahali katika mji ule mambo yote Yesu aliyomtendea.'),
(2015955,69,42,8,40,'Yesu aliporudi upande mwingine wa ziwa, kundi la watu lilimkaribisha, kwa maana wote walikuwa wanamngojea.'),
(2015956,69,42,8,41,'Hapo akaja mtu mmoja aitwaye Yairo, ofisa wa sunagogi. Alijitupa miguuni pa Yesu, akamwomba aende nyumbani kwake,'),
(2015957,69,42,8,42,'kwa kuwa binti yake wa pekee, mwana wa pekee mwenye umri wa miaka kumi na miwili, alikuwa mahututi. Yesu alipokuwa akienda, watu wakawa wanamsonga kila upande.'),
(2015958,69,42,8,43,'Kulikuwa na mwanamke mmoja kati ya lile kundi la watu, ambaye alikuwa na ugonjwa wa kutokwa damu kwa muda wa miaka kumi na miwili, ingawa alikuwa amekwisha tumia mali yake yote kwa waganga, hakuna aliyefaulu kumponya.'),
(2015959,69,42,8,44,'Huyo mwanamke alimfuata Yesu nyuma, akagusa pindo la vazi lake. Papo hapo akaponywa ugonjwa wake wa kutokwa damu.'),
(2015960,69,42,8,45,'Yesu akasema, "Ni nani aliyenigusa?" Wote wakasema kwamba hapakuwa na mtu aliyemgusa. Naye Petro akasema, "Mwalimu, umati wa watu umekuzunguka na kukusonga!"'),
(2015961,69,42,8,46,'Lakini Yesu akasema, "Kuna mtu aliyenigusa, maana nimehisi nguvu imenitoka."'),
(2015962,69,42,8,47,'Yule mwanamke alipoona kwamba hawezi kujificha, akajitokeza akitetemeka kwa hofu, akajitupa mbele ya Yesu. Hapo akaeleza mbele ya wote kisa cha kumgusa Yesu na jinsi alivyoponyeshwa mara moja.'),
(2015963,69,42,8,48,'Yesu akamwambia, "Binti, imani yako imekuponya. Nenda kwa amani."'),
(2015964,69,42,8,49,'Alipokuwa bado akiongea, Yairo akaletewa habari kutoka nyumbani: "Binti yako ameshakufa, ya nini kumsumbua Mwalimu zaidi?"'),
(2015965,69,42,8,50,'Yesu aliposikia hayo akamwambia Yairo, "Usiogope; amini tu, naye atapona."'),
(2015966,69,42,8,51,'Alipofika nyumbani hakumruhusu mtu kuingia ndani pamoja naye, isipokuwa Petro, Yohane, Yakobo na wazazi wa huyo msichana.'),
(2015967,69,42,8,52,'Watu wote walikuwa wakilia na kuomboleza kwa ajili yake. Lakini Yesu akawaambia, "Msilie, kwa maana mtoto hajafa, amelala tu!"'),
(2015968,69,42,8,53,'Nao wakamcheka kwa sababu walijua kwamba alikuwa amekufa.'),
(2015969,69,42,8,54,'Lakini Yesu akamshika mkono akasema, "Mtoto amka!"'),
(2015970,69,42,8,55,'Roho yake ikamrudia, akaamka mara. Yesu akaamuru wampe chakula.'),
(2015971,69,42,8,56,'Wazazi wake walishangaa, lakini Yesu akawaamuru wasimwambie mtu yeyote hayo yaliyotendeka.'),
(2015972,69,42,9,1,'Yesu aliwaita wale kumi na wawili, akawapa uwezo juu ya pepo wote, na uwezo wa kuponya wagonjwa.'),
(2015973,69,42,9,2,'Halafu akawatuma waende kuhubiri Ufalme wa Mungu na kuponya wagonjwa.'),
(2015974,69,42,9,3,'Akawaambia, "Mnaposafiri msichukue chochote: msichukue fimbo, wala mkoba, wala chakula, wala fedha, wala hata koti la ziada.'),
(2015975,69,42,9,4,'Nyumba yoyote mtakayoingia na kukaribishwa, kaeni humo mpaka mtakapoondoka katika kijiji hicho.'),
(2015976,69,42,9,5,'Watu wakikataa kuwakaribisha, tokeni katika mji huo, nanyi mnapotoka kung`uteni mavumbi miguuni mwenu kama onyo kwao."'),
(2015977,69,42,9,6,'Basi, wakaanza safari, wakapitia vijijini wakihubiri Habari Njema na kuponya wagonjwa kila mahali.'),
(2015978,69,42,9,7,'Sasa, mtawala Herode, alipata habari za mambo yote yaliyokuwa yanatendeka, akawa na wasiwasi kwa vile walikuwa wakisema: "Yohane amefufuka kutoka wafu!"'),
(2015979,69,42,9,8,'Wengine walisema kwamba Eliya ametokea, na wengine walisema kwamba mmojawapo wa manabii wa kale amerudi duniani.'),
(2015980,69,42,9,9,'Lakini Herode akasema, "Huyo Yohane nilimkata kichwa; sasa ni nani huyu ninayesikia habari zake?" Akawa na hamu ya kumwona.'),
(2015981,69,42,9,10,'Wale mitume waliporudi, walimweleza yote waliyoyafanya. Yesu akawachukua, wakaenda peke yao mjini Bethsaida.'),
(2015982,69,42,9,11,'Lakini wale watu walipojua alikokwenda, walimfuata. Yesu akawakaribisha akawazungumzia juu ya Ufalme wa Mungu, akawaponya wale waliohitaji kuponywa.'),
(2015983,69,42,9,12,'Jua lilipokuwa linaanza kutua, wale kumi na wawili walimwendea wakamwambia, "Waage watu waende kwenye vijiji na mashamba ya karibu, wakajipatie chakula na mahali pa kulala, kwa maana hapa tulipo ni nyikani."'),
(2015984,69,42,9,13,'Lakini Yesu akawaambia, "Wapeni ninyi chakula." Wakamjibu, "Hatuna chochote ila mikate mitano na samaki wawili. Labda twende wenyewe tukawanunulie chakula watu wote hawa!"'),
(2015985,69,42,9,14,'(Walikuwepo pale wanaume wapatao elfu tano.) Basi, Yesu akawaambia wanafunzi wake, "Waambieni watu waketi katika makundi ya watu hamsinihamsini."'),
(2015986,69,42,9,15,'Wanafunzi wakafanya walivyoambiwa, wakawaketisha wote.'),
(2015987,69,42,9,16,'Kisha Yesu akaitwaa ile mikate mitano na wale samaki wawili, akatazama juu mbinguni, akamshukuru Mungu, akavimega, akawapa wanafunzi wake wawagawie watu.'),
(2015988,69,42,9,17,'Wakala wote, wakashiba; wakakusanya makombo ya chakula, wakajaza vikapu kumi na viwili.'),
(2015989,69,42,9,18,'Siku moja, Yesu alikuwa anasali peke yake, na wanafunzi wake walikuwa karibu. Basi, akawauliza, "Eti watu wanasema mimi ni nani?"'),
(2015990,69,42,9,19,'Nao wakamjibu, "Wengine wanasema kuwa wewe ni Yohane mbatizaji, wengine wanasema wewe ni Eliya, hali wengine wanasema kuwa wewe ni mmoja wa manabii wa kale ambaye amefufuka."'),
(2015991,69,42,9,20,'Hapo akawauliza, "Na ninyi je, mwasema mimi ni nani?" Petro akajibu, "Wewe ndiwe Kristo wa Mungu."'),
(2015992,69,42,9,21,'Halafu Yesu akawaamuru wasimwambie mtu yeyote habari hiyo.'),
(2015993,69,42,9,22,'Akaendelea kusema: "Ni lazima Mwana wa Mtu apate mateso mengi na kukataliwa na wazee na makuhani wakuu na walimu wa Sheria; atauawa, lakini siku ya tatu atafufuliwa."'),
(2015994,69,42,9,23,'Kisha akawaambia watu wote, "Mtu yeyote akitaka kuwa mfuasi wangu, ni lazima ajikane nafsi yake, auchukue msalaba wake kila siku, anifuate.'),
(2015995,69,42,9,24,'Maana, mtu anayetaka kuyaokoa maisha yake mwenyewe, atayapoteza; lakini atakayeyapoteza maisha yake kwa ajili yangu, atayaokoa.'),
(2015996,69,42,9,25,'Je, kuna faida gani mtu kuupata utajiri wote wa dunia kwa kujipoteza au kujiangamiza yeye mwenyewe?'),
(2015997,69,42,9,26,'Mtu akinionea aibu mimi na mafundisho yangu, Mwana wa Mtu atamwonea aibu mtu huyo wakati atakapokuja katika utukufu wake na wa Baba na wa malaika watakatifu.'),
(2015998,69,42,9,27,'Nawaambieni kweli, kuna wengine papa hapa ambao hawatakufa kabla ya kuuona Ufalme wa Mungu."'),
(2015999,69,42,9,28,'Yapata siku nane baada ya kusema hayo, Yesu aliwachukua Petro, Yohane na Yakobo, akaenda nao mlimani kusali.'),
(2016000,69,42,9,29,'Alipokuwa akisali, sura yake ilibadilika, mavazi yake yakawa meupe na kung`aa sana.'),
(2016001,69,42,9,30,'Na watu wawili wakaonekana wakizungumza naye, nao ni Mose na Eliya,'),
(2016002,69,42,9,31,'ambao walitokea wakiwa wenye utukufu, wakazungumza naye juu ya kifo chake ambacho angekikamilisha huko Yerusalemu.'),
(2016003,69,42,9,32,'Petro na wenzake walikuwa wamelemewa na usingizi mzito, hata hivyo waliamka, wakauona utukufu wake, wakawaona na wale watu wawili waliokuwa wamesimama pamoja naye.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016004,69,42,9,33,'Basi, watu hao wawili walipokuwa wakiondoka, Petro alimwambia Yesu, "Bwana, ni vizuri kwamba tupo hapa: basi, tujenge vibanda vitatu: kimoja chako, kimoja cha Mose na kimoja cha Eliya."--Kwa kweli hakujua anasema nini.'),
(2016005,69,42,9,34,'Petro alipokuwa akisema hayo, mara wingu likatokea na kuwafunika; na wingu hilo lilipowajia, wale wanafunzi waliogopa sana.'),
(2016006,69,42,9,35,'Sauti ikasikika kutoka katika hilo wingu: "Huyu ndiye Mwanangu niliyemchagua, msikilizeni."'),
(2016007,69,42,9,36,'Baada ya hiyo sauti kusikika, Yesu alionekana akiwa peke yake. Wanafunzi walikaa kimya juu ya tukio hilo, na wakati ule hawakumwambia mtu yeyote mambo hayo waliyoyaona.'),
(2016008,69,42,9,37,'Kesho yake walipokuwa wakishuka kutoka kule mlimani, kundi kubwa la watu lilikutana na Yesu.'),
(2016009,69,42,9,38,'Hapo, mtu mmoja katika lile kundi akapaaza sauti, akasema, "Mwalimu! Ninakusihi umwangalie mwanangu--mwanangu wa pekee!'),
(2016010,69,42,9,39,'Pepo huwa anamshambulia, na mara humfanya apige kelele; humtia kifafa, na povu likamtoka kinywani. Huendelea kumtesa sana, asimwache upesi.'),
(2016011,69,42,9,40,'Niliwaomba wanafunzi wako wamfukuze, lakini hawakuweza."'),
(2016012,69,42,9,41,'Yesu akasema, "Enyi kizazi kisicho na imani, kilichopotoka! Nitakaa nanyi na kuwavumilia mpaka lini?" Kisha akamwambia huyo mtu, "Mlete mtoto wako hapa."'),
(2016013,69,42,9,42,'Wakati mtoto huyo alipokuwa anamjia Yesu, yule pepo alimwangusha chini na kumtia kifafa. Lakini Yesu akamkemea yule pepo mchafu akamponya mtoto na kumkabidhi kwa baba yake.'),
(2016014,69,42,9,43,'Watu wote wakashangazwa na uwezo mkuu wa Mungu. Wale watu walipokuwa bado wanashangaa juu ya mambo yote aliyofanya, Yesu aliwaambia wanafunzi wake,'),
(2016015,69,42,9,44,'"Tegeni masikio, myasikie mambo haya: Mwana wa Mtu anakwenda kutiwa mikononi mwa watu."'),
(2016016,69,42,9,45,'Lakini wao hawakuelewa maana ya usemi huo. Jambo hilo lilikuwa limefichwa kwao ili wasitambue; nao wakaogopa kumwuliza juu ya msemo huo.'),
(2016017,69,42,9,46,'Kukatokea majadiliano kati ya wale wanafunzi kuhusu nani kati yao aliyekuwa mkuu zaidi.'),
(2016018,69,42,9,47,'Yesu aliyajua mawazo yaliyokuwa mioyoni mwao; basi akamchukua mtoto mdogo akamweka karibu naye,'),
(2016019,69,42,9,48,'akawaambia, "Mtu yeyote anayempokea mtoto huyu mdogo kwa jina langu, ananipokea mimi; na yeyote anayenipokea mimi, anampokea yule aliyenituma. Maana yule aliye mdogo kuliko wote kati yenu ndiye aliye mkubwa kuliko wote."'),
(2016020,69,42,9,49,'Yohane alidakia na kusema, "Bwana, tumemwona mtu mmoja akitoa pepo kwa kulitumia jina lako nasi tukajaribu kumkataza kwa kuwa yeye si mmoja wetu."'),
(2016021,69,42,9,50,'Lakini Yesu akamwambia, "Msimkataze; kwani asiyepingana nanyi yuko upande wenu."'),
(2016022,69,42,9,51,'Wakati ulipokaribia ambapo Yesu angechukuliwa juu mbinguni, yeye alikata shauri kwenda Yerusalemu.'),
(2016023,69,42,9,52,'Basi, akawatuma wajumbe wamtangulie, nao wakaenda wakaingia kijiji kimoja cha Wasamaria ili wamtayarishie mahali.'),
(2016024,69,42,9,53,'Lakini wenyeji wa hapo hawakutaka kumpokea kwa sababu alikuwa anaelekea Yerusalemu.'),
(2016025,69,42,9,54,'Basi, wanafunzi wake, kina Yohane na Yakobo, walipoona hayo, wakasema, "Bwana, wataka tuamuru moto ushuke kutoka mbinguni uwateketeze?"'),
(2016026,69,42,9,55,'Lakini yeye akawageukia, akawakemea.*fa*'),
(2016027,69,42,9,56,'Wakatoka, wakaenda kijiji kingine. gani mliyo nayo; kwa maana Mwana wa Mtu hakuja kuyaangamiza maisha ya watu, bali kuyaokoa."'),
(2016028,69,42,9,57,'Walipokuwa wakisafiri njiani, mtu mmoja akamwambia Yesu, "Nitakufuata kokote utakakokwenda."'),
(2016029,69,42,9,58,'Yesu akasema, "Mbweha wana mapango, na ndege wana viota; lakini Mwana wa Mtu hana mahali pa kupumzikia."'),
(2016030,69,42,9,59,'Kisha akamwambia mtu mwingine, "Nifuate." Lakini huyo akasema, "Bwana, niruhusu kwanza niende kumzika baba yangu."'),
(2016031,69,42,9,60,'Yesu akamwambia, "Waache wafu wazike wafu wao; bali wewe nenda ukatangaze Ufalme wa Mungu."'),
(2016032,69,42,9,61,'Na mtu mwingine akamwambia, "Nitakufuata, lakini niruhusu kwanza nikawaage wale walio nyumbani kwangu."'),
(2016033,69,42,9,62,'Yesu akamwambia, "Yeyote anayeshika jembe tayari kulima na huku anaangalia nyuma, hafai kwa Ufalme wa Mungu."'),
(2016034,69,42,10,1,'Baada ya hayo, Bwana aliwachagua wengine sabini na wawili, akawatuma wawiliwawili, wamtangulie katika kila kijiji na mahali ambapo yeye mwenyewe alitaka kwenda.'),
(2016035,69,42,10,2,'Akawaambia, "Mavuno ni mengi, lakini wavunaji ni wachache. Kwa hivyo, mwombeni mwenye shamba atume wavunaji shambani mwake.'),
(2016036,69,42,10,3,'Sasa nendeni; fahamuni kwamba ninawatuma ninyi kama kondoo wanaokwenda kati ya mbwa mwitu.'),
(2016037,69,42,10,4,'Msichukue mfuko wa fedha, mkoba, wala viatu; msimsalimu mtu yeyote njiani.'),
(2016038,69,42,10,5,'Mkiingia katika nyumba yoyote, kwanza wasalimuni hivi: `Amani iwe katika nyumba hii!`'),
(2016039,69,42,10,6,'Kama akiwako mwenye kupenda amani, amani yenu itakaa naye, la sivyo, itawarudieni.'),
(2016040,69,42,10,7,'Kaeni katika nyumba hiyo mkila na kunywa wanavyowapeni, maana mfanyakazi anastahili mshahara wake. Msiende mara nyumba hii mara nyumba ile.'),
(2016041,69,42,10,8,'Kama mkifika mji fulani na watu wakiwakaribisha, kuleni wanavyowapeni.'),
(2016042,69,42,10,9,'Ponyeni wagonjwa walioko huko, waambieni watu: `Ufalme wa Mungu umekaribia kwenu.`'),
(2016043,69,42,10,10,'Lakini mkiingia katika mji wowote, wasipowakaribisheni, tokeni; nanyi mpitapo katika barabara zao semeni:'),
(2016044,69,42,10,11,'`Hata mavumbi ya mji wenu yaliyoshikamana na miguu yetu tunawakung`utieni. Lakini, jueni kwamba Ufalme wa Mungu umekaribia.`'),
(2016045,69,42,10,12,'Hakika nawaambieni, siku ile mji huo utapata adhabu kubwa zaidi kuliko ile ya watu wa Sodoma.'),
(2016046,69,42,10,13,'"Ole wako Korazini! Ole wako Bethsaida! Maana, kama miujiza iliyofanyika kwenu ingalifanyika kule Tiro na Sidoni, watu wake wangalikwishavaa mavazi ya gunia kitambo, na kukaa katika majivu kuonyesha kwamba wametubu.'),
(2016047,69,42,10,14,'Hata hivyo, Siku ya Hukumu ninyi mtapata adhabu kubwa zaidi kuliko ile ya watu wa Tiro na Sidoni.'),
(2016048,69,42,10,15,'Na wewe Kafarnaumu, unataka kujikweza mpaka mbinguni? La; utaporomoshwa mpaka Kuzimu."'),
(2016049,69,42,10,16,'Halafu akasema, "Anayewasikiliza ninyi, ananisikiliza mimi; na anayekataa kuwapokea ninyi, anakataa kunipokea mimi. Yeyote anayekataa kunipokea, anakataa kumpokea yule aliyenituma."'),
(2016050,69,42,10,17,'Baadaye, wale sabini na wawili walirudi wamejaa furaha, wakisema, "Bwana, hata pepo wametutii tulipolitaja jina lako."'),
(2016051,69,42,10,18,'Yeye akawaambia, "Nilimwona Shetani jinsi alivyokuwa anaporomoka kama umeme kutoka mbinguni.'),
(2016052,69,42,10,19,'Naam, nimewapeni uwezo wa kukanyaga nyoka na ng`e, na uwezo juu ya nguvu zote za yule adui; hakuna chochote kitakachowadhuru.'),
(2016053,69,42,10,20,'Hata hivyo, msifurahi kwa sababu pepo wamewatii, bali furahini kwa sababu majina yenu yameandikwa mbinguni." ic');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016054,69,42,10,21,'Saa ileile, Yesu akafurahi kwa uwezo wa Roho Mtakatifu, akasema, "Nakushukuru ee Baba, Bwana wa mbingu na dunia, kwa kuwa umewaficha wenye hekima na elimu mambo haya, ukawafumbulia wadogo. Naam, Baba, ndivyo ilivyokupendeza."'),
(2016055,69,42,10,22,'Kisha akasema, "Baba yangu ameweka yote mikononi mwangu. Hakuna amjuaye Mwana ni nani ila Baba, wala amjuaye Baba ni nani ila Mwana, na yeyote yule ambaye Mwana anataka kumfunulia hayo."'),
(2016056,69,42,10,23,'Halafu akawaelekea wafuasi wake akawaambia, "Heri wanaoona yale mnayoyaona ninyi!'),
(2016057,69,42,10,24,'Hakika, manabii na wafalme walitamani kuona yale mnayoyaona ninyi wasiyaone, na kusikia yale mnayoyasikia wasiyasikie."'),
(2016058,69,42,10,25,'Baadaye mwalimu mmoja wa Sheria alisimama akamwuliza akitaka kumtega, "Mwalimu, nifanye nini ili nipate uzima wa milele?"'),
(2016059,69,42,10,26,'Yesu akamwuliza, "Imeandikwa nini katika Sheria? Unaelewaje?"'),
(2016060,69,42,10,27,'Akamjibu, "Mpende Bwana Mungu wako kwa moyo wako wote, kwa roho yako yote, kwa nguvu zako zote na kwa akili yako yote. Na, mpende jirani yako kama unavyojipenda mwenyewe."'),
(2016061,69,42,10,28,'Yesu akawaambia, "Vema! Fanya hivyo, nawe utaishi."'),
(2016062,69,42,10,29,'Lakini yeye akitaka kujihakikishia kuwa mwema akamwuliza Yesu, "Na jirani yangu ni nani?"'),
(2016063,69,42,10,30,'Yesu akamjibu, "Mtu mmoja alikuwa anashuka kutoka Yerusalemu kwenda Yeriko. Alipokuwa njiani, alivamiwa na majambazi, wakamnyang`anya mali yake na kumpiga, wakamwacha amelala pale nusu mfu.'),
(2016064,69,42,10,31,'Kumbe, kuhani mmoja akawa anapita barabara ileile, akamwona, akapita kando.'),
(2016065,69,42,10,32,'Hali kadhalika na Mlawi mmoja, alipofika mahali akamwona, akapita kando.'),
(2016066,69,42,10,33,'Lakini Msamaria mmoja aliyekuwa anasafiri, alifika pale yule mtu alipokuwa, naye alipomwona, alimwonea huruma.'),
(2016067,69,42,10,34,'Akamwendea, akamtibu majeraha yake kwa kumtia mafuta na divai; na kuyafunga halafu akampandisha juu ya punda wake akampeleka katika nyumba moja ya wageni akamuuguza.'),
(2016068,69,42,10,35,'Kesho yake akatoa fedha dinari mbili akampa yule mwenye nyumba, akamwambia, `Muuguze mtu huyu; na chochote utakachotumia zaidi, nitakulipa nitakaporudi."`'),
(2016069,69,42,10,36,'Kisha Yesu akauliza, "Kati ya hao watatu, ni yupi aliyeonyesha kuwa jirani yake yule aliyevamiwa na majambazi?"'),
(2016070,69,42,10,37,'Yule mwalimu wa Sheria akamjibu, "Ni yule aliyemwonea huruma." Yesu akamwambia, "Nenda ukafanye vivyo hivyo."'),
(2016071,69,42,10,38,'Walipokuwa safarini, waliingia katika kijiji kimoja na mwanamke mmoja, aitwaye Martha, alimkaribisha nyumbani kwake.'),
(2016072,69,42,10,39,'Martha alikuwa na dada yake aitwaye Maria; huyu aliketi karibu na Yesu akisikiliza mafundisho yake.'),
(2016073,69,42,10,40,'Lakini Martha alikuwa anashughulika na mambo mengi. Basi, akamwendea Yesu, akamwambia, "Bwana, hivi hujali kwamba dada yangu ameniacha nishughulike peke yangu? Mwambie basi, anisaidie."'),
(2016074,69,42,10,41,'Lakini Bwana akamjibu, "Martha, Martha, unahangaika na kusumbuka kwa mambo mengi.'),
(2016075,69,42,10,42,'Kitu kimoja tu ni muhimu. Maria amechagua kitu bora zaidi ambacho hakuna mtu atakayemnyag`anya."'),
(2016076,69,42,11,1,'Siku moja, Yesu alikuwa mahali fulani akisali. Alipomaliza kusali, mmoja wa wanafunzi wake akamwambia, "Bwana, tunakuomba utufundishe kusali kama Yohane mbatizaji alivyowafundisha wanafunzi wake."'),
(2016077,69,42,11,2,'Yesu akawaambia, "Mnaposali, semeni: `Baba! Jina lako litukuzwe; Ufalme wako ufike.'),
(2016078,69,42,11,3,'Utupe daima chakula chetu cha kila siku.'),
(2016079,69,42,11,4,'Utusamehe dhambi zetu, maana sisi tunawasamehe wote waliotukosea; wala usitutie katika majaribu."`'),
(2016080,69,42,11,5,'Kisha akawaambia, "Tuseme mmoja wenu anaye rafiki, akaenda kwake usiku wa manane, akamwambia: `Rafiki, tafadhali niazime mikate mitatu,'),
(2016081,69,42,11,6,'kwa kuwa rafiki yangu amepitia kwangu akiwa safarini nami sina cha kumpa.`'),
(2016082,69,42,11,7,'Naye, akiwa ndani angemjibu: `Usinisumbue! Nimekwisha funga mlango. Mimi na watoto wangu tumelala; siwezi kuamka nikupe!`'),
(2016083,69,42,11,8,'Hakika, ingawa hataamka ampe kwa sababu yeye ni rafiki yake, lakini, kwa sababu ya huyo mtu kuendelea kumwomba, ataamka ampe chochote anachohitaji.'),
(2016084,69,42,11,9,'Kwa hiyo, ombeni, nanyi mtapewa, tafuteni, nanyi mtapata, bisheni nanyi mtafunguliwa.'),
(2016085,69,42,11,10,'Maana yeyote aombaye hupewa, atafutaye hupata na abishaye hufunguliwa.'),
(2016086,69,42,11,11,'Mtoto akimwomba baba yake samaki, je, atampa nyoka badala ya samaki?'),
(2016087,69,42,11,12,'Na kama akimwomba yai, je, atampa ng`e?'),
(2016088,69,42,11,13,'Ninyi, ingawa ni waovu, mnajua kuwapa watoto wenu vitu vizuri. Basi, baba yenu wa mbinguni atafanya zaidi; atawapa Roho Mtakatifu wale wanaomwomba."'),
(2016089,69,42,11,14,'Siku moja Yesu alikuwa anamfukuza pepo aliyemfanya mtu mmoja kuwa bubu. Basi, huyo pepo alipomtoka, yule mtu akaweza kuongea hata umati wa watu ukashangaa.'),
(2016090,69,42,11,15,'Lakini baadhi ya watu hao wakasema, "Anamfukuza pepo kwa uwezo wa Beelzebuli, mkuu wa pepo."'),
(2016091,69,42,11,16,'Wengine, wakimjaribu, wakamtaka afanye ishara kuonyesha kama alikuwa na idhini kutoka mbinguni.'),
(2016092,69,42,11,17,'Lakini yeye, akiwa anayajua mawazo yao, akawaambia, "Ufalme wowote uliofarakana wenyewe, hauwezi kudumu; kadhalika, jamaa yeyote inayofarakana huangamia.'),
(2016093,69,42,11,18,'Kama Shetani anajipinga mwenyewe, utawala wake utasimamaje? Mnasemaje, basi, kwamba ninawafukuza pepo kwa uwezo wa Beelzebuli?'),
(2016094,69,42,11,19,'Kama ninafukuza pepo kwa uwezo wa Beelzebuli, watoto wenu huwafukuza kwa uwezo wa nani? Kwa sababu hiyo, wao ndio watakaowahukumu ninyi.'),
(2016095,69,42,11,20,'Lakini ikiwa ninawafukuza pepo kwa uwezo wa Mungu, basi jueni kwamba Ufalme wa Mungu umekwisha fika kwenu.'),
(2016096,69,42,11,21,'"Mtu mwenye nguvu anapolinda jumba lake kwa silaha, mali yake yote iko salama.'),
(2016097,69,42,11,22,'Lakini akija mwenye nguvu zaidi akamshambulia na kumshinda, huyo huziteka silaha zake alizotegemea na kugawanya nyara.'),
(2016098,69,42,11,23,'Yeyote asiyejiunga nami, ananipinga; na yeyote asiyekusanya pamoja nami, hutawanya.'),
(2016099,69,42,11,24,'"Pepo mchafu akifukuzwa kwa mtu fulani, huzururazurura jangwani akitafuta mahali pa kupumzikia. Asipopata, hujisemea: `Nitarudi kwenye makao yangu nilikotoka.`'),
(2016100,69,42,11,25,'Anaporudi, huikuta ile nyumba imefagiwa na kupambwa.'),
(2016101,69,42,11,26,'Basi, huenda na kuwachukua pepo wengine saba waovu zaidi kuliko yeye; wote huenda na kumwingia mtu yule. Hivyo, basi hali ya mtu huyo sasa huwa mbaya zaidi kuliko pale mwanzo."'),
(2016102,69,42,11,27,'Alipokuwa akisema hayo, mwanamke mmoja katika lile kundi la watu, akasema kwa sauti kubwa: "Heri tumbo lililokuzaa, na maziwa yaliyokunyonyesha!"'),
(2016103,69,42,11,28,'Lakini Yesu akasema, "Lakini heri zaidi wale wanaolisikia neno la Mungu na kulishika."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016104,69,42,11,29,'Umati wa watu ulipozidi kuongezeka, Yesu akawaambia, "Kizazi hiki ni kizazi kiovu. Kinataka ishara, lakini hakitapewa ishara yoyote isipokuwa ile ya Yona.'),
(2016105,69,42,11,30,'Jinsi Yona alivyokuwa ishara kwa watu wa Ninewi, ndivyo pia Mwana wa Mtu atakavyokuwa ishara kwa kizazi hiki.'),
(2016106,69,42,11,31,'Malkia wa kusini atatokea wakati kizazi hiki kitakapohukumiwa, naye atashuhudia kwamba kina hatia. Yeye alisafiri kutoka mbali, akaja kusikiliza maneno ya hekima ya Solomoni; kumbe hapa pana mkuu zaidi kuliko Solomoni.'),
(2016107,69,42,11,32,'Watu wa Ninewi watatokea wakati kizazi hiki kitakapohukumiwa, na watashuhudia kwamba kizazi hiki kina hatia. Hao watu wa Ninewi walitubu kwa sababu ya mahubiri ya Yona; na hapa pana mkuu zaidi kuliko Yona!'),
(2016108,69,42,11,33,'"Hakuna mtu anayewasha taa na kuifunika kwa pishi, bali huiweka juu ya kinara ili watu wanaoingia ndani wapate kuona mwanga.'),
(2016109,69,42,11,34,'Jicho lako ni kama taa ya mwili wako; likiwa zima, mwili wako wote utakuwa katika mwanga. Jicho lako likiwa bovu, na mwili wako pia utakuwa katika giza.'),
(2016110,69,42,11,35,'Uwe mwangalifu basi mwanga ulio ndani yako usije ukawa giza.'),
(2016111,69,42,11,36,'Basi, kama mwili wako wote una mwanga, bila kuwa na sehemu yoyote yenye giza, mwili huo utang`aa kikamilifu kama vile taa inavyokuangazia kwa mwanga wake."'),
(2016112,69,42,11,37,'Yesu alipokuwa akiongea, Mfarisayo mmoja alimkaribisha chakula nyumbani kwake, naye akaenda, akaketi kula chakula.'),
(2016113,69,42,11,38,'Huyo Mfarisayo alistaajabu kuona kwamba alikula chakula bila kunawa.'),
(2016114,69,42,11,39,'Bwana akamwambia, "Ninyi Mafarisayo huosha kikombe na sahani kwa nje, lakini ndani mmejaa udhalimu na uovu.'),
(2016115,69,42,11,40,'Wapumbavu ninyi! Je, aliyetengeneza nje si ndiye aliyetengeneza ndani pia?'),
(2016116,69,42,11,41,'Toeni kwa maskini vile vitu vilivyomo ndani, na vingine vyote vitakuwa halali kwenu.'),
(2016117,69,42,11,42,'"Lakini ole wenu Mafarisayo, kwa sababu mnatoza watu zaka hata juu ya majani ya kukolezea chakula, mchicha na majani mengine, na huku hamjali juu ya haki na upendo kwa Mungu. Mambo haya iliwapasa muwe mmeyazingatia bila kuyasahau yale mengine.'),
(2016118,69,42,11,43,'"Ole wenu ninyi Mafarisayo, kwa sababu mnapenda kuketi mbele mahali pa heshima katika masunagogi, na kusalimiwa kwa heshima hadharani.'),
(2016119,69,42,11,44,'Ole wenu, kwa sababu mko kama makaburi yaliyofichika; watu hutembea juu yake bila kufahamu."'),
(2016120,69,42,11,45,'Mmoja wa walimu wa Sheria akamwambia, "Mwalimu, maneno yako yanatukashifu na sisi pia."'),
(2016121,69,42,11,46,'Yesu akamjibu, "Na ninyi walimu wa Sheria, ole wenu; maana mnawatwika watu mizigo isiyochukulika, huku ninyi wenyewe hamnyoshi hata kidole kuwasaidia.'),
(2016122,69,42,11,47,'Ole wenu, kwa kuwa mnajenga makaburi ya manabii wale ambao wazee wenu waliwaua.'),
(2016123,69,42,11,48,'Kwa hiyo mnashuhudia na kukubaliana na matendo ya wazee wenu; maana wao waliwaua hao manabii, nanyi mnajenga makaburi yao.'),
(2016124,69,42,11,49,'Kwa hiyo, Hekima ya Mungu ilisema hivi: `Nitawapelekea manabii na mitume, lakini watawaua baadhi yao, na kuwatesa wengine.`'),
(2016125,69,42,11,50,'Matokeo yake ni kwamba kizazi hiki kitaadhibiwa kwa sababu ya damu ya manabii wote iliyomwagika tangu mwanzo wa ulimwengu;'),
(2016126,69,42,11,51,'tangu kumwagwa damu ya Abeli mpaka kifo cha Zakariya ambaye walimuua kati ya madhabahu na mahali patakatifu. Naam, hakika kizazi hiki kitaadhibiwa kwa matendo haya.'),
(2016127,69,42,11,52,'"Ole wenu ninyi walimu wa Sheria, kwa sababu mmeuficha ule ufunguo wa mlango wa elimu; ninyi wenyewe hamkuingia na mmewazuia waliokuwa wanaingia wasiingie."'),
(2016128,69,42,11,53,'Alipokuwa akitoka pale, wale Mafarisayo na walimu wa Sheria wakaanza kumshambulia vikali na kumsonga kwa maswali mengi'),
(2016129,69,42,11,54,'ili wapate kumnasa kwa maneno yake.'),
(2016130,69,42,12,1,'Wakati watu kwa maelfu walipokuwa wamekusanyika hata wakawa wanakanyagana, Yesu aliwaambia kwanza wanafunzi wake, "Jihadharini na chachu ya Mafarisayo, yaani unafiki.'),
(2016131,69,42,12,2,'Kila kilichofunikwa kitafunuliwa, kila kilichofichika kitafichuliwa.'),
(2016132,69,42,12,3,'Kwa hiyo, kila mliyosema gizani, watu watayasikia katika mwanga, na kila mliyonong`ona faraghani milango imefungwa, yatatangazwa juu ya nyumba.'),
(2016133,69,42,12,4,'"Nawaambieni ninyi rafiki zangu: msiwaogope wale wanaoua mwili, wasiweze kufanya kitu kingine zaidi.'),
(2016134,69,42,12,5,'Nitawaonyesheni yule ambaye ni lazima kumwogopa: mwogopeni yule ambaye baada ya kuua ana uwezo wa kumtupa mtu katika moto wa Jehanamu. Naam, ninawaambieni, mwogopeni huyo.'),
(2016135,69,42,12,6,'Inajulikana kwamba shomoro watano huuzwa kwa senti kumi, au sivyo? Lakini mbele ya Mungu hasahauliki hata mmoja.'),
(2016136,69,42,12,7,'Lakini hata nywele za vichwa vyenu zimehesabiwa zote. Msiogope, basi, ninyi mna thamani zaidi kuliko shomoro wengi!'),
(2016137,69,42,12,8,'"Nawaambieni kweli, kila mtu anayekiri hadharani kwamba yeye ni wangu, Mwana wa Mtu naye atakiri mbele ya malaika wa Mungu kwamba mtu huyo ni wake.'),
(2016138,69,42,12,9,'Lakini, mtu yeyote anayenikana mbele ya watu, naye atakanwa mbele ya malaika wa Mungu.'),
(2016139,69,42,12,10,'"Yeyote anayesema neno la kumpinga Mwana wa Mtu atasamehewa; lakini anayemkufuru Roho Mtakatifu hatasamehewa.'),
(2016140,69,42,12,11,'"Watakapowapeleka ninyi mbele ya masunagogi na mbele ya wakuu na watawala msiwe na wasiwasi juu ya jinsi mtakavyojitetea au jinsi mtakavyosema.'),
(2016141,69,42,12,12,'Kwa maana wakati huo Roho Mtakatifu atawafundisheni kile mnachopaswa kusema."'),
(2016142,69,42,12,13,'Mtu mmoja katika ule umati wa watu akamwambia, "Mwalimu, mwambie ndugu yangu tugawane urithi aliotuachia baba."'),
(2016143,69,42,12,14,'Yesu akamjibu, "Rafiki, ni nani aliyeniweka mimi mwamuzi au msuluhishi kati yenu?"'),
(2016144,69,42,12,15,'Basi, akawaambia wote, "Jihadharini na kila aina ya tamaa; maana uzima wa mtu hautegemei wingi wa vitu alivyo navyo."'),
(2016145,69,42,12,16,'Kisha akawaambia mfano: "Kulikuwa na tajiri mmoja ambaye shamba lake lilizaa mavuno mengi.'),
(2016146,69,42,12,17,'Tajiri huyo akafikiri moyoni mwake: `Nitafanyaje nami sina mahali pa kuhifadhia mavuno yangu?'),
(2016147,69,42,12,18,'Nitafanya hivi: nitabomoa ghala zangu na kujenga kubwa zaidi, na humo nitahifadhi mavuno yangu yote na mali yangu.'),
(2016148,69,42,12,19,'Hapo nitaweza kuiambia roho yangu: sasa unayo akiba ya matumizi kwa miaka na miaka. Ponda mali, ule, unywe na kufurahi.`'),
(2016149,69,42,12,20,'Lakini Mungu akamwambia: `Mpumbavu wewe; leo usiku roho yako itachukuliwa. Na vitu vile vyote ulivyojilundikia vitakuwa vya nani?"`'),
(2016150,69,42,12,21,'Yesu akamaliza kwa kusema "Ndivyo ilivyo kwa mtu anayejilundikia mali kwa ajili yake mwenyewe, lakini si tajiri mbele ya Mungu."'),
(2016151,69,42,12,22,'Kisha Yesu akawaambia wanafunzi wake, "Kwa sababu hiyo nawaambieni, msiwe na wasiwasi juu ya chakula mnachohitaji ili kuishi, wala juu ya mavazi mnayohitaji kwa ajili ya miili yenu.'),
(2016152,69,42,12,23,'Kwa sababu uzima ni bora kuliko chakula, na mwili ni bora kuliko mavazi.'),
(2016153,69,42,12,24,'Chukueni kwa mfano, kunguru: hawapandi, hawavuni wala hawana ghala yoyote. Hata hivyo, Mungu huwalisha. Ninyi mna thamani zaidi kuliko ndege!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016154,69,42,12,25,'Ni nani kati yenu kwa kuwa na wasiwasi anaweza kuongeza urefu wa maisha yake?'),
(2016155,69,42,12,26,'Basi, kama hamwezi kufanya jambo dogo kama hilo, kwa nini kuwa na wasiwasi juu ya yale mengine?'),
(2016156,69,42,12,27,'Angalieni maua jinsi yanavyomea. Hayafanyi kazi wala hayafumi. Hata hivyo, nawahakikishieni kwamba hata Solomoni mwenyewe na fahari zake zote hakupata kuvikwa vizuri kama ua mojawapo.'),
(2016157,69,42,12,28,'Lakini, kama Mungu hulivika vizuri jani la shambani ambalo leo liko na kesho latupwa motoni, je, hatawafanyia ninyi zaidi? Enyi watu wenye imani haba!'),
(2016158,69,42,12,29,'"Basi, msivurugike akili, mkihangaika daima juu ya mtakachokula au mtakachokunywa.'),
(2016159,69,42,12,30,'Kwa maana hayo yote ndiyo yanayohangaikiwa na watu wasiomjua Mungu. Baba yenu anajua kwamba mnahitaji vitu hivyo.'),
(2016160,69,42,12,31,'Shughulikieni kwanza Ufalme wa Mungu, na hayo yote mtapewa kwa ziada.'),
(2016161,69,42,12,32,'"Msiogope, enyi kundi dogo! Maana Baba yenu amependa kuwapeni Ufalme.'),
(2016162,69,42,12,33,'Uzeni mali yenu mkawape maskini misaada. Jifanyieni mifuko isiyochakaa, na jiwekeeni hazina mbinguni ambako haitapungua. Huko wezi hawakaribii, wala nondo hawaharibu.'),
(2016163,69,42,12,34,'Pale ilipo hazina yako, ndipo pia utakapokuwa moyo wako.'),
(2016164,69,42,12,35,'"Muwe tayari! Jifungeni mkanda kiunoni, na taa zenu ziwe zinawaka;'),
(2016165,69,42,12,36,'muwe kama watumishi wanaomngojea bwana wao arudi kutoka arusini, ili wamfungulie mara atakapobisha hodi.'),
(2016166,69,42,12,37,'Heri yao watumishi wale ambao bwana wao atakaporudi atawakuta wanakesha! Nawaambieni hakika, huyo bwana atajifunga mkanda kiunoni, atawaketisha mezani na kuwahudumia.'),
(2016167,69,42,12,38,'Heri yao watumishi hao ikiwa bwana wao atawakuta wanakesha hata ikiwa atarudi usiku wa manane au alfajiri.'),
(2016168,69,42,12,39,'Jueni kwamba, kama mwenye nyumba angejua saa ambayo mwizi atakuja, angekesha, wala hangeiacha nyumba yake ivunjwe.'),
(2016169,69,42,12,40,'Nanyi, kadhalika muwe tayari, maana Mwana wa Mtu atakuja saa msiyoitazamia."'),
(2016170,69,42,12,41,'Petro akamwambia, "Bwana, mfano huo ni kwa ajili yetu tu, au ni kwa ajili ya watu wote?"'),
(2016171,69,42,12,42,'Bwana akajibu, "Ni nani basi, mtumishi aliye mwaminifu na mwenye busara, ambaye bwana wake atamweka juu ya watumishi wake ili awape chakula wakati ufaao?'),
(2016172,69,42,12,43,'Heri yake mtumishi huyo ikiwa bwana wake atakaporudi atamkuta akifanya hivyo.'),
(2016173,69,42,12,44,'Hakika atampa madaraka juu ya mali yake yote.'),
(2016174,69,42,12,45,'Lakini, kama mtumishi huyo atafikiri moyoni mwake: na kusema: `Bwana wangu amekawia sana kurudi` halafu aanze kuwapiga watumishi wenzake, wa kiume au wa kike, na kula, kunywa na kulewa,'),
(2016175,69,42,12,46,'bwana wake atarudi siku asiyoitazamia na saa asiyoijua; atamkatilia mbali na kumweka fungu moja na wasioamini.*fb*'),
(2016176,69,42,12,47,'Mtumishi ambaye anajua matakwa ya bwana wake lakini hajiweki tayari kufanya anavyotakiwa, atapigwa sana.'),
(2016177,69,42,12,48,'Lakini yule afanyaye yanayostahili adhabu bila kujua, atapigwa kidogo. Aliyepewa vingi atatakiwa vingi; aliyekabidhiwa vingi zaidi atatakiwa kutoa vingi zaidi.'),
(2016178,69,42,12,49,'"Nimekuja kuwasha moto duniani, laiti ungekuwa umewaka tayari!'),
(2016179,69,42,12,50,'Ninao ubatizo ambao inanipasa niupokee; jinsi gani ninavyohangaika mpaka ukamilike!'),
(2016180,69,42,12,51,'Mnadhani nimekuja kuleta amani duniani? Hata kidogo; si amani bali utengano.'),
(2016181,69,42,12,52,'Na tangu sasa, jamaa ya watu watano itagawanyika; watatu dhidi ya wawili, na wawili dhidi ya watatu.'),
(2016182,69,42,12,53,'Baba atakuwa dhidi ya mwanawe, mwana dhidi ya baba yake; mama dhidi ya bintiye, binti dhidi ya mama yake; mama mkwe dhidi ya mke wa mwanawe na huyo dhidi ya mama mkwe wake."'),
(2016183,69,42,12,54,'Yesu akayaambia tena makundi ya watu, "Mnapoona mawingu yakitokea upande wa magharibi, mara mwasema: `Mvua itanyesha`, na kweli hunyesha.'),
(2016184,69,42,12,55,'Mnapoona upepo wa kusi unavuma, mwasema `Kutakuwa na hali ya joto` na ndivyo inavyokuwa.'),
(2016185,69,42,12,56,'Enyi wanafiki! Mnajua kutabiri hali ya hewa kwa kuangalia dunia na anga; kwa nini basi, hamwezi kujua maana ya nyakati hizi?'),
(2016186,69,42,12,57,'"Na kwa nini hamwezi kujiamulia wenyewe jambo jema la kufanya?'),
(2016187,69,42,12,58,'Maana kama mshtaki wako anakupeleka mahakamani, ingekuwa afadhali kwako kupatana naye mkiwa bado njiani, ili asije akakupeleka mbele ya hakimu, naye hakimu akakutoa kwa polisi, nao wakakutia ndani.'),
(2016188,69,42,12,59,'Hakika hutatoka huko nakwambia, mpaka utakapomaliza kulipa senti ya mwisho."'),
(2016189,69,42,13,1,'Wakati huo watu fulani walikuja, wakamweleza Yesu juu ya watu wa Galilaya ambao Pilato alikuwa amewaua wakati walipokuwa wanachinja wanyama wao wa tambiko.'),
(2016190,69,42,13,2,'Naye Yesu akawaambia, "Mnadhani Wagalilaya hao walikuwa wahalifu zaidi kuliko Wagalilaya wengine, ati kwa sababu wameteseka hivyo?'),
(2016191,69,42,13,3,'Nawaambieni hakika sivyo; lakini nanyi, hali kadhalika, msipotubu, mtaangamia kama wao.'),
(2016192,69,42,13,4,'Au wale kumi na wanane walioangukiwa na mnara kule Siloamu wakafa; mnadhani wao walikuwa wakosefu zaidi kuliko wengine wote walioishi Yerusalemu?'),
(2016193,69,42,13,5,'Nawaambieni sivyo; lakini nanyi msipotubu, mtaangamia kama wao."'),
(2016194,69,42,13,6,'Kisha, Yesu akawaambia mfano huu: "Mtu mmoja alikuwa na mtini katika shamba lake. Mtu huyu akaenda akitaka kuchuma matunda yake, lakini akaukuta haujazaa hata tunda moja.'),
(2016195,69,42,13,7,'Basi, akamwambia mfanyakazi wake: `Angalia! Kwa miaka mitatu nimekuwa nikija kuchuma matunda ya mtini huu, nami nisiambulie kitu. Ukate! Kwa nini uitumie ardhi bure?`'),
(2016196,69,42,13,8,'Lakini naye akamjibu: `Bwana, tuuache tena mwaka huu; nitauzungushia mtaro na kuutilia mbolea.'),
(2016197,69,42,13,9,'Kama ukizaa matunda mwaka ujao, vema; la sivyo, basi utaweza kuukata."`'),
(2016198,69,42,13,10,'Yesu alikuwa akifundisha katika sunagogi moja siku ya Sabato.'),
(2016199,69,42,13,11,'Na hapo palikuwa na mwanamke mmoja aliyekuwa mgonjwa kwa miaka kumi na minane kutokana na pepo aliyekuwa amempagaa. Kwa sababu hiyo, mwili wake ulikuwa umepindika vibaya hata asiweze kusimama wima.'),
(2016200,69,42,13,12,'Yesu alipomwona, alimwita, akamwambia, "Mama, umeponywa ugonjwa wako."'),
(2016201,69,42,13,13,'Akamwekea mikono, na mara mwili wake ukawa wima tena, akawa anamtukuza Mungu.'),
(2016202,69,42,13,14,'Lakini mkuu wa sunagogi alikasirika kwa sababu Yesu alikuwa amemponya siku ya Sabato. Hivyo akawaambia wale watu walikusanyika pale, "Mnazo siku sita za kufanya kazi. Basi, fikeni siku hizo mkaponywe magonjwa yenu; lakini msije siku ya Sabato."'),
(2016203,69,42,13,15,'Hapo Bwana akamjibu, "Enyi wanafiki! Nani kati yenu hangemfungua ng`ombe au punda wake kutoka zizini ampeleke kunywa maji, hata kama siku hiyo ni ya Sabato?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016204,69,42,13,16,'Sasa, hapa yupo binti wa Abrahamu ambaye Shetani alimfanya kilema kwa muda wa miaka kumi na minane. Je, haikuwa vizuri kumfungulia vifungo vyake siku ya Sabato?"'),
(2016205,69,42,13,17,'Alipokwisha sema hayo, wapinzani wake waliona aibu lakini watu wengine wote wakajaa furaha kwa sababu ya mambo yote aliyotenda.'),
(2016206,69,42,13,18,'Yesu akauliza: "Ufalme wa Mungu unafanana na nini? Nitaulinganisha na nini?'),
(2016207,69,42,13,19,'NI kama mbegu ya haradali aliyotwaa mtu mmoja na kuipanda shambani mwake; ikaota hata ikawa mti. Ndege wa angani wakajenga viota vyao katika matawi yake."'),
(2016208,69,42,13,20,'Tena akauliza: "Nitaulinganisha Ufalme wa Mungu na nini?'),
(2016209,69,42,13,21,'Ni kama chachu aliyoitwaa mama mmoja na kuichanganya pamoja na unga debe moja kisha unga wote ukaumuka wote."'),
(2016210,69,42,13,22,'Yesu alindelea na safari yake kwenda Yerusalemu huku akipitia mijini na vijijini, akihubiri.'),
(2016211,69,42,13,23,'Mtu mmoja akamwuliza, "Je, Mwalimu, watu watakaookoka ni wachache?"'),
(2016212,69,42,13,24,'Yesu akawaambia, "Jitahidini kuingia kwa kupitia mlango mwembamba; maana nawaambieni, wengi watajaribu kuingia lakini hawataweza.'),
(2016213,69,42,13,25,'"Wakati utakuja ambapo mwenye nyumba atainuka na kufunga mlango. Ninyi mtasimama nje na kuanza kupiga hodi mkisema: `Bwana, tufungulie mlango.` Lakini yeye atawajibu: `Sijui mmetoka wapi.`'),
(2016214,69,42,13,26,'Nanyi mtaanza kumwambia: `Sisi ndio wale tuliokula na kunywa pamoja nawe; na wewe ulifundisha katika vijiji vyetu.`'),
(2016215,69,42,13,27,'Lakini yeye atasema: `Sijui ninyi mmetoka wapi; ondokeni mbele yangu, enyi nyote watenda maovu.`'),
(2016216,69,42,13,28,'Ndipo mtakuwa na kulia na kusaga meno, wakati mtakapowaona Abrahamu, Isaka na Yakobo, na manabii wote wapo katika Ufalme wa Mungu, lakini ninyi wenyewe mmetupwa nje!'),
(2016217,69,42,13,29,'Watu watakuja kutoka mashariki na magharibi, kutoka kaskazini na kusini, watakuja na kukaa kwenye karamu katika Ufalme wa Mungu.'),
(2016218,69,42,13,30,'Naam, wale walio wa mwisho watakuwa wa kwanza; na wale walio wa kwanza watakuwa wa mwisho."'),
(2016219,69,42,13,31,'Wakati huohuo, Mafarisayo na watu wengine walimwendea Yesu wakamwambia, "Ondoka hapa uende mahali pengine, kwa maana Herode anataka kukuua."'),
(2016220,69,42,13,32,'Yesu akawajibu, "Nendeni mkamwambie huyo mbweha hivi: `Leo na kesho ninafukuza pepo na kuponya wagonjwa, na siku ya tatu nitakamilisha kazi yangu.`'),
(2016221,69,42,13,33,'Hata hivyo, kwa leo, kesho na kesho kutwa, ni lazima niendelee na safari yangu, kwa sababu si sawa nabii auawe nje ya Yerusalemu.'),
(2016222,69,42,13,34,'"Yerusalemu! We Yerusalemu! Unawaua manabii na kuwapiga mawe wale waliotumwa kwako! Mara ngapi nimetaka kuwakusanya watoto wako pamoja kama kuku anavyokusanya vifaranga vyake chini ya mabawa yake, Lakini wewe umekataa.'),
(2016223,69,42,13,35,'Haya, utaachiwa mwenyewe nyumba yako. Naam, hakika nawaambieni, hamtaniona mpaka wakati utakapofika mseme: `Abarikiwe huyo ajaye kwa jina la Bwana."`'),
(2016224,69,42,14,1,'Siku moja ya Sabato, Yesu alikwenda kula chakula nyumbani kwa mmoja wa viongozi wa Mafarisayo; watu waliokuwapo hapo wakawa wanamchunguza.'),
(2016225,69,42,14,2,'Mbele yake Yesu palikuwa na mtu mmoja aliyekuwa na ugonjwa wa kuvimba mwili.'),
(2016226,69,42,14,3,'Yesu akawauliza walimu wa Sheria na Mafarisayo, "Je, ni halali au la kumponya mtu siku ya sabato?"'),
(2016227,69,42,14,4,'Lakini wao wakakaa kimya. Yesu akamshika huyo mgonjwa, akamponya, akamwacha aende zake.'),
(2016228,69,42,14,5,'Halafu akawaambia, "Ni nani kati yenu ambaye mtoto wake au ng`ombe wake akitumbukia shimoni, hangemtoa hata kama ni siku ya Sabato?"'),
(2016229,69,42,14,6,'Nao hawakuweza kumjibu swali hilo.'),
(2016230,69,42,14,7,'Yesu aliona jinsi wale walioalikwa walivyokuwa wanajichagulia nafasi za heshima, akawaambia mfano:'),
(2016231,69,42,14,8,'"Kama mtu akikualika arusini, usiketi mahali pa heshima isije ikawa amealikwa mwingine mheshimiwa kuliko wewe;'),
(2016232,69,42,14,9,'na mwenyeji wenu ninyi wawili atakuja na kukwambia: `Mwachie huyu nafasi.` Hapo utaaibika mbele ya wote na kulazimika kwenda kuchukua nafasi ya mwisho.'),
(2016233,69,42,14,10,'Bali ukialikwa kwenye karamu, keti mahali pa mwisho, ili mwenyeji wako atakapokuja akwambie: `Rafiki, njoo hapa mbele, mahali pazuri zaidi.` Hapo utakuwa umeheshimika mbele ya wote wanaoketi pamoja nawe.'),
(2016234,69,42,14,11,'Kwa maana yeyote anayejikweza atashushwa, na anayejishusha, atakwezwa."'),
(2016235,69,42,14,12,'Halafu akamwambia na yule aliyemwalika, "Kama ukiwaandalia watu karamu mchana au jioni, usiwaalike rafiki zako au jamaa zako au jirani zako walio matajiri, wasije nao wakakualika nawe ukawa umelipwa kile ulichowatendea.'),
(2016236,69,42,14,13,'Badala yake, unapofanya karamu, waalike maskini, vilema viwete na vipofu,'),
(2016237,69,42,14,14,'nawe utakuwa umepata baraka, kwa kuwa hao hawana cha kukulipa. Maana Mungu atakupa tuzo lako wakati watu wema watakapofufuka."'),
(2016238,69,42,14,15,'Mmoja wa wale waliokuwa wameketi pamoja na Yesu akasema, "Ana heri mtu yule atakayekula chakula katika Ufalme wa Mungu."'),
(2016239,69,42,14,16,'Yesu akamjibu, "Mtu mmoja alifanya karamu kubwa, akaalika watu wengi.'),
(2016240,69,42,14,17,'Wakati wa karamu ulipofika alimtuma mtumishi wake awaambie walioalikwa, `Njoni, kila kitu ni tayari.`'),
(2016241,69,42,14,18,'Lakini wote, kwa namna moja, wakaanza kuomba radhi. Wa kwanza akamwambia mtumishi: `Nimenunua shamba, kwa hiyo sina budi kwenda kuliangalia; nakuomba uniwie radhi.`'),
(2016242,69,42,14,19,'Mwingine akasema: `Nimenunua ng`ombe jozi tano wa kulima; sasa nimo njiani kwenda kuwajaribu; nakuomba uniwie radhi.`'),
(2016243,69,42,14,20,'Na mwingine akasema: `Nimeoa mke, kwa hiyo siwezi kuja.`'),
(2016244,69,42,14,21,'Mtumishi huyo akarudi na kumwarifu bwana wake jambo hilo. Yule mwenye nyumba alikasirika, akamwambia mtumishi wake: `Nenda upesi kwenye barabara na vichochoro vya mji, uwalete hapa ndani maskini, viwete, vipofu na waliolemaa.`'),
(2016245,69,42,14,22,'Baadaye, mtumishi huyo akasema: `Bwana mambo yamefanyika kama ulivyoamuru, lakini bado iko nafasi.`'),
(2016246,69,42,14,23,'Yule bwana akamwambia mtumishi: `Nenda katika barabara na vichochoro vya mji uwashurutishe watu kuingia ili nyumba yangu ijae.'),
(2016247,69,42,14,24,'Kwa maana, nawaambieni, hakuna hata mmoja wa wale walioalikwa atakayeonja karamu yangu."`'),
(2016248,69,42,14,25,'Hapo, makundi mengi yakawa yanaandamana pamoja na Yesu. Basi, akawageukia akawaambia,'),
(2016249,69,42,14,26,'"Mtu yeyote akija kwangu, asipowachukia baba na mama yake, mke wake, watoto, ndugu na dada zake, naam, hata na nafsi yake mwenyewe, hawezi kuwa mwanafunzi wangu.'),
(2016250,69,42,14,27,'Mtu asipochukua msalaba wake na kunifuata hawezi kuwa mwanafunzi wangu.'),
(2016251,69,42,14,28,'Kwa maana, ni nani miongoni mwenu ambaye akitaka kujenga mnara hataketi kwanza akadirie gharama zake ili ajue kama ana kiasi cha kutosha cha kumalizia?'),
(2016252,69,42,14,29,'La sivyo, baada ya kuweka msingi na kushindwa kumaliza, watu watamcheka'),
(2016253,69,42,14,30,'wakisema: `Mtu huyu alianza kujenga, lakini hakumalizia.`');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016254,69,42,14,31,'"Au, ni mfalme gani ambaye, akitaka kwenda kupigana na mfalme mwingine, hataketi kwanza chini na kufikiri kama ataweza, kwa askari wake elfu ishirini?'),
(2016255,69,42,14,32,'Kama anaona hataweza, atawatuma wajumbe kutaka masharti ya amani wakati mfalme huyo mwingine angali mbali.'),
(2016256,69,42,14,33,'Vivyo hivyo, basi, hakuna hata mmoja wenu atakayekuwa mwanafunzi wangu kama asipoachilia kila kitu alicho nacho.'),
(2016257,69,42,14,34,'"Chumvi ni nzuri; lakini ikipoteza ladha yake, itakolezwa na nini?'),
(2016258,69,42,14,35,'Haifai kitu wala kwa udongo wala kwa mbolea. Watu huitupilia mbali. Sikieni basi, kama mna masikio!"'),
(2016259,69,42,15,1,'Siku moja, watoza ushuru na wahalifu wengi walikwenda kumsikiliza Yesu.'),
(2016260,69,42,15,2,'Mafarisayo na walimu wa Sheria wakaanza kunung`unika: "Mtazameni mtu huyu! Anawakaribisha wenye dhambi, na tena anakula nao."'),
(2016261,69,42,15,3,'Yesu akawajibu kwa mfano:'),
(2016262,69,42,15,4,'"Hivi, mtu akiwa na kondoo mia, akigundua kwamba mmoja wao amepotea, atafanya nini? Atawaacha wale tisini na tisa mbugani, na kwenda kumtafuta yule aliyepotea mpaka ampate.'),
(2016263,69,42,15,5,'Akimpata, atambeba mabegani kwa furaha.'),
(2016264,69,42,15,6,'Anapofika nyumbani, atawaita rafiki zake akiwaambia, `Furahini pamoja nami, kwa sababu nimempata yule kondoo wangu aliyepotea.`'),
(2016265,69,42,15,7,'Kadhalika nawaambieni, ndivyo kutakavyokuwa na furaha mbinguni kwa ajili ya kutubu kwa mwenye dhambi mmoja, kuliko kwa ajili ya watu tisini na tisa wanaojiona kuwa wema, wasiohitaji kutubu. ic'),
(2016266,69,42,15,8,'"Au mwaonaje? Tuseme mwanamke fulani ana sarafu kumi za fedha, akipoteza moja, atafanya nini? Atawasha taa, aifagie nyumba na kuitafuta kwa uangalifu mpaka aipate.'),
(2016267,69,42,15,9,'Akiipata, atawaita rafiki na jirani zake akisema, `Furahini pamoja nami, kwa sababu nimeipata ile sarafu yangu iliyopotea.`'),
(2016268,69,42,15,10,'Kadhalika nawaambieni, ndivyo watakavyofurahi malaika wa Mungu kwa sababu ya mwenye dhambi mmoja anayetubu."'),
(2016269,69,42,15,11,'Yesu akaendelea kusema, "Kulikuwa na mtu mmoja mwenye wana wawili.'),
(2016270,69,42,15,12,'Yule mdogo, alimwambia baba yake: `Baba, nipe urithi wangu.` Naye akawagawia mali yake.'),
(2016271,69,42,15,13,'Baada ya siku chache, yule mdogo aliuza urithi wake, akasafiri na fedha aliyopata, akaenda nchi ya mbali ambako aliitumia ovyo.'),
(2016272,69,42,15,14,'Alipomaliza kutumia kila kitu, kukatokea njaa kali katika nchi ile, naye akaanza kuhangaika.'),
(2016273,69,42,15,15,'Akaomba kazi kwa mwananchi mtu mmoja wa huko naye akampeleka shambani mwake kulisha nguruwe.'),
(2016274,69,42,15,16,'Alitamani kula maganda waliyokula wale nguruwe, ila hakuna mtu aliyempa kitu.'),
(2016275,69,42,15,17,'Alipoanza kupata akili akafikiri: `Mbona kuna wafanyakazi wengi wa baba yangu wanaokula na kusaza, nami ninakufa njaa?'),
(2016276,69,42,15,18,'Nitarudi kwa baba yangu na kumwambia: Baba, nimemkosea Mungu, na nimekukosea wewe pia.'),
(2016277,69,42,15,19,'Sistahili hata kuitwa mwanao. Nifanye kama mmoja wa wafanyakazi wako.`'),
(2016278,69,42,15,20,'Basi, akaanza safari ya kurudi kwa baba yake. Alipokuwa bado yu mbali, baba yake alimwona, na kwa moyo wa huruma alimkimbilia, akamkumbatia na kumbusu.'),
(2016279,69,42,15,21,'"Mwanawe akamwambia: `Baba, nimemkosea Mungu, na nimekukosea wewe pia. Sistahili hata kuitwa mwanao.`'),
(2016280,69,42,15,22,'Lakini baba yake akawaambia watumishi wake: `Haraka! Leteni nguo nzuri mkamvike! Mvisheni pete na viatu!'),
(2016281,69,42,15,23,'Mchinjeni ndama mnono; tule kusherehekea!'),
(2016282,69,42,15,24,'Kwa sababu huyu mwanangu alikuwa amekufa, kumbe yu mzima alikuwa amepotea, lakini sasa amepatikana.` Wakaanza kufanya sherehe.'),
(2016283,69,42,15,25,'"Wakati huo kaka yake alikuwa bado shambani. Alipokuwa akirudi na kukaribia nyumbani akasikia vifijo na ngoma.'),
(2016284,69,42,15,26,'Akamwita mmoja wa watumishi, akamwuliza: `Kuna nini?`'),
(2016285,69,42,15,27,'Huyo mtumishi akamwambia: `Ndugu yako amerudi nyumbani, na baba yako amemchinjia ndama mnono kwa kuwa amempata akiwa salama salimini.`'),
(2016286,69,42,15,28,'Huyo kijana mkubwa akawaka hasira hata akakataa kuingia nyumbani. Baba yake akatoka nje na kumsihi aingie.'),
(2016287,69,42,15,29,'Lakini yeye akamjibu: `Kumbuka! Miaka yote nimekutumikia, sijavunja amri yako hata mara moja. Umenipa nini? Hujanipa hata mwana mbuzi mmoja nikafanye sherehe pamoja na rafiki zangu!'),
(2016288,69,42,15,30,'Lakini mtoto wako huyu aliyekula mali yako pamoja na makahaba, mara tu alipokuja umemchinjia yule ndama mnono.`'),
(2016289,69,42,15,31,'Baba yake akamjibu: `Mwanangu, wewe uko pamoja nami siku zote, na kila nilicho nacho ni chako.'),
(2016290,69,42,15,32,'Ilitubidi kufanya sherehe na kufurahi, kwa sababu huyu ndugu yako alikuwa amekufa, kumbe yu mzima; alikuwa amepotea, lakini sasa amepatikana."`'),
(2016291,69,42,16,1,'Yesu aliwaambia wanafunzi wake: "Tajiri mmoja alikuwa na karani wake. Huyu karani alichongewa kwamba alitumia ovyo mali ya tajiri wake.'),
(2016292,69,42,16,2,'Yule tajiri akamwita akamwambia: `Ni mambo gani haya ninayosikia juu yako? Toa hesabu ya mapato na matumizi ya mali yangu, kwa maana huwezi kuwa karani tena.`'),
(2016293,69,42,16,3,'Yule karani akafikiri: `Bwana wangu amenifukuza kazi ya ukarani; nitafanya nini? Kwenda kulima siwezi; kwenda kuombaomba kama maskini ni aibu.'),
(2016294,69,42,16,4,'Naam, najua la kufanya, ili nitakapofukuzwa kazi, watu waweze kunikaribisha nyumbani kwao.`'),
(2016295,69,42,16,5,'Basi, akawaita wadeni wa bwana wake, mmoja mmoja, akamwambia yule wa kwanza: `Unadaiwa kiasi gani na bwana wangu?`'),
(2016296,69,42,16,6,'Yeye akamjibu: `Mapipa mia ya mafuta ya zeituni.` Yule karani akamwambia: `Chukua hati yako ya deni, keti haraka, andika hamsini.`'),
(2016297,69,42,16,7,'Kisha akamwuliza mdeni mwingine: `Wewe unadaiwa kiasi gani?` Yeye akamjibu: `Magunia mia ya ngano.` Yule karani akamwambia: `Chukua hati yako ya deni, andika themanini.`'),
(2016298,69,42,16,8,'"Basi, yule bwana akamsifu huyo karani asiye mwaminifu, kwa kuwa alitumia busara. Kwa maana watu wa dunia hii wana busara zaidi na mambo yao kuliko watu wa mwanga."'),
(2016299,69,42,16,9,'Naye Yesu akaendelea kusema, "Nami nawaambieni, jifanyieni marafiki kutokana na mali ya dunia, ili zitakapowaishieni, mweze kupokewa nao katika makao ya milele.'),
(2016300,69,42,16,10,'Yeyote aliye mwaminifu katika mambo madogo, atakuwa mwaminifu katika mambo makubwa; na yeyote asiye mwaminifu katika mambo madogo, hatakuwa mwaminifu katika mambo makubwa.'),
(2016301,69,42,16,11,'Kama basi, ninyi si hamjawa waaminifu mali mbaya za dunia, ni nani atakayewakabidhi zile mali za kweli?'),
(2016302,69,42,16,12,'Na kama hamjakuwa waaminifu katika mali ya mtu mwingine, ni nani atakayewakabidhi mali yenu wenyewe?'),
(2016303,69,42,16,13,'"Hakuna mtumishi awezaye kuwatumikia mabwana wawili; kwa maana atamchukia mmoja na kumpenda mwingine, au ataambatana na mmoja na kumdharau mwingine. Hamwezi kumtumikia Mungu na mali."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016304,69,42,16,14,'Lakini Mafarisayo waliposikia hayo, kwa vile wao walikuwa wanapenda sana fedha, wakamdharau Yesu.'),
(2016305,69,42,16,15,'Hapo akawaambia, "Ninyi mnajifanya wema mbele ya watu, lakini Mungu anaijua mioyo yenu. Kwa maana kile kinachoonekana kuwa kitukufu mbele ya watu, Mungu anakiona kuwa takataka.'),
(2016306,69,42,16,16,'"Sheria na maandishi ya manabii vilikuweko mpaka wakati wa Yohane mbatizaji. Tangu hapo, Ufalme wa Mungu unahubiriwa, na kila mmoja anauingia kwa nguvu.'),
(2016307,69,42,16,17,'Lakini ni rahisi zaidi mbingu na dunia kupita, kuliko hata herufi moja ya Sheria kufutwa.'),
(2016308,69,42,16,18,'"Yeyote anayemwacha mke wake na kuoa mwingine, anazini; na yeyote anayemwoa mwanamke aliyepewa talaka, anazini.'),
(2016309,69,42,16,19,'"Palikuwa na mtu mmoja tajiri, ambaye alikuwa anavaa mavazi ya bei kubwa sana ya rangi ya zambarau, na ya kitani safi, na kufanya sherehe kila siku.'),
(2016310,69,42,16,20,'Kulikuwa pia na maskini mmoja jina lake Lazaro, aliyekuwa amejaa vidonda na alikuwa analazwa mlangoni pa nyumba ya huyo tajiri.'),
(2016311,69,42,16,21,'Lazaro alitamani kula makombo yaliyoanguka kutoka meza ya tajiri; na zaidi ya hayo, mbwa walikuwa wanakuja na kulamba vidonda vyake!'),
(2016312,69,42,16,22,'"Ikatokea kwamba huyo maskini akafa, malaika wakamchukua, wakamweka karibu na Abrahamu. Na yule tajiri pia akafa, akazikwa.'),
(2016313,69,42,16,23,'Huyo tajiri, alikuwa na mateso makali huko kuzimu, akainua macho yake, akamwona Abrahamu kwa mbali na Lazaro karibu naye.'),
(2016314,69,42,16,24,'Basi, akaita kwa sauti: `Baba Abrahamu, nionee huruma; umtume Lazaro angalau achovye ncha ya kidole chake katika maji, auburudishe ulimi wangu, maana ninateseka mno katika moto huu.`'),
(2016315,69,42,16,25,'Lakini Abrahamu akamjibu: `Kumbuka mwanangu, kwamba ulipokea mema yako katika maisha, naye Lazaro akapokea mabaya. Sasa lakini, yeye anatulizwa, nawe unateswa.'),
(2016316,69,42,16,26,'Licha ya hayo, kati yetu na ninyi kumewekwa shimo kubwa, ili wanaotaka kuja kwenu kutoka huku wasiweze, wala wanaotaka kutoka kwenu kuja kwetu wasiweze.`'),
(2016317,69,42,16,27,'Huyo aliyekuwa tajiri akasema: `Basi baba, nakuomba umtume aende nyumbani kwa baba yangu,'),
(2016318,69,42,16,28,'maana ninao ndugu watano, ili awaonye wasije wakaja huku kwenye mateso.`'),
(2016319,69,42,16,29,'Lakini Abrahamu akamwambia: `Ndugu zako wanao Mose na manabii; waache wawasikilize hao.`'),
(2016320,69,42,16,30,'Lakini yeye akasema: `Sivyo baba Abrahamu, ila kama mtu atafufuka kutoka wafu na kuwaendea, watatubu.`'),
(2016321,69,42,16,31,'Naye Abrahamu akasema: `Kama hawawasikilizi Mose na manabii, hawatajali hata kama mtu angefufuka kutoka wafu."`'),
(2016322,69,42,17,1,'Kisha, Yesu akawaambia wanafunzi wake, "Haiwezekani kabisa kusitokee vikwazo vinavyosababisha dhambi; lakini ole wake mtu yule atakayevisababisha.'),
(2016323,69,42,17,2,'Ingekuwa afadhali kwake kufungiwa shingoni jiwe kubwa la kusagia na kutoswa baharini, kuliko kumkwaza mmoja wa wadogo hawa.'),
(2016324,69,42,17,3,'Jihadharini! Kama ndugu yako akikukosea, mwonye; akitubu, msamehe.'),
(2016325,69,42,17,4,'Na kama akikukosea mara saba kwa siku, na kila mara akarudi kwako akisema `Nimetubu`, lazima umsamehe."'),
(2016326,69,42,17,5,'Mitume wakamwambia Bwana, "Utuongezee imani."'),
(2016327,69,42,17,6,'Naye Bwana akajibu, "Kama imani yenu ingekuwa ndogo hata kama chembe ndogo ya haradali, mngeweza kuuambia mti huu wa mkuyu: `Ng`oka ukajipandikize baharini`, nao ungewatii.'),
(2016328,69,42,17,7,'"Tuseme mmoja wenu ana mtumishi ambaye analima shambani au anachunga kondoo. Je, anaporudi kutoka shambani, atamwambia: `Haraka, njoo ule chakula?`'),
(2016329,69,42,17,8,'La! Atamwambia: `Nitayarishie chakula, ujifunge tayari kunitumikia mpaka nitakapomaliza kula na kunywa, ndipo nawe ule na unywe.`'),
(2016330,69,42,17,9,'Je utamshukuru huyo mtumishi kwa sababu ametimiza aliyoamriwa?'),
(2016331,69,42,17,10,'Hali kadhalika na ninyi mkisha fanya yote mliyoamriwa, semeni: `Sisi ni watumishi tusio na faida, tumetimiza tu yale tuliyotakiwa kufanya."`'),
(2016332,69,42,17,11,'Yesu akiwa safarini kwenda Yerusalemu alipitia mipakani mwa Samaria na Galilaya.'),
(2016333,69,42,17,12,'Alipokuwa anaingia katika kijiji kimoja, watu kumi wenye ukoma walikutana naye, wakasimama kwa mbali.'),
(2016334,69,42,17,13,'Wakapaza sauti wakisema, "Yesu Mwalimu, tuonee huruma!"'),
(2016335,69,42,17,14,'Alipowaona akawaambia, "Nendeni mkajionyeshe kwa makuhani." Basi, ikawa walipokuwa wanakwenda, wakatakasika.'),
(2016336,69,42,17,15,'Mmoja wao alipoona kwamba ameponywa alirudi akimtukuza Mungu kwa sauti kubwa.'),
(2016337,69,42,17,16,'Akajitupa chini mbele ya miguu ya Yesu huku akimshukuru. Huyo alikuwa Msamaria.'),
(2016338,69,42,17,17,'Hapo Yesu akasema, "Je, si watu kumi walitakaswa? Wale tisa wako wapi?'),
(2016339,69,42,17,18,'Hakupatikana mwingine aliyerudi kumtukuza Mungu ila tu huyu mgeni?"'),
(2016340,69,42,17,19,'Halafu akamwambia huyo mtu, "Simama, uende zako; imani yako imekuponya."'),
(2016341,69,42,17,20,'Wakati mmoja, Mafarisayo walimwuliza Yesu, "Ufalme wa Mungu utakuja lini?" Naye akawajibu, "Ufalme wa Mungu hauji kwa namna itakayoweza kuonekana.'),
(2016342,69,42,17,21,'Wala hakuna atakayeweza kusema, `Uko hapa`, au `Uko pale`. Kwa kweli Ufalme wa Mungu uko kati yenu."'),
(2016343,69,42,17,22,'Halafu akawaambia wanafunzi wake, "Siku zinakuja ambapo mtatamani kuona mojawapo ya siku za Mwana wa Mtu, lakini hamtaiona.'),
(2016344,69,42,17,23,'Na watu watawaambieni: `Tazameni yuko hapa`; ninyi msitoke wala msiwafuate.'),
(2016345,69,42,17,24,'Kwa maana kama vile umeme unavyotokea ghafla na kuangaza anga upande mmoja hadi mwingine, ndivyo Mwana wa Mtu atakavyokuwa siku yake.'),
(2016346,69,42,17,25,'Lakini kabla ya hayo, itambidi ateseke sana na kukataliwa na kizazi hiki.'),
(2016347,69,42,17,26,'Kama ilivyokuwa nyakati za Noa, ndivyo itakavyokuwa katika siku za Mwana wa Mtu.'),
(2016348,69,42,17,27,'Watu waliendelea kula na kunywa, kuoa na kuolewa mpaka wakati ule Noa alipoingia katika safina. Gharika ikatokea na kuwaangamiza wote.'),
(2016349,69,42,17,28,'Itakuwa kama ilivyotokea wakati wa Loti. Watu waliendelea kula na kunywa, kununua na kuuza, kupanda mbegu na kujenga.'),
(2016350,69,42,17,29,'Lakini siku ile Loti alipoondoka Sodoma, moto na kiberiti vikanyesha kama mvua kutoka mbinguni na kuwaangamiza wote.'),
(2016351,69,42,17,30,'Ndivyo itakavyokuwa siku ile Mwana wa Mtu atakapofunuliwa.'),
(2016352,69,42,17,31,'"Siku hiyo, yeyote atakayekuwa juu ya paa asishuke nyumbani kuchukua mali yake. Kadhalika, naye atakayekuwa shambani asirudi nyuma.'),
(2016353,69,42,17,32,'Kumbukeni yaliyompata mke wa Loti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016354,69,42,17,33,'Yeyote anayetaka kuiokoa nafsi yake, ataipoteza; na yeyote anayeipoteza, ataiokoa.'),
(2016355,69,42,17,34,'Nawaambieni, siku ile usiku watu wawili watakuwa wanalala pamoja, mmoja atachukuliwa na yule mwingine ataachwa.'),
(2016356,69,42,17,35,'Wanawake wawili watakuwa wakisaga nafaka pamoja; mmoja atachukuliwa na mwingine ataachwa."*fc* atachukuliwa na mwingine ataachwa.\ie'),
(2016357,69,42,17,36,'missing'),
(2016358,69,42,17,37,'Hapo wakamwuliza, "Ni wapi Bwana?" Naye akawaambia, "Ulipo mzoga, ndipo tai watakapokusanyikia."'),
(2016359,69,42,18,1,'Basi, Yesu aliwasimulia mfano kuonyesha kwamba ni lazima kusali daima bila kukata tamaa.'),
(2016360,69,42,18,2,'Alisema: "Katika mji mmoja kulikuwa na hakimu ambaye hakuwa anamcha Mungu wala kumjali binadamu.'),
(2016361,69,42,18,3,'Katika mji huohuo, kulikuwa pia na mama mmoja mjane, ambaye alimwendea huyo hakimu mara nyingi akimwomba amtetee apate haki yake kutoka kwa adui yake.'),
(2016362,69,42,18,4,'Kwa muda mrefu huyo hakimu hakupenda kumtetea huyo mjane; lakini, mwishowe akajisemea: `Ingawa mimi simchi Mungu wala simjali binadamu,'),
(2016363,69,42,18,5,'lakini kwa vile huyu mjane ananisumbua, nitamtetea; la sivyo ataendelea kufika hapa, na mwisho atanichosha kabisa!"`'),
(2016364,69,42,18,6,'Basi, Bwana akaendelea kusema, "Sikieni jinsi alivyosema huyo hakimu mbaya.'),
(2016365,69,42,18,7,'Je, ndio kusema Mungu hatawatetea wale aliowachagua, ambao wanamlilia mchana na usiku? Je, atakawia kuwasikiliza?'),
(2016366,69,42,18,8,'Nawaambieni atawatetea upesi. Hata hivyo, je, kutakuwako na imani duniani wakati Mwana wa Mtu atakapokuja?"'),
(2016367,69,42,18,9,'Halafu Yesu aliwaambia pia mfano wa wale ambao walijiona kuwa wema na kuwadharau wengine.'),
(2016368,69,42,18,10,'"Watu wawili walipanda kwenda Hekaluni kusali: mmoja Mfarisayo, na mwingine mtoza ushuru.'),
(2016369,69,42,18,11,'Huyo Mfarisayo akasimama, akasali kimoyomoyo: `Ee Mungu, nakushukuru kwa vile mimi si kama watu wengine: walafi, wadanganyifu au wazinzi. Nakushukuru kwamba mimi si kama huyu mtoza ushuru.'),
(2016370,69,42,18,12,'Nafunga mara mbili kwa juma, natoa zaka sehemu ya kumi ya pato langu.`'),
(2016371,69,42,18,13,'Lakini yule mtoza ushuru, akiwa amesimama kwa mbali bila hata kuinua macho yake mbinguni, ila tu akijipiga kifua kwa huzuni, alisema: `Ee Mungu, unionee huruma mimi mwenye dhambi.`'),
(2016372,69,42,18,14,'Nawaambieni, huyu mtoza ushuru alirudi nyumbani akiwa amesamehewa. Lakini yule mwingine, sivyo. Kwa maana kila anayejikweza atashushwa, na kila anayejishusha atakwezwa."'),
(2016373,69,42,18,15,'Watu walimletea Yesu watoto wadogo ili awawekee mikono yake. Wanafunzi walipowaona, wakawazuia kwa maneno makali.'),
(2016374,69,42,18,16,'Lakini Yesu akawaita kwake akisema: "Waacheni hao watoto waje kwangu, wala msiwazuie, kwa maana Ufalme wa Mungu ni kwa ajili ya watu kama hawa.'),
(2016375,69,42,18,17,'Nawaambieni kweli, mtu yeyote asiyeupokea Ufalme wa Mungu kama mtoto mdogo, hataingia katika Ufalme huo."'),
(2016376,69,42,18,18,'Kiongozi mmoja, Myahudi, alimwuliza Yesu, "Mwalimu mwema, nifanye nini ili niweze kuupata uzima wa milele?"'),
(2016377,69,42,18,19,'Yesu akamwambia, "Mbona waniita mwema? Hakuna aliye mwema ila Mungu peke yake.'),
(2016378,69,42,18,20,'Unazijua amri: `Usizini; usiue; usiibe; usitoe ushahidi wa uongo; waheshimu baba yako na mama yako."`'),
(2016379,69,42,18,21,'Yeye akasema, "Hayo yote nimeyazingatia tangu ujana wangu."'),
(2016380,69,42,18,22,'Yesu aliposikia hayo akamwambia, "Unatakiwa bado kufanya kitu kimoja: uza kila ulicho nacho, wagawie maskini, na hivyo utakuwa na hazina yako mbinguni; halafu njoo unifuate."'),
(2016381,69,42,18,23,'Lakini huyo mtu aliposikia hayo, alihuzunika sana kwa sababu alikuwa tajiri sana.'),
(2016382,69,42,18,24,'Yesu alipoona akihuzunika hivyo, akasema, "Jinsi gani ilivyo vigumu kwa matajiri kuingia katika Ufalme wa Mungu!'),
(2016383,69,42,18,25,'Naam, ni rahisi zaidi kwa ngamia kupita katika tundu la sindano, kuliko tajiri kuingia katika Ufalme wa Mungu."'),
(2016384,69,42,18,26,'Wale watu waliposikia hayo, wakasema, "Nani basi, atakayeokolewa?"'),
(2016385,69,42,18,27,'Yesu akajibu, "Yasiyowezekana kwa binadamu, yanawezekana kwa Mungu."'),
(2016386,69,42,18,28,'Naye Petro akamwuliza, "Na sisi je? Tumeacha vitu vyote tukakufuata!"'),
(2016387,69,42,18,29,'Yesu akawaambia, "Kweli nawaambieni, mtu yeyote aliyeacha nyumba au mke au kaka au wazazi au watoto kwa ajili ya Ufalme wa Mungu,'),
(2016388,69,42,18,30,'atapokea mengi zaidi wakati huu wa sasa, na kupokea uzima wa milele wakati ujao."'),
(2016389,69,42,18,31,'Yesu aliwachukua kando wale kumi na wawili, akawaambia, "Sikilizeni! Tunakwenda Yerusalemu na huko kila kitu kilichoandikwa na manabii kuhusu Mwana wa Mtu kitakamilishwa.'),
(2016390,69,42,18,32,'Kwa maana atakabidhiwa kwa watu wa mataifa nao watamtendea vibaya na kumtemea mate.'),
(2016391,69,42,18,33,'Watampiga mijeledi, watamuua; lakini siku ya tatu atafufuka."'),
(2016392,69,42,18,34,'Lakini wao hawakuelewa hata kidogo jambo hilo; walikuwa wamefichwa maana ya maneno hayo, na hawakutambua yaliyosemwa.'),
(2016393,69,42,18,35,'Wakati Yesu alipokaribia Yeriko, kulikuwa na mtu mmoja kipofu ameketi njiani akiomba.'),
(2016394,69,42,18,36,'Aliposikia umati wa watu ukipita aliuliza, "Kuna nini?"'),
(2016395,69,42,18,37,'Wakamwambia, "Yesu wa Nazareti anapita."'),
(2016396,69,42,18,38,'Naye akapaza sauti akisema, "Yesu, Mwana wa Daudi, nihurumie!"'),
(2016397,69,42,18,39,'Wale watu waliotangulia wakamkemea wakimwambia anyamaze; lakini yeye akazidi kupaza sauti: "Mwana wa Daudi, nihurumie;"'),
(2016398,69,42,18,40,'Yesu alisimama, akaamuru wamlete mbele yake. Yule kipofu alipofika karibu, Yesu akamwuliza,'),
(2016399,69,42,18,41,'"Unataka nikufanyie nini?" Naye akamjibu, "Bwana, naomba nipate kuona tena."'),
(2016400,69,42,18,42,'Yesu akamwambia, "Ona! Imani yako imekuponya."'),
(2016401,69,42,18,43,'Na mara yule aliyekuwa kipofu akapata kuona, akamfuata Yesu akimtukuza Mungu. Watu wote walipoona hayo, wakamsifu Mungu.'),
(2016402,69,42,19,1,'Yesu aliingia mjini Yeriko, akawa anapita katika njia za mji huo.'),
(2016403,69,42,19,2,'Kulikuwa na mtu mmoja mjini, jina lake Zakayo ambaye alikuwa mkuu wa watoza ushuru tena mtu tajiri.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016404,69,42,19,3,'Alitaka kuona Yesu alikuwa nani, lakini kwa sababu ya umati wa watu, na kwa vile alikuwa mfupi, hakufaulu.'),
(2016405,69,42,19,4,'Hivyo, alitangulia mbio, akapanda juu ya mkuyu ili aweze kumwona Yesu, kwa maana alikuwa apitie hapo.'),
(2016406,69,42,19,5,'Basi, Yesu alipofika mahali pale, aliangalia juu akamwambia, "Zakayo, shuka upesi, maana leo ni lazima nishinde nyumbani mwako."'),
(2016407,69,42,19,6,'Zakayo akashuka haraka, akamkaribisha kwa furaha.'),
(2016408,69,42,19,7,'Watu wote walipoona hayo, wakaanza kunung`unika wakisema, "Amekwenda kukaa kwa mtu mwenye dhambi."'),
(2016409,69,42,19,8,'Lakini Zakayo akasimama akamwambia Yesu, "Sikiliza Bwana! Mimi nitawapa maskini nusu ya mali yangu, na kama nimenyang`anya mtu yeyote kitu, nitamrudishia mara nne."'),
(2016410,69,42,19,9,'Yesu akamwambia, "Leo wokovu umefika katika nyumba hii, kwa vile huyu pia ni wa ukoo wa Abrahamu.'),
(2016411,69,42,19,10,'Kwa maana Mwana wa Mtu amekuja kutafuta na kuokoa waliopotea." ic'),
(2016412,69,42,19,11,'Wakati watu walipokuwa bado wanasikiliza hayo, Yesu akawaambia mfano. (Hapo alikuwa anakaribia Yerusalemu, na watu wale walidhani kwamba muda si muda, Ufalme wa Mungu ungefika.)'),
(2016413,69,42,19,12,'Hivyo akawaambia, "Kulikuwa na mtu mmoja wa ukoo wa kifalme aliyefanya safari kwenda nchi ya mbali ili apokee madaraka ya ufalme, halafu arudi.'),
(2016414,69,42,19,13,'Basi, kabla ya kuondoka aliwaita watumishi wake kumi, akawapa kiasi cha fedha kila mmoja na kumwambia: `Fanyeni nazo biashara mpaka nitakaporudi.`'),
(2016415,69,42,19,14,'Lakini wananchi wenzake walimchukia na hivyo wakatuma wajumbe waende wakaseme: `Hatumtaki huyu atutawale.`'),
(2016416,69,42,19,15,'"Huyo mtu mashuhuri alirudi nyumbani baada ya kufanywa mfalme, na mara akaamuru wale watumishi aliowapa zile fedha waitwe ili aweze kujua kila mmoja amepata faida gani.'),
(2016417,69,42,19,16,'Mtumishi wa kwanza akatokea, akasema: `Mheshimiwa, faida iliyopatikana ni mara kumi ya zile fedha ulizonipa.`'),
(2016418,69,42,19,17,'Naye akamwambia: `Vema; wewe ni mtumishi mwema. Kwa kuwa umekuwa mwaminifu katika jambo dogo, utakuwa na madaraka juu ya miji kumi!`'),
(2016419,69,42,19,18,'Mtumishi wa pili akaja, akasema: `Mheshimiwa, faida iliyopatikana ni mara tano ya zile fedha ulizonipa.`'),
(2016420,69,42,19,19,'Naye akamwambia pia: `Nawe utakuwa na madaraka juu ya miji mitano.`'),
(2016421,69,42,19,20,'"Mtumishi mwingine akaja, akasema: `Chukua fedha yako; niliificha salama katika kitambaa,'),
(2016422,69,42,19,21,'kwa maana niliogopa kwa sababu wewe ni mtu mkali. Wewe ni mtu ambaye huchukua yasiyo yako, na huchuma ambacho hukupanda.`'),
(2016423,69,42,19,22,'Naye akamwambia: `Nakuhukumu kutokana na msemo wako, ewe mtumishi mbaya! Ulijua kwamba mimi ni mtu mkali, ambaye huchukua yasiyo yangu na kuchuma nisichopanda.'),
(2016424,69,42,19,23,'Kwa nini basi, hukuiweka fedha yangu benki, nami ningeichukua pamoja na faida baada ya kurudi kwangu?`'),
(2016425,69,42,19,24,'Hapo akawaambia wale waliokuwa pale: `Mnyang`anyeni hizo fedha, mkampe yule aliyepata faida mara kumi.`'),
(2016426,69,42,19,25,'Nao wakamwambia: `Lakini Mheshimiwa, huyo ana faida ya kiasi hicho mara kumi!`'),
(2016427,69,42,19,26,'Naye akawajibu: `Kila aliye na kitu atapewa na kuzidishiwa. Lakini yule asiye na kitu, hata kile alicho nacho kitachukuliwa.'),
(2016428,69,42,19,27,'Na sasa, kuhusu hao maadui wangu ambao hawapendi niwe mfalme wao, waleteni hapa, mkawaue papa hapa mbele yangu."`'),
(2016429,69,42,19,28,'Yesu alisema hayo, kisha akatangulia mbele yao kuelekea Yerusalemu.'),
(2016430,69,42,19,29,'Alipokaribia kufika Bethfage na Bethania, karibu na mlima wa Mizeituni, aliwatuma wanafunzi wake wawili,'),
(2016431,69,42,19,30,'akawaambia: "Nendeni katika kijiji kilicho mbele yenu. Mtakapokuwa mnaingia kijijini, mtamkuta mwana punda amefungwa ambaye hajatumiwa na mtu. Mfungeni, mkamlete hapa.'),
(2016432,69,42,19,31,'Kama mtu akiwauliza, kwa nini mnamfungua, mwambieni, `Bwana ana haja naye."`'),
(2016433,69,42,19,32,'Basi, wakaenda, wakakuta sawa kama alivyowaambia.'),
(2016434,69,42,19,33,'Walipokuwa wanamfungua yule mwana punda, wenyewe wakawauliza, "Kwa nini mnamfungua mwana punda huyu?"'),
(2016435,69,42,19,34,'Nao wakawajibu, "Bwana anamhitaji."'),
(2016436,69,42,19,35,'Basi, wakampelekea Yesu yule mwana punda. Kisha wakatandika mavazi yao juu yake wakampandisha Yesu.'),
(2016437,69,42,19,36,'Yesu akaendelea na safari, na watu wakatandaza mavazi yao barabarani.'),
(2016438,69,42,19,37,'Alipofika karibu na Yerusalemu, katika mteremko wa mlima wa Mizeituni, umati wote na wanafunzi wake, wakaanza kushangilia na kumtukuza Mungu kwa sauti kubwa, kwa sababu ya mambo makuu waliyoyaona;'),
(2016439,69,42,19,38,'wakawa wanasema: "Abarikiwe Mfalme ajaye kwa jina la Bwana. Amani mbinguni, na utukufu juu mbinguni!"'),
(2016440,69,42,19,39,'Hapo baadhi ya Mafarisayo waliokuwako katika lile kundi la watu, wakamwambia Yesu, "Mwalimu, wanyamazishe wanafunzi wako!"'),
(2016441,69,42,19,40,'Yesu akawajibu, "Nawaambieni, kama hawa wakinyamaza, hakika hayo mawe yatapaza sauti."'),
(2016442,69,42,19,41,'Alipokaribia zaidi na kuuona ule mji, Yesu aliulilia'),
(2016443,69,42,19,42,'akisema: "Laiti ungelijua leo hii yale yaletayo amani! Lakini sasa yamefichika machoni pako.'),
(2016444,69,42,19,43,'Maana siku zaja ambapo adui zako watakuzungushia maboma, watakuzingira na kukusonga pande zote.'),
(2016445,69,42,19,44,'Watakupondaponda wewe pamoja na watoto wako ndani ya kuta zako; hawatakuachia hata jiwe moja juu jingine, kwa sababu hukuutambua wakati Mungu alipokujia kukuokoa."'),
(2016446,69,42,19,45,'Kisha, Yesu aliingia Hekaluni, akaanza kuwafukuzia nje wafanyabiashara'),
(2016447,69,42,19,46,'akisema, "Imeandikwa: `Nyumba yangu itakuwa nyumba ya sala`; lakini ninyi mmeifanya kuwa pango la wanyang`anyi."'),
(2016448,69,42,19,47,'Yesu akawa anafundisha kila siku Hekaluni. Makuhani wakuu, walimu wa Sheria na viongozi wa watu walitaka kumwangamiza,'),
(2016449,69,42,19,48,'lakini hawakuwa na la kufanya, maana watu wote walikuwa wakimsikiliza kwa makini kabisa.'),
(2016450,69,42,20,1,'Siku moja, Yesu alipokuwa akiwafundisha watu Hekaluni na kuwahubiria juu ya Habari Njema, makuhani wakuu na walimu wa Sheria pamoja na wazee walifika,'),
(2016451,69,42,20,2,'wakasema, "Tuambie! Unafanya mambo haya kwa mamlaka gani?"'),
(2016452,69,42,20,3,'Yesu akawaambia, "Na mimi nitawaulizeni swali:'),
(2016453,69,42,20,4,'mamlaka ya Yohane ya kubatiza yalitoka kwa Mungu au kwa watu?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016454,69,42,20,5,'Lakini wao wakajadiliana hivi: "Tukisema yalitoka mbinguni, yeye atatuuliza: `Mbona hamkumsadiki?`'),
(2016455,69,42,20,6,'Na tukisema yalitoka kwa binadamu, watu wote hapa watatupiga mawe, maana wote wanaamini kwamba Yohane alikuwa nabii."'),
(2016456,69,42,20,7,'Basi, wakamwambia, "Hatujui mamlaka hayo yalitoka wapi."'),
(2016457,69,42,20,8,'Yesu akawaambia, "Hata mimi sitawaambia ninafanya mambo haya kwa mamlaka gani."'),
(2016458,69,42,20,9,'Yesu akaendelea kuwaambia watu mfano huu: "Mtu mmoja alilima shamba la mizabibu, akalikodisha kwa wakulima; kisha akasafiri hadi nchi ya mbali, akakaa huko kwa muda mrefu.'),
(2016459,69,42,20,10,'Wakati wa mavuno, mtu huyo alimtuma mtumishi wake kwa wale wakulima, akachukue sehemu ya matunda ya shamba la mizabibu. Lakini wale wakulima wakampiga mtumishi huyo wakamrudisha mikono mitupu.'),
(2016460,69,42,20,11,'Yule bwana akamtuma tena mtumishi mwingine; lakini wao wakampiga huyo vilevile na kumtendea vibaya, wakamrudisha mikono mitupu.'),
(2016461,69,42,20,12,'Akamtuma tena wa tatu; huyu naye, baada ya kumwumiza, wakamfukuza.'),
(2016462,69,42,20,13,'Yule mwenye shamba akafikiri: `Nitafanya nini? Nitamtuma mwanangu mpenzi; labda watamjali yeye.`'),
(2016463,69,42,20,14,'Wale wakulima walipomwona tu, wakasemezana: `Huyu ndiye mrithi. Basi, tumwue ili urithi wake uwe wetu.`'),
(2016464,69,42,20,15,'Basi, wakamtoa nje ya lile shamba la mizabibu, wakamwua." Yesu akauliza, "Yule mwenye shamba atawafanya nini hao wakulima?'),
(2016465,69,42,20,16,'Atakuja kuwaangamiza wakulima hao, na atawapa wakulima wengine hilo shamba la mizabibu." Watu waliposikia maneno hayo, walisema: "Hasha! Yasitukie hata kidogo!"'),
(2016466,69,42,20,17,'Lakini Yesu akawatazama, akawaambia, "Maandiko haya Matakatifu yana maana gani basi? `Jiwe walilokataa waashi, sasa limekuwa jiwe kuu la msingi!`'),
(2016467,69,42,20,18,'Mtu yeyote akianguka juu ya jiwe hilo, atavunjika vipandevipande; na likimwangukia mtu yeyote, litamsaga kabisa."'),
(2016468,69,42,20,19,'Walimu wa Sheria na makuhani wakuu walifahamu kwamba mfano huo ulikuwa unawahusu, na hivyo walitaka kumkamata palepale, ila tu waliogopa watu.'),
(2016469,69,42,20,20,'Basi, wakawa wanatafuta wakati wa kufaa. Wakawahonga watu fulani wajisingizie kuwa wema, wakawatuma wamnase Yesu kwa maswali, na hivyo waweze kumtia nguvuni na kumpeleka kwa wakuu wa serikali.'),
(2016470,69,42,20,21,'Hao wapelelezi wakamwambia, "Mwalimu, tunajua kwamba unasema na kufundisha mambo ya kweli; tunajua kwamba wewe huna ubaguzi; wewe wafundisha ukweli juu ya njia ya Mungu.'),
(2016471,69,42,20,22,'Basi, twambie kama ni halali, au la, kulipa kodi kwa Kaisari!"'),
(2016472,69,42,20,23,'Yesu alitambua mtego wao, akawaambia,'),
(2016473,69,42,20,24,'"Nionyesheni sarafu. Je, sura na chapa ni vya nani?"'),
(2016474,69,42,20,25,'Nao wakamjibu, "Ni vya Kaisari." Yesu akawaambia, "Basi, mpeni Kaisari vilivyo vyake Kaisari, na Mungu vilivyo vyake Mungu."'),
(2016475,69,42,20,26,'Hawakufaulu kumnasa kwa neno lolote pale mbele ya watu na hivyo wakakaa kimya wakilistaajabia jibu lake.'),
(2016476,69,42,20,27,'Kisha Masadukayo, ambao husema kwamba wafu hawafufuki, wakamjia Yesu, wakasema:'),
(2016477,69,42,20,28,'"Mwalimu, Mose alituandikia kwamba kama ndugu ya mtu fulani akifa na kumwacha mjane wake bila watoto, ni lazima ndugu yake amchukue huyo mama mjane, amzalie watoto ndugu yake marehemu.'),
(2016478,69,42,20,29,'Sasa, wakati mmoja kulikuwa na ndugu saba. Yule wa kwanza alioa na baadaye akafa bila kuacha mtoto.'),
(2016479,69,42,20,30,'Yule ndugu wa pili akamwoa yule mjane, naye pia, akafa;'),
(2016480,69,42,20,31,'na ndugu wa tatu vilevile. Mambo yakawa yaleyale kwa wote saba--wote walikufa bila kuacha watoto.'),
(2016481,69,42,20,32,'Mwishowe akafa pia yule mwanamke.'),
(2016482,69,42,20,33,'Je, siku wafu watakapofufuliwa, mwanamke huyo atakuwa mke wa nani? Alikuwa ameolewa na wote saba."'),
(2016483,69,42,20,34,'Yesu akawaambia, "Watu wa nyakati hizi huoa na kuolewa;'),
(2016484,69,42,20,35,'lakini wale ambao Mungu atawawezesha kushiriki ule wakati wa ufufuo, hawataoa wala kuolewa.'),
(2016485,69,42,20,36,'Ama hakika, hawawezi kufa tena, kwa sababu watakuwa kama malaika, na ni watoto wa Mungu kwa vile wamefufuliwa katika wafu.'),
(2016486,69,42,20,37,'Lakini, kwamba kuna kufufuka kutoka wafu, hata Mose alithibitisha jambo hilo katika Maandiko Matakatifu. Katika sehemu ya Maandiko Matakatifu juu ya kile kichaka kilichokuwa kinawaka moto, anamtaja Bwana kama Mungu wa Abrahamu, Isaka na Yakobo.'),
(2016487,69,42,20,38,'Basi, yeye si Mungu wa wafu, bali ni Mungu wa wale walio hai; maana wale aliowaita kwake, wanaishi naye."'),
(2016488,69,42,20,39,'Baadhi ya wale walimu wa Sheria wakasema, "Mwalimu, umejibu vema kabisa."'),
(2016489,69,42,20,40,'Walisema hivyo kwa sababu hawakuthubutu kumwuliza tena maswali mengine.'),
(2016490,69,42,20,41,'Yesu akawauliza, "Yasemekanaje kwamba Kristo ni mwana wa Daudi?'),
(2016491,69,42,20,42,'Maana Daudi mwenyewe anasema katika Zaburi: `Bwana alimwambia Bwana wangu: Keti upande wangu wa kulia'),
(2016492,69,42,20,43,'mpaka niwafanye adui zako kama kiti cha kuwekea miguu yako.`'),
(2016493,69,42,20,44,'Ikiwa Daudi anamwita yeye, `Bwana,` basi atakuwaje mwanawe?"'),
(2016494,69,42,20,45,'Yesu aliwaambia wanafunzi wake mbele ya watu wote,'),
(2016495,69,42,20,46,'"Jihadharini na walimu wa Sheria ambao hupenda kupitapita wamevalia kanzu. Hupenda kusalimiwa na watu kwa heshima masokoni, huketi mahali pa heshima katika masunagogi na kuchukua nafasi za heshima katika karamu.'),
(2016496,69,42,20,47,'Huwadhulumu wajane huku wakisingizia kuwa wema kwa kusali sala ndefu. Hao watapata hukumu kali zaidi!"'),
(2016497,69,42,21,1,'Yesu alitazama kwa makini, akawaona matajiri walivyokuwa wanatia sadaka zao katika hazina ya Hekalu,'),
(2016498,69,42,21,2,'akamwona pia mama mmoja mjane akitumbukiza humo sarafu mbili ndogo.'),
(2016499,69,42,21,3,'Basi, akasema, "Nawaambieni kweli, mama huyu mjane ametia zaidi katika hazina kuliko wote.'),
(2016500,69,42,21,4,'Kwa maana, wengine wote wametoa sadaka zao kutokana na ziada ya mali zao, lakini huyu mama, ingawa ni maskini, ametoa kila kitu alichohitaji kwa kuishi."'),
(2016501,69,42,21,5,'Baadhi ya wanafunzi walikuwa wanazungumza juu ya Hekalu, jinsi lilivyopambwa kwa mawe ya thamani, pamoja na sadaka zilizotolewa kwa Mungu. Yesu akasema,'),
(2016502,69,42,21,6,'"Haya yote mnayoyaona--zitakuja siku ambapo hakuna hata jiwe moja litakalosalia juu ya lingine; kila kitu kitaharibiwa."'),
(2016503,69,42,21,7,'Basi, wakamwuliza, "Mwalimu, mambo hayo yatatokea lini? Na ni ishara gani zitakazoonyesha kwamba karibu mambo hayo yatokee?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016504,69,42,21,8,'Yesu akawajibu, "Jihadharini, msije mkadanganyika. Maana wengi watatokea na kulitumia jina langu wakisema: `Mimi ndiye`, na, `Wakati ule umekaribia`. Lakini ninyi msiwafuate!'),
(2016505,69,42,21,9,'Basi, mtakaposikia habari za vita na misukosuko, msitishike; maana ni lazima hayo yatokee kwanza, lakini mwisho wa yote, bado."'),
(2016506,69,42,21,10,'Halafu akaendelea kusema: "Taifa moja litapigana na taifa lingine, na ufalme mmoja utapigana na ufalme mwingine.'),
(2016507,69,42,21,11,'Kila mahali kutakuwa na mitetemeko mikubwa ya ardhi, kutakuwa na njaa na tauni. Kutakuwa na vituko vya kutisha na ishara kubwa angani.'),
(2016508,69,42,21,12,'Lakini kabla ya kutokea hayo yote, watawatieni nguvuni, watawatesa na kuwapelekeni katika masunagogi na kuwatia gerezani; mtapelekwa mbele ya wafalme na watawala kwa ajili ya jina langu.'),
(2016509,69,42,21,13,'Hii itawapeni fursa ya kushuhudia Habari Njema.'),
(2016510,69,42,21,14,'Muwe na msimamo huu mioyoni mwenu: hakuna kufikiria kabla ya wakati juu ya jinsi mtakavyojitetea,'),
(2016511,69,42,21,15,'kwa sababu mimi mwenyewe nitawapeni ufasaha wa maneno na hekima, hivyo kwamba zenu hawataweza kustahimili wala kupinga.'),
(2016512,69,42,21,16,'Wazazi wenu, ndugu, jamaa na rafiki zenu watawasaliti ninyi; na baadhi yenu mtauawa.'),
(2016513,69,42,21,17,'Watu wote watawachukieni kwa sababu ya jina langu.'),
(2016514,69,42,21,18,'Lakini, hata unywele mmoja wa vichwa vyenu hautapotea.'),
(2016515,69,42,21,19,'Kwa uvumilivu wenu, mtayaokoa maisha yenu.'),
(2016516,69,42,21,20,'"Mtakapoona mji wa Yerusalemu umezungukwa na majeshi, ndipo mtambue ya kwamba wakati umefika ambapo mji huo utaharibiwa.'),
(2016517,69,42,21,21,'Hapo walioko Yudea wakimbilie milimani; wale walio mjini watoke; na wale walio mashambani wasirudi mjini.'),
(2016518,69,42,21,22,'Kwa maana siku hizo ni siku za adhabu, ili yote yaliyoandikwa yatimie.'),
(2016519,69,42,21,23,'Ole wao waja wazito na wanyonyeshao siku hizo! Kwa maana kutakuwa na dhiki kubwa katika nchi, na hasira ya Mungu itawajia watu hawa.'),
(2016520,69,42,21,24,'Wengine watauawa kwa upanga, wengine watachukuliwa mateka katika nchi zote; na mji wa Yerusalemu utakanyagwa na watu wa mataifa mengine, hadi nyakati zao zitakapotimia.'),
(2016521,69,42,21,25,'"Kutakuwa na ishara katika jua na mwezi na nyota. Mataifa duniani yatakuwa na dhiki kwa sababu ya wasiwasi kutokana na mshindo wa mawimbi ya bahari.'),
(2016522,69,42,21,26,'Watu watazirai kwa sababu ya uoga, wakitazamia mambo yatakayoupata ulimwengu; kwa maana nguvu za mbingu zitatikiswa.'),
(2016523,69,42,21,27,'Halafu, watamwona Mwana wa Mtu akija katika wingu, mwenye nguvu na utukufu mwingi.'),
(2016524,69,42,21,28,'Wakati mambo hayo yatakapoanza kutukia, simameni na kuinua vichwa vyenu juu, kwa maana ukombozi wenu umekaribia."'),
(2016525,69,42,21,29,'Kisha akawaambia mfano: "Angalieni mtini na miti mingine yote.'),
(2016526,69,42,21,30,'Mnapoona kwamba imeanza kuchipua majani, mwatambua kwamba wakati wa kiangazi umekaribia.'),
(2016527,69,42,21,31,'Vivyo hivyo, mtakapoona mambo hayo yanatendeka, mtatambua kwamba Ufalme wa Mungu umekaribia.'),
(2016528,69,42,21,32,'Nawaambieni hakika, kizazi hiki cha sasa hakitapita kabla ya hayo yote kutendeka.'),
(2016529,69,42,21,33,'Mbingu na dunia vitapita, lakini maneno yangu hayatapita.'),
(2016530,69,42,21,34,'"Muwe macho, mioyo yenu isije ikalemewa na anasa, ulevi na shughuli za maisha haya. La sivyo, Siku ile itawajieni ghafla.'),
(2016531,69,42,21,35,'Kwa maana itawajia kama mtego, wote wanaoishi duniani pote.'),
(2016532,69,42,21,36,'Muwe waangalifu basi, na salini daima ili muweze kupata nguvu ya kupita salama katika mambo haya yote yatakayotokea, na kusimama mbele ya Mwana wa Mtu."'),
(2016533,69,42,21,37,'Wakati wa mchana, siku hizo, Yesu alikuwa akifundisha watu Hekaluni; lakini usiku alikuwa akienda katika mlima wa Mizeituni na kukaa huko.'),
(2016534,69,42,21,38,'Watu wote walikuwa wanakwenda Hekaluni asubuhi na mapema, wapate kumsikiliza.'),
(2016535,69,42,22,1,'Sikukuu ya Mikate Isiyotiwa chachu, iitwayo Pasaka, ilikuwa inakaribia.'),
(2016536,69,42,22,2,'Makuhani wakuu na walimu wa Sheria wakawa wanatafuta njia ya kumwua Yesu, lakini waliwaogopa watu.'),
(2016537,69,42,22,3,'Basi, Shetani akamwingia Yuda aitwae Iskarioti, mmoja wa wale mitume kumi na wawili.'),
(2016538,69,42,22,4,'Yuda akaenda akajadiliana na makuhani wakuu na walinzi wa Hekalu kuhusu atakavyomsaliti Yesu kwao.'),
(2016539,69,42,22,5,'Nao wakafurahi na kupatana naye kumlipa fedha.'),
(2016540,69,42,22,6,'Yuda akakubali, na akawa anatafuta nafasi nzuri ya kumkabidhi kwao bila umati wa watu kujua.'),
(2016541,69,42,22,7,'Basi, siku ya Mikate Isiyotiwa chachu ikafika. Hiyo ndiyo siku ambayo mwana kondoo wa Pasaka huchinjwa.'),
(2016542,69,42,22,8,'Hivyo Yesu akawatuma Petro na Yohane, akawaambia, "Nendeni mkatuandalie karamu ili tupate kula Pasaka."'),
(2016543,69,42,22,9,'Nao wakamwuliza, "Unataka tuiandae wapi?"'),
(2016544,69,42,22,10,'Akawaambia, "Sikilizeni! Mtakapokuwa mnakwenda mjini, mtakutana na mwanamume anayebeba mtungi wa maji. Mfuateni mpaka ndani ya nyumba atakayoingia.'),
(2016545,69,42,22,11,'Mwambieni mwenye nyumba: `Mwalimu anakuuliza, kiko wapi kile chumba ambamo nitakula Pasaka pamoja na wanafunzi wangu?`'),
(2016546,69,42,22,12,'Naye atawaonyesheni chumba kikubwa ghorofani ambacho kimepambwa. Andalieni humo."'),
(2016547,69,42,22,13,'Basi, wakaenda, wakakuta kila kitu sawa kama Yesu alivyokuwa amewaambia; wakaandaa karamu ya Pasaka.'),
(2016548,69,42,22,14,'Saa ilipotimia, Yesu akakaa kula chakula pamoja na mitume wake.'),
(2016549,69,42,22,15,'Akawaambia, "Nimetamani sana kula Pasaka hii pamoja nanyi kabla ya kuteswa kwangu.'),
(2016550,69,42,22,16,'Maana nawaambieni, sitaila tena hadi hapo itakapokamilika katika Ufalme wa Mungu."'),
(2016551,69,42,22,17,'Kisha akatwaa kikombe, akashukuru akasema, "Pokeeni, mgawanye ninyi kwa ninyi.'),
(2016552,69,42,22,18,'Kwa maana nawaambieni, sitakunywa tena divai ya zabibu mpaka Ufalme wa Mungu utakapokuja."'),
(2016553,69,42,22,19,'Halafu akatwaa mkate, akashukuru, akaumega, akawapa akisema, "Huu ni mwili wangu, unaotolewa kwa ajili yenu. Fanyeni hivi kwa kunikumbuka."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016554,69,42,22,20,'Akafanya vivyo hivyo na kikombe, baada ya chakula, akisema, "Kikombe hiki ni agano jipya linalothibitishwa kwa damu yangu inayomwagika kwa ajili yenu.*fd*'),
(2016555,69,42,22,21,'"Lakini, tazameni! Yule atakayenisaliti yuko nami hapa mezani.'),
(2016556,69,42,22,22,'Kweli Mwana wa Mtu anakwenda kuuawa kama ilivyopangwa, lakini ole wake mtu anayemsaliti."'),
(2016557,69,42,22,23,'Hapo wakaanza kuulizana wao kwa wao ni nani kati yao atakayefanya jambo hilo.'),
(2016558,69,42,22,24,'Kulitokea ubishi kati ya hao mitume kuhusu nani miongoni mwao anayefikiriwa kuwa mkuu zaidi kuliko wengine.'),
(2016559,69,42,22,25,'Yesu akawaambia, "Wafalme wa mataifa huwatawala watu wao kwa mabavu, nao huitwa wafadhili wa watu.'),
(2016560,69,42,22,26,'Lakini isiwe hivyo kati yenu; bali, yule aliye mkuu kati yenu ni lazima awe mdogo wa wote, na aliye kiongozi lazima awe kama mtumishi.'),
(2016561,69,42,22,27,'Kwa maana, ni nani aliye mkuu: yule anayeketi mezani kula chakula, ama yule anayetumikia? Bila shaka ni yule anayeketi mezani kula chakula! Hata hivyo, mimi niko hapa kati yenu kama mtumishi.'),
(2016562,69,42,22,28,'"Ninyi ndio mliobaki nami wakati wote wa majaribu yangu;'),
(2016563,69,42,22,29,'na, kama vile Baba yangu alivyonikabidhi Ufalme, vivyo hivyo nami nitawakabidhi ninyi Ufalme.'),
(2016564,69,42,22,30,'Mtakula na kunywa mezani pangu katika ufalme wangu, na mtaketi katika viti vya enzi kuyahukumu makabila kumi na mawili ya Israeli.'),
(2016565,69,42,22,31,'"Simoni, Simoni! Sikiliza! Shetani alitaka kuwapepeta ninyi kama mtu anavyopepeta ngano.'),
(2016566,69,42,22,32,'Lakini mimi nimekuombea ili imani yako isipungue. Nawe utakaponirudia, watie moyo ndugu zako."'),
(2016567,69,42,22,33,'Naye Petro akamjibu, "Bwana, mimi niko tayari kwenda pamoja nawe gerezani, na hata kufa."'),
(2016568,69,42,22,34,'Yesu akamjibu, "Nakwambia wewe Petro, kabla jogoo hajawika leo utakuwa umenikana mara tatu."'),
(2016569,69,42,22,35,'Kisha, Yesu akawauliza wanafunzi wake, "Wakati nilipowatuma bila mfuko wa fedha wala mkoba wala viatu, mlitindikiwa chochote?" Wakajibu, "La."'),
(2016570,69,42,22,36,'Naye akawaambia, "Lakini sasa, yule aliye na mfuko wa fedha auchukue; na aliye na mkoba, hali kadhalika. Na yeyote asiye na upanga, auze koti lake anunue mmoja.'),
(2016571,69,42,22,37,'Maana nawaambieni, haya maneno ya Maandiko Matakatifu: `Aliwekwa kundi moja na wahalifu,` ni lazima yatimie. Naam, yale yanayonihusu yanafikia ukamilifu wake."'),
(2016572,69,42,22,38,'Nao wakasema, "Bwana, tazama; hapa kuna panga mbili." Naye akasema, "Basi!"'),
(2016573,69,42,22,39,'Yesu akatoka, na kama ilivyokuwa desturi yake, akaenda katika mlima wa Mizeituni; wanafunzi wake wakamfuata.'),
(2016574,69,42,22,40,'Alipofika huko akawaambia, "Salini, msije mkaingia katika kishawishi."'),
(2016575,69,42,22,41,'Kisha akawaacha, akaenda umbali wa mtu kuweza kutupa jiwe, akapiga magoti, akasali:'),
(2016576,69,42,22,42,'"Baba, kama wapenda, ukiondoe kwangu kikombe hiki; hata hivyo, mapenzi yako yatimizwe, wala siyo yangu."'),
(2016577,69,42,22,43,'Hapo, malaika kutoka mbinguni, akamtokea ili kumtia moyo.'),
(2016578,69,42,22,44,'Akiwa katika uchungu mkubwa, alisali kwa bidii zaidi; na jasho likamtoka, kama matone ya damu, likatiririka mpaka chini.*fe* ic'),
(2016579,69,42,22,45,'Baada ya kusali, aliwarudia wanafunzi wake, akawakuta wamelala, kwani walikuwa na huzuni.'),
(2016580,69,42,22,46,'Akawaambia, "Mbona mnalala? Amkeni msali, msije mkaingia katika kishawishi."'),
(2016581,69,42,22,47,'Alipokuwa bado anaongea, kundi la watu likaja likiongozwa na yule aliyeitwa Yuda, mmoja wa wale mitume kumi na wawili. Yuda akaenda kumsalimu Yesu kwa kumbusu.'),
(2016582,69,42,22,48,'Lakini Yesu akamwambia, "Yuda! Je, unamsaliti Mwana wa Mtu kwa kumbusu?"'),
(2016583,69,42,22,49,'Wale wanafunzi wake walipoona hayo wakasema, "Bwana, tutumie panga zetu?"'),
(2016584,69,42,22,50,'Na mmoja wao akampiga upanga mtumishi wa Kuhani Mkuu, akamkata sikio lake la kulia.'),
(2016585,69,42,22,51,'Hapo, Yesu akasema, "Acha! Hii inatosha." Akaligusa sikio la mtu huyo akaliponya.'),
(2016586,69,42,22,52,'Kisha Yesu akawaambia makuhani wakuu, wakubwa wa walinzi wa Hekalu na wazee waliokuja kumkamata: "Je, mmekuja na mapanga na marungu kunikamata kana kwamba mimi ni mnyang`anyi?'),
(2016587,69,42,22,53,'Nilipokuwa pamoja nanyi kila siku Hekaluni hamkunitia nguvuni. Lakini, huu ndio wakati wenu hasa, ndio wakati wa utawala wa giza."'),
(2016588,69,42,22,54,'Basi, wakamkamata, wakamchukua na kwenda naye nyumbani kwa Kuhani Mkuu. Petro akawa anamfuata nyuma kwa mbali.'),
(2016589,69,42,22,55,'Moto ulikuwa umewashwa katikati ya ua, nao wakawa wameketi pamoja Petro akiwa miongoni mwao.'),
(2016590,69,42,22,56,'Mjakazi mmoja alipomwona Petro ameketi karibu na moto, akamkodolea macho, akasema, "Mtu huyu alikuwa pia pamoja na Yesu."'),
(2016591,69,42,22,57,'Lakini Petro akakana akisema, "Wee! simjui mimi."'),
(2016592,69,42,22,58,'Baadaye kidogo, mtu mwingine akamwona Petro, akasema, "Wewe ni mmoja wao." Lakini Petro akajibu "Bwana we; si mimi!"'),
(2016593,69,42,22,59,'Kama saa moja baadaye, mtu mwingine akasisitiza, "Hakika huyu alikuwa pamoja naye; ametoka Galilaya ati."'),
(2016594,69,42,22,60,'Lakini Petro akasema, "Bwana wee; sijui hata unachosema!" Na papo hapo, akiwa bado anaongea, jogoo akawika.'),
(2016595,69,42,22,61,'Bwana akageuka na kumtazama Petro, naye Petro akakumbuka yale aliyokuwa ameambiwa na Bwana: "Leo kabla jogoo hajawika, utanikana mara tatu."'),
(2016596,69,42,22,62,'Hapo akatoka nje, akalia sana.'),
(2016597,69,42,22,63,'Wale watu waliokuwa wanamchunga Yesu, walimpiga na kumdhihaki.'),
(2016598,69,42,22,64,'Walimfunga kitambaa usoni, wakawa wanamwuliza, "Ni nani aliyekupiga? Hebu bashiri tuone!"'),
(2016599,69,42,22,65,'Wakamtolea maneno mengi ya matusi.'),
(2016600,69,42,22,66,'Kulipokucha, kikao cha wazee wa watu kilifanyika, ambacho kilihudhuriwa na makuhani wakuu na walimu wa Sheria. Yesu akaletwa mbele ya Baraza hilo.'),
(2016601,69,42,22,67,'Nao wakamwambia, "Twambie! Je, wewe ndiwe Kristo?" Lakini Yesu akawaambia, "Hata kama nikiwaambieni, hamtasadiki;'),
(2016602,69,42,22,68,'na hata kama nikiwaulizeni swali, hamtanijibu.'),
(2016603,69,42,22,69,'Lakini tangu sasa, Mwana wa Mtu atakuwa ameketi upande wa kulia wa Mungu Mwenyezi."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016604,69,42,22,70,'Hapo wote wakasema, "Ndiyo kusema wewe ni Mwana wa Mungu?" Naye akasema, "Ninyi mnasema kwamba mimi ndiye."'),
(2016605,69,42,22,71,'Nao wakasema, "Je, tunahitaji ushahidi mwingine? Sisi wenyewe tumesikia akisema kwa mdomo wake mwenyewe."sw4323'),
(2016606,69,42,23,1,'Kisha, wote kwa jumla, wakasimama, wakampeleka Yesu mbele ya Pilato.'),
(2016607,69,42,23,2,'Wakaanza kumshtaki wakisema: "Tulimkuta mtu huyu akiwapotosha watu wetu, akipinga kulipa kodi kwa Kaisari na kujiita ati yeye ni Kristo, Mfalme."'),
(2016608,69,42,23,3,'Pilato akamwuliza Yesu, "Wewe ni Mfalme wa Wayahudi?" Yesu akamjibu, "Wewe umesema."'),
(2016609,69,42,23,4,'Pilato akawaambia makuhani wakuu na umati wa watu, "Sioni kosa lolote katika mtu huyu."'),
(2016610,69,42,23,5,'Lakini wao wakasisitiza wakisema: "Anawachochea watu kwa mafundisho yake katika nchi yote ya Yudea; alianza Galilaya, na sasa yuko hapa."'),
(2016611,69,42,23,6,'Pilato aliposikia hayo, akauliza, "Je, mtu huyu ni mwenyeji wa Galilaya?"'),
(2016612,69,42,23,7,'Alipojua kwamba Yesu alikuwa chini ya utawala wa Herode, akampeleka kwa Herode, ambaye wakati huo alikuwa Yerusalemu.'),
(2016613,69,42,23,8,'Herode alifurahi sana alipomwona Yesu. Alikuwa amekwisha sikia habari zake, na hivyo alikuwa anatazamia kwa muda mrefu kumwona kwa macho yake mwenyewe. Zaidi ya hayo, alikuwa anatumaini kumwona Yesu akitenda mwujiza.'),
(2016614,69,42,23,9,'Basi, akamwuliza maswali mengi kwa muda mrefu, lakini Yesu hakumjibu neno.'),
(2016615,69,42,23,10,'Makuhani wakuu na walimu wa Sheria wakajitokeza mbele, wakatoa mashtaka yao kwa nguvu sana.'),
(2016616,69,42,23,11,'Basi, herode pamoja na maaskari wake, wakamwaibisha Yesu na kumfanyia mzaha; kisha wakamvika vazi la kifalme, wakamrudisha kwa Pilato.'),
(2016617,69,42,23,12,'Herode na Pilato, ambao hapo awali walikuwa maadui, tangu siku hiyo wakawa marafiki.'),
(2016618,69,42,23,13,'Basi, Pilato akaitisha mkutano wa makuhani wakuu, viongozi na watu,'),
(2016619,69,42,23,14,'akawaambia, "Mmemleta mtu huyu kwangu mkisema kwamba alikuwa anawapotosha watu. Sasa sikilizeni! Baada ya kuchunguza jambo hilo mbele yenu, sikumpata na kosa lolote kuhusu mashtaka yenu juu yake.'),
(2016620,69,42,23,15,'Wala si mimi tu, bali hata Herode hakuona kosa lolote, kwa maana amemrudisha kwangu. Ni dhahiri kwamba mtu huyu hakufanya chochote kinachostahili adhabu ya kifo.'),
(2016621,69,42,23,16,'Hivyo, nitaamuru apigwe viboko, halafu nitamwachilia."*ff* mmoja.'),
(2016622,69,42,23,17,'missing'),
(2016623,69,42,23,18,'Lakini wote wakapiga kelele pamoja: "Mwondoe huyo, utufungulie Baraba!"'),
(2016624,69,42,23,19,'Baraba alikuwa ametiwa ndani kwa kusababisha uasi katika mji na pia kwa sababu ya kuua.)'),
(2016625,69,42,23,20,'Pilato alitaka kumwachilia Yesu, hivyo akasema nao tena;'),
(2016626,69,42,23,21,'lakini wao wakapiga kelele: "Msulubishe, msulubishe!"'),
(2016627,69,42,23,22,'Pilato akawaambia mara ya tatu, "Amefanya kosa gani? Sioni kosa lolote kwake linalomstahili auawe; kwa hiyo nitampiga viboko, halafu nimwachilie."'),
(2016628,69,42,23,23,'Lakini wao wakazidi kupiga kelele kwa nguvu sana, kwamba Yesu ni lazima asulubiwe. Mwishowe, sauti zao zikashinda.'),
(2016629,69,42,23,24,'Basi, Pilato akaamua kwamba matakwa yao yatimizwe.'),
(2016630,69,42,23,25,'Akamfungua kutoka gerezani yule waliyemtaka, ambaye alikuwa ametiwa gerezani kwa sababu ya uasi na kuua; akamtoa Yesu kwao, wamfanyie walivyotaka.'),
(2016631,69,42,23,26,'Walipokuwa wakimpeleka, walikutana na mtu mmoja, aitwaye Simoni wa Kurene, aliyekuwa anatoka shambani. Basi, walimkamata, wakamtwika ule msalaba auchukue nyuma ya Yesu.'),
(2016632,69,42,23,27,'Watu, umati kwa umati, walimfuata; miongoni mwao wakiwemo wanawake waliokuwa wanaomboleza na kumlilia.'),
(2016633,69,42,23,28,'Yesu akawageukia, akasema, "Enyi kina mama wa Yerusalemu! Msinililie mimi, ila lieni kwa ajili yenu wenyewe na kwa ajili ya watoto wenu.'),
(2016634,69,42,23,29,'Maana, hakika siku zitakuja ambapo watasema: `Heri yao wale walio tasa, ambao hawakupata kuzaa wala kunyonyesha watoto!`'),
(2016635,69,42,23,30,'Wakati huo, ndipo watu wataanza kuiambia milima: `Tuangukieni!` na vilima, `Tufunikeni!`'),
(2016636,69,42,23,31,'Kwa maana, kama watu wanautendea mti mbichi namna hiyo, itakuwaje kwa mti mkavu?"'),
(2016637,69,42,23,32,'Waliwachukua pia watu wengine wawili, wahalifu, wauawe pamoja naye.'),
(2016638,69,42,23,33,'Walipofika mahali paitwapo, "Fuvu la Kichwa," ndipo wakamsulubisha Yesu pamoja na wale wahalifu wawili, mmoja upande wake wa kulia na mwingine upande wake wa kushoto.'),
(2016639,69,42,23,34,'Yesu akasema, "Baba, uwasamehe kwa maana hawajui wanalofanya." Kisha wakagawana mavazi yake kwa kuyapigia kura.'),
(2016640,69,42,23,35,'Watu wakawa wamesimama pale wakitazama. Nao viongozi wakamdhihaki wakisema: "Amewaokoa wengine; sasa na ajiokoe mwenyewe, kama yeye ndiye Kristo, mteule wa Mungu!"'),
(2016641,69,42,23,36,'Askari nao walimdhihaki pia; walimwendea wakampa siki'),
(2016642,69,42,23,37,'wakisema: "Kama kweli wewe ni Mfalme wa Wayahudi, jiokoe mwenyewe."'),
(2016643,69,42,23,38,'Vilevile maandishi haya yalikuwa yameandikwa na kuwekwa juu yake: "Huyu ndiye Mfalme wa Wayahudi."'),
(2016644,69,42,23,39,'Mmoja wa wale wahalifu waliotundikwa msalabani, alimtukana akisema: "Je, si kweli kwamba wewe ndiwe Kristo? Basi, jiokoe mwenyewe, utuokoe na sisi pia."'),
(2016645,69,42,23,40,'Lakini yule mhalifu mwingine akamkemea mwenzake akisema: "Wewe humwogopi Mungu hata kidogo? Wewe umepata adhabu hiyohiyo.'),
(2016646,69,42,23,41,'Wewe na mimi tunastahili, maana haya ni malipo ya yale tuliyotenda. Lakini mtu huyu hakufanya chochote kibaya."'),
(2016647,69,42,23,42,'Kisha akasema, "Ee Yesu! Unikumbuke wakati utakapoingia katika ufalme wako."'),
(2016648,69,42,23,43,'Yesu akamwambia, "Nakwambia kwa hakika, leo utakuwa pamoja nami peponi."'),
(2016649,69,42,23,44,'Ilikuwa yapata saa sita mchana; jua likaacha kuangaza, giza likafunika nchi yote mpaka saa tisa,'),
(2016650,69,42,23,45,'na pazia lililokuwa limetundikwa Hekaluni likapasuka vipande viwili.'),
(2016651,69,42,23,46,'Yesu akalia kwa sauti kubwa: "Baba, naiweka roho yangu mikononi mwako." Alipokwisha sema hayo, akakata roho. ic'),
(2016652,69,42,23,47,'Hapo, yule jemadari alipoona yaliyotukia akamsifu Mungu akisema: "Hakika huyu alikuwa mtu mwema."'),
(2016653,69,42,23,48,'Watu wale wote waliokuwa wamekusanyika hapo kwa ajili ya tukio hilo, walipoona hayo yaliyotukia, walirudi makwao wakijipiga vifua kwa huzuni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016654,69,42,23,49,'Marafiki zake wote pamoja na wale wanawake walioandamana naye kutoka Galilaya, walisimama kwa mbali kutazama tukio hilo.'),
(2016655,69,42,23,50,'Kulikuwa na mtu mmoja jina lake Yosefu, mwenyeji wa kijiji kimoja cha Wayahudi kiitwacho Armathaya. Alikuwa mtu mwema anayeheshimika;'),
(2016656,69,42,23,51,'Alikuwa akitazamia kuja kwa Ufalme wa Mungu. Ingawa alikuwa mmoja wa Baraza kuu la Wayahudi, hakuwa amekubaliana nao katika kitendo chao.'),
(2016657,69,42,23,52,'Basi, yeye alikwenda kwa Pilato, akaomba apewe mwili wa Yesu.'),
(2016658,69,42,23,53,'Kisha, akaushusha mwili huo kutoka msalabani, akauzungushia sanda ya kitani, akauweka katika kaburi lililokuwa limechongwa kwenye mwamba, ambalo halikuwa limetumika.'),
(2016659,69,42,23,54,'Siku hiyo ilikuwa Ijumaa, na maandalio ya siku ya Sabato yalikuwa yanaanza.'),
(2016660,69,42,23,55,'Wale wanawake walioandamana na Yesu kutoka Galilaya walimfuata Yosefu, wakaliona lile kaburi na jinsi mwili wake Yesu ulivyowekwa'),
(2016661,69,42,23,56,'Halafu, walirudi nyumbani, wakatayarisha manukato na marashi kuyapaka mwili wa Yesu. Siku ya Sabato walipumzika kama ilivyoamriwa na sheria.'),
(2016662,69,42,24,1,'Jumapili, alfajiri na mapema, wale wanawake walikwenda kaburini wakichukua yale manukato waliyotayarisha.'),
(2016663,69,42,24,2,'Walikuta lile jiwe limeviringishwa mbali na kaburi.'),
(2016664,69,42,24,3,'Walipoingia ndani, hawakuona mwili wa Bwana Yesu.'),
(2016665,69,42,24,4,'Walipokuwa bado wanashangaa juu ya jambo hilo, mara watu wawili waliovaa mavazi yenye kung`aa sana, wakasimama karibu nao.'),
(2016666,69,42,24,5,'Hao wanawake wakaingiwa na hofu, wakainama chini. Ndipo wale watu wakawaambia, "Kwa nini mnamtafuta aliye hai kati ya wafu?'),
(2016667,69,42,24,6,'Hayuko hapa; amefufuka. Kumbukeni aliyowaambieni alipokuwa kule Galilaya:'),
(2016668,69,42,24,7,'`Ni lazima Mwana wa Mtu atolewe kwa watu waovu, nao watamsulubisha, na siku ya tatu atafufuka."`'),
(2016669,69,42,24,8,'Hapo wanawake wakayakumbuka maneno yake,'),
(2016670,69,42,24,9,'wakarudi kutoka kaburini, wakawapa mitume wale kumi na mmoja na wengine habari za mambo hayo yote.'),
(2016671,69,42,24,10,'Hao waliotoa habari hizo kwa mitume ni: Maria Magdalene, Yoana na Maria mama wa Yakobo, pamoja na wanawake wengine walioandamana nao.'),
(2016672,69,42,24,11,'Mitume waliyachukua maneno hayo kama yasiyo na msingi, hivyo hawakuamini.'),
(2016673,69,42,24,12,'Lakini Petro alitoka, akaenda mbio hadi kaburini. Alipoinama kuchungulia ndani, akaiona tu ile sanda. Akarudi nyumbani huku akiwa anashangaa juu ya hayo yaliyotokea.'),
(2016674,69,42,24,13,'Siku hiyohiyo, wawili kati ya wafuasi wake Yesu wakawa wanakwenda katika kijiji kimoja kiitwacho Emau, umbali wa kilomita kumi na moja kutoka Yerusalemu.'),
(2016675,69,42,24,14,'Wakawa wanazungumza juu ya hayo yote yaliyotukia.'),
(2016676,69,42,24,15,'Walipokuwa wakizungumza na kujadiliana, Yesu mwenyewe akatokea, akatembea pamoja nao.'),
(2016677,69,42,24,16,'Walimwona kwa macho, lakini hawakumtambua.'),
(2016678,69,42,24,17,'Akawauliza, "Mnazungumza nini huku mnatembea?" Nao wakasimama kimya, nyuso zao wamezikunja kwa huzuni.'),
(2016679,69,42,24,18,'Mmoja, aitwaye Kleopa, akamjibu, "Je, wewe ni mgeni peke yako Yerusalemu ambaye hujui yaliyotukia huko siku hizi?"'),
(2016680,69,42,24,19,'Naye akawajibu, "Mambo gani?" Wao wakamjibu, "Mambo yaliyompata Yesu wa Nazareti. Yeye alikuwa nabii mwenye uwezo wa kutenda na kufundisha mbele ya Mungu na mbele ya watu wote.'),
(2016681,69,42,24,20,'Makuhani na watawala wetu walimtoa ahukumiwe kufa, wakamsulubisha.'),
(2016682,69,42,24,21,'Lakini sisi tulitumaini kwamba yeye ndiye angeikomboa Israeli. Zaidi ya hayo yote, leo ni siku ya tatu tangu mambo hayo yalipotendeka.'),
(2016683,69,42,24,22,'Tena, wanawake wengine wa kwetu wametushtua. Walikwenda kaburini mapema asubuhi,'),
(2016684,69,42,24,23,'wasiukute mwili wake. Wakarudi wakasema kwamba walitokewa na malaika waliowaambia kwamba alikuwa hai.'),
(2016685,69,42,24,24,'Wengine wetu walikwenda kaburini wakashuhudia yale waliyosema hao wanawake; ila yeye hawakumwona."'),
(2016686,69,42,24,25,'Kisha Yesu akawaambia, "Mbona mu wapumbavu kiasi hicho na mioyo yenu ni mizito hivyo kusadiki yote yaliyonenwa na manabii?'),
(2016687,69,42,24,26,'Je, haikumpasa Kristo kuteswa, na hivyo aingie katika utukufu wake?"'),
(2016688,69,42,24,27,'Akawafafanulia mambo yote yaliyomhusu yeye katika Maandiko Matakatifu kuanzia Mose hadi manabii wote.'),
(2016689,69,42,24,28,'Walipokikaribia kile kijiji walikokuwa wanakwenda, Yesu akafanya kana kwamba anaendelea na safari;'),
(2016690,69,42,24,29,'lakini wao wakamsihi wakisema, "Kaa pamoja nasi, maana kunakuchwa, na usiku unakaribia." Basi, akaingia kijijini, akakaa pamoja nao.'),
(2016691,69,42,24,30,'Alipoketi kula chakula pamoja nao, akachukua mkate, akaubariki, akaumega, akawapa.'),
(2016692,69,42,24,31,'Mara macho yao yakafumbuliwa, wakamtambua; lakini yeye akatoweka kati yao.'),
(2016693,69,42,24,32,'Basi, wakaambiana, "Je, mioyo yetu haikuwa inawaka ndani yetu wakati alipokuwa anatufafanulia Maandiko Matakatifu kule njiani?"'),
(2016694,69,42,24,33,'Wakaondoka saa ileile, wakarudi Yerusalemu: wakawakuta wale mitume kumi na mmoja na wale wengine waliokuwa pamoja nao, wamekusanyika'),
(2016695,69,42,24,34,'wakisema, "Hakika Bwana amefufuka, amemtokea Simoni."'),
(2016696,69,42,24,35,'Basi, hao wafuasi wawili wakawajulisha yale yaliyowapata njiani, na jinsi walivyomtambua katika kumega mkate.'),
(2016697,69,42,24,36,'Wanafunzi wote wawili walipokuwa wakiwaambia hayo, Yesu mwenyewe akasimama kati yao, akawaambia "Amani kwenu."'),
(2016698,69,42,24,37,'Wakashtuka na kushikwa na hofu wakidhani wameona mzimu.'),
(2016699,69,42,24,38,'Lakini yeye akawaambia, "Kwa nini mnafadhaika? Mbona mnakuwa na mashaka mioyoni mwenu?'),
(2016700,69,42,24,39,'Angalieni mikono na miguu yangu, ya kwamba ni mimi mwenyewe. Nipapaseni mkanione, maana mzimu hauna mwili na mifupa kama mnionavyo."'),
(2016701,69,42,24,40,'Baada ya kusema hayo, akawaonyesha mikono na miguu.'),
(2016702,69,42,24,41,'Wakiwa bado katika hali ya kutosadiki kwa sababu ya furaha yao, na wakiwa wanastaajabu, akawauliza, "Mnacho chakula chochote hapa?"'),
(2016703,69,42,24,42,'Wakampa kipande cha samaki wa kuokwa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016704,69,42,24,43,'Akakichukua, akala, wote wakimwona.'),
(2016705,69,42,24,44,'Halafu akawaambia, "Hii ndiyo maana ya maneno niliyowaambia nilipokuwa pamoja nanyi: kwamba ilikuwa lazima kukamilisha yote yaliyoandikwa juu yangu katika Sheria ya Mose na katika vitabu vya manabii na katika kitabu cha Zaburi."'),
(2016706,69,42,24,45,'Kisha, akaziangazia akili zao ili wapate kuelewa Maandiko Matakatifu.'),
(2016707,69,42,24,46,'Akawaambia, "Ndivyo ilivyoandikwa, kwamba Kristo atateswa na siku ya tatu atafufuka kutoka wafu,'),
(2016708,69,42,24,47,'na kwamba ni lazima, kwa jina lake, mataifa yote kuanzia na Yerusalemu yahubiriwe juu ya kutubu na kusamehewa dhambi.'),
(2016709,69,42,24,48,'Ninyi ni mashahidi wa mambo hayo.'),
(2016710,69,42,24,49,'Nami mwenyewe nitawapelekeeni yule ambaye Baba aliahidi kumtuma, lakini ngojeni huku mjini mpaka mtakapopewa ile nguvu itokayo juu."'),
(2016711,69,42,24,50,'Kisha akawaongoza nje ya mji hadi Bethania, akainua mikono yake juu, akawabariki.'),
(2016712,69,42,24,51,'Alipokuwa anawabariki, akawaacha; akachukuliwa mbinguni.'),
(2016713,69,42,24,52,'Wao wakamwabudu, wakarudi Yerusalemu wakiwa na furaha kubwa:'),
(2016714,69,42,24,53,'wakakaa muda wote Hekaluni wakimsifu Mungu.'),
(2016715,69,43,1,1,'Hapo Mwanzo, Neno alikuwako; naye alikuwa na Mungu, naye alikuwa Mungu.'),
(2016716,69,43,1,2,'Tangu mwanzo Neno alikuwa na Mungu.'),
(2016717,69,43,1,3,'Kwa njia yake vitu vyote viliumbwa; hakuna hata kiumbe kimoja kilichoumbwa pasipo yeye.'),
(2016718,69,43,1,4,'Yeye alikuwa chanzo cha uhai na uhai huo ulikuwa mwanga wa watu.'),
(2016719,69,43,1,5,'Na mwanga huo huangaza gizani, nalo giza halikuweza kuushinda.'),
(2016720,69,43,1,6,'Mungu alimtuma mtu mmoja jina lake Yohane,'),
(2016721,69,43,1,7,'ambaye alikuja kuwaambia watu juu ya huo mwanga. Alikuja ili kwa ujumbe wake watu wote wapate kuamini.'),
(2016722,69,43,1,8,'Yeye hakuwa huo mwanga, ila alikuja tu kuwaambia watu juu ya huo mwanga.'),
(2016723,69,43,1,9,'Huu ndio mwanga halisi, mwanga unaokuja ulimwenguni, na kuwaangazia watu wote.'),
(2016724,69,43,1,10,'Basi, Neno alikuwako ulimwenguni; na kwa njia yake ulimwengu uliumbwa, lakini ulimwengu haukumtambua.'),
(2016725,69,43,1,11,'Alikuja katika nchi yake mwenyewe, nao walio wake hawakumpokea.'),
(2016726,69,43,1,12,'Lakini wale wote waliompokea na kumwamini, hao aliwapa uwezo wa kuwa watoto wa Mungu.'),
(2016727,69,43,1,13,'Hawa wamekuwa watoto wa Mungu si kwa uwezo wa kibinadamu, wala kwa nguvu za kimwili, wala kwa mapenzi ya mtu, bali Mungu mwenyewe ndiye baba yao.'),
(2016728,69,43,1,14,'Naye Neno akawa mwanadamu, akakaa kwetu. Nasi tumeuona utukufu wake, utukufu wake yeye aliye Mwana wa pekee wa Baba; amejaa neema na ukweli.'),
(2016729,69,43,1,15,'Yohane aliwaambia watu habari zake, akasema kwa sauti, "Huyu ndiye niliyemtaja wakati niliposema: `Anakuja mtu mmoja baada yangu ambaye ni mkuu kuliko mimi, maana alikuwako kabla mimi sijazaliwa."`'),
(2016730,69,43,1,16,'Kutokana na ukamilifu wake sisi tumepokea neema mfululizo.'),
(2016731,69,43,1,17,'Maana Mungu alitoa Sheria kwa njia ya Mose, lakini neema na kweli vimekuja kwa njia ya Kristo.'),
(2016732,69,43,1,18,'Hakuna mtu aliyemwona Mungu wakati wowote ule. Mwana wa pekee aliye sawa na Mungu ambaye ameungana na Baba, ndiye aliyetujulisha habari za Mungu.'),
(2016733,69,43,1,19,'Huu ndio ushahidi Yohane alioutoa wakati viongozi wa Wayahudi kule Yerusalemu walipowatuma makuhani wa Walawi kwake wamwulize: "Wewe u nani?"'),
(2016734,69,43,1,20,'Yohane hakukataa kujibu swali hilo, bali alisema waziwazi, "Mimi siye Kristo."'),
(2016735,69,43,1,21,'Hapo wakamwuliza, "Basi, wewe ni nani? Je, wewe ni Eliya?" Yohane akajibu, "La, mimi siye." Wakamwuliza, "Je, wewe ni yule nabii?" Yohane akawajibu, "La!"'),
(2016736,69,43,1,22,'Nao wakamwuliza, "Basi, wewe ni nani? Wasema nini juu yako mwenyewe? Tuambie, ili tuwapelekee jibu wale waliotutuma."'),
(2016737,69,43,1,23,'Yohane akawajibu, "Mimi ndiye yule ambaye nabii Isaya alisema habari zake: `Sauti ya mtu imesikika jangwani: Nyoosheni njia ya Bwana."`'),
(2016738,69,43,1,24,'Hao watu walikuwa wametumwa na Mafarisayo.'),
(2016739,69,43,1,25,'Basi, wakamwuliza Yohane, "Kama wewe si Kristo, wala Eliya, wala yule nabii, mbona wabatiza?"'),
(2016740,69,43,1,26,'Yohane akawajibu, "Mimi nabatiza kwa maji, lakini yuko mmoja kati yenu, msiyemjua bado.'),
(2016741,69,43,1,27,'Huyo anakuja baada yangu, lakini mimi sistahili hata kumfungua kamba za viatu vyake."'),
(2016742,69,43,1,28,'Mambo haya yalifanyika huko Bethania, ng`ambo ya mto Yordani ambako Yohane alikuwa anabatiza.'),
(2016743,69,43,1,29,'Kesho yake, Yohane alimwona Yesu akimjia, akasema, "Huyu ndiye Mwana-kondoo wa Mungu aondoaye dhambi ya ulimwengu!'),
(2016744,69,43,1,30,'Huyu ndiye niliyesema juu yake: `Baada yangu anakuja mtu mmoja aliye mkuu zaidi kuliko mimi, maana alikuwako kabla mimi sijazaliwa!`'),
(2016745,69,43,1,31,'Mimi mwenyewe sikumfahamu, lakini nimekuja kubatiza kwa maji ili watu wa Israeli wapate kumjua."'),
(2016746,69,43,1,32,'Huu ndio ushahidi Yohane alioutoa: "Nilimwona Roho akishuka kama njiwa kutoka mbinguni na kutua juu yake.'),
(2016747,69,43,1,33,'Mimi sikumjua, lakini yule aliyenituma nikabatize watu kwa maji alikuwa ameniambia: `Mtu yule utakayemwona Roho akimshukia kutoka mbinguni na kukaa juu yake, huyo ndiye anayebatiza kwa Roho Mtakatifu.`'),
(2016748,69,43,1,34,'Mimi nimeona na ninawaambieni kwamba huyu ndiye Mwana wa Mungu."'),
(2016749,69,43,1,35,'Kesho yake, Yohane alikuwa tena mahali hapo pamoja na wanafunzi wake wawili.'),
(2016750,69,43,1,36,'Alipomwona Yesu akipita akasema, "Tazameni! Huyu ndiye Mwana-kondoo wa Mungu."'),
(2016751,69,43,1,37,'Hao wanafunzi walimsikia Yohane akisema maneno hayo, wakamfuata Yesu.'),
(2016752,69,43,1,38,'Basi, Yesu aligeuka, na alipowaona hao wanafunzi wanamfuata, akawauliza, "Mnatafuta nini?" Nao wakamjibu, "Rabi (yaani Mwalimu), unakaa wapi?"'),
(2016753,69,43,1,39,'Yesu akawaambia, "Njoni, nanyi mtaona." Hao wanafunzi wakamfuata, wakaona mahali alipokuwa anakaa, wakashinda naye siku hiyo. Ilikuwa yapata saa kumi jioni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016754,69,43,1,40,'Andrea, nduguye Simoni Petro, alikuwa mmoja wa hao wawili waliokuwa wamemsikia Yohane akisema hivyo, wakamfuata Yesu.'),
(2016755,69,43,1,41,'Andrea alimkuta kwanza Simoni, ndugu yake, akamwambia, "Tumemwona Masiha" (maana yake Kristo).'),
(2016756,69,43,1,42,'Kisha akampeleka Simoni kwa Yesu. Naye Yesu akamtazama Simoni akasema, "Wewe ni Simoni mwana wa Yohane. Sasa utaitwa Kefa." (maana yake ni Petro, yaani, "Mwamba.")'),
(2016757,69,43,1,43,'Kesho yake Yesu aliamua kwenda Galilaya. Basi, akamkuta Filipo, akamwambia, "Nifuate."'),
(2016758,69,43,1,44,'Filipo alikuwa mwenyeji wa Bethsaida, mji wa akina Andrea na Petro.'),
(2016759,69,43,1,45,'Naye Filipo akamkuta Nathanieli, akamwambia, "Tumemwona yule ambaye Mose aliandika juu yake katika kitabu cha Sheria, na ambaye manabii waliandika habari zake, yaani Yesu Mwana wa Yosefu, kutoka Nazareti."'),
(2016760,69,43,1,46,'Naye Nathanieli akamwuliza Filipo, "Je, kitu chema chaweza kutoka Nazareti?" Filipo akamwambia, "Njoo uone."'),
(2016761,69,43,1,47,'Yesu alipomwona Nathanieli akimjia alisema juu yake, "Tazameni! Huyo ni Mwisraeli halisi: hamna hila ndani yake."'),
(2016762,69,43,1,48,'Naye Nathanieli akamwuliza, "Umepataje kunijua?" Yesu akamwambia, "Ulipokuwa chini ya mtini hata kabla Filipo hajakuita, nilikuona."'),
(2016763,69,43,1,49,'Hapo Nathanieli akamwambia, "Mwalimu, wewe ni Mwana wa Mungu. Wewe ni Mfalme wa Israeli!"'),
(2016764,69,43,1,50,'Yesu akamwambia, "Je, umeamini kwa kuwa nimekwambia kwamba nilikuona chini ya mtini? Utaona makubwa zaidi kuliko haya."'),
(2016765,69,43,1,51,'Yesu akaendelea kusema, "Nawaambieni kweli, mtaona mbingu zinafunguka na malaika wa Mungu wakipanda na kushuka juu ya Mwana wa Mtu."'),
(2016766,69,43,2,1,'Siku ya tatu kulikuwa na arusi mjini Kana, mkoani Galilaya. Mama yake Yesu alikuwapo,'),
(2016767,69,43,2,2,'naye Yesu alikuwa amealikwa arusini pamoja na wanafunzi wake.'),
(2016768,69,43,2,3,'Divai ilipokwisha, mama yake akamwambia, "Hawana divai!"'),
(2016769,69,43,2,4,'Yesu akamjibu, "Mama, usiniambie la kufanya. Saa yangu bado."'),
(2016770,69,43,2,5,'Hapo mama yake akawaambia watumishi, "Lolote atakalowaambieni, fanyeni."'),
(2016771,69,43,2,6,'Hapo palikuwa na mitungi sita ya mawe, ambayo kila mmoja uliweza kuchukua kiasi cha madebe mawili au matatu. Ilikuwa imewekwa hapo kufuatana na desturi ya Kiyahudi ya kutawadha.'),
(2016772,69,43,2,7,'Yesu akawaambia, "Ijazeni mitungi hiyo maji." Nao wakaijaza mpaka juu.'),
(2016773,69,43,2,8,'Kisha akawaambia, "Sasa choteni mkampelekee mkuu wa karamu."'),
(2016774,69,43,2,9,'Mkuu wa karamu alipoonja hayo maji, kumbe yalikuwa yamegeuka kuwa divai. Yeye hakujua ilikotoka, (lakini wale watumishi waliochota maji walijua). Mkuu wa karamu akamwita bwana arusi,'),
(2016775,69,43,2,10,'akamwambia, "Kila mtu huandaa divai nzuri kwanza hata wakisha tosheka huandaa ile hafifu. Lakini wewe umeiweka divai nzuri mpaka sasa!"'),
(2016776,69,43,2,11,'Yesu alifanya ishara hii ya kwanza huko Kana, Galilaya, akaonyesha utukufu wake; nao wanafunzi wake wakamwamini.'),
(2016777,69,43,2,12,'Baada ya hayo, Yesu alishuka pamoja na mama yake, ndugu zake na wanafunzi wake, wakaenda Kafarnaumu ambako walikaa kwa siku chache.'),
(2016778,69,43,2,13,'Sikukuu ya Wayahudi ya Pasaka ilikuwa imekaribia; hivyo Yesu akaenda Yerusalemu.'),
(2016779,69,43,2,14,'Hekaluni aliwakuta watu wakiuza ng`ombe, kondoo na njiwa, na wavunja fedha walikuwa wamekaa kwenye meza zao.'),
(2016780,69,43,2,15,'Akatengeneza mjeledi wa kamba, akawafukuza wote nje ya Hekalu pamoja na kondoo na ng`ombe wao, akazimwaga sarafu za wenye kuvunja fedha na kupindua meza zao.'),
(2016781,69,43,2,16,'Akawaambia wale waliokuwa wanauza njiwa, "Ondoeni vitu hivi hapa. Msiifanye nyumba ya Baba yangu kuwa soko!"'),
(2016782,69,43,2,17,'Wanafunzi wake wakakumbuka kwamba Maandiko yasema: "Upendo wangu kwa nyumba yako waniua."'),
(2016783,69,43,2,18,'Baadhi ya Wayahudi wakamwuliza Yesu, "Utafanya muujiza gani kuonyesha kwamba unayo haki kufanya mambo haya?"'),
(2016784,69,43,2,19,'Yesu akawaambia, "Vunjeni Hekalu hili, nami nitalijenga kwa siku tatu."'),
(2016785,69,43,2,20,'Hapo Wayahudi wakasema, "Hekalu hili lilijengwa kwa muda wa miaka arobaini na sita. Je, wewe utalijenga kwa siku tatu?"'),
(2016786,69,43,2,21,'Lakini Yesu alikuwa anaongea juu ya Hekalu ambalo ni mwili wake.'),
(2016787,69,43,2,22,'Basi, alipofufuliwa kutoka wafu, wanafunzi wake walikumbuka kwamba alikuwa amesema hayo, wakaamini Maandiko Matakatifu na yale maneno aliyokuwa akisema Yesu.'),
(2016788,69,43,2,23,'Yesu alipokuwa Yerusalemu kwa sikukuu ya Pasaka, watu wengi walimwamini walipoona ishara alizozifanya.'),
(2016789,69,43,2,24,'Lakini Yesu hakuwa na imani nao kwa sababu aliwajua wote.'),
(2016790,69,43,2,25,'Hakuhitaji kuambiwa chochote juu ya watu, maana aliyajua barabara mambo yote yaliyomo mioyoni mwao.'),
(2016791,69,43,3,1,'Kulikuwa na kiongozi mmoja Myahudi, wa kikundi cha Mafarisayo, jina lake Nikodemo.'),
(2016792,69,43,3,2,'Siku moja alimwendea Yesu usiku, akamwambia, "Rabi, tunajua kwamba wewe ni mwalimu uliyetumwa na Mungu, maana hakuna mtu awezaye kufanya ishara unazozifanya Mungu asipokuwa pamoja naye."'),
(2016793,69,43,3,3,'Yesu akamwambia, "Kweli nakwambia, mtu asipozaliwa upya hataweza kuuona ufalme wa Mungu."'),
(2016794,69,43,3,4,'Nikodemo akamwuliza, "Mtu mzima awezaje kuzaliwa tena? Hawezi kuingia tumboni mwa mama yake na kuzaliwa mara ya pili!"'),
(2016795,69,43,3,5,'Yesu akamjibu, "Kweli nakwambia, mtu asipozaliwa kwa maji na Roho, hawezi kamwe kuingia katika ufalme wa Mungu.'),
(2016796,69,43,3,6,'Mtu huzaliwa kimwili kwa baba na mama, lakini huzaliwa kiroho kwa Roho.'),
(2016797,69,43,3,7,'Usistaajabu kwamba nimekwambia kuwa ni lazima kuzaliwa upya.'),
(2016798,69,43,3,8,'Upepo huvuma kuelekea upendako; waisikia sauti yake, lakini hujui unakotoka wala unakokwenda. Ndivyo ilivyo kwa mtu aliyezaliwa kwa Roho."'),
(2016799,69,43,3,9,'Nikodemo akamwuliza, "Mambo haya yanawezekanaje?"'),
(2016800,69,43,3,10,'Yesu akamjibu, "Je, wewe ni mwalimu katika Israel na huyajui mambo haya?'),
(2016801,69,43,3,11,'Kweli nakwambia, sisi twasema tunayoyajua na kushuhudia tuliyoyaona, lakini ninyi hamkubali ujumbe wetu.'),
(2016802,69,43,3,12,'Ikiwa nimewaambieni mambo ya kidunia nanyi hamniamini, mtawezaje kuamini nikiwaambieni mambo ya mbinguni?'),
(2016803,69,43,3,13,'Hakuna mtu aliyepata kwenda juu mbinguni isipokuwa Mwana wa Mtu ambaye ameshuka kutoka mbinguni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016804,69,43,3,14,'"Kama vile Mose alivyomwinua juu nyoka wa shaba kule jangwani, naye Mwana wa Mtu atainuliwa juu vivyo hivyo,'),
(2016805,69,43,3,15,'ili kila anayemwamini awe na uzima wa milele.'),
(2016806,69,43,3,16,'Maana Mungu aliupenda ulimwengu hivi hata akamtoa Mwana wake wa pekee, ili kila amwaminiye asipotee, bali awe na uzima wa milele.'),
(2016807,69,43,3,17,'Maana Mungu hakumtuma Mwanae ulimwenguni ili auhukumu ulimwengu, bali aukomboe ulimwengu.'),
(2016808,69,43,3,18,'"Anayemwamini Mwana hahukumiwi; asiyemwamini amekwisha hukumiwa kwa sababu hakumwamini Mwana wa pekee wa Mungu.'),
(2016809,69,43,3,19,'Na hukumu yenyewe ndiyo hii: Mwanga umekuja ulimwenguni lakini watu wakapenda giza kuliko mwanga, kwani matendo yao ni maovu.'),
(2016810,69,43,3,20,'Kila mtu atendaye maovu anauchukia mwanga, wala haji kwenye mwanga, maana hapendi matendo yake maovu yamulikwe.'),
(2016811,69,43,3,21,'Lakini mwenye kuuzingatia ukweli huja kwenye mwanga, ili matendo yake yaonekane yametendwa kwa kumtii Mungu."'),
(2016812,69,43,3,22,'Baada ya hayo, Yesu alifika mkoani Yudea pamoja na wanafunzi wake. Alikaa huko pamoja nao kwa muda, akibatiza watu.'),
(2016813,69,43,3,23,'Yohane pia alikuwa akibatiza watu huko Ainoni, karibu na Salemu, maana huko kulikuwa na maji mengi. Watu walimwendea, naye akawabatiza.'),
(2016814,69,43,3,24,'Wakati huo Yohane alikuwa bado hajafungwa gerezani.)'),
(2016815,69,43,3,25,'Ubishi ulitokea kati ya baadhi ya wanafunzi wa Yohane na Myahudi mmoja kuhusu desturi za kutawadha.'),
(2016816,69,43,3,26,'Basi, wanafunzi hao wakamwendea Yohane na kumwambia, "Mwalimu, yule mtu aliyekuwa pamoja nawe ng`ambo ya Yordani na ambaye wewe ulimshuhudia, sasa naye anabatiza, na watu wote wanamwendea."'),
(2016817,69,43,3,27,'Yohane akawaambia, "Mtu hawezi kuwa na kitu asipopewa na Mungu.'),
(2016818,69,43,3,28,'Nanyi wenyewe mwaweza kushuhudia kuwa nilisema: `Mimi siye Kristo, lakini nimetumwa ili nimtangulie!`'),
(2016819,69,43,3,29,'Bibiarusi ni wake bwanaarusi, lakini rafiki yake bwana arusi, anayesimama na kusikiliza, hufurahi sana anapomsikia bwana arusi akisema. Ndivyo furaha yangu ilivyokamilishwa.'),
(2016820,69,43,3,30,'Ni lazima yeye azidi kuwa maarufu, na mimi nipungue.'),
(2016821,69,43,3,31,'"Anayekuja kutoka juu ni mkuu kuliko wote; atokaye duniani ni wa dunia, na huongea mambo ya kidunia. Lakini anayekuja kutoka mbinguni ni mkuu kuliko wote.'),
(2016822,69,43,3,32,'Yeye husema yale aliyoyaona na kuyasikia, lakini hakuna mtu anayekubali ujumbe wake.'),
(2016823,69,43,3,33,'Lakini mtu yeyote anayekubali ujumbe wake anathibitisha kwamba Mungu ni kweli.'),
(2016824,69,43,3,34,'Yule aliyetumwa na Mungu husema maneno ya Mungu, maana Mungu humjalia mtu huyo Roho wake bila kipimo.'),
(2016825,69,43,3,35,'Baba anampenda Mwana na amemkabidhi vitu vyote.'),
(2016826,69,43,3,36,'Anayemwamini Mwana anao uzima wa milele; asiyemtii Mwana hatakuwa na uzima wa milele, bali ghadhabu ya Mungu hubaki juu yake."'),
(2016827,69,43,4,1,'Mafarisayo walisikia kwamba Yesu alikuwa anabatiza na kuwapata wanafunzi wengi kuliko Yohane.'),
(2016828,69,43,4,2,'Lakini ukweli ni kwamba Yesu hakuwa anabatiza ila wanafunzi wake.)'),
(2016829,69,43,4,3,'Basi, Yesu aliposikia hayo, alitoka Yudea akarudi Galilaya;'),
(2016830,69,43,4,4,'na katika safari hiyo ilimbidi apitie Samaria.'),
(2016831,69,43,4,5,'Basi, akafika Sukari, mji mmoja wa Samaria, karibu na shamba ambalo Yakobo alikuwa amempa mwanawe, Yosefu.'),
(2016832,69,43,4,6,'Mahali hapo palikuwa na kisima cha Yakobo, naye Yesu, kutokana na uchovu wa safari, akaketi kando ya kisima. Ilikuwa yapata saa sita mchana.'),
(2016833,69,43,4,7,'Basi, mwanamke mmoja Msamaria akafika kuteka maji. Yesu akamwambia, "Nipatie maji ninywe."'),
(2016834,69,43,4,8,'(Wakati huo wanafunzi wake walikuwa wamekwenda mjini kununua chakula.)'),
(2016835,69,43,4,9,'Lakini huyo mwanamke akamwambia, "Wewe ni Myahudi; mimi ni mwanamke Msamaria! Unawezaje kuniomba maji?" (Wayahudi hawakuwa na ushirikiano na Wasamaria katika matumizi ya vitu.)'),
(2016836,69,43,4,10,'Yesu akamjibu, "Kama tu ungalijua zawadi ya Mungu na ni nani anayekwambia: `Nipatie maji ninywe,` ungalikwisha mwomba, naye angekupa maji yaliyo hai."'),
(2016837,69,43,4,11,'Huyo mama akasema, "Mheshimiwa, wewe huna chombo cha kutekea maji, nacho kisima ni kirefu; utapata wapi maji yaliyo hai?'),
(2016838,69,43,4,12,'Au, labda wewe wajifanya mkuu kuliko babu yetu Yakobo? Yeye alitupa sisi kisima hiki; na yeye mwenyewe, watoto wake na mifugo yake walikunywa maji ya kisima hiki."'),
(2016839,69,43,4,13,'Yesu akamjibu, "Kila anayekunywa maji haya ataona kiu tena.'),
(2016840,69,43,4,14,'Lakini atakayekunywa maji nitakayompa mimi, hataona kiu milele. Maji nitakayompa yatakuwa ndani yake chemchemi ya maji ya uzima na kumpatia uzima wa milele."'),
(2016841,69,43,4,15,'Huyo mwanamke akamwambia, "Mheshimiwa, nipe maji hayo ili nisione kiu tena; nisije tena mpaka hapa kuteka maji."'),
(2016842,69,43,4,16,'Yesu akamwambia, "Nenda ukamwite mumeo uje naye hapa."'),
(2016843,69,43,4,17,'Huyo mwanamke akamwambia, "Mimi sina mume." Yesu akamwambia, "Umesema kweli, kwamba huna mume.'),
(2016844,69,43,4,18,'Maana umekuwa na waume watano, na huyo unayeishi naye sasa si mume wako. Hapo umesema kweli."'),
(2016845,69,43,4,19,'Huyo Mwanamke akamwambia, "Mheshimiwa, naona ya kuwa wewe u nabii.'),
(2016846,69,43,4,20,'Babu zetu waliabudu juu ya mlima huu, lakini ninyi mwasema kwamba mahali pa kumwabudu Mungu ni kule Yerusalemu."'),
(2016847,69,43,4,21,'Yesu akamwambia, "Niamini; wakati unakuja ambapo hamtamwabudu Baba juu ya mlima huu, wala kule Yerusalemu.'),
(2016848,69,43,4,22,'Ninyi Wasamaria mnamwabudu yule msiyemjua, lakini sisi tunamjua huyo tunayemwabudu, kwa maana wokovu unatoka kwa Wayahudi.'),
(2016849,69,43,4,23,'Lakini wakati unakuja, tena umekwisha fika, ambapo wanaoabudu kweli, watamwabudu Baba kwa nguvu ya Roho; watu wanaomwabudu hivyo ndio Baba anaotaka.'),
(2016850,69,43,4,24,'Mungu ni Roho, na watu wataweza tu kumwabudu kweli kwa nguvu ya Roho wake."'),
(2016851,69,43,4,25,'Huyo mama akamwambia, "Najua kwamba Masiha, aitwaye Kristo, anakuja. Atakapokuja atatujulisha kila kitu."'),
(2016852,69,43,4,26,'Yesu akamwambia, "Mimi ninayesema nawe, ndiye."'),
(2016853,69,43,4,27,'Hapo wanafunzi wake wakarudi, wakastaajabu sana kuona anaongea na mwanamke. Lakini hakuna mtu aliyesema: "Unataka nini?" au, "Kwa nini unaongea na mwanamke?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016854,69,43,4,28,'Huyo mama akauacha mtungi wake pale, akaenda mjini na kuwaambia watu,'),
(2016855,69,43,4,29,'"Njoni mkamwone mtu aliyeniambia mambo yote niliyotenda! Je, yawezekana kuwa yeye ndiye Kristo?"'),
(2016856,69,43,4,30,'Watu wakatoka mjini, wakamwendea Yesu.'),
(2016857,69,43,4,31,'Wakati huohuo wanafunzi wake walikuwa wanamsihi Yesu: "Mwalimu, ule chakula."'),
(2016858,69,43,4,32,'Lakini Yesu akawaambia, "Mimi ninacho chakula msichokijua ninyi."'),
(2016859,69,43,4,33,'Wanafunzi wake wakaulizana, "Je, kuna mtu aliyemletea chakula?"'),
(2016860,69,43,4,34,'Yesu akawaambia, "Chakula changu ni kufanya anachotaka yule aliyenituma na kuitimiza kazi yake.'),
(2016861,69,43,4,35,'Ninyi mwasema: `Bado miezi minne tu, na wakati wa mavuno utafika!` Lakini mimi nawaambieni, yatazameni mashamba; mazao yako tayari kuvunwa.'),
(2016862,69,43,4,36,'Mvunaji anapata mshahara wake, na anakusanya mavuno kwa ajili ya uzima wa milele; hivyo mpandaji na mvunaji watafurahi pamoja.'),
(2016863,69,43,4,37,'Kwa sababu hiyo msemo huu ni kweli: `Mmoja hupanda na mwingine huvuna.`'),
(2016864,69,43,4,38,'Mimi nimewatuma mkavune mavuno ambayo hamkuyatolea jasho, wengine walifanya kazi, lakini ninyi mnafaidika kutokana na jasho lao."'),
(2016865,69,43,4,39,'Wasamaria wengi wa kijiji kile waliamini kwa sababu ya maneno aliyosema huyo mama: "Ameniambia mambo yote niliyofanya."'),
(2016866,69,43,4,40,'Wasamaria walimwendea Yesu wakamwomba akae nao; naye akakaa hapo siku mbili.'),
(2016867,69,43,4,41,'Watu wengi zaidi walimwamini kwa sababu ya ujumbe wake.'),
(2016868,69,43,4,42,'Wakamwambia yule mama, "Sisi hatuamini tu kwa sababu ya maneno yako; sisi wenyewe tumesikia, na tunajua kwamba huyu ndiye kweli Mwokozi wa ulimwengu."'),
(2016869,69,43,4,43,'Baada ya siku mbili Yesu aliondoka hapo, akaenda Galilaya.'),
(2016870,69,43,4,44,'Maana Yesu mwenyewe alisema waziwazi kwamba, "Nabii hapati heshima katika nchi yake."'),
(2016871,69,43,4,45,'Basi, alipofika Galilaya, Wagalilaya wengi walimkaribisha. Maana nao pia walikuwa kwenye sikukuu ya Pasaka, wakayaona mambo yote Yesu aliyotenda huko Yerusalemu wakati wa sikukuu hiyo.'),
(2016872,69,43,4,46,'Yesu alifika tena huko mjini Kana, mkoani Galilaya, mahali alipogeuza maji kuwa divai. Kulikuwa na ofisa mmoja aliyekuwa na mtoto mgonjwa huko Kafarnaumu.'),
(2016873,69,43,4,47,'Basi, huyo ofisa aliposikia kuwa Yesu alikuwa ametoka Yudea na kufika Galilaya, alimwendea akamwomba aende kumponya mtoto wake aliyekuwa mgonjwa mahututi.'),
(2016874,69,43,4,48,'Yesu akamwambia, "Msipoona ishara na maajabu hamtaamini!"'),
(2016875,69,43,4,49,'Huyo ofisa akamwambia, "Mheshimiwa, tafadhali twende kabla mwanangu hajafa."'),
(2016876,69,43,4,50,'Yesu akamwambia, "Nenda tu, mwanao yu mzima." Huyo mtu akaamini maneno ya Yesu, akaenda zake.'),
(2016877,69,43,4,51,'Alipokuwa bado njiani, watumishi wake walikutana naye, wakamwambia kwamba mwanawe alikuwa mzima.'),
(2016878,69,43,4,52,'Naye akawauliza saa mtoto alipopata nafuu; nao wakamwambia, "Jana saa saba mchana, homa ilimwacha."'),
(2016879,69,43,4,53,'Huyo baba akakumbuka kwamba ilikuwa ni saa ileile ambapo Yesu alimwambia: "Mwanao yu mzima." Basi, yeye akaamini pamoja na jamaa yake yote.'),
(2016880,69,43,4,54,'Hii ilikuwa ishara ya pili aliyoifanya Yesu alipokuwa anatoka Yudea kwenda Galilaya.'),
(2016881,69,43,5,1,'Baada ya hayo kulikuwa na sikukuu ya Wayahudi, naye Yesu akaenda Yerusalemu.'),
(2016882,69,43,5,2,'Huko Yerusalemu, karibu na mlango uitwao Mlango wa Kondoo, kulikuwa na bwawa la maji liitwalo kwa Kiebrania Bethzatha, ambalo lilikuwa na baraza tano zenye matao.'),
(2016883,69,43,5,3,'Humo barazani mlikuwa na wagonjwa wengi wamekaa: vipofu, viwete na waliopooza.*fa*'),
(2016884,69,43,5,4,'maana mara kwa mara malaika alishuka majini nyakati fulani na kuyatibua. Mtu yeyote aliyekuwa wa kwanza kuingia majini baada ya maji kutibuliwa, alipona ugonjwa wowote aliokuwa nao.'),
(2016885,69,43,5,5,'Basi, hapo palikuwa na mtu mmoja aliyekuwa mgonjwa kwa muda wa miaka thelathini na minane.'),
(2016886,69,43,5,6,'Naye alipomwona huyo mtu amelala hapo, akatambua kwamba alikuwa amekaa hapo kwa muda mrefu, akamwuliza, "Je, wataka kupona?"'),
(2016887,69,43,5,7,'Naye akajibu, "Mheshimiwa, mimi sina mtu wa kunipeleka majini wakati yanapotibuliwa. Kila nikijaribu kuingia, mtu mwingine hunitangulia."'),
(2016888,69,43,5,8,'Yesu akamwambia, "Inuka, chukua mkeka wako utembee."'),
(2016889,69,43,5,9,'Mara huyo mtu akapona, akachukua mkeka wake, akatembea. Jambo hili lilifanyika siku ya Sabato.'),
(2016890,69,43,5,10,'Kwa hiyo baadhi ya Wayahudi wakamwambia huyo mtu aliyeponywa, "Leo ni Sabato, si halali kubeba mkeka wako."'),
(2016891,69,43,5,11,'Lakini yeye akawaambia, "Yule mtu aliyeniponya ndiye aliyeniambia: `Chukua mkeka wako, tembea."`'),
(2016892,69,43,5,12,'Nao wakamwuliza, "Huyo mtu aliyekwambia: `Chukua mkeka wako, tembea,` ni nani?"'),
(2016893,69,43,5,13,'Lakini yeye hakumjua huyo mtu aliyemponya, maana Yesu alikuwa amekwisha ondoka mahali hapo, kwani palikuwa na umati mkubwa wa watu.'),
(2016894,69,43,5,14,'Basi, baadaye Yesu alimkuta huyo aliyeponywa Hekaluni, akamwambia, "Sasa umepona; usitende dhambi tena, usije ukapatwa na jambo baya zaidi."'),
(2016895,69,43,5,15,'Huyo mtu akaenda, akawaambia viongozi wa Wayahudi kwamba Yesu ndiye aliyemponya.'),
(2016896,69,43,5,16,'Kwa vile Yesu alifanya jambo hilo siku ya Sabato, Wayahudi walianza kumdhulumu.'),
(2016897,69,43,5,17,'Basi, Yesu akawaambia, "Baba yangu anafanya kazi daima, nami pia nafanya kazi."'),
(2016898,69,43,5,18,'Kwa sababu ya maneno haya, viongozi wa Wayahudi walizidi kutafuta njia ya kumwua Yesu: si kwa kuwa aliivunja Sheria ya Sabato tu, bali pia kwa kuwa alisema kwamba Mungu ni Baba yake, na hivyo akajifanya sawa na Mungu.'),
(2016899,69,43,5,19,'Yesu akawaambia, "Kweli nawaambieni, Mwana hawezi kufanya kitu peke yake; anaweza tu kufanya kile anachomwona Baba akikifanya. Maana kile anachofanya Baba, Mwana hukifanya vilevile.'),
(2016900,69,43,5,20,'Baba ampenda Mwana, na humwonyesha kila kitu anachokifanya yeye mwenyewe, tena atamwonyesha mambo makuu kuliko haya, nanyi mtastaajabu.'),
(2016901,69,43,5,21,'Kama vile Baba huwafufua wafu na kuwapa uzima, vivyo hivyo naye Mwana huwapa uzima wale anaopenda.'),
(2016902,69,43,5,22,'Baba hamhukumu mtu yeyote; shughuli yote ya hukumu amemkabidhi Mwana,'),
(2016903,69,43,5,23,'ili watu wote wamheshimu Mwana kama vile wanavyomheshimu Baba. Asiyemheshimu Mwana hamheshimu Baba ambaye amemtuma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016904,69,43,5,24,'"Kweli nawaambieni, anayesikia neno langu, na kumwamini yule aliyenituma, anao uzima wa milele. Hatahukumiwa kamwe, bali amekwisha pita kutoka kifo na kuingia katika uzima.'),
(2016905,69,43,5,25,'Kweli nawaambieni, wakati unakuja, tena umekwisha fika, ambapo wafu wataisikia sauti ya Mwana wa Mungu, nao watakaoisikia, wataishi.'),
(2016906,69,43,5,26,'Kama vile Baba alivyo asili ya uhai, ndivyo pia alivyomjalia Mwanawe kuwa asili ya uhai.'),
(2016907,69,43,5,27,'Tena amempa mamlaka ya kuhukumu kwa sababu yeye ni Mwana wa Mtu.'),
(2016908,69,43,5,28,'Msistaajabie jambo hili; maana wakati unakuja ambapo wote waliomo makaburini wataisikia sauti yake,'),
(2016909,69,43,5,29,'nao watafufuka: wale waliotenda mema watafufuka na kuishi, na wale waliotenda maovu watafufuka na kuhukumiwa.'),
(2016910,69,43,5,30,'"Mimi siwezi kufanya kitu kwa uwezo wangu mwenyewe. Mimi nina hukumu kama ninavyosikia kutoka kwa Baba, nayo hukumu yangu ni ya haki. Nia yangu si kufanya nipendavyo mwenyewe, bali apendavyo yule aliyenituma.'),
(2016911,69,43,5,31,'Nikijishuhudia mimi mwenyewe, ushahidi wangu hauwezi kukubaliwa kuwa wa kweli.'),
(2016912,69,43,5,32,'Lakini yuko mwingine ambaye hutoa ushahidi juu yangu, nami najua kwamba yote anayosema juu yangu ni ya kweli.'),
(2016913,69,43,5,33,'Ninyi mlituma ujumbe kwa Yohane naye aliushuhudia ukweli.'),
(2016914,69,43,5,34,'Si kwamba mimi nautegemea ushahidi wa wanadamu, lakini nasema mambo haya ili mpate kuokolewa.'),
(2016915,69,43,5,35,'Yohane alikuwa kama taa iliyokuwa ikiwaka na kuangaza, nanyi mlikuwa tayari kufurahia mwanga huo kwa kitambo.'),
(2016916,69,43,5,36,'Lakini mimi nina ushahidi juu yangu ambao ni mkuu zaidi kuliko ule wa Yohane. Kwa maana kazi ninazofanya, kazi alizonipa Baba nizifanye, ndizo zinazonishuhudia kwamba Baba ndiye aliyenituma.'),
(2016917,69,43,5,37,'Naye Baba aliyenituma hunishuhudia. Ninyi hamjapata kamwe kusikia sauti yake, wala kuuona uso wake,'),
(2016918,69,43,5,38,'na ujumbe wake haukai ndani yenu maana hamkumwamini yule aliyemtuma.'),
(2016919,69,43,5,39,'Ninyi huyachunguza Maandiko Matakatifu mkidhani kwamba ndani yake mtapata uzima wa milele; na kumbe maandiko hayohayo yananishuhudia!'),
(2016920,69,43,5,40,'Hata hivyo, ninyi hamtaki kuja kwangu ili mpate uzima. ic'),
(2016921,69,43,5,41,'"Shabaha yangu si kupata sifa kutoka kwa watu.'),
(2016922,69,43,5,42,'Lakini nawajua ninyi, najua kwamba upendo kwa Mungu haumo mioyoni mwenu.'),
(2016923,69,43,5,43,'Mimi nimekuja kwa mamlaka ya Baba yangu, lakini hamnipokei; bali mtu mwingine akija kwa mamlaka yake mwenyewe, mtampokea.'),
(2016924,69,43,5,44,'Mwawezaje kuamini, hali ninyi mnapenda kupokea sifa kutoka kwenu ninyi wenyewe, wala hamtafuti sifa kutoka kwake yeye aliye peke yake Mungu?'),
(2016925,69,43,5,45,'Msifikiri kwamba mimi nitawashtaki kwa Baba. Mose ambaye ninyi mmemtumainia ndiye atakayewashtaki.'),
(2016926,69,43,5,46,'Kama kweli mngemwamini Mose, mngeniamini na mimi pia; maana Mose aliandika juu yangu.'),
(2016927,69,43,5,47,'Lakini hamuyaamini yale aliyoandika, mtawezaje basi, kuamini maneno yangu?"'),
(2016928,69,43,6,1,'Baada ya hayo, Yesu alivuka ziwa Galilaya (au Ziwa Tiberia).'),
(2016929,69,43,6,2,'Umati mkubwa wa watu ulimfuata kwa sababu watu hao walikuwa wameona ishara alizokuwa akifanya kwa kuwaponya wagonjwa.'),
(2016930,69,43,6,3,'Yesu alipanda mlimani, akaketi pamoja na wanafunzi wake.'),
(2016931,69,43,6,4,'Sikukuu ya Wayahudi iitwayo Pasaka ilikuwa imekaribia.'),
(2016932,69,43,6,5,'Basi, Yesu na alipotazama na kuona umati wa watu ukija kwake, alimwambia Filipo, "Tununue wapi mikate ili watu hawa wapate kula?"'),
(2016933,69,43,6,6,'Alisema hivyo kwa kumjaribu Filipo, kwani alijua mwenyewe atakalofanya.)'),
(2016934,69,43,6,7,'Filipo akamjibu, "Mikate ya denari mia mbili za fedha haiwatoshi watu hawa hata kama ila mmoja atapata kipande kidogo tu!"'),
(2016935,69,43,6,8,'Mmoja wa wanafunzi wake aitwaye Andrea, nduguye Simoni Petro, akamwambia,'),
(2016936,69,43,6,9,'"Yupo hapa mtoto mmoja aliye na mikate mitano ya shayiri na samaki wawili; lakini hivi vyatosha nini kwa watu wengi kama hawa?"'),
(2016937,69,43,6,10,'Yesu akasema, "Waketisheni watu." Palikuwa na nyasi tele mahali hapo. Basi, watu wakaketi, jumla yapata wanaume elfu tano.'),
(2016938,69,43,6,11,'Yesu akaitwaa ile mikate, akamshukuru Mungu, akawagawia watu waliokuwa wameketi; akafanya vivyo hivyo na wale samaki, kila mtu akapata kadiri alivyotaka.'),
(2016939,69,43,6,12,'Watu waliposhiba Yesu akawaambia wanafunzi wake, "Kusanyeni vipande vilivyobaki visipotee."'),
(2016940,69,43,6,13,'Basi, wakakusanya vipande vya mikate ya shayiri walivyobakiza wale watu waliokula, wakajaza vikapu kumi na viwili.'),
(2016941,69,43,6,14,'Watu walipoiona ishara hiyo aliyoifanya Yesu, wakasema, "Hakika huyu ndiye nabii anayekuja ulimwenguni."'),
(2016942,69,43,6,15,'Yesu akajua ya kuwa watu walitaka kumchukua wamfanye mfalme, akaondoka tena, akaenda mlimani peke yake. ic'),
(2016943,69,43,6,16,'Ilipokuwa jioni wanafunzi wake waliteremka hadi ziwani,'),
(2016944,69,43,6,17,'wakapanda mashua ili wavuke kwenda Kafarnaumu. Giza lilikuwa limeingia, na Yesu alikuwa hajawafikia bado.'),
(2016945,69,43,6,18,'Ziwa likaanza kuchafuka kwa sababu upepo mkali ulikuwa unavuma.'),
(2016946,69,43,6,19,'Wanafunzi walipokuwa wamekwenda umbali wa kilomita tano au sita, walimwona Yesu akitembea juu ya maji, anakaribia mashua; wakaogopa sana.'),
(2016947,69,43,6,20,'Yesu akawaambia, "Ni mimi, msiogope!"'),
(2016948,69,43,6,21,'Walifurahi kumchukua Yesu katika mashua; na mara mashua ikawasili nchi kavu walipokuwa wanakwenda.'),
(2016949,69,43,6,22,'Kesho yake umati wa watu wale waliobaki upande wa pili wa ziwa walitambua kwamba kulikuwa na mashua moja tu pale, na Yesu hakuingia katika mashua pamoja na wanafunzi wake, ila wanafunzi hao walikuwa wamekwenda zao peke yao.'),
(2016950,69,43,6,23,'Mashua nyingine kutoka Tiberia zilifika mahali hapo watu walipokula ile mikate, Bwana alipokwisha mshukuru Mungu.'),
(2016951,69,43,6,24,'Basi, hao watu walipogundua kwamba Yesu na wanafunzi wake hawakuwapo mahali hapo, walipanda mashua, wakaenda Kafarnaumu wakimtafuta.'),
(2016952,69,43,6,25,'Wale watu walipomkuta Yesu ng`ambo ya pili wa ziwa walimwuliza, "Mwalimu, ulifika lini hapa?"'),
(2016953,69,43,6,26,'Yesu akawajibu, "Kweli nawaambieni, mnanitafuta si kwa kuwa mmeona ishara, bali kwa sababu mlikula ile mikate mkashiba.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2016954,69,43,6,27,'Msikishughulikie chakula kiharibikacho; kishugulikieni chakula kidumucho kwa ajili ya uzima wa milele. Mwana wa Mtu ambaye Baba amemthibitisha atawapeni chakula hicho."'),
(2016955,69,43,6,28,'Wao wakamwuliza, "Tufanye nini ili tuweze kuzitenda kazi za Mungu?"'),
(2016956,69,43,6,29,'Yesu akawajibu, "Hii ndiyo kazi anayotaka Mungu muifanye: kumwamini yule aliyemtuma."'),
(2016957,69,43,6,30,'Hapo wakamwambia, "Utafanya ishara gani ili tuione tupate kukuamini? Utafanya kitu gani?'),
(2016958,69,43,6,31,'Wazee wetu walikula mana kule jangwani, kama yasemavyo Maandiko: `Aliwalisha mkate kutoka mbinguni."`'),
(2016959,69,43,6,32,'Yesu akawaambia, "Kweli nawaambieni, Mose hakuwapeni mkate kutoka mbinguni; Baba yangu ndiye awapaye ninyi mkate halisi kutoka mbinguni.'),
(2016960,69,43,6,33,'Maana mkate wa Mungu ni yule ashukaye kutoka mbinguni na aupaye ulimwengu uzima."'),
(2016961,69,43,6,34,'Basi, wakamwambia, "Mheshimiwa, tupe daima mkate huo."'),
(2016962,69,43,6,35,'Yesu akawaambia, "Mimi ndimi mkate wa uzima. Anayekuja kwangu hataona njaa; anayeniamini hataona kiu kamwe.'),
(2016963,69,43,6,36,'Lakini niliwaambieni kwamba ingawa mmeniona hamniamini.'),
(2016964,69,43,6,37,'Wote anaonipa Baba watakuja kwangu; nami sitamtupa nje yeyote anayekuja kwangu,'),
(2016965,69,43,6,38,'kwani nimeshuka kutoka mbinguni si kwa ajili ya kufanya matakwa yangu, ila kutimiza matakwa ya yule aliyenituma.'),
(2016966,69,43,6,39,'Na matakwa ya yule aliyenituma ndiyo haya: nisimpoteze hata mmoja kati ya wale alionipa, ila niwafufue wote Siku ya mwisho.'),
(2016967,69,43,6,40,'Maana anachotaka Baba yangu ndicho hiki: kila amwonaye Mwana na kumwamini awe na uzima wa milele; nami nitamfufua Siku ya mwisho."'),
(2016968,69,43,6,41,'Basi, Wayahudi wakaanza kunung`unika kwa kuwa alisema: "Mimi ni mkate ulioshuka kutoka mbinguni."'),
(2016969,69,43,6,42,'Wakasema, "Je, huyu si mwana wa Yosefu? Tunawajua baba yake na mama yake! Basi, anawezaje kusema kwamba ameshuka kutoka mbinguni?"'),
(2016970,69,43,6,43,'Yesu akawaambia, "Acheni kunung`unika ninyi kwa ninyi.'),
(2016971,69,43,6,44,'Hakuna mtu awezaye kuja kwangu, Baba aliyenituma asipomvuta kwangu; nami nitamfufua mtu huyo Siku ya mwisho.'),
(2016972,69,43,6,45,'Manabii wameandika: `Watu wote watafundishwa na Mungu.` Kila mtu anayemsikia Baba na kujifunza kutoka kwake, huja kwangu.'),
(2016973,69,43,6,46,'Hii haina maana kwamba yupo mtu aliyemwona Baba, isipokuwa yule aliyetoka kwa Mungu; huyo ndiye aliyemwona Baba.'),
(2016974,69,43,6,47,'Kweli, nawaambieni, anayeamini anao uzima wa milele.'),
(2016975,69,43,6,48,'Mimi ni mkate wa uzima.'),
(2016976,69,43,6,49,'Wazee wenu walikula mana kule jangwani, lakini walikufa.'),
(2016977,69,43,6,50,'Huu ndio mkate kutoka mbinguni; mkate ambao anayekula hatakufa.'),
(2016978,69,43,6,51,'Mimi ni mkate hai ulioshuka kutoka mbinguni. Mtu yeyote akila mkate huu ataishi milele. Na mkate nitakaompa ni mwili wangu ninaoutoa kwa ajili ya uzima wa ulimwengu."'),
(2016979,69,43,6,52,'Ndipo Wayahudi wakaanza kubishana kati yao:'),
(2016980,69,43,6,53,'Yesu akawaambia, "Kweli nawaambieni, msipokula mwili wa Mwana wa Mtu na kunywa damu yake, hamtakuwa na uzima ndani yenu.'),
(2016981,69,43,6,54,'Anayekula mwili wangu na kunywa damu yangu anao uzima wa milele nami nitamfufua siku ya mwisho.'),
(2016982,69,43,6,55,'Maana mwili wangu ni chakula cha kweli, na damu yangu ni kinywaji cha kweli.'),
(2016983,69,43,6,56,'Aulaye mwili wangu na kunywa damu yangu, akaa ndani yangu, nami nakaa ndani yake.'),
(2016984,69,43,6,57,'Baba aliye hai alinituma, nami naishi kwa sababu yake; vivyo hivyo anilaye mimi ataishi pia kwa sababu yangu.'),
(2016985,69,43,6,58,'Basi, huu ndio mkate ulioshuka kutoka mbinguni; si kama mana waliyokula babu zetu, wakafa. Aulaye mkate huu ataishi milele."'),
(2016986,69,43,6,59,'Yesu alisema hayo alipokuwa akifundisha katika sunagogi kule Kafarnaumu.'),
(2016987,69,43,6,60,'Basi, wengi wa wafuasi wake waliposikia hayo, wakasema, "Haya ni mambo magumu! Nani awezaye kuyasikiliza?"'),
(2016988,69,43,6,61,'Yesu alijua bila kuambiwa na mtu kwamba wanafunzi wake walikuwa wananung`unika juu ya jambo hilo, akawauliza, "Je, jambo hili linawafanya muwe na mashaka?'),
(2016989,69,43,6,62,'Itakuwaje basi, mtakapomwona Mwana wa Mtu akipanda kwenda kule alikokuwa kwanza?'),
(2016990,69,43,6,63,'Roho ndiye atiaye uzima; binadamu peke yake hawezi. Maneno niliyowaambieni ni Roho, ni uzima.'),
(2016991,69,43,6,64,'Hata hivyo, wako baadhi yenu wasioamini." (Yesu alisema hivyo kwani alijua tangu mwanzo ni kina nani wasioamini, na pia ni nani atakayemsaliti.)'),
(2016992,69,43,6,65,'Kisha akasema, "Ndiyo maana niliwaambieni kwamba hakuna awezaye kuja kwangu asipowezeshwa na Baba yangu."'),
(2016993,69,43,6,66,'Kutokana na hayo, wengi wa wafuasi wake walirudi nyuma wasiandamane naye tena.'),
(2016994,69,43,6,67,'Basi, Yesu akawauliza wale kumi na wawili, "Je, nanyi pia mwataka kwenda zenu?"'),
(2016995,69,43,6,68,'Simoni Petro akamjibu, "Bwana, tutakwenda kwa nani? Wewe unayo maneno yaletayo uzima wa milele.'),
(2016996,69,43,6,69,'Sisi tunaamini, na tunajua kwamba wewe ndiwe yule Mtakatifu wa Mungu."'),
(2016997,69,43,6,70,'Yesu akawaambia, "Je, sikuwachagua ninyi kumi na wawili? Hata hivyo, mmoja wenu ni Ibilisi!"'),
(2016998,69,43,6,71,'Yesu alisema hayo juu ya Yuda, mwana wa Simoni Iskarioti; maana huyu alikuwa ndiye atakayemsaliti, ingawa alikuwa mmoja wa wale kumi na wawili.'),
(2016999,69,43,7,1,'Baada ya hayo, Yesu alikuwa akitembea katika Galilaya. Hakutaka kutembea mkoani Yudea kwa sababu viongozi wa Wayahudi walikuwa wanataka kumwua.'),
(2017000,69,43,7,2,'Sikukuu ya Vibanda ya Wayahudi ilikuwa imekaribia.'),
(2017001,69,43,7,3,'Basi ndugu zake wakamwambia, "Ondoka hapa uende Yudea ili wanafunzi wako wazione kazi unazozifanya.'),
(2017002,69,43,7,4,'Mtu hafanyi mambo kwa siri kama anataka kujulikana kwa watu. Maadam unafanya mambo haya, basi, jidhihirishe kwa ulimwengu."'),
(2017003,69,43,7,5,'Hata ndugu zake hawakumwamini!)');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017004,69,43,7,6,'Basi, Yesu akawaambia, "Wakati wangu ufaao haujafika bado. Lakini kwenu ninyi kila wakati unafaa.'),
(2017005,69,43,7,7,'Ulimwengu hauwezi kuwachukia ninyi, lakini mimi wanichukia kwa sababu mimi nauambia wazi kwamba matendo yake ni maovu.'),
(2017006,69,43,7,8,'Ninyi nendeni kwenye sikukuu hiyo. Mimi siendi kwenye sikukuu hiyo, maana saa yangu ifaayo haijafika."'),
(2017007,69,43,7,9,'Alisema hayo kisha akabaki huko Galilaya.'),
(2017008,69,43,7,10,'Baada ya ndugu zake kwenda kwenye sikukuu, Yesu naye alikwenda, lakini hakuenda kwa hadhara bali kwa siri.'),
(2017009,69,43,7,11,'Viongozi wa Wayahudi walikuwa wanamtafuta kwenye sikukuu hiyo; Wakauliza: "Yuko wapi?"'),
(2017010,69,43,7,12,'Kulikuwa na minong`ono mingi katika umati wa watu. Baadhi yao walisema, "Ni mtu mwema." Wengine walisema, "La! Anawapotosha watu."'),
(2017011,69,43,7,13,'Hata hivyo hakuna mtu aliyethubutu kusema, habari zake hadharani kwa kuwaogopa viongozi wa Wayahudi.'),
(2017012,69,43,7,14,'Sikukuu hiyo ilipofikia katikati, Yesu naye alikwenda Hekaluni, akaanza kufundisha.'),
(2017013,69,43,7,15,'Basi, Wayahudi wakashangaa na kusema "Mtu huyu amepataje elimu naye hakusoma shuleni?"'),
(2017014,69,43,7,16,'Hapo Yesu akawajibu, "Mafundisho ninayofundisha si yangu, bali ni yake yeye aliyenituma.'),
(2017015,69,43,7,17,'Mtu anayependa kufanya yale anayotaka Mungu, atajua kama mafundisho yangu yametoka kwa Mungu, au mimi najisemea tu mwenyewe.'),
(2017016,69,43,7,18,'Yeye anayejisemea tu mwenyewe anatafuta sifa yake mwenyewe; lakini anayetafuta sifa ya yule aliyemtuma, huyo ni mwaminifu, na ndani yake hamna uovu wowote.'),
(2017017,69,43,7,19,'Je, Mose hakuwapeni Sheria? Hata hivyo, hakuna hata mmoja wenu anayeishika Sheria. Kwa nini mnataka kuniua?"'),
(2017018,69,43,7,20,'Hapo watu wakamjibu, "Una wazimu wewe! Nani anataka kukuua?"'),
(2017019,69,43,7,21,'Yesu akawajibu, "Kuna jambo moja nililofanya, nanyi mnalistaajabia.'),
(2017020,69,43,7,22,'Mose aliwapeni ile desturi ya kutahiri. (Si kwamba desturi hiyo ilitoka kwa Mose, bali ilitoka kwa mababu). Sasa ninyi humtahiri mtu hata siku ya Sabato.'),
(2017021,69,43,7,23,'Ikiwa basi, mtu hutahiriwa hata siku ya Sabato kusudi Sheria ya Mose isivunjwe, mbona mnanikasirikia kwa sababu nimemfanya mtu kuwa mzima kabisa siku ya Sabato?'),
(2017022,69,43,7,24,'Msihukumu mambo kwa nje tu; toeni hukumu ya haki."'),
(2017023,69,43,7,25,'Baadhi ya watu wa Yerusalemu walisema, "Je, yule mtu wanayemtafuta wamuue si huyu?'),
(2017024,69,43,7,26,'Tazameni sasa! Anawaonya hadharani, wala hakuna mtu anayemwambia hata neno. Je, yawezekana kuwa viongozi wametambua kweli kwamba huyu ndiye Kristo?'),
(2017025,69,43,7,27,'Kristo atakapokuja hakuna mtu atakayejua mahali alikotoka, lakini sisi tunajua alikotoka mtu huyu!"'),
(2017026,69,43,7,28,'Basi, Yesu alipokuwa anafundisha Hekaluni alipaaza sauti na kusema, "Ati mnanijua; hata nilikotoka mnakujua! Hata hivyo, sikuja kwa mamlaka yangu mwenyewe; ila yeye aliyenituma mimi ni wa kweli, nanyi hamumjui.'),
(2017027,69,43,7,29,'Lakini mimi namjua kwa sababu nimetoka kwake, naye ndiye aliyenituma."'),
(2017028,69,43,7,30,'Basi, watu wakataka kumtia nguvuni, lakini hakuna mtu aliyethubutu kumkamata kwa sababu saa yake ilikuwa haijafika bado.'),
(2017029,69,43,7,31,'Wengi katika ule umati wa watu walimwamini, wakasema, "Je, Kristo akija atafanya ishara kubwa zaidi kuliko alizozifanya huyu?"'),
(2017030,69,43,7,32,'Mafarisayo waliwasikia watu wakinong`ona maneno hayo juu ya Yesu. Basi, wao pamoja na makuhani wakuu wakawatuma walinzi wamtie nguvuni.'),
(2017031,69,43,7,33,'Yesu akasema, "Bado niko nanyi kwa muda mfupi, kisha nitamwendea yule aliyenituma.'),
(2017032,69,43,7,34,'Mtanitafuta lakini hamtaniona, maana pale nitakapokuwa ninyi hamwezi kufika."'),
(2017033,69,43,7,35,'Viongozi wa Wayahudi wakasema wao kwa wao, "Mtu huyu atakwenda wapi ambapo hatutaweza kumpata? Atakwenda kwa Wayahudi waliotawanyika kati ya Wagiriki, na kuwafundisha Wagiriki?'),
(2017034,69,43,7,36,'Ana maana gani anaposema: `Mtanitafuta lakini hamtanipata, na mahali nitakapokuwa ninyi hamwezi kufika?"`'),
(2017035,69,43,7,37,'Siku ya mwisho ya sikukuu hiyo ilikuwa siku maalum. Yesu alisimama, akasema kwa sauti kubwa, "Aliye na kiu na aje kwangu anywe.'),
(2017036,69,43,7,38,'Kama yasemavyo Maandiko Matakatifu: `Anayeniamini mimi, mito ya maji yenye uzima itatiririka kutoka moyoni mwake!"`'),
(2017037,69,43,7,39,'Alisema hayo kumhusu Roho ambaye wale waliomwamini yeye watampokea. Wakati huo Roho alikuwa hajafika kwa sababu Yesu alikuwa hajatukuzwa bado.)'),
(2017038,69,43,7,40,'Baadhi ya watu katika ule umati walisikia maneno hayo, wakasema, "Kweli mtu huyu ndiye yule nabii!"'),
(2017039,69,43,7,41,'Wengine wakasema, "Huyu ndiye Kristo!" Lakini wengine walisema, "Je, yawezekana Kristo akatoka Galilaya?'),
(2017040,69,43,7,42,'Maandiko Matakatifu yasemaje? Yanasema: `Kristo atatoka katika ukoo wa Daudi, na atazaliwa Bethlehemu, mji wa Daudi!"`'),
(2017041,69,43,7,43,'Basi, kukatokea mafarakano juu yake katika ule umati wa watu.'),
(2017042,69,43,7,44,'Baadhi ya watu walitaka kumtia nguvuni lakini hakuna aliyejaribu kumkamata.'),
(2017043,69,43,7,45,'Kisha wale walinzi wakarudi kwa makuhani wakuu na Mafarisayo; nao wakawauliza, "Kwa nini hamkumleta?"'),
(2017044,69,43,7,46,'Walinzi wakawajibu, "Hakuna mtu aliyepata kamwe kusema kama asemavyo mtu huyu!"'),
(2017045,69,43,7,47,'Mafarisayo wakawauliza, "Je, nanyi pia mmedanganyika?'),
(2017046,69,43,7,48,'Je, mmekwisha mwona hata mmoja wa viongozi wa watu, au mmoja wa Mafarisayo aliyemwamini?'),
(2017047,69,43,7,49,'Lakini umati huu haujui Sheria ya Mose; umelaaniwa!"'),
(2017048,69,43,7,50,'Mmoja wao alikuwa Nikodemo ambaye hapo awali alikuwa amemwendea Yesu. Basi, yeye akawaambia,'),
(2017049,69,43,7,51,'"Je, Sheria yetu humhukumu mtu kabla ya kumsikia kwanza na kujua anafanya nini?"'),
(2017050,69,43,7,52,'Nao wakamjibu, "Je, wewe pia umetoka Galilaya? Haya, kayachunguze Maandiko Matakatifu nawe utaona kwamba Galilaya hakutoki kamwe nabii!" [[['),
(2017051,69,43,7,53,'Basi, wote wakaondoka, kila mtu akaenda zake;'),
(2017052,69,43,8,1,'lakini Yesu akaenda kwenye mlima wa Mizeituni.'),
(2017053,69,43,8,2,'Kesho yake asubuhi na mapema alikwenda tena Hekaluni. Watu wote wakamwendea, naye akaketi akawa anawafundisha.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017054,69,43,8,3,'Basi, walimu wa Sheria na Mafarisayo wakamletea mwanamke mmoja aliyefumaniwa katika uzinzi. Wakamsimamisha katikati yao.'),
(2017055,69,43,8,4,'Kisha wakamwuliza Yesu, "Mwalimu! Mwanamke huyu alifumaniwa katika uzinzi.'),
(2017056,69,43,8,5,'Katika Sheria yetu Mose alituamuru mwanamke kama huyu apigwe mawe. Basi, wewe wasemaje?"'),
(2017057,69,43,8,6,'Walisema hivyo kumjaribu, wapate kisa cha kumshtaki. Lakini Yesu akainama chini, akaandika ardhini kwa kidole.'),
(2017058,69,43,8,7,'Walipozidi kumwuliza, Yesu akainuka, akawaambia, "Mtu asiye na dhambi miongoni mwenu na awe wa kwanza kumpiga jiwe."'),
(2017059,69,43,8,8,'Kisha akainama tena, akawa anaandika ardhini.'),
(2017060,69,43,8,9,'Waliposikia hivyo, wakaanza kutoweka mmojammoja, wakitanguliwa na wazee. Yesu akabaki peke yake, na yule mwanamke amesimama palepale.'),
(2017061,69,43,8,10,'Yesu alipoinuka akamwuliza huyo mwanamke, "Wako wapi wale watu? Je, hakuna hata mmoja aliyekuhukumu?"'),
(2017062,69,43,8,11,'Huyo mwanamke akamjibu, "Mheshimiwa, hakuna hata mmoja!" Naye Yesu akamwambia, "Wala mimi sikuhukumu. Nenda zako; na tangu sasa usitende dhambi tena."]*fb* mahali pengine.'),
(2017063,69,43,8,12,'Yesu alipozungumza nao tena, aliwaambia, "Mimi ndimi mwanga wa ulimwengu. Anayenifuata mimi hatembei kamwe gizani, bali atakuwa na mwanga wa uzima."'),
(2017064,69,43,8,13,'Basi, Mafarisayo wakamwambia, "Wewe unajishuhudia mwenyewe; kwa hiyo ushahidi wako si halali."'),
(2017065,69,43,8,14,'Yesu akawajibu, "Hata kama ninajishuhudia mwenyewe, ushahidi wangu ni wa kweli kwa sababu mimi najua nilikotoka na ninakokwenda. Lakini ninyi hamjui nilikotoka wala ninakokwenda.'),
(2017066,69,43,8,15,'Ninyi mnahukumu kwa fikira za kibinadamu, lakini mimi simhukumu mtu.'),
(2017067,69,43,8,16,'Hata nikihukumu, hukumu yangu ni ya haki kwa sababu mimi siko peke yangu; Baba aliyenituma yuko pamoja nami.'),
(2017068,69,43,8,17,'Imeandikwa katika Sheria yenu ya kwamba ushahidi wa watu wawili ni halali.'),
(2017069,69,43,8,18,'Mimi najishuhudia mwenyewe, naye Baba aliyenituma, ananishuhudia pia."'),
(2017070,69,43,8,19,'Hapo wakamwuliza, "Baba yako yuko wapi?" Yesu akawajibu "Ninyi hamnijui mimi wala hamumjui Baba. Kama mngenijua mimi, mngemjua na Baba yangu pia."'),
(2017071,69,43,8,20,'Yesu alisema maneno hayo kwenye chumba cha hazina alipokuwa anafundisha Hekaluni. Wala hakuna mtu aliyemtia nguvuni, kwa sababu saa yake ilikuwa haijafika bado.'),
(2017072,69,43,8,21,'Yesu akawaambia tena, "Naenda zangu nanyi mtanitafuta, lakini mtakufa katika dhambi zenu. Niendako mimi,ninyi hamwezi kufika."'),
(2017073,69,43,8,22,'Basi, viongozi wa Wayahudi wakasema, "Je, atajiua? Mbona anasema: `Niendako ninyi hamwezi kufika?"`'),
(2017074,69,43,8,23,'Yesu akawaambia, "Ninyi mmetoka papa hapa chini, mimi nimetoka juu; ninyi ni wa ulimwengu huu, mimi si wa ulimwengu huu.'),
(2017075,69,43,8,24,'Ndiyo maana niliwaambieni mtakufa katika dhambi zenu. Kama msipoamini kwamba `Mimi ndimi`, mtakufa katika dhambi zenu."'),
(2017076,69,43,8,25,'Nao wakamwuliza, "Wewe ni nani?" Yesu akawajibu, "Nimewaambieni tangu mwanzo!'),
(2017077,69,43,8,26,'Ninayo mengi ya kusema na kuhukumu juu yenu. Lakini yule aliyenituma ni kweli; nami nauambia ulimwengu mambo yale tu niliyoyasikia kutoka kwake."'),
(2017078,69,43,8,27,'Hawakuelewa kwamba Yesu alikuwa akisema nao juu ya Baba.'),
(2017079,69,43,8,28,'Basi, Yesu akawaambia, "Mtakapokwisha mwinua Mwana wa Mtu hapo ndipo mtakapojua kwamba `Mimi ndimi`, na kwamba sifanyi chochote mimi mwenyewe, ila nasema tu yale Baba aliyonifundisha.'),
(2017080,69,43,8,29,'Yule aliyenituma yuko pamoja nami; yeye hakuniacha peke yangu kwani nafanya daima yale yanayompendeza."'),
(2017081,69,43,8,30,'Baada ya kusema hayo watu wengi walimwamini.'),
(2017082,69,43,8,31,'Basi, Yesu akawaambia wale Wayahudi waliomwamini, "Kama mkiyazingatia mafundisho yangu mtakuwa kweli wanafunzi wangu.'),
(2017083,69,43,8,32,'Mtaujua ukweli, nao ukweli utawapeni uhuru."'),
(2017084,69,43,8,33,'Nao wakamjibu, "Sisi ni wazawa wa Abrahamu, na hatujapata kamwe kuwa watumwa wa mtu yeyote yule. Una maana gani unaposema: `mtakuwa huru?"`'),
(2017085,69,43,8,34,'Yesu akawajibu, "Kweli nawaambieni, kila mtu anayetenda dhambi ni mtumwa wa dhambi.'),
(2017086,69,43,8,35,'Mtumwa hana makao ya kudumu nyumbani, lakini mwana anayo makao ya kudumu.'),
(2017087,69,43,8,36,'Kama mwana akiwapeni uhuru mtakuwa huru kweli.'),
(2017088,69,43,8,37,'Najua kwamba ninyi ni wazawa wa Abrahamu. Hata hivyo, mnataka kuniua kwa sababu hamuyakubali mafundisho yangu.'),
(2017089,69,43,8,38,'Mimi nasema yale aliyonionyesha Baba, lakini ninyi mwafanya yale aliyowaambieni baba yenu."'),
(2017090,69,43,8,39,'Wao wakamjibu, "Baba yetu ni Abrahamu!" Yesu akawaambia, "Kama ninyi mngekuwa watoto wa Abrahamu, mngefanya kama alivyofanya Abrahamu,'),
(2017091,69,43,8,40,'Mimi nimewaambieni ukweli niliousikia kwa Mungu; hata hivyo, ninyi mwataka kuniua. Abrahamu hakufanya hivyo!'),
(2017092,69,43,8,41,'Ninyi mnafanya mambo yaleyale aliyofanya babu yenu." Wao wakamwambia, "Sisi si watoto haramu! Tunaye baba mmoja tu, yaani Mungu."'),
(2017093,69,43,8,42,'Yesu akawaambia, "Kama Mungu angekuwa Baba yenu, mngenipenda mimi, maana mimi nilitoka kwa Mungu na sasa niko hapa. Sikuja kwa mamlaka yangu mwenyewe, ila yeye alinituma.'),
(2017094,69,43,8,43,'Kwa nini hamwelewi hayo ninayosema? Ni kwa kuwa hamwezi kuusikiliza ujumbe wangu.'),
(2017095,69,43,8,44,'Ninyi ni watoto wa baba yenu Ibilisi na mnataka tu kutekeleza tamaa za baba yenu. Yeye alikuwa muuaji tangu mwanzo; hana msimamo katika ukweli, kwani ukweli haumo ndani yake. Kila asemapo uongo, husema kutokana na hali yake ya maumbile, maana yeye ni mwongo na baba wa uongo.'),
(2017096,69,43,8,45,'Mimi nasema ukweli, na ndiyo maana ninyi hamniamini.'),
(2017097,69,43,8,46,'Nani kati yenu awezaye kuthibitisha kuwa mimi nina dhambi? Ikiwa basi nasema ukweli, kwa nini hamniamini?'),
(2017098,69,43,8,47,'Aliye wa Mungu husikiliza maneno ya Mungu. Lakini ninyi hamsikilizi kwa sababu ninyi si (watu wa) Mungu."'),
(2017099,69,43,8,48,'Wayahudi wakamwambia, "Je, hatukusema kweli kwamba wewe ni Msamaria, na tena una pepo?"'),
(2017100,69,43,8,49,'Yesu akajibu, "Mimi sina pepo; mimi namheshimu Baba yangu, lakini ninyi hamniheshimu.'),
(2017101,69,43,8,50,'Mimi sijitafutii utukufu wangu mwenyewe; yuko mmoja mwenye kuutafuta utukufu huo, naye ni hakimu.'),
(2017102,69,43,8,51,'Kweli nawaambieni, anayeuzingatia ujumbe wangu hatakufa milele."'),
(2017103,69,43,8,52,'Basi, Wayahudi wakasema, "Sasa tunajua kweli kwamba wewe ni mwendawazimu! Abrahamu alikufa, na manabii pia walikufa, nawe wasema ati, `Anayeuzingatia ujumbe wangu hatakufa milele!`');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017104,69,43,8,53,'Je, unajifanya mkuu zaidi kuliko baba yetu Abrahamu ambaye alikufa? Hata na manabii walikufa. Wewe unajifanya kuwa nani?"'),
(2017105,69,43,8,54,'Yesu akawajibu, "Nikijitukuza mwenyewe, utukufu wangu si kitu. Baba yangu ambaye ninyi mwasema ni Baba yenu, ndiye anayenitukuza.'),
(2017106,69,43,8,55,'Ninyi hamjapata kumjua, lakini mimi namjua. Na, nikisema simjui, nitakuwa mwongo kama ninyi. Mimi namjua na ninashika neno lake.'),
(2017107,69,43,8,56,'Abrahamu, baba yenu, alishangilia aione siku yangu; naye aliiona, akafurahi."'),
(2017108,69,43,8,57,'Basi, Wayahudi wakamwambia, "Wewe hujatimiza miaka hamsini bado, nawe umemwona Abrahamu?"'),
(2017109,69,43,8,58,'Yesu akawaambia, "Kweli nawaambieni, kabla Abrahamu hajazaliwa, mimi niko."'),
(2017110,69,43,8,59,'Hapo wakaokota mawe ili wamtupie, lakini Yesu akajificha, akatoka Hekaluni.'),
(2017111,69,43,9,1,'Yesu alipokuwa akipita alimwona mtu mmoja, kipofu tangu kuzaliwa.'),
(2017112,69,43,9,2,'Basi, wanafunzi wakamwuliza, "Mwalimu! Ni nani aliyetenda dhambi: mtu huyu, ama wazazi wake, hata akazaliwa kipofu?"'),
(2017113,69,43,9,3,'Yesu akajibu, "Jambo hili halikutukia kwa sababu ya dhambi zake yeye, wala dhambi za wazazi wake; ila alizaliwa kipofu ili nguvu ya Mungu ionekane ikifanya kazi ndani yake.'),
(2017114,69,43,9,4,'Kukiwa bado mchana yatupasa kuendelea kufanya kazi za yule aliyenituma; maana usiku unakuja ambapo mtu hawezi kufanya kazi.'),
(2017115,69,43,9,5,'Wakati ningali ulimwenguni, mimi ni mwanga wa ulimwengu."'),
(2017116,69,43,9,6,'Baada ya kusema hayo, akatema mate chini, akafanyiza tope, akampaka yule kipofu machoni,'),
(2017117,69,43,9,7,'akamwambia, "Nenda ukanawe katika bwawa la Siloamu." (maana ya jina hili ni "aliyetumwa"). Basi, huyo kipofu akaenda, akanawa, kisha akarudi akiwa anaona.'),
(2017118,69,43,9,8,'Basi, jirani zake na wale waliokuwa wanajua kwamba hapo awali alikuwa maskini mwombaji, wakasema, "Je, huyu siye yule maskini aliyekuwa akiketi na kuomba?"'),
(2017119,69,43,9,9,'Baadhi yao wakasema, "Ndiye." Wengine wakasema, "La! Ila anafanana naye." Lakini huyo aliyekuwa kipofu akasema, "Ni mimi!"'),
(2017120,69,43,9,10,'Basi, wakamwuliza, "Sasa, macho yako yalipataje kufumbuliwa?"'),
(2017121,69,43,9,11,'Naye akawajibu, "Yule mtu aitwaye Yesu alifanya tope, akanipaka machoni na kuniambia: `Nenda ukanawe katika bwawa la Siloamu.` Basi, mimi nikaenda, nikanawa, nikapata kuona."'),
(2017122,69,43,9,12,'Wakamwuliza, "Yeye yuko wapi?" Naye akawajibu, "Mimi sijui!"'),
(2017123,69,43,9,13,'Kisha wakampeleka huyo mtu aliyekuwa kipofu kwa Mafarisayo.'),
(2017124,69,43,9,14,'Siku hiyo Yesu alipofanya tope na kumfumbua macho mtu huyo, ilikuwa siku ya Sabato.'),
(2017125,69,43,9,15,'Basi, Mafarisayo wakamwuliza mtu huyo, "Umepataje kuona?" Naye akawaambia, "Alinipaka tope machoni, nami nikanawa na sasa naona."'),
(2017126,69,43,9,16,'Baadhi ya Mafarisayo wakasema, "Mtu huyu hakutoka kwa Mungu, maana hashiki sheria ya Sabato." Lakini wengine wakasema, "Mtu mwenye dhambi awezaje kufanya ishara za namna hii?" Kukawa na mafarakano kati yao.'),
(2017127,69,43,9,17,'Wakamwuliza tena huyo mtu aliyekuwa kipofu, "Maadam yeye amekufungua macho, wasemaje juu yake?" Naye akawaambia, "Yeye ni nabii!"'),
(2017128,69,43,9,18,'Viongozi wa Wayahudi hawakusadiki kwamba mtu huyo alikuwa kipofu hapo awali na sasa anaona mpaka walipowaita wazazi wake.'),
(2017129,69,43,9,19,'Basi, wakawauliza hao wazazi, "Je, huyu ndiye mtoto wenu ambaye ninyi mwasema alizaliwa kipofu? Sasa amepataje kuona?"'),
(2017130,69,43,9,20,'Wazazi wake wakajibu, "Tunajua kwamba huyu ni mtoto wetu, na kwamba alizaliwa kipofu.'),
(2017131,69,43,9,21,'Lakini amepataje kuona, hatujui; na wala hatumjui yule aliyemfumbua macho. Mwulizeni yeye mwenyewe; yeye ni mtu mzima, anaweza kujitetea mwenyewe."'),
(2017132,69,43,9,22,'Wazazi wake walisema hivyo kwa sababu waliwaogopa viongozi wa Wayahudi kwani viongozi hao walikuwa wamepatana ya kwamba mtu yeyote atakayekiri kwamba Yesu ni Kristo atafukuzwa nje ya sunagogi.'),
(2017133,69,43,9,23,'Ndiyo maana wazazi wake walisema: "Yeye ni mtu mzima, mwulizeni."'),
(2017134,69,43,9,24,'Basi, wakamwita tena aliyekuwa kipofu, wakamwambia, "Sema ukweli mbele ya Mungu! Sisi tunajua kwamba mtu huyu ni mwenye dhambi."'),
(2017135,69,43,9,25,'Yeye akajibu, "Kama ni mwenye dhambi mimi sijui. Lakini kitu kimoja najua: Nilikuwa kipofu, na sasa naona."'),
(2017136,69,43,9,26,'Basi, wakamwuliza, "Alikufanyia nini? Alikufumbuaje macho yako?"'),
(2017137,69,43,9,27,'Huyo mtu akawajibu, "Nimekwisha waambieni, nanyi hamkusikiliza; kwa nini mwataka kusikia tena? Je, ninyi pia mnataka kuwa wafuasi wake?"'),
(2017138,69,43,9,28,'Lakini wao wakamtukana wakisema, "Wewe ni mfuasi wake; sisi ni wafuasi wa Mose.'),
(2017139,69,43,9,29,'Sisi tunajua kwamba Mungu alisema na Mose, lakini mtu huyu hatujui ametoka wapi!"'),
(2017140,69,43,9,30,'Naye akawajibu, "Hili ni jambo la kushangaza! Ninyi hamjui ametoka wapi, lakini amenifumbua macho yangu!'),
(2017141,69,43,9,31,'Tunajua kwamba Mungu hawasikilizi watu wenye dhambi, ila humsikiliza yeyote mwenye kumcha na kutimiza mapenzi yake.'),
(2017142,69,43,9,32,'Tangu mwanzo wa ulimwengu haijasikika kwamba mtu ameyafumbua macho ya mtu aliyezaliwa kipofu.'),
(2017143,69,43,9,33,'Kama mtu huyu hakutoka kwa Mungu, hangeweza kufanya chochote!"'),
(2017144,69,43,9,34,'Wao wakamjibu, "Wewe ulizaliwa na kulelewa katika dhambi; unawezaje kutufundisha sisi?" Basi, wakamfukuzia mbali.'),
(2017145,69,43,9,35,'Yesu alisikia kwamba walikuwa wamemfukuzia mbali, naye alipomkuta akamwuliza, "Je, wewe unamwamini Mwana wa Mtu?"'),
(2017146,69,43,9,36,'Huyo mtu akajibu, "Mheshimiwa, niambie yeye ni nani, ili nipate kumwamini."'),
(2017147,69,43,9,37,'Yesu akamwambia, "Umekwisha mwona, naye ndiye anayesema nawe sasa."'),
(2017148,69,43,9,38,'Basi, huyo mtu akasema, "Ninaamini Bwana!" Akamsujudia.'),
(2017149,69,43,9,39,'Yesu akasema, "Mimi nimekuja ulimwenguni kutoa hukumu, kusudi wasioona wapate kuona, na wale wanaoona wawe vipofu."'),
(2017150,69,43,9,40,'Baadhi ya Mafarisayo waliokuwa pamoja naye walisikia maneno hayo, wakamwuliza, "Je, sisi pia ni vipofu?"'),
(2017151,69,43,9,41,'Yesu akawajibu, "Kama mngekuwa vipofu, hamngekuwa na hatia; lakini sasa ninyi mwasema: `Sisi tunaona`, na hiyo yaonyesha kwamba mna hatia bado.'),
(2017152,69,43,10,1,'Yesu alisema "Kweli nawaambieni, yeyote yule asiyeingia katika zizi la kondoo kwa kupitia mlangoni, bali hupenya na kuingia kwa njia nyingine, huyo ni mwizi na mnyang`anyi.'),
(2017153,69,43,10,2,'Lakini anayeingia kwa kupitia mlangoni, huyo ndiye mchungaji wa kondoo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017154,69,43,10,3,'Mngoja mlango wa zizi humfungulia, na kondoo husikia sauti yake, naye huwaita kondoo wake kila mmoja kwa jina lake na kuwaongoza nje.'),
(2017155,69,43,10,4,'Akisha watoa nje huwatangulia mbele nao kondoo humfuata, kwani wanaijua sauti yake.'),
(2017156,69,43,10,5,'Kondoo hao hawawezi kumfuata mgeni, bali watamkimbia kwa sababu hawaijui sauti yake."'),
(2017157,69,43,10,6,'Yesu aliwaambia mfano huo, lakini wao hawakuelewa alichotaka kuwaambia.'),
(2017158,69,43,10,7,'Basi, akasema tena, "Kweli nawaambieni, mimi ni mlango wa kondoo.'),
(2017159,69,43,10,8,'Wale wengine wote waliokuja kabla yangu ni wezi na wanyang`anyi, nao kondoo hawakuwasikiliza.'),
(2017160,69,43,10,9,'Mimi ni mlango. Anayeingia kwa kupitia kwangu ataokolewa; ataingia na kutoka, na kupata malisho.'),
(2017161,69,43,10,10,'Mwizi huja kwa shabaha ya kuiba, kuua na kuharibu. Mimi nimekuja mpate kuwa na uzima--uzima kamili.'),
(2017162,69,43,10,11,'"Mimi ni mchungaji mwema. Mchungaji mwema huutoa uhai wake kwa ajili ya kondoo wake.'),
(2017163,69,43,10,12,'Mtu wa kuajiriwa ambaye si mchungaji, na wala kondoo si mali yake, anapoona mbwa mwitu anakuja, huwaacha kondoo na kukimbia. Kisha mbwa mwitu huwakamata na kuwatawanya.'),
(2017164,69,43,10,13,'Yeye hajali kitu juu ya kondoo kwa sababu yeye ni mtu wa mshahara tu.'),
(2017165,69,43,10,14,'Mimi ni mchungaji mwema. Nawajua walio wangu, nao walio wangu wananijua mimi,'),
(2017166,69,43,10,15,'kama vile Baba anijuavyo, nami nimjuavyo Baba. Mimi nayatoa maisha yangu kwa ajili yao.'),
(2017167,69,43,10,16,'Tena ninao kondoo wengine ambao hawamo zizini humu. Inanibidi kuwaleta hao pia, nao wataisikia sauti yangu, na kutakuwako kundi moja na mchungaji mmoja.'),
(2017168,69,43,10,17,'"Baba ananipenda kwani nautoa uhai wangu ili nipate kuupokea tena.'),
(2017169,69,43,10,18,'Hakuna mtu anayeninyang`anya uhai wangu; mimi na nautoa kwa hiari yangu mwenyewe. Ninao uwezo wa kuutoa na uwezo wa kuuchukua tena. Hivi ndivyo Baba alivyoniamuru nifanye."'),
(2017170,69,43,10,19,'Kukawa tena na mafarakano kati ya Wayahudi kwa sababu ya maneno haya.'),
(2017171,69,43,10,20,'Wengi wao wakasema, "Ana pepo; tena ni mwendawazimu! Ya nini kumsikiliza?"'),
(2017172,69,43,10,21,'Wengine wakasema, "Haya si maneno ya mwenye pepo. Je, pepo anaweza kuyafumbua macho ya vipofu?"'),
(2017173,69,43,10,22,'Huko Yerusalemu kulikuwa na sikukuu ya Kutabaruku. Wakati huo ulikuwa wa baridi.'),
(2017174,69,43,10,23,'Naye Yesu akawa anatembea Hekaluni katika ukumbi wa Solomoni.'),
(2017175,69,43,10,24,'Basi, Wayahudi wakamzunguka, wakamwuliza, "Utatuacha katika mashaka mpaka lini? Kama wewe ndiye Kristo, basi, tuambie wazi."'),
(2017176,69,43,10,25,'Yesu akawajibu, "Nimewaambieni, lakini hamsadiki. Kazi ninazozifanya mimi kwa jina la Baba yangu zinanishuhudia.'),
(2017177,69,43,10,26,'Lakini ninyi hamsadiki kwa sababu ninyi si kondoo wangu.'),
(2017178,69,43,10,27,'Kondoo wangu huisikia sauti yangu; mimi nawajua, nao hunifuata.'),
(2017179,69,43,10,28,'Mimi nawapa uzima wa milele; nao hawatapotea milele, wala hakuna mtu atakayeweza kuwatoa mkononi mwangu.'),
(2017180,69,43,10,29,'Baba yangu ambaye ndiye aliyenipa hao ni mkuu kuliko wote, wale hakuna awezaye kuwatoa mikononi mwake Baba.'),
(2017181,69,43,10,30,'Mimi na Baba, tu mmoja."'),
(2017182,69,43,10,31,'Basi, Wayahudi wakachukua mawe ili wamtupie.'),
(2017183,69,43,10,32,'Yesu akawaambia, "Nimewaonyesheni kazi nyingi kutoka kwa Baba. Ni ipi kati ya hizo inayowafanya mnipige mawe?"'),
(2017184,69,43,10,33,'Wayahudi wakamjibu, "Hatukupigi mawe kwa ajili ya tendo jema, ila kwa sababu ya kukufuru! Maana wajifanya kuwa Mungu hali wewe ni binadamu tu."'),
(2017185,69,43,10,34,'Yesu akawajibu, "Je, haikuandikwa katika Sheria yenu: `Mimi nimesema, ninyi ni miungu?`'),
(2017186,69,43,10,35,'Mungu aliwaita miungu wale waliopewa neno lake; nasi twajua kwamba Maandiko Matakatifu yasema ukweli daima.'),
(2017187,69,43,10,36,'Je, yeye ambaye Baba alimweka wakfu na kumtuma ulimwenguni, mnamwambia: `Unakufuru`, eti kwa sababu nilisema: `Mimi ni Mwana wa Mungu?`'),
(2017188,69,43,10,37,'Kama sifanyi kazi za Baba yangu msiniamini.'),
(2017189,69,43,10,38,'Lakini ikiwa ninazifanya, hata kama hamniamini, walau ziaminini hizo kazi mpate kujua na kutambua kwamba Baba yuko ndani yangu, nami niko ndani yake."'),
(2017190,69,43,10,39,'Wakajaribu tena kumkamata lakini akachopoka mikononi mwao.'),
(2017191,69,43,10,40,'Yesu akaenda tena ng`ambo ya mto Yordani, mahali Yohane alipokuwa akibatiza, akakaa huko.'),
(2017192,69,43,10,41,'Watu wengi walimwendea wakasema, "Yohane hakufanya ishara yoyote. Lakini yale yote Yohane aliyosema juu ya mtu huyu ni kweli kabisa."'),
(2017193,69,43,10,42,'Watu wengi mahali hapo wakamwamini.'),
(2017194,69,43,11,1,'Mtu mmoja aitwaye Lazaro, mwenyeji wa Bethania, alikuwa mgonjwa. (Kijiji cha Bethania kilikuwa mahali walipokaa Maria na Martha, dada yake.'),
(2017195,69,43,11,2,'Maria ndiye yule aliyempaka Bwana marashi na kumpangusa kwa nywele zake. Lazaro, kaka yake, ndiye aliyekuwa mgonjwa.)'),
(2017196,69,43,11,3,'Basi, hao dada wakatuma ujumbe huu kwa Yesu: "Bwana, rafiki yako ni mgonjwa!"'),
(2017197,69,43,11,4,'Yesu aliposikia hivyo akasema, "Ugonjwa huo hautaleta kifo, ila ni kwa ajili ya kumtukuza Mungu; ameugua ili kwa njia hiyo Mwana wa Mungu atukuzwe."'),
(2017198,69,43,11,5,'Yesu aliwapenda Martha, dada yake na Lazaro.'),
(2017199,69,43,11,6,'Alipopata habari kwamba Lazaro ni mgonjwa, Yesu aliendelea kukaa mahali hapo alipokuwa kwa siku mbili zaidi.'),
(2017200,69,43,11,7,'Kisha akawaambia wanafunzi wake, "Twendeni tena Yudea!"'),
(2017201,69,43,11,8,'Wanafunzi wakamwambia, "Mwalimu! Muda mfupi tu umepita tangu Wayahudi walipotaka kukuua kwa mawe, nawe unataka kwenda huko tena?"'),
(2017202,69,43,11,9,'Yesu akajibu, "Je, saa za mchana si kumi na mbili? Basi, mtu akitembea mchana hawezi kujikwaa kwa kuwa anauona mwanga wa ulimwengu huu.'),
(2017203,69,43,11,10,'Lakini mtu akitembea usiku atajikwaa kwa maana mwanga haumo ndani yake."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017204,69,43,11,11,'Yesu alipomaliza kusema maneno hayo, akawaambia, "Rafiki yetu Lazaro amelala, lakini mimi nitakwenda kumwamsha."'),
(2017205,69,43,11,12,'Wanafunzi wake wakamwambia, "Bwana, ikiwa amelala, basi atapona."'),
(2017206,69,43,11,13,'Wao walidhani kwamba alikuwa amesema juu ya kulala usingizi, kumbe alikuwa amesema juu ya kifo cha Lazaro.'),
(2017207,69,43,11,14,'Basi, Yesu akawaambia waziwazi, "Lazaro amekufa;'),
(2017208,69,43,11,15,'Lakini nafurahi kwa ajili yenu kwamba sikuwako huko, ili mpate kuamini. Haya, twendeni kwake."'),
(2017209,69,43,11,16,'Thoma (aitwaye Pacha) akawaambia wanafunzi wenzake, "Twendeni nasi tukafe pamoja naye!"'),
(2017210,69,43,11,17,'Yesu alipofika huko alikuta Lazaro amekwisha kaa kaburini kwa siku nne.'),
(2017211,69,43,11,18,'Kijiji cha Bethania kilikuwa karibu na Yerusalemu umbali upatao kilomita tatu.'),
(2017212,69,43,11,19,'Wayahudi wengi walikuwa wamefika kwa Martha na Maria kuwafariji kwa kifo cha kaka yao.'),
(2017213,69,43,11,20,'Basi, Martha aliposikia kwamba Yesu alikuwa anakuja, akaenda kumlaki; lakini Maria alibaki nyumbani.'),
(2017214,69,43,11,21,'Martha akamwambia Yesu, "Bwana, kama ungalikuwa hapa, kaka yangu hangalikufa!'),
(2017215,69,43,11,22,'Lakini najua kwamba hata sasa chochote utakachomwomba Mungu, atakupa."'),
(2017216,69,43,11,23,'Yesu akamwambia, "Kaka yako atafufuka."'),
(2017217,69,43,11,24,'Martha akamjibu, "Najua kwamba atafufuka wakati wa ufufuo, siku ya mwisho."'),
(2017218,69,43,11,25,'Yesu akamwambia, "Mimi ndimi ufufuo na uzima. Anayeniamini mimi hata kama anakufa, ataishi:'),
(2017219,69,43,11,26,'na kila anayeishi na kuniamini, hatakufa kamwe. Je, waamini hayo?"'),
(2017220,69,43,11,27,'Martha akamwambia, "Ndiyo Bwana! Naamini kwamba wewe ndiwe Kristo, Mwana wa Mungu, yule ajaye ulimwenguni."'),
(2017221,69,43,11,28,'Baada ya kusema hayo, Martha alikwenda kumwita Maria, dada yake, akamwabia faraghani, "Mwalimu yuko hapa, anakuita."'),
(2017222,69,43,11,29,'Naye aliposikia hivyo, akainuka mara, akamwendea Yesu.'),
(2017223,69,43,11,30,'Yesu alikuwa hajaingia kijijini, ila alikuwa bado mahali palepale Martha alipomlaki.'),
(2017224,69,43,11,31,'Basi, Wayahudi waliokuwa nyumbani pamoja na Maria wakimfariji walipomwona ameinuka na kutoka nje ghafla, walimfuata. Walidhani alikuwa anakwenda kaburini kuomboleza.'),
(2017225,69,43,11,32,'Basi, Maria alipofika mahali pale Yesu alipokuwa na kumwona, alipiga magoti, akamwabia, "Bwana, kama ungalikuwa hapa, kaka yangu hangalikufa!"'),
(2017226,69,43,11,33,'Yesu alipomwona analia, na wale Wayahudi waliokuja pamoja naye wanalia pia, alijawa na huzuni na kufadhaika moyoni.'),
(2017227,69,43,11,34,'Kisha akawauliza, "Mlimweka wapi?" Wakamwambia, "Bwana, njoo uone."'),
(2017228,69,43,11,35,'Yesu akalia machozi.'),
(2017229,69,43,11,36,'Basi, Wayahudi wakasema, "Tazameni jinsi alivyompenda!"'),
(2017230,69,43,11,37,'Lakini baadhi yao wakasema, "Je, huyu aliyemfumbua macho yule kipofu, hakuweza kumfanya Lazaro asife?"'),
(2017231,69,43,11,38,'Basi, Yesu akiwa amehuzunika tena moyoni, akafika kaburini. Kaburi lenyewe lilikuwa pango, na lilikuwa limefunikwa kwa jiwe.'),
(2017232,69,43,11,39,'Yesu akasema, "Ondoeni hilo jiwe!" Martha, dada yake huyo aliyekufa, akamwambia, "Bwana, amekwishaanza kunuka; amekaa kaburini siku nne!"'),
(2017233,69,43,11,40,'Yesu akamwambia, "Je, sikukwambia kwamba ukiamini utaona utukufu wa Mungu?"'),
(2017234,69,43,11,41,'Basi, wakaliondoa lile jiwe. Yesu akatazama juu mbinguni, akasema, "Nakushukuru Baba kwa kuwa wewe wanisikiliza.'),
(2017235,69,43,11,42,'Najua kwamba unanisikiliza daima. Lakini nimesema hayo kwa ajili ya watu hawa waliopo hapa ili wapate kuamini kwamba wewe ndiwe uliyenituma."'),
(2017236,69,43,11,43,'Alipokwisha sema hayo, akaita kwa sauti kubwa: "Lazaro! Toka nje!"'),
(2017237,69,43,11,44,'Huyo aliyekuwa amekufa akatoka nje, huku amefungwa sanda miguu na mikono, na uso wake umefunikwa. Yesu akawaambia, "Mfungueni, mkamwache aende zake."'),
(2017238,69,43,11,45,'Basi, Wayahudi wengi waliokuwa wamefika kwa Maria walipoona kitendo hicho alichokifanya Yesu wakamwamini.'),
(2017239,69,43,11,46,'Lakini baadhi yao walikwenda kwa Mafarisayo wakatoa taarifa ya jambo hilo alilofanya Yesu.'),
(2017240,69,43,11,47,'kwa hiyo makuhani wakuu na Mafarisayo wakafanya kikao cha Baraza kuu, wakasema, "Tufanye nini? Mtu huyu anafanya ishara nyingi mno.'),
(2017241,69,43,11,48,'Tukimwacha tu watu wote watamwamini, nao Waroma watakuja kuliharibu Hekalu letu na taifa letu!"'),
(2017242,69,43,11,49,'Hapo, mmoja wao aitwaye Kayafa, ambaye alikuwa Kuhani Mkuu mwaka huo, akawaambia, "Ninyi hamjui kitu!'),
(2017243,69,43,11,50,'Je, hamwoni kwamba ni afadhali kwenu mtu mmoja afe kwa ajili ya watu, kuliko taifa zima liangamizwe?"'),
(2017244,69,43,11,51,'Yeye hakusema hivyo kwa hiari yake mwenyewe, bali kwa vile alikuwa Kuhani Mkuu mwaka huo, alibashiri kwamba Yesu atakufa kwa ajili ya taifa lao;'),
(2017245,69,43,11,52,'na wala si kwa ajili yao tu, bali pia apate kuwaleta pamoja watoto wa Mungu waliotawanyika.'),
(2017246,69,43,11,53,'Basi, tangu siku hiyo viongozi wa Wayahudi walifanya mipango ya kumwua Yesu.'),
(2017247,69,43,11,54,'Kwa hiyo, Yesu hakutembea tena hadharani kati ya Wayahudi, bali alitoka hapo, akaenda mahali karibu na jangwa, katika mji uitwao Efraimu. Akakaa huko pamoja na wanafunzi wake.'),
(2017248,69,43,11,55,'Sikukuu ya Wayahudi ya Pasaka ilikuwa karibu, na watu wengi walikwenda Yerusalemu ili wajitakase kabla ya sikukuu hiyo.'),
(2017249,69,43,11,56,'Basi, wakawa wanamtafuta Yesu; nao walipokusanyika pamoja Hekaluni wakaulizana, "Mwaonaje? Yaonekana kwamba haji kabisa kwenye sikukuu, au sivyo?"'),
(2017250,69,43,11,57,'Makuhani wakuu na Mafarisayo walikuwa wametoa amri kwamba mtu akijua mahali aliko Yesu awaarifu kusudi wamtie nguvuni.'),
(2017251,69,43,12,1,'Siku sita kabla ya sikukuu ya Pasaka, Yesu alifika Bethania alikoishi Lazaro ambaye Yesu alikuwa amemfufua kutoka wafu.'),
(2017252,69,43,12,2,'Huko walimwandalia chakula cha jioni, naye Martha akawa anawatumikia. Lazaro alikuwa mmoja wa wale waliokuwa mezani pamoja na Yesu.'),
(2017253,69,43,12,3,'Basi, Maria alichukua chupa ya marashi ya nardo safi ya thamani kubwa, akampaka Yesu miguu na kuipangusa kwa nywele zake. Nyumba yote ikajaa harufu ya marashi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017254,69,43,12,4,'Basi, Yuda Iskarioti, mmoja wa wale kumi na wawili ambaye ndiye atakayemsaliti Yesu, akasema,'),
(2017255,69,43,12,5,'"Kwa nini marashi hayo hayakuuzwa kwa fedha dinari mia tatu, wakapewa maskini?"'),
(2017256,69,43,12,6,'Alisema hivyo, si kwa kuwa alijali chochote juu ya maskini, bali kwa sababu alikuwa mweka hazina, na kwa kuwa alikuwa mwizi, mara kwa mara aliiba kutoka katika hiyo hazina.'),
(2017257,69,43,12,7,'Lakini Yesu akasema, "Msimsumbue huyu mama! Mwacheni ayaweke kwa ajili ya siku ya mazishi yangu.'),
(2017258,69,43,12,8,'Maskini mtakuwa nao siku zote, lakini hamtakuwa nami siku zote." ic'),
(2017259,69,43,12,9,'Wayahudi wengi walisikia kwamba Yesu alikuwa Bethania. Basi, wakafika huko si tu kwa ajili ya kumwona Yesu, ila pia wapate kumwona Lazaro ambaye Yesu alimfufua kutoka wafu.'),
(2017260,69,43,12,10,'Makuhani wakuu waliamua pia kumwua Lazaro,'),
(2017261,69,43,12,11,'Maana kwa sababu ya Lazaro Wayahudi wengi waliwaasi viongozi wao, wakamwamini Yesu.'),
(2017262,69,43,12,12,'Kesho yake, kundi kubwa la watu waliokuja kwenye sikukuu walisikia kuwa Yesu alikuwa njiani kuja Yerusalemu.'),
(2017263,69,43,12,13,'Basi, wakachukua matawi ya mitende, wakatoka kwenda kumlaki; wakapaaza sauti wakisema: "Hosana! Abarikiwe huyo ajaye kwa jina la Bwana. Abarikiwe mfalme wa Israeli."'),
(2017264,69,43,12,14,'Yesu akampata mwana punda mmoja akapanda juu yake kama yasemavyo Maandiko:'),
(2017265,69,43,12,15,'"Usiogope mji wa Sioni! Tazama, Mfalme wako anakuja, Amepanda mwana punda."'),
(2017266,69,43,12,16,'Wakati huo wanafunzi wake hawakuelewa mambo hayo, lakini Yesu alipokwisha tukuzwa, ndipo walipokumbuka kwamba hayo yalikuwa yameandikwa juu yake, na kwamba watu walikuwa wamemtendea hivyo.'),
(2017267,69,43,12,17,'Kundi la watu wale waliokuwa pamoja naye wakati alipomwita Lazaro kutoka kaburini, akamfufua kutoka wafu, walisema yaliyotukia.'),
(2017268,69,43,12,18,'Kwa hiyo umati huo wa watu ulimlaki, maana wote walisikia kwamba Yesu alikuwa amefanya ishara hiyo.'),
(2017269,69,43,12,19,'Basi, Mafarisayo wakaambiana, "Mnaona? Hatuwezi kufanya chochote! Tazameni, ulimwengu wote unamfuata."'),
(2017270,69,43,12,20,'Kulikuwa na Wagiriki kadhaa miongoni mwa watu waliokuwa wamefika Yerusalemu kuabudu wakati wa sikukuu hiyo.'),
(2017271,69,43,12,21,'Hao walimwendea Filipo, mwenyeji wa Bethsaida katika Galilaya, wakasema, "Mheshimiwa, tunataka kumwona Yesu."'),
(2017272,69,43,12,22,'Filipo akaenda akamwambia Andrea, nao wawili wakaenda kumwambia Yesu.'),
(2017273,69,43,12,23,'Yesu akawaambia, "Saa ya kutukuzwa kwa Mwana wa Mtu imefika!'),
(2017274,69,43,12,24,'Kweli nawaambieni, punje ya ngano hubaki punje tu isipokuwa ikianguka katika udongo na kufa. Kama ikifa, basi huzaa matunda mengi.'),
(2017275,69,43,12,25,'Anayependa maisha yake, atayapoteza; anayeyachukia maisha yake katika ulimwengu huu, atayaweka kwa ajili ya uzima wa milele.'),
(2017276,69,43,12,26,'Anayetaka kunitumikia ni lazima anifuate, hivyo kwamba popote pale nilipo mimi ndipo na mtumishi wangu atakapokuwa. Mtu yeyote anayenitumikia Baba yangu atampa heshima.'),
(2017277,69,43,12,27,'"Sasa roho yangu imefadhaika, na niseme nini? Je, niseme: `Baba, usiruhusu saa hii inifikie`? Lakini ndiyo maana nimekuja--ili nipite katika saa hii.'),
(2017278,69,43,12,28,'Baba, ulitukuze jina lako." Hapo sauti ikasema kutoka mbinguni, "Nimelitukuza, na nitalitukuza tena."'),
(2017279,69,43,12,29,'Umati wa watu waliokuwa wamesimama hapo walisikia sauti hiyo, na baadhi yao walisema, "Malaika ameongea naye!"'),
(2017280,69,43,12,30,'Lakini Yesu akawaambia, "Sauti hiyo haikutokea kwa ajili yangu mimi, ila kwa ajili yenu.'),
(2017281,69,43,12,31,'Sasa ndio wakati wa ulimwengu huu kuhukumiwa; sasa mtawala wa ulimwengu huu atapinduliwa.'),
(2017282,69,43,12,32,'Nami nitakapoinuliwa juu ya nchi nitamvuta kila mmoja kwangu."'),
(2017283,69,43,12,33,'Kwa kusema hivyo alionyesha atakufa kifo gani).'),
(2017284,69,43,12,34,'Basi, umati huo ukamjibu, "Sisi tunaambiwa na Sheria yetu kwamba Kristo atadumu milele. Wawezaje basi, kusema ati Mwana wa Mtu anapaswa kuinuliwa? Huyo Mwana wa Mtu ni nani?"'),
(2017285,69,43,12,35,'Yesu akawaambia, "Mwanga bado uko nanyi kwa muda mfupi. Tembeeni mngali mnao huo mwanga ili giza lisiwapate; maana atembeaye gizani hajui aendako.'),
(2017286,69,43,12,36,'Basi, wakati mnao huo mwanga uaminini ili mpate kuwa watu wa mwanga." Baada ya kusema maneno hayo, Yesu alikwenda zake na kujificha mbali nao.'),
(2017287,69,43,12,37,'Ingawa Yesu alifanya miujiza hii yote mbele yao, wao hawakumwamini.'),
(2017288,69,43,12,38,'Hivyo maneno aliyosema nabii Isaya yakatimia: "Bwana, nani aliyeuamini ujumbe wetu? Na uwezo wa Bwana umedhihirishwa kwa nani?"'),
(2017289,69,43,12,39,'Hivyo hawakuweza kuamini, kwani Isaya tena alisema:'),
(2017290,69,43,12,40,'"Mungu ameyapofusha macho yao, amezipumbaza akili zao; wasione kwa macho yao, wasielewe kwa akili zao; wala wasinigeukie, asema Bwana, ili nipate kuwaponya."'),
(2017291,69,43,12,41,'Isaya alisema maneno haya kwa sababu aliuona utukufu wa Yesu, akasema habari zake.'),
(2017292,69,43,12,42,'Hata hivyo, wengi wa viongozi wa Wayahudi walimwamini Yesu. Lakini kwa sababu ya Mafarisayo, hawakumkiri hadharani kwa kuogopa kwamba watatengwa na sunagogi.'),
(2017293,69,43,12,43,'Walipendelea kusifiwa na watu kuliko kusifiwa na Mungu'),
(2017294,69,43,12,44,'Kisha Yesu akasema kwa sauti kubwa, "Mtu aliyeniamini, haniamini mimi tu, ila anamwamini pia yule aliyenituma.'),
(2017295,69,43,12,45,'Anayeniona mimi anamwona pia yule aliyenituma.'),
(2017296,69,43,12,46,'Mimi ni mwanga, nami nimekuja ulimwenguni ili wote wanaoniamini wasibaki gizani.'),
(2017297,69,43,12,47,'Anayeyasikia maneno yangu lakini hayashiki mimi sitamhukumu; maana sikuja kuhukumu ulimwengu bali kuuokoa.'),
(2017298,69,43,12,48,'Asiyeyashika maneno yangu anaye wa kumhukumu: neno lile nililosema ni hakimu wake siku ya mwisho.'),
(2017299,69,43,12,49,'Mimi sikunena kwa mamlaka yangu mwenyewe, ila Baba aliyenituma ndiye aliyeniamuru niseme nini na niongee nini.'),
(2017300,69,43,12,50,'Nami najua kuwa amri yake huleta uzima wa milele. Basi, mimi nasema tu yale Baba aliyoniagiza niyaseme."'),
(2017301,69,43,13,1,'Ilikuwa kabla ya sikukuu ya Pasaka. Yesu alijua kwamba saa yake ya kuondoka ulimwenguni na kwenda kwa Baba ilikuwa imefika. Alikuwa amewapenda daima watu wake walioko duniani; naam, aliwapenda mpaka mwisho!'),
(2017302,69,43,13,2,'Basi, Yesu na wanafunzi wake walikuwa mezani kwa chakula cha jioni. Ibilisi alikwisha mtia Yuda, mwana wa Simoni Iskarioti, nia ya kumsaliti Yesu.'),
(2017303,69,43,13,3,'Yesu alijua kwamba Baba alikuwa amemkabidhi kila kitu, na kwamba alikuwa ametoka kwa Mungu na anarudi kwa Mungu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017304,69,43,13,4,'Basi, Yesu aliondoka mezani, akaweka kando vazi lake, akachukua kitambaa na kujifunga kiunoni.'),
(2017305,69,43,13,5,'Kisha akatia maji katika bakuli, akaanza kuwaosha wanafunzi wake miguu na kuipangusa kwa kile kitambaa alichojifungia.'),
(2017306,69,43,13,6,'Basi, akamfikia Simoni Petro; naye Petro akasema, "Bwana, wewe utaniosha miguu mimi?"'),
(2017307,69,43,13,7,'Yesu akamjibu, "Huelewi sasa ninachofanya lakini utaelewa baadaye."'),
(2017308,69,43,13,8,'Petro akamwambia, "Wewe hutaniosha miguu kamwe!" Yesu akamjibu, "Nisipokuosha hutakuwa na uhusiano nami tena."'),
(2017309,69,43,13,9,'Simoni Petro akamwambia, "Bwana, nioshe, si miguu tu, bali na mikono yangu na kichwa pia."'),
(2017310,69,43,13,10,'Yesu akamwambia, "Aliyekwisha oga hana lazima ya kunawa isipokuwa miguu, maana amekwisha takata mwili wote. Ninyi mmetakata, lakini si nyote."'),
(2017311,69,43,13,11,'Yesu alimjua yule ambaye atamsaliti, ndiyo maana alisema: "Ninyi mmetakata, lakini si nyote.")'),
(2017312,69,43,13,12,'Alipokwisha waosha miguu na kuvaa tena vazi lake, aliketi mezani, akawaambia, "Je, mmeelewa hayo niliyowatendeeni?'),
(2017313,69,43,13,13,'Ninyi mwaniita Mwalimu na Bwana, nanyi mwasema vyema, kwa kuwa ndimi.'),
(2017314,69,43,13,14,'Basi, ikiwa mimi niliye Bwana na Mwalimu, nimewaosha ninyi miguu, nanyi pia mnapaswa kuoshana miguu.'),
(2017315,69,43,13,15,'Nimewapeni mfano, ili nanyi pia mfanye kama nilivyowafanyieni.'),
(2017316,69,43,13,16,'Kweli nawaambieni, mtumishi si mkuu zaidi kuliko bwana wake, wala mtume si mkuu zaidi kuliko yule aliyemtuma.'),
(2017317,69,43,13,17,'Basi, ikiwa mwayajua hayo, mtakuwa na heri mkiyatekeleza.'),
(2017318,69,43,13,18,'"Haya nisemayo hayawahusu ninyi nyote. Mimi nawajua wale niliowachagua. Lakini lazima yatimie Maandiko Matakatifu yasemayo: `Yule aliyeshiriki chakula changu amegeuka kunishambulia.`'),
(2017319,69,43,13,19,'Mimi nimewaambieni mambo haya sasa kabla hayajatokea, ili yatakapotokea mpate kuamini kuwa mimi ndimi.'),
(2017320,69,43,13,20,'Kweli nawaambieni anayempokea yule ninayemtuma anaponipokea mimi; na anayenipokea mimi, anampokea yule aliyenituma."'),
(2017321,69,43,13,21,'Alipokwisha sema hayo, Yesu alifadhaika sana rohoni, akasema wazi, "Kweli nawaambieni, mmoja wenu atanisaliti!"'),
(2017322,69,43,13,22,'Wanafunzi wakatazama wasiweze kabisa kujua anasema nani.'),
(2017323,69,43,13,23,'Mmoja wa wanafunzi, ambaye Yesu alikuwa anampenda sana, alikuwa ameketi karibu na Yesu.'),
(2017324,69,43,13,24,'Basi, Simoni Petro akamwashiria na kusema: "Mwulize anasema juu ya nani."'),
(2017325,69,43,13,25,'Mwanafunzi huyo akasogea karibu zaidi na Yesu, akamwuliza, "Bwana, ni nani?"'),
(2017326,69,43,13,26,'Yesu akajibu, "Yule nitakayempa kipande cha mkate nilichochovya katika sahani, ndiye." Basi, akatwaa kipande cha mkate, akakichovya katika sahani, akampa Yuda, mwana wa Simoni Iskarioti.'),
(2017327,69,43,13,27,'Yuda alipokwisha pokea kipande hicho, Shetani akamwingia. Basi Yesu akamwambia, "Unachotaka kufanya, kifanye haraka!"'),
(2017328,69,43,13,28,'Lakini hakuna hata mmoja wa wale waliokaa pale mezani aliyefahamu kwa nini alikuwa amemwambia hivyo.'),
(2017329,69,43,13,29,'Kwa kuwa Yuda alikuwa na wajibu wa kuutunza mfuko wa fedha, baadhi yao walidhani kwamba Yesu alikuwa amemwambia anunue vilivyohitajiwa kwa sikukuu, au kwamba alikuwa amemwambia akatoe chochote kwa maskini.'),
(2017330,69,43,13,30,'Basi, Yuda alipokwisha twaa kile kipande cha mkate, akatoka nje mara. Na ilikuwa usiku.'),
(2017331,69,43,13,31,'Baada ya Yuda kuondoka, Yesu akasema, "Sasa Mwana wa Mtu ametukuzwa, naye Mungu ametukuzwa ndani yake.'),
(2017332,69,43,13,32,'Na kama utukufu wa Mungu umefunuliwa ndani ya Mwana, basi, naye Mungu ataudhihirisha utukufu wa Mwana ndani yake mwenyewe, na atafanya hivyo mara.'),
(2017333,69,43,13,33,'"Watoto wangu, bado niko nanyi kwa muda mfupi tu. Mtanitafuta, lakini sasa nawaambieni yale niliyowaambia viongozi wa Wayahudi: `Niendako ninyi hamwezi kwenda!`'),
(2017334,69,43,13,34,'Nawapeni amri mpya: pendaneni; pendaneni kama nilivyowapenda ninyi.'),
(2017335,69,43,13,35,'Mkipendana, watu wote watajua kwamba ninyi ni wanafunzi wangu."'),
(2017336,69,43,13,36,'Simoni Petro akamwuliza, "Bwana, unakwenda wapi?" Yesu akajibu, "Niendako huwezi kunifuata sasa, lakini utanifuata baadaye."'),
(2017337,69,43,13,37,'Petro akamwambia "Bwana, kwa nini siwezi kukufuata sasa? Niko tayari kufa kwa ajili yako!"'),
(2017338,69,43,13,38,'Yesu akajibu, "Je, uko tayari kweli kufa kwa ajili yangu? Kweli nakwambia, kabla jogoo hajawika utanikana mara tatu!"'),
(2017339,69,43,14,1,'Yesu aliwaambia, "Msifadhaike mioyoni mwenu. Mwaminini Mungu, niaminini na mimi pia.'),
(2017340,69,43,14,2,'Nyumbani mwa Baba yangu mna makao mengi; la sivyo ningalikwisha waambieni. Sasa nakwenda kuwatayarishieni nafasi.'),
(2017341,69,43,14,3,'Na nikienda na kuwatayarishieni nafasi, nitarudi na kuwachukueni kwangu, ili nanyi muwe pale nilipo mimi.'),
(2017342,69,43,14,4,'Mnajua njia ya kwenda huko ninakokwenda."'),
(2017343,69,43,14,5,'Thoma akamwuliza, "Bwana, hatujui unakokwenda, tutawezaje basi, kuijua hiyo njia?"'),
(2017344,69,43,14,6,'Yesu akamjibu, "Mimi ni njia, na ukweli na uzima. Hakuna awezaye kwenda kwa Baba ila kwa kupitia kwangu.'),
(2017345,69,43,14,7,'Ikiwa mnanijua mimi mnamjua na Baba yangu pia. Na tangu sasa, mnamjua, tena mmekwisha mwona."'),
(2017346,69,43,14,8,'Filipo akamwambia, "Bwana, tuonyeshe Baba, nasi tutatosheka."'),
(2017347,69,43,14,9,'Yesu akamwambia, "Filipo, nimekaa nanyi muda wote huu, nawe hujanijua? Aliyekwisha niona mimi amemwona Baba. Unawezaje basi, kusema: `Tuonyeshe Baba?`'),
(2017348,69,43,14,10,'Je, huamini kwamba mimi niko ndani ya Baba, naye Baba yuko ndani yangu? Maneno ninayowaambieni nyote siyasemi kwa mamlaka yangu; Baba aliye ndani yangu anafanya kazi yake.'),
(2017349,69,43,14,11,'Mnapaswa kuniamini ninaposema kwamba mimi niko ndani ya Baba naye Baba yuko ndani yangu. Ama sivyo, aminini kwa sababu ya mambo ninayofanya.'),
(2017350,69,43,14,12,'Kweli nawaambieni, anayeniamini atafanya mambo ninayofanya mimi; naam, atafanya hata makuu zaidi, maana nakwenda kwa Baba.'),
(2017351,69,43,14,13,'Na chochote mtakachoomba kwa jina langu nitafanya, ili Baba atukuzwe ndani ya Mwana.'),
(2017352,69,43,14,14,'Mkiniomba chochote kwa jina langu, nitawafanyieni.'),
(2017353,69,43,14,15,'"Mkinipenda mtazishika amri zangu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017354,69,43,14,16,'Nami nitamwomba Baba naye atawapeni Msaidizi mwingine, atakayekaa nanyi milele.'),
(2017355,69,43,14,17,'Yeye ni Roho wa kweli. Ulimwengu hauwezi kumpokea kwa sababu hauwezi kumwona wala kumjua. Lakini ninyi mnamjua kwa sababu anabaki nanyi na yu ndani yenu.'),
(2017356,69,43,14,18,'"Sitawaacha ninyi yatima; nitakuja tena kwenu.'),
(2017357,69,43,14,19,'Bado kidogo nao ulimwengu hautaniona tena, lakini ninyi mtaniona; na kwa kuwa mimi ni hai, nanyi pia mtakuwa hai.'),
(2017358,69,43,14,20,'Siku ile itakapofika mtajua kwamba mimi niko ndani ya Baba, nanyi mko ndani yangu, nami ndani yenu.'),
(2017359,69,43,14,21,'Azipokeaye amri zangu na kuzishika, yeye ndiye anipendaye. Naye anipendaye mimi atapendwa na Baba yangu, nami nitampenda na kujidhihirisha kwake."'),
(2017360,69,43,14,22,'Yuda (si yule Iskarioti) akamwambia, "Bwana, itawezekanaje wewe kujidhihirisha kwetu na si kwa ulimwengu?"'),
(2017361,69,43,14,23,'Yesu akamjibu, "Mtu akinipenda atashika neno langu, na Baba yangu atampenda, nasi tutakuja kwake na kukaa naye.'),
(2017362,69,43,14,24,'Asiyenipenda hashiki maneno yangu. Na neno mlilosikia si langu, bali ni lake Baba aliyenituma.'),
(2017363,69,43,14,25,'"Nimewaambieni mambo haya nikiwa bado pamoja nanyi'),
(2017364,69,43,14,26,'lakini Msaidizi, Roho Mtakatifu, ambaye Baba atamtuma kwa jina langu, atawafundisheni kila kitu na kuwakumbusheni yote niliyowaambieni.'),
(2017365,69,43,14,27,'"Nawaachieni amani; nawapeni amani yangu. Siwapi ninyi kama vile ulimwengu ufanyavyo. Msiwe na wasiwasi, wala msifadhaike.'),
(2017366,69,43,14,28,'Mlikwisha sikia nikiwaambieni: `Ninakwenda zangu, kisha nitarudi tena kwenu.` Kama mngalinipenda mngalifurahi kwa sababu ninakwenda kwa Baba, maana yeye ni mkuu kuliko mimi.'),
(2017367,69,43,14,29,'Nimewaambieni haya sasa kabla hayajatokea, ili yatakapotokea mpate kuamini.'),
(2017368,69,43,14,30,'Sitasema nanyi tena mambo mengi, maana mtawala wa ulimwengu huu anakuja. Kwangu mimi hawezi kitu;'),
(2017369,69,43,14,31,'lakini ulimwengu unapaswa kujua kwamba nampenda Baba, na ndiyo maana nafanya kila kitu kama Baba alivyoniamuru. Simameni, tutoke hapa!"'),
(2017370,69,43,15,1,'"Mimi ni mzabibu wa kweli, na Baba yangu ndiye mkulima.'),
(2017371,69,43,15,2,'Yeye huliondoa ndani yangu kila tawi lisilozaa matunda, na kila tawi lizaalo hulisafisha lipate kuzaa zaidi.'),
(2017372,69,43,15,3,'Ninyi mmekwisha kuwa safi kwa sababu ya ule ujumbe niliowaambieni.'),
(2017373,69,43,15,4,'Kaeni ndani yangu, nami nikae ndani yenu. Tawi haliwezi peke yake kuzaa matunda lisipokaa katika mzabibu hali kadhalika nanyi hamwezi kuzaa matunda msipokaa ndani yangu. ic'),
(2017374,69,43,15,5,'"Mimi ni mzabibu, nanyi ni matawi yake. Akaaye ndani yangu, nami ndani yake, huyo atazaa matunda mengi, maana bila mimi hamwezi kufanya chochote.'),
(2017375,69,43,15,6,'Mtu yeyote asipokaa ndani yangu hutupwa nje kama tawi litupwalo nje hata likakauka. Watu huliokota tawi la namna hiyo na kulitupa motoni liungue.'),
(2017376,69,43,15,7,'Mkikaa ndani yangu na maneno yangu yakikaa ndani yenu, basi, ombeni chochote mtakacho nanyi mtapewa.'),
(2017377,69,43,15,8,'Baba yangu hutukuzwa kama mkizaa matunda mengi na kuwa wanafunzi wangu.'),
(2017378,69,43,15,9,'Mimi nimewapenda ninyi kama vile Baba alivyonipenda mimi. Kaeni katika pendo langu.'),
(2017379,69,43,15,10,'Mkizishika amri zangu mtakaa katika pendo langu, kama vile nami nilivyozishika amri za Baba yangu na kukaa katika pendo lake.'),
(2017380,69,43,15,11,'Nimewaambieni mambo haya ili furaha yangu ikae ndani yenu, na furaha yenu ikamilike.'),
(2017381,69,43,15,12,'Hii ndiyo amri yangu: pendaneni; pendaneni kama nilivyowapenda ninyi.'),
(2017382,69,43,15,13,'Hakuna upendo mkuu zaidi kuliko upendo wa mtu atoaye uhai wake kwa ajili ya rafiki zake.'),
(2017383,69,43,15,14,'Ninyi ni rafiki zangu mkifanya ninayowaamuru.'),
(2017384,69,43,15,15,'Ninyi siwaiti tena watumishi, maana mtumishi hajui anachofanya bwana wake. Lakini mimi nimewaita ninyi rafiki, kwa sababu nimewajulisha yote ambayo nimeyasikia kutoka kwa Baba yangu.'),
(2017385,69,43,15,16,'Ninyi hamkunichagua mimi; mimi niliwachagueni na kuwatuma mwende mkazae matunda, matunda yadumuyo, naye Baba apate kuwapa ninyi chochote mumwombacho kwa jina langu.'),
(2017386,69,43,15,17,'Basi, amri yangu kwenu ndiyo hii: pendaneni.'),
(2017387,69,43,15,18,'"Kama ulimwengu ukiwachukia ninyi, kumbukeni kwamba umenichukia mimi kabla haujawachukia ninyi.'),
(2017388,69,43,15,19,'Kama mngalikuwa watu wa ulimwengu, ulimwengu ungaliwapenda ninyi kama watu wake. Lakini kwa vile ninyi si wa ulimwengu, ila mimi nimewachagueni kutoka ulimwenguni, kwa sababu hiyo ulimwengu unawachukieni.'),
(2017389,69,43,15,20,'Kumbukeni niliyowaambieni: mtumishi si mkuu zaidi kuliko bwana wake. Ikiwa wamenitesa mimi, watawatesa na ninyi pia; kama wameshika neno langu, watalishika na lenu pia.'),
(2017390,69,43,15,21,'Lakini hayo yote watawatendeeni ninyi kwa sababu ya jina langu, kwani hawamjui yeye aliyenituma.'),
(2017391,69,43,15,22,'Kama nisingalikuja na kusema nao wasingalikuwa na hatia; lakini sasa hawawezi kujitetea kwamba hawana dhambi.'),
(2017392,69,43,15,23,'Anayenichukia mimi, anamchukia na Baba yangu pia.'),
(2017393,69,43,15,24,'Kama nisingalifanya kwao mambo ambayo hakuna mtu mwingine amekwisha yafanya wasingalikuwa na hatia; lakini sasa wameona niliyoyafanya wakinichukia mimi, wakamchukia na Baba yangu pia.'),
(2017394,69,43,15,25,'Na hivi ni lazima yatimie yale yaliyoandikwa katika Sheria yao: `Wamenichukia bure!`'),
(2017395,69,43,15,26,'"Atakapokuja huyo Msaidizi nitakayemtuma kwenu kutoka kwa Baba, huyo Roho wa kweli atokaye kwa Baba, yeye atanishuhudia mimi.'),
(2017396,69,43,15,27,'Nanyi pia mtanishuhudia kwa kuwa mmekuwa nami tangu mwanzo.'),
(2017397,69,43,16,1,'"Nimewaambieni hayo kusudi msiiache imani yenu.'),
(2017398,69,43,16,2,'Watu watawatenga ninyi na masunagogi yao. Tena, wakati unakuja ambapo kila atakayewaua ninyi atadhani anamhudumia Mungu.'),
(2017399,69,43,16,3,'Watawatendeeni mambo hayo kwa sababu hawamjui Baba, wala hawanijui mimi.'),
(2017400,69,43,16,4,'Basi, nimewaambieni mambo haya ili saa yake itakapofika mkumbuke kwamba niliwaambieni. "Sikuwaambieni mambo haya tangu mwanzo kwa sababu nilikuwa pamoja nanyi.'),
(2017401,69,43,16,5,'Lakini sasa namwendea yule aliyenituma; na hakuna hata mmoja wenu anayeniuliza: `Unakwenda wapi?`'),
(2017402,69,43,16,6,'Kwa kuwa nimewaambieni mambo hayo mmejaa huzuni mioyoni mwenu.'),
(2017403,69,43,16,7,'Lakini, nawaambieni ukweli: afadhali kwenu mimi niende zangu, maana nisipokwenda Msaidizi hatakuja kwenu. Lakini nikienda, basi, nitamtuma kwenu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017404,69,43,16,8,'Naye atakapokuja atawathibitishia walimwengu kwamba wamekosea kuhusu dhambi, uadilifu na hukumu ya Mungu.'),
(2017405,69,43,16,9,'Wamekosea kuhusu dhambi kwa sababu hawaniamini;'),
(2017406,69,43,16,10,'kuhusu uadilifu, kwa sababu naenda zangu kwa Baba, nanyi hamtaniona tena;'),
(2017407,69,43,16,11,'kuhusu hukumu kwa sababu mkuu wa ulimwengu huu amekwisha hukumiwa.'),
(2017408,69,43,16,12,'"Ninayo bado mengi ya kuwaambieni, ila kwa sasa hamwezi kuyastahimili.'),
(2017409,69,43,16,13,'Lakini atakapokuja huyo Roho wa kweli atawaongoza kwenye ukweli wote; maana hatasema kwa mamlaka yake mwenyewe, bali atawaambieni yote atakayosikia, na atasema mambo yatakayokuwa yanakuja.'),
(2017410,69,43,16,14,'Yeye atanitukuza mimi kwa kuwa atawaambieni yale atakayopata kutoka kwangu.'),
(2017411,69,43,16,15,'Vyote alivyo navyo Baba ni vyangu; ndiyo maana nimesema kwamba huyo Roho Mtakatifu atawaambieni yale atakayopata kutoka kwangu.'),
(2017412,69,43,16,16,'"Bado kitambo kidogo nanyi hamtaniona; na baada ya kitambo kidogo tena mtaniona!"'),
(2017413,69,43,16,17,'Hapo baadhi ya wanafunzi wake wakaulizana, "Ana maana gani anapotwambia: `Bado kitambo kidogo nanyi hamtaniona; na baada ya kitambo kidogo tena mtaniona?` Tena anasema: `Kwa kuwa ninakwenda kwa Baba!"`'),
(2017414,69,43,16,18,'Basi, wakawa wanaulizana, "Ana maana gani anaposema: `Bado kitambo kidogo?` Hatuelewi anaongelea nini."'),
(2017415,69,43,16,19,'Yesu alijua kwamba walitaka kumwuliza, basi akawaambia, "Je, mnaulizana juu ya yale niliyosema: `Bado kitambo kidogo nanyi hamtaniona; na baada ya kitambo kidogo tena mtaniona?`'),
(2017416,69,43,16,20,'Nawaambieni kweli, ninyi mtalia na kuomboleza, lakini ulimwengu utafurahi: mtaona huzuni lakini huzuni yenu itageuka kuwa furaha.'),
(2017417,69,43,16,21,'Wakati mama anapojifungua huona huzuni kwa sababu saa ya maumivu imefika; lakini akisha jifungua hayakumbuki tena maumivu hayo kwa sababu ya furaha kwamba mtu amezaliwa duniani.'),
(2017418,69,43,16,22,'Ninyi pia mna huzuni sasa; lakini nitawajieni tena, nanyi mtajaa furaha mioyoni mwenu, na furaha hiyo hakuna mtu atakayeiondoa kwenu.'),
(2017419,69,43,16,23,'Siku hiyo hamtaniomba chochote. Kweli nawaambieni, chochote mtakachomwomba Baba kwa jina langu, atawapeni.'),
(2017420,69,43,16,24,'Mpaka sasa hamjaomba chochote kwa jina langu. Ombeni nanyi mtapata ili furaha yenu ikamilike.'),
(2017421,69,43,16,25,'"Nimewaambieni mambo hayo kwa mafumbo. Lakini wakati utakuja ambapo sitasema tena nanyi kwa mafumbo, bali nitawaambieni waziwazi juu ya Baba.'),
(2017422,69,43,16,26,'Siku hiyo mtaomba kwa jina langu, na siwaambii kwamba nitamwomba Baba kwa niaba yenu;'),
(2017423,69,43,16,27,'maana yeye mwenyewe anawapenda ninyi, kwa sababu ninyi mmenipenda mimi na mmeamini kwamba nimetoka kwa Mungu.'),
(2017424,69,43,16,28,'Mimi nilitoka kwa Baba, nikaja ulimwenguni; na sasa nauacha ulimwengu na kurudi kwa Baba."'),
(2017425,69,43,16,29,'Basi, wanafunzi wake wakamwambia, "Ahaa! Sasa unasema waziwazi kabisa bila kutumia mafumbo.'),
(2017426,69,43,16,30,'Sasa tunajua kwamba wewe unajua kila kitu, na huna haja ya kuulizwa maswali na mtu yeyote; kwa hiyo tunaamini kwamba umetoka kwa Mungu."'),
(2017427,69,43,16,31,'Yesu akawajibu, "Je, mnaamini sasa?'),
(2017428,69,43,16,32,'Wakati unakuja, tena umekwisha fika, ambapo ninyi nyote mtatawanyika kila mtu kwake, nami nitaachwa peke yangu. Kumbe, lakini mimi siko peke yangu, maana Baba yu pamoja nami.'),
(2017429,69,43,16,33,'Nimewaambieni mambo haya ili mpate kuwa na amani katika kuungana nami. Ulimwenguni mtapata masumbuko; lakini jipeni moyo! Mimi nimeushinda ulimwengu!"'),
(2017430,69,43,17,1,'Yesu alipokwisha sema hayo, alitazama juu mbinguni, akasema, "Baba, saa imefika! Mtukuze Mwanao ili naye Mwana apate kukutukuza.'),
(2017431,69,43,17,2,'Maana ulimpa Mwanao mamlaka juu ya watu wote ili awape uzima wa milele wote hao uliompa.'),
(2017432,69,43,17,3,'Na uzima wa milele ndio huu: kukujua wewe uliye peke yako Mungu wa kweli, na kumjua Yesu Kristo uliyemtuma.'),
(2017433,69,43,17,4,'Mimi nimekutukuza hapa duniani; nimeikamilisha ile kazi uliyonipa nifanye.'),
(2017434,69,43,17,5,'Sasa, Baba, nitukuze mbele yako kwa ule utukufu niliokuwa nao kabla ya kuumbwa ulimwengu.'),
(2017435,69,43,17,6,'"Nimekufanya ujulikane kwa watu wale ulionipa kutoka duniani. Walikuwa watu wako, nawe ukanipa wawe wangu; nao wamelishika neno lako.'),
(2017436,69,43,17,7,'Sasa wanajua kwamba kila ulichonipa kimetoka kwako.'),
(2017437,69,43,17,8,'Mimi nimewapa ule ujumbe ulionipa nao wameupokea; wanajua kwamba kweli nimetoka kwako, na wanaamini kwamba wewe ulinituma.'),
(2017438,69,43,17,9,'"Nawaombea hao; siuombei ulimwengu, ila nawaombea hao ulionipa, maana ni wako.'),
(2017439,69,43,17,10,'Yote niliyo nayo ni yako, na yako ni yangu; na utukufu wangu umeonekana ndani yao.'),
(2017440,69,43,17,11,'Na sasa naja kwako; simo tena ulimwenguni, lakini wao wamo ulimwenguni. Baba Mtakatifu! Kwa nguvu ya jina lako ulilonipa, tafadhali uwaweke salama ili wawe kitu kimoja kama sisi tulivyo mmoja.'),
(2017441,69,43,17,12,'Nilipokuwa nao, mimi niliwaweka salama kwa nguvu ya jina lako ulilonipa. Mimi nimewalinda, wala hakuna hata mmoja wao aliyepotea, isipokuwa yule aliyelazimika kupotea ili Maandiko Matakatifu yapate kutimia.'),
(2017442,69,43,17,13,'Basi, sasa naja kwako, na nimesema mambo haya ulimwenguni, ili waweze kushiriki kikamilifu furaha yangu.'),
(2017443,69,43,17,14,'Mimi nimewapa neno lako, nao ulimwengu ukawachukia, kwa sababu wao si wa ulimwengu kama vile nami nisivyo wa ulimwengu.'),
(2017444,69,43,17,15,'Siombi uwatoe ulimwenguni, bali naomba uwakinge na yule Mwovu.'),
(2017445,69,43,17,16,'Wao si wa ulimwengu, kama vile nami nisivyo wa ulimwengu.'),
(2017446,69,43,17,17,'Waweke wakfu kwa ukweli; neno lako ni ukweli.'),
(2017447,69,43,17,18,'Kama vile ulivyonituma ulimwenguni, nami pia nimewatuma wao ulimwenguni;'),
(2017448,69,43,17,19,'na kwa ajili yao mimi mwenyewe najiweka wakfu ili nao pia wafanywe wakfu katika ukweli.'),
(2017449,69,43,17,20,'"Siwaombei hao tu, bali nawaombea pia wote watakaoamini kutokana na ujumbe wao.'),
(2017450,69,43,17,21,'Naomba ili wote wawe kitu kimoja. Baba! Naomba wawe ndani yetu kama vile wewe ulivyo ndani yangu nami ndani yako. Naomba wawe kitu kimoja kusudi ulimwengu upate kuamini kwamba wewe ulinituma.'),
(2017451,69,43,17,22,'Mimi nimewapa utukufu uleule ulionipa mimi, ili wawe kitu kimoja kama nasi tulivyo mmoja;'),
(2017452,69,43,17,23,'mimi niwe ndani yao, nawe uwe ndani yangu; naomba wakamilishwe na kuwa kitu kimoja, ili ulimwengu upate kujua kwamba wewe ulinituma, na kwamba unawapenda wao kama unavyonipenda mimi.'),
(2017453,69,43,17,24,'"Baba! Nataka wao ulionipa wawe pamoja nami pale nilipo, ili wauone utukufu wangu ulionipa; kwa kuwa ulinipenda kabla ya kuumbwa ulimwengu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017454,69,43,17,25,'Baba Mwema! Ulimwengu haukujui, lakini mimi nakujua. Hawa nao wanajua kwamba wewe ulinituma.'),
(2017455,69,43,17,26,'Nimekufanya ujulikane kwao na nitaendelea kufanya hivyo, ili upendo ulio nao kwangu uwe ndani yao, nami niwe ndani yao."'),
(2017456,69,43,18,1,'Yesu alipokwisha sema hayo, alikwenda ng`ambo ya kijito Kedroni, pamoja na wanafunzi wake. Mahali hapo palikuwa na bustani, naye Yesu akaingia humo pamoja na wanafunzi wake.'),
(2017457,69,43,18,2,'Yuda, aliyemsaliti Yesu, alipajua mahali hapo kwani mara nyingi Yesu alikutana na wanafunzi wake huko.'),
(2017458,69,43,18,3,'Basi, Yuda alichukua kikosi cha askari na walinzi kutoka kwa makuhani wakuu na Mafarisayo, akaja nao bustanini wakiwa na taa, mienge na silaha.'),
(2017459,69,43,18,4,'Yesu, hali akijua yote yatakayompata, akatokea, akawauliza, "Mnamtafuta nani?"'),
(2017460,69,43,18,5,'Nao wakamjibu, "Yesu wa Nazareti!" Yesu akawaambia, "Mimi ndiye." Msaliti Yuda alikuwa amesimama hapo pamoja nao.'),
(2017461,69,43,18,6,'Basi, Yesu alipowaambia: "Mimi ndiye", wakarudi nyuma, wakaanguka chini.'),
(2017462,69,43,18,7,'Yesu akawauliza tena, "Mnamtafuta nani?" Wakamjibu, "Yesu wa Nazareti!"'),
(2017463,69,43,18,8,'Yesu akawaambia, "Nimekwisha waambieni kwamba mimi ndiye. Basi, kama mnanitafuta mimi, waacheni hawa waende zao."'),
(2017464,69,43,18,9,'Alisema hayo ili yapate kutimia yale aliyosema: "Wale ulionipa sikumpoteza hata mmoja.")'),
(2017465,69,43,18,10,'Simoni Petro alikuwa na upanga; basi, akauchomoa, akamkata sikio la kulia mtumishi wa Kuhani Mkuu. Mtumishi huyo aliitwa Malko.'),
(2017466,69,43,18,11,'Basi, Yesu akamwambia Petro, "Rudisha upanga wako alani. Je, nisinywe kikombe alichonipa Baba?"'),
(2017467,69,43,18,12,'Kile kikosi cha askari, mkuu wake na walinzi wa Wayahudi walimkamata Yesu, wakamfunga'),
(2017468,69,43,18,13,'na kumpeleka kwanza kwa Anasi; Anasi alikuwa baba mkwe wa Kayafa ambaye alikuwa Kuhani Mkuu mwaka huo.'),
(2017469,69,43,18,14,'Huyo Kayafa ndiye aliyekuwa amewashauri Wayahudi kwamba ni afadhali mtu mmoja afe kwa ajili ya taifa.'),
(2017470,69,43,18,15,'Simoni Petro pamoja na mwanafunzi mwingine walimfuata Yesu. Huyo mwanafunzi mwingine alikuwa anajulikana kwa Kuhani Mkuu, hivyo aliingia pamoja na Yesu ndani ya ukumbi wa Kuhani Mkuu.'),
(2017471,69,43,18,16,'Lakini Petro alikuwa amesimama nje, karibu na mlango. Basi, huyo mwanafunzi mwingine aliyekuwa anajulikana kwa Kuhani Mkuu alitoka nje akasema na mjakazi, mngoja mlango, akamwingiza Petro ndani.'),
(2017472,69,43,18,17,'Huyo msichana mngoja mlango akamwuliza Petro, "Je, nawe pia ni mmoja wa wanafunzi wa mtu huyu?" Petro akamwambia, "Si mimi!"'),
(2017473,69,43,18,18,'Watumishi na walinzi walikuwa wamewasha moto kwa sababu kulikuwa na baridi, wakawa wanaota moto. Naye Petro alikuwa amesimama pamoja nao akiota moto.'),
(2017474,69,43,18,19,'Basi, Kuhani akamwuliza Yesu juu ya wanafunzi wake na mafundisho yake.'),
(2017475,69,43,18,20,'Yesu akamjibu, "Nimesema na kila mtu daima hadharani. Kila mara nimefundisha katika masunagogi na Hekaluni, mahali wakutanikiapo Wayahudi wote; na wala sijasema chochote kwa siri.'),
(2017476,69,43,18,21,'Kwa nini waniuliza mimi? Waulize wale waliosikia nini niliwaambia. Wao wanajua nilivyosema."'),
(2017477,69,43,18,22,'Alipokwisha sema hayo mlinzi mmoja aliyekuwa amesimama hapo akampiga kofi akisema, "Je, ndivyo unavyomjibu Kuhani Mkuu?"'),
(2017478,69,43,18,23,'Yesu akamjibu, "Kama nimesema vibaya, onyesha huo ubaya; lakini ikiwa nimesema vema, mbona wanipiga?"'),
(2017479,69,43,18,24,'Basi, Anasi akampeleka Yesu akiwa amefungwa, kwa Kuhani Mkuu Kayafa.'),
(2017480,69,43,18,25,'Petro alikuwa hapo akiota moto. Basi, wakamwuliza, "Je, nawe pia si mmoja wa wanafunzi wake?" Yeye akakana na kusema, "Si mimi!"'),
(2017481,69,43,18,26,'Mmoja wa watumishi wa Kuhani Mkuu, jamaa wa yule aliyekatwa sikio na Petro, akamwuliza, "Je, mimi sikukuona wewe bustanini pamoja naye?"'),
(2017482,69,43,18,27,'Petro akakana tena; mara jogoo akawika.'),
(2017483,69,43,18,28,'Basi, walimchukua Yesu kutoka kwa Kayafa, wakampeleka ikulu. Ilikuwa alfajiri, nao ili waweze kula Pasaka, hawakuingia ndani ya ikulu wasije wakatiwa najisi.'),
(2017484,69,43,18,29,'Kwa hiyo, Pilato aliwaendea nje, akasema, "Mna mashtaka gani juu ya mtu huyu?"'),
(2017485,69,43,18,30,'Wakamjibu, "Kama huyu hangalikuwa mwovu hatungalimleta kwako."'),
(2017486,69,43,18,31,'Pilato akawaambia, "Haya, mchukueni ninyi wenyewe, mkamhukumu kufuatana na Sheria yenu." Wayahudi wakamjibu, "Sisi hatuna mamlaka ya kumwua mtu yeyote."'),
(2017487,69,43,18,32,'Ilifanyika hivyo yapate kutimia maneno aliyosema Yesu kuonyesha atakufa kifo gani.)'),
(2017488,69,43,18,33,'Pilato akaingia tena ndani ya ikulu, akamwita Yesu na kumwuliza: "Ati wewe ndiye Mfalme wa Wayahudi?"'),
(2017489,69,43,18,34,'Yesu akamjibu, "Je, hayo ni maneno yako au wengine wamekwambia habari zangu?"'),
(2017490,69,43,18,35,'Pilato akamjibu, "Je, ni Myahudi mimi? Taifa lako na makuhani wamekuleta kwangu. Umefanya nini?"'),
(2017491,69,43,18,36,'Yesu akamjibu, "Ufalme wangu si wa ulimwengu huu. Kama ufalme wangu ungekuwa wa ulimwengu huu watumishi wangu wangenipigania nisitiwe mikononi mwa Wayahudi. Lakini sasa ufalme wangu si wa hapa."'),
(2017492,69,43,18,37,'Hapo Pilato akamwambia, "Basi, wewe ni Mfalme?" Yesu akajibu, "Wewe umesema kwamba mimi ni Mfalme. Mimi nimezaliwa kwa ajili hiyo; na kwa ajili hiyo nimekuja ulimwenguni kuwaambia watu juu ya ukweli. Kila mtu wa ukweli hunisikiliza."'),
(2017493,69,43,18,38,'Pilato akamwambia, "Ukweli ni kitu gani?" Pilato alipokwisha sema hayo, aliwaendea tena Wayahudi nje, akawaambia, "Mimi sioni hatia yoyote kwake.'),
(2017494,69,43,18,39,'Lakini, mnayo desturi kwamba mimi niwafungulie mfungwa mmoja wakati wa Pasaka. Basi, mwataka niwafungulieni Mfalme wa Wayahudi?"'),
(2017495,69,43,18,40,'Hapo wakapiga kelele: "La! Si huyu ila Baraba!" Naye Baraba alikuwa mnyang`anyi.'),
(2017496,69,43,19,1,'Basi, Pilato akaamuru Yesu achukuliwe, apigwe viboko.'),
(2017497,69,43,19,2,'Nao askari wakasokota taji ya miiba, wakamtia kichwani, wakamvika na joho la rangi ya zambarau.'),
(2017498,69,43,19,3,'Wakawa wanakuja mbele yake na kusema: "Shikamoo, Mfalme wa Wayahudi!" Wakampiga makofi.'),
(2017499,69,43,19,4,'Pilato akatoka tena nje, akawaambia, "Tazameni, namleta nje kwenu, mpate kujua kwamba mimi sikuona hatia yoyote kwake."'),
(2017500,69,43,19,5,'Basi, Yesu akatoka nje amevaa taji ya miiba na joho la rangi ya zambarau. Pilato akawaambia, "Tazameni! Mtu mwenyewe ni huyo."'),
(2017501,69,43,19,6,'Makuhani wakuu na walinzi walipomwona wakapaaza sauti: "Msulubishe! Msulubishe!" Pilato akawaambia, "Mchukueni basi, ninyi wenyewe mkamsulubishe, kwa maana mimi sikuona hatia yoyote kwake."'),
(2017502,69,43,19,7,'Wayahudi wakamjibu, "Sisi tunayo Sheria, na kufuatana na Sheria hiyo, ni lazima afe, kwa sababu alijifanya kuwa Mwana wa Mungu."'),
(2017503,69,43,19,8,'Pilato aliposikia maneno hayo akazidi kuogopa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017504,69,43,19,9,'Basi, akaingia tena ndani ya ikulu, akamwuliza Yesu, "Umetoka wapi wewe?" Lakini Yesu hakumjibu neno.'),
(2017505,69,43,19,10,'Hivyo Pilato akamwambia, "Husemi nami? Je, hujui kwamba ninayo mamlaka ya kukufungua na mamlaka ya kukusulubisha?"'),
(2017506,69,43,19,11,'Yesu akamjibu, "Hungekuwa na mamlaka yoyote juu yangu kama hungepewa na Mungu. Kwa sababu hiyo, yule aliyenikabidhi kwako ana dhambi kubwa zaidi."'),
(2017507,69,43,19,12,'Tangu hapo, Pilato akawa anatafuta njia ya kumwachilia, lakini Wayahudi wakapiga kelele: "Ukimwachilia huyu mtu, wewe si rafiki yake Kaisari; kila mtu anayejifanya kuwa Mfalme humpinga Kaisari!"'),
(2017508,69,43,19,13,'Basi, Pilato aliposikia maneno hayo akamleta Yesu nje, akaketi juu ya kiti cha hukumu, mahali paitwapo: "Sakafu ya Mawe" (kwa Kiebrania, Gabatha).'),
(2017509,69,43,19,14,'Ilikuwa yapata saa sita mchana, siku ya maandalio ya Pasaka. Pilato akawaambia Wayahudi, "Tazameni, Mfalme wenu!"'),
(2017510,69,43,19,15,'Wao wakapaaza sauti: "Mwondoe! Mwondoe! Msulubishe!" Makuhani wakuu wakajibu, "Sisi hatuna Mfalme isipokuwa Kaisari!"'),
(2017511,69,43,19,16,'Basi, hapo Pilato akamtia Yesu mikononi mwao ili asulubiwe. Basi, wakamchukua Yesu.'),
(2017512,69,43,19,17,'Naye akatoka akiwa amejichukulia msalaba wake kwenda mahali paitwapo "Fuvu la Kichwa", (kwa Kiebrania Golgotha).'),
(2017513,69,43,19,18,'Hapo ndipo walipomsulubisha, na pamoja naye waliwasulubisha watu wengine wawili; mmoja upande wake wa kulia na mwingine upande wake wa kushoto, naye Yesu katikati.'),
(2017514,69,43,19,19,'Pilato aliandika ilani akaiweka juu ya msalaba. Nayo ilikuwa imeandikwa hivi: "Yesu wa Nazareti, Mfalme wa Wayahudi."'),
(2017515,69,43,19,20,'Wayahudi wengi waliisoma ilani hiyo, maana mahali hapo aliposulubiwa Yesu palikuwa karibu na mji. Tena ilani hiyo ilikuwa imeandikwa kwa Kiebrania, Kilatini, na Kigiriki.'),
(2017516,69,43,19,21,'Basi, makuhani wakuu wakamwambia Pilato, "Usiandike: `Mfalme wa Wayahudi`, ila `Yeye alisema, Mimi ni Mfalme wa Wayahudi."`'),
(2017517,69,43,19,22,'Pilato akajibu, "Niliyoandika, nimeandika!"'),
(2017518,69,43,19,23,'Askari walipokwisha msulubisha Yesu, walizichukua nguo zake, wakazigawa mafungu manne, fungu moja kwa kila askari. Walichukua pia na kanzu yake; kanzu hiyo ilikuwa imefumwa kwa kipande kimoja tu, bila mshono.'),
(2017519,69,43,19,24,'Basi, hao askari wakashauriana: "Tusiipasue, ila tuipigie kura itakuwa ya nani." Jambo hilo lilifanyika ili yatimie Maandiko Matakatifu yasemayo: "Waligawana mavazi yangu, na nguo yangu wakaipigia kura." Basi, ndivyo walivyofanya hao askari. ic'),
(2017520,69,43,19,25,'Karibu na msalaba wake Yesu walikuwa wamesimama mama yake, na dada ya mama yake, Maria mke wa Kleopa, na Maria Magdalene.'),
(2017521,69,43,19,26,'Yesu alipomwona mama yake, na karibu naye amesimama yule mwanafunzi aliyempenda, akamwambia mama yake: "Mama! Tazama, huyo ndiye mwanao."'),
(2017522,69,43,19,27,'Halafu akamwambia yule mwanafunzi: "Tazama, huyo ndiye mama yako." Na tangu saa ile huyo mwanafunzi alimchukua akae nyumbani kwake.'),
(2017523,69,43,19,28,'Yesu alijua kwamba yote yalikuwa yametimia; na, ili Maandiko Matakatifu yapate kutimia, akasema, "Naona kiu."'),
(2017524,69,43,19,29,'Hapo palikuwa na bakuli limejaa siki. Basi, wakachovya sifongo katika hiyo siki, wakaitia juu ya ufito wa husopo, wakamwekea mdomoni.'),
(2017525,69,43,19,30,'Yesu alipokwisha pokea hiyo siki, akasema, "Yametimia!" Kisha akainama kichwa, akatoa roho.'),
(2017526,69,43,19,31,'Ilikuwa Ijumaa, siku ya Maandalio. Kwa hiyo, kusudi miili isikae msalabani siku ya Sabato, maana siku hiyo ya Sabato ilikuwa siku kubwa, Wayahudi walimwomba Pilato miguu ya hao waliosulubiwa ivunjwe na miili yao iondolewe.'),
(2017527,69,43,19,32,'Basi, askari walikwenda, wakaivunja miguu ya yule mtu wa kwanza na yule wa pili ambao walikuwa wamesulubiwa pamoja na Yesu.'),
(2017528,69,43,19,33,'Lakini walipomfikia Yesu waliona kwamba alikwisha kufa, na hivyo hawakumvunja miguu.'),
(2017529,69,43,19,34,'Lakini askari mmoja alimtoboa ubavuni kwa mkuki, na mara ikatoka damu na maji.'),
(2017530,69,43,19,35,'Naye aliyeona tukio hilo ametoa habari zake ili nanyi mpate kuamini. Na hayo aliyosema ni ukweli, tena yeye anajua kwamba anasema ukweli.)'),
(2017531,69,43,19,36,'Jambo hilo lilitendwa ili Maandiko Matakatifu yatimie: "Hapana hata mfupa wake mmoja utakaovunjwa."'),
(2017532,69,43,19,37,'Tena Maandiko mengine yanasema: "Watamtazama yule waliyemtoboa."'),
(2017533,69,43,19,38,'Baada ya hayo, Yosefu, mwenyeji wa Armathaya, alimwomba Pilato ruhusa ya kuuchukua mwili wa Yesu. (Yosefu alikuwa mfuasi wa Yesu, lakini kwa siri, maana aliwaogopa viongozi wa Wayahudi). Basi, Pilato akamruhusu. Hivyo Yosefu alikwenda, akauondoa mwili wa Yesu.'),
(2017534,69,43,19,39,'Naye Nikodemo ambaye hapo awali alikuwa amemwendea Yesu usiku, akaja akiwa amechukua mchanganyiko wa manemane na ubani kiasi cha kilo thelathini.'),
(2017535,69,43,19,40,'Basi, waliutwaa mwili wa Yesu, wakaufunga sanda pamoja na manukato kufuatana na desturi ya Wayahudi katika kuzika.'),
(2017536,69,43,19,41,'Mahali hapo aliposulubiwa Yesu palikuwa na bustani, na katika bustani hiyo kulikuwa na kaburi jipya ambalo hakutiwa bado mtu yeyote ndani yake.'),
(2017537,69,43,19,42,'Basi, kwa sababu ya shughuli za Wayahudi za maandalio ya Sabato, na kwa vile kaburi hilo lilikuwa karibu, wakamweka Yesu humo.'),
(2017538,69,43,20,1,'Alfajiri na mapema Jumapili, kukiwa bado na giza, Maria Magdalene alikwenda kaburini, akaliona lile jiwe limeondolewa mlangoni pa kaburi.'),
(2017539,69,43,20,2,'Basi, akaenda mbio hadi kwa Petro na yule mwanafunzi mwingine ambaye Yesu alimpenda, akawaambia, "Wamemwondoa Bwana kaburini, na wala hatujui walikomweka."'),
(2017540,69,43,20,3,'Petro pamoja na yule mwanafunzi mwingine wakaenda kaburini.'),
(2017541,69,43,20,4,'Wote wawili walikimbia lakini yule mwanafunzi mwingine alikimbia mbio zaidi kuliko Petro, akatangulia kufika kaburini.'),
(2017542,69,43,20,5,'Alipoinama na kuchungulia ndani, aliona sanda, lakini hakuingia ndani.'),
(2017543,69,43,20,6,'Simoni Petro naye akaja akimfuata, akaingia kaburini; humo akaona sanda,'),
(2017544,69,43,20,7,'na kile kitambaa alichofungwa Yesu kichwani. Hicho kitambaa hakikuwekwa pamoja na hiyo sanda, bali kilikuwa kimekunjwa na kuwekwa mahali peke yake.'),
(2017545,69,43,20,8,'Kisha yule mwanafunzi mwingine aliyemtangulia kufika kaburini, akaingia pia ndani, akaona, akaaamini.'),
(2017546,69,43,20,9,'Walikuwa bado hawajaelewa Maandiko Matakatifu yaliyosema kwamba ilikuwa lazima afufuke kutoka wafu).'),
(2017547,69,43,20,10,'Basi, hao wanafunzi wakarudi nyumbani.'),
(2017548,69,43,20,11,'Maria alikuwa amesimama nje ya kaburi, akilia. Huku akiwa bado analia, aliinama na kuchungulia kaburini,'),
(2017549,69,43,20,12,'akawaona malaika wawili waliovaa mavazi meupe, wameketi pale mwili wa Yesu ulipokuwa umelazwa, mmoja kichwani na wa pili miguuni.'),
(2017550,69,43,20,13,'Hao malaika wakamwuliza, "Mama, kwa nini unalia?" Naye akawaambia, "Wamemwondoa Bwana wangu, na wala sijui walikomweka!"'),
(2017551,69,43,20,14,'Baada ya kusema hayo, aligeuka nyuma, akamwona Yesu amesimama hapo, lakini asitambue ya kuwa ni Yesu.'),
(2017552,69,43,20,15,'Yesu akamwuliza, "Mama, kwa nini unalia? Unamtafuta nani?" Maria, akidhani kwamba huyo ni mtunza bustani, akamwambia, "Mheshimiwa, kama ni wewe umemwondoa, niambie ulikomweka, nami nitamchukua."'),
(2017553,69,43,20,16,'Yesu akamwambia, "Maria!" Naye Maria akageuka, akamwambia kwa Kiebrania, "Raboni" (yaani "Mwalimu").');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017554,69,43,20,17,'Yesu akamwambia, "Usinishike; sijakwenda bado juu kwa Baba. Lakini nenda kwa ndugu zangu uwaambie: nakwenda juu kwa Baba yangu na Baba yenu, Mungu wangu na Mungu wenu."'),
(2017555,69,43,20,18,'Hivyo Maria Magdalene akaenda akawapa habari wale wanafunzi kuwa amemwona Bwana, na kwamba alikuwa amemwambia hivyo.'),
(2017556,69,43,20,19,'Ilikuwa jioni ya siku hiyo ya Jumapili. Wanafunzi walikuwa wamekutana pamoja ndani ya nyumba, na milango ilikuwa imefungwa kwa sababu waliwaogopa viongozi wa Wayahudi. Basi, Yesu akaja, akasimama kati yao, akawaambia, "Amani kwenu!"'),
(2017557,69,43,20,20,'Alipokwisha sema hayo, akawaonyesha mikono yake na ubavu wake. Basi, hao wanafunzi wakafurahi mno kumwona Bwana.'),
(2017558,69,43,20,21,'Yesu akawaambia tena, "Amani kwenu! Kama vile Baba alivyonituma mimi, nami nawatuma ninyi."'),
(2017559,69,43,20,22,'Alipokwisha sema hayo, akawapulizia na kuwaambia, "Pokeeni Roho Mtakatifu.'),
(2017560,69,43,20,23,'Mkiwasamehe watu dhambi zao, wamesamehewa; msipowaondolea, hawasamehewi."'),
(2017561,69,43,20,24,'Thoma mmoja wa wale kumi na wawili (aitwaye Pacha), hakuwa pamoja nao wakati Yesu alipokuja.'),
(2017562,69,43,20,25,'Basi, wale wanafunzi wengine wakamwambia, "Tumemwona Bwana." Thoma akawaambia, "Nisipoona mikononi mwake alama za misumari, na kutia kidole changu katika kovu hizo, na kutia mkono wangu ubavuni mwake, sitasadiki."'),
(2017563,69,43,20,26,'Basi, baada ya siku nane hao wanafunzi walikuwa tena pamoja mle ndani, na Thoma alikuwa pamoja nao. Milango ilikuwa imefungwa, lakini Yesu akaja, akasimama kati yao, akasema, "Amani kwenu!"'),
(2017564,69,43,20,27,'Kisha akamwambia Thoma, "Lete kidole chako hapa uitazame mikono yangu; lete mkono wako ukautie ubavuni mwangu. Usiwe na mashaka, ila amini!"'),
(2017565,69,43,20,28,'Thoma akamjibu, "Bwana wangu na Mungu wangu!"'),
(2017566,69,43,20,29,'Yesu akamwambia, "Je, unaamini kwa kuwa umeniona? Heri yao wale ambao hawajaona, lakini wameamini."'),
(2017567,69,43,20,30,'Yesu alifanya mbele ya wanafunzi wake ishara nyingine nyingi ambazo hazikuandikwa katika kitabu hiki.'),
(2017568,69,43,20,31,'Lakini hizi zimeandikwa ili mpate kuamini kwamba Yesu ni Kristo, Mwana wa Mungu; na kwa kuamini mpate kuwa na uzima kwa nguvu ya jina lake.'),
(2017569,69,43,21,1,'Baada ya hayo Yesu aliwatokea tena wanafunzi wake kando ya ziwa Tiberia. Aliwatokea hivi:'),
(2017570,69,43,21,2,'Simoni Petro, Thoma (aitwaye Pacha), na Nathanieli mwenyeji wa Kana Galilaya, wana wawili wa Zebedayo na wanafunzi wake wengine wawili, walikuwa wote pamoja.'),
(2017571,69,43,21,3,'Simoni Petro aliwaambia, "Nakwenda kuvua samaki." Nao wakamwambia, "Nasi tutafuatana nawe." Basi, wakaenda, wakapanda mashua, lakini usiku huo hawakupata chochote.'),
(2017572,69,43,21,4,'Kulipoanza kupambazuka, Yesu alisimama kando ya ziwa, lakini wanafunzi hawakujua kwamba alikuwa yeye.'),
(2017573,69,43,21,5,'Basi, Yesu akawauliza, "Vijana, hamjapata samaki wowote sio?" Wao wakamjibu, "La! Hatujapata kitu."'),
(2017574,69,43,21,6,'Yesu akawaambia, "Tupeni wavu upande wa kulia wa mashua nanyi mtapata samaki." Basi, wakatupa wavu lakini sasa hawakuweza kuuvuta tena kwa wingi wa samaki.'),
(2017575,69,43,21,7,'Hapo yule mwanafunzi aliyependwa na Yesu akamwambia Petro, "Ni Bwana!" Simoni Petro aliposikia ya kuwa ni Bwana, akajifunga vazi lake (maana hakuwa amelivaa), akarukia majini.'),
(2017576,69,43,21,8,'Lakini wale wanafunzi wengine walikuja pwani kwa mashua huku wanauvuta wavu uliojaa samaki; hawakuwa mbali na nchi kavu, ila walikuwa yapata mita mia moja kutoka ukingoni.'),
(2017577,69,43,21,9,'Walipofika nchi kavu waliona moto wa makaa umewashwa na juu yake pamewekwa samaki na mkate.'),
(2017578,69,43,21,10,'Yesu akawaambia, "Leteni hapa baadhi ya samaki mliovua."'),
(2017579,69,43,21,11,'Basi, Simoni Petro akapanda mashuani, akavuta hadi nchi kavu ule wavu uliokuwa umejaa samaki wakubwa mia moja na hamsini na watatu. Na ingawa walikuwa wengi hivyo wavu haukukatika.'),
(2017580,69,43,21,12,'Yesu akawaambia, "Njoni mkafungue kinywa." Hakuna hata mmoja wao aliyethubutu kumwuliza: "Wewe ni nani?" Maana walijua alikuwa Bwana.'),
(2017581,69,43,21,13,'Yesu akaja, akatwaa mkate akawapa; akafanya vivyo hivyo na wale samaki.'),
(2017582,69,43,21,14,'Hii ilikuwa mara ya tatu Yesu kuwatokea wanafunzi wake baada ya kufufuka kutoka wafu.'),
(2017583,69,43,21,15,'Walipokwisha kula, Yesu alimwuliza Simoni Petro, "Simoni, mwana wa Yohane! Je, wanipenda mimi zaidi kuliko hawa?" Naye akajibu, "Naam, Bwana; wajua kwamba mimi nakupenda." Yesu akamwambia, "Tunza wana kondoo wangu."'),
(2017584,69,43,21,16,'Kisha akamwambia mara ya pili, "Simoni mwana wa Yohane! Je, wanipenda?" Petro akamjibu, "Naam, Bwana; wajua kwamba nakupenda." Yesu akamwambia, "Tunza kondoo wangu."'),
(2017585,69,43,21,17,'Akamwuliza mara ya tatu, "Simoni mwana wa Yohane! Je, wanipenda?" Hapo Petro akahuzunika kwa sababu alimwuliza mara ya tatu: "Wanipenda?" akamwambia, "Bwana, wewe wajua yote; wewe wajua kwamba mimi nakupenda." Yesu akamwambia, "Tunza kondoo wangu!'),
(2017586,69,43,21,18,'Kweli nakwambia, ulipokuwa kijana ulizoea kujifunga mshipi na kwenda kokote ulikotaka. Lakini utakapokuwa mzee utanyosha mikono yako, na mtu mwingine atakufunga na kukupeleka usikopenda kwenda."'),
(2017587,69,43,21,19,'(Kwa kusema hivyo, alionyesha jinsi Petro atakavyokufa na kumtukuza Mungu.) Kisha akamwambia, "Nifuate."'),
(2017588,69,43,21,20,'Hapo Petro akageuka, akamwona yule mwanafunzi ambaye Yesu alimpenda, anafuata (Huyu mwanafunzi ndiye yule ambaye wakati wa chakula cha jioni, alikaa karibu sana na Yesu na kumwuliza: "Bwana ni nani atakayekusaliti?")'),
(2017589,69,43,21,21,'Basi, Petro alipomwona huyo akamwuliza Yesu, "Bwana, na huyu je?"'),
(2017590,69,43,21,22,'Yesu akamjibu, "Kama nataka abaki mpaka nitakapokuja, yakuhusu nini? Wewe nifuate mimi."'),
(2017591,69,43,21,23,'Basi, habari hiyo ikaenea miongoni mwa wale ndugu kwamba mwanafunzi huyo hafi. Lakini Yesu hakumwambia kwamba mwanafunzi huyo hafi, ila, "Kama nataka abaki mpaka nitakapokuja, yakuhusu nini?"'),
(2017592,69,43,21,24,'Huyo ndiye yule aliyeshuhudia mambo haya na kuyaandika. Nasi twajua kwamba aliyoyasema ni kweli.'),
(2017593,69,43,21,25,'Kuna mambo mengine mengi aliyofanya Yesu, ambayo kama yangeandikwa yote, moja baada ya lingine, nadhani hata ulimwengu wenyewe usingetosha kuviweka vitabu ambavyo vingeandikwa.'),
(2017594,69,44,1,1,'Ndugu Theofilo, Katika kitabu cha kwanza niliandika juu ya mambo yote Yesu aliyotenda na kufundisha tangu mwanzo wa kazi yake'),
(2017595,69,44,1,2,'mpaka siku ile alipochukuliwa mbinguni. Kabla ya kuchukuliwa mbinguni aliwapa maagizo kwa njia ya Roho Mtakatifu wale mitume aliowachagua.'),
(2017596,69,44,1,3,'Kwa muda wa siku arobaini baada ya kifo chake aliwatokea mara nyingi kwa namna ambazo zilithibitisha kabisa kwamba alikuwa hai. Walimwona, naye aliongea nao juu ya ufalme wa Mungu.'),
(2017597,69,44,1,4,'Wakati walipokutana pamoja aliwaamuru hivi: "Msiondoke Yerusalemu, bali ngojeeni ile zawadi aliyoahidi Baba, zawadi ambayo mlikwisha nisikia nikiongea juu yake.'),
(2017598,69,44,1,5,'Kwani Yohane alibatiza kwa maji, lakini baada ya siku chache, ninyi mtabatizwa kwa Roho Mtakatifu."'),
(2017599,69,44,1,6,'Basi, mitume walipokutana pamoja na Yesu, walimwuliza, "Je Bwana, wakati huu ndipo utakaporudisha ule ufalme kwa Israeli?"'),
(2017600,69,44,1,7,'Lakini Yesu akawaambia, "Nyakati na majira ya mambo hayo viko chini ya mamlaka ya Baba yangu, wala si shauri lenu kujua yatakuwa lini.'),
(2017601,69,44,1,8,'Lakini wakati Roho Mtakatifu atakapowashukieni ninyi, mtajazwa nguvu na mtakuwa mashahidi wangu katika Yerusalemu, katika nchi yote ya Yudea na Samaria, na hata miisho ya dunia."'),
(2017602,69,44,1,9,'Baada ya kusema hayo, wote wakiwa wanamtazama, alichukuliwa mbinguni; wingu likamficha wasimwone tena.'),
(2017603,69,44,1,10,'Walipokuwa bado wanatazama juu angani, akiwa anakwenda zake, mara watu wawili waliokuwa wamevaa nguo nyeupe walisimama karibu nao,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017604,69,44,1,11,'wakasema, "Enyi wananchi wa Galilaya! Mbona mnasimama mkitazama angani? Yesu huyu ambaye amechukuliwa kutoka kwenu kwenda mbinguni atakuja tena namna hiyohiyo mliivyomwona akienda mbinguni."'),
(2017605,69,44,1,12,'Kisha mitume wakarudi Yerusalemu kutoka mlima wa Mizeituni ulioko karibu kilomita moja kutoka mjini.'),
(2017606,69,44,1,13,'Walipofika mjini waliingia katika chumba ghorofani ambamo walikuwa wanakaa; nao walikuwa Petro, Yohane, Yakobo, Andrea, Filipo na Thoma, Bartholomayo na Mathayo, Yakobo mwana wa Alfayo, Simoni Zelote na Yuda mwana wa Yakobo.'),
(2017607,69,44,1,14,'Hawa wote walikusanyika pamoja kusali, pamoja na wanawake kadha wa kadha, na Maria mama yake Yesu, na ndugu zake.'),
(2017608,69,44,1,15,'Siku chache baadaye, kulikuwa na mkutano wa waumini, karibu watu mia moja na ishirini. Petro alisimama mbele yao,'),
(2017609,69,44,1,16,'akasema, "Ndugu zangu, ilikuwa lazima ile sehemu ya Maandiko Matakatifu itimie, sehemu ambayo Roho Mtakatifu, kwa maneno ya Daudi, alibashiri habari za Yuda ambaye aliwaongoza wale waliomtia Yesu nguvuni.'),
(2017610,69,44,1,17,'Yuda alikuwa mmoja wa kikundi chetu maana alichaguliwa ashiriki huduma yetu.'),
(2017611,69,44,1,18,'"Mnajua kwamba yeye alinunua shamba kwa zile fedha alizopata kutokana na kitendo chake kiovu. Akaanguka chini, akapasuka na matumbo yake yakamwagika nje.'),
(2017612,69,44,1,19,'Kila mtu katika Yerusalemu alisikia habari za tukio hilo na hivyo, kwa lugha yao, wakaliita lile shamba `Hekeli Dama`, maana yake, `Shamba la Damu.`)'),
(2017613,69,44,1,20,'Basi, imeandikwa katika kitabu cha Zaburi: `Nyumba yake ibaki mahame; mtu yeyote asiishi ndani yake.` Tena imeandikwa: `Mtu mwingine achukue nafasi yake katika huduma hiyo.`'),
(2017614,69,44,1,21,'Kwa hiyo, ni lazima mtu mwingine ajiunge nasi kama shahidi wa ufufuo wake Bwana Yesu. Anapaswa kuwa mmoja wa wale waliokuwa katika kundi letu wakati wote Bwana alipokuwa anasafiri pamoja nasi, tangu wakati Yohane alipokuwa anabatiza mpaka siku ile Yesu alipochukuliwa kutoka kwetu kwenda mbinguni."'),
(2017615,69,44,1,22,'[]'),
(2017616,69,44,1,23,'Basi, wakataja majina ya watu wawili; wa kwanza Yosefu aliyeitwa Barsaba (au pia Yusto), na wa pili Mathia.'),
(2017617,69,44,1,24,'Kisha wakasali: "Bwana, wewe unajua mioyo ya watu wote. Hivyo, utuonyeshe ni yupi kati ya hawa wawili uliyemchagua'),
(2017618,69,44,1,25,'ili achukue nafasi hii ya huduma ya kitume aliyoacha Yuda akaenda mahali pake mwenyewe."'),
(2017619,69,44,1,26,'Hapo, wakapiga kura; kura ikampata Mathia, naye akaongezwa katika idadi ya wale mitume wengine kumi na mmoja.'),
(2017620,69,44,2,1,'Siku ya Pentekoste ilipofika, waumini wote walikuwa wamekusanyika pamoja.'),
(2017621,69,44,2,2,'Ghafla, sauti ikasikika kutoka angani; sauti iliyokuwa kama ya upepo mkali, ikajaza ile nyumba yote walimokuwa wamekaa.'),
(2017622,69,44,2,3,'Kisha, vikatokea vitu vilivyoonekana kama ndimi za moto, vikagawanyika na kutua juu ya kila mmoja wao.'),
(2017623,69,44,2,4,'Wote wakajazwa Roho Mtakatifu, wakaanza kusema lugha mbalimbali kadiri Roho alivyowawezesha.'),
(2017624,69,44,2,5,'Na huko Yerusalemu walikuwako Wayahudi, watu wamchao Mungu, waliotoka katika kila nchi duniani.'),
(2017625,69,44,2,6,'Waliposikia sauti hiyo, kundi kubwa la watu lilikusanyika. Wote walishtuka sana kwani kila mmoja wao aliwasikia hao waumini wakisema kwa lugha yake mwenyewe.'),
(2017626,69,44,2,7,'Walistaajabu na kushangaa, wakisema, "Je, hawa wote tunaowasikia wakisema hivi, si wenyeji wa Galilaya?'),
(2017627,69,44,2,8,'Imekuwaje, basi, kwamba kila mmoja wetu anawasikia wakisema kwa lugha yake mwenyewe?'),
(2017628,69,44,2,9,'Baadhi yetu ni Waparthi, Wamedi na Waelami; wengine ni wenyeji wa Mesopotamia, Yudea, Kapadokia, Ponto na Asia,'),
(2017629,69,44,2,10,'Frugia na Pamfulia, Misri na sehemu za Libya karibu na Kurene; wengine wetu ni wageni kutoka Roma,'),
(2017630,69,44,2,11,'Wayahudi na watu walioongokea dini ya Kiyahudi; wengine wametoka Krete na Arabia. Sisi sote tunasikia wakisema kwa lugha zetu wenyewe mambo makuu ya Mungu."'),
(2017631,69,44,2,12,'Wote walishangaa na kufadhaika huku wakiulizana, "Hii ina maana gani?"'),
(2017632,69,44,2,13,'Lakini wengine wakawadhihaki wakisema, "Watu hawa wamelewa divai mpya!"'),
(2017633,69,44,2,14,'Lakini Petro alisimama pamoja na wale kumi na mmoja akaanza kuwahutubia watu kwa sauti kubwa: "Ndugu Wayahudi nanyi nyote mnaokaa hapa Yerusalemu, sikilizeni kwa makini maneno yangu.'),
(2017634,69,44,2,15,'Watu hawa hawakulewa kama mnavyodhani; mbona ni saa tatu tu asubuhi?'),
(2017635,69,44,2,16,'Ukweli ni kwamba jambo hili ni lile alilosema nabii Yoeli:'),
(2017636,69,44,2,17,'`Katika siku zile za mwisho, asema Bwana, nitawamiminia binadamu wote Roho wangu. Watoto wenu, wanaume kwa wanawake, watautangaza ujumbe wangu; vijana wenu wataona maono, na wazee wenu wataota ndoto.'),
(2017637,69,44,2,18,'Naam, hata watumishi wangu, wanaume kwa wanawake, nitawamiminia Roho wangu, siku zile, nao watautangaza ujumbe wangu.'),
(2017638,69,44,2,19,'Nitatenda miujiza juu angani, na ishara chini duniani; kutakuwa na damu, moto na moshi mzito;'),
(2017639,69,44,2,20,'jua litatiwa giza, na mwezi utakuwa mwekundu kama damu, kabla ya kutokea ile siku kuu na tukufu ya Bwana.'),
(2017640,69,44,2,21,'Hapo, yeyote atakayeomba kwa jina la Bwana, ataokolewa.`'),
(2017641,69,44,2,22,'"Wananchi wa Israeli, sikilizeni maneno haya! Yesu wa Nazareti alikuwa mtu ambaye mamlaka yake ya kimungu yalithibitishwa kwenu kwa miujiza, maajabu na ishara Mungu alizofanya kati yenu kwa njia yake, kama mnavyojua.'),
(2017642,69,44,2,23,'Kufuatana na mpango wake mwenyewe Mungu alikwisha amua kwamba Yesu angetiwa mikononi mwenu; nanyi mkamuua kwa kuwaachia watu wabaya wamsulubishe.'),
(2017643,69,44,2,24,'Lakini Mungu alimfufua kutoka wafu akamwokoa katika maumivu ya kifo kwa maana haingewezekana kabisa kifo kimfunge.'),
(2017644,69,44,2,25,'Maana Daudi alisema juu yake hivi: `Nilimwona Bwana mbele yangu daima; yuko nami upande wangu wa kulia, na hivyo sitatikisika.'),
(2017645,69,44,2,26,'Kwa hiyo, moyo wangu ulifurahi; tena nilipiga vigelegele vya furaha. Mwili wangu utakaa katika tumaini;'),
(2017646,69,44,2,27,'kwa kuwa hutaiacha roho yangu katika kuzimu, wala kumruhusu mtakatifu wako aoze.'),
(2017647,69,44,2,28,'Umenionyesha njia za kuufikia uzima, kuwako kwako kwanijaza furaha!`'),
(2017648,69,44,2,29,'"Ndugu zangu, napenda kuwaambieni waziwazi juu ya mambo yaliyompata Daudi, babu yetu. Yeye alikufa, akazikwa, tena kaburi lake liko papa hapa petu mpaka leo.'),
(2017649,69,44,2,30,'Lakini kwa vile Daudi alikuwa nabii, alijua kuwa Mungu alimwapia kiapo kwamba atamtawaza mmoja wa uzawa wake kuwa mfalme mahali pake.'),
(2017650,69,44,2,31,'Daudi aliona kabla mambo yatakayofanywa na Mungu na hivyo akasema juu ya ufufuo wa Kristo wakati aliposema: `Hakuachwa kuzimu, mwili wake haukuoza.`'),
(2017651,69,44,2,32,'Basi, Mungu alimfufua huyo Yesu na sisi sote ni mashahidi wa tukio hilo.'),
(2017652,69,44,2,33,'Yesu aliinuliwa juu mpaka upande wa kulia wa Mungu, akapokea kutoka kwa Baba ile zawadi aliyoahidi yaani Roho Mtakatifu; na mnachoona sasa na kusikia ni mmiminiko wa huyo Roho.'),
(2017653,69,44,2,34,'Maana Daudi mwenyewe, hakupanda mpaka mbinguni; ila yeye alisema: `Bwana alimwambia Bwana wangu: Keti upande wangu wa kulia,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017654,69,44,2,35,'hadi nitakapowafanya adui zako kibao cha kukanyagia miguu yako.`'),
(2017655,69,44,2,36,'"Watu wote wa Israeli wanapaswa kufahamu kwa hakika kwamba huyo Yesu mliyemsulubisha ninyi, ndiye huyo ambaye Mungu amemfanya kuwa Bwana na Kristo."'),
(2017656,69,44,2,37,'Basi, watu waliposikia hayo, walichomwa moyo, wakawauliza Petro na wale mitume wenzake: "Ndugu zetu, tufanye nini?"'),
(2017657,69,44,2,38,'Petro akajibu, "Tubuni na kila mmoja wenu abatizwe kwa jina la Yesu Kristo ili mpate kuondolewa dhambi zenu na kupokea ile zawadi ya Roho Mtakatifu.'),
(2017658,69,44,2,39,'Maana, ahadi ile ilikuwa kwa ajili yenu, kwa ajili ya watoto wenu, kwa ajili ya wote wanaokaa mbali; na kwa ajili ya kila mtu ambaye Bwana Mungu wetu atamwita kwake."'),
(2017659,69,44,2,40,'Kwa maneno mengine mengi, Petro alisisitiza na kuwahimiza watu akisema, "Jiokoeni katika kizazi hiki kiovu."'),
(2017660,69,44,2,41,'Wengi waliyakubali maneno yake, wakabatizwa. Watu wapatao elfu tatu wakaongezeka katika kile kikundi siku hiyo.'),
(2017661,69,44,2,42,'Hawa wote waliendelea kujifunza kutoka kwa mitume, kuishi pamoja kidugu, kumega mkate na kusali.'),
(2017662,69,44,2,43,'Miujiza na maajabu mengi yalifanyika kwa njia ya mitume hata kila mtu akajawa na hofu.'),
(2017663,69,44,2,44,'Waumini wote waliendelea kuwa kitu kimoja na mali zao waligawana pamoja.'),
(2017664,69,44,2,45,'Walikuwa wakiuza mali na vitu vyao kisha wakagawana fedha kadiri ya mahitaji ya kila mmoja.'),
(2017665,69,44,2,46,'Waliendelea kukutana pamoja kila siku Hekaluni. Lakini wakati wa kumega mkate, walikutana katika nyumba zao na wakakishiriki chakula hicho kwa furaha na moyo mkunjufu.'),
(2017666,69,44,2,47,'Walimtukuza Mungu, wakapendwa na watu wote. Kila siku Bwana aliwaongezea idadi ya watu waliokuwa wakiokolewa.'),
(2017667,69,44,3,1,'Siku moja, saa tisa alasiri, Petro na Yohane walikuwa wanakwenda Hekaluni, wakati wa sala.'),
(2017668,69,44,3,2,'Na pale karibu na mlango wa Hekalu uitwao "Mlango Mzuri", palikuwa na mtu mmoja, kiwete tangu kuzaliwa. Watu walimbeba huyo mtu kila siku na kumweka hapo ili aombe chochote kwa wale waliokuwa wakiingia Hekaluni.'),
(2017669,69,44,3,3,'Alipowaona Petro na Yohane wakiingia Hekaluni, aliwaomba wampe chochote.'),
(2017670,69,44,3,4,'Petro na Yohane walimkodolea macho, naye Petro akamwambia, "Tutazame!"'),
(2017671,69,44,3,5,'Naye akawageukia, akitazamia kupata kitu kutoka kwao.'),
(2017672,69,44,3,6,'Kisha Petro akamwambia, "Sina fedha wala dhahabu lakini kile nilicho nacho nitakupa. Kwa jina la Yesu Kristo wa Nazareti, tembea!"'),
(2017673,69,44,3,7,'Halafu, akamshika mkono wa kulia, akamwinua. Papo hapo miguu na magoti yake yakapata nguvu.'),
(2017674,69,44,3,8,'Akaruka, akasimama na kuanza kutembea. Halafu akaingia pamoja nao Hekaluni, akitembea na kurukaruka huku akimtukuza Mungu.'),
(2017675,69,44,3,9,'Watu wote waliokuwa hapo walimwona akitembea na kumsifu Mungu.'),
(2017676,69,44,3,10,'Walipomtambua kuwa ndiye yule aliyekuwa anaombaomba karibu na ule "Mlango Mzuri" wa Hekalu, wakashangaa mno hata wasiweze kuelewa yaliyompata.'),
(2017677,69,44,3,11,'Watu wote, wakiwa na mshangao mkubwa wakaanza kukimbilia mahali palipoitwa "Ukumbi wa Solomoni," ambapo yule mtu alikuwa bado anaandamana na Petro na Yohane.'),
(2017678,69,44,3,12,'Basi, Petro alipowaona watu hao akawaambia, "Wananchi wa Israeli, kwa nini mnashangazwa na jambo hili? Mbona mnatukodolea macho kana kwamba ni kwa nguvu zetu au utakatifu wetu sisi wenyewe tumemfanya mtu huyu aweze kutembea?'),
(2017679,69,44,3,13,'Mungu wa Abrahamu, Isaka na Yakobo, Mungu wa baba zetu amemtukuza Yesu mtumishi wake. Yeye ndiye yuleyule mliyemtia mikononi mwa wakuu na kumkataa mbele ya Pilato hata baada ya Pilato kuamua kumwacha huru.'),
(2017680,69,44,3,14,'Alikuwa mtakatifu na mwema; lakini ninyi mlimkataa, mkataka mtu mwingine aliyekuwa muuaji afunguliwe.'),
(2017681,69,44,3,15,'Basi, mlimuua yule ambaye ni chanzo cha uzima. Lakini Mungu alimfufua, na sisi ni mashahidi wa tukio hilo.'),
(2017682,69,44,3,16,'Jina la Yesu na imani katika jina hilo ndivyo vilivyompa nguvu mtu huyu mnayemwona na kumfahamu. Imani kwa Yesu ndiyo iliyomponya kabisa mtu huyu kama mnavyoona nyote.'),
(2017683,69,44,3,17,'"Sasa ndugu zangu, nafahamu kwamba ninyi na wakuu wenu mlitenda hayo kwa sababu ya kutojua kwenu.'),
(2017684,69,44,3,18,'Lakini ndivyo Mungu alivyotimiza yale aliyotangaza zamani kwa njia ya manabii wote, kwamba ilikuwa lazima Kristo wake ateseke.'),
(2017685,69,44,3,19,'Basi, tubuni mkamrudie Mungu ili afute dhambi zenu.'),
(2017686,69,44,3,20,'Fanyeni hivyo ili Bwana awape nyakati za kuburudika rohoni na kuwaletea yule Kristo aliyemteua ambaye ndiye Yesu.'),
(2017687,69,44,3,21,'Ni lazima yeye abaki huko mbinguni mpaka utakapofika wakati wa kurekebishwa vitu vyote, kama Mungu alivyosema kwa njia ya manabii wake watakatifu wa tangu zamani.'),
(2017688,69,44,3,22,'Kwa maana Mose alisema, `Bwana Mungu wenu atawapelekeeni nabii kama mimi kutoka kati yenu ninyi wenyewe.'),
(2017689,69,44,3,23,'Yeyote yule ambaye hatamsikiliza nabii huyo atatengwa mbali na watu wa Mungu na kuangamizwa.`'),
(2017690,69,44,3,24,'Manabii wote, kuanzia Samweli na wale waliomfuata, walitangaza habari za mambo haya ambayo yamekuwa yakitendeka siku hizi.'),
(2017691,69,44,3,25,'Ahadi zile Mungu alizotoa kwa njia ya manabii ni kwa ajili yenu; na mnashiriki lile agano Mungu alilofanya na babu zenu, kama alivyomwambia Abrahamu: `Kwa njia ya wazawa wako, jamaa zote za dunia zitabarikiwa.`'),
(2017692,69,44,3,26,'Basi, ilikuwa kwa ajili yenu kwanza kwamba Mungu alimfufua mtumishi wake, alimtuma awabariki kwa kumfanya kila mmoja wenu aachane kabisa na maovu yake."'),
(2017693,69,44,4,1,'Petro na Yohane walipokuwa bado wanawahutubia watu, makuhani na mkuu wa walinzi wa Hekalu pamoja na Masadukayo *walifika.'),
(2017694,69,44,4,2,'Walikasirika sana, maana hao mitume walikuwa wanawahubiria watu kwamba Yesu alifufuka, jambo ambalo linaonyesha wazi kwamba wafu watafufuka.'),
(2017695,69,44,4,3,'Basi, waliwatia nguvuni na kwa kuwa usiku ulikuwa umekaribia, wakawaweka chini ya ulinzi mpaka kesho yake.'),
(2017696,69,44,4,4,'Lakini wengi kati ya wale waliosikia ujumbe wao waliamini, na idadi ya waumini ikawa imefika karibu elfu tano.'),
(2017697,69,44,4,5,'Kesho yake, viongozi wa Wayahudi, wazee na walimu wa Sheria, walikusanyika pamoja huko Yerusalemu.'),
(2017698,69,44,4,6,'Walikutana pamoja na Anasi, Kayafa, Yohane, Aleksanda na wengine waliokuwa wa ukoo wa Kuhani Mkuu.'),
(2017699,69,44,4,7,'Waliwasimamisha mitume mbele yao, wakawauliza, "Ninyi mmefanya jambo hili kwa nguvu gani na kwa jina la nani?"'),
(2017700,69,44,4,8,'Hapo, Petro, akiwa amejawa na Roho Mtakatifu, akawaambia, "Viongozi na wazee wa watu!'),
(2017701,69,44,4,9,'Ikiwa mnatuuliza leo juu ya kile kitendo chema alichofanyiwa yule mtu aliyekuwa kiwete na jinsi alivyopata kuwa mzima,'),
(2017702,69,44,4,10,'basi, ninyi na watu wote wa Israeli mnapaswa kujua kwamba mtu huyu anasimama mbele yenu leo, mzima kabisa, kwa nguvu ya jina lake Yesu wa Nazareti ambaye ninyi mlimsulubisha, lakini Mungu akamfufua kutoka wafu.'),
(2017703,69,44,4,11,'Huyu ndiye ambaye Maandiko Matakatifu yanasema: `Jiwe mlilokataa ninyi waashi, sasa limekuwa jiwe kuu la msingi.`');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017704,69,44,4,12,'Wokovu haupatikani kwa mtu mwingine yeyote, kwa maana duniani pote, binadamu hawakupewa jina la mtu mwingine ambaye sisi tunaweza kuokolewa naye."'),
(2017705,69,44,4,13,'Hao wazee wa baraza, wakiwa wanajua kwamba Petro na Yohane walikuwa watu wasio na kisomo wala elimu yoyote, walishangaa juu ya jinsi walivyosema kwa uhodari. Wakatambua kwamba walikuwa wamejiunga na Yesu.'),
(2017706,69,44,4,14,'Lakini walipomwona yule mtu aliyeponywa amesimama pamoja nao, hawakuweza kusema kitu.'),
(2017707,69,44,4,15,'Hivyo, waliwaamuru watoke nje ya baraza, nao wakabaki ndani wakizungumza kwa faragha.'),
(2017708,69,44,4,16,'Wakaulizana, "Tufanye nini na watu hawa? Kila mtu anayeishi Yerusalemu anajua kwamba mwujiza huu wa ajabu umefanyika, nasi hatuwezi kukana jambo hilo.'),
(2017709,69,44,4,17,'Lakini ili tupate kuzuia jambo hili lisienee zaidi kati ya watu, tuwaonye wasiongee na mtu yeyote kwa jina la Yesu."'),
(2017710,69,44,4,18,'Kwa hiyo wakawaita tena ndani, wakawaonya wasiongee tena hadharani, wala kufundisha kwa jina la Yesu.'),
(2017711,69,44,4,19,'Lakini Petro na Yohane wakawajibu, "Amueni ninyi wenyewe kama ni haki mbele ya Mungu kuwatii ninyi kuliko kumtii yeye.'),
(2017712,69,44,4,20,'Kwa maana hatuwezi kuacha kusema juu ya mambo yale tuliyoyaona na kuyasikia."'),
(2017713,69,44,4,21,'Basi, hao wazee wa Baraza wakawaonya kwa ukali zaidi, halafu wakawaacha huru. Hawakuweza kuwapa adhabu kwa sababu watu wote walikuwa wakimtukuza Mungu kwa sababu ya tukio hilo.'),
(2017714,69,44,4,22,'Huyo mtu aliyeponywa alikuwa na umri wa miaka zaidi ya arobaini.'),
(2017715,69,44,4,23,'Mara tu walipoachwa huru, Petro na Yohane walirudi kwa wenzao, wakawaeleza yale waliyoambiwa na makuhani wakuu na wazee.'),
(2017716,69,44,4,24,'Waliposikia habari hiyo waliungana pamoja katika kumwomba Mungu wakisema, "Bwana, wewe ni Muumba wa mbingu na nchi, bahari na vyote vilivyomo!'),
(2017717,69,44,4,25,'Ndiwe uliyemfanya mtumishi wako, babu yetu Daudi, aseme kwa nguvu ya Roho Mtakatifu: `Kwa nini mataifa yameghadhibika? Mbona watu wamefanya mipango ya bure?'),
(2017718,69,44,4,26,'Wafalme wa dunia walijiweka tayari, na watawala walikutana pamoja, ili kumwasi Bwana na Kristo wake.`'),
(2017719,69,44,4,27,'"Maana, kwa hakika, ndivyo Herode, Pontio Pilato, watu wa Israeli na watu wa mataifa walivyokutanika papa hapa mjini, kumpinga Yesu Mtumishi wako Mtakatifu ambaye umemtia mafuta.'),
(2017720,69,44,4,28,'Naam, walikutana ili wafanye yale ambayo ulikusudia na kupanga tangu mwanzo kwa uwezo wako na mapenzi yako.'),
(2017721,69,44,4,29,'Lakini sasa, ee Bwana, angalia vitisho vyao. Utuwezeshe sisi watumishi wako kuhubiri neno lako kwa uhodari.'),
(2017722,69,44,4,30,'Nyosha mkono wako uponye watu. Fanya ishara na maajabu kwa jina la Yesu Mtumishi wako Mtakatifu."'),
(2017723,69,44,4,31,'Walipomaliza kusali, pale mahali walipokuwa wamekutanika pakatikiswa, nao wote wakajazwa Roho Mtakatifu. Wote wakaanza kuhubiri neno la Mungu bila uoga.'),
(2017724,69,44,4,32,'Jumuiya yote ya waumini ilikuwa moyo mmoja na roho moja. Hakuna hata mmoja aliyekuwa na kitu chochote akakiweka kuwa mali yake binafsi, ila waligawana vyote walivyokuwa navyo.'),
(2017725,69,44,4,33,'Mitume walishuhudia kwa nguvu nyingi kufufuka kwa Bwana Yesu, naye Mungu akawapa baraka nyingi.'),
(2017726,69,44,4,34,'Hakuna mtu yeyote aliyetindikiwa kitu, maana waliokuwa na mashamba au nyumba walikuwa wanaviuza'),
(2017727,69,44,4,35,'na kuwakabidhi mitume fedha hizo, zikagawiwa kila mmoja kadiri ya mahitaji yake.'),
(2017728,69,44,4,36,'Kulikuwa na Mlawi mmoja, mzaliwa wa Kupro, jina lake Yosefu, ambaye mitume walimwita jina Barnaba (maana yake, "Mtu mwenye kutia moyo").'),
(2017729,69,44,4,37,'Yeye pia alikuwa na shamba lake, akaliuza; akazichukua zile fedha, akawakabidhi mitume.'),
(2017730,69,44,5,1,'Mtu mmoja aitwaye Anania na mkewe Safira waliuza shamba lao vilevile.'),
(2017731,69,44,5,2,'Lakini, mkewe akiwa anajua, Anania akajiwekea sehemu ya fedha alizopata na ile sehemu nyingine akawakabidhi mitume.'),
(2017732,69,44,5,3,'Basi, Petro akamwuliza, "Anania, mbona Shetani ameuingia moyo wako na kukufanya umdanganye Roho Mtakatifu kwa kujiwekea sehemu ya fedha ulizopata kutokana na lile shamba?'),
(2017733,69,44,5,4,'Kabla ya kuliuza lilikuwa mali yako, na baada ya kuliuza, bado hizo fedha zilikuwa zako uzitumie utakavyo. Kwa nini basi, uliamua moyoni mwako kufanya jambo la namna hii? Hukumdanganya mtu; umemdanganya Mungu!"'),
(2017734,69,44,5,5,'Anania aliposikia hayo, akaanguka chini, akafa. Watu wote waliosikia habari ya tukio hilo waliogopa sana.'),
(2017735,69,44,5,6,'Vijana wakafika wakaufunika mwili wake, wakamtoa nje, wakamzika.'),
(2017736,69,44,5,7,'Baada ya muda wa saa tatu hivi, mke wake, bila kufahamu mambo yaliyotukia, akaingia mle ndani.'),
(2017737,69,44,5,8,'Petro akamwambia, "Niambie! Je, kiasi hiki cha fedha ndicho mlichopata kwa kuuza lile shamba?" Yeye akamjibu, "Naam, ni kiasi hicho."'),
(2017738,69,44,5,9,'Naye Petro akamwambia, "Mbona mmekula njama kumjaribu Roho wa Bwana? Sikiliza! Wale watu waliokwenda kumzika mume wako, sasa wako mlangoni na watakuchukua wewe pia."'),
(2017739,69,44,5,10,'Mara Safira akaanguka mbele ya miguu ya Petro, akafa. Wale vijana walipoingia, walimkuta amekwisha kufa; hivyo wakamtoa nje, wakamzika karibu na mume wake.'),
(2017740,69,44,5,11,'Kanisa lote pamoja na wote waliosikia habari ya tukio hilo, waliogopa sana.'),
(2017741,69,44,5,12,'Mitume walifanya miujiza na maajabu mengi kati ya watu. Waumini walikuwa wakikutana pamoja katika ukumbi wa Solomoni.'),
(2017742,69,44,5,13,'Mtu yeyote mwingine ambaye hakuwa mwamini hakuthubutu kujiunga nao. Hata hivyo, watu wengine wasiokuwa wa imani hiyo waliwasifu.'),
(2017743,69,44,5,14,'Idadi ya watu waliomwamini Bwana, wanaume kwa wanawake, iliongezeka zaidi na zaidi.'),
(2017744,69,44,5,15,'Kwa sababu hiyo, watu walikuwa wakipeleka wagonjwa barabarani na kuwalaza juu ya vitanda na mikeka ili Petro akipita, walau kivuli chake kiwaguse baadhi yao.'),
(2017745,69,44,5,16,'Watu wengi walifika kutoka katika miji ya kando kando ya Yerusalemu, wakiwaleta wagonjwa wao na wale waliokuwa na pepo wachafu, nao wote wakaponywa.'),
(2017746,69,44,5,17,'Kisha, Kuhani Mkuu na wenzake waliokuwa wa kikundi cha Masadukayo wa mahali hapo, wakawaonea mitume wivu.'),
(2017747,69,44,5,18,'Basi, wakawatia nguvuni, wakawafunga ndani ya gereza kuu.'),
(2017748,69,44,5,19,'Lakini usiku malaika wa Bwana aliifungua milango ya gereza, akawatoa nje, akawaambia,'),
(2017749,69,44,5,20,'"Nendeni mkasimame Hekaluni na kuwaambia watu kila kitu kuhusu maisha haya mapya."'),
(2017750,69,44,5,21,'Mitume walitii, wakaingia Hekaluni asubuhi na mapema, wakaanza kufundisha. Kuhani Mkuu na wenzake walipofika, waliita mkutano wa Baraza kuu, yaani halmashauri yote ya wazee wa Wayahudi halafu wakawatuma watu gerezani wawalete wale mitume.'),
(2017751,69,44,5,22,'Lakini hao watumishi walipofika huko hawakuwakuta mle gerezani. Hivyo walirudi, wakatoa taarifa mkutanoni,'),
(2017752,69,44,5,23,'wakisema, "Tulikuta gereza limefungwa kila upande na walinzi wakilinda milango. Lakini tulipofungua hatukumkuta mtu yeyote ndani."'),
(2017753,69,44,5,24,'Mkuu wa walinzi wa Hekalu na makuhani wakuu waliposikia habari hiyo wakawa na wasiwasi, wasijue yaliyowapata.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017754,69,44,5,25,'Akafika mtu mmoja, akawaambia, "Wale watu mliowafunga gerezani, hivi sasa wamo Hekaluni, wanawafundisha watu."'),
(2017755,69,44,5,26,'Hapo mkuu wa walinzi wa Hekalu pamoja na watu wake walikwenda Hekaluni, akawaleta. Lakini hawakuwakamata kwa kutumia nguvu, maana waliogopa kwamba watu wangewapiga mawe.'),
(2017756,69,44,5,27,'Basi, wakawapeleka, wakawasimamisha mbele ya Baraza. Kuhani Mkuu akawaambia,'),
(2017757,69,44,5,28,'"Tuliwakatazeni waziwazi kufundisha kwa jina la mtu huyu; sasa mmeyaeneza mafundisho yenu pote katika Yerusalemu na mnakusudia kutuwekea lawama ya kifo cha mtu huyo."'),
(2017758,69,44,5,29,'Hapo Petro, akiwa pamoja na wale mitume wengine, akajibu, "Lazima tumtii Mungu, na siyo binadamu.'),
(2017759,69,44,5,30,'Mungu wa babu zetu alimfufua Yesu baada ya ninyi kumwua kwa kumtundika msalabani.'),
(2017760,69,44,5,31,'Huyu ndiye yule aliyekwezwa na Mungu mpaka upande wake wa kulia, akawa kiongozi na Mwokozi, ili awawezeshe watu wa Israeli watubu, wapate kusamehewa dhambi zao.'),
(2017761,69,44,5,32,'Sisi ni mashahidi wa tukio hilo, naye Roho Mtakatifu ambaye Mungu amewapa wale wanaomtii, anashuhudia pia tukio hilo."'),
(2017762,69,44,5,33,'Wajumbe wote wa lile Baraza waliposikia hayo, wakawaka hasira, hata wakaamua kuwaua.'),
(2017763,69,44,5,34,'Lakini Mfarisayo mmoja aitwaye Gamalieli ambaye alikuwa mwalimu wa Sheria na aliyeheshimika sana mbele ya watu wote, alisimama mbele ya lile Baraza, akataka wale mitume watolewe nje kwa muda mfupi.'),
(2017764,69,44,5,35,'Kisha akawaambia wale wajumbe wa Baraza, "Wananchi wa Israeli, tahadhari kabla ya kutekeleza hicho mnachotaka kuwatenda watu hawa!'),
(2017765,69,44,5,36,'Zamani kidogo, kulitokea mtu mmoja jina lake Theuda, akajisema kuwa mtu wa maana na watu karibu mia nne wakajiunga naye. Lakini aliuawa, kisha wafuasi wake wote wakatawanyika na kikundi chake kikafa.'),
(2017766,69,44,5,37,'Tena, baadaye, wakati ule wa kuhesabiwa watu, alitokea Yuda wa Galilaya. Huyu naye, aliwavuta watu wakamfuata; lakini naye pia aliuawa, na wafuasi wake wakatawanyika.'),
(2017767,69,44,5,38,'Na sasa pia mimi nawaambieni, msiwachukulie watu hawa hatua yoyote; waacheni! Kwa maana, ikiwa mpango huu au shughuli hii yao imeanzishwa na binadamu, itatoweka yenyewe.'),
(2017768,69,44,5,39,'Lakini kama imeanzishwa na Mungu, siyo tu kwamba hamtaweza kuwashinda, bali mtajikuta mnapigana na Mungu." Basi, wakakubaliana naye.'),
(2017769,69,44,5,40,'Hivyo wakawaita wale mitume, wakaamuru wachapwe viboko na kuwaonya wasifundishe tena kwa jina la Yesu; kisha wakawaacha waende zao.'),
(2017770,69,44,5,41,'Basi, mitume wakatoka nje ya ule mkutano wa halmashauri wakiwa wamejaa furaha, kwani walistahili kuaibishwa kwa ajili ya jina la Yesu.'),
(2017771,69,44,5,42,'Wakaendelea kila siku kufundisha na kuhubiri Habari Njema ya Kristo, Hekaluni na nyumbani mwa watu.'),
(2017772,69,44,6,1,'Baadaye, idadi ya wanafunzi ilipokuwa inazidi kuongezeka, kulitokea manung`uniko kati ya wanafunzi waliosema Kigiriki na wale waliosema Kiebrania. Wale waliosema Kigiriki walinung`unika kwamba wajane wao walikuwa wanasahauliwa katika ugawaji wa mahitaji ya kila siku.'),
(2017773,69,44,6,2,'Kwa hiyo, mitume kumi na wawili waliita jumuiya yote ya wanafunzi, wakasema, "Si vizuri sisi tuache kulihubiri neno la Mungu ili tushughulikie ugawaji wa mahitaji.'),
(2017774,69,44,6,3,'Hivyo, ndugu zetu, chagueni miongoni mwenu watu saba wenye sifa njema, waliojawa na Roho na wenye hekima; nasi tutawakabidhi jukumu hilo.'),
(2017775,69,44,6,4,'Sisi, lakini, tutashughulika na sala na kazi ya kuhubiri neno la Mungu."'),
(2017776,69,44,6,5,'Jambo hilo likaipendeza jumuiya yote ya waumini. Wakawachagua Stefano, mtu mwenye imani kubwa na mwenye kujawa na Roho Mtakatifu, Filipo, Prokoro, Nikanora, Timona, Parmena na Nikolao wa Antiokia ambaye hapo awali alikuwa ameongokea dini ya Kiyahudi.'),
(2017777,69,44,6,6,'Wakawaweka mbele ya mitume, nao wakawaombea na kuwawekea mikono.'),
(2017778,69,44,6,7,'Neno la Mungu likazidi kuenea na idadi ya waumini huko Yerusalemu ikaongezeka zaidi, na kundi kubwa la makuhani wakaipokea imani.'),
(2017779,69,44,6,8,'Mungu alimjalia Stefano neema tele, akampa nguvu nyingi hata akawa anatenda miujiza na maajabu kati ya watu.'),
(2017780,69,44,6,9,'Lakini watu fulani wakatokea ili wabishane na Stefano. Baadhi ya watu hao walikuwa wa sunagogi moja lililoitwa "Sunagogi la Watu Huru", nao walitoka Kurene na Aleksandria; wengine walitoka Kilikia na Asia.'),
(2017781,69,44,6,10,'Lakini hawakuweza kumshinda kwa sababu ya hekima yake na kwa sababu ya yule Roho aliyeongoza maneno yake.'),
(2017782,69,44,6,11,'Kwa hiyo waliwahonga watu kadhaa waseme: "Tumemsikia Stefano akisema maneno ya kumkashifu Mose na kumkashifu Mungu."'),
(2017783,69,44,6,12,'Kwa namna hiyo, waliwachochea watu, wazee na walimu wa Sheria. Basi, wakamjia Stefano, wakamkamata na kumleta mbele ya Baraza kuu.'),
(2017784,69,44,6,13,'Walileta Barazani mashahidi wa uongo ambao walisema, "Mtu huyu haachi kamwe kusema maneno ya kupakashifu mahali hapa patakatifu na Sheria ya Mose.'),
(2017785,69,44,6,14,'Kwa maana tulikwisha msikia akisema eti huyo Yesu wa Nazareti atapaharibu kabisa mahali hapa na kufutilia mbali desturi zile tulizopokea kutoka kwa Mose."'),
(2017786,69,44,6,15,'Wote waliokuwa katika kile kikao cha Baraza walimkodolea macho Stefano, wakauona uso wake umekuwa kama wa malaika.'),
(2017787,69,44,7,1,'Basi, Kuhani Mkuu akamwuliza, "Je, mambo haya ni kweli?"'),
(2017788,69,44,7,2,'Naye Stefano akasema, "Ndugu zangu na akina baba, nisikilizeni! Mungu alimtokea baba yetu Abrahamu alipokuwa kule Mesopotamia kabla hajaenda kukaa kule Harani.'),
(2017789,69,44,7,3,'Mungu alimwambia: `Ondoka katika nchi yako; waache watu wa ukoo wako; nenda katika nchi nitakayokuonyesha!`'),
(2017790,69,44,7,4,'Kwa hivyo, Abrahamu alihama nchi ya Kaldayo, akaenda kukaa Harani. Baada ya kifo cha baba yake, Mungu alimtoa tena Harani akaja kukaa katika nchi hii mnayokaa sasa.'),
(2017791,69,44,7,5,'Mungu hakumpa hata sehemu moja ya nchi hii iwe mali yake; hata hivyo, alimwahidia kumpa nchi hii iwe yake na ya wazawa wake, ingawaje wakati huu hakuwa na mtoto.'),
(2017792,69,44,7,6,'Mungu alimwambia hivi: `Wazao wako watapelekwa katika nchi inayotawaliwa na watu wengine, na huko watafanywa watumwa na kutendewa vibaya kwa muda wa miaka mia nne.'),
(2017793,69,44,7,7,'Lakini mimi nitalihukumu taifa hilo litakalowafanya watumwa. Kisha nitawatoa katika nchi hiyo ili waje kuniabudu mahali hapa.`'),
(2017794,69,44,7,8,'Halafu Mungu aliifanya tohara iwe ishara ya agano. Hivyo, Abrahamu alimtahiri mtoto wake Isaka, siku ya nane baada ya kuzaliwa. Na Isaka, vivyo hivyo, alimtahiri Yakobo. Naye Yakobo aliwatendea wale mababu kumi na wawili vivyo hivyo.'),
(2017795,69,44,7,9,'"Wale mababu walimwonea wivu Yosefu, wakamuuza utumwani Misri. Lakini Mungu alikuwa pamoja naye,'),
(2017796,69,44,7,10,'akamwokoa katika taabu zake zote. Mungu alimjalia fadhili na hekima mbele ya Farao, mfalme wa Misri, hata Farao akamweka awe mkuu wa ile nchi na nyumba ya kifalme.'),
(2017797,69,44,7,11,'Kisha, kulizuka njaa kubwa katika nchi yote ya Misri na Kanaani, ikasababisha dhiki kubwa. Babu zetu hawakuweza kupata chakula chochote.'),
(2017798,69,44,7,12,'Basi, Yakobo alipopata habari kwamba huko Misri kulikuwa na nafaka, aliwatuma watoto wake, yaani babu zetu, waende huko Misri mara ya kwanza.'),
(2017799,69,44,7,13,'Katika safari yao ya pili, Yosefu alijitambulisha kwa ndugu zake, na Farao akaifahamu jamaa ya Yosefu.'),
(2017800,69,44,7,14,'Yosefu alituma ujumbe kwa baba yake na jamaa yote, jumla watu sabini na tano, waje Misri.'),
(2017801,69,44,7,15,'Hivyo, Yakobo alikwenda Misri ambako yeye na babu zetu wengine walikufa.'),
(2017802,69,44,7,16,'Miili yao ililetwa mpaka Shekemu, ikazikwa katika kaburi Abrahamu alilonunua kutoka kwa kabila la Hamori kwa kiasi fulani cha fedha.'),
(2017803,69,44,7,17,'"Wakati ulipotimia Mungu aitimize ahadi aliyompa Abrahamu, idadi ya wale watu kule Misri ilikwisha ongezeka na kuwa kubwa zaidi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017804,69,44,7,18,'Mwishowe, mfalme mmoja ambaye hakumtambua Yosefu alianza kutawala huko Misri.'),
(2017805,69,44,7,19,'Alilifanyia taifa letu ukatili, akawatendea vibaya babu zetu kwa kuwalazimisha waweke nje watoto wao wachanga ili wafe.'),
(2017806,69,44,7,20,'Mose alizaliwa wakati huo. Alikuwa mtoto mzuri sana. Alilelewa nyumbani kwa muda wa miezi mitatu,'),
(2017807,69,44,7,21,'na alipotolewa nje, binti wa Farao alimchukua, akamlea kama mtoto wake.'),
(2017808,69,44,7,22,'Mose alifundishwa mambo yote ya hekima ya Wamisri akawa mashuhuri kwa maneno na matendo.'),
(2017809,69,44,7,23,'"Alipokuwa na umri wa miaka arobaini aliamua kwenda kuwaona ndugu zake Waisraeli.'),
(2017810,69,44,7,24,'Huko alimwona mmoja wao akitendewa vibaya, akaenda kumwokoa, na kulipiza kisasi, akamuua yule Mmisri.'),
(2017811,69,44,7,25,'Alidhani kwamba Waisraeli wenzake wangeelewa kwamba Mungu angemtumia yeye kuwakomboa, lakini hawakuelewa hivyo.)'),
(2017812,69,44,7,26,'Kesho yake, aliwaona Waisraeli wawili wakipigana, akajaribu kuwapatanisha, akisema: `Ninyi ni ndugu; kwa nini basi, kutendeana vibaya ninyi kwa ninyi?`'),
(2017813,69,44,7,27,'Yule aliyekuwa anampiga mwenzake alimsukuma Mose kando akisema: `Ni nani aliyekuweka wewe kuwa kiongozi na mwamuzi wa watu?'),
(2017814,69,44,7,28,'Je, unataka kuniua kama ulivyomuua yule Mmisri jana?`'),
(2017815,69,44,7,29,'Baada ya kusikia hayo Mose alikimbia, akaenda kukaa katika nchi ya Midiani na huko akapata watoto wawili.'),
(2017816,69,44,7,30,'"Miaka arobaini ilipotimia, malaika wa Bwana alimtokea Mose katika kichaka kilichokuwa kinawaka moto kule jangwani karibu na mlima Sinai.'),
(2017817,69,44,7,31,'Mose alistaajabu sana kuona jambo hilo hata akasogea karibu ili achungulie; lakini alisikia sauti ya Bwana:'),
(2017818,69,44,7,32,'`Mimi ni Mungu wa baba zako, Mungu wa Abrahamu, Isaka na Yakobo!` Mose akatetemeka kwa hofu na wala hakuthubutu kutazama zaidi.'),
(2017819,69,44,7,33,'Bwana akamwambia: `Vua viatu vyako maana hapa unaposimama ni mahali patakatifu.'),
(2017820,69,44,7,34,'Nimeyaona mabaya wanayotendewa watu wangu kule Misri. Nimesikia kilio chao, nami nimekuja kuwaokoa. Basi sasa, nitakutuma Misri.`'),
(2017821,69,44,7,35,'"Huyu Mose ndiye yule watu wa Israeli waliyemkataa waliposema: `Ni nani aliyekuweka wewe kuwa kiongozi na mwamuzi wetu?` Kwa njia ya yule malaika aliyemtokea katika kichaka kilichokuwa kinawaka moto, Mungu alimtuma Mose huyo awe kiongozi na mkombozi.'),
(2017822,69,44,7,36,'Ndiye aliyewaongoza wale watu watoke Misri kwa kufanya miujiza na maajabu katika nchi ya Misri, katika bahari ya Shamu na jangwani kwa muda wa miaka arobaini.'),
(2017823,69,44,7,37,'Mose ndiye aliyewaambia watu wa Israeli: `Mungu atawateulieni nabii kama mimi kutoka katika ndugu zenu ninyi wenyewe.`'),
(2017824,69,44,7,38,'Wakati watu wa Israeli walipokutana pamoja kule jangwani, Mose ndiye aliyekuwako huko pamoja nao. Alikuwa huko pamoja na babu zetu na yule malaika aliyeongea naye mlimani Sinai; ndiye aliyekabidhiwa yale maneno yaletayo uzima atupe sisi.'),
(2017825,69,44,7,39,'"Lakini yeye ndiye babu zetu waliyemkataa kumsikiliza; walimsukuma kando, wakatamani kurudi Misri.'),
(2017826,69,44,7,40,'Walimwambia Aroni: `Tutengenezee miungu itakayotuongoza njiani, maana hatujui yaliyompata Mose huyu aliyetuongoza kutoka Misri!`'),
(2017827,69,44,7,41,'Hapo ndipo walipojitengenezea sanamu ya ndama, wakaitambikia na kukifanyia sherehe kitu ambacho ni kazi ya mikono yao wenyewe.'),
(2017828,69,44,7,42,'Lakini Mungu aliondoka kati yao, akawaacha waabudu nyota za anga, kama ilivyoandikwa katika kitabu cha manabii: `Enyi watu wa Israeli! Si mimi mliyenitolea dhabihu na sadaka kwa muda wa miaka arobaini kule jangwani!'),
(2017829,69,44,7,43,'Ninyi mlikibeba kibanda cha mungu Moloki, na sanamu ya nyota ya mungu wenu Refani. Sanamu mlizozifanya ndizo mlizoabudu. Kwa sababu hiyo nitakupeleka mateka mbali kupita Babuloni!`'),
(2017830,69,44,7,44,'Kule jangwani babu zetu walikuwa na lile hema lililoshuhudia kuweko kwa Mungu. Lilitengenezwa kama Mungu alivyomwambia Mose alifanye; nakala kamili ya kile alichoonyeshwa.'),
(2017831,69,44,7,45,'Kisha babu zetu walilipokezana wao kwa wao mpaka wakati wa Yoshua, walipoinyakua ile nchi kutoka kwa mataifa ambayo Mungu aliyafukuza mbele yao. Hapo lilikaa mpaka nyakati za Daudi.'),
(2017832,69,44,7,46,'Daudi alipata upendeleo kwa Mungu, akamwomba Mungu ruhusa ya kumjengea makao yeye aliye Mungu wa Yakobo.'),
(2017833,69,44,7,47,'Lakini Solomoni ndiye aliyemjengea Mungu nyumba.'),
(2017834,69,44,7,48,'"Hata hivyo, Mungu Mkuu haishi katika nyumba zilizojengwa na binadamu; kama nabii asemavyo:'),
(2017835,69,44,7,49,'`Bwana asema: Mbingu ni kiti changu cha enzi na dunia ni kiti changu cha kuwekea miguu.'),
(2017836,69,44,7,50,'Ni nyumba ya namna gani basi mnayoweza kunijengea, na ni mahali gani nitakapopumzika? Vitu hivi vyote ni mimi nimevifanya, au sivyo?`'),
(2017837,69,44,7,51,'"Enyi wakaidi wakuu! Mioyo na masikio yenu ni kama ya watu wa mataifa. Ninyi ni kama baba zenu. Siku zote mnampinga Roho Mtakatifu.'),
(2017838,69,44,7,52,'Je, yuko nabii yeyote ambaye baba zenu hawakumtesa? Waliwaua hao Mungu aliowatuma watangaze kuja kwake yule Mwenye Haki. Na sasa, ninyi mmemsaliti, mkamuua.'),
(2017839,69,44,7,53,'Ninyi mliipokea ile Sheria iliyoletwa kwenu na Malaika, lakini hamkuitii."'),
(2017840,69,44,7,54,'Wale wazee wa Baraza waliposikia hayo, walighadhibika sana, wakamsagia meno kwa hasira.'),
(2017841,69,44,7,55,'Lakini Stefano akiwa amejawa na Roho Mtakatifu, akatazama juu mbinguni, akauona utukufu wa Mungu na Yesu amekaa upande wa kulia wa Mungu.'),
(2017842,69,44,7,56,'Akasema, "Tazameni! Ninaona mbingu zimefunuliwa na Mwana wa Mtu amesimama upande wa kulia wa Mungu."'),
(2017843,69,44,7,57,'Hapo, watu wote katika kile kikao cha Baraza, wakapiga kelele na kuziba masikio yao kwa mikono yao. Kisha wakamrukia wote kwa pamoja,'),
(2017844,69,44,7,58,'wakamtoa nje ya mji, wakampiga mawe. Wale mashahidi wakayaweka makoti yao chini ya ulinzi wa kijana mmoja jina lake Saulo.'),
(2017845,69,44,7,59,'Waliendelea kumpiga mawe Stefano, huku akiwa anasali: "Bwana Yesu, ipokee roho yangu!"'),
(2017846,69,44,7,60,'Akapiga magoti, akalia kwa sauti kubwa: "Bwana, usiwalaumu kwa sababu ya dhambi hii." Baada ya kusema hivyo, akafa.'),
(2017847,69,44,8,1,'Saulo naye alikiona kitendo hicho cha kumwua Stefano kuwa sawa. Siku hiyo kanisa la Yerusalemu lilianza kuteswa vibaya. Waumini wote, isipokuwa tu wale mitume, walilazimika kutawanyika katika sehemu za mashambani za Yudea na Samaria.'),
(2017848,69,44,8,2,'Watu wamchao Mungu, walimzika Stefano na kumfanyia maombolezo makubwa.'),
(2017849,69,44,8,3,'Wakati huohuo, Saulo alijaribu kuliangamiza kanisa. Alikwenda katika kila nyumba, akawatoa nje waumini, wanaume kwa wanawake, akawatia gerezani.'),
(2017850,69,44,8,4,'Wale waumini waliotawanyika, walikwenda kila mahali wakihubiri ule ujumbe.'),
(2017851,69,44,8,5,'Naye Filipo aliingia katika mji wa Samaria na kumhubiri Kristo kwa wenyeji wa hapo.'),
(2017852,69,44,8,6,'Watu walijiunga kusikiliza kwa makini ule ujumbe wa Filipo na kuona ile miujiza aliyoifanya.'),
(2017853,69,44,8,7,'Maana pepo wachafu waliokuwa wamewapagaa watu wengi waliwatoka wakipiga kelele kubwa; na pia watu wengi waliokuwa wamepooza viungo na waliolemaa waliponywa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017854,69,44,8,8,'Kukawa na furaha kubwa katika mji ule.'),
(2017855,69,44,8,9,'Basi, kulikuwa na mtu mmoja aitwaye Simoni ambaye alikuwa amekwisha fanya uchawi wake katika mji huo kwa muda na kuwashangaza watu wa Samaria, akijiona kuwa yeye ni mtu maarufu.'),
(2017856,69,44,8,10,'Watu wote, wadogo na wakubwa, walimsikiliza kwa makini wakisema, "Simoni ndiye ile nguvu ya kimungu inayoitwa `Nguvu Kubwa."`'),
(2017857,69,44,8,11,'Walivutiwa sana naye kwa vile alikuwa amewashangaza kwa uchawi wake kwa muda mrefu.'),
(2017858,69,44,8,12,'Lakini walipouamini ujumbe wa Filipo juu ya Habari Njema ya Ufalme wa Mungu na jina la Yesu Kristo, walibatizwa, wanawake na wanaume.'),
(2017859,69,44,8,13,'Hata Simoni aliamini; baada ya kubatizwa ilikuwa akiandamana na Filipo, akastaajabia maajabu na miujiza iliyokuwa inafanyika.'),
(2017860,69,44,8,14,'Wale mitume waliokuwa kule Yerusalemu walipopata habari kwamba wenyeji wa Samaria nao wamelipokea neno la Mungu, waliwatuma kwao Petro na Yohane.'),
(2017861,69,44,8,15,'Walipofika waliwaombea hao waumini ili wampokee Roho Mtakatifu;'),
(2017862,69,44,8,16,'maana wakati huo Roho Mtakatifu hakuwa ameshukia yeyote kati yao; walikuwa wamebatizwa tu kwa jina la Bwana Yesu.'),
(2017863,69,44,8,17,'Basi, Petro na Yohane wakawawekea mikono hao waumini, nao wakampokea Roho Mtakatifu.'),
(2017864,69,44,8,18,'Hapo Simoni aling`amua kwamba kwa kuwekewa mikono ya mitume waumini walipewa Roho Mtakatifu. Hivyo aliwapa Petro na Yohane fedha akisema,'),
(2017865,69,44,8,19,'"Nipeni na mimi uwezo huo ili yeyote nitakayemwekea mikono, apokee Roho Mtakatifu."'),
(2017866,69,44,8,20,'Lakini Petro akamjibu, "Potelea mbali na fedha zako kwa vile unafikiri kwamba unaweza kununua karama ya Mungu kwa fedha!'),
(2017867,69,44,8,21,'Huna sehemu yoyote wala haki katika kazi hiyo kwa maana moyo wako hauko sawa mbele ya macho ya Mungu.'),
(2017868,69,44,8,22,'Kwa hiyo, tubu ubaya wako huu na umwombe Bwana naye anaweza kukusamehe fikira kama hizo.'),
(2017869,69,44,8,23,'Ni dhahiri kwangu kwamba umejaa wivu mkali na mfungwa wa dhambi!"'),
(2017870,69,44,8,24,'Simoni akajibu, "Tafadhali, niombeeni kwa Bwana lisije likanipata lolote kati ya hayo mliyosema."'),
(2017871,69,44,8,25,'Baada ya Petro na Yohane kutoa ushuhuda wao na kuutangaza ujumbe wa Bwana, walirudi Yerusalemu. Walipokuwa wanarudi walihubiri Habari Njema katika vijiji vingi vya Samaria.'),
(2017872,69,44,8,26,'Malaika wa Bwana alimwambia Filipo, "Jitayarishe uende kusini kupitia njia inayotoka Yerusalemu kwenda Gaza." (Njia hiyo hupita jangwani.)'),
(2017873,69,44,8,27,'Basi, Filipo akajiweka tayari, akaanza safari. Wakati huohuo kulikuwa na Mwethiopia mmoja, towashi, ambaye alikuwa anasafiri kuelekea nyumbani. Huyo mtu alikuwa ofisa maarufu wa hazina ya Kandake, malkia wa Ethiopia. Alikuwa amekwenda huko Yerusalemu kuabudu na wakati huo alikuwa anarudi akiwa amepanda gari la kukokotwa.'),
(2017874,69,44,8,28,'Alipokuwa anasafiri, alikuwa akijisomea kitabu cha nabii Isaya.'),
(2017875,69,44,8,29,'Basi, Roho Mtakatifu akamwambia Filipo, "Nenda karibu na gari hilo ukafuatane nalo."'),
(2017876,69,44,8,30,'Filipo akakimbilia karibu na gari, akamsikia huyo mtu akisoma katika kitabu cha nabii Isaya. Hapo Filipo akamwuliza, "Je, unaelewa hayo unayosoma?"'),
(2017877,69,44,8,31,'Huyo mtu akamjibu, "Ninawezaje kuelewa bila mtu kunielewesha?" Hapo akamwalika Filipo apande juu, aketi pamoja naye.'),
(2017878,69,44,8,32,'Basi, sehemu ya Maandiko Matakatifu aliyokuwa anasoma ilikuwa hii: "Alikuwa kama kondoo anayepelekwa kuchinjwa; kimya kama vile mwana kondoo anaponyolewa manyoya, yeye naye hakutoa sauti hata kidogo.'),
(2017879,69,44,8,33,'Alifedheheshwa na kunyimwa haki. Hakuna atakayeweza kuongea juu ya kizazi chake, kwa maana maisha yake yameondolewa duniani."'),
(2017880,69,44,8,34,'Huyo Mwethiopia akamwambia Filipo, "Niambie, huyu nabii anasema juu ya nani? Anasema mambo haya juu yake yeye mwenyewe au juu ya mtu mwingine?"'),
(2017881,69,44,8,35,'Basi, Filipo akianzia na sehemu hiyo ya Maandiko Matakatifu, akamweleza Habari Njema juu ya Yesu.'),
(2017882,69,44,8,36,'Walipokuwa bado wanaendelea na safari walifika mahali penye maji na huyo ofisa akasema, "Mahali hapa pana maji; je, kuna chochote cha kunizuia nisibatizwe?"*fa*'),
(2017883,69,44,8,37,'missing'),
(2017884,69,44,8,38,'Basi, huyo ofisa akaamuru lile gari lisimame; na wote wawili, Filipo na huyo ofisa wakashuka majini, naye Filipo akambatiza.'),
(2017885,69,44,8,39,'Walipotoka majini Roho wa Bwana akamfanya Filipo atoweke. Na huyo Mwethiopia hakumwona tena; lakini akaendelea na safari yake akiwa amejaa furaha.'),
(2017886,69,44,8,40,'Filipo akajikuta yuko Azoto, akapita katika miji yote akihubiri Habari Njema mpaka alipofika Kaisarea. kubatizwa." Naye akajibu, "Naam, ninaamini kwamba Yesu Kristo ni Mwana wa Mungu."'),
(2017887,69,44,9,1,'Wakati huo Saulo alikuwa akizidisha vitisho vikali vya kuwaua wafuasi wa Bwana. Alikwenda kwa Kuhani Mkuu,'),
(2017888,69,44,9,2,'akaomba apatiwe barua za utambulisho kwa masunagogi ya Kiyahudi kule Damasko, ili akikuta huko wanaume au wanawake wanaofuata Njia ya Bwana, awakamate na kuwaleta Yerusalemu.'),
(2017889,69,44,9,3,'Lakini alipokuwa njiani karibu kufika Damasko, ghafla mwanga kutoka angani ulimwangazia pande zote.'),
(2017890,69,44,9,4,'Akaanguka chini na kusikia sauti ikimwambia: "Saulo, Saulo! Kwa nini unanitesa?"'),
(2017891,69,44,9,5,'Naye Saulo akauliza, "Ni nani wewe Bwana?" Na ile sauti ikajibu, "Mimi ni Yesu ambaye wewe unamtesa.'),
(2017892,69,44,9,6,'Lakini simama sasa, uingie mjini na huko utaambiwa unachopaswa kufanya."'),
(2017893,69,44,9,7,'Wale watu waliokuwa wanasafiri pamoja na Saulo walisimama pale, wakiwa hawana la kusema; walisikia ile sauti lakini hawakumwona mtu.'),
(2017894,69,44,9,8,'Saulo aliinuka, na alipofumbua macho yake hakuweza kuona chochote; hivyo wale watu wakamwongoza kwa kumshika mkono mpaka mjini Damasko.'),
(2017895,69,44,9,9,'Saulo alikaa siku tatu bila kuona, na wakati huo hakula au kunywa chochote.'),
(2017896,69,44,9,10,'Basi, huko Damasko kulikuwa na mfuasi mmoja aitwaye Anania. Bwana akamwambia katika maono, "Anania!" Anania akaitika, "Niko hapa, Bwana."'),
(2017897,69,44,9,11,'Naye Bwana akamwambia, "Jitayarishe uende kwenye barabara inayoitwa Barabara ya Moja kwa Moja, na katika nyumba ya Yuda umtake mtu mmoja kutoka Tarso aitwaye Saulo. Sasa anasali;'),
(2017898,69,44,9,12,'na katika maono ameona mtu aitwaye Anania akiingia ndani na kumwekea mikono ili apate kuona tena."'),
(2017899,69,44,9,13,'Lakini Anania akajibu, "Bwana, nimesikia habari za mtu huyu kutoka kwa watu wengi; nimesikia juu ya mabaya aliyowatendea watu wako huko Yerusalemu.'),
(2017900,69,44,9,14,'Na amekuja hapa akiwa na mamlaka kutoka kwa makuhani wakuu kuwatia nguvuni wote wanaoomba kwa jina lako."'),
(2017901,69,44,9,15,'Lakini Bwana akamwambia, "Nenda tu, kwa maana nimemchagua awe chombo changu, alitangaze jina langu kwa mataifa na wafalme wao na kwa watu wa Israeli.'),
(2017902,69,44,9,16,'Mimi mwenyewe nitamwonyesha mengi yatakayomlazimu kuteswa kwa ajili ya jina langu."'),
(2017903,69,44,9,17,'Basi, Anania akaenda, akaingia katika hiyo nyumba. Kisha akaweka mikono yake juu ya Saulo, akasema, "Ndugu Saulo, Bwana ambaye ndiye Yesu mwenyewe aliyekutokea ulipokuwa njiani kuja hapa, amenituma ili upate kuona tena na kujazwa Roho Mtakatifu."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017904,69,44,9,18,'Mara vitu kama magamba vikaanguka kutoka macho ya Saulo, akaweza kuona tena. Akasimama, akabatizwa.'),
(2017905,69,44,9,19,'Na baada ya kula chakula, nguvu zake zikamrudia. Saulo alikaa siku chache pamoja na wafuasi huko Damasko.'),
(2017906,69,44,9,20,'Mara alianza kuhubiri katika masunagogi kwamba Yesu ni Mwana wa Mungu.'),
(2017907,69,44,9,21,'Watu wote waliomsikia walishangaa, wakasema, "Je, mtu huyu si yuleyule aliyewaua wale waliokuwa wanaomba kwa jina hili kule Yerusalemu? Tena alikuja hapa akiwa na madhumuni ya kuwatia nguvuni watu hao na kuwapeleka kwa makuhani!"'),
(2017908,69,44,9,22,'Saulo alizidi kupata nguvu, na kwa jinsi alivyothibitisha wazi kwamba Yesu ndiye Kristo, Wayahudi wa huko Damasko walivurugika kabisa.'),
(2017909,69,44,9,23,'Baada ya siku nyingi kupita, Wayahudi walikusanyika na kufanya mpango wa kumwua Saulo.'),
(2017910,69,44,9,24,'Lakini Saulo alipata habari ya mpango huo. Usiku na mchana walilinda milango ya kuingia mjini ili wapate kumwua.'),
(2017911,69,44,9,25,'Lakini wakati wa usiku wanafunzi wake walimchukua, wakamteremsha chini ndani ya kapu kubwa kwa kupitia nafasi iliyokuwako ukutani. ic'),
(2017912,69,44,9,26,'Saulo alipofika Yerusalemu alijaribu kujiunga na wale wanafunzi. Lakini wote walimwogopa, na hawakuweza kuamini kwamba yeye amekuwa mfuasi.'),
(2017913,69,44,9,27,'Hapo, Barnaba alikuja akamchukua Saulo, akampeleka kwa mitume na kuwaeleza jinsi Saulo alivyomwona Bwana njiani na jinsi Bwana alivyoongea naye. Aliwaambia pia jinsi Saulo alivyokuwa amehubiri bila uoga kule Damasko.'),
(2017914,69,44,9,28,'Basi, Saulo alikaa pamoja nao, akatembelea Yerusalemu yote akihubiri neno la Bwana bila hofu.'),
(2017915,69,44,9,29,'Pia aliongea na kubishana na Wayahudi wasemao Kigiriki, lakini wao walijaribu kumwua.'),
(2017916,69,44,9,30,'Wale ndugu walipogundua jambo hilo walimchukua Saulo, wakampeleka Kaisarea, wakamwacha aende zake Tarso.'),
(2017917,69,44,9,31,'Wakati huo kanisa likawa na amani popote katika Yudea, Galilaya, na Samaria. Lilijengwa na kukua katika kumcha Bwana, na kuongezeka likitiwa moyo na Roho Mtakatifu.'),
(2017918,69,44,9,32,'Petro alipokuwa anasafirisafiri kila mahali alifika pia kwa watu wa Mungu waliokuwa wanaishi Luda.'),
(2017919,69,44,9,33,'Huko alimkuta mtu mmoja aitwaye Enea ambaye kwa muda wa miaka minane alikuwa amelala kitandani kwa sababu alikuwa amepooza.'),
(2017920,69,44,9,34,'Basi, Petro akamwambia, "Enea, Yesu Kristo anakuponya. Amka utandike kitanda chako." Enea akaamka mara.'),
(2017921,69,44,9,35,'Wakazi wote wa Luda na Saroni walimwona Enea, na wote wakamgeukia Bwana.'),
(2017922,69,44,9,36,'Kulikuwa na mfuasi mmoja mwanamke mjini Yopa aitwaye Tabitha (kwa Kigiriki ni Dorka, maana yake, Paa). Huyo mwanamke alikuwa akitenda mema na kuwasaidia maskini daima.'),
(2017923,69,44,9,37,'Wakati huo ikawa kwamba aliugua, akafa. Watu wakauosha mwili wake, wakauzika katika chumba ghorofani.'),
(2017924,69,44,9,38,'Yopa si mbali sana na Luda; kwa hiyo wafuasi waliposikia kwamba Petro alikuwa Luda, wakawatuma watu wawili kwake na ujumbe: "Njoo kwetu haraka iwezekanavyo."'),
(2017925,69,44,9,39,'Basi, Petro akaenda pamoja nao. Alipofika alipelekwa ghorofani katika kile chumba. Huko wajane wengi walimzunguka Petro wakilia na kumwonyesha makoti na nguo ambazo Dorka alikuwa akitengeneza wakati alipokuwa hai.'),
(2017926,69,44,9,40,'Petro aliwatoa nje wote, akapiga magoti, akasali. Kisha akamgeukia yule maiti, akasema, "Tabitha, amka" Naye akafumbua macho yake na alipomwona Petro, akaketi.'),
(2017927,69,44,9,41,'Petro akamsaidia kusimama, halafu akawaita wale watu wa Mungu na wale wajane, akamkabidhi kwao akiwa mzima.'),
(2017928,69,44,9,42,'Habari ya tukio hili ilienea kila mahali huko Yopa, na watu wengi wakamwamini Bwana.'),
(2017929,69,44,9,43,'Petro alikaa siku kadhaa huko Yopa, akiishi kwa mtu mmoja mtengenezaji wa ngozi aitwaye Simoni.'),
(2017930,69,44,10,1,'Kulikuwa na mtu mmoja huko Kaisarea aitwaye Kornelio, Jemadari wa kikosi kimoja kiitwacho "Kikosi cha Italia."'),
(2017931,69,44,10,2,'Alikuwa mtu mwema; naye pamoja na jamaa yake yote walimcha Mungu; alikuwa anafanya mengi kusaidia maskini wa Kiyahudi na alikuwa anasali daima.'),
(2017932,69,44,10,3,'Yapata saa tisa mchana, aliona dhahiri katika maono malaika wa Mungu akiingia ndani na kumwambia, "Kornelio!"'),
(2017933,69,44,10,4,'Kornelio alimkodolea macho huyo malaika kwa hofu, akamwambia, "Kuna nini Mheshimiwa?" Huyo malaika akamwambia, "Mungu amezipokea sala na sadaka zako kwa maskini.'),
(2017934,69,44,10,5,'Sasa, watume watu Yopa wakamwite mtu mmoja aitwaye Simoni, kwa jina lingine Petro.'),
(2017935,69,44,10,6,'Yeye yumo nyumbani kwa Simoni mtengenezaji wa ngozi ambaye nyumba yake iko karibu na bahari."'),
(2017936,69,44,10,7,'Huyo malaika aliyesema hayo alipokwisha kwenda zake, Kornelio aliwaita watumishi wawili wa nyumbani na mmoja wa askari zake ambaye alikuwa mcha Mungu,'),
(2017937,69,44,10,8,'akawaeleza yote yaliyotukia, akawatuma Yopa.'),
(2017938,69,44,10,9,'Kesho yake, hao watu watatu wakiwa bado safarini, lakini karibu kufika Yopa, Petro alipanda juu ya paa la nyumba yapata saa sita mchana ili kusali.'),
(2017939,69,44,10,10,'Aliona njaa, akatamani kupata chakula. Chakula kilipokuwa kinatayarishwa, alipatwa na usingizi mzito akaona maono.'),
(2017940,69,44,10,11,'Aliona mbingu zimefunguliwa na kitu kama shuka kubwa inateremshwa chini ikiwa imeshikwa pembe zake nne.'),
(2017941,69,44,10,12,'Ndani ya shuka hiyo kulikuwa na kila aina ya wanyama: wanyama wenye miguu minne, wanyama watambaao na ndege wa angani.'),
(2017942,69,44,10,13,'Akasikia sauti ikimwambia: "Petro, amka uchinje, ule!"'),
(2017943,69,44,10,14,'Petro akajibu, "La, Bwana; mimi sijaonja kamwe chochote ambacho ni najisi au kichafu."'),
(2017944,69,44,10,15,'Ile sauti ikasikika tena ikimwambia: "Usiviite najisi vitu ambavyo Mungu amevitakasa!"'),
(2017945,69,44,10,16,'Jambo hili lilifanyika mara tatu, kisha ile shuka ikarudishwa juu mbinguni.'),
(2017946,69,44,10,17,'Petro alipokuwa bado anashangaa juu ya maana ya hilo maono alilokuwa ameliona, wale watu waliotumwa na Kornelio, baada ya kuigundua nyumba ya Simoni, walifika mlangoni,'),
(2017947,69,44,10,18,'Wakaita kwa sauti: "Je, kuna mgeni humu aitwaye Simoni Petro?"'),
(2017948,69,44,10,19,'Petro alikuwa bado anajaribu kuelewa lile maono, na hapo Roho akamwambia, "Sikiliza! kuna watu watatu hapa, wanakutafuta.'),
(2017949,69,44,10,20,'Shuka upesi na wala usisite kwenda pamoja nao kwa maana ni mimi niliyewatuma."'),
(2017950,69,44,10,21,'Basi, Petro akateremka chini, akawaambia hao watu, "Mimi ndiye mnayemtafuta. Kwa nini mmekuja?"'),
(2017951,69,44,10,22,'Wao wakamjibu, "Jemadari Kornelio ambaye ni mtu mwema, mcha Mungu na mwenye kuheshimika mbele ya Wayahudi wote ametutuma. Aliambiwa na malaika mtakatifu akualike nyumbani kwake ili asikilize chochote ulicho nacho cha kusema."'),
(2017952,69,44,10,23,'Petro akawaalika ndani, akawapa mahali pa kulala usiku ule. Kesho yake, Petro alianza safari pamoja nao, na baadhi ya ndugu wa huko Yopa walifuatana naye.'),
(2017953,69,44,10,24,'Siku ya pili yake, walifika Kaisarea na huko Kornelio alikuwa anawangojea pamoja na jamaa na marafiki aliokuwa amewaalika.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2017954,69,44,10,25,'Petro alipokuwa anaingia, Kornelio alitoka nje kumlaki, akapiga magoti mbele yake na kuinama chini kabisa.'),
(2017955,69,44,10,26,'Lakini Petro alimwinua, akamwambia, "Simama, kwa maana mimi ni binadamu tu."'),
(2017956,69,44,10,27,'Petro aliendelea kuongea na Kornelio wakiwa wanaingia nyumbani ambamo aliwakuta watu wengi wamekusanyika.'),
(2017957,69,44,10,28,'Petro akawaambia, "Ninyi wenyewe mnajua kwamba Myahudi yeyote amekatazwa na Sheria yake ya dini kushirikiana na watu wa mataifa mengine. Lakini Mungu amenijulisha nisimfikirie mtu yeyote kuwa najisi au mchafu.'),
(2017958,69,44,10,29,'Kwa sababu hiyo, mliponiita nimekuja bila kusita. Basi, nawaulizeni: kwa nini mmeniita?"'),
(2017959,69,44,10,30,'Kornelio akasema, "Siku tatu zilizopita saa kama hii, saa tisa alasiri, nilikuwa nikisali chumbani mwangu. Ghafla, mtu aliyekuwa amevaa mavazi yenye kun`gaa alisimama mbele yangu,'),
(2017960,69,44,10,31,'akasema: `Kornelio! Sala yako na sadaka zako kwa maskini vimekubaliwa na Mungu.'),
(2017961,69,44,10,32,'Mtume mtu Yopa akamwite mtu mmoja aitwaye Simoni, kwa jina lingine Petroi; yuko nyumbani kwa Simoni mtengenezaji wa ngozi karibu na bahari.`'),
(2017962,69,44,10,33,'Kwa hiyo nilikutumia ujumbe bila kuchelewa, nawe umefanya vyema kuja. Sasa, sisi tuko mbele ya Mungu, kusikiliza chochote ambacho bwana amekuamuru kusema."'),
(2017963,69,44,10,34,'Hapo Petro akaanza kusema: "Sasa nimetambua kwamba hakika Mungu hana ubaguzi.'),
(2017964,69,44,10,35,'Mtu wa taifa lolote anayemcha Mungu na kutenda haki anapokelewa naye.'),
(2017965,69,44,10,36,'Huu ndio ule ujumbe Mungu alioupeleka kwa watu wa Israeli, akitangaza Habari Njema iletayo amani kwa njia ya Yesu Kristo ambaye ni Bwana wa wote.'),
(2017966,69,44,10,37,'Ninyi mnajua jambo lililotukia katika nchi yote ya Wayahudi kuanzia Galilaya baada ya ule ubatizo aliohubiri Yohane.'),
(2017967,69,44,10,38,'Mnajua Yesu wa Nazareti na jinsi Mungu alivyomteua kwa kummiminia Roho Mtakatifu na nguvu. Mungu alikuwa pamoja naye; yeye alikwenda huko na huko akitenda mema na kuwaponya wote waliokuwa wamevamiwa na Ibilisi.'),
(2017968,69,44,10,39,'Sisi ni mashahidi wa mambo yote aliyotenda katika nchi ya Wayahudi na katika Yerusalemu. Walimuua kwa kumtundika msalabani;'),
(2017969,69,44,10,40,'lakini Mungu alimfufua siku ya tatu, akamfanya aonekane'),
(2017970,69,44,10,41,'si kwa watu wote ila kwa wale Mungu aliokwisha wachagua wawe mashahidi wake, yaani sisi tuliokula na kunywa pamoja naye baada ya kufufuka kwake kutoka wafu.'),
(2017971,69,44,10,42,'Alituamuru kuihubiri Habari Njema kwa watu wote na kushuhudia kwamba yeye ndiye aliyeteuliwa na Mungu awe Mwamuzi wa wazima na wafu.'),
(2017972,69,44,10,43,'Manabii wote waliongea juu yake kwamba kila mtu atakayemwamini atasamehewa dhambi zake zote kwa jina lake."'),
(2017973,69,44,10,44,'Wakati Petro alipokuwa bado anasema maneno hayo, Roho Mtakatifu aliwashukia wote waliokuwa wanasikiliza ujumbe huo.'),
(2017974,69,44,10,45,'Wale Wayahudi waumini waliokuja pamoja na Petro kutoka Yopa walishangaa kuona kuwa Mungu aliwamiminia zawadi ya Roho Mtakatifu watu wa mataifa mengine pia;'),
(2017975,69,44,10,46,'maana waliwasikia wakiongea kwa lugha mbalimbali wakimtukuza Mungu. Hapo Petro akasema,'),
(2017976,69,44,10,47,'"Watu hawa wamempokea Roho Mtakatifu kama sisi wenyewe tulivyompokea. Je, kuna yeyote atakayeweza kuwazuia wasibatizwe kwa maji?"'),
(2017977,69,44,10,48,'Basi, akaamuru wabatizwe kwa jina la Yesu Kristo. Kisha wakamwomba akae nao kwa siku chache.'),
(2017978,69,44,11,1,'Mitume na ndugu kule Yudea walisikia kwamba watu wa mataifa mengine pia walikuwa wamelipokea neno la Mungu.'),
(2017979,69,44,11,2,'Basi, Petro aliporudi Yerusalemu, wale Wayahudi waumini waliopendelea watu wa mataifa mengine watahiriwe, walimlaumu wakisema:'),
(2017980,69,44,11,3,'"Wewe umekwenda kukaa na watu wasiotahiriwa na hata umekula pamoja nao!'),
(2017981,69,44,11,4,'Hapo Petro akawaeleza kinaganaga juu ya yale yaliyotendeka tangu mwanzo:'),
(2017982,69,44,11,5,'"Siku moja nikiwa nasali mjini Yopa, niliona maono; niliona kitu kama shuka kubwa likishushwa chini kutoka mbinguni likiwa limeshikwa pembe zake nne, likawekwa kando yangu.'),
(2017983,69,44,11,6,'Nilichungulia ndani kwa makini nikaona wanyama wenye miguu minne, wanyama wa mwituni, wanyama watambaao na ndege wa angani.'),
(2017984,69,44,11,7,'Kisha nikasikia sauti ikiniambia: `Petro amka, chinja, ule.`'),
(2017985,69,44,11,8,'Lakini mimi nikasema: `La, Bwana; maana chochote kilicho najisi au kichafu hakijapata kamwe kuingia kinywani mwangu.`'),
(2017986,69,44,11,9,'Ile sauti ikasikika tena kutoka mbinguni: `Usiviite najisi vitu ambavyo Mungu amevitakasa.`'),
(2017987,69,44,11,10,'Jambo hilo lilifanyika mara tatu, na mwishowe vyote vilirudishwa juu mbinguni.'),
(2017988,69,44,11,11,'Ghafla, watu watatu waliokuwa wametumwa kwangu kutoka Kaisarea waliwasili kwenye nyumba niliyokuwa nakaa.'),
(2017989,69,44,11,12,'Roho aliniambia niende pamoja nao bila kusita. Hawa ndugu sita waliandamana nami pia kwenda Kaisarea na huko tuliingia nyumbani mwa Kornelio.'),
(2017990,69,44,11,13,'Yeye alitueleza jinsi alivyokuwa amemwona malaika amesimama nyumbani mwake na kumwambia: `Mtume mtu Yopa akamwite mtu mmoja aitwaye Simoni, kwa jina lingine Petro.'),
(2017991,69,44,11,14,'Yeye atakuambia maneno ambayo kwayo wewe na jamaa yako yote mtaokolewa.`'),
(2017992,69,44,11,15,'Na nilipoanza tu kuongea, Roho Mtakatifu aliwashukia kama alivyotushukia sisi pale awali.'),
(2017993,69,44,11,16,'Hapo nilikumbuka yale maneno Bwana aliyosema: `Yohane alibatiza kwa maji, lakini ninyi mtabatizwa kwa Roho Mtakatifu.`'),
(2017994,69,44,11,17,'Basi, kama Mungu amewapa pia watu wa mataifa mengine zawadi ileile aliyotupa sisi tulipomwamini Bwana Yesu Kristo, je, mimi ni nani hata nijaribu kumpinga Mungu?"'),
(2017995,69,44,11,18,'Waliposikia hayo, waliacha ubishi, wakamtukuza Mungu wakisema, "Mungu amewapa watu wa mataifa mengine nafasi ya kutubu na kuwa na uzima!"'),
(2017996,69,44,11,19,'Kutokana na mateso yaliyotokea wakati Stefano alipouawa, waumini walitawanyika. Wengine walikwenda mpaka Foinike, Kupro na Antiokia wakihubiri ule ujumbe kwa Wayahudi tu.'),
(2017997,69,44,11,20,'Lakini baadhi ya waumini waliotoka Kupro na Kurene, walikwenda Antiokia wakautangaza huo ujumbe kwa watu wa mataifa mengine wakiwahubiria ile Habari Njema juu ya Bwana Yesu.'),
(2017998,69,44,11,21,'Bwana aliwasaidia na idadi kubwa ya watu iliamini na kumgeukia Bwana.'),
(2017999,69,44,11,22,'Habari ya jambo hilo ikasikika kwa lile kanisa la Yerusalemu. Hivyo wakamtuma Barnaba aende Antiokia.'),
(2018000,69,44,11,23,'Alipofika huko na kuona jinsi Mungu alivyowaneemesha wale watu, alifurahi na kuwahimiza wote wadumu katika uaminifu wao kwa Bwana.'),
(2018001,69,44,11,24,'Barnaba alikuwa mtu mwema na mwenye kujaa Roho Mtakatifu na imani. Kundi kubwa la watu lilivutwa kwa Bwana.'),
(2018002,69,44,11,25,'Kisha, Barnaba alikwenda Tarso kumtafuta Saulo'),
(2018003,69,44,11,26,'Alipompata, alimleta Antiokia. Nao wote wawili walikaa na lile kanisa kwa mwaka wote mzima wakifundisha kundi kubwa la watu. Huko Antiokia, ndiko, kwa mara ya kwanza, wafuasi waliitwa Wakristo. ic');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018004,69,44,11,27,'Wakati huohuo, manabii kadhaa walikuja Antiokia kutoka Yerusalemu.'),
(2018005,69,44,11,28,'Basi, mmoja wao aitwaye Agabo alisimama, na kwa uwezo wa Roho akabashiri kwamba kutakuwa na njaa kubwa katika nchi yote (Njaa hiyo ilitokea wakati Klaudio alipokuwa akitawala).'),
(2018006,69,44,11,29,'Wale wanafunzi waliamua kila mmoja kwa kadiri ya uwezo wake apeleke chochote ili kuwasaidia wale ndugu waliokuwa wanaishi Yudea.'),
(2018007,69,44,11,30,'Basi, wakafanya hivyo na kupeleka mchango wao kwa wazee wa kanisa kwa mikono ya Barnaba na Saulo.'),
(2018008,69,44,12,1,'Karibu wakati huohuo, mfalme Herode alianza kuwatesa baadhi ya Wakristo.'),
(2018009,69,44,12,2,'Alimwua kwa upanga Yakobo ndugu yake Yohane.'),
(2018010,69,44,12,3,'Alipoona kuwa kitendo hiki kiliwapendeza Wayahudi, aliendelea, akamkamata Petro. (Hiyo ilifanyika wakati wa sikukuu ya Mikate Isiyotiwa chachu.)'),
(2018011,69,44,12,4,'Baada ya kutiwa nguvuni, Petro alifungwa gerezani, akawekwa chini ya ulinzi wa vikundi vinne vya askari wannewanne. Herode alikusudia kumtoa hadharani baada ya sikukuu ya Pasaka.'),
(2018012,69,44,12,5,'Basi, Petro alipokuwa gerezani, kanisa lilikuwa linamwombea kwa Mungu kwa moyo.'),
(2018013,69,44,12,6,'Usiku, kabla ya siku ile ambayo Herode angemtoa Petro hadharani, Petro alikuwa amelala kati ya askari wawili. Alikuwa amefungwa minyororo miwili, na walinzi walikuwa wanalinda lango la gereza.'),
(2018014,69,44,12,7,'Ghafla, malaika wa Bwana akasimama karibu naye na mwanga ukaangaza kile chumba cha gereza. Malaika akamgusa akisema, "Amka upesi!" Mara ile minyororo ikaanguka kutoka katika mikono yake.'),
(2018015,69,44,12,8,'Malaika akamwambia, "Jifunge mshipi wako, vaa viatu vyako." Akafanya hivyo. Kisha huyo malaika akamwambia, "Vaa koti lako, unifuate."'),
(2018016,69,44,12,9,'Petro akamfuata nje lakini hakujua kama hayo yaliyofanywa na huyo malaika yalikuwa ya kweli; alidhani alikuwa anaota ndoto.'),
(2018017,69,44,12,10,'Walipita kituo cha kwanza cha ulinzi na cha pili, halafu wakafika kwenye mlango wa chuma wa kuingilia mjini. Huo mlango ukawafungukia wenyewe, nao wakatoka nje. Wakawa wanatembea katika barabara moja na mara yule malaika akamwacha Petro peke yake.'),
(2018018,69,44,12,11,'Hapo ndipo Petro alipotambua yaliyotukia, akasema, "Sasa najua kwa hakika kwamba Bwana amemtuma malaika wake akaniokoa kutoka katika mkono wa Herode na kutoka katika mambo yale yote watu wa Israeli waliyotazamia."'),
(2018019,69,44,12,12,'Alipotambua hivyo alikwenda moja kwa moja mpaka nyumbani kwa Maria mama yake Yohane aitwaye Marko. Humo watu wengi walikuwa wamekusanyika wakisali.'),
(2018020,69,44,12,13,'Petro alibisha mlango wa nje na mtumishi mmoja msichana aitwaye Roda, akaenda mlangoni kuitikia.'),
(2018021,69,44,12,14,'Huyo msichana aliitambua sauti ya Petro akafurahi mno, hata badala ya kuufungua ule mlango, akakimbilia ndani na kuwaambia kwamba Petro alikuwa amesimama nje mlangoni.'),
(2018022,69,44,12,15,'Wakamwambia yule msichana, "Una wazimu!" Lakini yeye akasisitiza kwamba ilikuwa kweli. Nao wakamwambia, "Huyo ni malaika wake."'),
(2018023,69,44,12,16,'Wakati huo Petro alikuwa anaendelea kupiga hodi. Mwishowe walifungua mlango, wakamwona, wakashangaa.'),
(2018024,69,44,12,17,'Petro aliwaashiria kwa mkono wakae kimya, akawaeleza jinsi Bwana alivyomtoa gerezani. Kisha akawaambia watoe taarifa ya jambo hilo kwa Yakobo na wale ndugu wengine, halafu akatoka akaenda mahali pengine.'),
(2018025,69,44,12,18,'Kulipokucha, ulitokea wasiwasi mkubwa kati ya wale askari kuhusu yaliyokuwa yamempata Petro.'),
(2018026,69,44,12,19,'Herode aliamuru ufanywe msako lakini hawakuweza kumpata. Hivyo aliamuru wale askari wahojiwe, akatoa amri wauawe. Halafu akatoka huko Yudea akaenda Kaisarea ambako alikaa.'),
(2018027,69,44,12,20,'Herode alikasirishwa sana na watu wa Tiro na Sidoni. Lakini wao walimpelekea wajumbe. Nao wakafaulu kwanza kumpata Blasto awe upande wao. Blasto alikuwa msimamizi mkuu wa ikulu ya mfalme. Kisha, wakamwendea Herode wakamwomba kuwe na amani, kwa maana nchi yao ilitegemea nchi ya mfalme kwa chakula.'),
(2018028,69,44,12,21,'Siku moja iliyochaguliwa, Herode akiwa amevaa mavazi rasmi na kuketi katika kiti cha kifalme aliwahutubia watu.'),
(2018029,69,44,12,22,'Wale watu walimpigia kelele za shangwe wakisema, "Hii ni sauti ya mungu, si ya mtu."'),
(2018030,69,44,12,23,'Papo hapo malaika wa Bwana akamwangusha Herode chini kwa sababu hakumpa Mungu hizo sifa. Akaliwa na wadudu, akafa.'),
(2018031,69,44,12,24,'Neno la Mungu likazidi kuenea na kukua.'),
(2018032,69,44,12,25,'Baada ya Barnaba na Saulo kutekeleza shughuli zao, walitoka tena Yerusalemu wakamchukua Yohane aitwaye pia Marko.'),
(2018033,69,44,13,1,'Katika kanisa la Antiokia kulikuwa na watu wengine waliokuwa manabii na walimu; miongoni mwao akiwa Barnaba, Simoni aitwaye pia Mweusi, Lukio wa Kurene, Manaeni ambaye alikuwa amelelewa pamoja na mfalme Herode, na Saulo.'),
(2018034,69,44,13,2,'Walipokuwa wanafanya ibada yao kwa Bwana na kufunga, Roho Mtakatifu alisema: "Niteulieni Barnaba na Saulo kwa ajili ya kazi niliyowaitia."'),
(2018035,69,44,13,3,'Basi, baada ya kusali na kufunga zaidi, wakawawekea mikono, wakawaacha waende zao.'),
(2018036,69,44,13,4,'Basi, Barnaba na Saulo walipokwisha tumwa na Roho Mtakatifu, walishuka hadi Seleukia, na kutoka huko walipanda meli hadi kisiwa cha Kupro.'),
(2018037,69,44,13,5,'Walipofika Salami walihubiri neno la Mungu katika masunagogi ya Kiyahudi. Yohane (Marko) alikuwa msaidizi wao.'),
(2018038,69,44,13,6,'Walitembea toka upande mmoja wa kisiwa mpaka Pafo upande wa pili, na huko walimkuta mchawi mmoja Myahudi aitwaye Baryesu ambaye alijisingizia kuwa nabii.'),
(2018039,69,44,13,7,'Huyu alikuwa pamoja na Sergio Paulo, mkuu wa kile kisiwa, ambaye alikuwa mtu mwelewa sana. Sergio Paulo aliwaita Barnaba na Saulo ili asikie neno la Mungu.'),
(2018040,69,44,13,8,'Lakini huyo mchawi Elima (kama alivyokuwa anaitwa kwa Kigiriki), alijaribu kuwapinga ili kumzuia huyo mkuu wa kisiwa asije akaigeukia imani ya Kikristo.'),
(2018041,69,44,13,9,'Basi, Saulo ambaye aliitwa pia Paulo, akiwa amejaa Roho Mtakatifu, alimkodolea macho huyo mchawi,'),
(2018042,69,44,13,10,'akasema, "Mdanganyifu wa kupindukia na mlaghai wewe! Wewe ni mtoto wa Ibilisi! Wewe ni adui wa chochote kile kilicho cha kweli; hukomi hata mara moja kujaribu kuzipotosha njia za Bwana zilizonyoka.'),
(2018043,69,44,13,11,'Sasa, mkono wa Bwana utakuadhibu: utakuwa kipofu na hutaweza kuuona mwanga wa jua kwa kitambo." Mara kila kitu kikawa kama ukungu na giza kwake, akaanza kwenda huku na huku akitafuta mtu wa kumshika mkono amwongoze.'),
(2018044,69,44,13,12,'Yule mkuu wa kisiwa alipoona hayo, aliongoka akawa muumini; akastaajabia sana mafundisho aliyosikia juu ya Bwana.'),
(2018045,69,44,13,13,'Kutoka Pafo, Paulo na wenzake walipanda meli wakaenda hadi Perga katika Pamfulia; lakini Yohane (Marko) aliwaacha, akarudi Yerusalemu.'),
(2018046,69,44,13,14,'Lakini wao waliendelea na safari toka Pisga hadi mjini Antiokia Pisidia. Siku ya Sabato waliingia ndani ya Sunagogi, wakakaa.'),
(2018047,69,44,13,15,'Baada ya masomo katika kitabu cha Sheria ya Mose na katika maandiko ya manabii, wakuu wa lile sunagogi waliwapelekea ujumbe huu: "Ndugu, kama mnalo jambo la kuwaambia watu ili kuwapa moyo, semeni."'),
(2018048,69,44,13,16,'Basi, Paulo alisimama, akatoa ishara kwa mkono, akaanza kuongea: "Wananchi wa Israeli na wengine wote mnaomcha Mungu, sikilizeni!'),
(2018049,69,44,13,17,'Mungu wa taifa hili la Israeli aliwateua babu zetu na kuwafanya wawe taifa kubwa walipokuwa ugenini kule Misri. Mungu aliwatoa huko kwa uwezo wake mkuu.'),
(2018050,69,44,13,18,'Aliwavumilia kwa muda wa miaka arobaini kule jangwani.'),
(2018051,69,44,13,19,'Aliyaangamiza mataifa ya nchi ya Kanaani akawapa hao watu wake ile nchi kuwa mali yao.'),
(2018052,69,44,13,20,'Miaka mia nne na hamsini ilipita, halafu akawapatia waamuzi wawaongoze mpaka wakati wa nabii Samweli.'),
(2018053,69,44,13,21,'Hapo wakapendelea kuwa na mfalme, na Mungu akawapa Saulo, mtoto wa Kishi wa kabila la Benyamini, awe mfalme wao kwa muda wa miaka arobaini.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018054,69,44,13,22,'Baada ya kumwondoa Saulo, Mungu alimteua Daudi kuwa mfalme wao. Mungu alionyesha kibali chake kwake akisema: `Nimemwona Daudi mtoto wa Yese; ni mtu anayepatana na moyo wangu; mtu ambaye atatimiza yale yote ninayotaka kuyatenda.`'),
(2018055,69,44,13,23,'Kutokana na ukoo wake mtu huyu, Mungu, kama alivyoahidi, amewapelekea watu wa Israeli Mwokozi, ndiye Yesu.'),
(2018056,69,44,13,24,'Kabla ya kuja kwake Yesu, Yohane alimtangulia akiwahubiria watu wote wa Israeli kwamba ni lazima watubu na kubatizwa.'),
(2018057,69,44,13,25,'Yohane alipokuwa anamaliza ujumbe wake aliwaambia watu: `Mnadhani mimi ni nani? Mimi si yule mnayemtazamia. Huyo anakuja baada yangu na mimi sistahili hata kuzifungua kamba za viatu vyake.`'),
(2018058,69,44,13,26,'"Ndugu, ninyi mlio watoto wa ukoo wa Abrahamu, na wengine wote mnaomcha Mungu! Ujumbe huu wa wokovu umeletwa kwetu.'),
(2018059,69,44,13,27,'Kwa maana wenyeji wa Yerusalemu na wakuu wao hawakumtambua yeye kuwa Mwokozi. Wala hawakuelewa maneno ya manabii yanayosomwa kila Sabato. Hata hivyo, waliyafanya maneno ya manabii yatimie kwa kumhukumu Yesu adhabu ya kifo.'),
(2018060,69,44,13,28,'Ingawa hawakumpata na hatia inayostahili auawe, walimwomba Pilato amhukumu auawe.'),
(2018061,69,44,13,29,'Na baada ya kutekeleza yote yaliyokuwa yameandikwa kumhusu yeye, walimshusha kutoka msalabani, wakamweka kaburini.'),
(2018062,69,44,13,30,'Lakini Mungu alimfufua kutoka wafu.'),
(2018063,69,44,13,31,'Naye, kwa siku nyingi aliwatokea wale waliofuatana naye kutoka Galilaya mpaka Yerusalemu. Hao ndio walio sasa mashahidi wake kwa watu wa Israeli.'),
(2018064,69,44,13,32,'Sisi tumekuja hapa kuwaleteeni Habari Njema: jambo lile Mungu alilowaahidia babu zetu amelitimiza sasa kwa ajili yetu sisi tulio wajukuu wao kwa kumfufua Yesu kutoka wafu. Kama ilivyoandikwa katika zaburi ya pili: `Wewe ni Mwanangu, mimi leo nimekuwa baba yako.`'),
(2018065,69,44,13,33,'[]'),
(2018066,69,44,13,34,'Na juu ya kumfufua kutoka wafu, asipate tena kurudi huko na kuoza, Mungu alisema hivi: `Nitakupa baraka takatifu na za kweli nilizomwahidia Daudi.`'),
(2018067,69,44,13,35,'Naam, na katika sehemu nyingine za zaburi asema: `Hutamwacha Mtakatifu wako aoze.`'),
(2018068,69,44,13,36,'Sasa, Daudi mwenyewe alitimiza mapenzi ya Mungu wakati wake; kisha akafa na kuzikwa karibu na wazee wake, na mwili wake ukaoza.'),
(2018069,69,44,13,37,'Lakini yule ambaye Mungu alimfufua kutoka wafu hakupata kuoza.'),
(2018070,69,44,13,38,'Jueni wazi, ndugu zangu, kwamba ujumbe kuhusu kusamehewa dhambi unahubiriwa kwenu kwa njia ya Yesu Kristo; na ya kwamba kila mmoja anayemwamini Yesu anasamehewa dhambi zote, jambo ambalo halingewezekana kwa njia ya Sheria ya Mose.'),
(2018071,69,44,13,39,'[]'),
(2018072,69,44,13,40,'Jihadharini basi, msije mkapatwa na yale yaliyosemwa na manabii:'),
(2018073,69,44,13,41,'`Sikilizeni enyi wenye madharau, shangaeni mpotee! Kwa maana kitu ninachofanya sasa, nyakati zenu, ni kitu ambacho hamtakiamini hata kama mtu akiwaelezeni."`'),
(2018074,69,44,13,42,'Paulo na Barnaba walipokuwa wanatoka katika ile sunagogi, wale watu waliwaalika waje tena siku ya Sabato iliyofuata, waongee zaidi juu ya mambo hayo.'),
(2018075,69,44,13,43,'Mkutano huo ulipomalizika, Wayahudi wengi na watu wa mataifa mengine waliokuwa wameongokea dini ya Kiyahudi waliwafuata Paulo na Barnaba. Hao mitume waliongea nao, wakawatia moyo waendelee kuishi wakitegemea neema ya Mungu.'),
(2018076,69,44,13,44,'Siku ya Sabato iliyofuata, karibu kila mtu katika ule mji alikuja kusikiliza neno la Bwana.'),
(2018077,69,44,13,45,'Lakini Wayahudi walipoliona hilo kundi la watu walijaa wivu, wakapinga alichokuwa anasema Paulo na kumtukana.'),
(2018078,69,44,13,46,'Hata hivyo, Paulo na Barnaba waliongea kwa uhodari zaidi, wakasema, "Ilikuwa ni lazima neno la Mungu liwafikieni ninyi kwanza; lakini kwa kuwa mmelikataa na kujiona hamstahili uzima wa milele, basi, tunawaacheni na kuwaendea watu wa mataifa mengine.'),
(2018079,69,44,13,47,'Maana Bwana alituagiza hivi: `Nimekuteua wewe uwe mwanga kwa mataifa, uwe njia ya wokovu kwa ulimwengu wote."`'),
(2018080,69,44,13,48,'Watu wa mataifa mengine waliposikia jambo hilo walifurahi, wakausifu ujumbe wa Mungu; na wale waliokuwa wamechaguliwa kupata uzima wa milele, wakawa waumini.'),
(2018081,69,44,13,49,'Neno la Bwana likaenea kila mahali katika sehemu ile.'),
(2018082,69,44,13,50,'Lakini Wayahudi waliwachochea wanawake wa tabaka ya juu wa mataifa mengine ambao walikuwa wacha Mungu, na wanaume maarufu wa mji huo. Wakaanza kuwatesa Paulo na Barnaba, wakawafukuza kutoka katika eneo lao.'),
(2018083,69,44,13,51,'Basi, mitume wakayakung`uta mavumbi yaliyokuwa katika miguu yao kama onyo, kisha wakaenda Ikonio.'),
(2018084,69,44,13,52,'Lakini hao wafuasi walikuwa wamejaa furaha na Roho Mtakatifu.'),
(2018085,69,44,14,1,'Kule Ikonio, mambo yalikuwa kama yalivyokuwa kule Antiokia; Paulo na Barnaba walikwenda katika sunagogi la Wayahudi wakaongea kwa uhodari hata Wayahudi wengi na Wagiriki wakawa waumini.'),
(2018086,69,44,14,2,'Lakini Wayahudi wengine waliokataa kuwa waumini walichochea na kutia chuki katika mioyo ya watu wa mataifa mengine ili wawapinge hao ndugu.'),
(2018087,69,44,14,3,'Paulo na Barnaba waliendelea kukaa huko kwa muda mrefu. Waliongea kwa uhodari juu ya Bwana, naye Bwana akathibitisha ukweli wa ujumbe walioutoa juu ya neema yake, kwa kuwawezesha kutenda miujiza na maajabu.'),
(2018088,69,44,14,4,'Watu wa mji huo waligawanyika: wengine waliwaunga mkono Wayahudi, na wengine walikuwa upande wa mitume.'),
(2018089,69,44,14,5,'Mwishowe, baadhi ya watu wa mataifa mengine na Wayahudi, wakishirikiana na wakuu wao, waliazimu kuwatendea vibaya hao mitume na kuwapiga mawe.'),
(2018090,69,44,14,6,'Mitume walipogundua jambo hilo, walikimbilia Lustra na Derbe, miji ya Lukaonia, na katika sehemu za jirani,'),
(2018091,69,44,14,7,'wakawa wanahubiri Habari Njema huko.'),
(2018092,69,44,14,8,'Kulikuwa na mtu mmoja huko Lustra ambaye alikuwa amelemaa miguu tangu kuzaliwa, na alikuwa hajapata kutembea kamwe.'),
(2018093,69,44,14,9,'Mtu huyo alikuwa anamsikiliza Paulo alipokuwa anahubiri. Paulo alimtazama kwa makini, na alipoona kuwa alikuwa na imani ya kuweza kuponywa,'),
(2018094,69,44,14,10,'akasema kwa sauti kubwa, "Simama wima kwa miguu yako!" Huyo mtu aliyelemaa akainuka ghafla, akaanza kutembea.'),
(2018095,69,44,14,11,'Umati wa watu walipoona alichofanya Paulo, ulianza kupiga kelele kwa lugha ya Kilukaonia: "Miungu imetujia katika sura za binadamu!"'),
(2018096,69,44,14,12,'Barnaba akaitwa Zeu, na Paulo, kwa vile yeye ndiye aliyekuwa anaongea, akaitwa Herme.'),
(2018097,69,44,14,13,'Naye kuhani wa hekalu la Zeu lililokuwa nje ya mji akaleta fahali na shada za maua mbele ya mlango mkuu wa mji, na pamoja na ule umati wa watu akataka kuwatambikia mitume.'),
(2018098,69,44,14,14,'Barnaba na Paulo walipopata habari hiyo waliyararua mavazi yao na kukimbilia katika lile kundi la watu wakisema kwa sauti kubwa:'),
(2018099,69,44,14,15,'"Ndugu, kwa nini mnafanya mambo hayo? Sisi pia ni binadamu kama ninyi. Na, tuko hapa kuwahubirieni Habari Njema, mpate kuziacha hizi sanamu tupu, mkamgeukie Mungu aliye hai, Mungu aliyeumba mbingu na nchi, bahari na vyote vilivyomo.'),
(2018100,69,44,14,16,'Zamani Mungu aliruhusu kila taifa lifanye lilivyopenda.'),
(2018101,69,44,14,17,'Hata hivyo, Mungu hakuacha kujidhihirisha kwa mambo mema anayowatendea: huwanyeshea mvua toka angani, huwapa mavuno kwa wakati wake, huwapa chakula na kuijaza mioyo yenu furaha."'),
(2018102,69,44,14,18,'Ingawa walisema hivyo haikuwa rahisi kuwazuia wale watu wasiwatambikie.'),
(2018103,69,44,14,19,'Lakini Wayahudi kadhaa walikuja kutoka Antiokia na Ikonio, wakawafanya watu wajiunge nao, wakampiga mawe Paulo na kumburuta hadi nje ya mji wakidhani amekwisha kufa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018104,69,44,14,20,'Lakini waumini walipokusanyika na kumzunguka, aliamka akarudi mjini. Kesho yake, yeye pamoja na Barnaba walikwenda Derbe.'),
(2018105,69,44,14,21,'Baada ya Paulo na Barnabas kuhubiri Habari Njema huko Derbe na kupata wafuasi wengi, walifunga safari kwenda Antiokia kwa kupitia Lustra na Ikonio.'),
(2018106,69,44,14,22,'Waliwaimarisha waumini wa miji hiyo na kuwatia moyo wabaki imara katika imani. Wakawaambia, "Ni lazima sisi sote tupitie katika taabu nyingi ili tuingie katika ufalme wa Mungu."'),
(2018107,69,44,14,23,'Waliteua wazee katika kila kanisa kwa ajili ya waumini, na baada ya kusali na kufunga, wakawaweka chini ya ulinzi wa Bwana ambaye walikuwa wanamwamini.'),
(2018108,69,44,14,24,'Baada ya kupitia katika nchi ya Pisidia, walifika Pamfulia.'),
(2018109,69,44,14,25,'Baada ya kuhubiri ule ujumbe huko Perga, walikwenda Atalia.'),
(2018110,69,44,14,26,'Kutoka huko walisafiri kwa meli wakarudi Antiokia ambako hapo awali walikuwa wamewekwa chini ya ulinzi wa neema ya Mungu kwa ajili ya kazi ambayo sasa walikuwa wameitimiza.'),
(2018111,69,44,14,27,'Walipofika huko Antiokia walifanya mkutano wa kanisa la mahali hapo, wakawapa taarifa juu ya mambo Mungu aliyofanya pamoja nao, na jinsi alivyowafungulia mlango watu wa mataifa mengine mlango wa kuingia katika imani.'),
(2018112,69,44,14,28,'Wakakaa pamoja na wale waumini kwa muda mrefu.'),
(2018113,69,44,15,1,'Basi, watu wengine walifika Antiokia kutoka Yudea wakaanza kuwafundisha wale ndugu wakisema, "Kama hamtatahiriwa kufuatana na mapokeo ya Sheria ya Mose, hamtaweza kuokolewa."'),
(2018114,69,44,15,2,'Jambo hili lilisababisha ubishi mkubwa, na baada ya Paulo na Barnaba kujadiliana nao, ikaamuliwa Paulo na Barnaba pamoja na waumini kadhaa wa lile kanisa la Antiokia waende Yerusalemu kuwaona wale mitume na wazee kuhusu jambo hilo.'),
(2018115,69,44,15,3,'Basi, kanisa liliwaaga, nao walipokuwa wanapitia Foinike na Samaria waliwaeleza watu jinsi mataifa mengine yalivyomgeukia Mungu. Habari hizo zikawafurahisha sana ndugu hao wote.'),
(2018116,69,44,15,4,'Walipofika Yerusalemu walikaribishwa na kanisa, mitume na wazee; nao wakawapa taarifa juu ya yote Mungu aliyoyafanya pamoja nao.'),
(2018117,69,44,15,5,'Lakini waumini wengine waliokuwa wa kikundi cha Mafarisayo walisimama, wakasema, "Ni lazima watu wa mataifa mengine watahiriwe na kufundishwa kuifuata Sheria ya Mose."'),
(2018118,69,44,15,6,'Basi, mitume na wazee walifanya mkutano maalum wa kuchunguza jambo hilo.'),
(2018119,69,44,15,7,'Baada ya majadiliano marefu, Petro alisimama, akasema, "Ndugu zangu, ninyi mnafahamu kwamba hapo awali Mungu alipenda kunichagua mimi miongoni mwenu niihubiri Habari Njema, ili watu wa mataifa wapate kusikia na kuamini.'),
(2018120,69,44,15,8,'Naye Mungu anayejua mioyo ya watu, alithibitisha kwamba amewakubali kwa kuwapa nao Roho Mtakatifu kama alivyotupa sisi.'),
(2018121,69,44,15,9,'Hakufanya ubaguzi wowote kati yetu na wao; aliitakasa mioyo yao kwa imani.'),
(2018122,69,44,15,10,'Sasa basi, kwa nini kumjaribu Mungu kwa kuwatwika hao waumini mzigo ambao wala babu zetu, wala sisi hatukuweza kuubeba?'),
(2018123,69,44,15,11,'Isiwe hivyo, ila tunaamini kwamba, sisi kama vile wao, tunaokolewa kwa njia ya neema ya Bwana Yesu."'),
(2018124,69,44,15,12,'Kikundi chote kilikaa kimya, kikawasikiliza Barnaba na Paulo wakieleza miujiza na maajabu ambayo Mungu alitenda kwa mikono yao kati ya watu wa mataifa mengine.'),
(2018125,69,44,15,13,'Walipomaliza kuongea, Yakobo alianza kusema: "Ndugu zangu, nisikilizeni!'),
(2018126,69,44,15,14,'Simoni ameeleza jinsi Mungu hapo awali alivyojishughulisha na watu wa mataifa mengine, akachagua baadhi yao wawe watu wake.'),
(2018127,69,44,15,15,'Jambo hili ni sawa kabisa na maneno ya manabii, kama Maandiko Matakatifu yasemavyo:'),
(2018128,69,44,15,16,'`Baada ya mambo haya nitarudi. Nitaijenga tena ile nyumba ya Daudi iliyoanguka; nitayatengeneza magofu yake na kuijenga tena.'),
(2018129,69,44,15,17,'Hapo watu wengine wote, watu wa mataifa yote niliowaita wawe wangu, watamtafuta Bwana.'),
(2018130,69,44,15,18,'Ndivyo asemavyo Bwana, aliyefanya jambo hili lijulikane tangu kale.`'),
(2018131,69,44,15,19,'"Kwa hiyo, uamuzi wangu ni huu: tusiwataabishe watu wa mataifa wanomgeukia Mungu.'),
(2018132,69,44,15,20,'Bali tuwapelekee barua kuwaambia wasile vyakula vilivyotiwa najisi kwa kutambikiwa sanamu za miungu; wajiepushe na uasherati; wasile mnyama yeyote aliyenyongwa, na wasinywe damu.'),
(2018133,69,44,15,21,'Kwa maana kwa muda mrefu maneno ya Mose yamekuwa yakihubiriwa katika kila mji na kusomwa katika masunagogi yote kila siku ya Sabato." ic'),
(2018134,69,44,15,22,'Mitume, wazee na kanisa lote waliamua kuwachagua watu fulani miongoni mwao na kuwatuma Antiokia pamoja na Paulo na Barnaba. Basi, wakamchagua Yuda aitwaye pia Barsaba, na Sila ambao wote walikuwa wanajulikana zaidi kati ya ndugu.'),
(2018135,69,44,15,23,'Wakawapa barua hii: mataifa mengine mlioko huko Antiokia, Siria na Kilikia.'),
(2018136,69,44,15,24,'Tumesikia kwamba watu wengine kutoka huku kwetu waliwavurugeni kwa maneno yao, wakaitia mioyo yenu katika wasiwasi. Lakini wamefanya hivyo bila ya idhini yoyote kutoka kwetu.'),
(2018137,69,44,15,25,'Hivyo, tumeamua kwa pamoja kuwachagua watu kadhaa na kuwatuma kwenu pamoja na wapenzi wetu Barnaba na Paulo,'),
(2018138,69,44,15,26,'ambao wamehatarisha maisha yao kwa ajili ya jina la Bwana wetu Yesu Kristo.'),
(2018139,69,44,15,27,'Kwa hiyo, tunawatuma Yuda na Sila kwenu; hawa watawaambieni wao wenyewe haya tuliyoandika.'),
(2018140,69,44,15,28,'Basi, Roho Mtakatifu na sisi tumekubali tusiwatwike mzigo zaidi ya mambo haya muhimu:'),
(2018141,69,44,15,29,'Msile vyakula vilivyotambikiwa sanamu; msinywe damu; msile nyama ya mnyama aliyenyongwa; na mjiepushe na uasherati. Mtakuwa mmefanya vema kama mkiepa kufanya mambo hayo. Wasalaam!"'),
(2018142,69,44,15,30,'Baada ya kuwaaga, hao wajumbe walielekea Antiokia ambako waliita mkutano wa waumini, wakawapa hiyo barua.'),
(2018143,69,44,15,31,'Walipoisoma hiyo barua, maneno yake yaliwatia moyo, wakafurahi sana.'),
(2018144,69,44,15,32,'Yuda na Sila, ambao nao walikuwa manabii, walizungumza na hao ndugu kwa muda mrefu wakiwatia moyo na kuwaimarisha.'),
(2018145,69,44,15,33,'Baada ya kukaa huko kwa muda fulani, ndugu wa Antiokia waliwaaga wakiwatakia amani, kisha wakarudi kwa wale waliokuwa wamewatuma.*fb*'),
(2018146,69,44,15,34,'missing'),
(2018147,69,44,15,35,'Paulo na Barnaba walibaki huko Antiokia kwa muda; wakafundisha na kuhubiri neno la Bwana, pamoja na watu wengine wengi.'),
(2018148,69,44,15,36,'Baada ya siku kadhaa, Paulo alimwambia Barnaba, "Turudi tukawatembelee wale ndugu katika kila mji tulikolihubiri neno la Bwana tukajionee jinsi wanavyoendelea."'),
(2018149,69,44,15,37,'Barnaba alitaka wamchukue pia Yohane aitwaye Marko.'),
(2018150,69,44,15,38,'Lakini Paulo hakupendelea kumchukua Marko, ambaye awali aliwaacha kule Pamfulia na kukataa kushiriki katika kazi yao.'),
(2018151,69,44,15,39,'Basi kukatokea ubishi mkali kati yao, na wakaachana. Barnaba akamchukua Marko, wakapanda meli kwenda Kupro.'),
(2018152,69,44,15,40,'Naye Paulo akamchagua Sila, na baada ya ndugu wa mahali hapo kumweka chini ya ulinzi wa neema ya Bwana, akaondoka.'),
(2018153,69,44,15,41,'Katika safari hiyo alipitia Siria na Kilikia akiyaimarisha makanisa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018154,69,44,16,1,'Paulo alifika Derbe na Lustra, ambako aliishi mfuasi mmoja aitwaye Timotheo. Mama yake ambaye pia alikuwa mfuasi, alikuwa Myahudi; lakini baba yake alikuwa Mgiriki.'),
(2018155,69,44,16,2,'Timotheo alikuwa na sifa kubwa kati ya wale ndugu wa Lustra na Ikonio.'),
(2018156,69,44,16,3,'Paulo alitaka Timotheo aandamane naye safarini, kwa hiyo alimtahiri. Alifanya hivyo kwa sababu Wayahudi wote walioishi sehemu hizo walijua kwamba baba yake Timotheo alikuwa Mgiriki.'),
(2018157,69,44,16,4,'Walipokuwa wanapita katika ile miji waliwapa watu yale maagizo yaliyotolewa na mitume na wazee kule Yerusalemu, wakawaambia wayazingatie.'),
(2018158,69,44,16,5,'Hivyo, yale makanisa yalizidi kuwa imara katika imani, na idadi ya waumini ikaongezeka kila siku.'),
(2018159,69,44,16,6,'Walipitia sehemu za Frugia na Galatia kwani Roho Mtakatifu hakuwaruhusu kuhubiri huo ujumbe mkoani Asia.'),
(2018160,69,44,16,7,'Walipofika kwenye mipaka ya Musia, walijaribu kuingia mkoani Bithunia, lakini Roho wa Yesu hakuwaruhusu.'),
(2018161,69,44,16,8,'Basi, walipitia Musia, wakaenda moja kwa moja mpaka Troa.'),
(2018162,69,44,16,9,'Usiku huo, Paulo aliona ono ambalo alimwona mtu mmoja wa Makedonia amesimama pale na kumwomba: "Vuka, uje Makedonia ukatusaidie."'),
(2018163,69,44,16,10,'Mara baada ya Paulo kuona ono hilo, tulijitayarisha kwenda Makedonia bila kukawia, tukiwa na hakika kwamba Mungu ametuita tuwapelekee Habari Njema.'),
(2018164,69,44,16,11,'Kutoka Troa, tulisafiri kwa meli moja kwa moja mpaka Samothrake, na kesho yake tukatia nanga Neapoli.'),
(2018165,69,44,16,12,'Kutoka huko, tulikwenda mpaka Filipi, mji wa wilaya ya kwanza ya Makedonia, na ambao pia ni koloni la Waroma. Tulikaa katika mji huo siku kadhaa.'),
(2018166,69,44,16,13,'Siku ya Sabato tulitoka nje ya mji, tukaenda kando ya mto ambapo tulidhani ya kuwa ni mahali pa kusali. Tuliketi, tukaongea na wanawake waliokusanyika mahali hapo.'),
(2018167,69,44,16,14,'Miongoni mwa wale waliotusikiliza alikuwa mwanamke mmoja mcha Mungu aitwaye Ludia mwenyeji wa Thuatira, ambaye alikuwa mfanyabiashara ya nguo za kitani za rangi ya zambarau. Bwana aliufungua moyo wake hata akayapokea yale maneno Paulo aliyokuwa anasema.'),
(2018168,69,44,16,15,'Baada ya huyo mama pamoja na jamaa yake kubatizwa, alitualika akisema, "Kama kweli mmeona kwamba mimi namwamini Bwana, karibuni nyumbani kwangu mkakae." Akatuhimiza twende.'),
(2018169,69,44,16,16,'Siku moja, tulipokuwa tunakwenda mahali pa kusali, msichana mmoja aliyekuwa na pepo mwenye uwezo wa kuagua alikutana nasi. Msichana huyo alikuwa anawapatia matajiri wake fedha nyingi kwa uaguzi wake.'),
(2018170,69,44,16,17,'Basi, huyo msichana alimfuata Paulo na sisi, akipiga kelele na kusema, "Hawa watu ni watumishi wa Mungu Mkuu. Wanawatangazieni njia ya wokovu."'),
(2018171,69,44,16,18,'Akawa anafanya hivyo kwa siku nyingi hata siku moja Paulo alikasirika, akamgeukia na kumwambia huyo pepo, "Nakuamuru kwa jina la Yesu Kristo, mtoke huyu!" Mara huyo pepo akamtoka.'),
(2018172,69,44,16,19,'Matajiri wa yule msichana walipoona kwamba tumaini lao la kupata mali limekwisha, waliwakamata Paulo na Sila, wakawaburuta mpaka hadharani, mbele ya wakuu.'),
(2018173,69,44,16,20,'Wakawashtaki kwa mahakimu wakisema, "Watu hawa ni Wayahudi na wanafanya fujo katika mji wetu.'),
(2018174,69,44,16,21,'Wanafundisha desturi ambazo sisi raia wa Roma haturuhusiwi kuzikubali wala kuzifuata."'),
(2018175,69,44,16,22,'Kundi la watu likajiunga nao, likawashambulia. Wale mahakimu wakawatatulia Paulo na Sila mavazi yao, wakaamuru wapigwe viboko.'),
(2018176,69,44,16,23,'Baada ya kupigwa sana wakatiwa ndani, na askari wa gereza akaamriwa kuwaweka chini ya ulinzi mkali.'),
(2018177,69,44,16,24,'Kutokana na maagizo hayo, huyo askari aliwaweka katika chumba cha ndani kabisa cha gereza na kuifunga miguu yao kwenye nguzo.'),
(2018178,69,44,16,25,'Karibu na usiku wa manane Paulo na Sila walikuwa wakisali na kuimba nyimbo za kumsifu Mungu, huku wafungwa wengine wakiwa wanasikiliza.'),
(2018179,69,44,16,26,'Ghafla, kulitokea mtetemeko mkuu wa ardhi ambao uliitikisa misingi ya gereza. Mara, milango yote ikafunguka na minyororo iliyowafunga hao wafungwa ikaachana.'),
(2018180,69,44,16,27,'Askari wa gereza alipoamka na kuiona milango ya gereza imefunguliwa, alidhani kwamba wafungwa wote walikuwa wametoroka na hivyo akauchomoa upanga wake, akataka kujiua.'),
(2018181,69,44,16,28,'Lakini Paulo akaita kwa sauti kubwa: "Usijidhuru mwenyewe kwa maana sisi sote tuko hapa."'),
(2018182,69,44,16,29,'Baada ya kumwita mtu alete taa, huyo askari wa gereza alikimbilia ndani, akajitupa mbele ya miguu ya Paulo na Sila huku akitetemeka kwa hofu.'),
(2018183,69,44,16,30,'Halafu aliwaongoza nje, akawauliza, "Waheshimiwa, nifanye nini nipate kuokoka?"'),
(2018184,69,44,16,31,'Wao wakamjibu, "Mwamini Bwana Yesu nawe utaokolewa pamoja na jamaa yako yote."'),
(2018185,69,44,16,32,'Basi, wakamhubiria neno la Bwana yeye pamoja na jamaa yake.'),
(2018186,69,44,16,33,'Yule askari aliwachukua saa ileile ya usiku akawasafisha majeraha yao, kisha yeye na jamaa yake wakabatizwa papo hapo.'),
(2018187,69,44,16,34,'Halafu akawachukua Paulo na Sila nyumbani kwake, akawapa chakula. Yeye na jamaa yake yote wakafanya sherehe kwa vile sasa walikuwa wanamwamini Mungu.'),
(2018188,69,44,16,35,'Kesho yake asubuhi, mahakimu waliwatuma maofisa wao wakisema, "Wafungueni wale watu."'),
(2018189,69,44,16,36,'Yule askari wa gereza alimpasha habari Paulo: "Mahakimu wametuma ujumbe ili mfunguliwe. Sasa mnaweza kutoka na kwenda zenu kwa amani."'),
(2018190,69,44,16,37,'Lakini Paulo alimjibu, "Ati nini? Ingawa hatukuwa na kosa, walitupiga viboko hadharani hali sisi ni raia wa Roma. Tena, walitutia ndani na sasa wanataka kutufungulia kwa siri! Hata kidogo! Ni lazima wao wenyewe waje hapa watufungulie."'),
(2018191,69,44,16,38,'Hao maofisa waliwapasha habari mahakimu juu ya jambo hilo, nao waliposikia kwamba Paulo na Sila walikuwa raia wa Roma, waliogopa.'),
(2018192,69,44,16,39,'Hivyo, walikwenda kuwataka radhi na baada ya kuwatoa ndani waliwaomba watoke katika mji ule.'),
(2018193,69,44,16,40,'Paulo na Sila walitoka gerezani, wakaenda nyumbani kwa Ludia. Huko walionana na ndugu waumini na baada ya kuwatia moyo wakaondoka.'),
(2018194,69,44,17,1,'Kwa kupitia Amfipoli na Apolonia, walisafiri mpaka Thesalonika ambako kulikuwa na sunagogi la Wayahudi.'),
(2018195,69,44,17,2,'Paulo alijiunga nao kama ilivyokuwa desturi yake akajadiliana nao Sabato tatu mfululizo, akatumia Maandiko Matakatifu.'),
(2018196,69,44,17,3,'Aliyaeleza na kuonyesha kwamba ilimbidi Kristo kuteswa na kufufuka kutoka wafu. Akawaambia, "Yesu ambaye mimi namhubiri kwenu ndiye Kristo."'),
(2018197,69,44,17,4,'Baadhi yao walikubali wakajiunga na Paulo na Sila. Kadhalika, idadi kubwa ya Wagiriki waliomcha Mungu pamoja na wanawake wengi wa tabaka la juu, walijiunga nao.'),
(2018198,69,44,17,5,'Lakini Wayahudi wakaona wivu; wakawakodi wafidhuli sokoni, wakafanya kikundi na kuzusha fujo mjini kote. Wakaivamia nyumba ya Yasoni wakitumaini kuwapata humo Paulo na Sila ili wawalete hadharani.'),
(2018199,69,44,17,6,'Lakini hawakuwapata na hivyo walimburuta Yasoni pamoja na ndugu wengine mpaka kwa wakuu wa mji, wakapiga kelele: "Watu hawa wamekuwa wakivuruga dunia yote na sasa wako hapa mjini.'),
(2018200,69,44,17,7,'Yasoni amewakaribisha nyumbani kwake. Wote wanafanya kinyume cha amri ya Kaisari wakisema eti `Kuna mfalme mwingine aitwaye Yesu."`'),
(2018201,69,44,17,8,'Kwa maneno hayo waliwatia wasiwasi wakuu wa mji na kundi la watu.'),
(2018202,69,44,17,9,'Wakawafanya Yasoni na wenzake watoe dhamana, kisha wakawaacha waende zao.'),
(2018203,69,44,17,10,'Usiku, wale ndugu waliwahimiza Paulo na Sila waende Berea. Mara tu walipofika huko, walikwenda katika sunagogi la Wayahudi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018204,69,44,17,11,'Watu wa huko walikuwa wasikivu zaidi kuliko wale wa Thesalonika. Waliupokea ule ujumbe kwa hamu kubwa, wakawa wanayachunguza Maandiko Matakatifu kila siku, ili kuona kama yale waliyosema Paulo na Sila yalikuwa kweli.'),
(2018205,69,44,17,12,'Wengi wao waliamini na pia wanawake wa Kigiriki wa tabaka la juu na wanaume pia.'),
(2018206,69,44,17,13,'Lakini, Wayahudi wa Thesalonika walipogundua kwamba Paulo alikuwa anahubiri neno la Mungu huko Berea, walikwenda huko, wakaanza kufanya fujo na kuchochea makundi ya watu.'),
(2018207,69,44,17,14,'Wale ndugu wakamsindikiza haraka aende pwani lakini Sila na Timotheo walibaki Berea.'),
(2018208,69,44,17,15,'Wale ndugu waliomsindikiza Paulo walikwenda pamoja naye mpaka Athene. Kisha, wakarudi pamoja na maagizo kutoka kwa Paulo kwamba Sila na Timotheo wamfuate upesi iwezekanavyo.'),
(2018209,69,44,17,16,'Paulo alipokuwa anawasubiri Sila na Timotheo huko Athene, moyo wake ulighadhibika sana alipoona jinsi mji huo ulivyokuwa umejaa sanamu za miungu.'),
(2018210,69,44,17,17,'Alijadiliana na Wayahudi na watu wengine waliomcha Mungu katika sunagogi; na kila siku alikuwa na majadiliano sokoni pamoja na wowote wale waliojitokeza.'),
(2018211,69,44,17,18,'Wengine waliofuata falsafa ya Epikuro na Stoiki walibishana naye. Wengine walisema, "Anataka kusema nini huyu bwanamaneno?" Kwa kuwa Paulo alikuwa anahubiri juu ya Yesu na juu ya ufufuo, wengine walisema, "Inaonekana kama anahubiri juu ya miungu ya kigeni."'),
(2018212,69,44,17,19,'Hivyo walimchukua Paulo, wakampeleka Areopago, wakasema, "Tunataka kujua jambo hili jipya ulilokuwa unazungumzia.'),
(2018213,69,44,17,20,'Vitu vingine tulivyosikia kwa masikio yetu vinaonekana kuwa viroja kwetu. Tungependa kujua mambo haya yana maana gani."'),
(2018214,69,44,17,21,'Wananchi wa Athene na wakazi wengine wa huko walikuwa wanatumia wakati wao wote kuhadithiana na kusikiliza habari mpyampya. ic'),
(2018215,69,44,17,22,'Basi, Paulo alisimama mbele ya baraza la Areopago, akasema, "Wananchi wa Athene! Ninaona kwamba ninyi, kwa vyovyote, ni watu wa dini sana.'),
(2018216,69,44,17,23,'Sababu yenyewe ni kwamba katika pitapita yangu niliangalia sanamu zenu za ibada nikakuta madhabahu moja ambayo imeandikwa: `Kwa ajili ya Mungu yule Asiyejulikana.` Basi, huyo mnayemwabudu bila kujua, ndiye ninayemhubiri kwenu.'),
(2018217,69,44,17,24,'Mungu, aliyeumba ulimwengu na vyote vilivyomo, ni Bwana wa mbingu na nchi; yeye hakai katika hekalu zilizojengwa na watu.'),
(2018218,69,44,17,25,'Wala hatumikiwi kwa mikono ya watu kana kwamba anahitaji chochote kile, kwa maana yeye mwenyewe ndiye anayewapa watu uhai, anawawezesha kupumua na anawapa kila kitu.'),
(2018219,69,44,17,26,'Kutokana na mtu mmoja aliumba mataifa yote na kuyawezesha kuishi duniani kote. Aliamua na kupanga kabla kabisa lini na wapi mataifa hayo yangeishi.'),
(2018220,69,44,17,27,'Alifanya hivyo, ili mataifa hayo yapate kumfuata, na kama vile kwa kupapasapapasa, yapate kumfikia. Hata hivyo lakini, Mungu hayuko mbali na kila mmoja wetu.'),
(2018221,69,44,17,28,'Kama alivyosema mtu mmoja: `Ndani yake yeye sisi tunaishi, tunajimudu, na tuko!` Ni kama washairi wenu wengine walivyosema: `Sisi ni watoto wake.`'),
(2018222,69,44,17,29,'Ikiwa basi, sisi ni watoto wa Mungu, haifai kumfikiria Mungu kuwa kama dhahabu, fedha au hata jiwe lililochongwa na kutiwa nakshi na binadamu.'),
(2018223,69,44,17,30,'Mungu alifanya kama kwamba haoni nyakati zile watu walipokuwa wajinga. Lakini sasa, anaamuru watu wote kila mahali watubu.'),
(2018224,69,44,17,31,'Kwa maana amekwisha weka siku ambayo atauhukumu ulimwengu kwa haki kwa njia ya mtu mmoja aliyemteua. Mungu amewathibitishia wote jambo hili kwa kumfufua mtu huyo kutoka wafu!"'),
(2018225,69,44,17,32,'Walipomsikia Paulo anasema juu ya jambo la kufufuka kwa wafu, wengine wao waliangua kicheko; lakini wengine walisema, "Tunataka kukusikia tena juu ya jambo hili!"'),
(2018226,69,44,17,33,'Hivyo, Paulo aliwaacha, akatoka barazani.'),
(2018227,69,44,17,34,'Lakini watu kadhaa waliandamana naye, wakawa waumini. Miongoni mwao walikuwa Dionisio wa Areopago, mwanamke mmoja aitwaye Damari na wengineo.'),
(2018228,69,44,18,1,'Baada ya hayo, Paulo aliondoka Athene, akaenda Korintho.'),
(2018229,69,44,18,2,'Huko Korintho, alimkuta Myahudi mmoja aitwaye Akula, mzaliwa wa Ponto. Akula pamoja na mkewe aitwaye Priskila, walikuwa wamerudi kutoka Italia siku hizohizo kwa sababu Kaisari Klaudio alikuwa ameamuru Wayahudi wote waondoke Roma. Paulo alikwenda kuwaona,'),
(2018230,69,44,18,3,'na kwa vile wao walikuwa mafundi wa kushona mahema kama alivyokuwa yeye, Paulo alikaa nao akafanya kazi.'),
(2018231,69,44,18,4,'Kila Sabato alifanya majadiliano katika sunagogi akijaribu kuwavuta Wayahudi na Wagiriki.'),
(2018232,69,44,18,5,'Baada ya Sila na Timotheo kuwasili kutoka Makedonia, Paulo alianza kutumia wakati wake wote kwa ajili ya kuhubiri, akawathibitishia Wayahudi kwamba Yesu ndiye Kristo.'),
(2018233,69,44,18,6,'Walipompinga na kuanza kumtukana, aliyakung`uta mavazi yake mbele yao akisema, "Mkipotea ni shauri lenu wenyewe; mimi sina lawama yoyote juu ya jambo hilo. Na tangu sasa nitawaendea watu na mataifa mengine."'),
(2018234,69,44,18,7,'Basi, akatoka hapo akaenda kukaa nyumbani kwa mtu mmoja mcha Mungu aitwaye Tito Yusto. Nyumba yake Tito ilikuwa karibu na lile sunagogi.'),
(2018235,69,44,18,8,'Lakini Krispo, mkuu wa sunagogi, alimwamini Bwana yeye pamoja na jamaa yake yote. Wakorintho wengi waliusikiliza ujumbe huo, wakaamini na kubatizwa.'),
(2018236,69,44,18,9,'Siku moja usiku, Bwana alimwambia Paulo katika maono: "Usiogope, endelea kuhubiri tu bila kufa moyo,'),
(2018237,69,44,18,10,'maana mimi niko pamoja nawe. Hakuna mtu atakayejaribu kukudhuru maana hapa mjini pana watu wengi walio upande wangu."'),
(2018238,69,44,18,11,'Basi, Paulo alikaa huko akifundisha neno la Mungu kati yao kwa muda wa mwaka mmoja na nusu.'),
(2018239,69,44,18,12,'Lakini wakati Galio alipokuwa mkuu wa mkoa wa Akaya, Wayahudi walimvamia Paulo kwa pamoja na kumpeleka mahakamani.'),
(2018240,69,44,18,13,'Wakasema, "Tunamshtaki mtu huyu kwa sababu ya kuwashawishi watu wamwabudu Mungu kwa namna inayopingana na Sheria."'),
(2018241,69,44,18,14,'Kabla tu Paulo hajaanza kusema, Galio aliwaambia Wayahudi, "Sikilizeni enyi Wayahudi! Kama kweli jambo hili lingekuwa juu ya uhalifu au uovu ningekuwa tayari kuwasikilizeni.'),
(2018242,69,44,18,15,'Lakini kama ni shauri la ubishi kuhusu maneno na majina ya Sheria yenu, amueni ninyi wenyewe. Mimi sitaki kuwa hakimu wa mambo haya!"'),
(2018243,69,44,18,16,'Basi, akawafukuza kutoka mahakamani.'),
(2018244,69,44,18,17,'Nao wote wakamkamata Sosthene ambaye alikuwa kiongozi wa sunagogi, wakampiga palepale mbele ya mahakama. Lakini Galio hakujali kitendo hicho hata kidogo.'),
(2018245,69,44,18,18,'Paulo alikaa bado na wale ndugu huko Korintho kwa siku nyingi. Kisha aliwaaga, akapanda meli kwenda Siria pamoja na Priskila na Akula. Huko Kenkrea, alinyoa nywele zake kwa sababu ya nadhiri aliyokuwa ameweka.'),
(2018246,69,44,18,19,'Walifika Efeso na hapo Paulo aliwaacha Priskila na Akula, akaenda katika sunagogi, akajadiliana na Wayahudi.'),
(2018247,69,44,18,20,'Walimwomba akae nao muda mrefu zaidi, lakini hakupenda.'),
(2018248,69,44,18,21,'Bali alipokuwa anaondoka, alisema, "Mungu akipenda nitakuja kwenu tena." Akaondoka Efeso kwa meli.'),
(2018249,69,44,18,22,'Meli ilitia nanga Kaisarea, naye Paulo akaenda Yerusalemu kulisalimia lile kanisa, kisha akaenda Antiokia.'),
(2018250,69,44,18,23,'Alikaa huko muda mfupi, halafu akaendelea na safari kwa kupitia sehemu za Galatia na Frugia akiwatia moyo wafuasi wote.'),
(2018251,69,44,18,24,'Myahudi mmoja aitwaye Apolo, mzaliwa wa Aleksandria, alifika Efeso. Alikuwa mtu mwenye ufasaha wa kuongea na mwenye ujuzi mkubwa wa Maandiko Matakatifu.'),
(2018252,69,44,18,25,'Alikuwa amefundishwa juu ya hiyo njia ya Bwana, na akiwa motomoto, aliongea juu ya habari za Yesu. Akafundisha kwa usahihi ingawa alikuwa amepata ubatizo wa Yohane tu.'),
(2018253,69,44,18,26,'Priskila na Akula walipomsikia akiongea kwa uhodari ndani ya sunagogi, walimchukua kwao wakamfundisha hiyo Njia ya Mungu kwa usahihi zaidi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018254,69,44,18,27,'Apolo alipoamua kwenda Akaya, wale ndugu walimtia moyo kwa kuwaandikia wafuasi kule Akaya wampokee. Alipofika huko, aliweza kwa msaada wa neema ya Mungu, kuwasaidia sana wale ndugu waliopata kuwa waumini;'),
(2018255,69,44,18,28,'kwa maana aliendelea kwa uhodari kuwashinda Wayahudi hadharani akithibitisha kwa Maandiko Matakatifu kuwa Yesu ni Kristo.'),
(2018256,69,44,19,1,'Wakati Apolo alipokuwa Korintho, Paulo alisafiri sehemu za bara, akafika Efeso ambako aliwakuta wanafunzi kadhaa.'),
(2018257,69,44,19,2,'Akauliza, "Je, mlipopata kuwa waumini mlipokea Roho Mtakatifu?" Nao wakamjibu, "La! Hata kusikia kwamba kuna Roho Mtakatifu hatujasikia."'),
(2018258,69,44,19,3,'Naye akasema, "Sasa mlipata ubatizo wa namna gani?" Wakamjibu, "Ubatizo wa Yohane."'),
(2018259,69,44,19,4,'Naye Paulo akasema, "Ubatizo wa Yohane ulikuwa wa kuonyesha kwamba watu wametubu. Yohane aliwaambia watu wamwamini yule ambaye alikuwa anakuja baada yake, yaani Yesu."'),
(2018260,69,44,19,5,'Baada ya kusikia hayo, walibatizwa kwa jina la Bwana Yesu.'),
(2018261,69,44,19,6,'Basi, Paulo akawawekea mikono, na Roho Mtakatifu akawashukia, wakaanza kusema lugha mbalimbali na kutangaza ujumbe wa Mungu.'),
(2018262,69,44,19,7,'Wote jumla, walikuwa watu wapatao kumi na wawili.'),
(2018263,69,44,19,8,'Kwa muda wa miezi mitatu Paulo alikuwa akienda katika sunagogi, akawa na majadiliano ya kuvutia sana juu ya Ufalme wa Mungu.'),
(2018264,69,44,19,9,'Lakini wengine walikuwa wakaidi, wakakataa kuamini, wakaanza kuongea vibaya hadharani juu ya Njia ya Bwana. Hapo Paulo alivunja uhusiano nao, akawachukua pembeni wale wanafunzi wake, akawa anazungumza nao kila siku katika jumba la masomo la Turano.'),
(2018265,69,44,19,10,'Aliendelea kufanya hivyo kwa muda wa miaka miwili hata wakazi wote wa Asia, Wayahudi na watu wa mataifa mengine, wakaweza kusikia neno la Bwana.'),
(2018266,69,44,19,11,'Mungu alifanya miujiza ya ajabu kwa mikono ya Paulo.'),
(2018267,69,44,19,12,'Watu walikuwa wakichukua leso na nguo nyingine za kazi ambazo Paulo alikuwa amezitumia, wakazipeleka kwa wagonjwa, nao wakaponywa magonjwa yao; na wale waliokuwa na pepo wabaya wakatokwa na pepo hao.'),
(2018268,69,44,19,13,'Wayahudi kadhaa wenye kupunga pepo wabaya, walisafiri huko na huko, wakijaribu kulitumia jina la Bwana Yesu kwa wale waliokuwa wamepagawa na pepo wabaya. Walikuwa wakisema: "Ninawaamuru kwa jina la Yesu ambaye Paulo anamhubiri."'),
(2018269,69,44,19,14,'Watoto saba wa Skewa, Kuhani Mkuu wa Kiyahudi, walikuwa miongoni mwa hao waliokuwa wanafanya hivyo.'),
(2018270,69,44,19,15,'Lakini pepo mbaya aliwajibu, "Ninamfahamu Yesu, ninamjua pia Paulo, lakini ninyi ni nani?"'),
(2018271,69,44,19,16,'Kisha yule mtu aliyepagawa aliwarukia wote kwa kishindo, akawashinda nguvu. Na hao watoto wa Skewa wakakimbia kutoka ile nyumba wakiwa uchi na wamejaa majeraha.'),
(2018272,69,44,19,17,'Kila mtu huko Efeso, Myahudi na asiye Myahudi, alisikia juu ya tukio hilo. Wote waliingiwa na hofu, wakalitukuza jina la Bwana Yesu.'),
(2018273,69,44,19,18,'Waumini wengi walijitokeza wakakiri hadharani mambo waliyokuwa wametenda.'),
(2018274,69,44,19,19,'Wengine waliokuwa wameshughulikia mambo ya uchawi hapo awali, walikusanya vitabu vyao, wakavichoma mbele ya wote. Walikisia gharama ya vitabu hivyo, wakaona yafikia vipande vya fedha elfu hamsini.'),
(2018275,69,44,19,20,'Kwa namna hiyo, neno la Bwana lilizidi kuenea na kuwa na nguvu zaidi.'),
(2018276,69,44,19,21,'Baada ya mambo hayo, Paulo aliamua kwenda Yerusalemu kwa kupitia Makedonia na Akaya. Alisema, "Baada ya kufika huko, itanilazimu kuona Roma pia."'),
(2018277,69,44,19,22,'Hivyo, aliwatuma wawili wa wasaidizi wake, Timotheo na Erasto, wamtangulie kwenda Makedonia, naye akabaki kwa muda huko Asia.'),
(2018278,69,44,19,23,'Wakati huo ndipo kulipotokea ghasia kubwa huko Efeso kwa sababu ya hiyo Njia ya Bwana.'),
(2018279,69,44,19,24,'Kulikuwa na mfua fedha mmoja aitwaye Demetrio, ambaye alikuwa na kazi ya kutengeneza sanamu za nyumba ya mungu wa kike aitwaye Artemi. Shughuli hiyo iliwapatia mafundi faida kubwa.'),
(2018280,69,44,19,25,'Demetrio aliwakusanya hao wafanyakazi pamoja na wengine waliokuwa na kazi kama hiyo, akawaambia, "Wananchi, mnafahamu kwamba kipato chetu kinatokana na biashara hii.'),
(2018281,69,44,19,26,'Sasa, mnaweza kusikia na kujionea wenyewe mambo Paulo anayofanya, si tu hapa Efeso, ila pia kote katika Asia. Yeye amewashawishi na kuwageuza watu wakakubali kwamba miungu ile iliyotengenezwa na watu si miungu hata kidogo.'),
(2018282,69,44,19,27,'Hivyo iko hatari kwamba biashara yetu itakuwa na jina baya. Si hivyo tu, bali pia jambo hilo linaweza kuifanya nyumba ya mungu Artemi kuwa si kitu cha maana. Hatimaye sifa zake huyo ambaye Asia na dunia yote inamwabudu, zitakwisha." ic'),
(2018283,69,44,19,28,'Waliposikia hayo, waliwaka hasira, wakaanza kupiga kelele: "Mkuu ni Artemi, wa Efeso!"'),
(2018284,69,44,19,29,'Mji wote ukajaa ghasia. Wakawavamia Gayo na Aristarko, wenyeji wa Makedonia, ambao walikuwa wasafiri wenzake Paulo, wakakimbia nao mpaka kwenye ukumbi wa michezo.'),
(2018285,69,44,19,30,'Paulo mwenyewe alitaka kuukabili huo umati wa watu, lakini wale waumini walimzuia.'),
(2018286,69,44,19,31,'Maofisa wengine wa huo mkoa wa Asia, waliokuwa rafiki zake, walimtumia Paulo ujumbe wakimsihi asijihatarishe kwa kwenda kwenye ukumbi wa michezo.'),
(2018287,69,44,19,32,'Wakati huo, kila mtu alikuwa anapayuka; wengine hili na wengine lile, mpaka hata ule mkutano ukavurugika. Wengi hawakujua hata sababu ya kukutana kwao.'),
(2018288,69,44,19,33,'Kwa vile Wayahudi walimfanya Aleksanda ajitokeze mbele, baadhi ya watu katika ule umati walidhani kuwa ndiye. Basi, Aleksanda aliwaashiria watu kwa mkono akitaka kujitetea mbele ya ule umati wa watu.'),
(2018289,69,44,19,34,'Lakini walipotambua kuwa yeye ni Myahudi, wote kwa sauti moja walipiga kelele: "Mkuu ni Artemi wa Efeso!" Wakaendelea kupayukapayuka hivyo kwa muda wa saa mbili.'),
(2018290,69,44,19,35,'Hatimaye karani wa mji alifaulu kuwanyamazisha, akawaambia, "Wananchi wa Efeso, kila mtu anajua kwamba mji huu wa Efeso ni mlinzi wa nyumba ya mungu Artemi na mlinzi wa ile sanamu iliyoanguka kutoka mbinguni.'),
(2018291,69,44,19,36,'Hakuna anayeweza kukana mambo haya. Hivyo basi, tulieni; msifanye chochote bila hadhari.'),
(2018292,69,44,19,37,'Mmewaita watu hawa hapa ingawaje hawakuikufuru nyumba ya mungu wala kumtukana mungu wetu wa kike.'),
(2018293,69,44,19,38,'Kama, basi Demetrio na wafanyakazi wake wana mashtaka yao kuhusu watu hawa, yapo mahakama na wakuu wa mikoa; wanaweza kushtakiana huko.'),
(2018294,69,44,19,39,'Kama mna matatizo mengine, yapelekeni katika kikao halali.'),
(2018295,69,44,19,40,'Kwa maana tungaliweza kushtakiwa kwa kusababisha ghasia kutokana na vituko vya leo. Ghasia hii haina msingi halali na hatungeweza kutoa sababu za kuridhisha za ghasia hiyo."'),
(2018296,69,44,19,41,'Baada ya kusema hayo aliuvunja mkutano.'),
(2018297,69,44,20,1,'Ile ghasia ya Efeso ilipokwisha tulia Paulo aliwaita pamoja wale waumini, akawatia moyo. Kisha akawaaga, akasafiri kwenda Makedonia.'),
(2018298,69,44,20,2,'Alipitia sehemu za nchi zile akiwatia watu moyo kwa maneno mengi. Halafu akafika Ugiriki.'),
(2018299,69,44,20,3,'ambako alikaa kwa miezi mitatu. Alipokuwa anajitayarisha kwenda Siria, aligundua kwamba Wayahudi walikuwa wanamfanyia mpango mbaya; hivyo aliamua kurudi kwa kupitia Makedonia.'),
(2018300,69,44,20,4,'Sopatro, mwana wa Pirho kutoka Berea, aliandamana naye; pia Aristarko na Sekundo kutoka Thesalonika, Gayo kutoka Derbe, Timotheo, Tukiko na Trofimo wa mkoa wa Asia.'),
(2018301,69,44,20,5,'Hao walitutangulia na kutungojea kule Troa.'),
(2018302,69,44,20,6,'Sisi, baada ya sikukuu ya Mikate Isiyotiwa chachu, tulipanda meli kutoka Filipi na baada ya siku tatu tukawafikia kule Troa. Huko tulikaa kwa muda wa juma moja.'),
(2018303,69,44,20,7,'Jumamosi jioni, tulikutana ili kumega mkate. Kwa vile Paulo alikuwa amekusudia kuondoka kesho yake, aliwahutubia watu na kuendelea kuongea nao hadi usiku wa manane.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018304,69,44,20,8,'Katika chumba tulimokuwa, ghorofani, kulikuwa na taa nyingi zinawaka.'),
(2018305,69,44,20,9,'Kijana mmoja aitwaye Eutuko alikuwa ameketi dirishani wakati Paulo alipokuwa anaendelea kuhutubu. Eutuko alianza kusinzia kidogokidogo na hatimaye usingizi ukambana, akaanguka chini kutoka ghorofa ya tatu. Wakamwokota amekwisha kufa.'),
(2018306,69,44,20,10,'Lakini Paulo alishuka chini, akainama, akamkumbatia na kusema, "Msiwe na wasiwasi maana kuna uhai bado ndani yake."'),
(2018307,69,44,20,11,'Kisha akapanda tena ghorofani, akamega mkate, akala. Aliendelea kuhubiri kwa muda mrefu hadi alfajiri, halafu akaondoka.'),
(2018308,69,44,20,12,'Wale watu walimchukua yule kijana nyumbani akiwa mzima kabisa, wakapata kitulizo kikubwa.'),
(2018309,69,44,20,13,'Sisi tulipanda meli tukatangulia kwenda Aso ambako tungemchukua Paulo. Ndivyo alivyopanga; maana alitaka kufika huko kwa kupitia nchi kavu.'),
(2018310,69,44,20,14,'Basi, alitukuta kule Aso, tukampandisha melini, tukaenda Mitulene.'),
(2018311,69,44,20,15,'Kutoka huko tulisafiri tukafika Kio kesho yake. Siku ya pili, tulitia nanga Samo na kesho yake tukafika Mileto.'),
(2018312,69,44,20,16,'Paulo alikuwa amekusudia kuendelea na safari kwa meli bila kupitia Efeso ili asikawie zaidi huko Asia. Alikuwa na haraka ya kufika Yerusalemu kwa sikukuu ya Pentekoste kama ingewezekana.'),
(2018313,69,44,20,17,'Kutoka Mileto Paulo alituma ujumbe kwa wazee wa Efeso wakutane naye.'),
(2018314,69,44,20,18,'Walipofika kwake aliwaambia, "Mnajua jinsi nilivyotumia wakati wote pamoja nanyi tangu siku ile ya kwanza nilipofika Asia.'),
(2018315,69,44,20,19,'Mnajua jinsi nilivyomtumikia Bwana kwa unyenyekevu wote, kwa machozi na matatizo yaliyonipata kutokana na mipango ya hila ya Wayahudi.'),
(2018316,69,44,20,20,'Mnajua kwamba sikusita hata kidogo kuwahubiria hadharani na nyumbani mwenu na kuwafundisha chochote ambacho kingewasaidieni.'),
(2018317,69,44,20,21,'Niliwaonya wote--Wayahudi kadhalika na watu wa mataifa, wamgeukie Mungu na kumwamini Bwana wetu Yesu.'),
(2018318,69,44,20,22,'Sasa, sikilizeni! Mimi, nikiwa ninamtii Roho, nakwenda Yerusalemu bila kufahamu yatakayonipata huko.'),
(2018319,69,44,20,23,'Ninachojua tu ni kwamba Roho Mtakatifu ananithibitishia katika kila mji kwamba vifungo na mateso ndivyo vinavyoningojea.'),
(2018320,69,44,20,24,'Lakini, siuthamini uhai wangu kuwa ni kitu sana kwangu. Nataka tu nikamilishe ule utume wangu na kumaliza ile kazi aliyonipa Bwana Yesu niifanye, yaani nitangaze Habari Njema ya neema ya Mungu.'),
(2018321,69,44,20,25,'"Nimekuwa nikienda huko na huko kati yenu nikiuhubiri Ufalme wa Mungu. Sasa lakini, najua hakuna hata mmoja wenu atakayeniona tena.'),
(2018322,69,44,20,26,'Hivyo, leo hii ninawathibitishieni rasmi kwamba ikijatokea akapotea mmoja wenu, mimi sina lawama yoyote.'),
(2018323,69,44,20,27,'Kwa maana sikusita hata kidogo kuwatangazieni azimio lote la Mungu.'),
(2018324,69,44,20,28,'Jihadharini wenyewe; lilindeni lile kundi ambalo Roho Mtakatifu amewaweka ninyi muwe walezi wake. Lichungeni kanisa la Mungu ambalo amejipatia kwa damu ya Mwanae.'),
(2018325,69,44,20,29,'Nafahamu vizuri sana kwamba baada ya kuondoka kwangu mbwa mwitu wakali watawavamieni, na hawatakuwa na huruma kwa kundi hilo.'),
(2018326,69,44,20,30,'Hata kutoka miongoni mwenu watatokea watu ambao watasema mambo ya uongo ili kuwapotosha watu na kuwafanya wawafuate wao tu.'),
(2018327,69,44,20,31,'Kwa hiyo, muwe macho mkikumbuka kwamba kwa muda wa miaka mitatu, usiku na mchana, sikuchoka kumwonya kila mmoja wenu kwa machozi.'),
(2018328,69,44,20,32,'"Na sasa basi, ninawaweka ninyi chini ya ulinzi wa Mungu na ujumbe wa neema yake. Yeye anao uwezo wa kuwajenga ninyi na kuwawezesha mzipate zile baraka alizowawekea watu wake.'),
(2018329,69,44,20,33,'Mimi sikutamani hata mara moja fedha, wala dhahabu, wala nguo za mtu yeyote.'),
(2018330,69,44,20,34,'Mnajua ninyi wenyewe kwamba nimefanya kazi kwa mikono yangu mwenyewe, ili kujipatia mahitaji yangu na ya wenzangu.'),
(2018331,69,44,20,35,'Nimekuwa nikiwapeni daima mfano kwamba kwa kufanya kazi mithili hiyo tunapaswa kuwasaidia walio dhaifu, tukikumbuka maneno ya Bwana Yesu mwenyewe: `Heri zaidi kutoa kuliko kupokea."`'),
(2018332,69,44,20,36,'Baada ya kusema hayo, Paulo alipiga magoti pamoja nao wote, akasali.'),
(2018333,69,44,20,37,'Wote walikuwa wanalia; wakamwaga kwa kumkumbatia na kumbusu.'),
(2018334,69,44,20,38,'Jambo lililowahuzunisha zaidi lilikuwa neno alilosema kwamba hawangemwona tena. Basi, wakamsindikiza hadi melini.'),
(2018335,69,44,21,1,'Tulipokwisha agana nao, tulipanda meli tukaenda moja kwa moja mpaka Kosi. Kesho yake tulifika Rodo, na kutoka huko tulikwenda Patara.'),
(2018336,69,44,21,2,'Huko, tulikuta meli iliyokuwa inakwenda Foinike, hivyo tulipanda, tukasafiri.'),
(2018337,69,44,21,3,'Baada ya kufika mahali ambapo tuliweza kuona Kupro, tulipitia upande wake wa kusini tukaelekea Siria. Tulitia nanga katika mji wa Tiro ambapo ile meli ilikuwa ipakuliwe shehena yake.'),
(2018338,69,44,21,4,'Tulikuta waumini huko, tukakaa pamoja nao kwa muda wa juma moja. Waumini hao wakawa waongea kwa nguvu ya Roho, wakamwambia Paulo asiende Yerusalemu.'),
(2018339,69,44,21,5,'Lakini muda wetu ulipokwisha tuliondoka. Wote pamoja na wanawake na watoto wao walitusindikiza mpaka nje ya mji. Tulipofika pwani, sote tulipiga magoti tukasali.'),
(2018340,69,44,21,6,'Kisha tuliagana; sisi tukapanda meli nao wakarudi makwao.'),
(2018341,69,44,21,7,'Sisi tuliendelea na safari yetu kutoka Tiro tukafika Tolemai ambapo tuliwasalimu ndugu zetu, tukakaa nao siku moja.'),
(2018342,69,44,21,8,'Kesho yake tuliondoka tukaenda Kaisarea. Huko Kaisarea tulikwenda nyumbani kwa mhubiri Filipo. Yeye alikuwa mmoja wa wale saba waliochaguliwa kule Yerusalemu.'),
(2018343,69,44,21,9,'Alikuwa na binti watatu ambao walikuwa na kipaji cha unabii.'),
(2018344,69,44,21,10,'Baada ya kukaa huko siku kadhaa, nabii mmoja aitwaye Agabo alifika kutoka Yudea.'),
(2018345,69,44,21,11,'Alitujia, akachukua mkanda wa Paulo, akajifunga mikono na miguu, akasema "Roho Mtakatifu asema hivi: `Wayahudi kule Yerusalemu watamfunga namna hii mtu mwenye ukanda na kumtia mikononi mwa watu wa mataifa."`'),
(2018346,69,44,21,12,'Tuliposikia hayo, sisi na wale watu wengine waliokuwa hapo tulimsihi Paulo asiende Yerusalemu.'),
(2018347,69,44,21,13,'Lakini yeye alijibu, "Mnataka kufanya nini? Mnataka kuvunja moyo wangu kwa machozi? Niko tayari siyo tu kutiwa ndani kule Yerusalemu, ila hata kufa kwa ajili ya Bwana Yesu."'),
(2018348,69,44,21,14,'Tuliposhindwa kumshawishi tulinyamaza, tukasema tu: "Mapenzi ya Bwana yafanyike"'),
(2018349,69,44,21,15,'Baada ya kukaa pale kwa muda, tulifunga mizigo yetu, tukaendelea na safari kwenda Yerusalemu.'),
(2018350,69,44,21,16,'Wengine kati ya wale wafuasi wa Kaisarea walienda pamoja nasi, wakatupeleka nyumbani kwa Mnasoni ambaye tulikuwa tunakwenda kukaa naye kwa muda. Mnasoni alikuwa mwenyeji wa Kupro na alikuwa amekuwa muumini kwa siku nyingi.'),
(2018351,69,44,21,17,'Tulipofika Yerusalemu, ndugu waumini walitupokea vizuri sana.'),
(2018352,69,44,21,18,'Kesho yake Paulo alikwenda pamoja nasi kumwamkia Yakobo, na wazee wote wa kanisa walikuwako pia.'),
(2018353,69,44,21,19,'Baada ya kuwasalimu, Paulo aliwapa taarifa kamili kuhusu yote Mungu aliyokuwa ametenda kati ya mataifa kwa njia ya utumishi wake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018354,69,44,21,20,'Waliposikia hayo, walimtukuza Mungu. Kisha wakamwambia Paulo, "Ndugu, unaweza kuona kwamba kuna maelfu ya Wayahudi ambao sasa wamekuwa waumini na wote hao wanashika kwa makini Sheria ya Mose.'),
(2018355,69,44,21,21,'Wamepata habari zako kwamba umekuwa ukiwafundisha Wayahudi wanaoishi kati ya mataifa mengine kuwa wasiijali Sheria ya Mose, wasiwatahiri watoto wao na kwamba wasizifuate mila za Wayahudi.'),
(2018356,69,44,21,22,'Sasa, mambo yatakuwaje? Ni dhahiri kuwa watapata habari kwamba umekwisha wasili hapa.'),
(2018357,69,44,21,23,'Basi, fanya kama tunavyokushauri. Tunao hapa watu wanne ambao wameweka nadhiri.'),
(2018358,69,44,21,24,'Jiunge nao katika ibada ya kujitakasa, ukalipe na gharama zinazohusika, kisha wanyolewe nywele zao. Hivyo watu wote watatambua kwamba habari zile walizoambiwa juu yako hazina msingi wowote, na kwamba wewe binafsi bado unaishi kufuatana na maagizo ya Sheria za Mose.'),
(2018359,69,44,21,25,'Kuhusu wale watu wa mataifa mengine ambao wamekuwa waumini, tumekwisha wapelekea barua tukiwaambia mambo tuliyoamua: wasile chochote kilichotambikiwa miungu ya uongo, wasinywe damu, wasile nyama ya mnyama aliyenyongwa, na wajiepushe na uasherati."'),
(2018360,69,44,21,26,'Basi, kesho yake Paulo aliwachukua wale watu akafanya ibada ya kujitakasa pamoja nao. Kisha akaingia Hekaluni kutoa taarifa kuhusu mwisho wa siku za kujitakasa na kuhusu dhabihu itakayotolewa kwa ajili ya kila mmoja wao.'),
(2018361,69,44,21,27,'Wakati siku hizo saba zilipokaribia kuisha, Wayahudi waliokuwa wametoka katika mkoa wa Asia walimwona Paulo Hekaluni. Wakachochea hasira kati ya kundi lote la watu, wakamtia nguvuni'),
(2018362,69,44,21,28,'wakipiga kelele: "Wananchi wa Israeli, msaada, msaada! Huyu ndiye yule mtu anayewafundisha watu kila mahali mambo yanayopinga watu wa Israeli, yanayopinga Sheria ya Mose na mahali hapa patakatifu. Hata sasa amewaingiza watu wa mataifa mengine Hekaluni na kupatia najisi mahali hapa patakatifu."'),
(2018363,69,44,21,29,'Sababu ya kusema hivyo ni kwamba walikuwa wamemwona Trofimo mwenyeji, wa Efeso, akiwa pamoja na Paulo mjini, wakadhani kwamba Paulo alikuwa amemwingiza Hekaluni.'),
(2018364,69,44,21,30,'Mji wote ulienea ghasia; watu wakaja kutoka pande zote, wakamkamata Paulo, wakamburuta, wakamtoa nje ya Hekalu na papo hapo milango ya Hekalu ikafungwa.'),
(2018365,69,44,21,31,'Walikuwa tayari kumuua, lakini habari zilimfikia mkuu wa jeshi la Kiroma kuwa Yerusalemu yote ilikuwa imejaa ghasia.'),
(2018366,69,44,21,32,'Mara, mkuu wa jeshi akawachukua askari na jemadari, akalikabili lile kundi la watu. Nao walipomwona mkuu wa jeshi na askari, wakaacha kumpiga Paulo.'),
(2018367,69,44,21,33,'Mkuu wa jeshi alimwendea Paulo, akamtia nguvuni na kuamuru afungwe minyororo miwili. Kisha akauliza, "Ni mtu gani huyu, na amefanya nini?"'),
(2018368,69,44,21,34,'Wengine katika lile kundi la watu walikuwa wanapayuka kitu hiki na wengine kitu kingine. Kwa sababu ya ghasia hiyo, mkuu wa jeshi hakufaulu kujua kisa kamili. Hivyo, aliamuru watu wake wampeleke Paulo ndani ya ngome.'),
(2018369,69,44,21,35,'Paulo alipofika kwenye ngazi, askari walilazimika kumbeba kwa sababu ya fujo za watu.'),
(2018370,69,44,21,36,'Kwa maana kundi kubwa la watu walimfuata wakipiga kelele, "Muulie mbali!" ic'),
(2018371,69,44,21,37,'Walipokuwa wanamwingiza ndani ya ngome, Paulo alimwomba mkuu wa jeshi akisema, "Naweza kukwambia kitu?" Yule mkuu wa jeshi akamjibu, "Je unajua Kigiriki?'),
(2018372,69,44,21,38,'Kwani wewe si yule Mmisri ambaye hivi majuzi alianzisha uasi na kuwaongoza majahili elfu nne hadi jangwani?"'),
(2018373,69,44,21,39,'Paulo akajibu, "Mimi ni Myahudi, mzaliwa wa Tarso katika Kilikia; mimi ni raia wa mji maarufu. Tafadhali, niruhusu niongee na watu.'),
(2018374,69,44,21,40,'Yule mkuu wa jeshi akamruhusu. Hivyo Paulo alisimama juu ya ngazi, akawapungia mkono wale watu na walipokaa kimya, akaanza kuongea nao kwa Kiebrania.'),
(2018375,69,44,22,1,'"Ndugu zangu na akina baba, nisikilizeni sasa nikijitetea mbele yenu!"'),
(2018376,69,44,22,2,'Waliposikia akiongea nao kwa Kiebrania wakazidi kukaa kimya zaidi kuliko hapo awali. Naye Paulo akaendelea kusema,'),
(2018377,69,44,22,3,'"Mimi ni Myahudi, mzaliwa wa Tarso katika Kilikia. Lakini nililelewa papa hapa mjini Yerusalemu chini ya mkufunzi Gamalieli. Nilifundishwa kufuata kwa uthabiti Sheria ya wazee wetu. Nilijitolea kwa moyo wote kwa Mungu kama ninyi wenyewe mlivyo hivi leo.'),
(2018378,69,44,22,4,'Niliwatesa hata kuwaua wale watu waliofuata Njia hii. Niliwatia nguvuni wanaume kwa wanawake na kuwafunga gerezani.'),
(2018379,69,44,22,5,'Kuhani Mkuu na baraza lote la wazee wanaweza kushuhudia jambo hilo. Kutoka kwao nilipokea barua walioandikiwa wale ndugu Wayahudi waliokuwa huko Damasko. Nilikwenda Damasko ili niwatie nguvuni watu hao na kuwaleta wamefungwa mpaka Yerusalemu ili waadhibiwe.'),
(2018380,69,44,22,6,'"Basi, nilipokuwa njiani karibu kufika Damasko, yapata saa sita mchana, mwangu mkubwa kutoka mbinguni ulitokea ghafla ukaniangazia pande zote.'),
(2018381,69,44,22,7,'Hapo nilianguka chini, nikasikia sauti ikiniambia: `Saulo, Saulo! Kwa nini unanitesa?`'),
(2018382,69,44,22,8,'Nami nikauliza: `Nani wewe, Bwana?` Naye akaniambia: `Mimi ni Yesu wa Nazareti ambaye wewe unamtesa.`'),
(2018383,69,44,22,9,'Wale wenzangu waliuona ule mwanga lakini hawakusikia sauti ya yule aliyeongea nami.'),
(2018384,69,44,22,10,'Basi, mimi nikauliza: `Nifanye nini Bwana?` Naye Bwana akaniambia: `Simama, nenda Damasko na huko utaambiwa yote ambayo umepangiwa kufanya.`'),
(2018385,69,44,22,11,'Kutokana na ule mwanga mkali sikuweza kuona na hivyo iliwabidi wale wenzangu kuniongoza kwa kunishika mkono mpaka nikafika Damasko.'),
(2018386,69,44,22,12,'"Huko kulikuwa na mtu mmoja aitwaye Anania, mtu mcha Mungu, mwenye kuitii Sheria yetu na aliyeheshimika sana mbele ya Wayahudi waliokuwa wanaishi Damasko.'),
(2018387,69,44,22,13,'Yeye alikuja kuniona, akasimama karibu nami, akasema: `Ndugu Saulo! Ona tena.` Papo hapo nikaona tena, nikamwangalia.'),
(2018388,69,44,22,14,'Halafu Anania akasema: `Mungu wa babu zetu amekuchagua upate kujua matakwa yake na kumwona yule mtumishi wake mwadilifu na kumsikia yeye mwenyewe akiongea.'),
(2018389,69,44,22,15,'Kwa maana utamshuhudia kwa watu wote ukiwaambia yale uliyoyaona na kuyasikia.'),
(2018390,69,44,22,16,'Sasa basi, ya nini kukawia zaidi? Simama ubatizwe na uondolewe dhambi zako kwa kuliungama jina lake.`'),
(2018391,69,44,22,17,'"Basi, nilirudi Yerusalemu, na nilipokuwa nikisali Hekaluni, niliona maono.'),
(2018392,69,44,22,18,'Nilimwona Bwana akiniambia: `Haraka! Ondoka Yerusalemu upesi kwa maana watu wa hapa binadamu hawataukubali ushuhuda wako juu yangu.`'),
(2018393,69,44,22,19,'Nami nikamjibu: `Bwana, wao wanajua wazi kwamba mimi ni yule aliyekuwa anapitapita katika masunagogi na kuwatia nguvuni na kuwapiga wale waliokuwa wanakuamini.'),
(2018394,69,44,22,20,'Na kwamba wakati shahidi wako Stefano alipouawa, mimi binafsi nilikuwako pale nikakubaliana na kitendo hicho na kuyalinda makoti ya wale waliokuwa wanamuua.`'),
(2018395,69,44,22,21,'Naye Bwana akaniambia: `Nenda; ninakutuma mbali kwa mataifa mengine."`'),
(2018396,69,44,22,22,'Mpaka hapa, wale watu walikuwa wanamsikiza, lakini aliposema maneno haya, walianza kusema kwa sauti kubwa, "Mwondoe duniani! Mtu wa namna hiyo hastahili kuishi."'),
(2018397,69,44,22,23,'Waliendelea kupayukapayuka huku wakitikisa makoti yao na kurusha vumbi angani.'),
(2018398,69,44,22,24,'Mkuu wa jeshi aliwaamuru watu wake wampeleke Paulo ndani ya ngome, akawaambia wamchape viboko ili wapate kujua kisa cha Wayahudi kumpigia kelele.'),
(2018399,69,44,22,25,'Lakini walipokwisha mfunga ili wamchape viboko, Paulo alimwuliza jemadari mmoja aliyesimama hapo, "Je, ni halali kwenu kumpiga viboko raia wa Roma kabla hajahukumiwa?"'),
(2018400,69,44,22,26,'Yule jemadari aliposikia hayo, alimpasha habari mkuu wa jeshi akisema, "Unataka kufanya nini? Mtu huyu ni raia wa Roma!"'),
(2018401,69,44,22,27,'Basi, mkuu wa jeshi alimwendea Paulo, akamwambia, "Niambie; je, wewe ni raia wa Roma?" Paulo akamjibu, "Naam."'),
(2018402,69,44,22,28,'Mkuu wa jeshi akasema, "Mimi nami nimekuwa raia wa Roma kwa kulipa gharama kubwa." Paulo akasema, "Lakini mimi ni raia wa Roma kwa kuzaliwa."'),
(2018403,69,44,22,29,'Wale watu ambao walikuwa tayari kumchunguza Paulo walitoweka mara. Hata yule mkuu wa jeshi aliogopa alipojua kwamba Paulo ni raia wa Roma na kwamba alikuwa amekwisha mfunga minyororo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018404,69,44,22,30,'Kesho yake, mkuu wa jeshi alitaka kujua mashtaka kamili ambayo Wayahudi walikuwa wamemwekea Paulo. Hivyo, alimfungua Paulo minyororo, akaamuru makuhani wakuu na Baraza lote wafanye kikao. Kisha alimleta Paulo, akamsimamisha mbele ya Baraza.'),
(2018405,69,44,23,1,'Paulo aliwakodolea macho wale wanabaraza, halafu akaanza kusema, "Ndugu zangu, mpaka hivi leo nimekuwa nikiishi na dhamiri njema mbele ya Mungu."'),
(2018406,69,44,23,2,'Hapo Kuhani Mkuu Anania akaamuru wale waliokuwa wamesimama karibu na Paulo wampige kofi mdomoni.'),
(2018407,69,44,23,3,'Basi, Paulo akamwambia, "Mungu mwenyewe atakupiga kofi wewe uliye kama ukuta uliopakwa chokaa! Unawezaje kukaa hapo ili unihukumu kisheria na huku wewe mwenyewe unaivunja Sheria kwa kuamuru nipigwe?"'),
(2018408,69,44,23,4,'Watu waliokuwa wamesimama pale wakamwambia Paulo, "Unamtukana Kuhani Mkuu wa Mungu!"'),
(2018409,69,44,23,5,'Paulo akajibu, "Ndugu zangu, sikujua kama yeye ni Kuhani Mkuu. Maana Maandiko yasema hivi: `Usiseme vibaya juu ya mtawala wa watu wako."`'),
(2018410,69,44,23,6,'Wakati huo Paulo alikwisha tambua kwamba sehemu moja ya wanabaraza wale ilikuwa ni Masadukayo na nyingine Mafarisayo. Basi, alipaaza sauti yake mbele ya Baraza: "Ndugu zangu, mimi ni Mfarisayo, mwana wa Mfarisayo. Mimi nimeletwa mahakamani kwa kuwa ninatumaini kwamba wafu watafufuka."'),
(2018411,69,44,23,7,'Baada ya kusema hivyo, mzozo mkali ulitokea kati ya Mafarisayo na Masadukayo na mkutano ukagawanyika sehemu mbili.'),
(2018412,69,44,23,8,'Kisa chenyewe kilikuwa hiki: Masadukayo hushikilia kwamba wafu hawafufuki, hakuna malaika, na roho nazo hazipo. Lakini Mafarisayo husadiki hayo yote matatu.'),
(2018413,69,44,23,9,'Kelele ziliongezeka na baadhi ya walimu wa Sheria wa kikundi cha Mafarisayo walisimama na kutoa malalamiko yao kwa nguvu: "Hatuoni chochote kilicho kiovu katika mtu huyu; huenda ikawa kwamba roho au malaika ameongea naye."'),
(2018414,69,44,23,10,'Mzozo ulizidi kuwa mwingi hata mkuu wa jeshi akaogopa kwamba Paulo angeraruliwa vipandevipande. Kwa hiyo, aliwaamuru askari wake kuingia kati ya lile kundi, wamtoe Paulo na kumrudisha ndani ya ngome.'),
(2018415,69,44,23,11,'Usiku uliofuata, Bwana alisimama karibu na Paulo, akamwambia, "Jipe moyo! Umenishuhudia katika Yerusalemu, utafanya vivyo hivyo mjini Roma."'),
(2018416,69,44,23,12,'Kulipokucha, Wayahudi walifanya kikao cha faragha. Wakala kiapo: "Hatutakula wala kunywa mpaka tutakapokuwa tumekwisha muua Paulo."'),
(2018417,69,44,23,13,'Watu zaidi ya arobaini ndio waliokula njama kufanya hivyo.'),
(2018418,69,44,23,14,'Basi, walikwenda kwa makuhani wakuu na wazee, wakasema, "Sisi tumeapa kwamba hatutaonja chochote kwa vinywa vyetu mpaka hapo tutakapokuwa tumemuua Paulo.'),
(2018419,69,44,23,15,'Sasa basi, ninyi pamoja na Baraza tumeni ujumbe kwa mkuu wa jeshi ili amlete Paulo kwenu mkijisingizia kwamba mnataka kupata habari kamili zaidi juu yake. Tuko tayari kumuua hata kabla hajafika karibu."'),
(2018420,69,44,23,16,'Lakini mtoto wa kiume wa dada yake Paulo alisikia juu ya mpango huo; hivyo akaenda ndani ya ngome, akamjulisha Paulo juu ya njama hiyo.'),
(2018421,69,44,23,17,'Hapo Paulo akamwita mmoja wa askari, akamwambia, "Mchukue kijana huyu kwa mkuu wa jeshi; ana kitu cha kumwambia."'),
(2018422,69,44,23,18,'Askari akamchukua huyo kijana, akamwongoza mpaka kwa mkuu wa jeshi, akasema, "Yule mfungwa Paulo ameniita akaniomba nimlete kijana huyu kwako kwa maana ana jambo la kukwambia."'),
(2018423,69,44,23,19,'Mkuu wa jeshi alimshika huyo kijana mkono, akampeleka mahali pa faragha, akamwuliza, "Una nini cha kuniambia?"'),
(2018424,69,44,23,20,'Yeye akasema, "Wayahudi wamepatana wakuombe umpeleke Paulo Barazani wakijisingizia kwamba Baraza lingependa kupata habari kamili zaidi juu yake.'),
(2018425,69,44,23,21,'Lakini wewe usikubali kwa maana kuna watu zaidi ya arobaini walio tayari kumvamia. Wameapa kutokula wala kunywa mpaka watakapokuwa wamemuua. Sasa wako tayari, wanangojea tu uamuzi wako."'),
(2018426,69,44,23,22,'Mkuu wa jeshi alimwacha aende zake akimwonya asimwambie mtu yeyote kwamba amemletea habari hizo.'),
(2018427,69,44,23,23,'Basi, mkuu wa jeshi aliwaita askari wawili akawaambia, "Wekeni tayari askari mia mbili, wapanda farasi sabini na askari mia mbili wa mikuki, waende Kaisarea; muwe tayari kuondoka kabla ya saa tatu leo usiku.'),
(2018428,69,44,23,24,'Wekeni farasi kadhaa kwa ajili ya Paulo; mfikisheni salama kwa Felisi, mkuu wa mkoa."'),
(2018429,69,44,23,25,'Halafu mkuu huyo wa jeshi akaandika barua hivi:'),
(2018430,69,44,23,26,'"Mimi Klaudio Lusia ninakuandikia wewe Mheshimiwa Felisi, mkuu wa mkoa. Salamu!'),
(2018431,69,44,23,27,'"Wayahudi walimkamata mtu huyu na karibu wangemuua kama nisingalifahamishwa kwamba yeye ni raia wa Roma na hivyo nikaenda pamoja na askari nikamwokoa.'),
(2018432,69,44,23,28,'Nilimpeleka mbele ya Baraza lao kuu nikitaka kujua kisa cha mashtaka yao.'),
(2018433,69,44,23,29,'Niligundua kwamba mashtaka yenyewe yalihusu ubishi juu ya sehemu kadha wa kadha za Sheria yao na hivyo sikuona kwamba amefanya chochote kinachostahili auawe au afungwe gerezani.'),
(2018434,69,44,23,30,'Nilipofahamishwa kwamba Wayahudi walikuwa wamefanya njama za kumuua, niliamua kumleta kwako. Nikamwambia washtaki wake walete mashtaka yao mbele yako."'),
(2018435,69,44,23,31,'Basi, hao askari walimchukua Paulo kama walivyoamriwa; wakampeleka usiku uleule mpaka Antipatri.'),
(2018436,69,44,23,32,'Kesho yake askari wa miguu walirudi ngomeni, wakawaacha wale askari wapanda farasi waendelee na safari pamoja na Paulo.'),
(2018437,69,44,23,33,'Walipofika Kaisarea walimpa mkuu wa mkoa ile barua na kumweka Paulo chini ya mamlaka yake.'),
(2018438,69,44,23,34,'Felisi alipoisoma hiyo barua aliwauliza Paulo ametoka mkoa gani. Alipofahamishwa kwamba alikuwa ametoka mkoa wa Kilikia,'),
(2018439,69,44,23,35,'akasema, "Nitasikiliza kesi yako baada ya washtaki wako kufika." Kisha akaamuru Paulo awekwe chini ya ulinzi ndani ya ukumbi wa Herode.'),
(2018440,69,44,24,1,'Baada ya siku tano, Kuhani Mkuu Anania aliwasili Kaisarea pamoja na wazee kadhaa na wakili mmoja wa sheria aitwaye Tertulo. Walimwendea yule mkuu wa mkoa wakamweleza mashtaka yao juu ya Paulo.'),
(2018441,69,44,24,2,'Paulo aliitwa na Tertulo akafungua mashtaka hivi: "Mheshimiwa Felisi, uongozi wako bora umeleta amani kubwa na marekebisho ya lazima yanafanywa kwa manufaa ya taifa letu.'),
(2018442,69,44,24,3,'Tunalipokea jambo hili kwa furaha daima na kutoa shukrani nyingi kwako kila mahali.'),
(2018443,69,44,24,4,'Lakini, bila kupoteza wakati wako zaidi, tunakusihi kwa wema wako, usikilize taarifa yetu fupi.'),
(2018444,69,44,24,5,'Tumegundua kwamba mtu huyu ni wa hatari mno. Yeye huanzisha ghasia kati ya Wayahudi kila mahali duniani na pia ni kiongozi wa kile chama cha Wanazareti.'),
(2018445,69,44,24,6,'Tena alijaribu kulikufuru Hekalu nasi tukamtia nguvuni. Kama ukimhoji wewe mwenyewe, utaweza kubainisha mambo haya yote tunayomshtaki kwayo."*fc*'),
(2018446,69,44,24,7,'missing'),
(2018447,69,44,24,8,'missing'),
(2018448,69,44,24,9,'Nao Wayahudi waliunga mkono mashtaka hayo wakisema kwamba hayo yote yalikuwa kweli. jeshi, aliingilia kati, akamchukua kwa nguvu kutoka mikononi mwetu. 8 Kisha akaamuru washtaki wake waje mbele yako.'),
(2018449,69,44,24,10,'Basi, mkuu wa mkoa alimwashiria Paulo aseme. Naye Paulo akasema, "Nafurahi kujitetea mbele yako nikijua kwamba umekuwa hakimu wa taifa hili kwa miaka mingi.'),
(2018450,69,44,24,11,'Unaweza kujihakikishia kwamba si zaidi ya siku kumi na mbili tu zimepita tangu nilipokwenda kuabudu Yerusalemu.'),
(2018451,69,44,24,12,'Wayahudi hawakunikuta nikijadiliana na mtu yeyote. Hawakunikuta nikichochea watu Hekaluni wala katika masunagogi yao, wala mahali pengine popote katika mji huo.'),
(2018452,69,44,24,13,'Wala hawawezi kuthibitisha mashtaka waliyotoa juu yangu.'),
(2018453,69,44,24,14,'Ninachokubali mbele yako ni hiki: Mimi ninamwabudu Mungu na wazee wetu nikiishi kufuatana na Njia ile ambayo wao wanaiita chama cha uzushi. Ninaamini mambo yote yaliyoandikwa katika vitabu vya Sheria na manabii.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018454,69,44,24,15,'Mimi namtumainia Mungu, na wao wanalo tumaini hilo, kwamba watu, wema na wabaya, watafufuka.'),
(2018455,69,44,24,16,'Kwa hiyo ninajitahidi daima kuwa na dhamiri njema mbele ya Mungu na mbele ya watu.'),
(2018456,69,44,24,17,'"Baada ya kukaa mbali kwa miaka kadhaa, nilirudi Yerusalemu ili kuwapelekea wananchi wenzangu msaada na kutoa dhabihu.'),
(2018457,69,44,24,18,'Wakati nilipokuwa nikifanya hayo ndipo waliponikuta Hekaluni, nilipokuwa nimekwisha fanya ile ibada ya kujitakasa. Hakukuwako kundi la watu wala ghasia.'),
(2018458,69,44,24,19,'Lakini kulikuwa na Wayahudi wengine kutoka mkoa wa Asia; hao ndio wangepaswa kuwa hapa mbele yako na kutoa mashtaka yao kama wana chochote cha kusema dhidi yangu.'),
(2018459,69,44,24,20,'Au, waache hawa walio hapa waseme kosa waliloliona kwangu wakati niliposimama mbele ya Baraza lao kuu,'),
(2018460,69,44,24,21,'isipokuwa tu maneno haya niliyosema niliposimama mbele yao: `Mnanihukumu leo hii kwa sababu ya kushikilia kwamba wafu watafufuliwa!"`'),
(2018461,69,44,24,22,'Hapo, Felisi, ambaye mwenyewe alikuwa anaifahamu hiyo Njia vizuri, aliahirisha kesi hiyo. Akawaambia, "Nitatoa hukumu juu ya kesi hiyo wakati Luisa, mkuu wa jeshi, atakapokuja hapa."'),
(2018462,69,44,24,23,'Kisha akamwamuru yule jemadari amweke Paulo kizuizini, lakini awe na uhuru kiasi, na rafiki zake wasizuiwe kumpatia mahitaji yake.'),
(2018463,69,44,24,24,'Baada ya siku chache, Felisi alifika pamoja na mkewe Drusila ambaye alikuwa Myahudi. Aliamuru Paulo aletwe, akamsikiliza akiongea juu ya kumwamini Yesu Kristo.'),
(2018464,69,44,24,25,'Lakini wakati Paulo alipoanza kuongea juu ya uadilifu, juu ya kuwa na kiasi na juu ya siku ya hukumu inayokuja, Felisi aliogopa, akasema, "Kwa sasa unaweza kwenda; nitakuita tena nitakapopata nafasi."'),
(2018465,69,44,24,26,'Wakati huohuo alikuwa anatumaini kwamba Paulo angempa fedha. Kwa sababu hii alimwita Paulo mara kwa mara na kuzungumza naye.'),
(2018466,69,44,24,27,'Baada ya miaka miwili, Porkio Festo alichukua nafasi ya Felisi, akawa mkuu wa Mkoa. Kwa kuwa alitaka kujipendekeza kwa Wayahudi, Felisi alimwacha Paulo kizuizini.'),
(2018467,69,44,25,1,'Siku tatu baada ya kufika mkoani, Festo alitoka Kaisarea, akaenda Yerusalemu.'),
(2018468,69,44,25,2,'Makuhani wakuu pamoja na viongozi wa Wayahudi walimpa habari kuhusu mashtaka yaliyokuwa yanamkabili Paulo. Walimsihi Festo'),
(2018469,69,44,25,3,'awafanyie fadhili kwa kumleta Paulo Yerusalemu; walikuwa wamekula njama wamuue akiwa njiani.'),
(2018470,69,44,25,4,'Lakini Festo alijibu, "Paulo atabaki kizuizini kule Kaisarea na mimi nitakwenda huko karibuni.'),
(2018471,69,44,25,5,'Waacheni viongozi wenu waende huko pamoja nami wakatoe mashtaka yao juu yake kama amefanya chochote kiovu."'),
(2018472,69,44,25,6,'Festo alikaa nao kwa muda wa siku nane au kumi hivi, kisha akarudi Kaisarea. Kesho yake alikwenda barazani, akaamuru Paulo aletwe ndani.'),
(2018473,69,44,25,7,'Wakati Paulo alipofika, Wayahudi waliokuwa wametoka Yerusalemu walimzunguka wakaanza kutoa mashtaka mengi mazitomazito ambayo hawakuweza kuthibitisha.'),
(2018474,69,44,25,8,'Kwa kujitetea, Paulo alisema, "Mimi sikufanya kosa lolote kuhusu Sheria ya Wayahudi, wala kuhusu Hekalu, wala kumhusu Kaisari."'),
(2018475,69,44,25,9,'Festo alitaka kujipendekeza kwa Wayahudi na hivyo akamwuliza Paulo, "Je, ungependa kwenda Yerusalemu na huko ukahukumiwe mbele yangu kuhusu mashtaka haya?"'),
(2018476,69,44,25,10,'Paulo akajibu, "Nasimama mbele ya mahakama ya Kaisari na papa hapa ndipo ninapopaswa kupewa hukumu. Kama unavyojua vizuri, sikuwatendea Wayahudi ubaya wowote.'),
(2018477,69,44,25,11,'Basi, ikiwa nimepatikana na kosa linalostahili adhabu ya kifo, siombi kusamehewa adhabu hiyo. Lakini kama hakuna ukweli katika mashtaka waliyotoa watu hawa, hakuna awezaye kunikabidhi kwao. Nakata rufani kwa Kaisari!"'),
(2018478,69,44,25,12,'Basi, baada ya Festo kuzungumza na washauri wake, akamwambia Paulo, "Umekata rufani kwa Kaisari, basi, utakwenda kwa Kaisari."'),
(2018479,69,44,25,13,'Siku chache baadaye, mfalme Agripa na Bernike walifika Kaisarea ili kutoa heshima zao kwa Festo.'),
(2018480,69,44,25,14,'Walikuwa huko siku kadhaa naye Festo akamweleza mfalme kesi ya Paulo: "Kuna mtu mmoja hapa ambaye Felisi alimwacha kizuizini.'),
(2018481,69,44,25,15,'Nilipokwenda Yerusalemu makuhani wakuu na wazee wa Wayahudi walimshtaki na kuniomba nimhukumu.'),
(2018482,69,44,25,16,'Lakini mimi niliwajibu kwamba si desturi ya Waroma kumtoa mtu aadhibiwe kabla mshtakiwa hajakutana na washtaki wake ana kwa ana na kupewa fursa ya kujitetea kuhusu hayo mashtaka.'),
(2018483,69,44,25,17,'Basi, walipofika hapa sikukawia, ila nilifanya kikao mahakamani kesho yake, nikaamuru mtu huyo aletwe.'),
(2018484,69,44,25,18,'Washtaki wake walisimama lakini hawakutoa mashtaka maovu kama nilivyokuwa ninatazamia.'),
(2018485,69,44,25,19,'Ila tu walikuwa na mabishano kadhaa pamoja naye kuhusu dini yao na kuhusu mtu mmoja aitwaye Yesu ambaye alikufa, lakini Paulo anashikilia kwamba yu hai.'),
(2018486,69,44,25,20,'Sikujua la kufanya kuhusu shauri hilo. Basi, nilimwuliza Paulo kama angependa kwenda mahakamani kule Yerusalemu kwa ajili ya mashtaka hayo.'),
(2018487,69,44,25,21,'Lakini Paulo alikata rufani, akaomba aachwe kizuizini mpaka uamuzi wa shauri hilo ufanywe na Kaisari. Kwa hiyo niliamua akae kizuizini mpaka nitakapoweza kumpeleka kwa Kaisari."'),
(2018488,69,44,25,22,'Basi Agripa akamwambia Festo, "Ningependa kumsikia mtu huyu mimi mwenyewe." Festo akamwambia, "Utamsikia kesho."'),
(2018489,69,44,25,23,'Hivyo, kesho yake, Agripa na Bernike walifika kwa shangwe katika ukumbi wa mkutano wakiwa wameandamana na wakuu wa majeshi na viongozi wa mji. Festo aliamuru Paulo aletwe ndani,'),
(2018490,69,44,25,24,'Kisha akasema, "Mfalme Agripa na wote mlioko hapa pamoja nasi! Hapa mbele yenu yuko mtu ambaye jumuiya yote ya Wayahudi hapa na kule Yerusalemu walinilalamikia wakipiga kelele kwamba hastahili kuishi tena.'),
(2018491,69,44,25,25,'Lakini mimi sikuona kuwa alikuwa ametenda chochote kibaya hata astahili kupewa adhabu ya kifo. Lakini, kwa vile Paulo mwenyewe alikata rufani kwa Kaisari, niliamua kumpeleka.'),
(2018492,69,44,25,26,'Kwa upande wangu sina habari kamili ambayo naweza kumwandikia Kaisari juu yake. Ndiyo maana nimemleta hapa mbele yenu na mbele yako mfalme Agripa, ili baada ya kumchunguza, niweze kuwa na la kuandika.'),
(2018493,69,44,25,27,'Kwa maana nadhani itakuwa kichekesho kumpeleka mfungwa bila kutaja wazi mashtaka yanayomkabili."'),
(2018494,69,44,26,1,'Basi, Agripa akamwambia Paulo, "Unaruhusiwa kujitetea." Hapo Paulo alinyosha mkono wake akajitetea hivi:'),
(2018495,69,44,26,2,'"Mfalme Agripa, ninajiona mwenye bahati leo kujitetea mbele yako kuhusu yale mashtaka yote ambayo Wayahudi walikuwa wamesema juu yangu.'),
(2018496,69,44,26,3,'Hasa kwa vile wewe mwenyewe ni mtaalamu wa desturi za Wayahudi na migogoro yao, ninakuomba basi unisikilize kwa uvumilivu.'),
(2018497,69,44,26,4,'"Wayahudi wanajua habari za maisha yangu tangu utoto, jinsi nilivyoishi tangu mwanzo kati ya taifa langu huko Yerusalemu.'),
(2018498,69,44,26,5,'Wananifahamu kwa muda mrefu, na wanaweza kushuhudia, kama wakipenda, kwamba tangu mwanzo niliishi kama mmoja wa kikundi chenye siasa kali zaidi katika dini yetu, yaani kikundi cha Mafarisayo.'),
(2018499,69,44,26,6,'Na sasa niko hapa nihukumiwe kwa sababu ninaitumainia ile ahadi ambayo Mungu aliwaahidia babu zetu.'),
(2018500,69,44,26,7,'Ahadi hiyo ndiyo ileile inayotumainiwa na makabila kumi na mawili ya taifa letu, wakimtumikia Mungu kwa dhati mchana na usiku. Mheshimiwa mfalme, Wayahudi wananishtaki kwa sababu ya tumaini hilo!'),
(2018501,69,44,26,8,'Kwa nini ninyi mnaona shida sana kuamini kwamba Mungu huwafufua wafu?'),
(2018502,69,44,26,9,'Kwa kweli mimi mwenyewe niliamini kwamba ni wajibu wangu kufanya mambo mengi kulipinga jina la Yesu wa Nazareti.'),
(2018503,69,44,26,10,'Mambo hayo ndiyo niliyoyafanya huko Yerusalemu. Mimi binafsi, nikiwa nimepewa mamlaka kutoka kwa makuhani wakuu, nilipata kuwatia gerezani wengi wa watu wa Mungu. Nao walipohukumiwa kuuawa, nilipiga kura ya kukubali.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018504,69,44,26,11,'Mara nyingi niliwafanya waadhibiwe katika masunagogi yote nikiwashurutisha waikane imani yao. Hasira yangu kwao ilikuwa kubwa hata nikawasaka mpaka miji ya mbali.'),
(2018505,69,44,26,12,'"Kwa mujibu huohuo, nilikwenda Damasko wakati mmoja, nikiwa na mamlaka na maagizo kutoka kwa makuhani wakuu.'),
(2018506,69,44,26,13,'Mheshimiwa, wakati nilipokuwa njiani, saa sita mchana, niliona mwanga mkubwa kuliko wa jua ukiangaza kutoka mbinguni, ukanizunguka mimi na wale wasafiri wenzangu.'),
(2018507,69,44,26,14,'Sisi sote tulianguka chini, nami nikasikia sauti ikiniambia kwa Kiebrania: `Saulo, Saulo! Kwa nini unanitesa? Unajiumiza bure kama punda anayepiga teke fimbo ya bwana wake.`'),
(2018508,69,44,26,15,'Mimi nikauliza: `Ni nani wewe Bwana?` Naye Bwana akajibu: `Mimi ni Yesu ambaye wewe unamtesa.'),
(2018509,69,44,26,16,'Haidhuru, inuka sasa; simama wima. Nimekutokea ili nikuweke rasmi kuwa mtumishi wangu. Utawathibitishia watu wengine mambo uliyoyaona leo na yale ambayo bado nitakuonyesha.'),
(2018510,69,44,26,17,'Nitakuokoa na watu wa Israeli na watu wa mataifa mengine ambao mimi ninakutuma kwao.'),
(2018511,69,44,26,18,'Utayafumbua macho yao na kuwawezesha watoke gizani na kuingia katika mwanga; watoke katika utawala wa Shetani, wamgeukie Mungu; ili kwa kuamini, wapate kusamehewa dhambi na kuchukua nafasi yao kati ya wale ambao wamepata kuwa watu wa Mungu.`'),
(2018512,69,44,26,19,'"Hivyo, mfalme Agripa, sikuweza kuwa mkaidi kwa maono hilo la mbinguni.'),
(2018513,69,44,26,20,'Ila nilianza kuhubiri kwanza kwa watu wa Damasko, halafu kwa wale wa Yerusalemu na nchi yote ya Yudea, na pia kwa watu wa mataifa mengine. Niliwahimiza wamgeukie Mungu na kuonyesha kwa vitendo kwamba wamebadilisha mioyo yao.'),
(2018514,69,44,26,21,'Kwa sababu hiyo, Wayahudi walinikamata nikiwa Hekaluni, wakajaribu kuniua.'),
(2018515,69,44,26,22,'Lakini Mungu alinisaidia; na hivyo mpaka siku ya leo nimesimama imara nikitoa ushuhuda kwa wote, wakubwa na wadogo. Ninayosema ni yale ambayo manabii na Mose walisema yatatukia;'),
(2018516,69,44,26,23,'yaani ilimpasa Kristo ateseke na kuwa wa kwanza kufufuka kutoka wafu, ili atangaze kwamba mwanga wa ukombozi unawaangazia sasa watu wote, Wayahudi na pia watu wa mataifa mengine."'),
(2018517,69,44,26,24,'Paulo alipofika hapa katika kujitetea kwake, Festo alisema kwa sauti kubwa, "Paulo! Una wazimu! Kusoma kwako kwingi kunakutia wazimu!"'),
(2018518,69,44,26,25,'Lakini Paulo akasema, "Sina wazimu mheshimiwa Festo: Ninachosema ni ukweli mtupu.'),
(2018519,69,44,26,26,'Wewe Mfalme unayafahamu mambo haya, kwa hiyo ninaweza kuongea bila uoga mbele yako. Sina mashaka kwamba matukio hayo yanajulikana kwako maana jambo hili halikutendeka mafichoni.'),
(2018520,69,44,26,27,'Mfalme Agripa, je, una imani na manabii? Najua kwamba unaamini."'),
(2018521,69,44,26,28,'Agripa akamjibu Paulo, "Kidogo tu utanifanya Mkristo!"'),
(2018522,69,44,26,29,'Paulo akamjibu, "Namwomba Mungu kwamba, kwa muda mfupi au mrefu, si wewe tu bali wote wanaonisikia leo wapate kuwa kama nilivyo mimi, lakini bila hii minyororo."'),
(2018523,69,44,26,30,'Hapo mfalme Agripa, mkuu wa mkoa, Bernike na wale wote waliokuwa pamoja nao, walisimama.'),
(2018524,69,44,26,31,'Walipokwisha ondoka, waliambiana, "Mtu huyu hakufanya chochote kinachostahili adhabu ya kifo au kifungo."'),
(2018525,69,44,26,32,'Naye Agripa akamwambia Festo, "Mtu huyu angeweza kufunguliwa kama asingalikuwa amekata rufani kwa Kaisari."'),
(2018526,69,44,27,1,'Walipokwisha amua tusafiri mpaka Italia, walimweka Paulo pamoja na wafungwa wengine chini ya ulinzi wa Yulio aliyekuwa ofisa wa jeshi katika kikosi kiitwacho "Kikosi cha Augusto."'),
(2018527,69,44,27,2,'Tulipanda meli ya Adiramito iliyokuwa inasafiri na kupitia bandari kadhaa za mkoa wa Asia, tukaanza safari. Aristarko, mwenyeji wa Makedonia kutoka Thesalonika, alikuwa pamoja nasi.'),
(2018528,69,44,27,3,'Kesho yake tulitia nanga katika bandari ya Sidoni. Yulio alimtendea Paulo vizuri kwa kumruhusu awaone rafiki zake na kupata mahitaji yake.'),
(2018529,69,44,27,4,'Kutoka huko tuliendelea na safari, lakini kwa kuwa upepo ulikuwa unavuma kwa kasi kutujia kwa mbele, tulipitia upande wa kisiwa cha Kupro ambapo upepo haukuwa mwingi.'),
(2018530,69,44,27,5,'Halafu tulivuka bahari ya Kilikia na Pamfulia, tukatia nanga Mura, mji wa Lukia.'),
(2018531,69,44,27,6,'Hapo yule ofisa alikuta meli moja ya Aleksandria iliyokuwa inakwenda Italia, na hivyo akatupandisha ndani.'),
(2018532,69,44,27,7,'Kwa muda wa siku nyingi tulisafiri polepole, na kwa shida tulifika karibu na Nido. Kwa sababu upepo ulikuwa bado unatupinga, tuliendelea mbele moja kwa moja tukapitia upande wa Krete karibu na rasi Salmone ambapo upepo haukuwa mwingi.'),
(2018533,69,44,27,8,'Tulipita kando yake polepole tukafika mahali paitwapo "Bandari Nzuri", karibu na mji wa Lasea.'),
(2018534,69,44,27,9,'Muda mrefu ulikuwa umepita, na hata siku ya kufunga ilikuwa imekwisha pita. Sasa ilikuwa hatari sana kusafiri kwa meli. Basi, Paulo aliwapa onyo:'),
(2018535,69,44,27,10,'"Waheshimiwa, nahisi kwamba safari hii itakuwa ya shida na hasara nyingi si kwa shehena na meli tu, bali pia kwa maisha yetu."'),
(2018536,69,44,27,11,'Lakini yule ofisa alivutiwa zaidi na maoni ya nahodha na ya mwenye meli kuliko yale aliyosema Paulo.'),
(2018537,69,44,27,12,'Kwa kuwa bandari hiyo haikuwa mahali pazuri pa kukaa wakati wa baridi, wengi walipendelea kuendelea na safari, ikiwezekana mpaka Foinike. Foinike ni bandari ya Krete inayoelekea kusini-magharibi na kaskazini-magharibi; na huko wangeweza kukaa wakati wa baridi.'),
(2018538,69,44,27,13,'Basi, upepo mzuri wa kusi ulianza kuvuma, nao wakadhani wamefanikiwa lengo lao; hivyo wakang`oa nanga, wakaiendesha meli karibu sana na pwani ya Krete.'),
(2018539,69,44,27,14,'Lakini haukupita muda, upepo mkali uitwao "Upepo wa Kaskazi" ulianza kuvuma kutoka kisiwani.'),
(2018540,69,44,27,15,'Upepo uliipiga ile meli, na kwa kuwa hatukuweza kuukabili, tukaiacha ikokotwe na huo upepo.'),
(2018541,69,44,27,16,'Kisiwa kimoja kiitwacho Kanda kilitukinga kidogo na ule upepo; na tulipopita kusini mwake tulifaulu, ingawa kwa shida, kuusalimisha ule mtumbwi wa meli.'),
(2018542,69,44,27,17,'Wale wanamaji waliuvuta mtumbwi ndani, kisha wakaizungushia meli kamba na kuifunga kwa nguvu. Waliogopa kwamba wangeweza kukwama kwenye ufuko wa bahari, pwani ya Libya. Kwa hiyo walishusha matanga na kuiacha meli ikokotwe na upepo.'),
(2018543,69,44,27,18,'Dhoruba iliendelea kuvuma na kesho yake wakaanza kutupa nje shehena ya meli.'),
(2018544,69,44,27,19,'Siku ya tatu, wakaanza pia kutupa majini vifaa vya meli kwa mikono yao wenyewe.'),
(2018545,69,44,27,20,'Kwa muda wa siku nyingi hatukuweza kuona jua wala nyota; dhoruba iliendelea kuvuma sana, hata matumaini yote ya kuokoka yakatuishia.'),
(2018546,69,44,27,21,'Baada ya kukaa muda mrefu bila kula chakula, Paulo alisimama kati yao, akasema, "Waheshimiwa, ingalikuwa afadhali kama mngalinisikiliza na kuacha kusafiri kutoka Krete. Kama mngalifanya hivyo tungaliiepuka shida hii na hasara hizi zote.'),
(2018547,69,44,27,22,'Lakini sasa ninawaombeni muwe na moyo; hakuna hata mmoja wenu atakayepoteza maisha yake; meli tu ndiyo itakayopotea.'),
(2018548,69,44,27,23,'Kwa maana jana usiku malaika wa yule Mungu ambaye mimi ni wake na ambaye mimi ninamwabudu alinitokea,'),
(2018549,69,44,27,24,'akaniambia: `Paulo usiogope! Ni lazima utasimama mbele ya Kaisari; naye Mungu, kwa wema wake, amekufadhili kwa kuwaokoa wote wanaosafiri nawe wasiangamie.`'),
(2018550,69,44,27,25,'Hivyo, waheshimiwa, jipeni moyo! Maana ninamwamini Mungu kwamba itakuwa sawa kama nilivyoambiwa.'),
(2018551,69,44,27,26,'Lakini ni lazima tutatupwa ufukoni mwa kisiwa fulani."'),
(2018552,69,44,27,27,'Usiku wa siku ya kumi na nne, tulikuwa tunakokotwa huku na huku katika bahari ya Adria. Karibu na usiku wa manane wanamaji walijihisi kuwa karibu na nchi kavu.'),
(2018553,69,44,27,28,'Hivyo walitafuta kina cha bahari kwa kuteremsha kamba iliyokuwa imefungiwa kitu kizito, wakapata kina cha mita arobaini. Baadaye wakapima tena wakapata mita thelathini.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018554,69,44,27,29,'Kwa sababu ya kuogopa kukwama kwenye miamba, waliteremsha nanga nne nyuma ya meli; wakaomba kuche upesi.'),
(2018555,69,44,27,30,'Wanamaji walitaka kutoroka, na walikwisha kuteremsha ule mtumbwi majini, wakijisingizia kwamba wanakwenda kuteremsha nanga upande wa mbele wa meli.'),
(2018556,69,44,27,31,'Lakini Paulo alimwambia yule ofisa wa jeshi na askari wake, "Kama wanamaji hawa hawabaki ndani ya meli, hamtaokoka."'),
(2018557,69,44,27,32,'Hapo wale askari walizikata kamba zilizokuwa zimeshikilia ule mtumbwi, wakauacha uchukuliwe na maji.'),
(2018558,69,44,27,33,'Karibu na alfajiri, Paulo aliwahimiza wote wale chakula: "Kwa siku kumi na nne sasa mmekuwa katika mashaka na bila kula; hamjala kitu chochote.'),
(2018559,69,44,27,34,'Basi, ninawasihi mle chakula kwa maana mnakihitaji ili mweze kuendelea kuishi. Maana hata unywele mmoja wa vichwa vyenu hautapotea."'),
(2018560,69,44,27,35,'Baada ya kusema hivyo, Paulo alichukua mkate, akamshukuru Mungu mbele yao wote, akaumega, akaanza kula.'),
(2018561,69,44,27,36,'Hapo wote wakapata moyo, nao pia wakala chakula.'),
(2018562,69,44,27,37,'Jumla tulikuwa watu mia mbili na sabini na sita katika meli.'),
(2018563,69,44,27,38,'Baada ya kila mmoja kula chakula cha kutosha, walipunguza uzito wa meli kwa kutupa nafaka baharini.'),
(2018564,69,44,27,39,'Kulipokucha, wanamaji hawakuweza kuitambua nchi ile, ila waliona ghuba moja yenye ufuko; wakaamua kutia nanga huko kama ikiwezekana.'),
(2018565,69,44,27,40,'Hivyo walikata nanga na kuziacha baharini, na wakati huohuo wakazifungua kamba zilizokuwa zimeufunga usukani, kisha wakatweka tanga moja mbele kushika upepo, wakaelekea ufukoni.'),
(2018566,69,44,27,41,'Lakini walifika mahali ambapo mikondo miwili ya bahari hukutana, na meli ikakwama. Sehemu ya mbele ilikuwa imezama mchangani bila kutikisika. Sehemu ya nyuma ya meli ilianza kuvunjika vipandevipande kwa mapigo ya nguvu ya mawimbi.'),
(2018567,69,44,27,42,'Askari walitaka kuwaua wafungwa wote kwa kuogopa kwamba wangeogelea hadi pwani na kutoroka.'),
(2018568,69,44,27,43,'Lakini kwa vile yule ofisajeshi alitaka kumwokoa Paulo, aliwazuia wasifanye hivyo. Aliamuru wale waliojua kuogelea waruke kutoka melini na kuogelea hadi pwani,'),
(2018569,69,44,27,44,'na wengine wafuate wakijishikilia kwenye mbao au kwenye vipande vya meli iliyovunjika. Ndivyo sisi sote tulivyofika salama pwani.'),
(2018570,69,44,28,1,'Tulipokwisha fika salama kwenye nchi kavu, tuligundua kwamba kile kisiwa kinaitwa Malta.'),
(2018571,69,44,28,2,'Wenyeji wa hapo walikuwa wema sana kwetu. Mvua ilikuwa inaanza kunyesha na kulikuwa na baridi, hivyo waliwasha moto, wakatukaribisha.'),
(2018572,69,44,28,3,'Paulo aliokota mzigo mdogo wa kuni akawa anazitia motoni. Hapo, kwa sababu ya lile joto la moto, nyoka akatoka katika kuni akamnasa Paulo mkononi na kujishikilia hapo.'),
(2018573,69,44,28,4,'Wenyeji wa pale walipokiona kile kiumbe kinaning`inia kwenye mkono wake waliambiana, "Bila shaka mtu huyu amekwisha ua mtu, na ingawa ameokoka kuangamia baharini, `Haki` haitamwacha aendelee kuishi!"'),
(2018574,69,44,28,5,'Lakini Paulo alikikung`utia kile kiumbe motoni na hakuumizwa hata kidogo.'),
(2018575,69,44,28,6,'Wale watu walikuwa wakitazamia kwamba angevimba au hapohapo angeanguka chini na kufa. Baada ya kungojea kwa muda mrefu bila kuona kwamba Paulo amepatwa na jambo lolote lisilo la kawaida, walibadilisha fikira zao juu yake, wakasema kuwa ni mungu.'),
(2018576,69,44,28,7,'Karibu na mahali pale palikuwa na mashamba ya Publio, mkuu wa kile kisiwa. Publio alitukaribisha kirafiki, tukawa wageni wake kwa siku tatu.'),
(2018577,69,44,28,8,'Basi, ikawa kwamba baba yake Publio alikuwa amelala kitandani, mgonjwa, ana homa na kuhara. Paulo alikwenda kumwona na baada ya kusali, akaweka mikono yake juu ya mgonjwa, akamponya.'),
(2018578,69,44,28,9,'Kutokana na tukio hilo, wagonjwa wote katika kile kisiwa walikuja wakaponywa.'),
(2018579,69,44,28,10,'Watu walitupatia zawadi mbalimbali na wakati tulipoanza tena safari, walitia ndani ya meli masurufu tuliyohitaji.'),
(2018580,69,44,28,11,'Baada ya miezi mitatu tulianza tena safari yetu kwa meli moja ya Aleksandria iitwayo "Miungu Pacha". Meli hiyo ilikuwa imetia nanga kisiwani wakati wote wa baridi.'),
(2018581,69,44,28,12,'Tulifika katika mji wa Sirakusa, tukakaa hapo kwa siku tatu.'),
(2018582,69,44,28,13,'Toka huko tuling`oa nanga, tukazunguka na kufika Regio. Baada ya siku moja, upepo ulianza kuvuma kutoka kusini, na baada ya siku mbili tulifika bandari ya Potioli.'),
(2018583,69,44,28,14,'Huko tuliwakuta ndugu kadhaa ambao walituomba tukae nao kwa juma moja. Hivi ndivyo tulivyopata kufika Roma.'),
(2018584,69,44,28,15,'Ndugu wa kule Roma walipopata habari zetu, wakaja kutulaki kwenye soko la Apio na Mikahawa Mitatu. Paulo alipowaona alimshukuru Mungu, akapata moyo.'),
(2018585,69,44,28,16,'Tulipofika Roma, Paulo aliruhusiwa kukaa peke yake pamoja na askari mmoja wa kumlinda. ic'),
(2018586,69,44,28,17,'Baada ya siku tatu, Paulo aliwaita pamoja viongozi wa Kiyahudi wa mahali hapo. Walipokusanyika, Paulo aliwaambia, "Wananchi wenzangu, mimi, ingawa sikufanya chochote kibaya wala kupinga desturi za wazee wetu, nilitiwa nguvuni kule Yerusalemu na kutiwa mikononi mwa Waroma.'),
(2018587,69,44,28,18,'Waliponihoji na kuona kwamba sikuwa na hatia yeyote, walitaka kuniacha.'),
(2018588,69,44,28,19,'Lakini Wayahudi wengine walipinga jambo hilo, nami nikalazimika kukata rufani kwa Kaisari, ingawa sikuwa na chochote cha kuwashtaki wananchi wenzangu.'),
(2018589,69,44,28,20,'Ni kwa sababu hiyo nimeomba kuonana na kuongea nanyi, maana nimefungwa minyororo hii kwa sababu ya tumaini lile la Israeli."'),
(2018590,69,44,28,21,'Wao wakamwambia, "Sisi hatujapokea barua yoyote kutoka Yudea, wala hakuna ndugu yeyote aliyefika hapa na kutoa habari rasmi au kusema chochote kibaya juu yako.'),
(2018591,69,44,28,22,'Lakini tunafikiri inafaa tusikie kutoka kwako mwenyewe mambo yaliyo kichwani mwako. Kwa maana tujualo sisi kuhusu hicho kikundi ni kwamba kinapingwa kila mahali."'),
(2018592,69,44,28,23,'Basi, walipanga naye siku kamili ya kukutana, na wengi wakafika huko alikokuwa anakaa. Tangu asubuhi mpaka jioni Paulo aliwaeleza na kuwafafanulia juu ya Ufalme wa Mungu akijaribu kuwafanya wakubali habari juu ya Yesu kwa kutumia Sheria ya Mose na maandiko ya manabii.'),
(2018593,69,44,28,24,'Baadhi yao walikubali maneno yake, lakini wengine hawakuamini.'),
(2018594,69,44,28,25,'Basi, kukawa na mtengano wa fikira kati yao. Walipokuwa wanakwenda zao, Paulo alisema jambo hili, "Kweli ni sawa yale aliyoyanena Roho Mtakatifu kwa wazee wenu kwa njia ya nabii Isaya'),
(2018595,69,44,28,26,'akisema: `Nenda kwa watu hawa ukawaambie: kusikia mtasikia, lakini hamtaelewa; kutazama mtatazama, lakini hamtaona.'),
(2018596,69,44,28,27,'Maana akili za watu hawa zimepumbaa, wameziba masikio yao, wamefumba macho yao. La sivyo, wangeona kwa macho yao, wangesikia kwa masikio yao. Wangeelewa kwa akili zao, na kunigeukia, asema Bwana, nami ningewaponya."`'),
(2018597,69,44,28,28,'Halafu Paulo akamaliza na kusema, "Jueni basi, kwamba ujumbe wa Mungu juu ya wokovu umepelekwa kwa watu wa mataifa. Wao watasikiliza!"*fd* walijiondokea huku wakiwa wanabishana vikali wao kwa wao.'),
(2018598,69,44,28,29,'missing'),
(2018599,69,44,28,30,'Kwa muda wa miaka miwili mizima Paulo aliishi katika nyumba aliyoipanga yeye mwenyewe; akawa anawakaribisha wote waliofika kumsalimu.'),
(2018600,69,44,28,31,'Alikuwa akihubiri Ufalme wa Mungu na kufundisha juu ya Bwana Yesu Kristo kwa uhodari, bila kizuizi.'),
(2018601,69,45,1,1,'Kutoka kwangu mimi Paulo, mtumishi wa Kristo Yesu, na mtume niliyeteuliwa na kuitwa kwa ajili ya kuhubiri Habari Njema ya Mungu.'),
(2018602,69,45,1,2,'Hapo kale, Mungu aliwaahidia watu hii Habari Njema kwa njia ya manabii wake katika Maandiko Matakatifu.'),
(2018603,69,45,1,3,'Hii Habari Njema inamhusu Mwana wa Mungu, Bwana wetu Yesu Kristo, ambaye mintarafu ubinadamu wake, alikuwa mzawa wa Daudi;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018604,69,45,1,4,'mintarafu utakatifu wake wa kimungu, alithibitishwa kwa uwezo mkuu kwamba ni Mwana wa Mungu kwa kufufuliwa kutoka wafu.'),
(2018605,69,45,1,5,'Kwa njia yake, mimi nimepewa neema ya kuwa mtume, ili kwa ajili yake niwaongoze watu wa mataifa yote wapate kuamini na kutii.'),
(2018606,69,45,1,6,'Ninyi ni miongoni mwa watu hao; mmeitwa muwe watu wake Yesu Kristo.'),
(2018607,69,45,1,7,'Basi, ninawaandikia ninyi nyote mlioko Roma ambao Mungu anawapenda, akawateua muwe watu wake. Nawatakieni neema na amani kutoka kwa Mungu Baba yetu na Bwana Yesu Kristo.'),
(2018608,69,45,1,8,'Awali ya yote, namshukuru Mungu wangu kwa njia ya Yesu Kristo kwa ajili yenu nyote, kwa sababu imani yenu inasikika duniani kote.'),
(2018609,69,45,1,9,'Mungu, ambaye ninamtumikia kwa moyo wangu wote katika kuhubiri Habari Njema ya Mwanae, ni shahidi wangu kwamba ninawakumbukeni'),
(2018610,69,45,1,10,'daima katika sala zangu. Namwomba Mungu akipenda, anipatie nafasi nzuri ya kuja kwenu sasa.'),
(2018611,69,45,1,11,'Kwa maana ninatamani sana kuwaoneni ili nipate kuwagawieni zawadi ya kiroho na kuwaimarisha.'),
(2018612,69,45,1,12,'Ndiyo kusema, tutaimarishana: imani yenu itaniimarisha mimi, na yangu itawaimarisha ninyi.'),
(2018613,69,45,1,13,'Ndugu zangu, nataka mjue kwamba mara nyingi nilikusudia kuwatembeleeni, lakini mpaka sasa nimezuiwa. Ningependa kupata mafanikio mema kati yenu kama nilivyopata kati ya watu wa mataifa mengine.'),
(2018614,69,45,1,14,'Ninalo jukumu kwa watu wote, waliostaarabika na wasiostaarabika, wenye elimu na wasio na elimu.'),
(2018615,69,45,1,15,'Ndiyo maana ninatamani pia kuihubiri Habari Njema kwenu ninyi mlioko huko Roma.'),
(2018616,69,45,1,16,'Sioni aibu kutangaza Habari Njema; yenyewe ni nguvu ya Mungu inayowaokoa wote wanaoamini: Wayahudi kwanza, na wasio Wayahudi pia.'),
(2018617,69,45,1,17,'Kwa maana Habari Njema inaonyesha wazi jinsi Mungu anavyowakubali watu kuwa waadilifu; jambo hili hufanyika kwa imani, tangu mwanzo mpaka mwisho. Kama ilivyoandikwa: "Mwadilifu*fa* kwa imani ataishi."'),
(2018618,69,45,1,18,'Ghadhabu ya Mungu imedhihirishwa kutoka mbinguni dhidi ya uasi na uovu wote wa binadamu ambao kwa njia zao mbaya wanaupinga ukweli usijulikane.'),
(2018619,69,45,1,19,'Kwa maana, yote yanayoweza kujulikana juu ya Mungu ni wazi kwao; maana Mungu mwenyewe ameyadhirisha.'),
(2018620,69,45,1,20,'Tangu Mungu alipoumba ulimwengu, uwezo wake wa milele na uungu wake, ingawa havionekani kwa macho, vinafahamika wazi. Watu wanaweza kuyajua mambo hayo kutokana na vitu hivyo alivyoumba Mungu. Kwa hiyo hawana njia yoyote ya kujitetea!'),
(2018621,69,45,1,21,'Ingawa wanajua kuna Mungu, lakini hawampi heshima anayostahili, wala hawamshukuru. Badala yake, fikira zao zimekuwa batili na akili zao tupu zimejaa giza.'),
(2018622,69,45,1,22,'Wanajidai kuwa wenye hekima, kumbe ni wapumbavu.'),
(2018623,69,45,1,23,'Wanaacha kumwabudu Mungu aishiye milele, na badala yake, wanaabudu sanamu zilizo mfano wa binadamu ambaye hufa, mfano wa wanyama, ndege, au wanyama watambaao.'),
(2018624,69,45,1,24,'Kwa sababu hiyo, Mungu amewaacha wafuate tamaa mbaya za mioyo yao na kufanyiana mambo ya aibu kwa miili yao.'),
(2018625,69,45,1,25,'Wanaubadili ukweli juu ya Mungu kwa uongo; wanaheshimu na kuabudu kiumbe badala ya Muumba mwenyewe, ambaye ndiye astahiliye sifa milele! Amina.'),
(2018626,69,45,1,26,'Kwa hiyo, Mungu amewaacha wafuate tamaa mbaya. Hata wanawake wanabadili matumizi yanayopatana na maumbile.'),
(2018627,69,45,1,27,'Nao wanaume hali kadhalika, wanaacha kufuata matumizi ya maumbile ya mume na mke wakawakiana tamaa wao kwa wao. Wanaume wanafanyiana mambo ya aibu, na hivyo wanajiletea wenyewe adhabu wanayostahili kwa vitendo vyao viovu.'),
(2018628,69,45,1,28,'Kwa vile watu walikataa kumtambua Mungu, Mungu amewaacha katika fikira zao potovu, wakafanya yale ambayo hawangestahili kufanya.'),
(2018629,69,45,1,29,'Wamejaa kila aina ya uovu, dhuluma, ulafi na ufisadi. Wamejaa wivu, uuaji, ugomvi, udanganyifu na nia mbaya; husengenya,'),
(2018630,69,45,1,30,'na kusingiziana; ni watu wa kuchukiza kwa Mungu, wafidhuli, wenye kiburi na majivuno; hodari sana katika kutenda mabaya, na hawawatii wazazi wao;'),
(2018631,69,45,1,31,'hawana dhamiri, hawatimizi ahadi zao, hawana wema wala huruma kwa wengine.'),
(2018632,69,45,1,32,'Wanajua kwamba Sheria ya Mungu yasema kwamba watu wanaoishi mithili hiyo, wanastahili kifo. Zaidi ya hayo, siyo tu kwamba wanafanya mambo hayo wao wenyewe, bali hata huwapongeza wale wanaofanya mambo hayohayo.'),
(2018633,69,45,2,1,'Basi, rafiki, kama unawahukumu wengine, huwezi kamwe kujitetea haidhuru wewe ni nani. Kwa maana, kwa kuwahukumu wengine, unajilaani wewe mwenyewe kwa vile nawe unayafanya mambo yaleyale unayohukumu.'),
(2018634,69,45,2,2,'Tunajua kwamba hukumu ya Mungu kwa wale wanaofanya mambo kama hayo ni hukumu ya haki.'),
(2018635,69,45,2,3,'Lakini wewe, rafiki, unayewahukumu wale wanaofanya mambo kama hayo bali wewe pia unayafanya, je unadhani utaiepa hukumu ya Mungu?'),
(2018636,69,45,2,4,'Au labda unaudharau wema wake mkuu, uvumilivu wake na saburi yake, bila kutambua kwamba wema wake huo una shabaha ya kukuongoza upate kutubu?'),
(2018637,69,45,2,5,'Lakini unao ugumu na ukaidi wa moyo, na hivyo unajilundikia adhabu kwa Siku ile ambayo ghadhabu ya Mungu na hukumu zake za haki vitadhihirishwa.'),
(2018638,69,45,2,6,'Siku hiyo Mungu atamlipa kila mmoja kufuatana na matendo yake.'),
(2018639,69,45,2,7,'Wale wanaozingatia kutenda mema, kutafuta utukufu na heshima ya Mungu na kutokufa, watapata uzima wa milele.'),
(2018640,69,45,2,8,'Lakini wale wengine wenye ubinafsi, wenye kukataa mambo ya haki na kufuata uovu, wataangukiwa na ghadhabu na hasira ya Mungu.'),
(2018641,69,45,2,9,'Mateso na maumivu yatampata binadamu yeyote atendaye uovu. Yatawapata Wayahudi kwanza, na watu wa mataifa mengine pia.'),
(2018642,69,45,2,10,'Lakini Mungu atawapa utukufu, heshima na amani wale wanaotenda mema; Wayahudi kwanza, na watu wa mataifa mengine pia.'),
(2018643,69,45,2,11,'Maana Mungu hambagui mtu yeyote.'),
(2018644,69,45,2,12,'Wale wanaotenda dhambi bila kuijua Sheria ya Mose wataangamia ingawaje hawajui Sheria. Na wale wanaotenda dhambi wakiwa wanaijua Sheria watahukumiwa kisheria.'),
(2018645,69,45,2,13,'Mtu hafanywi kuwa mwadilifu mbele yake Mungu kwa kuisikia Sheria, bali kwa kuitii Sheria.'),
(2018646,69,45,2,14,'Mathalan: watu wa mataifa mengine hawana Sheria ya Mose; lakini kila wanapotimiza matakwa ya Sheria wakiongozwa na dhamiri zao, wao wenyewe wanakuwa kipimo cha Sheria ingawa hawaijui Sheria.'),
(2018647,69,45,2,15,'Mwenendo wao unaonyesha kwamba matakwa ya Sheria yameandikwa mioyoni mwao. Dhamiri zao zinashuhudia pia jambo hilo, maana fikira zao mara nyingine huwashtaki, na mara nyingine huwatetea.'),
(2018648,69,45,2,16,'Hivyo, kufuatana na hii Habari Njema ninayohubiri, ndivyo itakavyokuwa wakati Mungu atakapohukumu mambo ya siri ya binadamu kwa njia ya Yesu Kristo.'),
(2018649,69,45,2,17,'Na wewe, je? Wewe mwenyewe unajiita Myahudi; unaitumainia Sheria na kujivunia kuwa wa Mungu;'),
(2018650,69,45,2,18,'kwa njia ya Sheria unajua matakwa ya Mungu na unaweza kuchagua jambo jema;'),
(2018651,69,45,2,19,'wewe unajiona kuwa kiongozi wa vipofu na mwanga kwa wale walio gizani;'),
(2018652,69,45,2,20,'unajiona kuwa mkufunzi wa wajinga na mwalimu wa wale wasiokomaa bado. Unayo katika Sheria picha kamili ya elimu na ukweli.'),
(2018653,69,45,2,21,'Basi, wewe unawafundisha wengine; kwa nini hujifundishi wewe mwenyewe? Unawahubiria wengine wasiibe, lakini kumbe wewe mwenyewe unaiba.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018654,69,45,2,22,'Unasema: "Msizini," na huku wewe unazini; unachukia sanamu za miungu hali wewe unajitajirisha kwa kuiba katika nyumba za miungu.'),
(2018655,69,45,2,23,'Kwa kujigamba ati unayo Sheria ya Mungu, je huoni kwamba kwa kuivunja Sheria unamdharau Mungu?'),
(2018656,69,45,2,24,'Kama vile Maandiko Matakatifu yasemavyo: "Watu wa mataifa mengine wamelikufuru jina la Mungu kwa sababu yenu ninyi Wayahudi!"'),
(2018657,69,45,2,25,'Kutahiriwa kwako kutakuwa na maana kama ukiitii Sheria. Lakini kama unaivunja Sheria, basi, ni afadhali ungalibaki bila kutahiriwa.'),
(2018658,69,45,2,26,'Kama mtu wa mataifa mengine ambaye hakutahiriwa akitimiza matakwa ya Sheria, hakika atafikiriwa kana kwamba ametahiriwa.'),
(2018659,69,45,2,27,'Watu wa mataifa mengine watakuhukumu wewe Myahudi kama ukiivunja Sheria, ingawaje unayo maandishi ya Sheria na umetahiriwa, hali wao wanaitii Sheria ingawa hawakutahiriwa.'),
(2018660,69,45,2,28,'Ndiyo kusema, si kila anayeonekana kwa nje kuwa Myahudi ni Myahudi wa kweli, wala mtu hawi Myahudi wa kweli ati kwa kuwa ametahiriwa kimwili.'),
(2018661,69,45,2,29,'Myahudi wa kweli ni yule aliye Myahudi kwa ndani, yaani yule ambaye ametahiriwa moyoni. Hili ni jambo la Roho, na si jambo la maandishi ya Sheria. Mtu wa namna hiyo anapata sifa, si kutoka kwa watu, bali kutoka kwa Mungu.'),
(2018662,69,45,3,1,'Basi, Myahudi ana nini zaidi kuliko watu wengine? Au kutahiriwa kuna faida gani?'),
(2018663,69,45,3,2,'Naam, iko faida kwa kila upande. Kwanza, Mungu aliwakabidhi Wayahudi ujumbe wake.'),
(2018664,69,45,3,3,'Lakini itakuwaje iwapo baadhi yao hawakuwa waaminifu? Je, jambo hilo litaondoa uaminifu wa Mungu?'),
(2018665,69,45,3,4,'Hata kidogo! Mungu hubaki mwaminifu daima, ingawaje kila binadamu ni mwongo. Kama Maandiko Matakatifu yasemavyo: "Kila usemapo, maneno yako ni ya haki; na katika hukumu, wewe hushinda."'),
(2018666,69,45,3,5,'Lakini, ikiwa uovu wetu unathibitisha kwamba Mungu anatenda kwa haki, tutasema nini? Je, tutasema kwamba anakosa haki akituadhibu? (Hapa naongea kibinadamu).'),
(2018667,69,45,3,6,'Hata kidogo! Ingekuwa hivyo, Mungu angewezaje kuuhukumu ulimwengu?'),
(2018668,69,45,3,7,'Labda utasema: "Ikiwa ukosefu wa uaminifu kwa upande wangu unamdhihirisha Mungu kuwa mwaminifu zaidi na hivyo kumpatia utukufu, basi singepaswa kuhukumiwa kuwa mwenye dhambi!"'),
(2018669,69,45,3,8,'Ni sawa na kusema: tufanye maovu ili tupate mema! Ndivyo wengine walivyotukashifu kwa kutushtaki kwamba tumefundisha hivyo. Watahukumiwa wanavyostahili!'),
(2018670,69,45,3,9,'Tuseme nini, basi? Je, sisi Wayahudi ni bora zaidi kuliko wengine? Hata kidogo! Kwa maana nimekwisha bainisha hapo mwanzoni kwamba Wayahudi na watu wa mataifa mengine wote wako chini ya utawala wa dhambi.'),
(2018671,69,45,3,10,'Kama Maandiko Matakatifu yasemavyo: "Hakuna hata mmoja aliye mwadilifu!'),
(2018672,69,45,3,11,'Hakuna mtu anayeelewa, wala anayemtafuta Mungu.'),
(2018673,69,45,3,12,'Wote wamepotoka wote wamekosa; hakuna atendaye mema, hakuna hata mmoja.'),
(2018674,69,45,3,13,'Makoo yao ni kama kaburi wazi, ndimi zao zimejaa udanganyifu, midomoni mwao mwatoka maneno yenye sumu kama ya nyoka.'),
(2018675,69,45,3,14,'Vinywa vyao vimejaa laana chungu.'),
(2018676,69,45,3,15,'Miguu yao iko mbioni kumwaga damu,'),
(2018677,69,45,3,16,'popote waendapo husababisha maafa na mateso;'),
(2018678,69,45,3,17,'njia ya amani hawaijui.'),
(2018679,69,45,3,18,'Hawajali kabisa kumcha Mungu."'),
(2018680,69,45,3,19,'Tunajua kwamba Sheria huwahusu walio chini ya Sheria hiyo, hata hawawezi kuwa na kisingizio chochote, na ulimwengu wote uko chini ya hukumu ya Mungu.'),
(2018681,69,45,3,20,'Maana hakuna binadamu yeyote anayekubaliwa kuwa mwadilifu mbele yake Mungu kwa kuishika Sheria; kazi ya Sheria ni kumwonyesha tu mtu kwamba ametenda dhambi.'),
(2018682,69,45,3,21,'Lakini sasa, njia ya Mungu ya kuwakubali watu kuwa waadilifu imekwisha dhihirishwa, tena bila kutegemea Sheria. Sheria na manabii hushuhudia jambo hili.'),
(2018683,69,45,3,22,'Mungu huwakubali watu kuwa waadilifu kwa njia ya imani yao kwa Yesu Kristo; Mungu hufanya hivyo kwa wote wanaoamini; hakuna ubaguzi wowote.'),
(2018684,69,45,3,23,'Watu wote wametenda dhambi na wametindikiwa utukufu wa Mungu.'),
(2018685,69,45,3,24,'Lakini kwa zawadi ya neema ya Mungu, watu wote hukubaliwa kuwa waadilifu kwa njia ya Yesu Kristo anayewakomboa.'),
(2018686,69,45,3,25,'Mungu alimtoa Yesu kusudi, kwa damu yake, awe njia ya kuwaondolea watu dhambi zao kwa imani yao kwake. Alifanya hivyo ili apate kuonyesha kwamba yeye ni mwadilifu. Hapo zamani Mungu alikuwa mvumilivu bila kuzijali dhambi za watu;'),
(2018687,69,45,3,26,'lakini sasa, wakati huu, anazikabili dhambi za watu apate kuonyesha uadilifu wake. Kwa namna hiyo Mungu mwenyewe huonyesha kwamba yeye ni mwadilifu na kwamba humkubali kuwa mwadilifu mtu yeyote anayemwamini Yesu.'),
(2018688,69,45,3,27,'Basi, tunaweza kujivunia nini? Hakuna! Kwa nini? Je, kwa sababu ya kutimiza Sheria? La! Bali kwa sababu tunaamini.'),
(2018689,69,45,3,28,'Maana mtu hukubaliwa kuwa mwadilifu kwa imani, wala si kwa kutimiza matakwa ya Sheria.'),
(2018690,69,45,3,29,'Au je, Mungu nu Mungu wa Wayahudi tu, ama pia wa watu wa mataifa mengine? Naam, wa mataifa mengine pia.'),
(2018691,69,45,3,30,'Mungu ni mmoja, naye atawakubali Wayahudi kuwa waadilifu kwa imani yao, na watu wa mataifa mengine pia kwa imani yao.'),
(2018692,69,45,3,31,'Je, tunaitumia imani kuibatilisha Sheria? Hata kidogo; bali tunaipa Sheria thamani yake kamili.'),
(2018693,69,45,4,1,'Tuseme nini basi, juu ya Abrahamu baba yetu?'),
(2018694,69,45,4,2,'Kama Abrahamu alikubaliwa kuwa mwadilifu kutokana na matendo yake, basi, anacho kitu cha kujivunia mbele ya Mungu.'),
(2018695,69,45,4,3,'Kwa maana, Maandiko Matakatifu yasema: "Abrahamu alimwamini Mungu, naye Mungu akamkubali kuwa mwadilifu."'),
(2018696,69,45,4,4,'Mfanyakazi hulipwa mshahara; mshahara wake si zawadi bali ni haki yake.'),
(2018697,69,45,4,5,'Lakini mtu asiyetegemea matendo yake mwenyewe, bali anamwamini Mungu ambaye huwasamehe waovu, basi, Mungu huijali imani ya mtu huyo, na hivi humkubali kuwa mwadilifu.'),
(2018698,69,45,4,6,'Naye Daudi asema hivi juu ya furaha ya mtu ambaye Mungu amemkubali kuwa mwadilifu bila kuyajali matendo yake:'),
(2018699,69,45,4,7,'"Heri wale waliosamehewa makosa yao ambao makosa yao yamefutwa.'),
(2018700,69,45,4,8,'Heri mtu yule ambaye Bwana hataziweka dhambi zake katika kumbukumbu."'),
(2018701,69,45,4,9,'Je, hiyo ni kwa wale waliotahiriwa tu, ama pia kwa wale wasiotahiriwa? Ni kwa wale wasiotahiriwa pia. Kwa maana tumekwisha sema: "Abrahamu aliamini, naye Mungu akamkubali kuwa mwadilifu."'),
(2018702,69,45,4,10,'Je, Abrahamu alikubaliwa kabla ya kutahiriwa ama baada ya kutahiriwa? Kabla ya kutahiriwa, na si baada ya kutahiriwa.'),
(2018703,69,45,4,11,'Abrahamu alitahiriwa baadaye, na kutahiriwa huko kulikuwa alama iliyothibitisha kwamba Mungu alimkubali kuwa mwadilifu kwa sababu ya imani yake aliyokuwa nayo kabla ya kutahiriwa. Kwa hiyo, Abrahamu amekuwa baba wa wale wote ambao, ingawa hawakutahiriwa, wamemwamini Mungu, wakafanywa waadilifu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018704,69,45,4,12,'Vilevile yeye ni baba wa wale waliotahiriwa; lakini si kwa kuwa wametahiriwa, bali kwa sababu wanafuata njia ileile ya imani baba yetu Abrahamu aliyofuata kabla ya kutahiriwa.'),
(2018705,69,45,4,13,'Mungu alimwahidi Abrahamu na wazawa wake kwamba ulimwengu ungekuwa mali yao. Ahadi hiyo haikufanywa kwa sababu Abrahamu aliitii Sheria, bali kwa kuwa aliamini, akakubaliwa kuwa mwadilifu.'),
(2018706,69,45,4,14,'Maana kama watakaopewa hayo aliyoahidi Mungu ni wale tu wanaoitii Sheria, basi, imani haina maana yoyote, nayo ahadi ya Mungu si kitu.'),
(2018707,69,45,4,15,'Sheria husababisha ghadhabu; lakini kama hakuna Sheria, haiwezekani kuivunja.'),
(2018708,69,45,4,16,'Kwa sababu hiyo, jambo hili lategemea imani, hivyo kwamba ahadi hiyo yatokana na neema ya Mungu, na kwamba ni hakika kuwa ahadi hiyo ni kwa ajili ya wote: si kwa wale tu wanaoishika Sheria, bali pia kwa wale waishio kwa imani kama Abrahamu. Yeye ni baba yetu sisi sote.'),
(2018709,69,45,4,17,'Kama Maandiko Matakatifu yasemavyo: "Nimekuweka uwe baba wa mataifa mengi." Ahadi hiyo ni kweli mbele ya Mungu ambaye Abrahamu alimwamini--Mungu ambaye huwapa wafu uzima, na kwa amri yake, vitu ambavyo havikuwapo huwa.'),
(2018710,69,45,4,18,'Abrahamu aliamini na kutumaini ingawa hali yenyewe ilikuwa bila matumaini, na hivyo amekuwa baba wa mataifa mengi kama Maandiko Matakatifu yasemavyo: "Wazao wako watakuwa wengi kama nyota!"'),
(2018711,69,45,4,19,'Alikuwa mzee wa karibu miaka mia moja, lakini imani yake haikufifia ingawa alijua kwamba mwili wake ulikuwa kama umekufa, na pia mkewe, Sara, alikuwa tasa.'),
(2018712,69,45,4,20,'Abrahamu hakuionea mashaka ile ahadi ya Mungu; alipata nguvu kutokana na imani, akamtukuza Mungu.'),
(2018713,69,45,4,21,'Alijua kwamba Mungu anaweza kuyatekeleza yale aliyoahidi.'),
(2018714,69,45,4,22,'Ndiyo maana Mungu alimkubali kuwa mwadilifu.'),
(2018715,69,45,4,23,'Inaposemwa, "Alimkubali," haisemwi kwa ajili yake mwenyewe tu.'),
(2018716,69,45,4,24,'Jambo hili linatuhusu sisi pia ambao tunamwamini Mungu aliyemfufua Yesu, Bwana wetu, kutoka wafu.'),
(2018717,69,45,4,25,'Yeye alitolewa auawe kwa ajili ya dhambi zetu, akafufuka ili tupate kukubaliwa kuwa waadilifu na Mungu.'),
(2018718,69,45,5,1,'Sasa, kwa vile tumekubaliwa kuwa wadilifu kwa imani, basi, tunayo amani na Mungu kwa ajili ya Bwana wetu Yesu Kristo.'),
(2018719,69,45,5,2,'Kwa imani yetu, yeye ametuleta katika hali hii ya neema ya Mungu ambamo sasa tunaishi. Basi, tunajivunia tumaini tulilo nalo la kushiriki utukufu wa Mungu.'),
(2018720,69,45,5,3,'Naam, si hayo tu, bali tunafurahi pia katika taabu tukijua kwamba taabu huleta saburi,'),
(2018721,69,45,5,4,'nayo saburi huleta uthabiti, na uthabiti huleta tumaini.'),
(2018722,69,45,5,5,'Tumaini hilo haliwezi kutuhadaa, maana Mungu amekwisha miminia mioyoni mwetu upendo wake kwa njia ya Roho Mtakatifu aliyetujalia.'),
(2018723,69,45,5,6,'Tulipokuwa bado wanyonge, Kristo, wakati ulipotimia, alikufa kwa ajili yetu sisi waovu.'),
(2018724,69,45,5,7,'Si rahisi mtu kufa kwa ajili ya mtu mwadilifu; labda mtu anaweza kuthubutu kufa kwa ajili ya mtu mwema.'),
(2018725,69,45,5,8,'Lakini Mungu amethibitisha kwamba anatupenda, maana wakati tulipokuwa bado wenye dhambi, Kristo alikufa kwa ajili yetu.'),
(2018726,69,45,5,9,'Kwa kuwa sasa tumekubaliwa kuwa waadilifu kwa damu ya Kristo, ni dhahiri zaidi kwamba atatuokoa katika ghadhabu ya Mungu.'),
(2018727,69,45,5,10,'Maana, tulipokuwa bado adui zake, Mungu alitupatanisha naye kwa kifo cha Mwanae. Na kwa vile sasa tumepatanishwa naye, ni dhahiri zaidi kwamba tutaokolewa kwa uzima wa Kristo.'),
(2018728,69,45,5,11,'Wala si hayo tu, ila tunafurahi pia katika Mungu kwa njia ya Bwana wetu Yesu Kristo ambaye ametupatanisha na Mungu.'),
(2018729,69,45,5,12,'Kwa njia ya mtu mmoja dhambi iliingia ulimwenguni, nayo ikasababisha kifo. Hivyo kifo kimeenea katika jumuiya yote ya binadamu, kwa maana wote wametenda dhambi.'),
(2018730,69,45,5,13,'Kabla ya Sheria kuwako, dhambi ilikuwako ulimwenguni; lakini dhambi haiwekwi katika kumbukumbu bila sheria.'),
(2018731,69,45,5,14,'Lakini tangu wakati wa Adamu mpaka wakati wa Mose, kifo kiliwatawala hata wale ambao hawakutenda dhambi kama ile ya Adamu, ya kumwasi Mungu. Adamu alikuwa kielelezo cha yule ambaye atakuja baadaye.'),
(2018732,69,45,5,15,'Lakini ipo tofauti: neema ya Mungu si kama dhambi ya Adamu. Maana, ingawa dhambi ya mtu mmoja ilisababisha kifo kwa wote, kwa fadhili ya mtu mmoja, yaani Yesu Kristo, Mungu amewazidishia wote neema na zawadi zake.'),
(2018733,69,45,5,16,'Kuna tofauti baina ya zawadi ya Mungu, na dhambi ya mtu yule mmoja. Maana, baada ya kosa la mtu mmoja, Mungu alitoa hukumu; lakini baada ya makosa ya watu wengi, Mungu aliwapa zawadi yake kwa kuwasamehe.'),
(2018734,69,45,5,17,'Kweli, kwa dhambi ya mtu mmoja kifo kilianza kutawala kwa sababu ya huyo mtu mmoja; lakini, ni dhahiri zaidi kwamba alichokifanya yule mtu mmoja, yaani Yesu Kristo, ni bora zaidi. Wote wanaopokea neema na zawadi hiyo ya kukubaliwa kuwa waadilifu, watatawala katika uzima kwa njia ya huyo mmoja, yaani Yesu Kristo.'),
(2018735,69,45,5,18,'Basi, kama vile kosa la mtu mmoja lilivyoleta hukumu kwa binadamu wote, kadhalika kitendo kimoja kiadilifu kinawapa uhuru na uzima.'),
(2018736,69,45,5,19,'Na kama kwa kutotii kwa mtu mmoja watu wengi walifanywa wenye dhambi, kadhalika kutii kwa mtu mmoja kutawafanya wengi wakubaliwe kuwa waadilifu.'),
(2018737,69,45,5,20,'Sheria ilitokea, ikasababisha kuongezeka kwa uhalifu; lakini pale dhambi ilipoongezeka, neema iliongezeka zaidi.'),
(2018738,69,45,5,21,'Kama vile dhambi ilivyotawala kwa kifo, kadhalika neema inatawala kwa njia ya uadilifu, na kuleta uzima wa milele kwa njia ya Yesu Kristo Bwana wetu.'),
(2018739,69,45,6,1,'Tuseme nini basi? Je, twendelee kubaki katika dhambi ili neema ya Mungu iongezeke?'),
(2018740,69,45,6,2,'Hata kidogo! Kuhusu dhambi sisi tumekufa--tutaendeleaje kuishi tena katika dhambi?'),
(2018741,69,45,6,3,'Maana, mnajua kwamba sisi tuliobatizwa tukaungana na Kristo Yesu, tulibatizwa na kuungana na kifo chake.'),
(2018742,69,45,6,4,'Tulipobatizwa tuliungana na kifo chake, tukazikwa pamoja naye, ili kama vile Kristo alivyofufuliwa kutoka wafu kwa kitendo kitukufu cha Baba, sisi pia tuweze kuishi maisha mapya.'),
(2018743,69,45,6,5,'Maana, kama sisi tumeungana naye katika kufa kama yeye, vivyo hivyo tutaungana naye kwa kufufuliwa kutoka wafu kama yeye.'),
(2018744,69,45,6,6,'Tunajua kwamba utu wetu wa kale ulisulubiwa pamoja na Kristo, ili hali ya dhambi iharibiwe, tusiwe tena watumwa wa dhambi.'),
(2018745,69,45,6,7,'Kwa maana, mtu aliyekufa, amenasuliwa kutoka katika nguvu ya dhambi.'),
(2018746,69,45,6,8,'Basi, ikiwa tumekufa pamoja na Kristo, tunaamini kwamba tutaishi pia pamoja naye.'),
(2018747,69,45,6,9,'Maana, tunajua kwamba Kristo amekwisha fufuliwa kutoka wafu na hafi tena; kifo hakimtawali tena.'),
(2018748,69,45,6,10,'Hivyo, kwa kuwa alikufa--mara moja tu--dhambi haina nguvu tena juu yake; na sasa anaishi maisha yake katika umoja na Mungu.'),
(2018749,69,45,6,11,'Hali kadhalika nanyi lazima mjione kuwa mmekufa kuhusu dhambi, lakini kama mnaoishi katika umoja na Mungu kwa njia ya Kristo Yesu.'),
(2018750,69,45,6,12,'Kwa hiyo, dhambi isiitawale tena miili yenu ambayo hufa, na hivyo kuzitii tamaa zake.'),
(2018751,69,45,6,13,'Wala msitoe hata sehemu moja ya miili yenu iwe chombo cha kutenda uovu na dhambi. Badala yake, jitoleeni ninyi wenyewe kwa Mungu kama watu waliofufuliwa kutoka wafu; toeni nafsi zenu zote kwa Mungu kwa ajili ya uadilifu.'),
(2018752,69,45,6,14,'Maana, dhambi haitawatawala ninyi tena, kwani hamko chini ya Sheria, bali chini ya neema.'),
(2018753,69,45,6,15,'Basi, tuseme nini? Je, tutende dhambi ati kwa sababu hatuko chini ya Sheria bali chini ya neema? Hata kidogo!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018754,69,45,6,16,'Mnajua kwamba mkijitolea ninyi wenyewe kama watumwa na kumtii fulani, mnakuwa kweli watumwa wake mtu huyo--au watumwa wa dhambi, na matokeo yake ni kifo, au wa utii, na matokeo yake ni kukubaliwa kuwa waadilifu.'),
(2018755,69,45,6,17,'Ingawa mlikuwa watumwa wa dhambi zamani, sasa lakini--namshukuru Mungu--mmetii kwa moyo wote yale maazimio na mafundisho mliyopokea.'),
(2018756,69,45,6,18,'Mlikombolewa kutoka utumwa wa dhambi, mkawa watumwa wa uadilifu.'),
(2018757,69,45,6,19,'(Hapa natumia lugha ya kawaida ya watu kwa sababu ya udhaifu wenu wenyewe.) Kama vile wakati fulani mlivyojitolea ninyi wenyewe kutumikia uchafu na uhalifu kwa ajili ya uovu, vivyo hivyo sasa jitoleeni nafsi zenu wenyewe kutumikia uadilifu kwa ajili ya utakatifu.'),
(2018758,69,45,6,20,'Mlipokuwa watumwa wa dhambi, mlikuwa huru mbali na uadilifu.'),
(2018759,69,45,6,21,'Sasa, mlipata faida gani siku zile kutokana na mambo yale ambayo mnayaonea aibu sasa? Maana, matokeo ya mambo haya ni kifo!'),
(2018760,69,45,6,22,'Lakini sasa, mmekwisha kombolewa kutoka utumwa wa dhambi na mmekuwa watumishi wa Mungu; faida mliyo nayo sasa ni utakatifu, na matokeo yake ni uzima wa milele.'),
(2018761,69,45,6,23,'Kwa maana mshahara wa dhambi ni kifo; lakini zawadi anayotoa Mungu ni uzima wa milele katika kuungana na Kristo Yesu, Bwana wetu.'),
(2018762,69,45,7,1,'Ndugu zangu, bila shaka mtaelewa yafuatayo, maana ninawazungumzia watu wanaojua Sheria. Sheria humtawala mtu wakati akiwa hai.'),
(2018763,69,45,7,2,'Mathalan: mwanamke aliyeolewa anafungwa na sheria muda wote mumewe anapokuw hai; lakini mumewe akifa, hiyo sheria haimtawali tena huyo mwanamke.'),
(2018764,69,45,7,3,'Hivyo mwanamke huyo akiishi na mwanamume mwingine wakati mumewe yungali hai, ataitwa mzinzi; lakini mumewe akifa, mwanamke huyo yu huru kisheria, na akiolewa na mwanamume mwingine, yeye si mzinzi.'),
(2018765,69,45,7,4,'Hali kadhalika ninyi ndugu zangu: ninyi pia mmekufa kuhusu Sheria kwa kuwa ninyi ni sehemu ya mwili wa Kristo; sasa mmekuwa wake yeye aliyefufuliwa kutoka wafu ili tupate kuzaa matunda mema kwa ajili ya Mungu.'),
(2018766,69,45,7,5,'Maana, tulipokuwa tukiishi kimaumbile tu, tamaa mbaya zikichochewa na Sheria, zilifanya kazi katika miili yetu, na kuchuma pato la kifo.'),
(2018767,69,45,7,6,'Lakini sasa tumekuwa huru kutoka vifungo vya Sheria, kwa sababu tumekufa kuhusu lile jambo lililotufanya sisi watumwa. Sasa tunatumikia kufuatana na maisha mapya ya Roho, na si kufuatana na hali ile ya kale ya Sheria iliyoandikwa.'),
(2018768,69,45,7,7,'Je, tuseme basi, kwamba Sheria ni dhambi? Hata kidogo! Lakini bila Sheria, mimi nisingalijua dhambi ni kitu gani. Maana, nisingalijua ni nini hasa kutamani mabaya, kama Sheria isingalikuwa imesema: "Usitamani."'),
(2018769,69,45,7,8,'Kwa kuitumia hiyo amri, dhambi ilipata fursa ya kuamsha kila aina ya tamaa mbaya ndani yangu. Maana, bila Sheria dhambi ni kitu kilichokufa.'),
(2018770,69,45,7,9,'Wakati mmoja mimi nilikuwa hai mbali na Sheria; lakini amri ilipokuja, dhambi ilifufuka,'),
(2018771,69,45,7,10,'nami nikafa. Hiyo amri ambayo shabaha yake ilikuwa kuleta uhai, kwangu imeleta kifo.'),
(2018772,69,45,7,11,'Maana, dhambi ilichukua fursa iliyopatiwa na amri hiyo, ikanidanganya na kuniua.'),
(2018773,69,45,7,12,'Basi, Sheria yenyewe ni takatifu, na amri yenyewe ni takatifu, ni ya haki na nzuri.'),
(2018774,69,45,7,13,'Je, hii inamaanisha kwamba kile kilicho kizuri kimesababisha kifo changu? Hata kidogo! Iliyo ni kwamba, dhambi, ili ionekane dhahiri kuwa ni dhambi, imekitumia kile kilicho kizuri na kusababisha kifo changu. Hivyo dhambi, kwa njia ya ile amri, ilijionyesha kikamilifu jinsi ilivyo mbaya mno.'),
(2018775,69,45,7,14,'Tunajua kwamba Sheria ni ya kiroho, lakini mimi ni wa kidunia, mimi nimeuzwa kuwa mtumwa wa dhambi.'),
(2018776,69,45,7,15,'Sielewi nifanyacho, maana kile ninachotaka sikifanyi, bali kile ninachochukia ndicho nikifanyacho.'),
(2018777,69,45,7,16,'Ikiwa basi, ninatenda kinyume cha matakwa yangu, hii inamaanisha kwamba nakubali kuwa ile Sheria ni nzuri.'),
(2018778,69,45,7,17,'Basi, si mimi hasa ninayefanya kitu hicho, bali ile dhambi iliyo ndani yangu.'),
(2018779,69,45,7,18,'Najua kwamba hamna jema lolote ndani yangu mimi, kadiri ya ubinadamu wangu. Kwa maana, ingawa nataka kufanya jambo jema, siwezi kulitekeleza.'),
(2018780,69,45,7,19,'Yaani, badala ya kufanya lile jambo jema ninalotaka, nafanya lile baya nisilotaka.'),
(2018781,69,45,7,20,'Basi, kama ninafanya kinyume cha matakwa yangu, hii inamaanisha kwamba si mimi ninayefanya hayo, bali ni ile dhambi iliyo ndani yangu.'),
(2018782,69,45,7,21,'Basi, nimegundua kanuni hii: ninataka kufanya jema, lakini najikuta kwamba lile lililo baya ndilo ninalochagua.'),
(2018783,69,45,7,22,'Ndani kabisa katika moyo wangu naifurahia sheria ya Mungu.'),
(2018784,69,45,7,23,'Lakini naona kwamba kuna sheria nyingine inayofanya kazi mwilini mwangu, sheria ambayo inapingana na ile inayokubaliwa na akili yangu. Hiyo inanifanya niwe mtumwa wa sheria ya dhambi ifanyayo kazi mwilini mwangu.'),
(2018785,69,45,7,24,'Maskini miye! Nani atakayeniokoa kutoka katika mwili huu unaonipeleka kifoni?'),
(2018786,69,45,7,25,'Shukrani kwa Mungu afanyaye hayo kwa njia ya Bwana wetu Yesu Kristo! Hii basi, ndiyo hali yangu: mimi binafsi, kwa akili yangu, ninaitumikia sheria ya dhambi.'),
(2018787,69,45,8,1,'Kwa hiyo, sasa hakuna hukumu kwa wale ambao katika maisha yao wameungana na Kristo.'),
(2018788,69,45,8,2,'Maana, sheria ya Roho iletayo uzima kwa kuungana na Kristo Yesu imenikomboa kutoka katika sheria ya dhambi na kifo.'),
(2018789,69,45,8,3,'Mungu ametekeleza jambo lile ambalo Sheria haikuweza kutekeleza kwa sababu ya udhaifu w binadamu. Mungu alimtuma Mwanae akiwa mwenye mwili sawa na miili yetu sisi wenye dhambi, ili aikabili dhambi, na kwa mwili huo akaiangamiza dhambi.'),
(2018790,69,45,8,4,'Mungu alifanya hivyo kusudi matakwa ya haki ya Sheria yatekelezwe kikamilifu ndani yetu sisi ambao tunaishi, si kwa nguvu za kibinadamu, bali kwa nguvu ya Roho.'),
(2018791,69,45,8,5,'Maana, wale wanaoishi kufuatana na matakwa ya mwili, hutawaliwa na fikira za mwili. Lakini wale wanaoishi kufuatana na matakwa ya Roho Mtakatifu, hutawaliwa na fikira za Roho.'),
(2018792,69,45,8,6,'Fikira za mwili huleta kifo; fikira za Roho huleta uzima na amani.'),
(2018793,69,45,8,7,'Maana, mwenye kutawaliwa na fikira za mwili ni adui wa Mungu; haitii sheria ya Mungu, wala hawezi kuitii.'),
(2018794,69,45,8,8,'Watu wanaotii matakwa ya mwili hawawezi kumpendeza Mungu.'),
(2018795,69,45,8,9,'Lakini ninyi hamuishi kufuatana na matakwa ya mwili, bali kufuatana na matakwa ya Roho, ikiwa Roho wa Mungu anaishi ndani yenu. Yeyote asiye na Roho wa Kristo, huyo si wake Kristo.'),
(2018796,69,45,8,10,'Lakini kama Kristo yumo ndani yenu, ingawa miili yenu itakufa kwa sababu ya dhambi, kwenu Roho ndiye uhai kwa sababu mmekubaliwa kuwa waadilifu.'),
(2018797,69,45,8,11,'Ikiwa Roho wa Mungu aliyemfufua Kristo kutoka wafu anaishi ndani yenu, basi huyo aliyemfufua Kristo kutoka wafu ataipa uzima miili yenu yenye hali ya kufa; atafanya hivyo kwa njia ya Roho wake akaaye ndani yenu.'),
(2018798,69,45,8,12,'Hivyo basi, ndugu zangu, tunalo jukumu, lakini si la kuishi kufuatana na maumbile ya kibinadamu.'),
(2018799,69,45,8,13,'Kwa maana, kama mkiishi kufuatana na matakwa ya maumbile ya kibinadamu, hakika mtakufa. Lakini, kama kwa njia ya Roho mnayaua matendo yenu maovu, basi, mtaishi.'),
(2018800,69,45,8,14,'Wote wanaoongozwa na Roho wa MUngu ni watoto wa Mungu.'),
(2018801,69,45,8,15,'Kwa maana, Roho mliyempokea si Roho mwenye kuwafanya ninyi watumwa na kuwatia tena hofu; sivyo, bali mmempokea Roho mwenye kuwafanya ninyi watoto wa Mungu, na kwa nguvu ya huyo Roho, sisi tunaweza kumwita Mungu, "Aba," yaani "Baba!"'),
(2018802,69,45,8,16,'Naye Roho mwenyewe anajiunga na roho zetu na kuthibitisha kwamba sisi ni watoto wa Mungu.'),
(2018803,69,45,8,17,'Basi, kwa vile sisi ni watoto wa Mungu, tutapokea baraka zote Mungu alizowawekea watu wake, na tutashiriki urithi huo pamoja na Kristo; maana, tukiyashiriki mateso yake Kristo, tutaushiriki pia utukufu wake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018804,69,45,8,18,'Naona kuwa mateso ya wakati huu wa sasa si kitu kamwe kama tukiyafananisha na ule utukufu utakaodhihirishwa kwetu.'),
(2018805,69,45,8,19,'Viumbe vyote vinatazamia kwa hamu Mungu awadhihirishe watoto wake.'),
(2018806,69,45,8,20,'Kwa maana, viumbe viliwekwa katika hali ya kutojiweza kabisa, si kwa hiari yao, ila vilifanywa hivyo kwa mapenzi ya Mungu. Hata hivyo yapo matumaini,'),
(2018807,69,45,8,21,'maana hivyo viumbe navyo vitaokolewa kutoka katika utumwa wa uharibifu, vishiriki uhuru mtukufu wa watoto wa Mungu.'),
(2018808,69,45,8,22,'Kwa maana tunajua kwamba mpaka hivi sasa, viumbe vyote vinalia kwa maumivu kama ya kujifungua mtoto.'),
(2018809,69,45,8,23,'Wala si hivyo viumbe peke yake, bali hata sisi tulio na huyo Roho, aliye wa kwanza wa zawadi za Mungu; sisi pia tunalalamika ndani yetu, tukitazamia kufanywa watoto wa Mungu, nazo nafsi zenu zikombolewe.'),
(2018810,69,45,8,24,'Maana kwa matumaini hayo sisi tumekombolewa; lakini tumaini halina maana ikiwa tunakiona kile tunachotumainia. Maana ni nani anayetumaini kile ambacho tayari anakiona?'),
(2018811,69,45,8,25,'Kama tunakitumaini kile ambacho hatujakiona bado, basi, tunakingojea kwa uvumilivu.'),
(2018812,69,45,8,26,'Hali kadhalika, naye Roho anatusaidia katika udhaifu wetu. Maana hatujui inavyotupasa kuomba; lakini Roho mwenyewe anatuombea kwa Mungu kwa mlio wa huzuni usioelezeka.'),
(2018813,69,45,8,27,'Naye Mungu aonaye mpaka ndani ya mioyo ya watu, anajua fikira ya huyo Roho; kwani huyo Roho huwaombea watu wa Mungu kufuatana na mapenzi ya Mungu.'),
(2018814,69,45,8,28,'Tunajua kwamba, katika mambo yote, Mungu hufanya kazi na kuifanikisha pamoja na wote wampendao, yaani wale aliowaita kufuatana na kusudi lake.'),
(2018815,69,45,8,29,'Maana hao aliowachagua tangu mwanzo, ndio aliowateua wapate kufanana na Mwanae, ili Mwana awe wa kwanza miongoni mwa ndugu wengi.'),
(2018816,69,45,8,30,'Basi, Mungu aliwaita wale aliokuwa amewateua; na hao aliowaita aliwakubali kuwa waadilifu; na hao aliowakubali kuwa waadilifu aliwashirikisha pia utukufu wake.'),
(2018817,69,45,8,31,'Kutokana na hayo, tuseme nini zaidi? Ikiwa Mungu yuko upande wetu, nani awezaye kutupinga?'),
(2018818,69,45,8,32,'Mungu hakumhurumia hata mwanae wa pekee, bali alimtoa kwa ajili yetu sisi sote. Ikiwa amefanya hivyo, je, hatatujalia pia mema yote?'),
(2018819,69,45,8,33,'Ni nani atakayewashtaki wateule wa Mungu? Mungu mwenyewe huwaondolea hatia!'),
(2018820,69,45,8,34,'Ni nani atakayewahukumu? Hakuna! Maana Kristo ndiye aliyekufa, tena alifufuka kutoka wafu na anakaa upande wa kulia wa Mungu. Yeye anatuombea!'),
(2018821,69,45,8,35,'Ni nani awezaye kututenga na mapendo ya Kristo? Je, ni taabu, au dhiki, au mateso, au njaa, au ukosefu wa nguo, au hatari, au kuuawa?'),
(2018822,69,45,8,36,'Kama Maandiko Matakatifu yasemavyo: "Kwa ajili yako, twakikabili kifo kutwa kucha: tunatendewa kama kondoo wa kuchinjwa."'),
(2018823,69,45,8,37,'Lakini, katika mambo haya yote, tumepata ushindi mkubwa kwa msaada wake yeye aliyetupenda.'),
(2018824,69,45,8,38,'Maana ninajua hakika kwamba hakuna kitu kiwezacho kututenganisha na upendo wake: wala kifo, wala uhai; wala malaika, au nguvu nyingine za mbinguni; wala yanayotokea sasa, wala yatakayotokea baadaye; wala mamlaka;'),
(2018825,69,45,8,39,'Wala ulimwengu wa juu, wala wa chini kabisa. Hakuna kiumbe chochote kitakachoweza kututenga na upendo wa Mungu kwetu kwa njia ya Kristo Yesu Bwana wetu.'),
(2018826,69,45,9,1,'Nasema ukweli mtupu; nimeungana na Kristo nami sisemi uongo. Dhamiri yangu ikiongozwa na Roho Mtakatifu inanithibitishia jambo hili pia.'),
(2018827,69,45,9,2,'Nataka kusema hivi: nina huzuni kubwa na maumivu yasiyopimika moyoni mwangu'),
(2018828,69,45,9,3,'kwa ajili ya watu wangu, walio damu moja nami! Kama ingekuwa kwa faida yao, ningekuwa radhi kulaaniwa na kutengwa na Kristo.'),
(2018829,69,45,9,4,'Hao ndio watu wa Israeli ambao Mungu aliwateua wawe watoto wake, akawashirikisha utukufu wake; aliagana nao, akawapa Sheria yake, imani ya kweli na ahadi zake.'),
(2018830,69,45,9,5,'Wao ni wajukuu wa mababu, naye Kristo, kadiri ya ubinadamu wake, ametoka katika ukoo wao. Mungu atawalaye juu ya yote, na atukuzwe milele! Amina.'),
(2018831,69,45,9,6,'Sisemi kwamba ahadi ya Mungu imebatilika; maana si watu wote wa Israeli ni wateule wa Mungu.'),
(2018832,69,45,9,7,'Wala, si wazawa wote wa Abrahamu ni watoto wake wa kweli. Ila, kama yasemavyo Maandiko Matakatifu: "Wazao wake watatokana na Isaka."'),
(2018833,69,45,9,8,'Nido kusema, wale waliozaliwa kimaumbile ndio watoto wa Mungu, bali wale waliozaliwa kutokana na ahadi ya Mungu ndio watakaoitwa watoto wake.'),
(2018834,69,45,9,9,'Maana ahadi yenyewe ni hii: "Nitakujia wakati maalum, naye Sara atapata mtoto."'),
(2018835,69,45,9,10,'Tena si hayo tu ila pia Rebeka naye alipata mapacha kwa baba mmoja, yaani Isaka, babu yetu.'),
(2018836,69,45,9,11,'Lakini, ili Mungu aonekane kwamba anao uhuru wa kuchagua, hata kabla wale ndugu hawajazaliwa na kabla hawajaweza kupambanua jema na baya,'),
(2018837,69,45,9,12,'Rebeka aliambiwa kwamba yule mtoto wa kwanza atamtumikia yule wa nyuma. Hivyo uchaguzi wa Mungu unategemea jinsi anavyoita mwenyewe, na si matendo ya binadamu.'),
(2018838,69,45,9,13,'Kama Maandiko Matakatifu yasemavyo: "Yakobo nilimpenda, lakini Esau nilimchukia."'),
(2018839,69,45,9,14,'Basi, tuseme nini? Je, Mungu amekosa haki? Hata kidogo!'),
(2018840,69,45,9,15,'Maana alimwambia Mose: "Nitamhurumia mtu yeyote ninayetaka kumhurumia; nitamwonea huruma mtu yeyote ninayetaka."'),
(2018841,69,45,9,16,'Kwa hiyo, yote hutegemea huruma ya Mungu, na si bidii au mapenzi ya mtu.'),
(2018842,69,45,9,17,'Maana Maandiko Matakatifu yasema hivi kwa Farao: "Nilikufanya mfalme ili kwa njia yako, uwezo wangu ujulikane, na jina langu litangazwe popote duniani."'),
(2018843,69,45,9,18,'Ni wazi,basi, kwamba Mungu humhurumia yeyote anayetaka kumhurumia, na akipenda kumfanya mtu awe mkaidi, hufanya hivyo.'),
(2018844,69,45,9,19,'Labda utaniuliza: "Ikiwa mambo yako hivyo, Mungu anawezaje kumlaumu mtu? Nani awezaye kuyapinga mapenzi yake?"'),
(2018845,69,45,9,20,'Lakini, ewe binadamu, u nani hata uthubutu kumhoji Mungu? Je, chungu chaweza kumwuliza mfinyanzi wake: "Kwa nini umenitengeneza namna hii?"'),
(2018846,69,45,9,21,'Mfinyanzi anaweza kuutumia udongo apendavyo na kufinyanga vyungu viwili kwa udongo uleule; kimoja kwa matumizi ya heshima, na kingine kwa matumizi ya kawaida.'),
(2018847,69,45,9,22,'Hivyo ndivyo ilivyo kwa Mungu. Alitaka kuonyesha ghadhabu yake na kujulisha uwezo wake, Basi, alikuwa na saburi sana, akiwavumilia wale ambao walikuwa lengo la ghadhabu yake, ambao walistahili kuangamizwa.'),
(2018848,69,45,9,23,'Alitaka pia kudhihirisha wingi wa utukufu wake ambao alitumiminia sisi tulio lengo la huruma yake; sisi ambao alikwisha kututayarisha kuupokea utukufu wake.'),
(2018849,69,45,9,24,'Maana sisi ndio hao aliowaita, si tu kutoka miongoni mwa Wayahudi bali pia kutoka kwa watu wa mataifa mengine.'),
(2018850,69,45,9,25,'Maana ndivyo asemavyo katika kitabu cha Hosea: "Wale waliokuwa `Si watu wangu` nitawaita: `Watu wangu!` Naye `Sikupendi` ataitwa: `Mpenzi wangu!`'),
(2018851,69,45,9,26,'Na pale walipoambiwa: `Ninyi si wangu` hapo wataitwa: `Watoto wa Mungu hai."`'),
(2018852,69,45,9,27,'Naye nabii Isaya, kuhusu Israeli anapaaza sauti: "Hata kama watoto wa Israeli ni wengi kama mchanga wa pwani, ni wachache tu watakaookolewa;'),
(2018853,69,45,9,28,'maana, Bwana ataitekeleza upesi hukumu yake kamili juu ya ulimwengu wote."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018854,69,45,9,29,'Ni kama Isaya alivyosema hapo awali: "Kama Bwana Mwenye Nguvu asingalituachia baadhi ya watoto wa Israeli, tungalikwisha kuwa kama Sodoma, tungalikwisha kuwa ma Gomora."'),
(2018855,69,45,9,30,'Basi, tuseme nini? Ni hivi: watu wa mataifa ambao hawakutafuta kukubaliwa kuwa waadilifu, wamekubaliwa kuwa waadilifu kwa njia ya imani,'),
(2018856,69,45,9,31,'hali watu wa Israeli waliokuwa wakitafuta Sheria iletayo kukubaliwa kuwa waadilifu, hawakuipata.'),
(2018857,69,45,9,32,'Kwa nini? Kwa sababu walitegemea matendo yao badala ya kutegemea imani. Walijikwaa juu ya jiwe la kujikwaa'),
(2018858,69,45,9,33,'kama yesemavyo Maandiko Matakatifu: "Tazama! Naweka huko Sioni jiwe likwazalo, mwamba utakaowafanya watu waanguke. Mtu atakayemwamini yeye aliye hilo jiwe, hataaibishwa!"'),
(2018859,69,45,10,1,'Ndugu zangu, ninataka na kutazamia kwa moyo wangu wote hao wananchi wenzangu wakombolewe. Tena nawaombea kwa Mungu daima.'),
(2018860,69,45,10,2,'Maana naweza kuthibitisha kwa niaba yao kwamba wanayo bidii ya kumtafuta Mungu; lakini bidii hiyo haikujengwa juu ya ujuzi wa kweli.'),
(2018861,69,45,10,3,'Maana hawakufahamu jinsi Mungu anavyowafanya watu wawe waadilifu, na wamejaribu kuanzisha mtindo wao wenyewe, na hivyo hawakuikubali njia hiyo ya Mungu ya kuwafanya wawe waadilifu.'),
(2018862,69,45,10,4,'Maana kwa kuja kwake Kristo, Sheria imefikia kikomo chake, ili kila mtu anayeamini akubaliwe kuwa mwadilifu.'),
(2018863,69,45,10,5,'Kuhusu kukubaliwa kuwa mwadilifu kwa kuitii Sheria, Mose aliandika hivi: "Mtu yeyote anayetimiza matakwa ya Sheria ataishi."'),
(2018864,69,45,10,6,'Lakini, kuhusu kukubaliwa kuwa mwadilifu kwa njia ya imani, yasemwa hivi: "Usiseme moyoni mwako: `Nani atapanda mpaka mbinguni?` (yaani, kumleta Kristo chini);'),
(2018865,69,45,10,7,'wala usiseme: `Nani atashuka mpaka Kuzimu` (yaani, kumleta Kristo kutoka kwa wafu)."'),
(2018866,69,45,10,8,'Maandiko Matakatifu yesema hivi, "Ujumbe huo wa Mungu uko karibu nawe, uko kinywani mwako na moyoni mwako" nao ndio ile imani tunayoihubiri.'),
(2018867,69,45,10,9,'Kama ukikiri kwa kinywa chako kwamba Yesu ni Bwana na kuamini moyoni mwako kwamba Mungu alimfufua kutoka wafu, utaokoka.'),
(2018868,69,45,10,10,'Maana tunaamini kwa moyo na kukubaliwa kuwa waadilifu; na tunakiri kwa midomo yetu na kuokolewa.'),
(2018869,69,45,10,11,'Maandiko Matakatifu yasema: "Kila amwaminiye hatakuwa na sababu ya kuaibika."'),
(2018870,69,45,10,12,'Jambo hili ni kwa wote, kwani hakuna tofauti kati ya Wayahudi na wasio Wayahudi; Bwana wa wote ni mmoja, naye ni mkarimu sana kwao wote wamwombao.'),
(2018871,69,45,10,13,'Maana Maandiko Matakatifu yasema: "Kila mtu atakayeomba kwa jina la Bwana, ataokolewa."'),
(2018872,69,45,10,14,'Basi, watamwombaje yeye ambaye hawamwamini? Tena, watamwaminije kama hawajapata kusikia habari zake? Na watasikiaje habari zake kama hakuna mhubiri?'),
(2018873,69,45,10,15,'Na watu watahubirije kama hawakutumwa? Kama yasemavyo Maandiko Matakatifu: "Ni jambo la kupendeza mno kuja kwa wale wanaohubiri Habari Njema!"'),
(2018874,69,45,10,16,'Lakini wote hawakuipokea hiyo Habari Njema. Maana Isaya alisema: "Bwana, ni nani aliyeamini ujumbe wetu?"'),
(2018875,69,45,10,17,'Hivyo basi, imani inatokana na kuusikiliza ujumbe, na huo ujumbe unatokana na neno la Kristo.'),
(2018876,69,45,10,18,'Lakini nauliza: je, hawakuusikia huo ujumbe? Naam, waliusikia; kama Maandiko Matakatifu yasemavyo: "Sauti yao imeenea duniani kote; maneno yao yamefika mpaka kingo za ulimwengu."'),
(2018877,69,45,10,19,'Tena nauliza: je, yawezekana kwamba watu wa Israeli hawakufahamu? Mose mwenyewe ni kwa kwanza kujibu: "Nitawafanyeni mwaonee wivu watu ambao si taifa; nitawafanyeni muwe na hasira juu ya taifa la watu wapumbavu."'),
(2018878,69,45,10,20,'Tena Isaya anathubutu hata kusema: "Wale ambao hawakunitafuta wamenipata; nimejionyesha kwao wasiouliza habari zangu."'),
(2018879,69,45,10,21,'Lakini kuhusu Israeli anasema: "Mchana kutwa niliwanyoshea mikono yangu watu waasi na wasiotii."'),
(2018880,69,45,11,1,'Basi, nauliza: je, Mungu amewakataa watu wake? Hata kidogo! Mini binafsi ni Mwisraeli mzawa wa Abrahamu, wa kabila la Benyamini.'),
(2018881,69,45,11,2,'Mungu hakuwakataa watu wake aliowateua tangu mwanzo. Mnakumbuka yasemavyo Maandiko Matakatifu juu ya Eliya wakati alipomnung`unikia Mungu kuhusu Israeli:'),
(2018882,69,45,11,3,'"Bwana, wamewaua manabii wako na kubomoa madhabahu yako. Ni mimi tu peke yangu niliyebaki, nao wanataka kuniua?"'),
(2018883,69,45,11,4,'Je, Mungu alimjibu nini? Alimwambia: "Nimejiwekea elfu saba ambao hawakumwabudu Baali."'),
(2018884,69,45,11,5,'Basi, ndivyo ilivyo pia wakati huu wa sasa: ipo idadi ya waliobaki ambao Mungu aliwateua kwa sababu ya neema yake.'),
(2018885,69,45,11,6,'Uteuzi wake unatokana na neema yake, na si kwa sababu ya matendo yao. Maana, kama uteuzi wake ungetegemea matendo ya watu, neema yake haingekuwa neema tena.'),
(2018886,69,45,11,7,'Sasa, je? Watu wa Israeli hawakukipata kile walichokuwa wanakitafuta; lakini wote walioteuliwa walikipata. Wengine walipumbazwa,'),
(2018887,69,45,11,8,'kama yasemavyo Maandiko Matakatifu: "Mungu ameifanya mioyo yao kuwa mizito, na mpaka leo hii hawawezi kuona kwa macho yao wala kusikia kwa masikio yao."'),
(2018888,69,45,11,9,'Naye Daudi anasema: "Karamu zao na ziwe mtego wa kuwanasa, waanguke na kuadhibiwa.'),
(2018889,69,45,11,10,'Macho yao yatiwe giza wasiweze kuona. Migongo yao ipindike kwa taabu daima!"'),
(2018890,69,45,11,11,'Basi, nauliza: je, Wayahudi wamejikwaa hata wakaangamia kabisa? Hata kidogo! Kutokana na kosa lao ukombozi umewajia watu wa mataifa mengine, ili Wayahudi wapate kuwaonea wivu.'),
(2018891,69,45,11,12,'Kosa la Wayahudi limesababisha baraka nyingi kwa ulimwengu, na utovu wao kwa kiroho umeleta baraka nyingi kwa watu wa mataifa mengine. Basi, ni dhahiri zaidi kwamba utimilifu wao utasababisha baraka nyingi zaidi.'),
(2018892,69,45,11,13,'Basi, sasa nawaambieni ninyi watu wa mataifa mengine: Maadamu mimi nimekuwa mtume kwa watu wa mataifa mengine, ninajivunia huduma yangu,'),
(2018893,69,45,11,14,'nipate kuwafanya wananchi wenzangu wawaonee ninyi wivu, na hivyo nipate kuwaokoa baadhi yao.'),
(2018894,69,45,11,15,'Maana ikiwa kukataliwa kwao kulisababisha ulimwengu upatanishwe na Mungu, itakuwaje wakati watakapokubaliwa na Mungu? Wafu watafufuka!'),
(2018895,69,45,11,16,'Ikiwa kipande cha kwanza cha mkate kimewekwa wakfu, mkate wote umewekwa wakfu; mizizi ya mti ikiwa mizuri, na matawi yake huwa mazuri pia.'),
(2018896,69,45,11,17,'Naam, baadhi ya matawi ya mzeituni bustanini yalikatwa, na mahali pake tawi la mzeituni mwitu likapandikizwa. Ninyi watu wa mataifa mengine ndio hilo tawi la mzeituni mwitu; na sasa mnashiriki nguvu na utomvu wa mzeituni bustanini.'),
(2018897,69,45,11,18,'Basi, msiwadharau wale waliokatwa kama matawi! Na, hata kama kuna la kujivunia, kumbukeni kwamba si ninyi mnaoitegemeza mizizi, bali mizizi ndiyo inayowategemeza ninyi.'),
(2018898,69,45,11,19,'Lakini utasema: "Matawi yalikatwa kusudi mimi nipandikizwe mahali pake."'),
(2018899,69,45,11,20,'Sawa! Yalikatwa kwa sababu ya kukosa imani, bali wewe unasimama kwa imani yako. Lakini usijivune; ila uwe na tahadhari.'),
(2018900,69,45,11,21,'Kwa maana, ikiwa Mungu hakuwahurumia Wayahudi ambao ni kama matawi ya asili, je, unadhani atakuhurumia wewe?'),
(2018901,69,45,11,22,'Kumbuka, basi, jinsi Mungu alivyo mwema na mkali. Yeye ni mkali kwa wale walioanguka, na ni mwema kwako wewe ikiwa utaendelea katika wema wake; la sivyo, nawe pia utakatwa.'),
(2018902,69,45,11,23,'Nao Wayahudi, hali kadhalika; wakiacha utovu wao wa imani, watapandikizwa tena. Maana Mungu anao uwezo wa kuwapandikiza tena.'),
(2018903,69,45,11,24,'Ninyi watu wa mataifa mengine, kwa asili ni kama tawi la mzeituni mwitu, lakini mmeondolewa huko, mkapandikizwa katika mzeituni bustanini mahali ambapo kwa asili si penu. Lakini, Wayahudi kwa asili ni kama mzeituni bustanini, na itakuwa jambo rahisi zaidi kwao kupandikizwa tena katika mti huohuo wao.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018904,69,45,11,25,'Ndugu zangu, napenda mjue ukweli huu uliofichika msije mkajiona wenye akili sana. Ukaidi wa Wayahudi ulikuwa ni wa muda tu, mpaka watu wa mataifa mengine watakapokuwa wamemfikia Mungu.'),
(2018905,69,45,11,26,'Hapo ndipo taifa lote la Israeli litakapookolewa, kama yesemavyo Maandiko Matakatifu: "Mkombozi atakuja kutoka Sioni, atauondoa uovu wa Yakobo.'),
(2018906,69,45,11,27,'Hili ndilo agano nitakalofanya nao wakati nitakapoziondoa dhambi zao."'),
(2018907,69,45,11,28,'Kwa sababu wanaikataa Habari Njema, Wayahudi wamekuwa adui wa Mungu, lakini kwa faida yenu nyinyi watu wa mataifa. Lakini, kwa kuwa waliteuliwa, bado ni rafiki wa Mungu kwa sababu ya baba zao.'),
(2018908,69,45,11,29,'Maana Mungu akisha wapa watu zawadi zake na kuwateua, hajuti kwamba amefanya hivyo.'),
(2018909,69,45,11,30,'Hapo awali ninyi mlikuwa mmemwasi Mungu, lakini sasa mmepata huruma yake kutokana na kuasi kwao.'),
(2018910,69,45,11,31,'Hali kadhalika, kutokana na huruma mliyojaliwa ninyi, Wayahudi wanamwasi Mungu sasa ili nao pia wapokee sasa huruma ya Mungu.'),
(2018911,69,45,11,32,'Maana Mungu amewafunga watu wote katika uasi wao ili wapate kuwahurumia wote.'),
(2018912,69,45,11,33,'Utajiri, hekima na elimu ya Mungu ni kuu mno! Huruma zake hazichunguziki, na njia zake hazieleweki! Kama yasemavyo Maandiko Matakatifu:'),
(2018913,69,45,11,34,'"Nani aliyepata kuyajua mawazo ya Bwana? Nani awezaye kuwa mshauri wake?'),
(2018914,69,45,11,35,'Au, nani aliyempa yeye kitu kwanza hata aweze kulipwa tena kitu hicho?"'),
(2018915,69,45,11,36,'Kwa maana vitu vyote vyatoka kwake, vyote vipo kwa uwezo wake na kwa ajili yake. Utukufu na uwe kwake hata milele! Amina.'),
(2018916,69,45,12,1,'Kwa hiyo, ndugu zangu, maadam Mungu ni mwenye huruma nyingi, nawasihi kwa moyo wote: jitoleeni nafsi zenu kwa Mungu kama tambiko iliyo hai, takatifu na yenye kupendeza. Hii ndiyo njia yenu halisi ya kumwabudu.'),
(2018917,69,45,12,2,'Msiige mitindo ya ulimwengu huu, bali Mungu afanye mabadiliko ndani yenu kwa kuzigeuza fikira zenu. Hapo ndipo mtakapoweza kuyajua mapenzi ya Mungu, kutambua jambo lililo jema, linalompendeza na kamilifu.'),
(2018918,69,45,12,3,'Kutokana na neema aliyonijalia Mungu, nawaambieni ninyi nyote: msijione kuwa ni kitu zaidi kuliko mnavyopaswa kuwa. Fikira zenu na ziwe na kiasi kufuatana na kipimo cha imani Mungu aliyomgawia kila mmoja.'),
(2018919,69,45,12,4,'Mwili una viungo vingi, kila kimoja na kazi yake.'),
(2018920,69,45,12,5,'Hali kadhalika ingawa sisi ni wengi, tu mwili mmoja kwa kuungana na Kristo, na kila mmoja ni kiungo cha mwenzake.'),
(2018921,69,45,12,6,'Basi, tunavyo vipaji mbalimbali kufuatana na neema tuliyopewa. Mwenye kipaji cha unabii na akitumie kadiri ya imani yake.'),
(2018922,69,45,12,7,'Mwenye kipaji cha utumishi na atumikie. mwenye kipaji cha kufundisha na afundishe.'),
(2018923,69,45,12,8,'Mwenye kipaji cha kuwafariji wengine na afanye hivyo. Mwenye kumgawia mwenzake alicho nacho na afanye hivyo kwa ukarimu. Msimamizi na asimamie kwa bidii; naye mwenye kutenda jambo la huruma na afanye hivyo kwa furaha.'),
(2018924,69,45,12,9,'Mapendo yenu na yawe bila unafiki wowote. Chukieni jambo lolote ovu, zingatieni jema.'),
(2018925,69,45,12,10,'Pendaneni kidugu; kila mmoja amfikirie mwenzake kwanza kwa heshima.'),
(2018926,69,45,12,11,'Msilegee katika bidii, muwe wachangamfu rohoni katika kumtumikia Bwana.'),
(2018927,69,45,12,12,'Tumaini lenu liwaweke daima wenye furaha; muwe na saburi katika shida na kusali daima.'),
(2018928,69,45,12,13,'Wasaidieni watu wa Mungu katika mahitaji yao; wapokeeni wageni kwa ukarimu.'),
(2018929,69,45,12,14,'Watakieni baraka wote wanaowadhulumu ninyi; naam, watakieni baraka na wala msiwalaani.'),
(2018930,69,45,12,15,'Furahini pamoja na wanaofurahi, lieni pamoja na wanaolia.'),
(2018931,69,45,12,16,'Muwe na wema uleule kwa kila mtu. Msijitakie makuu, bali jishugulisheni na watu wadogo. Msijione kuwa wenye hekima sana.'),
(2018932,69,45,12,17,'Msilipe ovu kwa ovu. Zingatieni mambo mema mbele ya wote.'),
(2018933,69,45,12,18,'Kadiri inavyowezekana kwa upande wenu, muwe na amani na watu wote.'),
(2018934,69,45,12,19,'Wapenzi wangu, msilipize kisasi, bali mwachieni Mungu jambo hilo; maana Maandiko Matakatifu yasema: "Kulipiza kisasi ni shauri langu; mimi nitalipiza asema Bwana."'),
(2018935,69,45,12,20,'Tena, Maandiko yasema: "Adui yako akiwa na njaa, mpe chakula; akiwa na kiu, mpe kinywaji. Maana kwa kufanya hivyo utamfanya apate aibu kali kama makaa ya moto juu ya kichwa chake."'),
(2018936,69,45,12,21,'Usikubali kushindwa na ubaya, bali ushinde ubaya kwa wema.'),
(2018937,69,45,13,1,'Kila mtu anapaswa kuwatii wenye mamlaka katika serikali; maana mamlaka yote hutoka kwa Mungu; nao wenye mamlaka wamewekwa na Mungu.'),
(2018938,69,45,13,2,'Anayepinga mamlaka ya viongozi anapinga agizo la Mungu; nao wafanyao hivyo wanajiletea hukumu wenyewe,'),
(2018939,69,45,13,3,'Maana, watawala hawasababishi hofu kwa watu wema, ila kwa watu wabaya. Basi, wataka usimwogope mtu mwenye mamlaka? Fanya mema naye atakusifu;'),
(2018940,69,45,13,4,'maana yeye ni mtumishi wa Mungu anayefanya kazi kwa faida yako. Lakini ukifanya mabaya, basi, huna budi kumwogopa, maana anao kweli uwezo wa kutoa adhabu. Yeye ni mtumishi wa Mungu na huitekeleza ghadhabu ya Mungu kwao watendao maovu.'),
(2018941,69,45,13,5,'Kwa hiyo ni lazima kuwatii wenye mamlaka, si tu kwa sababu ya kuogopa ghadhabu ya Mungu, bali pia kwa sababu dhamiri inadai hivyo.'),
(2018942,69,45,13,6,'Kwa sababu hiyohiyo ninyi hulipa kodi; maana viongozi hao humtumikia Mungu ikiwa wanatimiza wajibu wao.'),
(2018943,69,45,13,7,'Mpeni kila mtu haki yake; mtu wa ushuru, ushuru; wa kodi, kodi; na astahiliye heshima, heshima.'),
(2018944,69,45,13,8,'Msiwe na deni kwa mtu yeyote, isipokuwa tu deni la kupendana. Ampendaye jirani yake ameitekeleza Sheria.'),
(2018945,69,45,13,9,'Maana, amri hizi: "Usizini; Usiue; Usitamani;" na nyingine zote, zimo katika amri hii moja: "Mpende jirani yako kama unavyojipenda mwenyewe."'),
(2018946,69,45,13,10,'Ampendaye jirani yake hamtendei vibaya. Basi, kwa mapendo Sheria yote hutimizwa.'),
(2018947,69,45,13,11,'Zaidi ya hayo, ninyi mnajua tumo katika wakati gani: sasa ndio wakati wa kuamka usingizini; naam, wokovu wetu u karibu zaidi sasa kuliko wakati ule tulipoanza kuamini.'),
(2018948,69,45,13,12,'Usiku unakwisha na mchana unakaribia. Basi, tutupilie mbali mambo yote ya giza, tukajitwalie silaha za mwanga.'),
(2018949,69,45,13,13,'Mwenendo wetu uwe wa adabu kama inavyostahili wakati wa mchana; tusiwe na ulafi na ulevi, uchafu na uasherati, ugomvi na wivu.'),
(2018950,69,45,13,14,'Bwana Yesu Kristo awe vazi lenu; msishughulikie tena tamaa zenu za maumbile na kuziridhisha.'),
(2018951,69,45,14,1,'Mkaribisheni kwenu mtu aliye dhaifu, lakini msibishane naye juu ya mawazo yake binafsi.'),
(2018952,69,45,14,2,'Watu huhitilafiana: mmoja imani yake inamruhusu kula kila kitu; lakini mwingine ambaye imani yake ni dhaifu, hula tu mboga za majani.'),
(2018953,69,45,14,3,'Mtu ambaye hula kila kitu asimdharau yule ambaye hawezi kula kila kitu; naye ambaye hula tu mboga za majani asimhukumu anayekula kila kitu, maana Mungu amemkubali.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2018954,69,45,14,4,'Wewe ni nani hata uthubutu kumhukumu mtumishi wa mwingine? Akisimama au akianguka ni shauri la Bwana wake; naam, atasimama imara, maana Bwana anaweza kumsimamisha.'),
(2018955,69,45,14,5,'Mtu anaweza kufikiria siku fulani kuwa ya maana zaidi kuliko nyingine; mtu mwingine aweza kuzifikiria siku zote kuwa sawa. Kila mmoja na afuate msimamo wa akili yake.'),
(2018956,69,45,14,6,'Anayeadhimisha siku fulani anaadhimisha siku hiyo kwa ajili ya kumtukuza Mungu; naye anayekula chakula fulani anafanya hivyo kwa kumtukuza Bwana maana anamshukuru Mungu. Kadhalika naye anayeacha kula chakula fulani anafanya hivyo kwa ajili ya kumtukuza Bwana, naye pia anamshukuru Mungu.'),
(2018957,69,45,14,7,'Maana hakuna mtu yeyote miongoni mwetu aishiye kwa ajili yake mwenyewe, wala hakuna anayekufa kwa ajili yake mwenyewe'),
(2018958,69,45,14,8,'maana tukiishi twaishi kwa ajili ya Bwana; tukifa, tunakufa kwa ajili ya Bwana. Basi, kama tukiishi au tukifa, sisi ni mali yake Bwana.'),
(2018959,69,45,14,9,'Maana Kristo alikufa, akafufuka ili wapate kuwa Bwana wa wazima na wafu.'),
(2018960,69,45,14,10,'Kwa nini, basi wewe wamhukumu ndugu yako? Nawe, kwa nini wamdharau ndugu yako? Sisi sote tutasimama mbele ya kiti cha hukumu cha Mungu.'),
(2018961,69,45,14,11,'Maana Maandiko yanasema: "Kama niishivyo, asema Bwana kila mtu atanipigia magoti, na kila mmoja atakiri kwamba mimi ni Mungu."'),
(2018962,69,45,14,12,'Kwa hiyo, kila mmoja wetu atatoa hoja yake mbele ya Mungu.'),
(2018963,69,45,14,13,'Basi, tuache kuhukumiana, bali tuazimie kutokuwa kamwe kikwazo kwa ndugu yetu au kumsababisha aanguke katika dhambi.'),
(2018964,69,45,14,14,'Katika kuungana na Bwana Yesu, nina hakika kwamba hakuna kitu chochote kilicho najisi kwa asili yake; lakini, mtu akidhani kwamba kitu fulani ni najisi, basi, kwake huwa najisi.'),
(2018965,69,45,14,15,'Kama ukimhuzunisha ndugu yako kwa sababu ya chakula unachokula, basi mwenendo wako hauongozwi na mapendo. Usikubali hata kidogo chakula chako kiwe sababu ya kupotea kwa mtu mwingine ambaye Kristo alikufa kwa ajili yake!'),
(2018966,69,45,14,16,'Basi, msikubalie kitu mnachokiona kuwa kwenu ni kitu chema kidharauliwe.'),
(2018967,69,45,14,17,'Maana Utawala wa Mungu si shauri la kula na kunywa, bali unahusika na kuwa na uadilifu, amani na furaha iletwayo na Roho Mtakatifu.'),
(2018968,69,45,14,18,'Anayemtumikia Kristo namna hiyo humpendeza Mungu, na kukubaliwa na watu.'),
(2018969,69,45,14,19,'Kwa hiyo tuyazingatie daima mambo yenye kuleta amani, na yanayotusaidia kujengana.'),
(2018970,69,45,14,20,'Basi, usiiharibu kazi ya Mungu kwa sababu ya ubishi juu ya chakula. Vyakula vyote ni halali, lakini haifai kula chakula ambacho kitamfanya mtu aanguke katika dhambi.'),
(2018971,69,45,14,21,'Afadhali kuacha kula nyama, kunywa divai, au kufanya chochote ambacho chaweza kumsababisha ndugu yako aanguke.'),
(2018972,69,45,14,22,'Basi, shikilia unachoamini kati yako na Mungu wako. Heri mtu yule ambaye, katika kujiamulia la kufanya, haipingi dhamiri yake.'),
(2018973,69,45,14,23,'Lakini mtu anayeona shaka juu ya chakula anachokula, anahukumiwa kama akila, kwa sababu msimamo wa kitendo chake haumo katika imani. Na, chochote kisicho na msingi wake katika imani ni dhambi.'),
(2018974,69,45,15,1,'Sisi tulio imara katika imani tunapaswa kuwasaidia wale walio dhaifu wayakabili matatizo yao. Tusijipendelee sisi wenyewe tu.'),
(2018975,69,45,15,2,'Kila mmoja wetu anapaswa kumpendeza jirani yake kwa wema ili huyo apate kujijenga katika imani.'),
(2018976,69,45,15,3,'Maana Kristo hakujipendelea mwenyewe; ila alikuwa kama yasemavyo Maandiko: "Kashfa zote walizokutolea wewe zimenipata mimi."'),
(2018977,69,45,15,4,'Maana yote yalioandikwa yameandikwa kwa ajili ya kutufundisha sisi ili kutokana na saburi na faraja tupewayo na Maandiko hayo Matakatifu tupate kuwa na matumaini.'),
(2018978,69,45,15,5,'Mungu aliye msingi wa saburi na faraja yote, awajalieni ninyi kuwa na msimamo mmoja kufuatana na mfano wake Kristo Yesu,'),
(2018979,69,45,15,6,'ili ninyi nyote, kwa nia moja na sauti moja, mumtukuze Mungu, Baba wa Bwana wetu Yesu Kristo.'),
(2018980,69,45,15,7,'Basi, karibishaneni kwa ajili ya utukufu wa Mungu kama naye Kristo alivyowakaribisheni.'),
(2018981,69,45,15,8,'Maana, nawaambieni Kristo aliwatumikia Wayahudi apate kuonyesha uaminifu wa Mungu, na zile ahadi Mungu alizowapa babu zetu zipate kutimia;'),
(2018982,69,45,15,9,'ili nao watu wa mataifa mengine wapate kumtukuza Mungu kwa sababu ya huruma yake. Kama yasemavyo Maandiko Matakatifu: "Kwa sababu hiyo, nitakusifu miongoni mwa watu wa mataifa. Nitaziimba sifa za jina lako."'),
(2018983,69,45,15,10,'Tena Maandiko yasema: "Furahini, enyi watu wa mataifa; furahini pamoja na watu wake."'),
(2018984,69,45,15,11,'Na tena: "Enyi mataifa yote, msifuni Bwana; enyi watu wote, msifuni."'),
(2018985,69,45,15,12,'Tena Isaya asema: "Atatokea mtu katika ukoo wa Yese, naye atawatawala watu wa mataifa; nao watamtumainia."'),
(2018986,69,45,15,13,'Basi, Mungu aliye msingi wa matumaini, awajazeni furaha yote na amani kutokana na imani yenu; tumaini lenu lipate kuongezeka kwa nguvu ya Roho Mtakatifu.'),
(2018987,69,45,15,14,'Ndugu zangu, mimi binafsi nina hakika kwamba ninyi pia mmejaa wema, elimu yote, na mnaweza kushauriana ninyi kwa ninyi.'),
(2018988,69,45,15,15,'Lakini nimewaandikia hapa na pale katika barua hii bila woga, nipate kuwakumbusheni juu ya mambo fulani. Nimefanya hivyo kwa sababu ya neema aliyonijalia Mungu'),
(2018989,69,45,15,16,'ya kuwa mtumishi wa Yesu Kristo kwa watu wa mataifa. Ni jukumu langu la kikuhani kuihubiri Habari Njema ya Mungu ili watu wa mataifa mengine wapate kuwa dhabihu inayokubaliwa na Mungu, dhabihu iliyotakaswa na Roho Mtakatifu.'),
(2018990,69,45,15,17,'Kwa hiyo, nikiwa nimeungana na Kristo Yesu, naweza kujivunia huduma yangu kwa ajili ya Mungu.'),
(2018991,69,45,15,18,'Sithubutu kusema kitu kingine chochote isipokuwa tu kile ambacho Kristo Yesu amekifanya kwa kunitumia mimi ili watu wa mataifa wapate kutii. Amefanya hivyo kwa maneno na vitendo,'),
(2018992,69,45,15,19,'kwa nguvu ya miujiza na maajabu, na kwa nguvu ya Roho wa Mungu. Basi, kwa kusafiri kila mahali, tangu kule Yerusalemu mpaka Iluriko, nimeihubiri kikamilifu Habari Njema ya Kristo.'),
(2018993,69,45,15,20,'Nia yangu imekuwa daima kuihubiri Habari Njema popote pale ambapo jina la Kristo halijapata kusikika, nisije nikajenga juu ya msingi wa mtu mwingine.'),
(2018994,69,45,15,21,'Kama yasemavyo Maandiko Matakatifu: "Watu wote ambao hawakuambiwa habari zote wataona; nao wale ambao hawajapata kusikia, wataelewa."'),
(2018995,69,45,15,22,'Kwa sababu hiyo nilizuiwa mara nyingi kuja kwenu.'),
(2018996,69,45,15,23,'Lakini maadam sasa nimemaliza kazi yangu pande hizi, na kwa kuwa kwa miaka mingi nimekuwa na nia kubwa ya kuja kwenu,'),
(2018997,69,45,15,24,'natumaini kufanya hivyo sasa. Ningependa kuwaoneni nikiwa safarini kwenda Spania na kupata msaada wenu kwa safari hiyo baada ya kufurahia kuwa kwa muda pamoja nanyi.'),
(2018998,69,45,15,25,'Lakini, kwa sasa nakwenda kuwahudumia watu wa Mungu kule Yerusalem.'),
(2018999,69,45,15,26,'Maana makanisa ya Makedonia na Akaya yemeamua kutoka mchango wao kuwasaidia watu wa Mungu walio maskini huko Yerusalem.'),
(2019000,69,45,15,27,'Wao wenyewe wameamua kufanya hivyo; lakini, kwa kweli, hilo ni jukumu lao kwa hao. Maana, ikiwa watu wa mataifa mengine wameshiriki baraka za kiroho za Wayahudi, wanapaswa nao pia kuwahudumia Wayahudi katika mahitaji yao ya kidunia.'),
(2019001,69,45,15,28,'Nitakapokwisha tekeleza kazi hiyo na kuwakabidhi mchango huo uliokusanywa kwa ajili yao, nitawatembeleeni ninyi nikiwa safarini kwenda Spania.'),
(2019002,69,45,15,29,'Najua ya kuwa nikija kwenu nitawaletea wingi wa baraka za Kristo.'),
(2019003,69,45,15,30,'Basi, ndugu zangu, nawasihi kwa kwa ajili ya Bwana wetu Yesu Kristo, na kwa ajili ya upendo uletwao na Roho, mniunge mkono kwa kuniombea kwa Mungu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019004,69,45,15,31,'Ombeni nipate kutoka salama miongoni mwa wale wasioamini walioko Uyahudi, nayo huduma yangu huko Yerusalem ipate kukubaliwa na watu wa Mungu walioko huko.'),
(2019005,69,45,15,32,'Hivyo, Mungu akipenda, nitaweza kuja kwenu na moyo wa furaha, nikapumzike pamoja nanyi.'),
(2019006,69,45,15,33,'Mungu aliye chanzo cha amani na awe nanyi nyote! Amina!'),
(2019007,69,45,16,1,'Napenda kumjulisha kwenu dada yetu Foibe ambaye ni mtumishi katika kanisa la Kenkrea.'),
(2019008,69,45,16,2,'Mpokeeni kwa ajili ya Bwana kama iwapasavyo watu wa Mungu. Mpeni msaada wowote atakaohitaji kutoka kwenu, maana yeye amekuwa mwema sana kwa watu wengi na kwangu pia.'),
(2019009,69,45,16,3,'Salamu zangu ziwafikie Priska na Akula, wafanyakazi wenzangu katika utumishi wa Kristo Yesu.'),
(2019010,69,45,16,4,'Wao walihatarisha maisha yao kwa ajili yangu. Wanastahili shukrani; si tu kutoka kwangu, bali pia kutoka kwa makanisa yote ya watu wa mataifa mengine.'),
(2019011,69,45,16,5,'Salamu zangu pia kwa kanisa linalokutana nyumbani kwao. Salamu zangu zimfikie rafiki yangu Epaineto ambaye ni kwa kwanza katika mkoa wa Asia kumwamini Kristo.'),
(2019012,69,45,16,6,'Nisalimieni Maria ambaye amefanya kazi kwa bidii kwa ajili yenu.'),
(2019013,69,45,16,7,'Salamu zangu kwa Androniko na Yunia, wananchi wenzangu waliofungwa gerezani pamoja nami; wao wanajulikana sana kati ya mitume; tena walikuwa Wakristo kabla yangu mimi.'),
(2019014,69,45,16,8,'Salamu zangu kwa Ampliato, rafiki yangu katika kuungana na Bwana.'),
(2019015,69,45,16,9,'Salamu zangu zimfikie Urbano, mfanyakazi mwenzangu katika utumishi wa Kristo; salamu zangu pia kwa rafiki yangu Staku.'),
(2019016,69,45,16,10,'Nisalimieni Apele ambaye uaminifu wake kwa Kristo umethibitishwa. Salamu zangu kwa wote walio nyumbani mwa Aristobulo.'),
(2019017,69,45,16,11,'Salamu zangu kwa Herodiana, mwananchi mwenzangu; na kwa jamaa yote ya Narkisi iliyojiunga na Bwana.'),
(2019018,69,45,16,12,'Nisalimieni Trufena na Trufosa wanaofanya kazi katika utumishi wa Bwana, na rafiki yangu Persi ambaye amefanya mengi kwa ajili ya Bwana.'),
(2019019,69,45,16,13,'Nisalimieni Rufo, mtu hodari sana katika kazi ya Bwana, na mama yake ambaye ni mama yangu pia.'),
(2019020,69,45,16,14,'Nisalimieni Asunkrito, Flegoni, Herme Patroba, Herma na ndugu wote walio pamoja nao.'),
(2019021,69,45,16,15,'Nisalimieni Filologo na Yulia, Nerea na dada yake, na Olumpa, pamoja na watu wote wa Mungu walio pamoja nao.'),
(2019022,69,45,16,16,'Salimianeni ninyi kwa ninyi kwa ishara ya upendo. Salamu kwenu kutoka kwa makanisa yote ya Kristo.'),
(2019023,69,45,16,17,'Ndugu zangu, nawasihi muwafichue wote wanaosababisha mafarakano na kuwafanya watu wengine waanguke, kinyume cha mafundisho mliyofundishwa. Jiepusheni na watu hao,'),
(2019024,69,45,16,18,'maana watu wa namna hiyo hawamtumikii Kristo Bwana wetu, bali wanayatumikia matumbo yao wenyewe. Kwa maneno yao matamu na hotuba za kubembeleza hupotosha mioyo ya watu wanyofu.'),
(2019025,69,45,16,19,'Kila mtu amesikia juu ya utii wenu na hivyo mmekuwa sababu ya furaha yangu. Nawatakeni muwe na hekima katika mambo mema, na bila hatia kuhusu mambo mabaya.'),
(2019026,69,45,16,20,'Naye Mungu aliye chanzo cha amani hatakawia kumponda Shetani chini ya miguu yenu. Neema ya Bwana wetu Yesu Kristo iwe nanyi.'),
(2019027,69,45,16,21,'Timotheo, mfanyakazi mwenzangu, anawasalimu. Hali kadhalika Lukio, Yasoni, na Sosipatro, wananchi wenzangu, wanawasalimu.'),
(2019028,69,45,16,22,'Nami Tertio, ninayeandika barua hii nawasalimuni katika Bwana.'),
(2019029,69,45,16,23,'Gayo, mwenyeji wangu, pamoja na kanisa lote linalokutana kwake, anawasalimu. Erasto, mweka hazina wa mji huu, pamoja na Kwarto, wanawasalimu.*fb*'),
(2019030,69,45,16,24,'missing'),
(2019031,69,45,16,25,'Basi, sasa na tumsifu Mungu! Yeye anaweza kuwaimarisheni katika ile Habari Njema niliyohubiri juu ya ujumbe wa Yesu Kristo, na katika ile siri iliyofunuliwa na ambayo ilikuwa imefichika kwa karne nyinyi zilizopita.'),
(2019032,69,45,16,26,'Lakini, sasa ukweli huo umefunuliwa kwa njia ya maandiko ya manabii; na kwa amri ya Mungu wa milele umedhihirisha kwa mataifa yote ili wote waweze kuamini na kutii.'),
(2019033,69,45,16,27,'Kwake Mungu aliye peke yake mwenye hekima, uwe utukufu kwa njia ya Yesu Kristo, milele na milele! Amina.'),
(2019034,69,46,1,1,'Mimi Paulo, niliyeitwa kuwa mtume wa Kristo Yesu kwa mapenzi ya Mungu, na ndugu Sosthene,'),
(2019035,69,46,1,2,'tunawaandikia ninyi mlio kanisa la Mungu huko Korintho. Ninyi mmefanywa watakatifu katika kuungana na Kristo Yesu, mkaitwa muwe watu wa Mungu, pamoja na watu wote popote wanaomwomba Bwana wetu Yesu Kristo aliye Bwana wao na wetu pia.'),
(2019036,69,46,1,3,'Nawatakieni neema na amani kutoka kwa Mungu Baba yetu na Bwana wetu Yesu Kristo.'),
(2019037,69,46,1,4,'Ninamshukuru Mungu wangu daima kwa ajili yenu kwa sababu amewatunukia ninyi neema yake kwa njia ya Kristo Yesu.'),
(2019038,69,46,1,5,'Maana, kwa kuungana na Kristo mmetajirishwa katika kila kitu. Mmejaliwa elimu yote na uwezo wote wa kuhubiri,'),
(2019039,69,46,1,6,'kwani, ujumbe juu ya Kristo umethibitishwa ndani yenu,'),
(2019040,69,46,1,7,'hata hampungukiwi kipaji chochote cha kiroho mkiwa mnangojea kufunuliwa kwake Bwana wetu Yesu Kristo.'),
(2019041,69,46,1,8,'Yeye atawaimarisha ninyi mpaka mwisho mpate kuonekana bila hatia Siku ile ya Bwana wetu Yesu Kristo.'),
(2019042,69,46,1,9,'Mungu ni mwaminifu; yeye aliwaita ninyi muwe na umoja na Mwanae Yesu Kristo Bwana wetu.'),
(2019043,69,46,1,10,'Ndugu, ninawasihi kwa jina la Bwana wetu Yesu Kristo: pataneni nyote katika kila jambo msemalo; yasiweko mafarakano kati yenu; muwe na fikira moja na nia moja.'),
(2019044,69,46,1,11,'Ndugu zangu, habari nilizopata kutoka kwa watu kadhaa wa jamaa ya Kloe, zaonyesha wazi kwamba kuna kutoelewana kati yenu.'),
(2019045,69,46,1,12,'Nataka kusema hivi: kila mmoja anasema chake: mmoja husema, "Mimi ni wa Paulo," mwingine: "Mimi ni wa Apolo," mwingine: "Mimi ni wa Kefa," na mwingine: "Mimi ni wa Kristo,".'),
(2019046,69,46,1,13,'Je, Kristo amegawanyika? Je, Paulo ndiye aliyesulubiwa kwa ajili yenu? Au je, mlibatizwa kwa jina la Paulo?'),
(2019047,69,46,1,14,'Namshukuru Mungu kwamba sikumbatiza mtu yeyote miongoni mwenu isipokuwa tu Krispo na Gayo.'),
(2019048,69,46,1,15,'Kwa hiyo hakuna awezaye kusema amebatizwa kwa jina langu.'),
(2019049,69,46,1,16,'Samahani, nilibatiza pia jamaa ya Stefana; lakini zaidi ya hawa, sidhani kama nilimbatiza mtu mwingine yeyote.)'),
(2019050,69,46,1,17,'Kristo hakunituma kubatiza, bali kuhubiri Habari Njema; tena, niihubiri bila kutegemea maarifa ya hotuba za watu kusudi nguvu ya kifo cha Kristo msalabani isibatilishwe.'),
(2019051,69,46,1,18,'Maana ujumbe kuhusu kifo cha Kristo msalabani ni jambo la kipumbavu kwa wale walio katika mkumbo wa kupotea, lakini kwetu sisi tulio katika njia ya wokovu ujumbe huo ni nguvu ya Mungu.'),
(2019052,69,46,1,19,'Maana Maandiko Matakatifu yasema: "Nitaiharibu hekima yao wenye hekima, na elimu ya wataalamu nitaitupilia mbali."'),
(2019053,69,46,1,20,'Yu wapi basi, mwenye hekima? Yu wapi basi, mwalimu wa Sheria? Naye bingwa wa mabishano wa nyakati hizi yuko wapi? Mungu ameifanya hekima ya ulimwengu kuwa upumbavu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019054,69,46,1,21,'Maana, kadiri ya hekima ya Mungu, watu hawawezi kumjua Mungu kwa njia ya hekima yao wenyewe. Badala yake, Mungu amependa kuwaokoa wale wanaoamini kwa njia ya kile ambacho wenye hekima wanakiona kuwa ni upumbavu, yaani ujumbe tunaohubiri.'),
(2019055,69,46,1,22,'Wayahudi wanataka ishara, na Wagiriki wanatafuta hekima;'),
(2019056,69,46,1,23,'lakini sisi tunamhubiri Kristo aliyesulubiwa. Kwa Wayahudi jambo hili ni kikwazo, na kwa watu wa mataifa ni upumbavu;'),
(2019057,69,46,1,24,'lakini kwa wale walioitwa, Wayahudi kwa Wagiriki, Kristo ni nguvu ya Mungu na hekima ya Mungu.'),
(2019058,69,46,1,25,'Maana kinachoonekana kuwa ni upumbavu wa Mungu, kina busara zaidi kuliko hekima ya binadamu; na kinachoonekana kuwa ni udhaifu wa Mungu, kina nguvu zaidi kuliko nguvu za binadamu.'),
(2019059,69,46,1,26,'Ndugu, kumbukeni wakati mlipoitwa: wengi wenu hawakuwa wenye hekima hata kwa fikira za binadamu; wengi hawakuwa wenye nguvu au watu wa tabaka ya juu.'),
(2019060,69,46,1,27,'Ndiyo kusema, Mungu aliyachagua yale ambayo ulimwengu huyaona ni upumbavu, ili awaaibishe wenye hekima; na aliyachagua yale ambayo ulimwengu huyaona ni dhaifu, ili awaaibishe wenye nguvu.'),
(2019061,69,46,1,28,'Mungu ameyachagua yale ambayo kwa fikira za dunia ni mambo yaliyo duni na yanayodharauliwa, mambo ambayo hata hayakuwako, ili kwa hayo ayafutilie mbali yale ambayo kwa fikira za binadamu ni mambo ya maana.'),
(2019062,69,46,1,29,'Basi, hakuna mtu awezaye kujivunia chochote mbele ya Mungu.'),
(2019063,69,46,1,30,'Mungu mwenyewe ndiye aliyewaunganisha ninyi na Kristo Yesu. Mungu amemfanya Kristo awe hekima yetu; kwa njia yake sisi tunapatanishwa na Mungu, tunakuwa watu wake Mungu na kukombolewa.'),
(2019064,69,46,1,31,'Basi, kama yasemavyo Maandiko Matakatifu: "Mwenye kutaka kujivuna, basi, na ajivunie kazi ya Bwana."'),
(2019065,69,46,2,1,'Ndugu, mimi nilipokuja kwenu sikuwahubiria siri ya ujumbe wa Mungu kwa ufasaha wa lugha, au kwa hekima ya binadamu.'),
(2019066,69,46,2,2,'Nilipokuwa kwenu niliamua kutojua chochote kile isipokuwa tu kumjua Yesu Kristo; naam, Kristo aliyesulubiwa.'),
(2019067,69,46,2,3,'Nilipokuwa kwenu nilikuwa dhaifu, natetemeka kwa hofu nyingi.'),
(2019068,69,46,2,4,'Hotuba zangu na mahubiri yangu sikuyatoa kwa maneno ya kuvutia na ya hekima, bali kwa uthibitisho mwingi na nguvu ya Roho.'),
(2019069,69,46,2,5,'Nilifanya hivyo kusudi imani yenu ipate kutegemea nguvu ya Mungu, na si hekima ya binadamu.'),
(2019070,69,46,2,6,'Hata hivyo, sisi tunatumia lugha ya hekima kwa wale waliokomaa kiroho; lakini hekima hiyo si ya hapa duniani, wala si ya watawala wa dunia hii ambao wako katika mkumbo wa kupotea.'),
(2019071,69,46,2,7,'Hekima tunayotumia ni hekima ya siri ya Mungu, hekima iliyofichika, ambayo Mungu aliiazimia tangu mwanzo kwa ajili ya utukufu wetu.'),
(2019072,69,46,2,8,'Ni hekima ambayo watawala wa dunia hii hawakuielewa; maana wangalielewa, hawangalimsulubisha Bwana wa utukufu.'),
(2019073,69,46,2,9,'Lakini, ni kama yasemavyo Maandiko Matakatifu: "Mambo ambayo jicho halijapata kuyaona wala sikio kuyasikia, mambo ambayo binadamu hajapata kuyafikiria moyoni, hayo ndiyo Mungu aliyowatayarishia wale wampendao."'),
(2019074,69,46,2,10,'Hayo ndiyo mambo Mungu aliyotufunulia kwa njia ya Roho wake. Maana Roho huchunguza kila kitu hata mambo ya ndani kabisa ya Mungu.'),
(2019075,69,46,2,11,'Nani awezaye kujua mambo ya ndani ya mtu isipokuwa roho yake mtu huyo? Hali kadhalika, hakuna ajuaye mambo ya Mungu isipokuwa Roho wa Mungu.'),
(2019076,69,46,2,12,'Sasa sisi hatukuipokea roho ya ulimwengu, bali tumepokea Roho atokaye kwa Mungu ili atuwezeshe kujua yale tuliyojaliwa na Mungu.'),
(2019077,69,46,2,13,'Basi sisi twafundisha, si kwa maneno tuliyofundishwa kwa hekima ya binadamu, bali kwa maneno tuliyofundishwa na Roho, tukifafanua mambo ya kiroho kwa walio na huyo Roho.'),
(2019078,69,46,2,14,'Mtu wa kidunia hapokei mambo ya Roho wa Mungu. Kwake mtu huyo mambo hayo ni upumbavu mtupu; yanapita akili yake; maana yanaweza tu kutambuliwa kwa msaada wa Roho.'),
(2019079,69,46,2,15,'Lakini mtu aliye na huyo Roho anaweza kubainisha ubora wa kila kitu, naye mwenyewe hahukumiwi na mtu mwingine.'),
(2019080,69,46,2,16,'Maandiko yasema: "Nani awezaye kuifahamu akili ya Bwana? Nani awezaye kumshauri?" Lakini sisi tunayo akili ya Kristo.'),
(2019081,69,46,3,1,'Ndugu, mimi sikuweza kusema nanyi kama watu mlio na huyo Roho. Nilipaswa kusema nanyi kama watu wa kidunia, kama watoto wachanga katika maisha ya Kikristo.'),
(2019082,69,46,3,2,'Ilinibidi kuwalisheni kwa maziwa, na si kwa chakula kigumu, kwani hamkuwa tayari kukipokea. Hata sasa hamko tayari.'),
(2019083,69,46,3,3,'Maana bado mu watu wa kidunia. Je, si kweli kwamba bado uko wivu na magombano kati yenu? Mambo hayo yanaonyesha wazi kwamba ninyi bado ni watu wa kidunia, mnaishi mtindo wa kidunia.'),
(2019084,69,46,3,4,'Mmoja wenu anaposema, "Mimi ni wa Paulo", na mwingine, "Mimi ni wa Apolo", je, hiyo haionyeshi kwamba mnaishi bado kama watu wa dunia hii tu?'),
(2019085,69,46,3,5,'Apolo ni nani? na Paulo ni nani? Sisi ni watumishi tu ambao tuliwaleteeni ninyi imani. Kila mmoja wetu anafanya kazi aliyopewa na Bwana.'),
(2019086,69,46,3,6,'Mimi nilipanda mbegu, Apolo akamwagilia maji; lakini aliyeiotesha mbegu ni Mungu.'),
(2019087,69,46,3,7,'Wa maana si yule aliyepanda mbegu, au yule aliyemwagilia maji; wa maana ni Mungu aliyeiwezesha mbegu kuota.'),
(2019088,69,46,3,8,'Yule aliyepanda na yule aliyemwagilia maji wote ni sawa, ingawa kila mmoja atapokea tuzo lake kufuatana na jitihada yake mwenyewe.'),
(2019089,69,46,3,9,'Maana sisi ni ndugu, wafanyakazi pamoja na Mungu; na ninyi ni shamba lake; ninyi ni jengo lake.'),
(2019090,69,46,3,10,'Kwa msaada wa neema aliyonipa Mungu, nimefaulu, kama mwashi stadi mwenye busara, kuweka msingi ambao juu yake mtu mwingine anajenga. Basi, kila mmoja awe mwangalifu jinsi anavyojenga juu yake.'),
(2019091,69,46,3,11,'Hakuna mtu awezaye kuweka msingi mwingine badala ya ule uliokwisha wekwa, yaani Yesu Kristo.'),
(2019092,69,46,3,12,'Juu ya msingi huo mtu anaweza kujenga kwa dhahabu, fedha au mawe ya thamani; anaweza kutumia miti, majani au nyasi.'),
(2019093,69,46,3,13,'Iwe iwavyo, ubora wa kazi ya kila mmoja utaonekana wakati Siku ile ya Kristo itakapoifichua. Maana, Siku hiyo itatokea na moto, na huo moto utaipima na kuonyesha ubora wake.'),
(2019094,69,46,3,14,'Ikiwa alichojenga mtu juu ya huo msingi kitaustahimili huo moto, atapokea tuzo;'),
(2019095,69,46,3,15,'lakini kama alichojenga kitaunguzwa, basi, atapoteza tuzo lake; lakini yeye mwenyewe ataokolewa kana kwamba ameponyoka kutoka motoni.'),
(2019096,69,46,3,16,'Je, hamjui kwamba ninyi ni hekalu la Mungu, na kwamba Roho wa Mungu anakaa ndani yenu?'),
(2019097,69,46,3,17,'Basi, mtu akiliharibu hekalu la Mungu, Mungu atamharibu; maana hekalu la Mungu ni takatifu, na hekalu hilo ni ninyi wenyewe.'),
(2019098,69,46,3,18,'Msijidanganye! Mtu yeyote miongoni mwenu akijidhania mwenye hekima mtindo wa kidunia, heri awe mjinga kusudi apate kuwa na hekima ya kweli.'),
(2019099,69,46,3,19,'Maana, hekima ya kidunia ni upumbavu mbele ya Mungu. Kwani Maandiko Matakatifu yasema: "Mungu huwanasa wenye hekima katika ujanja wao."'),
(2019100,69,46,3,20,'Na tena: "Bwana ajua kwamba mawazo ya wenye hekima hayafai."'),
(2019101,69,46,3,21,'Basi, mtu asijivunie watu. Maana kila kitu ni chenu.'),
(2019102,69,46,3,22,'Paulo, Apolo na Kefa, ulimwengu, maisha na kifo; mambo ya sasa na ya baadaye, yote ni yenu.'),
(2019103,69,46,3,23,'Lakini ninyi ni wa Kristo naye Kristo ni wa Mungu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019104,69,46,4,1,'Mtu na atuone sisi kuwa ni watumishi wa Kristo tuliokabidhiwa siri za mungu.'),
(2019105,69,46,4,2,'Kinachotakiwa kwa yeyote yule aliyekabidhiwa kazi ni kuwa mwaminifu.'),
(2019106,69,46,4,3,'Kwangu mimi si kitu nikihukumiwa na ninyi, au na mahakama ya kibinadamu; wala sijihukumu.'),
(2019107,69,46,4,4,'Dhamiri yangu hainishtaki kwa jambo lolote, lakini hiyo haionyeshi kwamba sina lawama. Bwana ndiye anayenihukumu.'),
(2019108,69,46,4,5,'Basi, msihukumu kabla ya wakati wake acheni mpaka Bwana atakapokuja. Yeye atayafichua mambo ya giza yaliyofichika, na kuonyesha wazi nia za mioyo ya watu. Ndipo kila mmoja atapata sifa anayostahili kutoka kwa Mungu.'),
(2019109,69,46,4,6,'Ndugu, hayo yote niliyosema juu ya Apolo na juu yangu, ni kielelezo kwenu: kutokana na mfano wangu mimi na Apolo nataka mwelewe maana ya msemo huu: "Zingatieni yaliyoandikwa." Kati yenu pasiwe na mtu yeyote anayejivunia mtu mmoja na kumdharau mwingine.'),
(2019110,69,46,4,7,'Nani amekupendelea wewe? Una kitu gani wewe ambacho hukupewa? Na ikiwa umepewa, ya nini kujivunia kana kwamba hukukipewa?'),
(2019111,69,46,4,8,'Haya, mmekwisha shiba! Mmekwisha kuwa matajiri! Mmekuwa wafalme bila ya sisi! Naam, laiti mngekuwa kweli watawala, ili nasi pia tuweze kutawala pamoja nanyi.'),
(2019112,69,46,4,9,'Nafikiri Mungu ametufanya sisi mitume tuwe watu wa mwisho kabisa, kama watu waliohukumiwa kuuawa, maana tumekuwa tamasha mbele ya ulimwengu wote, mbele ya malaika na watu.'),
(2019113,69,46,4,10,'Sisi ni wapumbavu kwa ajili ya Kristo, lakini ninyi ni wenye busara katika kuungana na Kristo! Sisi ni dhaifu, ninyi ni wenye nguvu. Ninyi mnaheshimika, sisi tunadharauliwa.'),
(2019114,69,46,4,11,'Mpaka dakika hii, sisi tuna njaa na kiu, hatuna nguo, twapigwa makofi, hatuna malazi.'),
(2019115,69,46,4,12,'Tena twataabika na kufanya kazi kwa mikono yetu wenyewe. Tukitukanwa, tunawatakia baraka; tukidhulumiwa, tunavumilia;'),
(2019116,69,46,4,13,'tukisingiziwa, tunajibu kwa adabu. Mpaka sasa tumetendewa kama uchafu wa dunia; na kwa kila mtu sisi ni takataka!'),
(2019117,69,46,4,14,'Siandiki mambo haya kwa ajili ya kuwaaibisha ninyi, bali kwa ajili ya kuwafundisheni watoto wangu wapenzi.'),
(2019118,69,46,4,15,'Maana hata kama mnao maelfu ya walezi katika maisha yenu ya Kikristo, baba yenu ni mmoja tu, kwani katika maisha ya Kikristo mimi ndiye niliyewazaeni kwa kuihubiri Habari Njema.'),
(2019119,69,46,4,16,'Kwa hiyo, nawasihi: fuateni mfano wangu.'),
(2019120,69,46,4,17,'Ndiyo maana nimemtuma Timetheo kwenu. Yeye ni mtoto wangu mpenzi na mwaminifu katika Bwana. Atawakumbusheni njia ninayofuata katika kuishi maisha ya Kikristo; njia ninayofundisha kila mahali katika makanisa yote.'),
(2019121,69,46,4,18,'Baadhi yenu wameanza kuwa na majivuno wakidhani kwamba sitakuja tena kwenu.'),
(2019122,69,46,4,19,'Lakini, Bwana akipenda, nitakuja kwenu upesi; na hapo ndipo nitakapojionea mwenyewe, sio tu kile wanachoweza kusema hao wenye majivuno, bali pia kila wanachoweza kufanya.'),
(2019123,69,46,4,20,'Maana Utawala wa Mungu si shauri la maneno matupu, bali ni nguvu.'),
(2019124,69,46,4,21,'Mnapendelea lipi? Nije kwenu na fimbo, ama nije na moyo wa upendo na upole?'),
(2019125,69,46,5,1,'Ziko habari za kuaminika kwamba kuna uzinzi miongoni mwenu; tena ni uzinzi mbaya ambao haujapata kuwako hata kati ya watu wasiomjua Mungu. Nimeambiwa eti mmoja wenu anaishi na mke wa baba yake!'),
(2019126,69,46,5,2,'Mnawezaje kujivuna? Ingekuwa afadhali kwenu kuomboleza, na huyo aliyefanya kitu hicho aondolewe miongoni mwenu.'),
(2019127,69,46,5,3,'Nami, kwa upande wangu, ingawa kwa mwili niko mbali nanyi, hata hivyo kwa roho niko hapo pamoja nanyi: na hivyo, kama vile nipo hapo, nimekwisha mhukumu huyo aliyefanya jambo hilo la aibu.'),
(2019128,69,46,5,4,'Wakati mnapokusanyika pamoja kwa jina la Bwana Yesu, nami nikiwa pamoja nanyi kwa roho, basi, kwa uwezo wa Bwana wetu Yesu,'),
(2019129,69,46,5,5,'mkabidhini mtu huyo kwa Shetani ili mwili wake uharibiwe na roho yake iweze kuokolewa Siku ile ya Bwana.'),
(2019130,69,46,5,6,'Majivuno yenu hayafai! Je, hamjui kwamba chachu kidogo huchachusha donge lote la unga?'),
(2019131,69,46,5,7,'Jitakaseni, mkatupe mbali chachu ya kale ili mpate kuwa donge jipya lisilotiwa chachu kama mnavyopaswa kuwa; maana, Kristo, Pasaka yetu, amekwisha tolewa tambiko.'),
(2019132,69,46,5,8,'Basi, tufanye karamu hiyo si kwa chachu ile ya kale, chachu ya ubaya na uovu, bali kwa mkate usiotiwa chachu, mkate wa usafi na kweli.'),
(2019133,69,46,5,9,'Niliwaandikia katika barua yangu msishirikiane na wazinzi.'),
(2019134,69,46,5,10,'Ukweli ni kwamba sikuwa na maana ya watu wote duniani walio wazinzi, wachoyo, walaghai na wenye kuabudu sanamu. Maana, ili kuwaepa hao wote ingewalazimu ninyi kuihama dunia hii kabisa!'),
(2019135,69,46,5,11,'Nilichoandika ni hiki: msishirikiane na ndugu Mkristo aliye mzinzi, mchoyo, mwenye kuabudu sanamu, mchongezi mlevi na mlaghai. Mtu wa namna hiyo, hata kula msile naye.'),
(2019136,69,46,5,12,'Je, ni shauri langu kuwahukumu watu walio nje? Hao Mungu atawahukumu. Je, ninyi hampaswi kuwahukumu wale walio katika jamii yenu ninyi wenyewe?'),
(2019137,69,46,5,13,'Mfukuzeni mbali nanyi huyo mwovu!'),
(2019138,69,46,6,1,'Anathubutuje mmoja wenu kumshtaki ndugu muumini mbele ya mahakama ya watu wasiomjua Mungu badala ya kumshtaki mbele ya watu wa Mungu?'),
(2019139,69,46,6,2,'Je, hamjui kwamba watu wa Mungu watauhukumu ulimwengu? Ikiwa basi, ulimwengu utahukumiwa nanyi, kwa nini hamstahili kuhukumu hata katika mambo madogo?'),
(2019140,69,46,6,3,'Je, hamjui kwamba, licha ya kuhukumu mambo ya kawaida ya kila siku, tutawahukumu hata malaika?'),
(2019141,69,46,6,4,'Mnapokuwa na mizozo juu ya mambo ya kawaida, je, mnawaita wawe mahakimu watu ambao hata hawalijali kanisa?'),
(2019142,69,46,6,5,'Aibu kwenu! Ndiyo kusema hakuna hata mmoja miongoni mwenu mwenye hekima kiasi cha kuweza kutatua tatizo kati ya ndugu waumini?'),
(2019143,69,46,6,6,'Badala yake, kweli imekuwa mtindo ndugu kumpeleka ndugu yake mahakamani, tena mbele ya mahakimu wasioamini.'),
(2019144,69,46,6,7,'Kwa kweli huko kushtakiana tu wenyewe kwa wenyewe kwabainisha kwamba mmeshindwa kabisa! Je, haingekuwa jambo bora zaidi kwenu kudhulumiwa! Haingekuwa bora zaidi kwenu kunyang`anywa mali yenu?'),
(2019145,69,46,6,8,'Lakini, badala yake, ninyi ndio mnaodhulumu na kunyang`anya; tena, hayo mnawafanyia ndugu zenu!'),
(2019146,69,46,6,9,'Au je, hamjui kwamba watu wabaya hawataurithi Utawala wa Mungu? Msijidanganye! Watu wanaoishi maisha ya uasherati, wanaoabudu sanamu, wazinzi, au walawiti,'),
(2019147,69,46,6,10,'wevi, wachoyo, walevi, wasengenyaji, wanyang`anyi, hao wote hawatashiriki Utawala wa Mungu.'),
(2019148,69,46,6,11,'Baadhi yenu mlikuwa hivyo; lakini sasa mmeoshwa, mkafanywa watakatifu, na kupatanishwa na Mungu kwa jina la Bwana Yesu Kristo na kwa Roho wa Mungu wetu.'),
(2019149,69,46,6,12,'Mtu anaweza kusema: "Kwangu mimi kila kitu ni halali." Sawa; lakini si kila kitu kinafaa. Nakubali kwamba kila kitu ni halali kwangu lakini sitaki kutawaliwa na kitu chochote.'),
(2019150,69,46,6,13,'Unaweza kusema: "Chakula ni kwa ajili ya tumbo, na tumbo ni kwa ajili ya chakula." Sawa; lakini Mungu ataviharibu vyote viwili. Mwili wa mtu si kwa ajili ya uzinzi bali ni kwa ajili ya kumtumikia Bwana, naye Bwana ni kwa ajili ya mwili.'),
(2019151,69,46,6,14,'Basi, Mungu aliyemfufua Bwana kutoka wafu atatufufua nasi pia kwa nguvu yake.'),
(2019152,69,46,6,15,'Je, hamjui kwamba miili yenu ni viungo vya mwili wa Kristo? Je, mnadhani naweza kuchukua sehemu ya mwili wa Kristo na kuifanya kuwa sehemu ya mwili wa kahaba? Hata kidogo!'),
(2019153,69,46,6,16,'Maana, kama mjuavyo, anayeungana na kahaba huwa mwili mmoja naye--kama ilivyoandikwa: "Nao wawili watakuwa mwili mmoja."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019154,69,46,6,17,'Lakini aliyejiunga na Bwana huwa roho moja naye.'),
(2019155,69,46,6,18,'Jiepusheni kabisa na uzinzi. Dhambi nyingine zote hutendwa nje ya mwili lakini mzinzi hutenda dhambi dhidi ya mwili wake mwenyewe.'),
(2019156,69,46,6,19,'Je, hamjui kwamba miili yenu ni hekalu la Roho Mtakatifu aliye ndani yenu, ambaye mlimpokea kutoka kwa Mungu? Ninyi basi, si mali yenu wenyewe.'),
(2019157,69,46,6,20,'Mlinunuliwa kwa bei kubwa. Kwa hiyo, itumieni miili yenu kwa ajili ya kumtukuza Mungu.'),
(2019158,69,46,7,1,'Yahusu sasa mambo yale mliyoandika: naam, ni vizuri kama mtu haoi;'),
(2019159,69,46,7,2,'lakini kwa sababu ya hatari ya uzinzi, basi, kila mwanamume na awe na mke wake mwenyewe, na kila mwanamke awe na mume wake mwenyewe.'),
(2019160,69,46,7,3,'Mume atimize wajibu alio nao kwa mkewe, naye mke atimize wajibu alio nao kwa mumewe.'),
(2019161,69,46,7,4,'Mke hana mamlaka juu ya mwili wake, bali mumewe anayo; hali kadhalika naye mume, hana mamlaka juu ya mwili wake, bali mkewe anayo.'),
(2019162,69,46,7,5,'Msinyimane haki zenu, isipokuwa kama mnaafikiana kufanya hivyo kwa kitambo tu, ili mpate nafasi nzuri ya kusali. Kisha rudianeni tena mara, ili Shetani asije akawajaribu kwa sababu ya udhaifu wenu.'),
(2019163,69,46,7,6,'Ninayowaambieni sasa ni mawaidha, si amri.'),
(2019164,69,46,7,7,'Ningependa watu wote wawe kama mimi nilivyo; lakini kila mmoja anacho kipaji chake kutoka kwa Mungu; mmoja kipaji hiki na mwingine kile.'),
(2019165,69,46,7,8,'Basi, wale ambao hawajaoana na wale walio wajane nawaambia kwamba ni vema kuendelea kuwa kama mimi nilivyo.'),
(2019166,69,46,7,9,'Hata hivyo, kama mtu hawezi kujizuia basi, na aoe; maana ni afadhali zaidi kuoa kuliko kuwaka tamaa.'),
(2019167,69,46,7,10,'Kwa wale waliooa ninayo amri, tena si yangu, ila ni ya Bwana: mke asiachane na mumewe;'),
(2019168,69,46,7,11,'lakini kama akiachana naye, basi abaki bila kuolewa; ama la, apatanishwe na mume wake. Mume naye asimpe talaka mkewe.'),
(2019169,69,46,7,12,'Kwa wale wengine, (mimi binafsi, si Bwana) nasema hivi: Ikiwa mwanamume Mkristo anaye mke asiyeamini, na huyo mwanamke akakubali kuendelea kuishi naye, asimpe talaka.'),
(2019170,69,46,7,13,'Na, kama mwanamke Mkristo anaye mume asiyeamini, na huyo mwanamume akakubali kuendelea kuishi naye, basi, asimpe talaka mumewe.'),
(2019171,69,46,7,14,'Kwa maana huyo mume asiyeamini hupokelewa kwa Mungu kwa kuungana na mkewe; na huyo mke asiyeamini hupokelewa kwa Mungu kwa kuungana na mumewe. Vinginevyo watoto wao wangekuwa si wa Mungu; kumbe sasa ni watoto wake Mungu.'),
(2019172,69,46,7,15,'Hata hivyo, ikiwa yule asiyeamini anataka kumwacha mwenzake aliye Mkristo, basi, na amwache tu. Hapo huyo Mkristo, mume au mke, atakuwa huru. Maana Mungu amewaiteni ninyi muishi kwa amani.'),
(2019173,69,46,7,16,'Wewe mama Mkristo, unawezaje kuwa na hakika kwamba hutaweza kumwokoa mume wako? Au wewe mume Mkristo, unawezaje kuwa na hakika kwamba hutaweza kumwokoa mkeo?'),
(2019174,69,46,7,17,'Kwa vyovyote kila mmoja na aishi kufuatana na vipaji alivyogawiwa na Bwana, na kama alivyoitwa na Mungu. Hili ndilo agizo langu kwa makanisa yote.'),
(2019175,69,46,7,18,'Kama mtu aliitwa akiwa ametahiriwa, basi asijisingizie kwamba hakutahiriwa; na kama alipoitwa hakuwa ametahiriwa, basi na asitahiriwe.'),
(2019176,69,46,7,19,'Maana kutahiriwa au kutotahiriwa si kitu; kilicho muhimu ni kuzishika amri za Mungu.'),
(2019177,69,46,7,20,'Basi, kila mmoja na abaki kama alivyokuwa wakati alipoitwa.'),
(2019178,69,46,7,21,'Je, wewe ulikuwa mtumwa wakati ulipoitwa? Sawa, usijali; lakini ukipata fursa ya kuwa huru, itumie.'),
(2019179,69,46,7,22,'Maana yeye aliyeitwa na Bwana akiwa mtumwa huyo huwa mtu huru wa Bwana. Hali kadhalika naye aliyeitwa akiwa mtu huru, huwa mtumwa wa Kristo.'),
(2019180,69,46,7,23,'Nyote mmenunuliwa kwa bei; kwa hiyo msiwe tena watumwa wa watu.'),
(2019181,69,46,7,24,'Ndugu zangu, kila mmoja wenu basi, na abaki na Mungu kama alivyokuwa wakati alipoitwa.'),
(2019182,69,46,7,25,'Sasa, kuhusu mabikira na waseja, sina amri kutoka kwa Bwana; lakini natoa maoni yangu mimi ambaye kwa huruma yake Bwana nastahili kuaminiwa.'),
(2019183,69,46,7,26,'Basi, kutokana na shida iliyopo sasa nadhani ingefaa mtu abaki kama alivyo.'),
(2019184,69,46,7,27,'Je, umeoa? Basi, usitake kuachana na mkeo. Wewe hukuoa? Basi, usitake kuoa.'),
(2019185,69,46,7,28,'Lakini ikiwa utaoa hutakuwa umetenda dhambi; na msichana akiolewa hatakuwa ametenda dhambi. Hao watakaooana watapatwa na matatizo ya dunia hii, lakini mimi ningependa hayo yasiwapate ninyi.'),
(2019186,69,46,7,29,'Ndugu, nataka kusema hivi: muda uliobaki ni mfupi. Na tangu sasa wale waliooa na waishi kama vile hawakuoa;'),
(2019187,69,46,7,30,'wenye kulia wawe kama hawalii, na wenye kufurahi wawe kama hawafurahi; wanaonunua wawe kama hawana kitu;'),
(2019188,69,46,7,31,'nao wenye shughuli na dunia hii wawe kama vile hawana shughuli sana nayo. Maana ulimwengu huu, kama tuujuavyo, unapita.'),
(2019189,69,46,7,32,'Ningependa ninyi msiwe na wasiwasi. Mtu asiye na mke hujishughulisha na kazi ya Bwana jinsi atakavyompendeza Bwana.'),
(2019190,69,46,7,33,'Mtu aliyeoa hujishughulisha na mambo ya dunia jinsi atakavyompendeza mkewe,'),
(2019191,69,46,7,34,'naye amegawanyika. Mwanamke asiyeolewa au bikira hujishughulisha na mambo ya Bwana apate kujitolea mwili na roho kwa Bwana. Lakini mwanamke aliyeolewa hujishughulisha na mambo ya dunia hii jinsi atakavyompendeza mumewe.'),
(2019192,69,46,7,35,'Nawaambieni haya kwa faida yenu, na si kwa kuwawekeeni kizuio. Nataka tu muwe na mpango unaofaa, mpate kumtumikia Bwana kwa moyo na nia moja.'),
(2019193,69,46,7,36,'Kama mtu anaona kwamba hamtendei vyema mchumba wake asipomwoa, na kama tamaa zake zinamshinda, na afanye atakavyo; waoane tu; hatakuwa ametenda dhambi.'),
(2019194,69,46,7,37,'Lakini kama huyo mwanamume akiamua kwa hiari moyoni mwake kutooa na kama anaweza kuzitawala tamaa zake na kuamua namna ya kufanya, basi, anafanya vizuri zaidi asipomwoa huyo mwenzake bikira.'),
(2019195,69,46,7,38,'Kwa maneno mengine: yule anayeamua kumwoa huyo mchumba wake anafanya vema; naye anayeamua kutomwoa anafanya vema zaidi.'),
(2019196,69,46,7,39,'Mwanamke huwa amefungwa na mumewe kwa muda wote mumewe aishipo. Lakini mumewe akifa, mama huyo yuko huru, na akipenda anaweza kuolewa na mtu yeyote, mradi tu iwe Kikristo.'),
(2019197,69,46,7,40,'Lakini, nionavyo mimi, atakuwa na heri zaidi kama akibaki hivyo alivyo. Hayo ni maoni yangu, na nafikiri mimi pia ninaye Roho wa Mungu.'),
(2019198,69,46,8,1,'Yahusu sasa vyakula vilivyotambikiwa sanamu: Tunajua kwamba sisi sote tuna ujuzi, lakini ujuzi huo huwafanya watu wawe na majivuno; lakini mapendo hujenga.'),
(2019199,69,46,8,2,'Anayefikiri kwamba anajua kitu, kwa kweli hajui chochote kama inavyompasa.'),
(2019200,69,46,8,3,'Lakini anayempenda Mungu huyo anajulikana naye.'),
(2019201,69,46,8,4,'Kwa hiyo, kuhusu vyakula vilivyotambikiwa sanamu, twajua kwamba sanamu si kitu duniani; twajua kwamba Mungu ni mmoja tu.'),
(2019202,69,46,8,5,'Hata kama viko vitu viitwavyo miungu duniani au mbinguni, na hata kama wako miungu na mabwana wengi,'),
(2019203,69,46,8,6,'hata hivyo, kwetu sisi yuko Mungu mmoja tu: Baba, Muumba wa vyote, ambaye kwa ajili yake sisi tuko. Pia yuko Bwana mmoja tu, Yesu Kristo, ambaye kwa njia yake vitu vyote viliumbwa, na sisi twaishi kwa njia yake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019204,69,46,8,7,'Lakini, si kila mtu anao ujuzi huu. Maana wako watu wengine waliokwisha zoea sanamu, watu ambao mpaka hivi sasa wanapokula vyakula huviona bado kama vyakula vilivyotambikiwa sanamu. Na kwa vile dhamiri zao ni dhaifu, hutiwa unajisi.'),
(2019205,69,46,8,8,'Lakini chakula hakiwezi kutupeleka karibu zaidi na Mungu. Tukiacha kukila hatupungukiwi kitu, tukikila hatuongezewi kitu.'),
(2019206,69,46,8,9,'Lakini, jihadharini: huu uhuru wenu usiwafanye walio na imani dhaifu waanguke katika dhambi.'),
(2019207,69,46,8,10,'Maana, mtu ambaye dhamiri yake ni dhaifu, akikuona wewe mwenye ujuzi unakula vyakula hivyo ndani ya hekalu la sanamu, je, hatatiwa moyo wa kula vyakula vilivyotambikiwa sanamu?'),
(2019208,69,46,8,11,'Hivyo, huyo ndugu yako dhaifu ambaye Kristo alikufa kwa ajili yake, atapotea kwa sababu ya ujuzi wako.'),
(2019209,69,46,8,12,'Kama mkiwakosesha ndugu zenu jinsi hiyo na kuzijeruhi dhamiri zao dhaifu, mtakuwa mmemkosea Kristo.'),
(2019210,69,46,8,13,'Kwa hiyo, ikiwa chakula husababisha kuanguka kwa ndugu yangu, sitakula nyama kamwe, nisije nikamfanya ndugu yangu aanguke katika dhambi.'),
(2019211,69,46,9,1,'Je, mimi si mtu huru? Je, mimi si mtume? Je, mimi sikumwona Yesu Bwana wetu? Je, ninyi si matokeo ya kazi yangu kwa ajili ya Bwana?'),
(2019212,69,46,9,2,'Hata kama kwa watu wengine mimi si mtume, lakini walau kwenu ninyi mimi ni mtume. Ninyi ni uthibitisho wa mtume wangu kwa sababu ya kuungana kwenu na Bwana.'),
(2019213,69,46,9,3,'Hoja yangu kwa wale wanaonipinga ndiyo hii:'),
(2019214,69,46,9,4,'Je, hatuna haki ya kula na kunywa?'),
(2019215,69,46,9,5,'Je, hatuna ruhusa kumchukua mke Mkristo katika ziara zetu, kama vile wafanyavyo mitume wengine, ndugu zake Bwana, na pia Kefa?'),
(2019216,69,46,9,6,'Au ni mimi tu na Barnaba ambao tunapaswa kujipatia maslahi yetu kwa kufanya kazi?'),
(2019217,69,46,9,7,'Je, mwanajeshi gani anayelipia utumishi wake jeshini? Mkulima gani asiyekula matunda ya shamba lake la mizabibu? Mchungaji gani asiyekunywa maziwa ya mifugo yake?'),
(2019218,69,46,9,8,'Je, nasema mambo haya kibinadamu tu? Je, Sheria nayo haisemi hivyo?'),
(2019219,69,46,9,9,'Imeandikwa katika Sheria ya Mose: "Usimfunge kinywa ng`ombe anapoliwata nafaka." Je, ndio kusema Mungu anajishughulisha na ng`ombe?'),
(2019220,69,46,9,10,'Je, hakuwa anatufikiria sisi aliposema hivyo? Naam, haya yaliandikwa kwa ajili yetu; kwani yule anayelima na yule anayevuna, wote wawili wana haki ya kutumaini kupata sehemu ya mavuno.'),
(2019221,69,46,9,11,'Ikiwa sisi tumepanda mbegu ya kiroho kati yenu, je, ni jambo kubwa tukichuma kwenu faida ya kidunia?'),
(2019222,69,46,9,12,'Ikiwa wengine wanayo haki ya kutazamia hayo kutoka kwenu, je, sisi hatuna haki zaidi kuliko hao? Lakini, sisi hatukuitumia haki hiyo, Badala yake, tumestahimili kila kitu ili tusiiwekee kizuizi chochote Habari Njema ya Kristo.'),
(2019223,69,46,9,13,'Je, hamjui kwamba wanaotumikia Hekaluni hupata chakula chao Hekaluni, na kwamba wanaotolea sadaka madhabahuni hupata sehemu ya hiyo sadaka?'),
(2019224,69,46,9,14,'Bwana aliagiza vivyo hivyo; wahubiri wa Habari Njema wapate riziki zao kutokana nayo.'),
(2019225,69,46,9,15,'Lakini, mimi sikutumia hata mojawapo ya haki hizo. Na wala siandiki nijipatie haki hizo; kwangu mimi ni afadhali kufa kuliko kumfanya yeyote aone kwamba najisifu bure.'),
(2019226,69,46,9,16,'Ikiwa ninaihubiri Habari Njema, hilo si jambo la kujivunia; hilo ni jukumu nililopewa. Na, ole wangu kama sitaihubiri Habari Njema!'),
(2019227,69,46,9,17,'Ningekuwa nimeichagua kazi hii kwa hiari, basi, ningetazamia malipo; lakini maadam naifanya ikiwa ni wajibu, hiyo ina maana kwamba ni jukumu nililopewa nitekeleze.'),
(2019228,69,46,9,18,'Mshahara wangu ni kitu gani, basi? Mshahara wangu ni fursa ya kuihubiri Habari Njema bure, bila kudai haki ninazostahili kwa kuihubiri.'),
(2019229,69,46,9,19,'Kwa hiyo, ingawa mimi si mtumwa wa mtu yeyote, nimejifanya mtumwa wa kila mtu ili nimpatie Kristo watu wengi iwezekanavyo.'),
(2019230,69,46,9,20,'Kwa Wayahudi nimeishi kama Myahudi ili niwapate Wayahudi; yaani, ingawa mimi siko chini ya Sheria, nimejiweka chini ya Sheria kwao, ili niwapate hao walio chini ya Sheria.'),
(2019231,69,46,9,21,'Na kwa wale walio nje ya Sheria, naishi kama wao, nje ya Sheria, ili niwapate hao walio nje ya Sheria. Hii haimaanishi kwamba mimi niko nje ya sheria ya Mungu, maana nabanwa na sheria ya Kristo.'),
(2019232,69,46,9,22,'Kwao walio dhaifu nimejifanya dhaifu ili niwapate hao walio dhaifu. Nimejifanya kila kitu kwa wote ili nipate kuwaokoa baadhi yao kwa kila njia.'),
(2019233,69,46,9,23,'Nafanya haya yote kwa ajili ya Habari Njema, nipate kushiriki baraka zake.'),
(2019234,69,46,9,24,'Je, hamjui kwamba katika uwanja wa michezo, ingawa wapiga mbio wote hukimbia, ni mmoja tu anayejinyakulia zawadi?'),
(2019235,69,46,9,25,'Wanariadha hujipa mazoezi na nidhamu kali; hufanya hivyo ili wajipatie taji iharibikayo! Lakini sisi twafanya hivyo tupate taji ya kudumu daima.'),
(2019236,69,46,9,26,'Ndivyo basi, ninavyopiga mbio nikiwa na nia ya kushinda; ndivyo ninavyopigana, na si kama bondia anayetupa ngumi zake hewani.'),
(2019237,69,46,9,27,'Naupa mwili wangu mazoezi magumu na kuutia katika nidhamu kamili, nisije mimi mwenyewe nikakataliwa baada ya kuwahubiria wengine. ic'),
(2019238,69,46,10,1,'Ndugu, nataka mjue kwamba babu zetu wote walikuwa chini ya ulinzi wa lile wingu, na kwamba wote walivuka salama ile bahari.'),
(2019239,69,46,10,2,'Wote walibatizwa katika umoja na Mose kwa lile wingu na ile bahari.'),
(2019240,69,46,10,3,'Wote walikula chakula kilekile cha kiroho,'),
(2019241,69,46,10,4,'wakanywa pia kinywaji kilekile cha kiroho, maana walikunywa kutoka ule mwamba wa kiroho uliowafuata; mwamba huo ulikuwa Kristo mwenyewe.'),
(2019242,69,46,10,5,'Hata hivyo, wengi wao hawakumpendeza Mungu, na maiti zao zilisambazwa jangwani.'),
(2019243,69,46,10,6,'Sasa, mambo hayo yote ni mfano tu kwetu; yanatuonya sisi tusitamani ubaya kama wao walivyotamani.'),
(2019244,69,46,10,7,'Msiwe waabudu sanamu kama baadhi yao walivyokuwa; kama yasemavyo Maandiko: "Watu waliketi kula na kunywa, wakasimama kucheza."'),
(2019245,69,46,10,8,'Wala tusizini kama baadhi yao walivyozini, wakaangamia siku moja watu ishirini na tatu elfu.'),
(2019246,69,46,10,9,'Tusimjaribu Bwana kama baadhi yao walivyomjaribu, wakauawa na nyoka.'),
(2019247,69,46,10,10,'Wala msinung`unike kama baadhi yao walivyonung`unika, wakaangamizwa na Mwangamizi!'),
(2019248,69,46,10,11,'Basi, mambo hayo yaliyowapata wao ni kielelezo kwa wengine, na yaliandikwa ili kutuonya sisi, ambao mwisho wa nyakati unatukabili.'),
(2019249,69,46,10,12,'Anayedhani amesimama imara ajihadhari asianguke.'),
(2019250,69,46,10,13,'Majaribu mliyokwisha pata ni ya kawaida kwa binadamu. Mungu ni mwaminifu, naye hataruhusu mjaribiwe kupita nguvu zenu, ila pamoja na majaribu, yeye atawapeni pia nguvu ya kustahimili na njia ya kutoka humo salama.'),
(2019251,69,46,10,14,'Kwa hiyo, wapenzi wangu, epeni ibada za sanamu.'),
(2019252,69,46,10,15,'Naongea nanyi, watu wenye busara; jiamulieni wenyewe hayo nisemayo.'),
(2019253,69,46,10,16,'Tunapomshukuru Mungu kwa kikombe kile cha baraka, je, huwa hatushiriki damu ya Kristo? Na tunapoumega mkate, je, huwa hatushiriki mwili wa Kristo?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019254,69,46,10,17,'Kwa kuwa mkate huo ni mmoja, sisi, ingawa ni wengi, tu mwili mmoja; maana sote twashiriki mkate huohuo.'),
(2019255,69,46,10,18,'Chukueni, kwa mfano, Wayahudi wenyewe: kwao, wenye kula vilivyotambikiwa madhabahuni waliungana na hiyo madhabahu.'),
(2019256,69,46,10,19,'Nataka kusema nini, basi? Kwamba chakula kilichotambikiwa sanamu ni kitu zaidi ya chakula? Na hizo sanamu, je, ni kitu kweli zaidi ya sanamu?'),
(2019257,69,46,10,20,'Hata kidogo! Ninachosema ni kwamba tambiko wanazotoa watu wasiomjua Mungu wanawatolea pepo, sio Mungu. Sipendi kamwe ninyi muwe na ushirika na pepo.'),
(2019258,69,46,10,21,'Hamwezi kunywa kikombe cha Bwana na kikombe cha pepo; hamwezi kushiriki katika meza ya Bwana na katika meza ya pepo.'),
(2019259,69,46,10,22,'Au je, tunataka kumfanya Bwana awe na wivu? Mnadhani tuna nguvu zaidi kuliko yeye?'),
(2019260,69,46,10,23,'Vitu vyote ni halali, lakini si vyote vinafaa. Vitu vyote ni halali lakini si vyote vinajenga.'),
(2019261,69,46,10,24,'Mtu asitafute faida yake mwenyewe, ila faida ya mwenzake.'),
(2019262,69,46,10,25,'Kuleni chochote kile kiuzwacho sokoni bila ya kuulizauliza kwa sababu ya dhamiri zenu;'),
(2019263,69,46,10,26,'maana Maandiko yasema: "Dunia na vyote vilivyomo ni mali ya Bwana."'),
(2019264,69,46,10,27,'Kama mtu ambaye si muumini akiwaalikeni nanyi mkakubali kwenda, basi, kuleni vyote atakavyowaandalieni bila kuulizauliza kwa sababu ya dhamiri zenu.'),
(2019265,69,46,10,28,'Lakini mtu akiwaambieni: "Chakula hiki kimetambikiwa sanamu," basi, kwa ajili ya huyo aliyewaambieni hivyo na kwa ajili ya dhamiri, msile.'),
(2019266,69,46,10,29,'Nasema, "kwa ajili ya dhamiri," si dhamiri yenu, bali dhamiri yake huyo aliyewaambieni. Mtaniuliza: "Kwa nini uhuru wangu utegemee dhamiri ya mtu mwingine?'),
(2019267,69,46,10,30,'Ikiwa mimi nashiriki chakula hicho huku namshukuru Mungu, kwa nini nilaumiwe kwa chakula ambacho kwa ajili yake nimemshukuru Mungu?"'),
(2019268,69,46,10,31,'Basi, chochote mfanyacho iwe ni kula au kunywa, fanyeni yote kwa ajili ya utukufu wa Mungu.'),
(2019269,69,46,10,32,'Msiwe kikwazo kwa Wayahudi au kwa Wagiriki au kwa kanisa la Mungu.'),
(2019270,69,46,10,33,'Muwe kama mimi; najaribu kuwapendeza wote kwa kila njia, bila kutafuta faida yangu mwenyewe ila faida ya wote, wapate kuokolewa.'),
(2019271,69,46,11,1,'Niigeni mimi kama ninavyomwiga Kristo.'),
(2019272,69,46,11,2,'Nawapeni hongera kwa sababu mnanikumbuka na kwa sababu mnayashikilia yale maagizo niliyowapeni.'),
(2019273,69,46,11,3,'Lakini napenda pia mjue kwamba Kristo ni kichwa cha kila mwanamume, na mwanamume ni kichwa cha mkewe, na Mungu ni kichwa cha Kristo.'),
(2019274,69,46,11,4,'Basi, kila mwanamume anayesali au anayetangaza ujumbe wa Mungu huku amefunika kichwa chake, huyo anamdharau Kristo.'),
(2019275,69,46,11,5,'Na mwanamke akisali au kutangaza ujumbe wa Mungu bila kufunika kichwa chake, anamdharau mumewe; anayefanya hivyo ni sawa tu na mwanamke aliyenyoa kichwa chake.'),
(2019276,69,46,11,6,'Mwanamke asiyefunika kichwa chake, afadhali anyoe nywele zake. Lakini ni aibu kwa mwanamke kukatwa nywele zake au kunyolewa; basi, afadhali afunike kichwa chake.'),
(2019277,69,46,11,7,'Haifai mwanamume kufunika kichwa chake, kwa kuwa yeye ni mfano wa Mungu na kioo cha utukufu wake Mungu; lakini mwanamke ni kioo cha utukufu wa mwanamume.'),
(2019278,69,46,11,8,'Mwanamume hakutoka kwa mwanamke, ila mwanamke alitoka kwa mwanamume.'),
(2019279,69,46,11,9,'Mwanamume hakuumbwa kwa ajili ya mwanamke, ila mwanamke aliumbwa kwa ajili ya mwanamume.'),
(2019280,69,46,11,10,'Ndiyo maana mwanamke hufunika kichwa chake, iwe ishara ya mamlaka yaliyo juu yake, na pia kwa sababu ya malaika.'),
(2019281,69,46,11,11,'Hata hivyo, mbele ya Bwana mwanamke si kitu bila mwanamume, naye mwanamume si kitu bila mwanamke.'),
(2019282,69,46,11,12,'Kama vile mwanamke alivyotokana na mwanamume, vivyo hivyo mwanamume huzaliwa na mwanamke; kila kitu hutoka kwa Mungu.'),
(2019283,69,46,11,13,'Amueni wenyewe: Je, inafaa mwanamke kumwomba Mungu bila kuvaa kitu kichwani?'),
(2019284,69,46,11,14,'Hata maumbile yenyewe huonyesha wazi kwamba kwa mwanamume kuwa na nywele ndefu ni aibu kwake mwenyewe;'),
(2019285,69,46,11,15,'lakini kwa mwanamke kuwa na nywele ni heshima kwake; nywele zake ndefu amepewa ili zimfunike.'),
(2019286,69,46,11,16,'Kama mtu anataka kuleta ubishi juu ya jambo hili, basi, na ajue kwamba sisi hatuna desturi nyingine, wala makanisa ya Mungu hayana desturi nyingine.'),
(2019287,69,46,11,17,'Nikiwa bado nawapeni maagizo haya, siwezi hata kidogo kuwapa ninyi hongera kuhusu haya yafuatayo: mikutano yenu ninyi waumini yaleta hasara zaidi kuliko faida.'),
(2019288,69,46,11,18,'Awali ya yote, nasikia kwamba mnapokutana pamoja hutokea mafarakano kati yenu. Nami naamini kiasi,'),
(2019289,69,46,11,19,'maana ni lazima fikira tofauti ziweko miongoni mwenu, ili wale walio thabiti wapate kutambulikana.'),
(2019290,69,46,11,20,'Kweli mnakutana, lakini si kwa ajili ya kula chakula cha Bwana!'),
(2019291,69,46,11,21,'Maana mnapokula kila mmoja hukikalia chakula chake mwenyewe, hata hutokea kwamba baadhi yenu wana njaa, na wengine wamelewa!'),
(2019292,69,46,11,22,'Je, hamwezi kula na kunywa nyumbani kwenu! Au je, mnalidharau kanisa la Mungu na kuwaaibisha hao wasio na kitu? Niwaambie nini? Niwasifu? La hasha! Si kuhusu jambo hili.'),
(2019293,69,46,11,23,'Maana mimi nilipokea kwa Bwana yale maagizo niliyowaachieni: kwamba, usiku ule Bwana Yesu aliotolewa, alitwaa mkate,'),
(2019294,69,46,11,24,'akamshukuru Mungu, akaumega, akasema: "Huu ndio mwili wangu ulio kwa ajili yenu; fanyeni hivi kwa kunikumbuka."'),
(2019295,69,46,11,25,'Vivyo hivyo, baada ya kula, akatwaa kikombe akasema: "Hiki ni kikombe cha agano jipya linalothibitishwa kwa damu yangu. Fanyeni hivi, kila mnapokunywa, kwa kunikumbuka."'),
(2019296,69,46,11,26,'Maana kila mnapokula mkate huu na kunywa kikombe hiki, mwatangaza kifo cha Bwana, mpaka atakapokuja.'),
(2019297,69,46,11,27,'Kwa hiyo, kila aulaye mkate huo au kunywa kikombe cha Bwana bila kustahili, atakuwa na hatia dhidi ya mwili na damu ya Bwana.'),
(2019298,69,46,11,28,'Basi, kila mtu ajichunguze mwenyewe kwanza, ndipo ale mkate huo na anywe kikombe hicho;'),
(2019299,69,46,11,29,'maana anayekula na kunywa bila kutambua maana ya mwili wa Bwana, anakula na kunywa hukumu yake yeye mwenyewe.'),
(2019300,69,46,11,30,'Ndiyo maana wengi kati yenu ni dhaifu na wagonjwa, na wengine kadhaa wamekufa.'),
(2019301,69,46,11,31,'Kama tungejichunguza wenyewe vizuri hatungeadhibiwa hivyo.'),
(2019302,69,46,11,32,'Lakini tunapohukumiwa na Bwana, tunafunzwa tuwe na nidhamu, ili tusije tukahukumiwa pamoja na ulimwengu.'),
(2019303,69,46,11,33,'Kwa hiyo, ndugu zangu, mnapokutana kula chakula cha Bwana, kila mmoja amngoje mwenzake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019304,69,46,11,34,'Na kama kuna yeyote aliye na njaa, na ale nyumbani kwake, ili kukutana kwenu kusisababishe hukumu. Lakini, kuhusu yale mambo mengine, nitawapeni maelezo nitakapokuja.'),
(2019305,69,46,12,1,'Ndugu, kuhusu vipaji vya kiroho, napenda mfahamu vizuri mambo haya:'),
(2019306,69,46,12,2,'Mnajua kwamba, kabla ya kuongoka kwenu, mlitawaliwa na kupotoshwa na sanamu tupu.'),
(2019307,69,46,12,3,'Basi, jueni kwamba mtu yeyote anayeongozwa na Roho wa Mungu hawezi kusema: "Yesu alaaniwe!" Hali kadhalika, mtu yeyote hawezi kusema: "Yesu ni Bwana," asipoongozwa na Roho Mtakatifu.'),
(2019308,69,46,12,4,'Vipaji vya kiroho ni vya namna nyingi, lakini Roho avitoaye ni mmoja.'),
(2019309,69,46,12,5,'Kuna namna nyingi za kutumikia, lakini Bwana anayetumikiwa ni mmoja.'),
(2019310,69,46,12,6,'Kuna namna mbalimbali za kufanya kazi ya huduma, lakini Mungu ni mmoja, anayewezesha kazi zote katika wote.'),
(2019311,69,46,12,7,'Kila mtu hupewa mwangaza wa Roho kwa faida ya wote.'),
(2019312,69,46,12,8,'Roho humpa mmoja ujumbe wa hekima, na mwingine ujumbe wa elimu apendavyo Roho huyohuyo.'),
(2019313,69,46,12,9,'Roho huyohuyo humpa mmoja imani, na humpa mwingine kipaji cha kuponya;'),
(2019314,69,46,12,10,'humpa mmoja kipaji cha kufanya miujiza, mwingine kipaji cha kusema ujumbe wa Mungu, mwingine kipaji cha kubainisha vipaji vitokavyo kwa Roho na visivyo vya Roho; humpa mmoja kipaji cha kusema lugha ngeni, na mwingine kipaji cha kuzifafanua.'),
(2019315,69,46,12,11,'Hizo zote ni kazi za Roho huyohuyo mmoja, ambaye humpa kila mtu kipaji tofauti, kama apendavyo mwenyewe.'),
(2019316,69,46,12,12,'Kama vile mwili ulivyo mmoja wenye viungo vingi, na viungo hivyo vyote--ingawaje ni vingi--hufanya mwili mmoja, ndivyo ilivyo pia kwa Kristo.'),
(2019317,69,46,12,13,'Maana sisi, tukiwa Wayahudi au watu wa mataifa mengine, watumwa au watu huru, sote tumebatizwa kwa Roho mmoja katika mwili huo mmoja; na sote tukanyweshwa Roho huyo mmoja.'),
(2019318,69,46,12,14,'Mwili hauna kiungo kimoja tu, bali una viungo vingi.'),
(2019319,69,46,12,15,'Kama mguu ungejisemea: "Kwa kuwa mimi si mkono, basi mimi si mali ya mwili", je, ungekoma kuwa sehemu ya mwili? La hasha!'),
(2019320,69,46,12,16,'Kama sikio lingejisemea: "Kwa vile mimi si jicho, basi mimi si mali ya mwili", je, kwa hoja hiyo lingekoma kuwa sehemu ya mwili? La!'),
(2019321,69,46,12,17,'Kama mwili wote ungekuwa jicho, sikio lingekuwa wapi? Na kama mwili wote ungekuwa sikio, mtu angewezaje kunusa?'),
(2019322,69,46,12,18,'Lakini kama ilivyo, Mungu alizipanga sehemu hizo tofauti katika mwili kama alivyopenda.'),
(2019323,69,46,12,19,'Kama sehemu zote zingekuwa kiungo kimoja, mwili ungekuwa wapi?'),
(2019324,69,46,12,20,'Ukweli ni kwamba, sehemu za mwili ni nyingi, lakini mwili ni mmoja.'),
(2019325,69,46,12,21,'Basi, jicho haliwezi kuuambia mkono: "Sikuhitaji wewe", wala kichwa hakiwezi kuiambia miguu: "Siwahitaji ninyi."'),
(2019326,69,46,12,22,'Zaidi ya hayo, inaonekana kwamba sehemu zile za mwili zinazoonekana kuwa ni dhaifu ndizo zilizo muhimu zaidi.'),
(2019327,69,46,12,23,'Tena, viungo vile tunavyovifikiria kuwa havistahili heshima kubwa, ndivyo tunavyovitunza kwa uangalifu zaidi; viungo vya mwili ambavyo havionekani kuwa vizuri sana, huhifadhiwa zaidi,'),
(2019328,69,46,12,24,'ambapo viungo vingine havihitaji kushughulikiwa. Mungu mwenyewe ameuweka mwili katika mpango, akakipa heshima zaidi kiungo kile kilichopungukiwa heshima,'),
(2019329,69,46,12,25,'ili kusiweko na utengano katika mwili bali viungo vyote vishughulikiane.'),
(2019330,69,46,12,26,'Kama kiungo kimoja kinaumia viungo vyote huumia pamoja nacho. Kiungo kimoja kikisifiwa viungo vingine vyote hufurahi pamoja nacho.'),
(2019331,69,46,12,27,'Basi, ninyi nyote ni mwili wa Kristo; kila mmoja wenu ni kiungo cha mwili huo.'),
(2019332,69,46,12,28,'Mungu ameweka katika kanisa: kwanza mitume, pili manabii, tatu walimu; kisha ameweka wale wenye kipaji cha kufanya miujiza, kuponya, kusaidia; viongozi na wenye kusema lugha ngeni.'),
(2019333,69,46,12,29,'Je, wote ni mitume? Wote ni manabii? Wote ni walimu? Wote ni wenye kipaji cha kufanya miujiza?'),
(2019334,69,46,12,30,'Je, wote ni wenye kipaji cha kuponya? Wote ni wenye kipaji cha kusema lugha ngeni? Je, wote hufafanua lugha?'),
(2019335,69,46,12,31,'Muwe basi, na tamaa ya kupata vipaji muhimu zaidi. Nami sasa nitawaonyesheni njia bora zaidi kuliko hizi zote.'),
(2019336,69,46,13,1,'Hata kama nikinena lugha za watu na hata za malaika, lakini kama sina upendo mimi nimekuwa tu kama sauti ya debe tupu au kengele.'),
(2019337,69,46,13,2,'Tena, naweza kuwa na kipaji cha kutangaza ujumbe wa Mungu, nikafahamu siri zote na kujua kila kitu; naweza kuwa na imani yote hata nikaweza kuihamisha milima, lakini kama sina upendo mimi si kitu.'),
(2019338,69,46,13,3,'Nikitoa mali yangu yote na kuwapa maskini, na tena nikiutoa mwili wangu uchomwe, kama sina upendo hiyo hainifai chochote.'),
(2019339,69,46,13,4,'Mwenye upendo huvumilia, hufadhili; mwenye upendo hana wivu, hajidai, wala hajivuni.'),
(2019340,69,46,13,5,'Mwenye upendo hakosi adabu, hatafuti faida yake binafsi, wala hana wepesi wa hasira; haweki kumbukumbu ya mabaya,'),
(2019341,69,46,13,6,'hafurahii uovu, bali hufurahia ukweli.'),
(2019342,69,46,13,7,'Mwenye upendo huvumilia yote, huamini yote, na hustahimili yote.'),
(2019343,69,46,13,8,'Upendo hauna kikomo kamwe. Kama kuna vipaji vya kutangaza ujumbe wa Mungu, hivyo vitatoweka siku moja; kama ni vipaji vya kusema lugha ngeni, vitakoma; kama kuna elimu, nayo itapita.'),
(2019344,69,46,13,9,'Maana ujuzi wetu si kamili, na kipaji chetu cha kutangaza neno la Mungu si kamili.'),
(2019345,69,46,13,10,'Lakini kile kilicho kikamilifu kitakapofika, vyote visivyo vikamilifu vitatoweka.'),
(2019346,69,46,13,11,'Nilipokuwa mtoto mchanga nilisema kitoto, nilifahamu kitoto, nilifikiri kitoto. Lakini sasa, maadam mimi ni mtu mzima, mambo ya kitoto nimeyaacha.'),
(2019347,69,46,13,12,'Tunachoona sasa ni kama tu sura hafifu katika kioo, lakini hapo baadaye tutaona uso kwa uso. Sasa ninajua kiasi fulani tu, lakini hapo baadaye nitajua yote kikamilifu, kama vile Mungu anavyonijua mimi.'),
(2019348,69,46,13,13,'Sasa yanadumu haya matatu: imani, tumaini na upendo; lakini lililo kuu kupita yote ni upendo.'),
(2019349,69,46,14,1,'Jitahidini kuwa na upendo. Vilevile fanyeni bidii ya kupata vipaji vingine vya kiroho, hasa kipaji cha kutangaza ujumbe wa Mungu.'),
(2019350,69,46,14,2,'Mwenye kunena lugha ngeni hasemi na watu bali anasema na Mungu. Yeye hunena kwa nguvu ya Roho mambo yaliyofichika.'),
(2019351,69,46,14,3,'Lakini mwenye kipaji cha kutangaza ujumbe wa Mungu, husema na watu kwa ajili ya kuwajenga, kuwafariji na kuwatia moyo.'),
(2019352,69,46,14,4,'Mwenye kunena lugha ngeni anajijenga mwenyewe. Lakini mwenye kipaji cha kutangaza ujumbe wa Mungu, analijenga kanisa.'),
(2019353,69,46,14,5,'Basi, ningependa ninyi nyote mseme kwa lugha ngeni lakini ningependelea hasa muwe na kipaji cha kutangaza ujumbe wa Mungu, maana mtu mwenye kipaji cha kutangaza ujumbe wa Mungu, ni wa maana zaidi kuliko yule mwenye kusema lugha ngeni, isipokuwa tu kama yupo hapo mtu awezaye kuyafafanua hayo mambo asemayo, ili kanisa lipate kujengwa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019354,69,46,14,6,'Hivyo, ndugu zangu, kama nikija kwenu na kusema nanyi kwa lugha ngeni itawafaa nini? Haitawafaa chochote, isipokuwa tu kama nitawaelezeni ufunuo wa Mungu au ujuzi fulani au ujumbe wa Mungu au mafundisho fulani.'),
(2019355,69,46,14,7,'Ndivyo ilivyo kwa vyombo visivyo na uhai vyenye kutoa sauti kama vile filimbi au kinanda. Je, mtu anawezaje kuutambua wimbo unaochezwa kama vyombo hivyo havitoi sauti waziwazi vinapopigwa?'),
(2019356,69,46,14,8,'La mgambo likilia bila kufuata taratibu zake, nani atajiweka tayari kwa vita?'),
(2019357,69,46,14,9,'Hali kadhalika na ninyi, kama ulimi wenu hausemi kitu chenye kueleweka, nani ataweza kufahamu mnayosema? Maneno yenu yatapotea hewani.'),
(2019358,69,46,14,10,'Zipo lugha mbalimbali ulimwenguni, na hakuna hata mojawapo isiyo na maana.'),
(2019359,69,46,14,11,'Lakini ikiwa mimi sifahamu maana ya lugha asemayo mtu fulani, mimi ni mgeni kwake mtu huyo naye pia ni mgeni kwangu.'),
(2019360,69,46,14,12,'Hali kadhalika na ninyi, maadam mna hamu ya kupata vipaji vya Roho, jitahidini hasa kujipatia vile vinavyosaidia kulijenga kanisa.'),
(2019361,69,46,14,13,'Kwa hiyo, mwenye kunena lugha ngeni na aombe apate uwezo wa kuzifafanua.'),
(2019362,69,46,14,14,'Maana, nikisali kwa lugha ngeni roho yangu ndiyo inayosali, lakini akili yangu hubaki bure.'),
(2019363,69,46,14,15,'Nifanye nini, basi? Nitasali kwa roho yangu, nitasali pia kwa akili yangu; nitaimba kwa roho yangu, nitaimba pia kwa akili yangu.'),
(2019364,69,46,14,16,'Ukimsifu Mungu kwa roho yako tu, atawezaje mtu wa kawaida aliye katika mkutano kuitikia sala yako ya shukrani kwa kusema: "Amina," kama haelewi unachosema?'),
(2019365,69,46,14,17,'Sala yako ya shukrani yaweza kweli kuwa bora, lakini huyo mwingine haitamfaidia.'),
(2019366,69,46,14,18,'Namshukuru Mungu kwamba mimi nasema kwa lugha ngeni zaidi kuliko ninyi nyote.'),
(2019367,69,46,14,19,'Lakini katika mikutano ya waumini napendelea zaidi kusema maneno matano yenye kueleweka ili niwafundishe wengine, kuliko kusema maneno elfu ya lugha ngeni.'),
(2019368,69,46,14,20,'Ndugu, msiwe kama watoto katika fikira zenu. Kuhusu uovu muwe kama watoto wachanga lakini katika kufikiri ni lazima muwe kama watu waliokomaa.'),
(2019369,69,46,14,21,'Imeandikwa katika Sheria: "Bwana asema hivi: `Kwa njia ya wenye kunena lugha ngeni, na kwa midomo ya wageni, nitasema na watu hawa, hata hivyo, hawatanisikiliza."`'),
(2019370,69,46,14,22,'Hivyo basi, kipaji cha kusema lugha ngeni ni ishara, si kwa ajili ya watu wenye imani, bali kwa ajili ya wale wasioamini; lakini kipaji cha kutangaza ujumbe wa Mungu ni kwa ajili ya wale wanaoamini na si kwa ajili ya wasioamini.'),
(2019371,69,46,14,23,'Basi, kanisa lote linapokutana pamoja, na wote wakaanza kusema kwa lugha ngeni, kama wakija watu wa kawaida au wasioamini, je, hawatasema kwamba ninyi mna wazimu?'),
(2019372,69,46,14,24,'Lakini, wote wakiwa wanautangaza ujumbe wa Mungu, akija mtu wa kawaida au asiyeamini, yote atakayosikia yatamhakikishia ubaya wake mwenyewe; yote atakayosikia yatamhukumu.'),
(2019373,69,46,14,25,'Siri za moyo wake zitafichuliwa, naye atapiga magoti na kumwabudu Mungu akisema: "Kweli Mungu yupo pamoja nanyi."'),
(2019374,69,46,14,26,'Ndugu, tuseme nini, basi? Mnapokutana pamoja, mmoja aimbe wimbo, mwingine atoe mafundisho, mwingine awe na ufunuo kutoka kwa Mungu, mwingine atumie kipaji cha kusema kwa lugha ngeni na mwingine afafanue yanayosemwa. Yote yawe kwa ajili ya kulijenga kanisa.'),
(2019375,69,46,14,27,'Wakiwepo watu wenye vipaji vya kusema kwa lugha ngeni, waseme wawili au watatu, si zaidi, tena mmojammoja; na aweko mtu wa kufafanua yanayosemwa.'),
(2019376,69,46,14,28,'Lakini kama hakuna awezaye kufafanua, basi, mwenye kusema lugha ngeni anyamaze mkutanoni, aseme na nafsi yake mwenyewe na Mungu.'),
(2019377,69,46,14,29,'Kuhusu wale wenye kipaji cha kutangaza ujumbe wa Mungu, waseme wawili au watatu, na wengine wayapime maneno yao.'),
(2019378,69,46,14,30,'Ikiwa mmoja anaposema mwingine wa wasikilizaji amepata ufunuo kutoka kwa Mungu, basi, yule anayesema anyamaze.'),
(2019379,69,46,14,31,'Maana nyote mwaweza kutangaza ujumbe wa Mungu, mmoja baada ya mwingine, ili nyote mpate kujifunza na kutiwa moyo.'),
(2019380,69,46,14,32,'Kipaji cha kutangaza ujumbe wa Mungu ni lazima kitawaliwe na huyo mwenye hicho kipaji.'),
(2019381,69,46,14,33,'Maana Mungu si Mungu wa fujo, ila wa amani.'),
(2019382,69,46,14,34,'Kama ilivyo desturi katika makanisa yote ya watu wa Mungu, wanawake wakae kimya katika mikutano ya waumini. Hawana ruhusa kusema; ila wawe watii kama isemavyo Sheria.'),
(2019383,69,46,14,35,'Ikiwa wanayo maswali ya kuuliza, wawaulize waume zao nyumbani, maana ni aibu kwa mwanamke kusema katika mikutano ya waumini.'),
(2019384,69,46,14,36,'Je, mnadhani neno la Mungu limetoka kwenu ninyi au kwamba limewajieni ninyi peke yenu?'),
(2019385,69,46,14,37,'Kama mtu yeyote anadhani kwamba yeye ni mjumbe wa Mungu au kwamba anacho kipaji cha Roho, na ajue kwamba haya ninayowaandikia ninyi ni amri ya Bwana.'),
(2019386,69,46,14,38,'Lakini mtu asiyetambua hayo, basi, mtu asimjali mtu huyo.'),
(2019387,69,46,14,39,'Hivyo basi, ndugu zangu, mnapaswa kuwa na hamu ya kutangaza ujumbe wa Mungu; lakini msimkataze mtu kusema kwa lugha ngeni.'),
(2019388,69,46,14,40,'Lakini yote yafanyike kwa heshima na kwa utaratibu.'),
(2019389,69,46,15,1,'Sasa ndugu, napenda kuwakumbusha ile Habari Njema niliyowahubirieni nanyi mkaipokea na kusimama imara ndani yake.'),
(2019390,69,46,15,2,'Kwa njia yake mnaokolewa, ikiwa mnayazingatia maneno niliyowahubirieni, na kama kuamini kwenu hakukuwa bure.'),
(2019391,69,46,15,3,'Mimi niliwakabidhi ninyi mambo muhimu sana ambayo mimi niliyapokea: kwamba Kristo alikufa kwa ajili ya dhambi zetu kufuatana na Maandiko Matakatifu;'),
(2019392,69,46,15,4,'kwamba alizikwa, akafufuka siku ya tatu kama ilivyoandikwa;'),
(2019393,69,46,15,5,'kwamba alimtokea Kefa, na baadaye aliwatokea wale kumi na wawili.'),
(2019394,69,46,15,6,'Kisha aliwatokea ndugu zaidi ya mia tano kwa mara moja; wengi wao wanaishi bado, lakini baadhi yao wamekwisha kufa.'),
(2019395,69,46,15,7,'Baadaye alimtokea Yakobo kisha akawatokea mitume wote.'),
(2019396,69,46,15,8,'Baada ya wote, akanitokea hata mimi, mimi niliyekuwa kama mtu aliyezaliwa kabla ya wakati.'),
(2019397,69,46,15,9,'Maana mimi ni mdogo kabisa miongoni mwa mitume na wala sistahili kuitwa mtume, kwa sababu nililidhulumu kanisa la Mungu.'),
(2019398,69,46,15,10,'Lakini, kwa neema yake Mungu, nimekuwa kama nilivyo. Na neema yake kwangu haikuwa bure. Mimi nimefanya kazi kuliko wote; si mimi hasa, ila ni neema ya Mungu ifanyayo kazi pamoja nami.'),
(2019399,69,46,15,11,'Lakini hata hivyo, iwe wao ndio wahubirio au mimi nihubiriye, haidhuru, hiki ndicho tunachuhubiri, na hiki ndicho mnachoamini.'),
(2019400,69,46,15,12,'Sasa, maadam inahubiriwa kwamba Kristo amefufuliwa kutoka wafu, baadhi yenu wanawezaje kusema kwamba hakuna ufufuo wa wafu?'),
(2019401,69,46,15,13,'Kama hakuna ufufuo wa wafu, basi, Kristo naye hakufufuka;'),
(2019402,69,46,15,14,'na kama Kristo hakufufuka, basi mahubiri yetu hayana maana na imani yenu haina maana.'),
(2019403,69,46,15,15,'Zaidi ya hayo sisi tungekuwa mashahidi wa uongo mbele ya Mungu, maana tulisema kwamba Mungu alimfufua Kristo kutoka wafu na kumbe yeye hakumfufua--kama ni kweli kwamba wafu hawafufuliwi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019404,69,46,15,16,'Maana, ikiwa ni kweli kwamba wafu hawafufuki, basi naye Kristo hakufufuka.'),
(2019405,69,46,15,17,'Na kama Kristo hakufufuliwa, basi, imani yenu ni ya bure; mngali bado katika dhambi zenu.'),
(2019406,69,46,15,18,'Zaidi ya hayo, wale wote waliokufa wakiwa wameungana na Kristo wamepotea kabisa.'),
(2019407,69,46,15,19,'Kama matumaini yetu katika Kristo yanahusu tu maisha haya ya sasa, basi, sisi ni watu wa kusikitikiwa zaidi kuliko wengine wote duniani.'),
(2019408,69,46,15,20,'Lakini ukweli ni kwamba Kristo amefufuliwa kutoka wafu, limbuko lao wale waliolala katika kifo.'),
(2019409,69,46,15,21,'Maana kama vile kifo kilivyoletwa duniani na mtu mmoja, vivyo hivyo nako kufufuka kutoka wafu kumesababishwa na mtu mmoja.'),
(2019410,69,46,15,22,'Kama vile watu wote wanavyokufa kwa kujiunga na Adamu, vivyo hivyo wote watafufuliwa kwa kuungana na Kristo.'),
(2019411,69,46,15,23,'Lakini kila mmoja kwa mpango wake: Kristo kwanza, halafu wale walio wake Kristo wakati Kristo atakapokuja.'),
(2019412,69,46,15,24,'Baada ya hayo, mwisho utafika wakati ambapo Kristo atamkabidhi Mungu Baba Utawala, baada ya kufutilia mbali kila tawala na mamlaka na nguvu.'),
(2019413,69,46,15,25,'Maana Kristo sharti atawale mpaka Mungu atakapowashinda adui zake na kuwaweka chini ya miguu yake.'),
(2019414,69,46,15,26,'Adui wa mwisho atakayeangamizwa ni kifo.'),
(2019415,69,46,15,27,'Maana, Maandiko yasema: "Mungu ameweka vitu vyote chini ya miguu yake." Lakini, Maandiko yanaposema: "Vitu vyote vimewekwa chini ya miguu yake avitawale" ni dhahiri kwamba Mungu haingii katika kundi hilo la vitu, maana yeye ndiye anayeviweka vitu hivyo chini ya Kristo.'),
(2019416,69,46,15,28,'Lakini vitu vyote vitakapowekwa chini ya Utawala wa Kristo, ndipo naye Mwana atakapojiweka chini ya Mungu, aliyeweka vyote chini ya Utawala wake; ili Mungu atawale juu ya vyote.'),
(2019417,69,46,15,29,'Kama hakuna ufufuo, je watu wale wanaobatizwa kwa ajili ya wafu wanatumainia kupata nini? Kama wafu hawafufuliwi, ya nini kubatizwa kwa ajili yao?'),
(2019418,69,46,15,30,'Na sisi, ya nini kujitia hatarini kila saa?'),
(2019419,69,46,15,31,'Ndugu, mimi nakikabili kifo kila siku! Fahari niliyo nayo juu yenu katika kuungana na Kristo Yesu Bwana wetu inanifanya nitangaze jambo hili.'),
(2019420,69,46,15,32,'Kama kusudi langu lingalikuwa la kibinadamu tu, kule kupigana kwangu na wanyama wakali hapa Efeso kungalinifaa kitu gani? Kama wafu hawafufuki, basi, "Tule na tunywe, maana kesho tutakufa."'),
(2019421,69,46,15,33,'Msidanganyike! Urafiki mbaya huharibu tabia njema.'),
(2019422,69,46,15,34,'Amkeni! Anzeni kuishi vema, na acheni kutenda dhambi. Baadhi yenu hawamjui Mungu kabisa. Hii nawaambieni, ni aibu kubwa kwenu!'),
(2019423,69,46,15,35,'Lakini mtu anaweza kuuliza: "Wafu watafufuliwaje? Watakuwa na mwili wa namna gani wakati watakapokuja tena?"'),
(2019424,69,46,15,36,'Hayo ni maswali ya kijinga! Ukipanda mbegu, isipokufa kwanza haitaota.'),
(2019425,69,46,15,37,'Unachopanda ni mbegu tu, labda ya ngano au nafaka nyingine, na si mmea mzima ambao hutokea baadaye.'),
(2019426,69,46,15,38,'Mungu huipa hiyo mbegu mwili anaoutaka mwenyewe; kila mbegu hupata mwili wake wa pekee.'),
(2019427,69,46,15,39,'Miili ya viumbe vyote si sawa. Miili ya binadamu ni ya namna moja, ya wanyama ni ya namna nyingine, ya ndege ni ya namna nyingine na miili ya samaki pia ni ya namna nyingine.'),
(2019428,69,46,15,40,'Iko miili ya mbinguni na miili ya duniani; uzuri wa miili ya mbinguni ni mwingine, na na uzuri wa miili ya duniani ni mwingine.'),
(2019429,69,46,15,41,'Uko uzuri wa jua, wa mwezi na wa nyota; hata nyota nazo huhitilafiana kwa uzuri.'),
(2019430,69,46,15,42,'Ndivyo ilivyo kuhusu ufufuo wa wafu. Kama vile mbegu, mwili huzikwa ardhini ukiwa katika hali ya kuharibika, lakini hufufuliwa katika hali ya kutoharibika.'),
(2019431,69,46,15,43,'Huzikwa katika hali duni, hufufuliwa katika hali tukufu; huzikwa katika hali dhaifu, hufufuliwa ukiwa wenye nguvu.'),
(2019432,69,46,15,44,'Unapozikwa ni mwili wa kawaida, unapofufuliwa ni mwili wa kiroho. Kuna mwili wa kawaida na kutakuwa na mwili wa kiroho.'),
(2019433,69,46,15,45,'Maana Maandiko yasema: "Mtu wa kwanza, Adamu, alikuwa kiumbe mwenye uhai;" lakini adamu wa mwisho ni Roho awapaye watu uzima.'),
(2019434,69,46,15,46,'Lakini unaotangulia kuwako si ule mwili wa kiroho, ila ule mwili wa kawaida kisha ule mwili wa kiroho.'),
(2019435,69,46,15,47,'Adamu wa kwanza aliumbwa kwa udongo, alitoka ardhini; mtu wa pili alitoka mbinguni.'),
(2019436,69,46,15,48,'Wote walio wa dunia wako kama huyo mtu aliyeumbwa kwa udongo; wale walio wa mbinguni wako kama yule aliyetoka mbinguni.'),
(2019437,69,46,15,49,'Kama vile tulivyofanana na yule aliyeumbwa kwa udongo, vivyo hivyo tutafanana na huyohuyo aliyetoka mbinguni.'),
(2019438,69,46,15,50,'Basi, ndugu, nasema hivi: kile kilichofanywa kwa mwili na damu hakiwezi kuushiriki Ufalme wa Mungu; na chenye kuharibika hakiwezi kuwa na hali ya kutoharibika.'),
(2019439,69,46,15,51,'Sikilizeni, nawaambieni siri: sisi hatutakufa sote, ila sote tutageuzwa'),
(2019440,69,46,15,52,'wakati wa mbiu ya mwisho, kwa nukta moja, kufumba na kufumbua. Maana mbiu itakapolia, wafu watafufuliwa katika hali ya kutoweza kufa tena, na sisi tutageuzwa.'),
(2019441,69,46,15,53,'Maana ni lazima kila kiharibikacho kijivalie hali ya kutoharibika, mwili uwezao kufa ujivalie hali ya kutokufa.'),
(2019442,69,46,15,54,'Basi, mwili huu wenye kuharibika utakapojivalia hali ya kutoharibika, na kile chenye kufa kitakapojivalia hali ya kutokufa, hapo ndipo litakapotimia lile neno lililoandikwa: "Kifo kimeangamizwa ushindi umekamilika!"'),
(2019443,69,46,15,55,'"Kifo, ushindi wako uko wapi? Uwezo wako wa kuumiza uko wapi?"'),
(2019444,69,46,15,56,'Ukali wa kifo hutokana na dhambi, nayo dhambi hupata nguvu yake katika Sheria.'),
(2019445,69,46,15,57,'Lakini tumshukuru Mungu anayetupatia ushindi kwa njia ya Bwana wetu Yesu Kristo.'),
(2019446,69,46,15,58,'Basi, ndugu zangu wapenzi, simameni imara na thabiti. Endeleeni daima kuwa na bidii katika kazi ya Bwana, mkijua kwamba kazi mnayofanya katika utumishi wa Bwana haitapotea bure.'),
(2019447,69,46,16,1,'Sasa, yahusu ule mchango kwa ajili ya watu wa Mungu: fanyeni kama nilivyoyaagiza makanisa ya Galatia.'),
(2019448,69,46,16,2,'Kila Jumapili kila mmoja wenu atenge kiasi cha fedha kadiri ya mapato yake, ili kusiwe na haja ya kufanya mchango wakati nitakapokuja.'),
(2019449,69,46,16,3,'Wakati nitakapokuja kwenu, nitawatuma wale mtakaowachagua miongoni mwenu wapeleke barua na zawadi zenu Yerusalemu.'),
(2019450,69,46,16,4,'Kama itafaa nami niende, basi, watakwenda pamoja nami.'),
(2019451,69,46,16,5,'Nitakuja kwenu, baada ya kupitia Makedonia--maana nataraji kupitia Makedonia.'),
(2019452,69,46,16,6,'Labda nitakaa kwenu kwa muda fulani, au huenda nitakaa pamoja nanyi wakati wote wa baridi, ili mpate kunisaidia niendelee na safari yangu kokote nitakakokwenda.'),
(2019453,69,46,16,7,'Sipendi kupita kwenu harakaharaka na kuendelea na safari. Natumaini kukaa kwenu kwa kitambo fulani, Bwana akiniruhusu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019454,69,46,16,8,'Lakini nitabaki hapa Efeso mpaka siku ya Pentekoste.'),
(2019455,69,46,16,9,'Mlango uko wazi kabisa kwa ajili ya kazi yangu muhimu hapa, ingawa wapinzani nao ni wengi.'),
(2019456,69,46,16,10,'Timotheo akija, angalieni asiwe na hofu yoyote wakati yupo kati yenu, kwani anafanya kazi ya Bwana kama mimi.'),
(2019457,69,46,16,11,'Kwa hiyo mtu yeyote asimdharau, ila msaidieni aendelee na safari yake kwa amani ili aweze kurudi kwangu, maana mimi namngojea pamoja na ndugu zetu.'),
(2019458,69,46,16,12,'Kuhusu ndugu Apolo, nimemsihi sana aje kwenu pamoja na ndugu wengine, lakini hapendelei kabisa kuja sasa ila atakuja mara itakapowezekana.'),
(2019459,69,46,16,13,'Kesheni, simameni imara katika imani, muwe hodari na wenye nguvu.'),
(2019460,69,46,16,14,'Kila mfanyacho kifanyike kwa upendo.'),
(2019461,69,46,16,15,'Ndugu, mnaifahamu jamaa ya Stefana; wao ni watu wa kwanza kabisa kuipokea imani ya Kikristo katika Akaya, na wamejitolea kuwatumikia watu wa Mungu. Ninawasihi ninyi ndugu zangu,'),
(2019462,69,46,16,16,'muufuate uongozi wa watu kama hao, na uongozi wa kila mtu afanyaye kazi na kutumikia pamoja nao.'),
(2019463,69,46,16,17,'Nafurahi sana kwamba Stefana, Fortunato na Akaiko wamefika; wamelijaza pengo lililokuwako kwa kutokuwako kwenu.'),
(2019464,69,46,16,18,'Wameiburudisha roho yangu na yenu pia. Kwa hiyo inafaa kuwakumbuka watu wa namna hii.'),
(2019465,69,46,16,19,'Makanisa yote ya Asia yanawasalimuni. Akula na Priskila pamoja na watu wote wa Mungu walio nyumbani mwao wanawasalimuni sana katika Bwana.'),
(2019466,69,46,16,20,'Ndugu wote wanawasalimuni. Nanyi salimianeni kwa ishara ya mapendo ya Mungu.'),
(2019467,69,46,16,21,'Mimi Paulo nawasalimuni, nikiandika kwa mkono wangu mwenyewe.'),
(2019468,69,46,16,22,'Yeyote asiyempenda Bwana, na alaaniwe. MARANA THA--BWANA, njoo!'),
(2019469,69,46,16,23,'Neema ya Bwana Yesu iwe nanyi.'),
(2019470,69,46,16,24,'Mapendo yangu yawe kwenu katika kuungana na Kristo Yesu.'),
(2019471,69,47,1,1,'Mimi Paulo, mtume wa Kristo Yesu kwa mapenzi ya Mungu, na ndugu Timotheo, tunawaandikia ninyi mlio kanisa la Mungu huko Korintho, na watu wote wa Mungu kila mahali katika Akaya.'),
(2019472,69,47,1,2,'Tunawatakieni neema na amani kutoka kwa Mungu Baba yetu na Bwana Yesu Kristo.'),
(2019473,69,47,1,3,'Atukuzwe Mungu na Baba wa Bwana wetu Yesu Kristo, Baba mwenye huruma na Mungu mwenye kuleta faraja yote.'),
(2019474,69,47,1,4,'Yeye hutufariji sisi katika taabu zetu zote, ili nasi tupate kuwafariji wengine katika kila taabu kwa faraja hiyohiyo tunayopokea kutoka kwa Mungu.'),
(2019475,69,47,1,5,'Naam, kadiri mateso ya Kristo yanavyozidi ndani yetu, ni kadiri hiyohiyo tunazidi kufarijiwa naye.'),
(2019476,69,47,1,6,'Ikiwa tunapata taabu, basi ni kwa ajili ya faraja na wokovu wenu. Tukifarijika, ni kwa ajili ya kuwafariji ninyi na kuwaunga mkono mpate nguvu ya kustahimili mateso yaleyale tunayoteseka sisi.'),
(2019477,69,47,1,7,'Tena, matumaini tuliyo nayo kwa ajili yenu ni imara; tunajua kwamba mkishiriki mateso yetu, mtashiriki pia faraja yetu.'),
(2019478,69,47,1,8,'Ndugu, tunataka kuwajulisheni taabu zilizotupata kule Asia; taabu hizo zilitulemea kupita kiasi, hata tukakata matumaini yote ya kuendelea kuishi.'),
(2019479,69,47,1,9,'Naam, tulikuwa kama watu waliohukumiwa kuuawa, ili tufundishwe kumtegemea Mungu mwenye kuwafufua wafu, badala ya kutegemea nguvu zetu sisi wenyewe.'),
(2019480,69,47,1,10,'Yeye alituokoa katika hatari kubwa ya kifo, na anaendelea kutuokoa; sisi tumemwekea tumaini letu kwamba atatuokoa tena,'),
(2019481,69,47,1,11,'ninyi mkiwa mnatuunga mkono kwa kutuombea. Hivyo neema tutakazokuwa tumepata kutokana na maombi ya watu wengi hivyo, ziwe sababu ya watu wengi zaidi kumshukuru Mungu kwa ajili yetu.'),
(2019482,69,47,1,12,'Sisi tunajivunia kitu kimoja: dhamiri yetu inatuhakikishia kwamba tumeishi ulimwenguni hapa, na hasa kati yenu, kwa unyenyekevu na unyofu tuliojaliwa na Mungu; hatukuongozwa na hekima ya kibinadamu bali neema ya Mungu.'),
(2019483,69,47,1,13,'Tunawaandikia ninyi mambo mnayoweza kuyasoma na kuyaelewa. Ninatumaini kwamba mtaelewa vizuri kabisa,'),
(2019484,69,47,1,14,'maana mpaka sasa mmenielewa kiasi fulani tu. Tunajua kwamba katika ile Siku ya Bwana Yesu mtaweza kutuonea sisi fahari kama nasi tunavyowaonea ninyi fahari.'),
(2019485,69,47,1,15,'Nikiwa na matumaini hayo, nilikusudia kuja kwenu hapo awali ili mpate baraka maradufu.'),
(2019486,69,47,1,16,'Nilikusudia kupita kwenu nikiwa safarini kwenda Makedonia, na wakati wa kurudi pia, ili nipate msaada wenu kwa safari yangu kwenda Yudea.'),
(2019487,69,47,1,17,'Je, mnadhani nilipopanga hivyo nimekuwa kama mtu asiye na msimamo? Je, mnadhani kwamba ninafanya uamuzi wangu kwa fikira za kibinadamu na kwamba nasema "Ndiyo" na "Siyo" papo hapo?'),
(2019488,69,47,1,18,'Mungu ni ukweli mtupu; basi, kile tulichowaambia ninyi si jambo la "Ndiyo" na "Siyo".'),
(2019489,69,47,1,19,'Maana Kristo Yesu, Mwana wa Mungu, ambaye mimi, Silwano na Timotheo, tulimhubiri kwenu, hakuwa mtu wa "Ndiyo" na "Siyo"; bali yeye daima ni "Ndiyo" ya Mungu.'),
(2019490,69,47,1,20,'Maana ndani yake ahadi zote za Mungu zimekuwa "Ndiyo". Kwa sababu hiyo, "Amina" yetu husemwa kwa njia ya Kristo kwa ajili ya kumtukuza Mungu.'),
(2019491,69,47,1,21,'Mungu mwenyewe ndiye mwenye kutuimarisha sisi na ninyi pia katika Kristo, na ndiye anayetuweka wakfu;'),
(2019492,69,47,1,22,'ndiye aliyetutia mhuri wa kuwa mali yake yeye na kutujalia Roho mioyoni mwetu kama dhamana ya mambo yote ambayo ametuwekea.'),
(2019493,69,47,1,23,'Mungu ndiye shahidi wangu--yeye anajua moyo wangu! Mimi sikuja tena Korintho, kwa sababu tu ya kuwahurumieni.'),
(2019494,69,47,1,24,'Hatutaki kutumia mabavu juu ya imani yenu; ninyi mko imara katika imani yenu. Wajibu wetu ni kufanya kazi pamoja kwa ajili ya furaha yenu.'),
(2019495,69,47,2,1,'Basi nimeamua nisiwatembelee tena kuwatia huzuni.'),
(2019496,69,47,2,2,'Maana nikiwahuzunisha ninyi, basi, ni nani atakayenifariji? Ni walewale niliowahuzunisha!'),
(2019497,69,47,2,3,'Ndiyo maana niliwaandikia--sikutaka kuja kwenu na kuhuzunishwa na ninyi ambao ndio mngepaswa kuwa furaha yangu. Nina hakika kwamba, mimi nikifurahi, ninyi nyote pia mnafurahi.'),
(2019498,69,47,2,4,'Nilipowaandikia hapo awali katika hali ya huzuni na sikitiko moyoni na kwa machozi mengi, haikuwa kwa ajili ya kuwahuzunisha ninyi, bali kwa ajili ya kuwaonyesheni kwamba nawapenda mno.'),
(2019499,69,47,2,5,'Ikiwa kuna mtu aliyemhuzunisha mwingine, hakunihuzunisha mimi--ila amewahuzunisha ninyi nyote, na sipendi kuwa mkali zaidi.'),
(2019500,69,47,2,6,'Adhabu aliyokwisha pata kutoka kwa wengi wenu inamtosha.'),
(2019501,69,47,2,7,'Iliyobakia ni afadhali kwenu kumsamehe mtu huyo na kumpa moyo ili asije akahuzunika mno na kukata tamaa kabisa.'),
(2019502,69,47,2,8,'Kwa hiyo nawasihi: mwonyesheni kwamba mnampenda.'),
(2019503,69,47,2,9,'Madhumuni yangu kuandika ile barua yalikuwa kutaka kujua kama mko tayari kutii katika kila jambo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019504,69,47,2,10,'Mkimsamehe mtu, nami pia ninamsamehe. Maana ninaposamehe--kama kweli ninacho cha kusamehe--nasamehe mbele ya Kristo kwa ajili yenu,'),
(2019505,69,47,2,11,'ili tusimpe nafasi Shetani atudanganye; maana twaijua mipango yake ilivyo.'),
(2019506,69,47,2,12,'Nilipofika Troa kuhubiri Habari Njema ya Kristo, nilikuta mlango u wazi kwa ajili ya kazi ya Bwana.'),
(2019507,69,47,2,13,'Lakini nilifadhaika sana kwa kutomkuta ndugu yetu Tito. Ndiyo maana niliwaaga wote pale nikaenda Makedonia.'),
(2019508,69,47,2,14,'Lakini, shukrani kwa Mungu anayetuongoza daima katika msafara wa ushindi wa Kristo. Yeye hutufanya tuueneze ukweli wa Kristo kama harufu nzuri, kila mahali.'),
(2019509,69,47,2,15,'Maana sisi ni kama harufu nzuri ya ubani ambayo Kristo anamtolea Mungu, harufu nzuri inayofikia wote wanaookolewa na wanaopotea.'),
(2019510,69,47,2,16,'Kwa wale wanaopotea, harufu hiyo ni kifo; lakini kwa wale wanaookolewa, harufu hiyo ni uhai. Nani basi, awezaye kushiriki katika kazi ya namna hiyo?'),
(2019511,69,47,2,17,'Sisi si kama wengine ambao hufanya biashara na ujumbe wa Mungu; sisi tunahubiri kwa unyofu mbele ya Mungu, kama watu tuliotumwa na Mungu, tukiwa tumeungana na Kristo.'),
(2019512,69,47,3,1,'Je, tunaanza tena kujipendekeza? Je, tunahitaji barua ya utambulisho kwenu, au kutoka kwenu, kama watu wengine?'),
(2019513,69,47,3,2,'Ninyi wenyewe ni barua yetu; barua iliyoandikwa mioyoni mwetu kila mtu aione na kuisoma.'),
(2019514,69,47,3,3,'Ni dhahiri kwamba ninyi ni barua ya Kristo aliyoipeleka kwa mikono yetu. Barua yenyewe imeandikwa si kwa wino, bali kwa Roho wa Mungu hai; imeandikwa si juu ya kipande cha jiwe, bali juu ya mioyo ya watu.'),
(2019515,69,47,3,4,'Tunaweza kusema hayo kwa sababu ya tumaini letu tulilo nalo kwa Mungu kwa njia ya Kristo.'),
(2019516,69,47,3,5,'Si kwamba sisi tunaweza kufanya chochote kwa nguvu zetu wenyewe, ila uwezo wetu wote hutoka kwa Mungu:'),
(2019517,69,47,3,6,'maana yeye ndiye aliyetuwezesha kulihudumia Agano Jipya ambalo si agano la sheria iliyoandikwa, bali Agano la Roho. Maana sheria iliyoandikwa huleta kifo, lakini Roho huleta uzima.'),
(2019518,69,47,3,7,'Sheria iliwekwa kwa kuandikwa juu ya vipande vya mawe. Ingawaje mwisho wake umekuwa kifo, utukufu wake ulikuwa mkuu mno hata wana wa Israeli wasiweze kuutazama uso wa Mose kwa sababu ya mng`ao wake. Tena mng`ao huo ulikuwa wa muda tu. Basi, ikiwa huduma ya kile ambacho kimesababisha kifo imefanyika kwa utukufu mwingi kiasi hicho,'),
(2019519,69,47,3,8,'basi, huduma ya Roho ina utukufu mkuu zaidi.'),
(2019520,69,47,3,9,'Ikiwa basi, kulikuwa na utukufu katika huduma ile iliyoleta hukumu, ni wazi kwamba huduma ile iletayo kukubaliwa kuwa waadilifu itakuwa na utukufu mkuu zaidi.'),
(2019521,69,47,3,10,'Sasa utukufu mkuu zaidi umechukua nafasi ya ule utukufu uliokuja hapo awali, ambao fahari yake imekwisha toweka.'),
(2019522,69,47,3,11,'Maana ikiwa kile kilichokuwa cha muda tu kilikuwa na utukufu wake, bila shaka kile chenye kudumu milele kitakuwa na utukufu mkuu zaidi.'),
(2019523,69,47,3,12,'Kwa vile hili ndilo tumaini letu, sisi twasema kwa uhodari mkuu.'),
(2019524,69,47,3,13,'Sisi hatufanyi kama Mose ambaye alilazimika kuufunika uso wake kwa kitambaa ili watu wa Israeli wasiuone ule mwisho wa mng`ao uliokuwa unafifia.'),
(2019525,69,47,3,14,'Lakini akili zao zilipumbazwa. Mpaka leo hii lisomwapo Agano la Kale, kifuniko hicho bado kipo. Kifuniko hicho kitaondolewa tu mtu anapoungana na Kristo.'),
(2019526,69,47,3,15,'Naam, mpaka hivi leo kila isomwapo Sheria ya Mose akili zao huwa zimefunikwa.'),
(2019527,69,47,3,16,'Lakini, wakati mtu amgeukiapo Bwana, kifuniko hicho huondolewa.'),
(2019528,69,47,3,17,'Hapa "Bwana" ni Roho; na pale alipo Roho wa Bwana ndipo ulipo uhuru.'),
(2019529,69,47,3,18,'Basi, sisi sote ambao nyuso zetu hazikufunikwa, twaonyesha kama katika kioo, utukufu wa Bwana; tunabadilishwa tufanane zaidi na huo mfano wake kwa utukufu mwingi zaidi. Hiyo ni kazi yake Roho wa Bwana.'),
(2019530,69,47,4,1,'Basi, Mungu, kwa huruma yake, ametukabidhi kazi hii na hivyo hatufi moyo.'),
(2019531,69,47,4,2,'Tumeyaacha kabisa mambo yote ya aibu na ya kisirisiri. Hatuishi tena kwa udanganyifu, wala kwa kulipotosha neno la Mungu; bali tunaudhihirisha ukweli kwa kuufanya ukweli, na hivyo kujiweka chini ya uamuzi wa dhamiri za watu mbele ya Mungu.'),
(2019532,69,47,4,3,'Maana, kama Habari Njema tunayohubiri imefichika, imefichika tu kwa wale wanaopotea.'),
(2019533,69,47,4,4,'Hao hawaamini kwa sababu yule mungu wa ulimwengu huu amezitia giza akili zao wasipate kuuona wazi mwanga wa Habari Njema ya utukufu wa Kristo, ambaye ni mfano kamili wa Mungu.'),
(2019534,69,47,4,5,'Maana hatujitangazi sisi wenyewe, ila tunamhubiri Yesu Kristo aliye Bwana, sisi wenyewe tukiwa watumishi wenu kwa ajili ya Yesu.'),
(2019535,69,47,4,6,'Mungu ambaye alisema, "Mwanga na uangaze kutoka gizani," ndiye mwenye kuiangaza mioyo yetu, na kutupatia mwanga wa ujuzi wa utukufu wa Mungu uangazao katika uso wa Kristo.'),
(2019536,69,47,4,7,'Basi, sisi tulio na hazina hii tuko tu kama vyombo vya udongo, ili ionekane wazi kwamba nguvu hiyo kuu yatoka kwa Mungu wala si kwetu sisi wenyewe.'),
(2019537,69,47,4,8,'Daima twapata taabu, lakini hatugandamizwi; twapata mashaka, lakini hatukati tamaa;'),
(2019538,69,47,4,9,'twateseka, lakini hatuachwi bila msaada; na ingawa tumeangushwa chini, hatukuangamizwa.'),
(2019539,69,47,4,10,'Kila wakati tumekuwa tukichukua mwilini mwetu kifo cha Kristo, ili uhai wake Yesu pia udhihirike katika miili yetu.'),
(2019540,69,47,4,11,'Naam, katika maisha yetu yote tunakabiliwa na kifo daima kwa ajili ya Yesu, ili uzima wake Yesu udhihirike katika miili yetu inayokufa.'),
(2019541,69,47,4,12,'Hii ina maana kwamba ndani yetu kifo kinafanya kazi, lakini ndani yenu uhai unafanya kazi.'),
(2019542,69,47,4,13,'Maandiko Matakatifu yasema: "Niliamini, ndiyo maana nilinena." Nasi pia, tukiwa na moyo huohuo wa imani, tunaamini, na kwa sababu hiyo twanena.'),
(2019543,69,47,4,14,'Tunajua kwamba yule aliyemfufua Bwana Yesu atatufufua sisi pia pamoja na Yesu na kutuweka mbele yake pamoja nanyi.'),
(2019544,69,47,4,15,'Yote haya ni kwa faida yenu; ili kama vile neema ya Mungu inavyoenea kwa watu wengi zaidi na zaidi vivyo hivyo watu wengi zaidi watoe shukrani nyingi kwa utukufu wa Mungu.'),
(2019545,69,47,4,16,'Kwa sababu hiyo hatufi moyo; na hata kama maumbile yetu ya nje yataoza, lakini kwa ndani tunafanywa wapya siku kwa siku.'),
(2019546,69,47,4,17,'Taabu tunayopata ni kidogo, tena ya muda tu: lakini itatupatia utukufu upitao matazamio yote, utukufu ambao hauna mwisho.'),
(2019547,69,47,4,18,'Hivyo tunatazamia kwa makini si vitu vinavyoonekana, bali visivyoonekana. Maana vinavyoonekana ni vya muda tu; lakini vile visivyoonekana ni vya milele.'),
(2019548,69,47,5,1,'Maana tunajua kwamba hema hii ambayo ndani yake tunaishi sasa hapa duniani, yaani mwili wetu, itakapong`olewa, Mungu atatupa makao mengine mbinguni, nyumba ya milele isiyotengenezwa kwa mikono.'),
(2019549,69,47,5,2,'Na sasa, katika hali hii, tunaugua, tukitazamia kwa hamu kubwa kuvikwa makao yetu yaliyo mbinguni.'),
(2019550,69,47,5,3,'Naam, tunapaswa kuvikwa namna hiyo ili tusije tukasimama mbele ya Mungu bila vazi.'),
(2019551,69,47,5,4,'Tukiwa bado katika hema hii ya duniani, tunalia kwa kukandamizwa; si kwamba tunataka kuuvua mwili huu wa kufa, ila tuna hamu ya kuvalishwa ule usiokufa, ili kile chenye kufa kimezwe kabisa na uhai.'),
(2019552,69,47,5,5,'Mungu mwenyewe alitutayarishia mabadiliko hayo, naye ametupa Roho wake awe dhamana ya yote aliyotuwekea.'),
(2019553,69,47,5,6,'Tuko imara daima. Tunajua kwamba kuishi katika mwili huu tu ni kukaa mbali na Bwana.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019554,69,47,5,7,'Maana tunaishi kwa imani, na si kwa kuona.'),
(2019555,69,47,5,8,'Lakini tuko imara na tungependelea hata kuyahama makao haya, tukahamie kwa Bwana.'),
(2019556,69,47,5,9,'Lakini jambo la maana zaidi, tunataka kumpendeza, iwe tunaishi hapa duniani au huko.'),
(2019557,69,47,5,10,'Maana sote ni lazima tusimame mbele ya kiti cha hukumu cha Kristo, ili kila mmoja apokee anayostahili kwa matendo aliyoyafanya wakati alipokuwa anaishi duniani, mema au mabaya.'),
(2019558,69,47,5,11,'Basi, sisi tunajua umuhimu wa kumcha Bwana, na hivyo tunajitahidi kuwavuta watu. Mungu anatujua waziwazi, nami natumaini kwamba nanyi pia mnatujua kinaganaga.'),
(2019559,69,47,5,12,'Si kwamba tunajaribu tena kujipendekeza kwenu, ila tunataka kuwapa ninyi sababu zetu za kuona fahari juu yenu, ili mpate kuwajibu wale wanaojivunia hali yao ya nje zaidi kuliko jinsi walivyo moyoni.'),
(2019560,69,47,5,13,'Ikiwa tumeonekana kuwa wendawazimu, hiyo ni kwa ajili ya Mungu; na ikiwa tunazo akili zetu timamu, hiyo ni kwa faida yenu.'),
(2019561,69,47,5,14,'Maana mapendo ya Kristo yanatumiliki sisi ambao tunatambua ya kwamba mtu mmoja tu amekufa kwa ajili ya wote, na hiyo ina maana kwamba wote wanashiriki kifo chake.'),
(2019562,69,47,5,15,'Alikufa kwa ajili ya watu wote, ili wanaoishi wasiishi kwa ajili yao wenyewe, bali kwa ajili yake yeye aliyekufa, akafufuliwa kwa ajili yao.'),
(2019563,69,47,5,16,'Basi, tangu sasa, sisi hatumpimi mtu yeyote kibinadamu. Hata kama kwa wakati mmoja tulimpima Kristo kibinadamu, sasa si hivyo tena.'),
(2019564,69,47,5,17,'Mtu yeyote akiungana na Kristo huwa kiumbe kipya, mambo ya kale yamepita, hali mpya imefika.'),
(2019565,69,47,5,18,'Yote ni kazi ya Mungu mwenye kutupatanisha sisi naye kwa njia ya Kristo, akatupa nasi jukumu la kuwapatanisha watu naye.'),
(2019566,69,47,5,19,'Ndiyo kusema: Mungu, amekuwa akiupatanisha ulimwengu naye kwa njia ya Kristo, bila kutia maanani dhambi zao binadamu. Yeye ametupa ujumbe kuhusu kuwapatanisha watu naye.'),
(2019567,69,47,5,20,'Basi, sisi tunamwakilisha Kristo, naye Mungu mwenyewe anatutumia sisi kuwasihi ninyi. Tunawaombeni kwa niaba ya Kristo, mpatanishwe na Mungu.'),
(2019568,69,47,5,21,'Kristo hakuwa na dhambi, lakini Mungu alimfanya ahusike na dhambi kwa ajili yetu, ili sisi kwa kuungana naye, tupate kuushiriki uadilifu wake Mungu.'),
(2019569,69,47,6,1,'Basi, tukiwa wafanyakazi pamoja na Mungu, tunawasihi msikubali ile neema mliyopokea kutoka kwa Mungu ipotee bure.'),
(2019570,69,47,6,2,'Mungu asema hivi: "Wakati wa kufaa nimekusikiliza, wakati wa wokovu nikakusaidia." Basi, sasa ndio wakati wa kufaa, sasa ndiyo siku ya wokovu!'),
(2019571,69,47,6,3,'Kusudi tusiwe na lawama yoyote katika utumishi wetu, hatupendi kumwekea mtu yeyote kizuio chochote.'),
(2019572,69,47,6,4,'Badala yake, tunajionyesha kuwa kweli watumishi wa Mungu kwa kila kitu: kwa uvumilivu mwingi wakati wa mateso, shida na taabu.'),
(2019573,69,47,6,5,'Tumepigwa, tumetiwa gerezani na kuzomewa hadharani; tumefanya kazi tukachoka; tumekesha na kukaa bila kula.'),
(2019574,69,47,6,6,'Tunajionyesha kuwa watumishi wa Mungu kwa usafi wa moyo, elimu, uvumilivu na wema; kwa Roho Mtakatifu, kwa upendo usio na unafiki,'),
(2019575,69,47,6,7,'kwa ujumbe wa kweli na kwa nguvu ya Mungu. Uadilifu ndiyo silaha yetu upande wa kulia na upande wa kushoto.'),
(2019576,69,47,6,8,'Tuko tayari kupata heshima na kudharauliwa, kulaumiwa na kusifiwa. Twadhaniwa kuwa waongo, kumbe twasema kweli;'),
(2019577,69,47,6,9,'kama wasiojulikana, kumbe twajulikana kwa wote, kama waliokufa, lakini mwonavyo, sisi ni wazima kabisa.'),
(2019578,69,47,6,10,'Ingawa tumeadhibiwa, hatukuuawa; ingawa tunayo huzuni, twafurahi daima; ingawa tu maskini hohehahe, lakini twatajirisha watu wengi; twaonekana kuwa watu tusio na chochote, kumbe tuna kila kitu.'),
(2019579,69,47,6,11,'Ndugu Wakorintho, tumezungumza nanyi kwa unyofu; mioyo yetu iko wazi kabisa.'),
(2019580,69,47,6,12,'Kama mnaona kuna kizuizi chochote kile, kizuizi hicho kiko kwenu ninyi wenyewe, na si kwa upande wetu.'),
(2019581,69,47,6,13,'Sasa nasema nanyi kama watoto wangu, wekeni mioyo yenu wazi kama nasi tulivyofanya.'),
(2019582,69,47,6,14,'Msiambatane na watu wasioamini. Je, wema na uovu vyapatana kweli? Mwanga na giza vyawezaje kukaa pamoja?'),
(2019583,69,47,6,15,'Kristo anawezaje kupatana na Shetani? Muumini ana uhusiano gani na asiyeamini?'),
(2019584,69,47,6,16,'Hekalu la Mungu lina uhusiano gani na sanamu za uongo? Maana sisi ni hekalu la Mungu aliye hai. Kama Mungu mwenyewe alivyosema: "Nitafanya makao yangu kwao, na kuishi kati yao; Nitakuwa Mungu wao, nao watakuwa watu wangu."'),
(2019585,69,47,6,17,'Kwa hiyo Bwana asema pia: "Ondokeni kati yao, mkajitenge nao, msiguse kitu najisi, nami nitawapokea.'),
(2019586,69,47,6,18,'Mimi nitakuwa Baba yenu, nanyi mtakuwa watoto wangu, waume kwa wake, asema Bwana Mwenye Uwezo."'),
(2019587,69,47,7,1,'Basi, wapenzi wangu, tukiwa tumepewa ahadi hizi zote, na tujitakase na chochote kiwezacho kuchafua miili na roho zetu, tuwe watakatifu kabisa, na tuishi kwa kumcha Mungu.'),
(2019588,69,47,7,2,'Tunaomba mtupe nafasi mioyoni mwenu! Hatujamkosea mtu yeyote, hatujamdhuru wala kumdanganya mtu yeyote.'),
(2019589,69,47,7,3,'Sisemi mambo haya kwa ajili ya kumhukumu mtu; maana, kama nilivyokwisha sema, ninyi mko mioyoni mwetu, tufe pamoja, tuishi pamoja.'),
(2019590,69,47,7,4,'Nina imani kubwa sana ninaposema nanyi; naona fahari kubwa juu yenu! Katika taabu zetu nimepata kitulizo kikubwa na kufurahi mno.'),
(2019591,69,47,7,5,'Hata baada ya kufika Makedonia hatukuweza kupumzika. Kila upande tulikabiliwa na taabu: nje ugomvi; ndani hofu.'),
(2019592,69,47,7,6,'Lakini Mungu, mwenye kuwapa shime wanyonge alitupa moyo sisi pia kwa kuja kwake Tito.'),
(2019593,69,47,7,7,'Si tu kwa kule kuja kwake Tito, bali pia kwa sababu ya moyo mliompa ninyi. Yeye ametuarifu jinsi mnavyotamani kuniona, jinsi mlivyo na huzuni, na mnavyotaka kunitetea. Jambo hili linanifurahisha sana.'),
(2019594,69,47,7,8,'Maana, hata kama kwa barua ile yangu nimewahuzunisha, sioni sababu ya kujuta. Naam, naona kwamba barua hiyo iliwatia huzuni lakini kwa muda.'),
(2019595,69,47,7,9,'Sasa nafurahi, si kwa sababu mmehuzunika, ila kwa kuwa huzuni yenu imewafanya mbadili nia zenu na kutubu. Mmehuzunishwa kadiri ya mpango wa Mungu, na kwa sababu hiyo hatukuwadhuru ninyi kwa vyovyote.'),
(2019596,69,47,7,10,'Kuwa na huzuni jinsi atakavyo Mungu, husababisha badiliko la moyo, badiliko lenye kuleta wokovu; hivyo hakuna sababu ya kujuta. Lakini huzuni ya kidunia huleta kifo.'),
(2019597,69,47,7,11,'Sasa mnaweza kuona matokeo ya kuona huzuni jinsi Mungu atakavyo: ninyi mmepata kuwa sasa watu wenye jitihada, wenye hoja, mnashtuka na kuogopa, mna bidii na mko tayari kuona kwamba haki yatekelezwa. Ninyi mmethibitisha kwa kila njia kwamba hamna hatia kuhusu jambo hili.'),
(2019598,69,47,7,12,'Hivyo, ingawa niliandika ile barua, haikuwa kwa ajili ya yule aliyekosa, au kwa ajili ya yule aliyekosewa. Niliandika kusudi ionekane wazi mbele ya Mungu jinsi mlivyo na bidii kwa ajili yetu.'),
(2019599,69,47,7,13,'Ndiyo maana sisi tulifarijika sana. Siyo kwamba tulifarijika tu, ila pia Tito alitufurahisha kwa furaha aliyokuwa nayo kutokana na jinsi mlivyomchangamsha moyo.'),
(2019600,69,47,7,14,'Mimi nimewasifu sana mbele yake, na katika jambo hilo sikudanganyika. Tumewaambieni ukweli daima, na kule kuwasifia ninyi mbele ya Tito kumekuwa jambo la ukweli mtupu.'),
(2019601,69,47,7,15,'Hivyo upendo wake wa moyo kwenu unaongezeka zaidi akikumbuka jinsi ninyi nyote mlivyo tayari kutii, na jinsi mlivyomkaribisha kwa hofu nyingi na kutetemeka.'),
(2019602,69,47,7,16,'Nafurahi sana kwamba naweza kuwategemea ninyi kabisa katika kila jambo.'),
(2019603,69,47,8,1,'Ndugu, tunapenda kuwapa habari juu ya neema ambazo Mungu ameyajalia makanisa ya Makedonia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019604,69,47,8,2,'Waumini wa huko walijaribiwa sana kwa taabu; lakini furaha yao ilikuwa kubwa hivi hata wakawa wakarimu kupita kiasi, ingawaje walikuwa maskini sana.'),
(2019605,69,47,8,3,'Naweza kushuhudia kwamba walikuwa wakarimu kadiri ya nguvu zao na hata zaidi. Kwa hiari yao wenyewe,'),
(2019606,69,47,8,4,'walitusihi sana wapewe nafasi ya kushiriki katika huduma hii ya kuwasaidia watu wa Mungu.'),
(2019607,69,47,8,5,'Hilo lilikuwa jambo ambalo hatukulitazamia kabisa! Kwanza walijitolea wao wenyewe kwa Bwana, kisha wakajitolea wenyewe kwetu pia, kufuatana na mapenzi ya Mungu.'),
(2019608,69,47,8,6,'Kwa sababu hiyo, tulimsihi Tito aliyeianza kazi hiyo awasaidieni pia muitekeleze huduma hii ya upendo miongoni mwenu.'),
(2019609,69,47,8,7,'Ninyi mna kila kitu: imani, uwezo wa kusema, elimu; bidii yote ya kutenda mema, na upendo wenu kwetu. Hivyo, tunatazamia muwe wakarimu katika huduma hii ya upendo.'),
(2019610,69,47,8,8,'Siwapi ninyi amri, lakini nataka tu kuonyesha jinsi wengine walivyo na bidii ya kusaidia ili nipate kujua jinsi upendo wenu ulivyo wa kweli.'),
(2019611,69,47,8,9,'Maana, ninyi mnajua neema ya Bwana wetu Yesu Kristo: yeye, ingawa alikuwa na kila kitu, alijifanya maskini kwa ajili yenu, ili kutokana na umaskini wake, awatajirishe.'),
(2019612,69,47,8,10,'Kuhusu jambo hili, basi, nawapeni shauri hili: inafaa kwenu kutekeleza sasa yale mliyoanza mwaka jana. Ninyi mlikuwa wa kwanza kuchukua hatua na kuamua kufanya hivyo.'),
(2019613,69,47,8,11,'Basi, kamilisheni shughuli hiyo; na kama vile mlivyokuwa na hamu kubwa ya kusaidia, basi, fanyeni bidii vivyo hivyo, kadiri ya uwezo wenu, kuikamilisha.'),
(2019614,69,47,8,12,'Maana ikiwa mtu ana moyo wa kusaidia, Mungu hupokea kila anachoweza kutoa: hadai zaidi.'),
(2019615,69,47,8,13,'Ninyi hampaswi kuongezewa taabu kusudi wengine wapunguziwe mzigo wao; sivyo, ila ni lazima tujali usawa na haki.'),
(2019616,69,47,8,14,'Kila mlicho nacho sasa cha ziada kiwasaidie wale wanaohitaji, ili nao wakati watakapokuwa na ziada, wawasaidie ninyi katika mahitaji yenu, na hivyo kuwe na usawa.'),
(2019617,69,47,8,15,'Kama Maandiko yasemavyo: "Aliyekusanya kwa wingi hakuwa na ziada, na yule aliyekusanya kidogo hakupungukiwa."'),
(2019618,69,47,8,16,'Namshukuru Mungu aliyeweka ndani ya moyo wa Tito hamu hiyo niliyo nayo mimi ya kuwasaidia.'),
(2019619,69,47,8,17,'Si tu kwamba alikubali ombi letu, ila pia alikuwa na hamu kubwa ya kusaidia, hata akaamua kwa hiari yake mwenyewe kuja kwenu.'),
(2019620,69,47,8,18,'Pamoja naye, tunamtuma ndugu mmoja ambaye sifa zake katika kueneza Habari Njema zimeenea katika makanisa yote.'),
(2019621,69,47,8,19,'Zaidi ya hayo, yeye amechaguliwa na makanisa awe mwenzetu safarini wakati tunapopeleka huduma hii yetu ya upendo, huduma tunayoifanya kwa ajili ya utukufu wa Bwana na uthibitisho wa nia yetu njema.'),
(2019622,69,47,8,20,'Tunataka kuepa lawama zinazoweza kutokea kuhusu usimamizi wetu juu ya zawadi hii karimu.'),
(2019623,69,47,8,21,'Nia yetu ni kufanya vema, si tu mbele ya Bwana, lakini pia mbele ya watu.'),
(2019624,69,47,8,22,'Basi, pamoja na ndugu hao, tumemtuma ndugu yetu mwingine ambaye mara nyingi tumempa majaribio mbalimbali, tukamwona kuwa ni mwenye hamu kubwa ya kusaidia; hata sasa amekuwa na moyo zaidi kwa sababu ana imani sana nanyi.'),
(2019625,69,47,8,23,'Tito ni mwenzangu; tunafanya kazi pamoja kwa ajili yenu; lakini kuhusu hawa ndugu zetu wengine, wanaokuja pamoja nao, hao ni wajumbe wa makanisa, na utukufu kwa Kristo.'),
(2019626,69,47,8,24,'Basi, waonyesheni uthabiti wa upendo wenu, makanisa yapate kuona kweli kwamba fahari ninayoona juu yenu ni ya halali.'),
(2019627,69,47,9,1,'Si lazima kuandika zaidi kuhusu huduma hiyo yenu kwa ajili ya watu wa Mungu.'),
(2019628,69,47,9,2,'Ninajua jinsi mlivyo na moyo wa kusaidia, na nilijivuna juu yenu kuhusu jambo hilo mbele ya watu wa Makedonia. Niliwaambia: "Ndugu zetu wa Akaya wako tayari tangu mwaka jana." Hivyo, moto wenu umekwisha wahimiza watu wengi zaidi.'),
(2019629,69,47,9,3,'Basi, nimewatuma ndugu zetu hao, ili fahari yetu juu yenu ionekane kwamba si maneno matupu, na kwamba mko tayari kabisa na msaada wenu kama nilivyosema.'),
(2019630,69,47,9,4,'Isije ikawa kwamba watu wa Makedonia watakapokuja pamoja nami tukawakuta hamko tayari, hapo sisi tutaaibika--bila kutaja aibu mtakayopata ninyi wenyewe--kwa sababu tutakuwa tumewatumainia kupita kiasi.'),
(2019631,69,47,9,5,'Kwa hiyo, nimeona ni lazima kuwaomba hawa ndugu watutangulie kuja kwenu, wapate kuweka tayari zawadi yenu kubwa mliyoahidi; nayo ionyeshe kweli kwamba ni zawadi iliyotolewa kwa hiari na si kwa kulazimishwa.'),
(2019632,69,47,9,6,'Kumbukeni: "Apandaye kidogo huvuna kidogo; apandaye kwa wingi huvuna kwa wingi."'),
(2019633,69,47,9,7,'Kila mmoja, basi, na atoe kadiri alivyoamua, kwa moyo na wala si kwa huzuni au kwa kulazimishwa, maana Mungu humpenda yule mwenye kutoa kwa furaha.'),
(2019634,69,47,9,8,'Mungu anaweza kuwapeni ninyi zaidi ya yale mnayoyahitaji, mpate daima kuwa na kila kitu mnachohitaji, na hivyo mzidi kusaidia katika kila kazi njema.'),
(2019635,69,47,9,9,'Kama yasemavyo Maandiko Matakatifu: "Yeye hutoa kwa ukarimu, huwapa maskini, wema wahudumu milele."'),
(2019636,69,47,9,10,'Na Mungu ampaye mkulima mbegu na mkate kwa chakula, atawapa ninyi pia mbegu mnazohitaji, na atazifanya ziote, ziwe na kuwapa mavuno mengi ya ukarimu wenu.'),
(2019637,69,47,9,11,'Yeye atawatajirisha ninyi daima kwa kila kitu, ili watu wapate kumshukuru Mungu kwa ajili ya zawadi zenu wanazozipokea kwa mikono yetu.'),
(2019638,69,47,9,12,'Maana huduma hii takatifu mnayoifanya si tu kwamba itasaidia mahitaji ya watu wa Mungu, bali pia itasababisha watu wengi wamshukuru Mungu.'),
(2019639,69,47,9,13,'Kutokana na uthibitisho unaoonyeshwa kwa huduma hii yetu, watu watamtukuza Mungu kwa sababu ya uaminifu wenu kwa Habari Njema ya Kristo mnayoiungama, na pia kwa sababu ya ukarimu mnaowapa wao na watu wote.'),
(2019640,69,47,9,14,'Kwa hiyo watawaombea ninyi kwa moyo kwa sababu ya neema ya pekee aliyowajalieni Mungu.'),
(2019641,69,47,9,15,'Tumshukuru Mungu kwa ajili ya zawadi yake isiyo na kifani!'),
(2019642,69,47,10,1,'Mimi Paulo mwenyewe ambaye naonekana kuwa mpole nikiwa pamoja nanyi, lakini mkali wakati nikiwa mbali nanyi, nawasihini kwa huruma na wema wake Kristo.'),
(2019643,69,47,10,2,'Nawaombeni msinisababishe kuwa mkali wakati nitakapokuja, maana nina hakika naweza kuwa mkali kwa wote wale wanaotudhania kwamba tunaishi kidunia.'),
(2019644,69,47,10,3,'Kweli tunaishi duniani, lakini hatupigani vita kidunia.'),
(2019645,69,47,10,4,'Maana, silaha tunazotumia katika vita vyetu si silaha za kidunia, ila ni nguvu za Mungu zenye kuharibu ngome zote. Tunaharibu hoja zote za uongo,'),
(2019646,69,47,10,5,'na kubomoa kila kizuizi cha majivuno kilichowekwa kuipinga elimu ya Mungu; tunaziteka fikira zote na kuzifanya zimtii Kristo.'),
(2019647,69,47,10,6,'Mkisha kuwa wakamilifu katika kutii, sisi tuko tayari kuadhibu kila namna ya kutotii.'),
(2019648,69,47,10,7,'Ninyi hutazama mambo kwa nje tu. Je, yupo mtu yeyote anayedhani kwamba yeye ni wa Kristo? Sawa! Basi, afikirie vilevile kwamba sisi pia ni wa Kristo kama yeye alivyo wa Kristo.'),
(2019649,69,47,10,8,'Hata kama nimezidi katika kujivuna kwangu juu ya ule uwezo aliotupa--uwezo wa kuwajenga na sio wa kubomoa--hata hivyo sijutii hata kidogo.'),
(2019650,69,47,10,9,'Sipendi mfikiri kwamba nataka kuwatisha ninyi kwa barua zangu.'),
(2019651,69,47,10,10,'Mtu anaweza kusema: "Barua za Paulo ni kali na zenye maneno mazito, lakini yeye mwenyewe anapokuwa pamoja nasi ni mtu dhaifu, na hata anapoongea maneno yake ni kama si kitu."'),
(2019652,69,47,10,11,'Mtu asemaye hivyo heri akumbuke kwamba hakuna tofauti ya yale tunayoandika katika barua wakati tuko mbali, na yale tutakayofanya wakati tutakapokuwa nanyi.'),
(2019653,69,47,10,12,'Kwa vyovyote hatungethubutu kujiweka au kujilinganisha na wale watu wanaojisifia wenyewe. Watu wenye kujifanya wao kuwa kipimo cha kujipimia, na watu wanaojilinganisha wenyewe kwa wenyewe, ni wapumbavu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019654,69,47,10,13,'Lakini sisi hatutajivuna kupita kiasi; kujivuna huko kutabaki katika kile kipimo cha kazi aliyotukabidhi Mungu, kazi ambayo tunaifanya pia kwenu.'),
(2019655,69,47,10,14,'Na kwa vile ninyi mu katika mipaka hiyo, hatukuipita tulipokuja kwenu, tukiwaleteeni Habari Njema juu ya Kristo.'),
(2019656,69,47,10,15,'Basi, hatujivunii kazi waliyofanya wengine zaidi ya kipimo tulichopewa; ila tunatumaini kwamba imani yenu itazidi miongoni mwenu kufuatana na kipimo alichotuwekea Mungu.'),
(2019657,69,47,10,16,'Hapo tutaweza kuihubiri Habari Njema katika nchi nyingine, mbali nanyi; na haitakuwa shauri la kujivunia kazi waliyofanya watu wengine mahali pengine.'),
(2019658,69,47,10,17,'Lakini kama yasemavyo Maandiko: "Mwenye kuona fahari na aone fahari juu ya alichofanya Bwana."'),
(2019659,69,47,10,18,'Anayekubaliwa si yule anayejisifu mwenyewe, bali yule anayesifiwa na Bwana.'),
(2019660,69,47,11,1,'Laiti mngenivumilia kidogo, hata kama mimi ni mjinga kiasi fulani! Naam, nivumilieni kidogo.'),
(2019661,69,47,11,2,'Ninawaoneeni wivu lakini ni wivu wa Mungu; maana ninyi ni kama bikira safi niliyemposa kwa mwanamume mmoja tu ambaye ndiye Kristo.'),
(2019662,69,47,11,3,'Lakini naogopa kwamba, kama vile yule nyoka kwa hila zake za uongo alimdanganya Hawa, fikira zenu zaweza kupotoshwa, mkauacha uaminifu wenu wa kweli kwa Kristo.'),
(2019663,69,47,11,4,'Maana mtu yeyote ajaye na kumhubiri Yesu aliye tofauti na yule tuliyemhubiri, ninyi mwampokea kwa mikono miwili; au mnakubali roho au habari njema tofauti kabisa na ile mliyopokea kutoka kwetu!'),
(2019664,69,47,11,5,'Sidhani kwamba mimi ni mdogo kuliko hao "mitume wakuu."'),
(2019665,69,47,11,6,'Labda sina ufasaha wa lugha, lakini elimu ninayo; jambo hili tumelionyesha wazi kwenu, kila mahali na kila wakati.'),
(2019666,69,47,11,7,'Mimi niliihubiri kwenu Habari Njema ya Mungu bila kudai mshahara; nilijinyenyekeza ili nipate kuwakweza ninyi. Je, nilifanya vibaya?'),
(2019667,69,47,11,8,'Nilipofanya kazi kati yenu, mahitaji yangu yaligharimiwa na makanisa mengine. Kwa namna moja au nyingine niliwapokonya wao mali yao nipate kuwatumikia ninyi.'),
(2019668,69,47,11,9,'Nilipokuwa nanyi sikumsumbua mtu yeyote nilipohitaji fedha; ndugu waliotoka Makedonia waliniletea kila kitu nilichohitaji. Nilikuwa mwangalifu sana nisiwe mzigo kwa namna yoyote ile, na nitaendelea kufanya hivyo.'),
(2019669,69,47,11,10,'Naahidi kwa ule ukweli wa Kristo ulio ndani yangu, kwamba hakuna kitakachoweza kunizuia kujivunia jambo hilo popote katika Akaya.'),
(2019670,69,47,11,11,'Kwa nini nasema hivyo? Kwa sababu eti siwapendi ninyi? Mungu anajua kwamba nawapenda!'),
(2019671,69,47,11,12,'Nitaendelea kufanya kama ninavyofanya sasa, ili nisiwape nafasi wale wanaotafuta nafasi, nafasi ya kujivuna kwamba eti wanafanya kazi kama sisi.'),
(2019672,69,47,11,13,'Maana, hao ni mitume wa uongo, wafanyakazi wadanganyifu wanojisingizia kuwa mitume wa Kristo.'),
(2019673,69,47,11,14,'Wala si ajabu, maana hata Shetani mwenyewe hujisingizia kuwa malaika wa mwanga!'),
(2019674,69,47,11,15,'Kwa hiyo si jambo la kushangaza ikiwa na hao watumishi wake wanajisingizia kuwa watumishi wa haki. Mwisho wao watapata kile wanachostahili kufuatana na matendo yao.'),
(2019675,69,47,11,16,'Tena nasema: Mtu asinifikirie kuwa mpumbavu. Lakini kama mkifikiri hivyo, basi, nichukueni kama mpumbavu ili nami nipate kuwa na cha kujivunia angaa kidogo.'),
(2019676,69,47,11,17,'Ninachosema sasa si kile alichoniagiza Bwana; kuhusu jambo hili la kujivuna, nasema tu kama mtu mpumbavu.'),
(2019677,69,47,11,18,'Maadam wengi hujivuna kwa sababu za kidunia, nami pia nitajivuna.'),
(2019678,69,47,11,19,'Ninyi ni wenye busara, ndiyo maana hata mnawavumilia wapumbavu!'),
(2019679,69,47,11,20,'Mnamvumilia hata mtu anayewafanya ninyi watumwa, mtu mwenye kuwanyonya, mwenye kuwakandamiza, mwenye kuwadharau na kuwapiga usoni!'),
(2019680,69,47,11,21,'Kwa aibu nakubali kwamba sisi tulikuwa dhaifu. Iwe iwavyo, lakini kama kuna mtu yeyote anayethubutu kujivunia kitu--nasema kama mtu mpumbavu--mimi nathubutu pia.'),
(2019681,69,47,11,22,'Je, wao ni Waebrania? Hata mimi. Je, wao ni Waisraeli? Hata mimi. Wao ni wazawa wa Abrahamu? Hata mimi.'),
(2019682,69,47,11,23,'Wao ni watumishi wa Kristo? Hata mimi--nanena hayo kiwazimu--ni mtumishi wa Kristo zaidi kuliko wao. Mimi nimefanya kazi ngumu zaidi, nimekaa gerezani mara nyingi zaidi, nimepigwa mara nyingi zaidi na nimekaribia kifo mara nyingi.'),
(2019683,69,47,11,24,'Mara tano nilichapwa vile viboko thelathini na tisa vya Wayahudi.'),
(2019684,69,47,11,25,'Nilipigwa viboko mara tatu, nilipigwa mawe mara moja; mara tatu nilivunjikiwa meli baharini, na humo nikakesha usiku kucha na kushinda mchana kutwa.'),
(2019685,69,47,11,26,'Kila mara safarini nimekabiliwa na hatari za mafuriko ya mito, na hatari za wanyama; hatari kutoka kwa wananchi wenzangu na kutoka kwa watu wa mataifa mengine; hatari za mjini, hatari za porini, hatari za baharini, hatari kutoka kwa ndugu wa uongo'),
(2019686,69,47,11,27,'Nimefanya kazi na kutaabika, nimekesha bila usingizi mara nyingi; nimekuwa na njaa na kiu; mara nyingi nimefunga na kukaa katika baridi bila nguo.'),
(2019687,69,47,11,28,'Na, licha ya mengine mengi, kila siku nakabiliwa na shughuli za makanisa yote.'),
(2019688,69,47,11,29,'Kama mtu yeyote ni dhaifu, nami pia ni dhaifu; mtu yeyote akikwazwa, nami pia huwa na wasiwasi. ic'),
(2019689,69,47,11,30,'Ikinilazimu kujivuna, basi, nitajivunia udhaifu wangu.'),
(2019690,69,47,11,31,'Mungu na Baba wa Bwana Yesu--jina lake litukuzwe milele--yeye anajua kwamba sisemi uongo.'),
(2019691,69,47,11,32,'Nilipokuwa Damasko, mkuu wa mkoa, aliyekuwa chini ya mfalme Areta, alikuwa akiulinda mji wa Damasko ili apate kunikamata.'),
(2019692,69,47,11,33,'Lakini, ndani ya kapu kubwa, niliteremshwa nje kupitia katika nafasi ukutani, nikachopoka mikononi mwake.'),
(2019693,69,47,12,1,'Nitajivuna basi, ingawa haifai! Lakini sasa nitasema juu ya maono na ufunuo alivyonijalia Bwana.'),
(2019694,69,47,12,2,'Namjua mtu mmoja Mkristo, ambaye miaka kumi na minne iliyopita alinyakuliwa mpaka katika mbingu ya tatu. (Sijui kama alikuwa huko kwa mwili au kwa roho; Mungu ajua.)'),
(2019695,69,47,12,3,'Narudia: najua kwamba mtu huyo alinyakuliwa mpaka peponi. (Lakini sijui kama alikuwa huko kwa mwili au kwa roho; Mungu ajua.)'),
(2019696,69,47,12,4,'Huko akasikia mambo ya siri ambayo binadamu hastahili kuyatamka.'),
(2019697,69,47,12,5,'Basi, nitajivunia juu ya mtu wa namna hiyo, na si juu yangu mimi binafsi, isipokuwa tu juu ya udhaifu wangu.'),
(2019698,69,47,12,6,'Kama ningetaka kujivuna singekuwa mpumbavu hata kidogo, maana ningekuwa nasema ukweli mtupu. Lakini sitajivuna; sipendi mtu anifikirie zaidi ya vile anavyoona na kusikia kutoka kwangu.'),
(2019699,69,47,12,7,'Lakini, kusudi mambo haya makuu niliyofunuliwa yasinifanye nilewe majivuno, nilipewa maumivu mwilini kama mwiba, mjumbe wa Shetani mwenye kunipiga nisijivune kupita kiasi.'),
(2019700,69,47,12,8,'Nilimsihi Bwana mara tatu kuhusu jambo hili ili linitoke.'),
(2019701,69,47,12,9,'Lakini akaniambia: "Neema yangu inatosha kwa ajili yako; maana uwezo wangu hukamilishwa zaidi katika udhaifu." Basi, ni radhi kabisa kujivunia udhaifu wangu ili uwezo wake Kristo ukae juu yangu.'),
(2019702,69,47,12,10,'Kwa hiyo nakubali kwa radhi udhaifu, madharau, taabu, udhalimu na mateso, kwa ajili ya Kristo; maana ninapokuwa dhaifu, ndipo ninapokuwa na nguvu.'),
(2019703,69,47,12,11,'Nimekuwa kama mpumbavu, lakini, ninyi mmenilazimisha kuwa hivyo. Ninyi ndio mngalipaswa kunisifu. Maana, ingawa mimi si kitu, kwa vyovyote, mimi si mdogo zaidi kuliko hao "mitume wakuu."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019704,69,47,12,12,'Miujiza na maajabu yaonyeshayo wazi kwamba mimi ni mtume yalifanyika miongoni mwenu kwa uvumilivu wote.'),
(2019705,69,47,12,13,'Je, mlipungukiwa nini zaidi kuliko makanisa mengine, isipokuwa tu kwamba mimi kwa upande wangu sikuwasumbueni kupata msaada wenu? Samahani kwa kuwakoseeni haki hiyo!'),
(2019706,69,47,12,14,'Sasa niko tayari kabisa kuja kwenu mara ya tatu, na sitawasumbua. Maana ninachotafuta si mali zenu, bali ni ninyi wenyewe. Ni kawaida ya wazazi kuwawekea watoto wao akiba, na si watoto kuwawekea wazazi wao.'),
(2019707,69,47,12,15,'Mimi ni radhi kabisa kutumia nilicho nacho, na hata kujitolea mimi mwenyewe kabisa, kwa faida ya roho zenu. Je, mtanipenda kidogo ati kwa kuwa mimi nawapenda ninyi mno?'),
(2019708,69,47,12,16,'Basi, mtakubali kwamba sikuwa mzigo kwenu. Lakini labda mtu mwingine atasema: "Kwa vile Paulo ni mwerevu, amewafanyieni ulaghai."'),
(2019709,69,47,12,17,'Je, mimi niliwanyonyeni kwa njia ya mjumbe yeyote niliyemtuma kwenu?'),
(2019710,69,47,12,18,'Mimi nilimwita Tito, nikamtuma kwenu na ndugu yetu mwingine. Je, Tito aliwanyonyeni? Je, hamjui kwamba sisi tumekuwa tukiongozwa na roho yuleyule, na mwenendo wetu ni mmoja?'),
(2019711,69,47,12,19,'Labda mnafikiri kwamba mpaka sasa tumekuwa tukijitetea wenyewe mbele yenu! Lakini, tunasema mambo haya mbele ya Mungu, tukiwa tumeungana na Kristo. Mambo hayo, yote, wapenzi wangu, ni kwa ajili ya kuwajenga ninyi.'),
(2019712,69,47,12,20,'Naogopa, huenda nitakapokuja kwenu nitawakuta katika hali nisiyopenda, nami itanilazimu kuwa katika hali msiyoipenda. Naogopa huenda kukawa na ugomvi, wivu, uhasama, ubishi, masengenyano, kunong`ona, majivuno na fujo kati yenu.'),
(2019713,69,47,12,21,'Naogopa huenda hapo nitakapokuja safari ijayo Mungu wangu atanifanya niaibike mbele yenu, nami nitaomboleza kwa ajili ya wengi wa wale waliotenda dhambi lakini hawakujutia huo uchafu, tamaa zao mbaya na uzinzi waliokuwa wamefanya.'),
(2019714,69,47,13,1,'Hii ni mara yangu ya tatu kuja kwenu. "Kila tatizo litatatuliwa kwa ushahidi wa watu wawili au watatu," yasema Maandiko.'),
(2019715,69,47,13,2,'Nilikwisha sema, na kama ilivyokuwa safari ya pili, sasa nasema tena nikiwa mbali: wale wote waliotenda uovu bila kutubu, na pia wale wengine, nitakapokuja, watakiona cha mtema kuni.'),
(2019716,69,47,13,3,'Mtajionea wenyewe kwamba Kristo anasema ndani yangu. Kwenu Kristo si dhaifu; bali nguvu yake yafanya kazi miongoni mwenu.'),
(2019717,69,47,13,4,'Maana hata kama alisulubiwa kwa sababu ya udhaifu, lakini sasa anaishi kwa uwezo wa Mungu. Sisi pia tu dhaifu kwa kuungana naye lakini tutaishi naye kwa uwezo wa Mungu kwa ajili yenu.'),
(2019718,69,47,13,5,'Jichunguzeni ninyi wenyewe mpate kujua kama kweli mnayo imani. Jichunguzeni ninyi wenyewe. Je, hamjui kwamba Kristo Yesu yumo ndani yenu? Kama sivyo, basi ninyi mmeshindwa.'),
(2019719,69,47,13,6,'Lakini natumaini kwamba ninyi mnajua kuwa sisi hatukushindwa.'),
(2019720,69,47,13,7,'Tunamwomba Mungu msifanye uovu wowote, lakini si kusudi tuonekane kama watu waliokwisha faulu, bali mpate kutenda mema, hata kama sisi tunaonekana kuwa tumeshindwa.'),
(2019721,69,47,13,8,'Maana hatuwezi kuupinga ukweli; uwezo tulio nao ni wa kuuendeleza ukweli.'),
(2019722,69,47,13,9,'Tunafurahi kwamba sisi tu dhaifu, lakini ninyi mna nguvu; kwa hiyo tunaomba mpate kuwa wakamilifu.'),
(2019723,69,47,13,10,'Basi, ninaandika barua hii nikiwa mbali, ili nitakapofika kwenu nisilazimike kuwa mkali kwenu kwa kutumia ule uwezo alionipa Bwana; naam, uwezo wa kujenga na si wa kubomoa.'),
(2019724,69,47,13,11,'Kwa sasa, ndugu, kwaherini! Muwe na ukamilifu, shikeni mashauri yangu, muwe na nia moja; kaeni kwa amani. Naye Mungu wa mapendo na amani atakuwa pamoja nanyi.'),
(2019725,69,47,13,12,'Salimianeni kwa ishara ya upendo. Watu wote wa Mungu huku wanawasalimuni.'),
(2019726,69,47,13,13,'Neema ya Bwana Yesu Kristo na upendo wa Mungu na umoja wa Roho Mtakatifu, viwe nanyi nyote.'),
(2019727,69,48,1,1,'Mimi Paulo mtume,'),
(2019728,69,48,1,2,'na ndugu wote walio pamoja nami, tunayaandikia makanisa yaliyoko Galatia. Mimi nimepata kuwa mtume si kutokana na mamlaka ya binadamu, wala si kwa nguvu ya mtu, bali kwa uwezo wa Yesu Kristo na wa Mungu Baba aliyemfufua Yesu kutoka wafu.'),
(2019729,69,48,1,3,'Tunawatakieni neema na amani kutoka kwa Mungu Baba yetu na kutoka kwa Bwana Yesu Kristo.'),
(2019730,69,48,1,4,'Kristo alijitoa mwenyewe kwa ajili ya dhambi zetu kufuatana na mapenzi ya Mungu wetu na Baba, ili apate kutuokoa katika ulimwengu huu mbaya wa sasa.'),
(2019731,69,48,1,5,'Kwake yeye uwe utukufu milele! Amina.'),
(2019732,69,48,1,6,'Nashangaa kwamba muda mfupi tu umepita, nanyi mnamwasi yule aliyewaita kwa neema ya Kristo, mkafuata Habari Njema ya namna nyingine.'),
(2019733,69,48,1,7,'Lakini hakuna "Habari Njema" nyingine. Ukweli ni kwamba wako watu wanaowavurugeni, watu wanaotaka kuipotosha Habari Njema ya Kristo.'),
(2019734,69,48,1,8,'Lakini, hata kama mmoja wetu au malaika kutoka mbinguni, atawahubirieni Habari Njema tofauti na ile tuliyowahubirieni sisi, basi huyo na alaaniwe!'),
(2019735,69,48,1,9,'Tulikwisha sema, na sasa nasema tena: kama mtu yeyote anawahubirieni Habari Njema ya aina nyingine, tofauti na ile mliyokwisha pokea, huyo na alaaniwe!'),
(2019736,69,48,1,10,'Sasa nataka kibali cha nani: cha binadamu, ama cha Mungu? Au je, nataka kuwapendeza watu? Kama ningefanya hivyo, mimi singekuwa kamwe mtumishi wa Kristo.'),
(2019737,69,48,1,11,'Ndugu, napenda mfahamu kwamba ile Habari Njema niliyoihubiri si ujumbe wa kibinadamu.'),
(2019738,69,48,1,12,'Wala mimi sikuipokea kutoka kwa binadamu, wala sikufundishwa na mtu. Yesu Kristo mwenyewe ndiye aliyenifunulia.'),
(2019739,69,48,1,13,'Bila shaka mlikwisha sikia jinsi nilivyokuwa ninaishi zamani kwa kuzingatia dini ya Kiyahudi, na jinsi nilivyolitesa kanisa la Mungu kupita kiasi na kutaka kuliharibu kabisa.'),
(2019740,69,48,1,14,'Naam, mimi niliwashinda wengi wa wananchi wenzangu wa rika langu katika kuizingatia dini ya Kiyahudi, nikajitahidi sana kuyashika mapokeo ya wazee wetu.'),
(2019741,69,48,1,15,'Lakini Mungu, kwa neema yake, alikuwa ameniteua hata kabla sijazaliwa, akaniita nimtumikie.'),
(2019742,69,48,1,16,'Mara tu alipoamua kunifunulia Mwanae kusudi niihubiri Habari Njema yake kwa watu wa mataifa mengine, bila kutafuta maoni ya binadamu,'),
(2019743,69,48,1,17,'na bila kwenda kwanza Yerusalemu kwa wale waliopata kuwa mitume kabla yangu, nilikwenda kwanza Arabia, kisha nikarudi tena Damasko.'),
(2019744,69,48,1,18,'Ilikuwa tu baada ya miaka mitatu, ndipo nilipokwenda Yerusalemu kuonana na Kefa; nilikaa kwake siku kumi na tano.'),
(2019745,69,48,1,19,'Lakini sikuwaona mitume wengine isipokuwa Yakobo, ndugu yake Bwana.'),
(2019746,69,48,1,20,'Haya ninayowaandikieni, Mungu anajua; sisemi uongo.'),
(2019747,69,48,1,21,'Baadaye nilikwenda katika tarafa za Siria na Kilikia.'),
(2019748,69,48,1,22,'Wakati huo, mimi binafsi sikujulikana kwa jumuiya za Wakristo kule Yudea.'),
(2019749,69,48,1,23,'Walichokuwa wanajua ni kile tu walichosikia: "Mtu yule aliyekuwa akitutesa hapo awali, sasa anaihubiri imani ileile aliyokuwa anajaribu kuiangamiza."'),
(2019750,69,48,1,24,'Basi, wakamtukuza Mungu kwa sababu yangu.'),
(2019751,69,48,2,1,'Baada ya miaka kumi na minne, nilikwenda tena Yerusalemu pamoja na Barnaba; nilimchukua pia Tito pamoja nami.'),
(2019752,69,48,2,2,'Kwenda kwangu kulitokana na ufunuo alionipa Mungu. Katika kikao cha faragha niliwaeleza hao viongozi ujumbe wa Habari Njema niliohubiri kwa watu wa mataifa. Nilifanya hivyo kusudi kazi yangu niliyokuwa nimefanya, na ile ninayofanya sasa isije ikawa bure.'),
(2019753,69,48,2,3,'Lakini, hata mwenzangu Tito, ambaye ni Mgiriki, hakulazimika kutahiriwa,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019754,69,48,2,4,'ingawa kulikuwa na ndugu wengine wa uongo waliotaka atahiriwe. Watu hawa walijiingiza kwa ujanja na kupeleleza uhuru wetu tulio nao katika kuungana na Kristo Yesu, ili wapate kutufanya watumwa.'),
(2019755,69,48,2,5,'Hatukukubaliana nao hata kidogo ili ukweli wa Habari Njema ubaki nanyi daima.'),
(2019756,69,48,2,6,'Lakini watu hawa wanaosemekana kuwa ni viongozi--kama kweli walikuwa hivyo au sivyo, kwangu si kitu, maana Mungu hahukumu kwa kuangalia mambo ya nje--watu hawa hawakuwa na kitu cha kuongeza katika Habari hii Njema kama niihubirivyo.'),
(2019757,69,48,2,7,'Badala yake, walitambua kwamba Mungu alikuwa amenituma kuhubiri Habari Njema kwa watu wa mataifa mengine kama vile Petro alivyokuwa ametumwa kuihubiri kwa Wayahudi.'),
(2019758,69,48,2,8,'Maana, yule aliyemwezesha Petro kuwa mtume kwa Wayahudi, ndiye aliyeniwezesha nami pia kuwa mtume kwa watu wa mataifa mengine.'),
(2019759,69,48,2,9,'Basi, Yakobo, Kefa na Yohane, ambao waonekana kuwa viongozi wakuu, walitambua kwamba Mungu alinijalia neema hiyo, wakatushika sisi mkono, yaani Barnaba na mimi, iwe ishara ya ushirikiano. Sisi ilitupasa tukafanye kazi kati ya watu wa mataifa mengine, na wao kati ya Wayahudi.'),
(2019760,69,48,2,10,'Wakatuomba lakini kitu kimoja: tuwakumbuke maskini; jambo ambalo nimekuwa nikijitahidi kutekeleza.'),
(2019761,69,48,2,11,'Lakini Kefa alipofika Antiokia nilimpinga waziwazi maana alikuwa amekosea.'),
(2019762,69,48,2,12,'Awali, kabla ya watu kadhaa waliokuwa wametumwa na Yakobo kuwasili hapo, Petro alikuwa akila pamoja na watu wa mataifa mengine. Lakini, baada ya hao watu kufika, aliacha kabisa kula pamoja na watu wa mataifa mengine, kwa kuogopa kikundi cha waliosisitiza tohara.'),
(2019763,69,48,2,13,'Hata ndugu wengine Wayahudi walimuunga mkono Petro katika kitendo hiki cha unafiki, naye Barnaba akakumbwa na huo unafiki wao.'),
(2019764,69,48,2,14,'Basi, nilipoona kuwa msimamo wao kuhusu ukweli wa Habari Njema haukuwa umenyooka, nikamwambia Kefa mbele ya watu wote: "Ingawa wewe ni Myahudi, unaishi kama watu wa mataifa mengine na si kama Myahudi! Unawezaje, basi kujaribu kuwalazimisha watu wa mataifa mengine kuishi kama Wayahudi?"'),
(2019765,69,48,2,15,'Kweli, sisi kwa asili ni Wayahudi, na si watu wa mataifa mengine hao wenye dhambi!'),
(2019766,69,48,2,16,'Lakini, tunajua kwa hakika kwamba mtu hawezi kukubaliwa kuwa mwadilifu kwa kuitii Sheria, bali tu kwa kumwamini Yesu Kristo. Na sisi pia tumemwamini Yesu Kristo ili tupate kukubaliwa kuwa waadilifu kwa njia ya imani yetu kwa Kristo, na si kwa kuitii Sheria.'),
(2019767,69,48,2,17,'Sasa, ikiwa katika kutafuta kukubaliwa kuwa waadilifu kwa kuungana na Kristo sisi tunaonekana kuwa wenye dhambi, je, jambo hili lina maana kwamba Kristo anasaidia utendaji wa dhambi? Hata kidogo!'),
(2019768,69,48,2,18,'Lakini ikiwa ninajenga tena kile nilichokwisha bomoa, basi nahakikisha kwamba mimi ni mhalifu.'),
(2019769,69,48,2,19,'Maana, kuhusu Sheria hiyo, mimi nimekufa; Sheria yenyewe iliniua, nipate kuishi kwa ajili ya Mungu. Mimi nimeuawa pamoja na Kristo msalabani,'),
(2019770,69,48,2,20,'na sasa naishi, lakini si mimi tena, bali Kristo anaishi ndani yangu. Maisha haya ninayoishi sasa naishi kwa imani, imani katika Mwana wa Mungu aliyenipenda hata akayatoa maisha yake kwa ajili yangu.'),
(2019771,69,48,2,21,'Sipendi kuikataa neema ya Mungu. Kama mtu huweza kukubaliwa kuwa mwadilifu kwa njia ya Sheria, basi, Kristo alikufa bure!'),
(2019772,69,48,3,1,'Enyi Wagalatia, mmekuwa wajinga kweli! Ni nani aliyewaloga? Habari juu ya kusulubiwa kwake Yesu Kristo ilielezwa waziwazi mbele ya macho yenu.'),
(2019773,69,48,3,2,'Napenda kujua tu kitu kimoja kutoka kwenu: Je, mlipokea Roho wa Mungu kwa sababu ya kutimiza matakwa ya Sheria ama kwa sababu ya kuisikia na kuiamini Habari Njema?'),
(2019774,69,48,3,3,'Je, mu wajinga kiasi hicho? Ninyi mlianza yote kwa msaada wa Roho je, mnataka sasa kumaliza kwa nguvu zenu wenyewe?'),
(2019775,69,48,3,4,'Je, mambo yale yote yaliyowapata ninyi yamekuwa bure tu? Haiwezekani!'),
(2019776,69,48,3,5,'Je, Mungu huwajalia Roho na kutenda miujiza kati yenu ati kwa sababu mnatimiza yanayotakiwa na sheria, ama kwa sababu mnasikia Habari Njema na kuiamini?'),
(2019777,69,48,3,6,'Chukueni kwa mfano habari za Abrahamu: yeye alimwamini Mungu, naye Mungu akamkubali kuwa mwadilifu.'),
(2019778,69,48,3,7,'Sasa basi jueni kwamba watu wenye kumwamini ndio walio watoto halisi wa Abrahamu.'),
(2019779,69,48,3,8,'Maandiko Matakatifu yalionyesha kabla kwamba Mungu atawakubali watu wa mataifa kuwa waadilifu kwa njia ya imani. Hivyo Maandiko Matakatifu yalitangulia kumtangazia Abrahamu Habari Njema: "Katika wewe mataifa yote yatabarikiwa."'),
(2019780,69,48,3,9,'Basi, wale walio na imani wanabarikiwa pamoja na Abrahamu aliyeamini.'),
(2019781,69,48,3,10,'Lakini wote wanaotegemea tu kutimiza yanayotakiwa na Sheria, wako chini ya laana. Maana, Maandiko Matakatifu yasema: "Yeyote asiyeshika na kutimiza yote yaliyoandikwa katika kitabu cha Sheria, yuko chini ya laana."'),
(2019782,69,48,3,11,'Ni dhahiri kwamba Sheria haiwezi kumfanya mtu akubaliwe kuwa mwadilifu; maana Maandiko Matakatifu yasema: "Mwadilifu kwa imani ataishi."'),
(2019783,69,48,3,12,'Lakini Sheria haitegemei imani, ila Maandiko yasema: "Mwenye kutimiza yanayotakiwa na Sheria ataishi."'),
(2019784,69,48,3,13,'Kristo alitukomboa kutoka katika laana ya Sheria kwa kujitwalia laana hiyo kwa ajili yetu; maana Maandiko yanasema: "Yeyote aliyetundikwa msalabani amelaaniwa."'),
(2019785,69,48,3,14,'Jambo hili lilifanyika kusudi ile baraka aliyopewa Abrahamu iwashukie watu wa mataifa mengine kwa njia ya Kristo, na ili kwa imani, tumpokee yule Roho ambaye Mungu alituahidia.'),
(2019786,69,48,3,15,'Ndugu, nitawapeni mfano kutoka maisha yetu ya kila siku. Fikirini juu ya mkataba kati ya watu wawili. Mkataba ukisha fanyika na kutiwa sahihi hapana mtu anayeuweka kando au kuuongezea kitu.'),
(2019787,69,48,3,16,'Basi, Abrahamu alipewa ahadi, yeye pamoja na mzawa wake. Maandiko hayasemi: "Na wazawa wake," yaani wengi, bali yasema, "Na mzawa wake," yaani mmoja, naye ndiye Kristo.'),
(2019788,69,48,3,17,'Ninachotaka kusema ni hiki: Mungu alifanya agano lake akalithibitisha; Sheria ambayo ilitokea miaka mia nne na thelathini baadaye, haiwezi kulitangua hilo agano wala kuibatilisha hiyo ahadi.'),
(2019789,69,48,3,18,'Maana, kama urithi ya Mungu inategemea Sheria, basi, haiwezi kutegemea tena ahadi ya Mungu. Kumbe, lakini Mungu alimkirimia Abrahamu kwa sababu aliahidi.'),
(2019790,69,48,3,19,'Ya nini basi, Sheria? Iliongezwa hapo ili kuonyesha uhalifu ni kitu gani, mpaka atakapokuja yule mzawa wa Abrahamu aliyepewa ile ahadi. Sheria ililetwa na malaika kwa mkono wa mpatanishi.'),
(2019791,69,48,3,20,'Ama hakika, mpatanishi hahitajiwi ikiwa jambo lenyewe lamhusu mtu mmoja; na Mungu ni mmoja.'),
(2019792,69,48,3,21,'Je, Sheria inapingana na ahadi za Mungu? Hata kidogo! Maana, kama kungalitolewa sheria ambayo ingeweza kuwapa watu uzima, basi, tungeweza kukubaliwa kuwa waadilifu kwa njia ya Sheria.'),
(2019793,69,48,3,22,'Lakini sivyo; Maandiko Matakatifu yamekwisha sema kwamba ulimwengu wote upo chini ya utawala wa dhambi; na hivyo, kwa kumwamini Yesu Kristo, wenye kuamini watimiziwe ile ahadi.'),
(2019794,69,48,3,23,'Kabla ya kujaliwa imani, Sheria ilitufanya wafungwa mpaka imani hiyo iliyokuwa inakuja ifunuliwe.'),
(2019795,69,48,3,24,'Basi, hiyo Sheria ilikuwa kama mlezi wetu mpaka alipokuja Kristo, ili kwa njia ya imani, tukubaliwe kuwa waadilifu.'),
(2019796,69,48,3,25,'Tangu kufika kwa hiyo imani, Sheria si mlezi wetu tena.'),
(2019797,69,48,3,26,'Kwa njia ya imani, ninyi nyote mmekuwa watoto wa Mungu katika kuungana na Kristo.'),
(2019798,69,48,3,27,'Ninyi nyote mliobatizwa mkaungana na Kristo ni kama vile mmemvaa Kristo.'),
(2019799,69,48,3,28,'Hivyo, hakuna tena tofauti kati ya Myahudi na Mgiriki, mtumwa na mtu huru, mwanamume na mwanamke. Nyote ni kitu kimoja katika kuungana na Kristo Yesu.'),
(2019800,69,48,3,29,'Ikiwa ninyi ni wa Kristo, basi ni wazawa wa Abrahamu, na mtapokea yale aliyoahidi Mungu.'),
(2019801,69,48,4,1,'Basi, nasema hivi: mrithi, akiwa bado mtoto, hawi tofauti na mtumwa ingawaje mali yote ni yake.'),
(2019802,69,48,4,2,'Wakati huo wote yuko chini ya walezi na wadhamini mpaka wakati ule uliowekwa na baba yake.'),
(2019803,69,48,4,3,'Hali kadhalika na sisi tulipokuwa bado watoto, tulikuwa watumwa wa pepo watawala wa ulimwengu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019804,69,48,4,4,'Lakini wakati ule maalumu ulipotimia, Mungu alimtuma Mwanawe aliyezaliwa na mwanamke, akaishi chini ya Sheria'),
(2019805,69,48,4,5,'apate kuwakomboa wale waliokuwa chini ya Sheria ili sisi tufanywe wana wa Mungu.'),
(2019806,69,48,4,6,'Kwa vile sasa ninyi ni wana, Mungu amemtuma Roho wa Mwanae mioyoni mwenu, Roho ambaye hulia "Aba," yaani "Baba."'),
(2019807,69,48,4,7,'Basi, wewe si mtumwa tena, bali mwana. Na ikiwa ni mwana, basi, wewe utapokea yote Mungu aliyowawekea watoto wake.'),
(2019808,69,48,4,8,'Zamani hamkumjua Mungu na hivyo mkatumikia miungu isiyo miungu kweli.'),
(2019809,69,48,4,9,'Lakini sasa, kwa vile mnamjua Mungu, au tuseme mnajulikana na Mungu, mnawezaje tena kurudi kwa wale pepo maskini na dhaifu hata kutaka kuwatumikia tena?'),
(2019810,69,48,4,10,'Bado mnaadhimisha siku, miezi na miaka!'),
(2019811,69,48,4,11,'Nahofu kwamba labda kazi niliyoifanya kwa ajili yenu imepotea bure!'),
(2019812,69,48,4,12,'Ndugu, nawasihi muwe kama mimi, kwa vile hata mimi nimekuwa kama ninyi. Hamkunitendea ubaya wowote.'),
(2019813,69,48,4,13,'Mnajua kwamba ugonjwa wangu ndio ulionipatia fursa ya kuwahubirieni Habari Njema kwa mara ya kwanza.'),
(2019814,69,48,4,14,'Hata hivyo, wakati ule hamkunidharau wala kunikataa kwa sababu ya udhaifu wangu ingawa mlishawishiwa kufanya hivyo; lakini mlinipokea kama malaika wa Mungu, kama vile ningekuwa Kristo Yesu mwenyewe.'),
(2019815,69,48,4,15,'Mlikuwa wenye furaha; sasa kumetokea nini? Naapa kwamba wakati ule mngaliweza hata kuyang`oa macho yenu na kunipa mimi.'),
(2019816,69,48,4,16,'Je, sasa nimekuwa adui yenu kwa sababu ya kuwaambieni ukweli?'),
(2019817,69,48,4,17,'Hao watu wengine wanawahangaikia ninyi, lakini nia zao si njema. Wanataka kuwatenganisha nami ili ninyi muwahangaikie wao.'),
(2019818,69,48,4,18,'Kwa kweli ni jambo jema daima kuwahangaikia wengine katika mambo mema, na si tu wakati mimi nipo pamoja nanyi.'),
(2019819,69,48,4,19,'Watoto wangu, kama vile mama mja mzito anavyotaabika wakati wa kujifungua, mimi nataabika tena kwa ajili yenu mpaka hapo hali yake Kristo itakapoundwa ndani yenu.'),
(2019820,69,48,4,20,'Laiti ningekuwa pamoja nanyi sasa, maana ningalipata msimamo ufaao juu yenu! Nina wasiwasi sana nanyi!'),
(2019821,69,48,4,21,'Niambieni, enyi mnaopenda kutawaliwa na sheria: Je, mnasikia isemavyo Sheria?'),
(2019822,69,48,4,22,'Imeandikwa katika Maandiko Matakatifu kwamba Abrahamu alikuwa na watoto wawili: mmoja kwa mwanamke mtumwa, na wa pili kwa mwanamke huru.'),
(2019823,69,48,4,23,'Yule wa mwanamke mtumwa alizaliwa kama kawaida, lakini yule wa mwanamke huru alizaliwa kutokana na ahadi ya Mungu.'),
(2019824,69,48,4,24,'Mambo hayo yamekuwa mfano; mama hao wawili ni mfano wa maagano mawili; la kwanza ni lile lililofanyika mlimani Sinai, mwakilishi wake ni Hagari, na watoto wake wanazaliwa utumwani.'),
(2019825,69,48,4,25,'Hagari anawakilisha mlima Sinai ulioko Arabia, na ni mfano wa Yerusalemu ya sasa, ulio mtumwa pamoja na watoto wake.'),
(2019826,69,48,4,26,'Lakini Yerusalemu ya juu mbinguni ni mji ulio huru, nao ni mama yetu.'),
(2019827,69,48,4,27,'Maana imeandikwa: "Furahi, ewe uliye tasa usiyezaa; paaza sauti wewe usiyepata kujifungua mtoto; maana watoto wa yule aliyeachwa ni wengi zaidi kuliko wa yule aliye na mume."'),
(2019828,69,48,4,28,'Sasa, basi, ndugu zangu, ninyi ni watoto wa Mungu kutokana na ahadi yake kama alivyokuwa Isaka.'),
(2019829,69,48,4,29,'Lakini kama vile siku zile yule mtoto aliyezaliwa kwa njia ya kawaida alimdhulumu yule aliyezaliwa kwa uwezo wa Roho wa Mungu, vivyo hivyo na siku hizi.'),
(2019830,69,48,4,30,'Lakini Maandiko Matakatifu yasemaje? Yasema: "Mfukuze mama mtumwa pamoja na mwanawe; maana mtoto wa mtumwa hatarithi pamoja na mtoto wa mama huru."'),
(2019831,69,48,4,31,'Kwa hiyo, basi, ndugu, sisi si watoto wa mtumwa bali wa mama huru.'),
(2019832,69,48,5,1,'Kristo alitupa uhuru akataka tubaki huru. Basi, simameni imara wala msikubali tena kuwa chini ya nira ya utumwa.'),
(2019833,69,48,5,2,'Sikilizeni! Ni mimi Paulo ninayesema nanyi! Kama mkikubali kutahiriwa, Kristo hatawafaidia chochote.'),
(2019834,69,48,5,3,'Nasema tena wazi: kila anayekubali kutahiriwa itambidi kuishika Sheria yote.'),
(2019835,69,48,5,4,'Kama mnatazamia kukubaliwa kuwa waadilifu kwa njia ya Sheria, basi, mmejitenga mbali na Kristo; mko nje ya neema ya Mungu.'),
(2019836,69,48,5,5,'Kwa upande wetu, lakini, sisi tunatumaini kwamba kwa nguvu ya Roho tunakubaliwa kuwa waadilifu kwa njia ya imani.'),
(2019837,69,48,5,6,'Maana ikiwa tumeungana na Kristo Yesu, kutahiriwa au kutotahiriwa hakuna maana; cha maana ni imani ifanyayo kazi kwa mapendo. ic'),
(2019838,69,48,5,7,'Mwenendo wenu ulikuwa mzuri! Nani, basi aliyewazuia kuuzingatia ukweli?'),
(2019839,69,48,5,8,'Aliyesababisha hali hiyo si Mungu ambaye amewaiteni.'),
(2019840,69,48,5,9,'"chachu kidogo tu huchachusha donge lote la unga!"'),
(2019841,69,48,5,10,'Kutokana na kuungana kwetu na Bwana, nina tumaini kubwa kwamba ninyi hamtakuwa na msimamo tofauti nami. Tena yeyote huyo anayewavurugeni--awe nani au nani--hakika ataadhibiwa.'),
(2019842,69,48,5,11,'Na kwa upande wangu, ndugu zangu, kama bado ninahubiri kwamba kutahiriwa ni lazima, kwa nini basi, bado ninadhulumiwa? Kama ingalikuwa hivyo, mahubiri yangu juu ya msalaba wa Kristo yasingalileta aibu yoyote.'),
(2019843,69,48,5,12,'Laiti hao wanaowavurugeni wangejikatakata wenyewe!'),
(2019844,69,48,5,13,'Ninyi, ndugu, mliitwa muwe watu huru. Lakini uhuru huo usiwe kisingizio cha kutawaliwa na tamaa za kidunia; ila mnapaswa kutumikiana kwa upendo.'),
(2019845,69,48,5,14,'Maana Sheria yote hutimizwa katika kushika amri hii moja: "Mpende jirani yako kama unavyojipenda mwenyewe."'),
(2019846,69,48,5,15,'Lakini ikiwa mtaumana na kutafunana kama wanyama, jihadharini msije mkaangamizana wenyewe kwa wenyewe!'),
(2019847,69,48,5,16,'Basi, nasema hivi: mwenendo wenu na uongozwe na Roho, nanyi hamtafuata tena tamaa za kidunia.'),
(2019848,69,48,5,17,'Maana, tamaa za kidunia hupingana na matakwa ya Roho; na matakwa ya Roho hupingana na tamaa za kidunia. Mambo hayo mawili hayaafikiani; kwa sababu hiyo hamwezi kufanya yale mnayotaka ninyi wenyewe.'),
(2019849,69,48,5,18,'Kama mkiongozwa na Roho, basi, hamko tena chini ya Sheria.'),
(2019850,69,48,5,19,'Basi, matendo ya kidunia yanajulikana: uzinzi, uasherati, ufisadi;'),
(2019851,69,48,5,20,'kuabudu sanamu, uchawi, uadui, ugomvi, wivu, hasira, choyo, mabishano, mafarakano;'),
(2019852,69,48,5,21,'husuda, ulevi, ulafi na mambo mengine kama hayo. Nawaambieni tena kama nilivyokwisha sema: watu wanaotenda mambo hayo hawatakuwa na nafasi yao katika ufalme wa Mungu.'),
(2019853,69,48,5,22,'Lakini matokeo ya kuongozwa na Roho ni mapendo, furaha, amani, uvumilivu, wema, fadhili, uaminifu,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019854,69,48,5,23,'upole na kuwa na kiasi. Hakuna Sheria inayoweza kupinga mambo hayo.'),
(2019855,69,48,5,24,'Wale walio wa Kristo wameisulubisha hali yao ya kidunia pamoja na mawazo yake mabaya na tamaa zake.'),
(2019856,69,48,5,25,'Tukiishi kwa msaada wa Roho, na tuufuate mwongozo wake.'),
(2019857,69,48,5,26,'Basi, tusijivune, tusichokozane wala kuoneana wivu.'),
(2019858,69,48,6,1,'Ndugu, kama mkimwona mtu fulani amekosea, basi, ninyi mnaoongozwa na Roho mwonyeni mtu huyo ajirekebishe; lakini fanyeni hivyo kwa upole, mkiwa na tahadhari msije nanyi wenyewe mkajaribiwa.'),
(2019859,69,48,6,2,'Saidianeni kubeba mizigo yenu na hivyo mtatimiza sheria ya Kristo.'),
(2019860,69,48,6,3,'Mtu akijiona kuwa ni kitu, na kumbe si kitu, huyo anajidanganya mwenyewe.'),
(2019861,69,48,6,4,'Lakini kila mmoja na aupime vizuri mwenendo wake mwenyewe. Ukiwa mwema, basi, anaweza kuona fahari juu ya alichofanya bila kuwa na sababu ya kujilinganisha na mtu mwingine.'),
(2019862,69,48,6,5,'Maana kila mmoja anao mzigo wake mwenyewe wa kubeba.'),
(2019863,69,48,6,6,'Mwenye kufundishwa neno la Mungu na amshirikishe mwalimu wake riziki zake.'),
(2019864,69,48,6,7,'Msidanganyike; Mungu hafanyiwi dhihaka. Alichopanda mtu ndicho atakachovuna.'),
(2019865,69,48,6,8,'Apandaye katika tamaa za kidunia, atavuna humo uharibifu; lakini akipanda katika Roho, atavuna kutoka kwa Roho uzima wa milele.'),
(2019866,69,48,6,9,'Basi, tusichoke kutenda mema; maana tusipolegea tutavuna mavuno kwa wakati wake.'),
(2019867,69,48,6,10,'Kwa hiyo, tukiwa bado na wakati, tuwatendee watu wote mema, na hasa ndugu wa imani yetu.'),
(2019868,69,48,6,11,'Tazameni jinsi nilivyoandika kwa herufi kubwa, kwa mkono wangu mwenyewe.'),
(2019869,69,48,6,12,'Wale wanaotaka kuonekana wazuri kwa mambo ya mwili ndio wanaotaka kuwalazimisha ninyi mtahiriwe. Wanafanya hivyo kwa sababu moja tu: kusudi wao wenyewe wasije wakadhulumiwa kwa sababu ya msalaba wa Kristo.'),
(2019870,69,48,6,13,'Maana, hao wenyewe waliotahiriwa hawaishiki Sheria; huwataka ninyi mtahiriwe wapate kujivunia alama hiyo mwilini mwenu.'),
(2019871,69,48,6,14,'Lakini mimi sitajivunia kamwe chochote isipokuwa msalaba wa Bwana wetu Yesu Kristo; maana kwa njia ya msalaba huo ulimwengu umesulubiwa kwangu, nami nimesulubiwa kwa ulimwengu.'),
(2019872,69,48,6,15,'Kutahiriwa au kutotahiriwa si kitu; cha maana ni kuwa kiumbe kipya.'),
(2019873,69,48,6,16,'Wanaoufuata mwongozo huo nawatakia amani na huruma; amani na huruma kwa Israeli--Wateule wa Mungu.'),
(2019874,69,48,6,17,'Basi, sasa mtu yeyote asinisumbue tena, maana alama nilizo nazo mwilini mwangu ni zile za Yesu.'),
(2019875,69,48,6,18,'Ndugu, nawatakieni ninyi nyote neema ya Bwana wetu Kristo. Amina.'),
(2019876,69,49,1,1,'Mimi Paulo, mtume wa Kristo Yesu kwa mapenzi ya Mungu, nawaandikia ninyi watu wa Mungu huko Efeso, mlio waaminifu katika kuungana na Kristo Yesu.'),
(2019877,69,49,1,2,'Nawatakieni neema na amani kutoka kwa Mungu Baba yetu na kwa Bwana Yesu Kristo.'),
(2019878,69,49,1,3,'Atukuzwe Mungu na Baba wa Bwana wetu Yesu Kristo! Maana, katika kuungana na Kristo ametubariki kwa kutujalia zawadi zote za kiroho mbinguni.'),
(2019879,69,49,1,4,'Kabla ya kuumbwa ulimwengu, Mungu alituteua tuwe wake katika kuungana na Kristo ili tuwe watakatifu na bila hitilafu mbele yake. Kwa sababu ya upendo wake,'),
(2019880,69,49,1,5,'Mungu alikuwa ameazimia tangu zamani kutuleta kwake kama watoto wake kwa njia ya Yesu Kristo. Ndivyo alivyopenda na kunuia.'),
(2019881,69,49,1,6,'Basi, tumsifu Mungu kwa sababu ya neema yake tukufu katika Mwanae mpenzi!'),
(2019882,69,49,1,7,'Maana kwa damu yake Kristo sisi tunakombolewa, yaani dhambi zetu zinaondolewa. Ndivyo ulivyo ukuu wa neema yake'),
(2019883,69,49,1,8,'aliotukirimia bila kipimo! Kwa hekima na ujuzi wake wote'),
(2019884,69,49,1,9,'Mungu alitekeleza kile alichonuia, akatujulisha mpango wake uliofichika, ambao alikuwa ameazimia kuutekeleza kwa njia ya Kristo.'),
(2019885,69,49,1,10,'Mpango huo ambao angeutimiza wakati utimiapo ni kukusanya pamoja viumbe vyote, kila kitu mbinguni na duniani, chini ya Kristo.'),
(2019886,69,49,1,11,'Kila kitu hufanywa kufuatana na mpango na uamuzi wa Mungu; naye Mungu ametuteua sisi tuwe watu wake kwa mapenzi yake katika kuungana na Kristo, kufuatana na azimio alilofanya tangu mwanzo.'),
(2019887,69,49,1,12,'Basi, sisi tuliotangulia kumtumainia Kristo tunapaswa kuusifu utukufu wa Mungu!'),
(2019888,69,49,1,13,'Nanyi pia watu wa mataifa mengine, mliusikia ujumbe wa kweli yaani Habari Njema iliyowaletea wokovu, mkamwamini Kristo; naye Mungu, ili kuonyesha kuwa ninyi ni wake, akawapiga mhuri kwa kuwapeni yule Roho Mtakatifu aliyetuahidia.'),
(2019889,69,49,1,14,'Huyu Roho ni dhamana ya kurithi yote yale Mungu aliyowaahidia watu wake, na jambo hili latuhakikishia kwamba Mungu atawakomboa kabisa wote walio wake. Tuusifu utukufu wake!'),
(2019890,69,49,1,15,'Kwa sababu hiyo, tangu niliposikia juu ya imani yenu kwa Bwana Yesu na mapendo yenu kwa watu wa Mungu,'),
(2019891,69,49,1,16,'sijaacha kamwe kumshukuru Mungu kwa ajili yenu. Ninawakumbuka katika sala zangu'),
(2019892,69,49,1,17,'ili Mungu wa Bwana wetu Yesu Kristo Baba mtukufu, awajalieni Roho wake atakayewapa hekima na kuwafunulieni Mungu mpate kumjua.'),
(2019893,69,49,1,18,'Namwomba Mungu aifunue mioyo yenu iweze kuuona mwanga wake, mpate kutambua lile tumaini alilowaitieni na utukufu mkuu wa zawadi alizowawekea watu wake,'),
(2019894,69,49,1,19,'mpate kutambua jinsi uwezo wake ulivyo mkuu mno kwa ajili yetu sisi tunaoamini. Uwezo huo unaofanya kazi ndani yetu, ni sawa na nguvu ile kuu mno'),
(2019895,69,49,1,20,'aliyomfufua nayo Kristo kutoka wafu, akamketisha kulia kwake mbinguni.'),
(2019896,69,49,1,21,'Huko, Kristo anatawala juu ya kila tawala, mamlaka, enzi na ukuu; anatawala juu ya kila cheo kiwezacho kutajwa katika ulimwengu huu na katika ulimwengu ujao.'),
(2019897,69,49,1,22,'Mungu ameweka vitu vyote chini ya miguu yake, akamkabidhi kwa kanisa akiwa mkuu wa vitu vyote.'),
(2019898,69,49,1,23,'Kanisa ni mwili wa Kristo, na ukamilifu wake yeye anayekamilisha vitu vyote kila mahali.'),
(2019899,69,49,2,1,'Ninyi mlikuwa mmekufa kwa sababu ya makosa na dhambi zenu.'),
(2019900,69,49,2,2,'Wakati ule mliishi kufuatana na mtindo mbaya wa ulimwengu huu, mkawa mnamtii mtawala wa pepo wenye nguvu wa anga, pepo ambao huwatawala sasa watu wasiomtii Mungu.'),
(2019901,69,49,2,3,'Na hata sisi sote tulikuwa kama wao; tuliishi kufuatana na tamaa zetu za kidunia na kufanya tu mambo yale yaliyoipendeza miili na akili zetu. Kidunia, sisi kama vile pia wao, tulistahili ghadhabu ya Mungu.'),
(2019902,69,49,2,4,'Lakini Mungu ni mwenye huruma nyingi. Alitupenda kwa mapendo yasiyopimika,'),
(2019903,69,49,2,5,'hata, ingawa tulikuwa tumekufa kwa sababu ya dhambi, alitufanya hai pamoja na Kristo. Kwa neema ya Mungu ninyi mmeokolewa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019904,69,49,2,6,'Kwa kuungana na Kristo Yesu, Mungu alitufufua pamoja naye, tukatawale pamoja naye mbinguni.'),
(2019905,69,49,2,7,'Ndivyo alivyopenda kuonyesha kwa watu wa nyakati za baadaye, ukuu wa neema yake aliyotujalia kwa ukarimu katika kuungana kwetu na Kristo Yesu.'),
(2019906,69,49,2,8,'Maana, kwa neema ya Mungu mmekombolewa kwa njia ya imani. Jambo hili si matokeo ya juhudi zenu, bali ni zawadi ya Mungu.'),
(2019907,69,49,2,9,'Wala halitokani na matendo yenu wenyewe, asije mtu akajivunia kitu.'),
(2019908,69,49,2,10,'Sisi ni viumbe vyake Mungu, na kwa kuungana na Kristo Yesu, alituumba kwa ajili ya kuishi maisha ya matendo mema aliyotutayarishia tuyatende.'),
(2019909,69,49,2,11,'Ninyi mlio kwa asili watu wa mataifa mengine--mnaoitwa, "wasiotahiriwa" na Wayahudi ambao hujiita, "Waliotahiriwa," (kwa sababu ya kile wanachoifanyia miili yao)--kumbukeni mlivyokuwa zamani.'),
(2019910,69,49,2,12,'Wakati ule ninyi mlikuwa bila Kristo; mlikuwa nje ya jamii ya Israeli; mlikuwa wageni na hamkuwa na sehemu yoyote katika lile agano la zile ahadi. Mlikuwa bila matumaini Mungu hapa duniani.'),
(2019911,69,49,2,13,'Lakini sasa, kwa kuungana na Kristo Yesu, ninyi ambao hapo awali mlikuwa mbali, mmekaribishwa kwa njia ya damu yake Kristo.'),
(2019912,69,49,2,14,'Maana Kristo mwenyewe ametuletea amani kwa kuwafanya Wayahudi na watu wa mataifa mengine kuwa jamii moja. Kwa mwili wake yeye mwenyewe aliubomoa ule ukuta uliowatenganisha na kuwafanya maadui.'),
(2019913,69,49,2,15,'Aliiondoa ile Sheria ya Wayahudi pamoja na amri zake na kanuni zake, ili kutokana na jamii hizo mbili aumbe jamii moja mpya katika umoja naye na hivyo kuleta amani.'),
(2019914,69,49,2,16,'Kwa mwili wake, Kristo aliuangamiza uadui wao; kwa msalaba wake aliziunganisha jamii hizo kuwa moja na kuzipatanisha na Mungu.'),
(2019915,69,49,2,17,'Basi, Kristo alikuja akahubiri Habari Njema ya amani kwenu ninyi watu wa mataifa mengine mliokuwa mbali na Mungu, na pia kwa Wayahudi ambao walikuwa karibu na Mungu.'),
(2019916,69,49,2,18,'Hivyo, kwa njia yake, sisi sote, Wayahudi na watu wa mataifa mengine, tunaweza kumwendea Baba katika Roho mmoja.'),
(2019917,69,49,2,19,'Basi, ninyi si wageni tena, wala si watu wa nje; ninyi ni raia pamoja na watu wa Mungu, na ni watu wa jamaa ya Mungu.'),
(2019918,69,49,2,20,'Mmejengwa juu ya msingi uliowekwa na mitume na manabii, naye Kristo mwenyewe ndiye jiwe kuu la msingi.'),
(2019919,69,49,2,21,'Yeye ndiye mwenye kulitengeneza jengo lote na kulikuza hata liwe hekalu takatifu kwa ajili ya B wana.'),
(2019920,69,49,2,22,'Katika kuungana naye, ninyi pia mnajengwa pamoja na wote wengine, muwe makao ya Mungu kwa njia ya Roho wake.'),
(2019921,69,49,3,1,'Kutokana na hayo, mimi Paulo, mfungwa wa Kristo Yesu kwa ajili yenu, namwomba Mungu.'),
(2019922,69,49,3,2,'Bila shaka mmekwisha sikia kwamba Mungu, kwa neema yake, alinikabidhi kazi hii niifanye kwa faida yenu.'),
(2019923,69,49,3,3,'Mimi nilijulishwa kwa njia ya ufunuo mpango wake uliofichika. (Nimeandika kwa ufupi juu ya jambo hili,'),
(2019924,69,49,3,4,'nanyi mkiyasoma maneno yangu mtaweza kujua jinsi ninavyoielewa siri hiyo ya Kristo.)'),
(2019925,69,49,3,5,'Zamani watu hawakujulishwa siri hiyo; lakini sasa Mungu amewajulisha mitume na manabii wake watakatifu kwa njia ya Roho.'),
(2019926,69,49,3,6,'Siri yenyewe ni hii: kwa njia ya Habari Njema watu wa mataifa mengine wanapata sehemu yao pamoja na Wayahudi katika zile baraka za Mungu; wao ni viungo vya mwili uleule, na wanashiriki ahadi ileile aliyofanya Mungu kwa njia ya Kristo Yesu.'),
(2019927,69,49,3,7,'Mimi nimefanywa kuwa mtumishi wa Habari Njema kwa neema ya pekee aliyonijalia Mungu kwa uwezo wake mkuu.'),
(2019928,69,49,3,8,'Mimi ni mdogo kuliko watu wote wa Mungu; lakini amenijalia neema yake, ili niwahubirie watu wa mataifa utajiri wake Kristo usiopimika,'),
(2019929,69,49,3,9,'tena niwaangazie watu wote waone jinsi mpango wa Mungu uliofichika unavyotekelezwa. Mungu aliye Muumba wa vitu vyote alificha siri hiyo yake tangu milele,'),
(2019930,69,49,3,10,'kusudi, sasa kwa njia ya kanisa, wakuu na wenye enzi wa mbinguni wapate kuitambua hekima ya Mungu iliyo ya namna nyingi.'),
(2019931,69,49,3,11,'Mungu alifanya jambo hilo kufuatana na azimio lake la milele ambalo amelifanya kwa njia ya Kristo Bwana wetu.'),
(2019932,69,49,3,12,'Basi, katika kuungana na Kristo, na kwa njia ya imani katika Kristo, sisi tunathubutu kumkaribia Mungu kwa uhodari.'),
(2019933,69,49,3,13,'Kwa hiyo, nawaombeni msife moyo kwa sababu ya mateso ninayopata kwa ajili yenu, maana hayo ni kwa ajili ya utukufu wenu.'),
(2019934,69,49,3,14,'Kwa sababu hiyo, nampigia magoti Baba,'),
(2019935,69,49,3,15,'aliye asili ya jamaa zote duniani na mbinguni.'),
(2019936,69,49,3,16,'Namwomba Mungu, kadiri ya utajiri wa utukufu wake, awajalieni kwa uwezo wa Roho wake, nguvu ya kuwa imara ndani yenu,'),
(2019937,69,49,3,17,'naye Kristo akae mioyoni mwenu kwa imani. Namwomba mpate kuwa na mzizi na msingi katika mapendo'),
(2019938,69,49,3,18,'kusudi muweze kufahamu pamoja na watu wote wa Mungu jinsi upendo wa Kristo ueneavyo kwa mapana na marefu, kwa kimo na kina.'),
(2019939,69,49,3,19,'Naam, mpate kujua upendo wa Kristo upitao elimu yote, mjazwe kabisa utimilifu wote wa Mungu.'),
(2019940,69,49,3,20,'Kwake yeye ambaye kwa nguvu yake ifanyayo kazi ndani yetu, aweza kufanya mambo makuu zaidi ya yale tuwezayo kuomba au kufikiria;'),
(2019941,69,49,3,21,'kwake Mungu uwe utukufu katika kanisa na katika Kristo Yesu, nyakati zote, milele na milele! Amina.'),
(2019942,69,49,4,1,'Basi, mimi niliye mfungwa kwa kuwa namtumikia Bwana, nawasihi muishi maisha yanayostahili wito mlioitiwa.'),
(2019943,69,49,4,2,'Muwe daima wanyenyekevu, wapole na wenye saburi; vumilianeni ninyi kwa ninyi kwa mapendo.'),
(2019944,69,49,4,3,'Fanyeni bidii ya kuhifadhi umoja uletwao na Roho kwa kuzingatia amani iliyo kati yenu.'),
(2019945,69,49,4,4,'Kuna mwili mmoja na Roho mmoja, kama vile tumaini mliloitiwa na Mungu ni moja.'),
(2019946,69,49,4,5,'Kuna Bwana mmoja, imani moja na ubatizo mmoja;'),
(2019947,69,49,4,6,'kuna Mungu mmoja na Baba wa wote, ambaye yuko juu ya wote, afanya kazi katika yote na yuko katika yote.'),
(2019948,69,49,4,7,'Kila mmoja wetu amepewa neema kadiri ya kipimo alichojaliwa na Kristo.'),
(2019949,69,49,4,8,'Kama yasemavyo Maandiko: "Alipopaa mbinguni juu kabisa, alichukua mateka; aliwapa watu zawadi."'),
(2019950,69,49,4,9,'Basi, inaposemwa: "alipaa juu," ina maana gani? Maana yake ni kwamba, kwanza alishuka mpaka chini kabisa duniani.'),
(2019951,69,49,4,10,'Basi, huyo aliyeshuka hapa duniani, ndiye aliyepaa juu ya mbingu zote apate kuujaza ulimwengu.'),
(2019952,69,49,4,11,'Ndiye aliyewapa watu zawadi: wengine aliwajalia wawe mitume, wengine manabii, wengine wawe waeneza Habari Njema, wengine wachungaji na walimu.'),
(2019953,69,49,4,12,'Alifanya hivyo apate kuwatayarisha watu wote wa Mungu kwa ajili ya kazi ya huduma ya Kikristo ili kuujenga mwili wa Kristo,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2019954,69,49,4,13,'na hivyo sote tuufikie umoja wa imani na kumjua Mwana wa Mungu; tuwe watu waliokomaa na kuufikia utimilifu wake Kristo mwenyewe.'),
(2019955,69,49,4,14,'Basi, hatutakuwa tena kama watoto, tukitupwa na kupeperushwa huko na huko kwa kila upepo wa mafundisho wanayozua watu wadanganyifu, ili wawapotoshe wengine kwa hila.'),
(2019956,69,49,4,15,'Ila, sisi tukisema ukweli kwa moyo wa mapendo tutakua zidi katika kila jambo kulingana na Kristo ambaye ndiye kichwa;'),
(2019957,69,49,4,16,'chini ya uongozi wake, viungo vyote vya mwili hushikamana pamoja, na mwili wote hutegemezwa kwa msaada wa viungo vyake. Basi, kila kiungo kikitekeleza kazi yake ipasavyo, mwili wote hukua na kujijenga katika upendo.'),
(2019958,69,49,4,17,'Basi, kwa jina la Bwana, nawaonyeni: msiishi tena kama watu wasiomjua Mungu, ambao fikira zao zimekuwa upuuzi mtupu,'),
(2019959,69,49,4,18,'na akili zao zimo gizani. Wako mbali na uzima wa Mungu, kwa sababu ya upumbavu ulio ndani yao na ukaidi wao.'),
(2019960,69,49,4,19,'Wamepotoka na hawana aibu, wamejitosa katika ufisadi; hufanya kwa pupa kila aina ya mambo ya aibu.'),
(2019961,69,49,4,20,'Lakini ninyi hamkujifunza hivyo juu ya Kristo.'),
(2019962,69,49,4,21,'Ni dhahiri kwamba mlisikia barabara habari zake, na mkiwa wafuasi wake mkafundishwa ukweli ulivyo katika Yesu.'),
(2019963,69,49,4,22,'Basi, acheni mwenendo wenu wa awali, yaani ule utu wenu wa kale uliokuwa unaangamizwa kwa tamaa zake danganyifu.'),
(2019964,69,49,4,23,'Jirekebisheni upya rohoni na katika fikira zenu.'),
(2019965,69,49,4,24,'Vaeni hali mpya ya utu ambayo imeumbwa kwa mfano wa Mungu na ambayo hujionyesha katika maisha ya kweli ya uadilifu na utakatifu.'),
(2019966,69,49,4,25,'Kwa hiyo, acheni uongo. Kila mmoja anapaswa kumwambia mwenzake ukweli, maana kila mmoja wetu ni kiungo cha mwili wa Kristo.'),
(2019967,69,49,4,26,'Kama mkikasirika, msikubali hasira yenu iwafanye mtende dhambi, na wala msikae na hasira kutwa nzima.'),
(2019968,69,49,4,27,'Msimpe Ibilisi nafasi.'),
(2019969,69,49,4,28,'Aliyekuwa akiiba, asiibe tena, bali na aanze kufanya kazi njema kwa mikono yake, apate kuwa na kitu cha kumsaidia mtu aliye maskini.'),
(2019970,69,49,4,29,'Maneno mabaya hata yasisikike kamwe miongoni mwenu; kila mara maneno yenu yawe ya kufaa na ambayo hujenga na kuwasaidia wengine, ili yawaneemeshe wasikilizaji wenu.'),
(2019971,69,49,4,30,'Msimhuzunishe Roho Mtakatifu wa Mungu maana Roho huyo ni alama ya Mungu kwenu kwamba ninyi ni watu wake, na thibitisho kwamba siku itakuja ambapo Mungu atawakomboeni.'),
(2019972,69,49,4,31,'Basi, achaneni na uhasama, chuki, hasira, kelele, matusi! Achaneni na kila uovu!'),
(2019973,69,49,4,32,'Muwe na moyo mwema na wenye kuhurumiana; kila mmoja na amsamehe mwenzake kama naye Mungu alivyowasamehe ninyi kwa njia ya Kristo.'),
(2019974,69,49,5,1,'Kwa hiyo, mwigeni Mungu, maana ninyi ni watoto wake wapenzi.'),
(2019975,69,49,5,2,'Upendo uongoze maisha yenu, kama vile Kristo alivyotupenda, na kwa ajili yetu akajitoa mwenyewe kama dhabihu yenye harufu nzuri na tambiko impendezayo Mungu.'),
(2019976,69,49,5,3,'Kwa vile ninyi ni watu wa Mungu, basi uasherati, uchafu wowote ule au choyo visitajwe kamwe miongoni mwenu.'),
(2019977,69,49,5,4,'Tena maneno ya aibu, ya upuuzi au ubishi, yote hayo hayafai kwenu; maneno ya kumshukuru Mungu ndiyo yanayofaa.'),
(2019978,69,49,5,5,'Jueni wazi kwamba mwasherati yeyote au mchafu au mfisadi, (ufisadi ni sawa na kuabudu sanamu), au mtu yeyote wa aina hiyo hataambulia chochote katika Utawala wa Kristo na wa Mungu.'),
(2019979,69,49,5,6,'Msikubali kudanganywa na mtu kwa maneno matupu; maana, kwa sababu ya mambo kama hayo ghadhabu ya Mungu huwajia wote wasiomtii.'),
(2019980,69,49,5,7,'Basi, msishirikiane nao.'),
(2019981,69,49,5,8,'Zamani ninyi mlikuwa gizani, lakini sasa ninyi mko katika mwanga kwa kuungana na Bwana. Ishini kama watoto wa mwanga:'),
(2019982,69,49,5,9,'maana matokeo ya mwanga ni wema kamili, uadilifu na ukweli.'),
(2019983,69,49,5,10,'Jaribuni kujua yale yanayompendeza Bwana.'),
(2019984,69,49,5,11,'Msishiriki katika matendo yasiyofaa, ya giza bali yafichueni.'),
(2019985,69,49,5,12,'Mambo yanayotendwa kwa siri ni aibu hata kuyataja.'),
(2019986,69,49,5,13,'Lakini mambo yale yanayotendwa katika mwanga, ukweli wake hudhihirishwa;'),
(2019987,69,49,5,14,'na kila kilichodhihirishwa huwa mwanga. Ndiyo maana Maandiko yasema: "Amka wewe uliyelala, fufuka kutoka wafu, naye Kristo atakuangaza."'),
(2019988,69,49,5,15,'Basi, muwe waangalifu jinsi mnavyoishi: Msiishi kama wapumbavu, bali kama wenye hekima.'),
(2019989,69,49,5,16,'Tumieni vizuri muda mlio nao maana siku hizi ni mbaya.'),
(2019990,69,49,5,17,'Kwa hiyo, msiwe wapumbavu, bali jaribuni kujua matakwa ya Bwana.'),
(2019991,69,49,5,18,'Acheni kulewa divai maana hiyo itawaangamiza, bali mjazwe Roho Mtakatifu.'),
(2019992,69,49,5,19,'Zungumzeni kwa maneno ya Zaburi, nyimbo na tenzi za kiroho; mwimbieni Bwana nyimbo na zaburi kwa shukrani mioyoni mwenu.'),
(2019993,69,49,5,20,'Mshukuruni Mungu Baba daima kwa ajili ya yote, kwa jina la Bwana wetu Yesu Kristo.'),
(2019994,69,49,5,21,'Kila mmoja amstahi mwenzake kwa sababu ya kumcha Kristo.'),
(2019995,69,49,5,22,'Wake wawatii waume zao kama kumtii Bwana.'),
(2019996,69,49,5,23,'Maana mume anayo mamlaka juu ya mkewe, kama vile Kristo alivyo na mamlaka juu ya kanisa; naye Kristo mwenyewe hulikomboa kanisa, mwili wake.'),
(2019997,69,49,5,24,'Kama vile kanisa linavyomtii Kristo, vivyo hivyo, wake wawatii waume zao katika mambo yote.'),
(2019998,69,49,5,25,'Nanyi waume, wapendeni wake zenu kama Kristo alivyolipenda kanisa, akajitoa mwenyewe sadaka kwa ajili yake.'),
(2019999,69,49,5,26,'Alifanya hivyo, ili kwa neno lake, aliweke wakfu kwa Mungu, baada ya kulifanya safi kwa kuliosha katika maji,'),
(2020000,69,49,5,27,'kusudi ajipatie kanisa lililo takatifu na safu kabisa, kanisa lisilo na doa, kasoro au chochote cha namna hiyo.'),
(2020001,69,49,5,28,'Basi, waume wanapaswa kuwapenda wake zao kama miili yao wenyewe. (('),
(2020002,69,49,5,29,'Hakuna mtu yeyote auchukiaye mwili wake; badala ya kuuchukia, huulisha na kuuvika. Ndivyo naye Kristo anavyolitunza kanisa,'),
(2020003,69,49,5,30,'maana sisi ni viungo vya mwili wake.)');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020004,69,49,5,31,'Kama yasemavyo Maandiko Matakatifu: "Kwa hiyo, mwanamume atawaacha baba na mama yake, ataungana na mkewe, nao wawili watakuwa mwili mmoja."'),
(2020005,69,49,5,32,'Kuna ukweli uliofichika katika maneno haya, nami naona kwamba yamhusu Kristo na kanisa lake.'),
(2020006,69,49,5,33,'Lakini yanawahusu ninyi pia: kila mume lazima ampende mkewe kama nafsi yake mwenyewe, naye mke anapaswa kumstahi mumewe.'),
(2020007,69,49,6,1,'Enyi watoto, watiini wazazi wenu Kikristo maana hili ni jambo jema.'),
(2020008,69,49,6,2,'"Waheshimu Baba na mama yako," hii ndiyo amri ya kwanza ambayo imeongezewa ahadi, yaani,'),
(2020009,69,49,6,3,'"Upate fanaka na miaka mingi duniani."'),
(2020010,69,49,6,4,'Nanyi akina baba, msiwachukize watoto wenu ila waleeni katika nidhamu na mafundisho ya Kikristo.'),
(2020011,69,49,6,5,'Enyi watumwa, watiini mabwana zenu hapa duniani kwa hofu na tetemeko; fanyeni hivyo kwa unyofu wa moyo kana kwamba mnamtumikia Kristo.'),
(2020012,69,49,6,6,'Fanyeni hivyo si tu wakati wanapowatazama ili mjipendekeze kwao, bali tumikieni kwa moyo kama atakavyo Mungu kwa sababu ninyi ni watumishi wa Kristo.'),
(2020013,69,49,6,7,'Muwe radhi kutumikia kwa ajili ya Bwana na si kwa ajili ya watu.'),
(2020014,69,49,6,8,'Kumbukeni kwamba kila mtu mwenye kutenda mema, awe mtumwa au mtu huru, atapokea tuzo lake kutoka kwa Bwana.'),
(2020015,69,49,6,9,'Nanyi mnaotumikiwa, watendeeni vivyo hivyo watumwa wenu, na acheni kutumia vitisho. Kumbukeni kwamba ninyi pia kama vile wao, mnaye Bwana yuleyule mbinguni, kwake cheo cha mtu si kitu.'),
(2020016,69,49,6,10,'Hatimaye, nawatakeni muwe imara katika kuungana na Bwana na kwa msaada wa nguvu yake kuu.'),
(2020017,69,49,6,11,'Vaeni silaha anazowapeni Mungu mpate kuzipinga mbinu mbaya za Ibilisi.'),
(2020018,69,49,6,12,'Maana vita vyenu si vita kati yetu na binadamu, bali ni vita dhidi ya jeshi ovu la ulimwengu wa roho; tunapigana na watawala, wakuu na wenye nguvu wanaomiliki ulimwengu huu wa giza.'),
(2020019,69,49,6,13,'Kwa sababu hiyo, vaeni silaha za Mungu ili siku ile itakapofika muweze kuyapinga mashambulio ya adui; na mkisha pigana mpaka mwisho, muwe bado thabiti.'),
(2020020,69,49,6,14,'Basi, simameni imara! Ukweli uwe kama ukanda kiunoni mwenu, uadilifu uwe kama vazi la kujikinga kifuani,'),
(2020021,69,49,6,15,'na hamu ya kutangaza Habari Njema ya amani iwe kama viatu miguuni mwenu.'),
(2020022,69,49,6,16,'Zaidi ya hayo yote, imani iwe daima kama ngao mikononi mwenu, iwawezeshe kuizima mishale ya moto ya yule Mwovu.'),
(2020023,69,49,6,17,'Upokeeni wokovu kama kofia yenu ya chuma, na neno la Mungu kama upanga mnaopewa na Roho Mtakatifu.'),
(2020024,69,49,6,18,'Salini daima, mkiomba msaada wa Mungu. Salini kila wakati kwa nguvu ya Roho. Kesheni bila kuchoka mkisali kwa ajili ya watu wote wa Mungu.'),
(2020025,69,49,6,19,'Niombeeni nami pia ili niongeapo Mungu anijalie cha kusema, niweze kuwajulisha watu fumbo la Habari Njema kwa uthabiti.'),
(2020026,69,49,6,20,'Mimi ni balozi kwa ajili ya Habari Njema hiyo ingawa sasa niko kifungoni. Ombeni, basi, ili niweze kuwa hodari katika kuitangaza kama inipasavyo.'),
(2020027,69,49,6,21,'Tukiko, ndugu yetu mpenzi na mtumishi mwaminifu wa Bwana, atawapeni habari zangu zote mpate kujua ninachofanya.'),
(2020028,69,49,6,22,'Namtuma kwenu awapeni habari zetu mpate kuwa na moyo.'),
(2020029,69,49,6,23,'Ninawatakieni ninyi ndugu amani, upendo na imani kutoka kwa Mungu Baba na kutoka kwa Bwana Yesu Kristo.'),
(2020030,69,49,6,24,'Nawatakia neema ya Mungu wote wanaompenda Bwana wetu Yesu Kristo kwa mapendo yasiyo na mwisho.'),
(2020031,69,51,1,1,'Mimi Paulo, mtume wa Kristo Yesu kwa mapenzi ya Mungu, na ndugu Timotheo,'),
(2020032,69,51,1,2,'tunawaandikia ninyi watu wa Mungu huko Kolosai, ndugu zetu waaminifu katika kuungana na Kristo. Tunawatakieni neema na amani kutoka kwa Mungu Baba yetu.'),
(2020033,69,51,1,3,'Daima tunamshukuru Mungu, Baba wa Bwana wetu Yesu Kristo, wakati tunapowaombea.'),
(2020034,69,51,1,4,'Maana tumesikia juu ya imani yenu katika Kristo Yesu na juu ya upendo wenu kwa watu wote wa Mungu.'),
(2020035,69,51,1,5,'Wakati ujumbe ule wa kweli, yaani Habari Njema, ilipowafikieni kwa mara ya kwanza, mlipata kusikia juu ya lile tumaini linalopatikana kwake. Kwa sababu hiyo imani na upendo wenu vinategemea jambo lile mnalotumainia ambalo mmewekewa salama mbinguni.'),
(2020036,69,51,1,6,'Habari Njema inazidi kuzaa matunda na kuenea ulimwenguni kote kama vile ilivyofanya kwenu ninyi tangu siku ile mliposikia juu ya neema ya Mungu na kuitambua ilivyo kweli.'),
(2020037,69,51,1,7,'Mlijifunza juu ya neema ya Mungu kutoka kwa Epafra, mtumishi mwenzetu, ambaye ni mfanyakazi mwaminifu wa Kristo kwa niaba yetu.'),
(2020038,69,51,1,8,'Yeye alitupa habari za upendo wenu mliojaliwa na Roho.'),
(2020039,69,51,1,9,'Kwa sababu hiyo tumekuwa tukiwaombeeni daima tangu tulipopata habari zenu. Tunamwomba Mungu awajazeni ujuzi kamili wa mapenzi yake, awajazeni hekima yote na elimu iletwayo na Roho wake.'),
(2020040,69,51,1,10,'Hapo mtaweza kuishi kama anavyotaka Bwana na kutenda daima yanayompendeza. Maisha yenu yatakuwa yenye matunda ya kila namna ya matendo mema na mtazidi kukua katika kumjua Mungu.'),
(2020041,69,51,1,11,'Mungu awajalieni nguvu kwa uwezo wake mtukufu ili mweze kustahimili kila kitu kwa uvumilivu.'),
(2020042,69,51,1,12,'Na kwa furaha, mshukuruni Baba aliyewawezesha ninyi kuwa na sehemu yenu katika mambo yale Mungu aliyowawekea watu wake katika utawala wa mwanga.'),
(2020043,69,51,1,13,'Yeye alituokoa katika nguvu ya giza, akatuleta salama katika ufalme wa Mwanae mpenzi,'),
(2020044,69,51,1,14,'ambaye kwa njia yake tunakombolewa, yaani dhambi zetu zinaondolewa.'),
(2020045,69,51,1,15,'Kristo ni mfano wa Mungu asiyeonekana; ni mzaliwa wa kwanza wa viumbe vyote.'),
(2020046,69,51,1,16,'Maana kwa njia yake vitu vyote viliumbwa duniani na mbinguni, vitu vinavyoonekana na visivyoonekana: wenye enzi, watawala, wakuu na wenye mamlaka. Vyote viliumbwa kwa njia yake na kwa ajili yake.'),
(2020047,69,51,1,17,'Kristo alikuwako kabla ya vitu vyote; kwa kuungana naye, vyote vyadumu mahali pake.'),
(2020048,69,51,1,18,'Yeye ni kichwa cha mwili wake, yaani kanisa; yeye ni chanzo cha uhai wa huo mwili. Yeye ndiye mwanzo, mzaliwa wa kwanza aliyefufuliwa kutoka wafu, ili awe na nafasi ya kwanza katika vitu vyote.'),
(2020049,69,51,1,19,'Maana Mungu alipenda utimilifu wote uwe ndani yake.'),
(2020050,69,51,1,20,'Kwa njia yake Mungu alivipatanisha naye vitu vyote naam, viumbe vyote mbinguni na duniania; alileta amani kwa damu ya Kristo msalabani.'),
(2020051,69,51,1,21,'Hapo kwanza ninyi pia mlikuwa mbali na Mungu na mlikuwa adui zake kwa sababu ya fikira zenu na matendo yenu maovu.'),
(2020052,69,51,1,22,'Lakini sasa, kwa kifo cha Mwanae aliyeishi hapa duniani, Mungu amewapatanisha naye, kusudi awalete mbele yake mkiwa watakatifu, safi na bila lawama.'),
(2020053,69,51,1,23,'Mnapaswa, lakini kuendelea kuwa imara na thabiti katika imani hiyo, na msikubali kusukumwa mbali na tumaini lile mlilopata wakati mlipoisikia Habari Njema. Mimi Paulo nimekuwa mtumishi wa hiyo Habari Njema ambayo imekwisha hubiriwa kila kiumbe duniani.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020054,69,51,1,24,'Na sasa nafurahi kuteseka kwa ajili yenu, maana kwa mateso yangu hapa duniani, nasaidia kukamilisha kile kilichopungua bado katika mateso ya Kristo kwa ajili ya mwili wake, yaani kanisa.'),
(2020055,69,51,1,25,'Nami nimefanywa kuwa mtumishi wa kanisa kufuatana na mpango wake Mungu ambao alinikabidhi kwa faida yenu. Mpango wenyewe ni kuutangaza kwa ukamilifu ujumbe wake,'),
(2020056,69,51,1,26,'ambao ni siri aliyowaficha binadamu wote tangu milele, lakini sasa amewajulisha watu wake.'),
(2020057,69,51,1,27,'Mpango wa Mungu ni kuwajulisha watu wake siri hii kuu na tukufu ambayo ni kwa ajili ya watu wote. Na, siri yenyewe ndiyo hii: Kristo yuko ndani yenu, na jambo hilo lamaanisha kwamba ninyi mtaushiriki utukufu wa Mungu.'),
(2020058,69,51,1,28,'Kwa sababu hiyo tunamhubiri Kristo kwa watu wote; tunawaonya na kuwafundisha wote kwa hekima yote, ili tuweze kumleta kila mmoja mbele ya Mungu akiwa amekomaa katika kuungana na Kristo.'),
(2020059,69,51,1,29,'Kwa madhumuni hayo mimi nafanya kazi na kujitahidi nikiitumia nguvu kuu ya Kristo ifanyayo kazi ndani yangu.'),
(2020060,69,51,2,1,'Napenda mjue jinsi ninavyofanya kazi kwa bidii kwa ajili yenu, kwa ajili ya watu wa Laodikea na kwa ajili ya wote ambao hawajapata kuniona kwa macho.'),
(2020061,69,51,2,2,'Nafanya hivi kusudi mioyo yao ifarijiwe na kuvutwa pamoja katika upendo, ili wajazwe uthabiti mwingi uletwao na elimu ya kweli. Hapo wataijua siri ya Mungu ambayo ni Kristo mwenyewe.'),
(2020062,69,51,2,3,'Ndani yake zimefichika hazina zote za hekima na elimu.'),
(2020063,69,51,2,4,'Basi, nawaambieni, msikubali kudanganywa na mtu yeyote kwa maneno ya uongo hata kama ni ya kuvutia sana.'),
(2020064,69,51,2,5,'Maana, ingawa mimi niko mbali nanyi kwa mwili, lakini niko pamoja nanyi kwa roho, na ninafurahi kuona uthabiti kamili mnaosimama nao pamoja katika imani yenu kwa Kristo.'),
(2020065,69,51,2,6,'Maadamu ninyi mmemkubali Kristo Yesu kuwa Bwana, basi, ishini katika muungano naye.'),
(2020066,69,51,2,7,'Mnapaswa kuwa na mizizi ndani yake, kujijenga juu yake na kuwa imara katika imani yenu kama mlivyofundishwa. Muwe na shukrani tele.'),
(2020067,69,51,2,8,'Angalieni basi, mtu asiwapotoshe kwa udanganyifu mtupu wa hekima ya kibinadamu, ambayo chanzo chake ni mafundisho ya mapokeo ya watu na ya pepo watawala, na wala si Kristo mwenyewe!'),
(2020068,69,51,2,9,'Maana, ndani yake Kristo katika ubinadamu wake, umo ukamilifu wote wa Mungu,'),
(2020069,69,51,2,10,'nanyi mmepewa uzima kamili katika kuungana naye. Yeye yuko juu ya pepo watawala wote na wakuu wote.'),
(2020070,69,51,2,11,'Katika kuungana na Kristo ninyi mlitahiriwa, lakini si kwa tohara ifanywayo na watu, bali inayofanywa na Kristo mwenyewe, na ambayo inahusikana na kukombolewa kutoka katika utu wa dhambi.'),
(2020071,69,51,2,12,'Maana, mlipobatizwa mlizikwa pamoja na Kristo, na katika ubatizo, mlifufuliwa pia pamoja naye kwa imani yenu katika nguvu ya Mungu ambaye alimfufua Kristo kutoka wafu.'),
(2020072,69,51,2,13,'Wakati mmoja nanyi mlikuwa mmekufa kwa sababu ya makosa yenu na kwa sababu ninyi mlikuwa watu wa mataifa mengine. Lakini Mungu amewapa ninyi uzima pamoja na Kristo. Mungu ametusamehe dhambi zetu zote;'),
(2020073,69,51,2,14,'alifutilia mbali ile hati ya deni iliyokuwa inatukabili na masharti yake, na kuifuta kabisa kwa kuipigilia msalabani.'),
(2020074,69,51,2,15,'Juu ya msalaba Kristo aliwapokonya nguvu zao hao pepo watawala na wakuu; aliwafanya kuwa kitu cha fedheha hadharani kwa kuwaburuta kama mateka katika msafara wa ushindi wake.'),
(2020075,69,51,2,16,'Kwa hiyo, basi, msikubali kupewa masharti na mtu yeyote kuhusu vyakula au vinywaji, siku za sherehe, sikukuu ya Mwezi mpya au Sabato.'),
(2020076,69,51,2,17,'Mambo ya aina hiyo ni kivuli tu cha yale yatakayokuja; ukweli wenyewe ndiye Kristo.'),
(2020077,69,51,2,18,'Msikubali kuhukumiwa na mtu yeyote anayejitakia kuwa wa maana kwa sababu ya maono ya pekee na ambaye anasisitiza juu ya unyenyekevu wa uongo na ibada kwa malaika. Mtu wa namna hiyo amepumbazika kwa fikira danganifu za kidunia'),
(2020078,69,51,2,19,'na amejitenga na Kristo aliye kichwa cha huo mwili. Chini ya uongozi wa Kristo, mwili wote unalishwa na kuunganishwa pamoja kwa viungo na mishipa yake, nao hukua kama atakavyo Mungu.'),
(2020079,69,51,2,20,'Ninyi mmekufa pamoja na Kristo na kukombolewa kutoka nguvu za pepo watawala wa ulimwengu. Kwa nini, basi, kuishi tena kama vile mngekuwa wa ulimwengu huu? Ya nini kuwekewa masharti:'),
(2020080,69,51,2,21,'"Msishike hiki," "Msionje kile," "Msiguse kile!"'),
(2020081,69,51,2,22,'Mambo hayo yote yanahusika na vitu vyenye kuharibika mara tu vinapotumiwa; hayo ni maagizo na mafundisho ya kibinadamu tu.'),
(2020082,69,51,2,23,'Kweli, masharti hayo yaonekana kuwa ya hekima katika namna ya ibada ya kujitakia wenyewe, unyenyekevu wa uongo na kuutendea mwili kwa ukali; lakini kwa kweli, haifai chochote kuzuia tamaa za mwili.'),
(2020083,69,51,3,1,'Basi, ikiwa mmefufuka pamoja na Kristo, panieni mambo ya juu, kule Kristo aliko, ameketi upande wa kulia wa Mungu.'),
(2020084,69,51,3,2,'Muwe na hamu ya mambo ya huko juu, na siyo mambo ya hapa duniani.'),
(2020085,69,51,3,3,'Maana ninyi mmekufa na uzima wenu umefichwa pamoja na Kristo katika Mungu.'),
(2020086,69,51,3,4,'Uzima wenu halisi ni Kristo, na wakati atakapotokea ndipo nanyi pia mtakapotokea pamoja naye katika utukufu.'),
(2020087,69,51,3,5,'Basi, komesheni kabisa kila kitu kilicho ndani yenu ambacho chahusika na mambo ya kidunia: uasherati, uchafu, shauku, tamaa mbaya na uchu (ambao ni sawa na kuabudu sanamu).'),
(2020088,69,51,3,6,'Kwa sababu ya mambo hayo hasira ya Mungu huwajia wote wanaomwasi.'),
(2020089,69,51,3,7,'Wakati mmoja ninyi pia mliishi kufuatana na mambo hayo, mlipotawaliwa nayo.'),
(2020090,69,51,3,8,'Lakini sasa mnapaswa kuachana na mambo haya yote: hasira, tamaa, uovu; kufuru au maneno yasiyofaa yasitoke kamwe vinywani mwenu.'),
(2020091,69,51,3,9,'Msiambiane uongo, kwani ninyi mmekwisha vua ule utu wa kale pamoja na matendo yake yote,'),
(2020092,69,51,3,10,'mkavaa utu mpya. Huu unaendelea kurekebishwa na Mungu, Muumba wake, kadiri ya mfano wake, ili mpate kumjua Mungu kwa ukamilifu.'),
(2020093,69,51,3,11,'Katika hali hii, hakuna tena tofauti kati ya Mgiriki na Myahudi, aliyetahiriwa na asiyetahiriwa, msomi na asiye msomi, mtumwa na mtu aliye huru. Kristo ni kila kitu, na yumo katika yote.'),
(2020094,69,51,3,12,'Ninyi ni watu wake Mungu; yeye aliwapenda na kuwateua. Kwa hiyo basi, vaeni moyo wa huruma, wema, unyenyekevu, upole na uvumilivu.'),
(2020095,69,51,3,13,'Vumilianeni na kusameheana iwapo mmoja wenu analo jambo lolote dhidi ya mwenzake. Mnapaswa kusameheana kama Bwana alivyowasamehe ninyi.'),
(2020096,69,51,3,14,'Zaidi ya hayo yote, zingatieni upendo kwani upendo huunganisha kila kitu katika umoja ulio kamili.'),
(2020097,69,51,3,15,'Nayo amani ya Kristo itawale mioyoni mwenu; maana kwa ajili hiyo ninyi mmeitwa katika mwili huo mmoja. Tena muwe na shukrani!'),
(2020098,69,51,3,16,'Ujumbe wa Kristo ukae ndani yenu pamoja na utajiri wake wote. Fundishaneni na kushauriana kwa hekima yote. Imbeni zaburi, nyimbo na tenzi za kiroho; mwimbieni Mungu mioyoni mwenu kwa shukrani.'),
(2020099,69,51,3,17,'Na, kila mfanyacho kwa neno au tendo, fanyeni vyote kwa jina la Bwana Yesu na kumshukuru Mungu Baba kwa njia yake.'),
(2020100,69,51,3,18,'Enyi akina mama, watiini waume zenu, kwani ndivyo apendavyo Bwana.'),
(2020101,69,51,3,19,'Nanyi waume, wapendeni wake zenu, na msiwe wakali kwao.'),
(2020102,69,51,3,20,'Enyi watoto, watiini wazazi wenu daima maana hiyo humpendeza Bwana.'),
(2020103,69,51,3,21,'Nanyi wazazi, msiwachukize watoto wenu, la sivyo watakata tamaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020104,69,51,3,22,'Enyi watumwa, watiini wakuu wenu wa kidunia katika mambo yote, na si tu wakati wanapowatazama kwa kuwa mnataka kujipendekeza kwao; ila fanyeni hivyo kwa moyo wote, kwa sababu ya kumcha Bwana.'),
(2020105,69,51,3,23,'Kila mfanyalo, fanyeni kwa moyo wote, kwa sababu ya Bwana na si kwa ajili ya mtu.'),
(2020106,69,51,3,24,'Kumbukeni kwamba atawapeni tuzo lile alilowawekea watu wake. Mtumikieni Kristo Bwana!'),
(2020107,69,51,3,25,'Atendaye mabaya atalipwa kufuatana na ubaya wake; Mungu hana ubaguzi.'),
(2020108,69,51,4,1,'Nanyi wakuu, watendeeni watumwa wenu kwa uadilifu na haki, mkikumbuka kwamba nanyi pia mnaye Bwana mbinguni.'),
(2020109,69,51,4,2,'Dumuni katika sala, na mnaposali muwe waangalifu, mkimshukuru Mungu.'),
(2020110,69,51,4,3,'Vilevile, mtuombee sisi pia ili Mungu atupe fursa ya kuuhubiri ujumbe wake kuhusu siri ya Kristo. Kwa ajili hiyo mimi niko sasa kifungoni.'),
(2020111,69,51,4,4,'Basi, ombeni ili niweze kusema kama inavyonipasa na kwa namna itakayodhihirisha siri hiyo.'),
(2020112,69,51,4,5,'Muwe na hekima katika uhusiano wenu na watu wasioamini, mkitumia vizuri kila nafasi mliyo nayo.'),
(2020113,69,51,4,6,'Mazungumzo yenu yanapaswa kuwa daima mema na ya kuvutia, na mnapaswa kujua jinsi ya kumjibu vizuri kila mmoja.'),
(2020114,69,51,4,7,'Ndugu yetu mpenzi Tukiko, mfanyakazi mwaminifu na mtumishi mwenzetu katika kazi ya Bwana, atawapeni habari zangu zote.'),
(2020115,69,51,4,8,'Ndiyo maana namtuma, ili aichangamshe mioyo yenu kwa kuwaambieni habari zetu.'),
(2020116,69,51,4,9,'Anakuja pamoja na Onesimo, ndugu yetu mpenzi na mwaminifu, ambaye ni mwananchi mwenzenu. Watawapeni habari za mambo yote yanayofanyika hapa.'),
(2020117,69,51,4,10,'Aristarko, ambaye yuko kifungoni pamoja nami, anawasalimuni; hali kadhalika Marko, binamu yake Barnaba, (mmekwisha pata maagizo juu yake; akifika kwenu mkaribisheni).'),
(2020118,69,51,4,11,'Naye Yoshua aitwaye Yusto, anawasalimuni. Miongoni mwa Wayahudi waliokwisha pokea imani, hawa tu peke yao, ndio wanaofanya kazi pamoja nami kwa ajili ya Utawala wa Mungu; nao wamekuwa msaada mkubwa kwangu.'),
(2020119,69,51,4,12,'Epafra, mwananchi mwenzenu na mtumishi wa Kristo Yesu anawasalimuni. Daima anawaombeeni ninyi kwa bidii ili mpate kusimama imara, mkomae na kuwa thabiti kabisa katika mambo yote anayotaka Mungu.'),
(2020120,69,51,4,13,'Naweza kushuhudia kwamba anafanya kazi kwa bidii kwa ajili yenu na kwa ajili ya watu wa Laodikea na Hierapoli.'),
(2020121,69,51,4,14,'Luka, daktari wetu mpenzi, na Dema, wanawasalimuni.'),
(2020122,69,51,4,15,'Salamu zetu kwa ndugu zetu wa Laodikea; msalimuni dada Nimfa pamoja na jumuiya yote ya waumini inayokutana nyumbani kwake.'),
(2020123,69,51,4,16,'Mkisha soma barua hii, hakikisheni kwamba inasomwa na Wakristo wa Laodikea; na ninyi fanyeni mpango mpate kuisoma barua waliyoipata kwao.'),
(2020124,69,51,4,17,'Mwambieni Arkipo aitekeleze vizuri ile huduma aliyokabidhiwa na Bwana.'),
(2020125,69,51,4,18,'Naandika haya kwa mkono wangu mwenyewe: Salamu kutoka kwangu, mimi Paulo. Kumbukeni kwamba niko kifungoni. Neema ya Mungu iwe nanyi.'),
(2020126,69,52,1,1,'Mimi Paulo, Silwano na Timotheo tunawaandikia ninyi jumuiya ya kanisa la Thesalonike, ambao ni watu wake Mungu Baba, na wa Bwana Yesu Kristo.'),
(2020127,69,52,1,2,'Tunamshukuru Mungu daima kwa ajili yenu ninyi nyote na kuwakumbukeni daima katika sala zetu.'),
(2020128,69,52,1,3,'Maana, mbele ya Mungu Baba yetu, twakumbuka jinsi mnavyoonyesha imani yenu kwa matendo, jinsi upendo wenu unavyowawezesha kufanya kazi kwa bidii, na jinsi tumaini lenu katika Bwana wetu Yesu Kristo lilivyo thabiti.'),
(2020129,69,52,1,4,'Ndugu, twajua kwamba Mungu anawapenda na kwamba amewateua muwe watu wake,'),
(2020130,69,52,1,5,'maana wakati tulipowahubirieni ile Habari Njema haikuwa kwa maneno tu, bali pia kwa nguvu na kwa Roho Mtakatifu, tukiwa na hakika kwamba ujumbe huo ulikuwa wa kweli. Mnajua jinsi tulivyoishi pamoja nanyi; tuliishi kwa manufaa yenu.'),
(2020131,69,52,1,6,'Ninyi mlifuata mfano wetu, na kumwiga Bwana. Ingawa mliteswa sana, mliupokea ujumbe huo kwa furaha itokayo kwa Roho Mtakatifu.'),
(2020132,69,52,1,7,'Kwa hiyo ninyi mmekuwa mfano mzuri kwa waumini wote wa Makedonia na Akaya.'),
(2020133,69,52,1,8,'Maana, kutokana na bidii yenu ujumbe wa Bwana umesikika si tu huko Makedonia na Akaya, bali imani yenu kwa Mungu imeenea popote. Tena hatuhitaji kusema zaidi.'),
(2020134,69,52,1,9,'Watu hao wanazungumza juu ya ziara yetu kwenu: jinsi mlivyotukaribisha, jinsi mlivyoziacha sanamu mkamgeukia Mungu aliye hai na wa kweli,'),
(2020135,69,52,1,10,'na sasa mwamngojea Mwanae ashuke kutoka mbinguni, Yesu, ambaye Mungu alimfufua kutoka wafu, na ambaye anatuokoa katika ghadhabu ya Mungu inayokuja.'),
(2020136,69,52,2,1,'Ndugu, ninyi wenyewe mnafahamu kwamba ziara yetu kwenu haikuwa bure.'),
(2020137,69,52,2,2,'Mnajua jinsi tulivyodhulumiwa na kutukanwa kule Filipi kabla ya kufika kwenu Thesalonike. Ingawa kulikuwa na upinzani mwingi, Mungu wetu alitujalia uhodari wa kuwahubirieni Habari Njema yake.'),
(2020138,69,52,2,3,'Jambo tunalosisitiza kwenu si jambo linalotegemea uongo au nia mbaya; wala hatupendi kumdanganya mtu yeyote.'),
(2020139,69,52,2,4,'Sisi twanena daima kama atakavyo Mungu kwani yeye alituona kwamba tunafaa, akatukabidhi hii Habari Njema. Si nia yetu kuwapendeza watu hata kidogo, bali twataka kumpendeza Mungu ambaye anajua mioyo yetu mpaka ndani.'),
(2020140,69,52,2,5,'Ninyi mnajua kwamba sisi hatukuja kwenu na maneno matamu ya kubembeleza wala hatukutumia maneno ya kijanja ya kuficha ubinafsi fulani; Mungu ni shahidi!'),
(2020141,69,52,2,6,'Hatukutafuta sifa kutoka kwa watu, wala kutoka kwenu, wala kutoka kwa mtu yeyote,'),
(2020142,69,52,2,7,'ingawa sisi tukiwa mitume wa Kristo, tungeweza kudai mambo fulani kwenu. Lakini sisi tulikuwa Wapole kati yenu kama alivyo mama kwa watoto wake.'),
(2020143,69,52,2,8,'Tuliwapenda ninyi sana hata tukawa tayari kuwashirikisha si tu Habari Njema ya Mungu, bali pia na maisha yetu. Ndivyo mlivyokuwa wapenzi wetu!'),
(2020144,69,52,2,9,'Ndugu, mnakumbuka jinsi tulivyofanya kazi na kutaabika. Tulipowaleteeni Habari Njema ya Mungu tulifanya kazi mchana na usiku kusudi tusiwe mzigo kwa mtu yeyote miongoni mwenu.'),
(2020145,69,52,2,10,'Ninyi mnaweza kushuhudia, na Mungu pia ni shahidi, jinsi mwenendo wetu kati yenu ninyi mnaoamini ulivyokuwa mzuri, mwadilifu na usio na lawama.'),
(2020146,69,52,2,11,'Mnajua kwamba sisi tulimtendea kila mmoja wenu kama vile baba anavyowatendea watoto wake mwenyewe.'),
(2020147,69,52,2,12,'Tuliwapeni moyo, tuliwafarijini na kuwahimiza ili mpate kuishi maisha yampendezayo Mungu ambaye aliwaiteni mshiriki Utawala na utukufu wake.'),
(2020148,69,52,2,13,'Tena tunayo sababu nyingine ya kumshukuru Mungu: tulipowaleteeni ujumbe wa Mungu, ninyi mliusikia mkaupokea, si kama vile ujumbe wa binadamu, bali kama ujumbe wa Mungu, na kweli ndivyo ulivyo. Maana Mungu anafanya kazi ndani yenu ninyi mnaoamini.'),
(2020149,69,52,2,14,'Ndugu, ninyi mmepatwa na mambo yaleyale yaliyoyapata makanisa ya Mungu kule Yudea, mambo yaliyowapata watu walio wake Kristo Yesu. Ninyi mlidhulumiwa na wananchi wenzenu kama vile wao walivyodhulumiwa na wenzao Wayahudi,'),
(2020150,69,52,2,15,'ambao walimuua Bwana Yesu na manabii, wakatutesa na sisi pia. Watu hao wanamchukiza Mungu, tena ni adui za kila mtu!'),
(2020151,69,52,2,16,'Hata walijaribu kutuzuia kuwahubiria watu wa mataifa mengine ujumbe utakaowaletea wokovu. Ndivyo walivyokamilisha orodha ya dhambi zote walizotenda siku zote. Lakini sasa hasira ya Mungu imewaangukia.'),
(2020152,69,52,2,17,'Ndugu, kuachana kwetu nanyi kulikuwa kwa muda tu, tena kuachana huko kulikuwa kwa mwili tu na si kwa roho. Kitambo kifupi baadaye, tulishikwa na hamu kubwa ya kuwaoneni tena!'),
(2020153,69,52,2,18,'Kwa hiyo tuliamua kuwatembeleeni tena. Nami, Paulo, nilijaribu kuja kwenu zaidi ya mara moja, lakini Shetani alituzuia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020154,69,52,2,19,'Je, tutakaposimama mbele ya Bwana Yesu wakati atakapokuja, fahari ya ushindi wetu itakuwa nini? Itakuwa ni ninyi wenyewe; ninyi ndio tumaini letu na furaha yetu.'),
(2020155,69,52,2,20,'Naam, ninyi ni utukufu wetu na furaha yetu!'),
(2020156,69,52,3,1,'Mwishowe hatukuweza kuvumilia zaidi. Basi, tuliamua kubaki kule Athene peke yetu,'),
(2020157,69,52,3,2,'na kumtuma kwenu ndugu yetu Timotheo, ambaye ni mfanyakazi mwenzetu kwa ajili ya Mungu katika kuhubiri Habari Njema ya Kristo. Tulimtuma ili awaimarisheni na kuwafarijini,'),
(2020158,69,52,3,3,'kusudi imani ya mtu yeyote miongoni mwenu isije ikafifia kwa sababu ya taabu hizo. Ninyi mnajua kwamba tunapaswa kupata mateso.'),
(2020159,69,52,3,4,'Maana, tulipokuwa pamoja nanyi, tuliwaambieni kwamba tutateswa; na kama mjuavyo ndivyo ilivyotukia.'),
(2020160,69,52,3,5,'Ndio maana nilimtuma Timotheo kwenu. Sikuweza kungoja zaidi, na hivyo nilimtuma nipate habari za imani yenu. Isije ikawa labda Mshawishi aliwajaribuni na kazi yote tuliyofanya miongoni mwenu imepotea bure!'),
(2020161,69,52,3,6,'Sasa Timotheo amekwisha rudi, naye ametupa habari za kufurahisha kuhusu imani na upendo wenu. Ametuarifu kwamba mnatukumbuka daima, na kwamba mna hamu ya kutuona sisi kama nasi tulivyo na hamu ya kuwaoneni.'),
(2020162,69,52,3,7,'Basi, habari za imani yenu zimetutia moyo katika taabu na mateso yetu yote,'),
(2020163,69,52,3,8,'kwani sasa tunaishi kweli ikiwa ninyi mnasimama imara katika kuungana na Bwana.'),
(2020164,69,52,3,9,'Sasa twaweza kumshukuru Mungu wetu kwa ajili yenu. Tunamshukuru kwa furaha tuliyo nayo mbele yake kwa sababu yenu.'),
(2020165,69,52,3,10,'Tunazidi kumwomba Mungu usiku na mchana kwa moyo wetu wote ili atupatie fursa ya kuwaoneni uso kwa uso ili tuweze kurekebisha chochote kilichopungua katika imani yenu.'),
(2020166,69,52,3,11,'Tunamwomba Mungu, Baba yetu mwenyewe, na Bwana wetu Yesu atutayarishie njia ya kuja kwenu.'),
(2020167,69,52,3,12,'Bwana awawezeshe ninyi kupendana na kuwapenda watu wote zaidi na zaidi, kama vile sisi tunavyowapenda ninyi.'),
(2020168,69,52,3,13,'Hivyo ataiimarisha mioyo yenu, nanyi mtakuwa wakamilifu na watakatifu mbele ya Mungu na Baba yetu wakati Bwana wetu Yesu atakapokuja pamoja na wote walio wake.'),
(2020169,69,52,4,1,'Hatimaye, ndugu zangu, mmejifunza kutoka kwetu namna mnavyopaswa kuishi ili kumpendeza Mungu. Na kweli mmekuwa mnaishi hivyo. Sasa tunawaombeni na kuwasihi kwa jina la Bwana Yesu mfanye vema zaidi.'),
(2020170,69,52,4,2,'Maana mnayajua yale maagizo tuliyowapeni kwa mamlaka ya Bwana Yesu.'),
(2020171,69,52,4,3,'Mungu anataka ninyi muwe watakatifu na mjiepushe kabisa na maisha ya zinaa.'),
(2020172,69,52,4,4,'Kila mwanamume anapaswa kujua namna ya kuishi na mkewe kwa utakatifu na heshima,'),
(2020173,69,52,4,5,'na si kwa tamaa mbaya kama watu wa mataifa mengine wasiomjua Mungu.'),
(2020174,69,52,4,6,'Basi, mtu yeyote asimkosee au kumpunja mwenzake kuhusu jambo hili. Tulikwisha waambieni hayo na kuwaonya kwamba Bwana atawaadhibu wanaofanya mambo hayo.'),
(2020175,69,52,4,7,'Mungu hakutuita tuishi maisha ya zinaa, bali tuishi katika utakatifu.'),
(2020176,69,52,4,8,'Kwa hiyo basi, anayedharau mafundisho hayo hamdharau mtu, bali amdharau Mungu mwenyewe anayewapeni Roho wake Mtakatifu.'),
(2020177,69,52,4,9,'Hakuna haja ya kuwaandikieni juu ya kuwapenda ndugu zenu waumini. Ninyi wenyewe mmefundishwa na Mungu namna mnavyopaswa kupendana.'),
(2020178,69,52,4,10,'Na mmekuwa mkiwatendea hivyo ndugu zenu wote kila mahali katika Makedonia. Basi, ndugu tunawaombeni mfanye hata zaidi.'),
(2020179,69,52,4,11,'Muwe na nia ya kuishi maisha ya utulivu, kila mmoja ashughulikie mambo yake mwenyewe na afanye kazi kwa mikono yake mwenyewe kama tulivyowaagiza pale awali.'),
(2020180,69,52,4,12,'Kwa namna hiyo mtajipatia sifa nzuri kutoka kwa wale wasio Wakristo, na hamtakuwa na lazima ya kuwategemea wengine kwa mahitaji yenu.'),
(2020181,69,52,4,13,'Ndugu, twataka mjue ukweli kuhusu wale ambao wamekwisha fariki dunia, ili msipatwe na huzuni kama watu wengine wasio na matumaini.'),
(2020182,69,52,4,14,'Sisi tunaamini kwamba Yesu alikufa, akafufuka; na hivyo sisi tunaamini kwamba Mungu atawaleta pamoja na Yesu wale wote waliofariki wakiwa wanamwamini.'),
(2020183,69,52,4,15,'Hili tunalowaambieni ni fundisho la Bwana; sisi tulio hai, ambao tutakuwa tumebaki, wakati Bwana atakapokuja, hakika hatutawatangulia wale waliokwisha fariki dunia.'),
(2020184,69,52,4,16,'Maana patatolewa amri, sauti ya malaika mkuu, sauti ya tarumbeta ya Mungu, naye Bwana mwenyewe atashuka kutoka mbinguni. Ndipo wale waliokufa wakiwa wanamwamini Kristo watafufuliwa kwanza.'),
(2020185,69,52,4,17,'Kisha sisi tulio hai wakati huo tutakusanywa pamoja nao katika mawingu kumlaki Bwana hewani. Na hivyo tutakuwa daima pamoja na Bwana.'),
(2020186,69,52,4,18,'Basi, farijianeni kwa maneno haya.'),
(2020187,69,52,5,1,'Ndugu, hakuna haja ya kuwaandikieni juu ya nyakati na majira yatakapotukia mambo haya.'),
(2020188,69,52,5,2,'Maana ninyi wenyewe mwajua kwamba Siku ya Bwana itakuja kama mwizi ajavyo usiku.'),
(2020189,69,52,5,3,'Watu watakapokuwa wanasema: "Kila kitu ni shwari na salama" ndipo uharibifu utakapowaangukia ghafla! Mambo hayo yatatukia ghafla kama uchungu wa uzazi unavyomjia mama anayejifungua, wala watu hawataweza kuepukana nayo.'),
(2020190,69,52,5,4,'Lakini ninyi ndugu, hamko gizani, na siku hiyo haipaswi kuwajieni ghafla kama vile mwizi.'),
(2020191,69,52,5,5,'Ninyi nyote ni watu mnaoishi katika mwanga, watu wa mchana. Sisi si watu wa usiku, wala wa giza.'),
(2020192,69,52,5,6,'Basi, tusilale usingizi kama wengine; tunapaswa kukesha na kuwa na kiasi.'),
(2020193,69,52,5,7,'Wanaolala hulala usiku, na walevi hulewa usiku.'),
(2020194,69,52,5,8,'Lakini sisi ni watu wa mchana na tunapaswa kuwa na kiasi. Tunapaswa kuvaa imani na upendo kama vazi la kujikinga kifuani, na tumaini letu la wokovu kama kofia ya chuma.'),
(2020195,69,52,5,9,'Maana Mungu hakututeua ili tuangamizwe na ghadhabu yake, bali tuupate wokovu kwa njia ya Bwana wetu Yesu Kristo,'),
(2020196,69,52,5,10,'ambaye alikufa kwa ajili yetu, ili tuishi pamoja naye, iwe tu hai au tumekufa.'),
(2020197,69,52,5,11,'Kwa hiyo farijianeni na kusaidiana ninyi kwa ninyi kama mnavyofanya sasa.'),
(2020198,69,52,5,12,'Ndugu, tunawaombeni muwastahi wale wanaofanya kazi kati yenu, wale wanaowaongoza na kuwafundisheni kuhusu maisha ya Kikristo.'),
(2020199,69,52,5,13,'Wapeni heshima kubwa na kuwapenda kwa sababu ya kazi wanayofanya. Muwe na amani kati yenu.'),
(2020200,69,52,5,14,'Ndugu, tunawahimizeni muwaonye watu walio wavivu, muwatie moyo watu wanyonge, muwasaidie watu dhaifu, muwe na subira kwa wote.'),
(2020201,69,52,5,15,'Angalieni mtu yeyote asimlipe mwingine maovu kwa maovu, ila nia yenu iwe kutendeana mema daima na kuwatendea mema watu wote.'),
(2020202,69,52,5,16,'Furahini daima,'),
(2020203,69,52,5,17,'salini kila wakati');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020204,69,52,5,18,'na muwe na shukrani katika kila hali. Hayo ndiyo anayotaka Mungu kwenu katika kuungana kwenu na Kristo Yesu.'),
(2020205,69,52,5,19,'Msimpinge Roho Mtakatifu;'),
(2020206,69,52,5,20,'msidharau unabii.'),
(2020207,69,52,5,21,'Pimeni kila kitu: zingatieni kilicho chema,'),
(2020208,69,52,5,22,'na epukeni kila aina ya uovu.'),
(2020209,69,52,5,23,'Mungu anayetupatia amani awafanye ninyi watakatifu kwa kila namna na kuzilinda nafsi zenu--roho, mioyo na miili yenu--mbali na hatia yoyote wakati wa kuja kwake Bwana wetu Yesu Kristo.'),
(2020210,69,52,5,24,'Yeye anayewaita ninyi atafanya hivyo kwani ni mwaminifu.'),
(2020211,69,52,5,25,'Ndugu, tuombeeni na sisi pia.'),
(2020212,69,52,5,26,'Wasalimuni ndugu wote kwa ishara ya upendo.'),
(2020213,69,52,5,27,'Nawahimizeni kwa jina la Bwana muwasomee ndugu zetu wote barua hii.'),
(2020214,69,52,5,28,'Tunawatakieni neema ya Bwana wetu Yesu Kristo.'),
(2020215,69,53,1,1,'Mimi Paulo, Silwano na Timotheo tunawaandikia ninyi jumuiya ya kanisa la Thesalonike, ambao ni watu wake Mungu Baba yetu na wa Bwana Yesu Kristo.'),
(2020216,69,53,1,2,'Tunawatakieni neema na amani kutoka kwa Mungu Baba yetu na kwa Bwana Yesu Kristo.'),
(2020217,69,53,1,3,'Ndugu, tunapaswa kushukuru Mungu daima kwa ajili yenu. Inafaa kwetu kufanya hivyo kwani imani yenu inakua sana na kupendana kwenu kunaongezeka sana.'),
(2020218,69,53,1,4,'Ndio maana sisi tunajivunia ninyi katika makanisa ya Mungu. Tunaona fahari juu ya jinsi mnavyoendelea kuamini na kustahimili katika udhalimu wote na mateso mnayopata.'),
(2020219,69,53,1,5,'Hayo yote yanathibitisha kwamba hukumu ya Mungu ni ya haki, na matokeo yake ninyi mtastahili Utawala wake ambao kwa ajili yake mnateseka.'),
(2020220,69,53,1,6,'Mungu atafanya jambo la haki: atawalipa mateso wale wanaowatesa ninyi,'),
(2020221,69,53,1,7,'na kuwapeni nafuu ninyi mnaoteseka, na sisi pia. Atafanya jambo hilo wakati Bwana atakapotokea kutoka mbinguni pamoja na malaika wake na wakuu'),
(2020222,69,53,1,8,'na miali ya moto, kuwaadhibu wale wanaomkataa Mungu na wale wasiotii Habari Njema ya Bwana wetu Yesu.'),
(2020223,69,53,1,9,'Adhabu yao itakuwa kuangamizwa milele na kutengwa mbali na utukufu wake mkuu,'),
(2020224,69,53,1,10,'wakati atakapokuja Siku ile kupokea utukufu kutoka kwa watu wake na heshima kutoka kwa wote wanaoamini. Ninyi pia mtakuwa miongoni mwao, kwani mmeuamini ule ujumbe tuliowaletea.'),
(2020225,69,53,1,11,'Ndiyo maana tunawaombeeni daima. Tunamwomba Mungu wetu awawezeshe muyastahili maisha aliyowaitia myaishi. Tunamwomba, kwa uwezo wake, atimize nia yenu ya kutenda mema na kukamilisha kazi yenu ya imani.'),
(2020226,69,53,1,12,'Kwa namna hiyo, jina la Bwana wetu Yesu litapata utukufu kutoka kwenu, nanyi mtapata utukufu kutoka kwake kwa neema ya Mungu wetu na ya Bwana Yesu Kristo.'),
(2020227,69,53,2,1,'Sasa yahusu kuja kwake Bwana wetu Yesu Kristo na kukusanywa kwetu pamoja tukae naye. Ndugu, tunawaombeni sana'),
(2020228,69,53,2,2,'msifadhaike upesi moyoni, na wala msitiwe wasiwasi kwa sababu ya madai kwamba Siku ya Bwana imekwisha fika. Labda inadhaniwa kwamba jambo hili limetokana na uaguzi fulani, mahubiri au barua inayosemekana kuwa imetoka kwetu.'),
(2020229,69,53,2,3,'Msikubali kudanganywa na mtu yeyote kwa namna yoyote ile. Maana Siku hiyo haitakuja mpaka kwanza ule Uasi Mkuu utokee na yule Mwovu aonekane ambaye mwisho wake ni kuangamizwa kabisa.'),
(2020230,69,53,2,4,'Yeye atapinga kila kitu wanachokiona watu kuwa ni mungu, au wanachokiabudu. Naam, hata ataingia na kuketi ndani ya Hekalu la Mungu akijidai kuwa Mungu.'),
(2020231,69,53,2,5,'Je, hamkumbuki kwamba niliwaambieni haya yote wakati nilipokuwa pamoja nanyi?'),
(2020232,69,53,2,6,'Lakini kuna kitu kinachomzuia sasa, nanyi mwakijua kitu hicho. Basi, huyo Mwovu ataonekana wakati wake ufaao.'),
(2020233,69,53,2,7,'Hata hivyo, Mwovu huyo aliyefichika anafanya kazi sasa, lakini hataonekana mpaka yule anayemzuia aondolewe.'),
(2020234,69,53,2,8,'Hapo ndipo Mwovu atakapotokea; lakini Bwana Yesu anapokuja atamuua kwa pumzi ya kinywa chake na kumwangamiza kwa mng`ao wa kuja kwake.'),
(2020235,69,53,2,9,'Huyo Mwovu atakuja na nguvu za Shetani na kufanya kila namna ya miujiza na maajabu ya uongo,'),
(2020236,69,53,2,10,'na kutumia udanganyifu wa kila namna kwa wale walio katika mkumbo wa kupotea. Hao watapotea kwa sababu hawakuupokea na kuupenda ule ukweli ili waokolewe.'),
(2020237,69,53,2,11,'Ndiyo maana Mungu amewaweka chini ya nguvu ya upotovu, wauamini uongo.'),
(2020238,69,53,2,12,'Matokeo yake ni kwamba wote wasioamini ukweli, ila wafurahia dhambi, watahukumiwa.'),
(2020239,69,53,2,13,'Tunapaswa kumshukuru Mungu daima kwa ajili yenu ninyi ndugu, ninyi mnaopendwa na Bwana, kwa maana Mungu amewateua tangu mwanzo mpate kuokolewa kwa nguvu ya Roho mfanywe watu wake watakatifu kwa imani yenu katika ukweli.'),
(2020240,69,53,2,14,'Mungu aliwaitieni jambo hili kwa njia ya Habari Njema tuliyowahubirieni; aliwaiteni mpate kupokea sehemu yenu katika utukufu wa Bwana wetu Yesu Kristo.'),
(2020241,69,53,2,15,'Basi, ndugu, simameni imara na zingatieni yale mafundisho tuliyowafundisheni kwa mahubiri yetu na barua zetu.'),
(2020242,69,53,2,16,'Tunamwomba Bwana wetu Yesu Kristo mwenyewe na Mungu Baba yetu ambaye alitupenda, na kwa neema yake akatujalia faraja ya milele na tumaini jema,'),
(2020243,69,53,2,17,'aifariji mioyo yenu na kuwaimarisheni ili mweze daima kutenda na kusema yaliyo mema.'),
(2020244,69,53,3,1,'Hatimaye, ndugu, tuombeeni ili ujumbe wa Bwana uzidi kuenea upesi na kupokelewa kwa heshima kama vile ulivyo kati yenu.'),
(2020245,69,53,3,2,'Ombeni pia ili Mungu atuokoe na watu wapotovu na waovu, maana si wote wanaoamini ujumbe huu.'),
(2020246,69,53,3,3,'Lakini Bwana ni mwaminifu. Yeye atawaimarisheni na kuwalinda salama na yule Mwovu.'),
(2020247,69,53,3,4,'Naye Bwana anatupatia tumaini kubwa juu yenu, na hatuna shaka kwamba mnafanya na mtaendelea kufanya yale tuliyowaambieni.'),
(2020248,69,53,3,5,'Bwana aiongoze mioyo yenu katika upendo wa Mungu na katika uvumilivu tunaopewa na Kristo.'),
(2020249,69,53,3,6,'Ndugu, tunawaamuru kwa jina la Bwana wetu Yesu Kristo, mjiepushe na ndugu wote walio wavivu na ambao hawafuati maagizo tuliyowapa.'),
(2020250,69,53,3,7,'Ninyi wenyewe mnajua kwamba mnapaswa kufuata mfano wetu. Sisi tulipokuwa nanyi hatukuwa wavivu;'),
(2020251,69,53,3,8,'hatukula chakula kwa mtu yeyote bila ya kumlipa. Tulifanya kazi kwa bidii na taabu mchana na usiku ili tusiwe mzigo kwa mtu yeyote kati yenu.'),
(2020252,69,53,3,9,'Tulifanya hivyo si kwa kuwa hatuna haki ya kutaka msaada wenu, ila kwa sababu tunataka kuwapeni mfano.'),
(2020253,69,53,3,10,'Tulipokuwa pamoja nanyi tulikuwa tukiwaambieni, "Mtu asiyefanya kazi, asile."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020254,69,53,3,11,'Tunasema mambo hayo kwa sababu tumesikia kwamba wako baadhi yenu ambao ni wavivu na ambao hawafanyi chochote, isipokuwa tu kujiingiza katika mambo ya watu wengine.'),
(2020255,69,53,3,12,'Kwa jina la Bwana wetu Yesu Kristo tunawaamuru na kuwaonya watu hao wawe na nidhamu na kufanya kazi ili wajipatie maslahi yao wenyewe.'),
(2020256,69,53,3,13,'Lakini ninyi ndugu, msichoke kutenda mema.'),
(2020257,69,53,3,14,'Huenda kwamba huko kuna mtu ambaye hatautii huu ujumbe tunaowapelekeeni katika barua hii. Ikiwa hivyo, basi, mfichueni mtu huyo na msiwe na uhusiano wowote naye kusudi aone aibu.'),
(2020258,69,53,3,15,'Lakini msimtendee mtu huyo kama adui, bali mwonyeni kama ndugu.'),
(2020259,69,53,3,16,'Bwana mwenyewe ndiye chanzo cha amani, awajalieni amani siku zote kwa kila namna. Bwana awe nanyi nyote.'),
(2020260,69,53,3,17,'Kwa mkono wangu mwenyewe naandika hivi: Salamu kutoka kwa Paulo! Hivi ndivyo ninavyotia sahihi kila barua; ndivyo ninavyoandika.'),
(2020261,69,53,3,18,'Tunawatakieni nyote neema ya Bwana wetu Yesu Kristo.'),
(2020262,69,54,1,1,'Mimi Paulo, mtume wa Yesu Kristo kwa amri ya Mungu Mwokozi wetu na Yesu Kristo tumaini letu,'),
(2020263,69,54,1,2,'nakuandikia Timotheo mwanangu halisi katika imani. Nakutakia neema, huruma na amani kutoka kwa Mungu Baba yetu na Kristo Yesu Bwana wetu.'),
(2020264,69,54,1,3,'Napenda ukae huko Efeso, kama nilivyokuomba nilipokuwa ninakwenda Makedonia. Wako watu fulani huko wanaofundisha mafundisho ya uongo. Wakomeshe watu hao.'),
(2020265,69,54,1,4,'Waambie waachane na zile hadithi tupu na orodha ndefu za mababu, ambazo huleta tu ubishi, wala haviwajengi watu katika mpango ujulikanao kwa imani.'),
(2020266,69,54,1,5,'Shabaha ya amri hii ni kuhimiza mapendo yatokayo katika moyo safi, dhamiri njema, na imani ya kweli.'),
(2020267,69,54,1,6,'Watu wengine wamepotoka na kugeukia majadiliano yasiyo na maana.'),
(2020268,69,54,1,7,'Wanapenda kuwa walimu wa Sheria, lakini hawaelewi maneno yao wenyewe au mambo wanayosisitiza.'),
(2020269,69,54,1,8,'Twajua kwamba Sheria ni njema, kama ikitumiwa ipasavyo.'),
(2020270,69,54,1,9,'Lakini tunapaswa kukumbuka kwamba sheria haziwekwi kwa ajili ya watu wema, bali kwa ajili ya wahalifu na wasiotii, wasiomcha Mungu na wenye dhambi, watu wasio na dini na wa kidunia. Watu wanaowaua baba na mama zao, au wauaji wowote wale;'),
(2020271,69,54,1,10,'sheria imewekwa kwa ajili ya waasherati, wafiraji, wanaowaiba watu, waongo, na wanaoapa uongo au wanaofanya chochote ambacho ni kinyume cha mafundisho ya kweli.'),
(2020272,69,54,1,11,'Mafundisho hayo hupatikana katika Habari Njema ambayo mimi nimekabidhiwa niihubiri, Habari Njema ya Mungu mtukufu na mwenye heri.'),
(2020273,69,54,1,12,'Namshukuru Bwana wetu Yesu Kristo aliyenipa nguvu kwa ajili ya kazi yangu. Namshukuru kwa kuniona mimi kuwa ni mwaminifu, akaniteua nimtumikie,'),
(2020274,69,54,1,13,'ingawa pale awali mimi nilimtukana na kumtesa na kumdhulumu. Lakini Mungu alinionea huruma, kwa sababu sikuwa na imani bado, na hivyo sikujua nilichokuwa ninafanya.'),
(2020275,69,54,1,14,'Lakini Bwana wetu alinijalia neema yake kwa wingi, akanipa imani na upendo katika kuungana na Kristo Yesu.'),
(2020276,69,54,1,15,'Usemi huu ni wa kuaminika, na tena unafaa kukubaliwa kabisa: Kristo Yesu alikuja ulimwenguni kuwaokoa wenye dhambi. Nami ni mkosefu zaidi kuliko hao wote,'),
(2020277,69,54,1,16,'lakini Mungu alinionea huruma, ili Kristo aonyeshe uvumilivu wake wote kwangu mimi, kama mfano kwa wale wote ambao baadaye watamwamini na kupokea uzima wa milele.'),
(2020278,69,54,1,17,'Kwake yeye aliye Mfalme wa milele na asiyekufa, yeye aliye Mungu pekee--kwake viwe heshima na utukufu milele na milele! Amina.'),
(2020279,69,54,1,18,'Mwanangu Timotheo, nakukabidhi amri hii kufuatana na maneno ya unabii yaliyosemwa zamani juu yako. Yatumie maneno hayo yawe silaha yako katika kupigana vita vizuri,'),
(2020280,69,54,1,19,'na ushike imani yako na dhamiri njema. Watu wengine hawakusikiliza dhamiri zao na hivyo wakaiharibu imani yao.'),
(2020281,69,54,1,20,'Miongoni mwao ni Humenayo na Aleksanda ambao nimewakabidhi kwa Shetani, ili wafundishwe wasimtukane Mungu.'),
(2020282,69,54,2,1,'Kwanza kabisa, basi naomba dua, sala, maombi na sala za shukrani zitolewe kwa Mungu kwa ajili ya watu wote,'),
(2020283,69,54,2,2,'kwa ajili ya wafalme na wote wenye mamlaka, ili tupate kuishi maisha ya utulivu na amani pamoja na uchaji wa Mungu na mwenendo mwema.'),
(2020284,69,54,2,3,'Jambo hili ni jema na lampendeza Mungu Mwokozi wetu,'),
(2020285,69,54,2,4,'ambaye anataka watu wote waokolewe na wapate kuujua ukweli.'),
(2020286,69,54,2,5,'Maana yuko Mungu mmoja, na pia yuko mmoja anayewapatanisha watu na Mungu, binadamu Kristo Yesu,'),
(2020287,69,54,2,6,'ambaye alijitoa mwenyewe kuwakomboa watu wote. Huo ulikuwa uthibitisho, wakati ufaao ulipowadia.'),
(2020288,69,54,2,7,'Kwa sababu hiyo mimi nilitumwa niwe mtume na mwalimu wa watu wa mataifa, niutangaze ujumbe wa imani na ukweli. Nasema ukweli; sisemi uongo!'),
(2020289,69,54,2,8,'Basi, popote mnapokutana kufanya ibada nataka wanaume wasali, watu waliojitolea kweli na ambao wanaweza kuinua mikono yao wakisali bila hasira wala ubishi.'),
(2020290,69,54,2,9,'Hali kadhalika, nawataka wanawake wawe wanyofu na wenye busara kuhusu mavazi yao; wavae sawasawa na si kwa urembo wa mitindo ya kusuka nywele, kujipamba kwa dhahabu, lulu au mavazi ya gharama kubwa,'),
(2020291,69,54,2,10,'bali kwa matendo mema kama iwapasavyo wanawake wamchao Mungu.'),
(2020292,69,54,2,11,'Wanawake wanapaswa kukaa kimya na kuwa wanyenyekevu wakati wa kujifunza.'),
(2020293,69,54,2,12,'Mimi simruhusu mwanamke amfundishe au amtawale mwanamume; anapaswa kukaa kimya.'),
(2020294,69,54,2,13,'Maana Adamu aliumbwa kwanza, halafu Hawa.'),
(2020295,69,54,2,14,'Na wala si Adamu aliyedanganywa; bali mwanamke ndiye aliyedanganywa, akaivunja sheria ya Mungu.'),
(2020296,69,54,2,15,'Hata hivyo, mwanamke ataokolewa kwa kupata watoto, kama akidumu katika imani, upendo, utakatifu na unyofu.'),
(2020297,69,54,3,1,'Msemo huu ni wa kweli: mtu akitaka kuwa kiongozi katika kanisa, huyo anatamani kazi nzuri.'),
(2020298,69,54,3,2,'Basi, kiongozi wa kanisa anapaswa awe mtu asiye na lawama; anapaswa awe na mke mmoja tu, awe mwenye kiasi, nidhamu na utaratibu; ni lazima awe mkarimu na anayeweza kufundisha;'),
(2020299,69,54,3,3,'asiwe mlevi au mtu wa matata, bali awe mpole, apendaye amani; asiwe mtu wa kupenda fedha;'),
(2020300,69,54,3,4,'anapaswa awe mtu awezaye kuongoza vema nyumba yake, na kuwafanya watoto wake wawe watii kwa heshima yote.'),
(2020301,69,54,3,5,'Maana kama mtu hawezi kuongoza vema nyumba yake, atawezaje kulitunza kanisa la Mungu?'),
(2020302,69,54,3,6,'Mtu ambaye hajakomaa bado katika imani asifanywe kuwa kiongozi katika kanisa, asije akajaa majivuno na kuhukumiwa kama vile Ibilisi alivyohukumiwa.'),
(2020303,69,54,3,7,'Anapaswa awe mwenye sifa njema kati ya watu walio nje ya kanisa, ili asije akalaumiwa na kuanguka katika mtego wa Ibilisi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020304,69,54,3,8,'Wasaidizi katika kanisa wanapaswa pia kuwa watu wenye tabia njema na wanyofu; wasiwe wanywaji mno wa divai au wenye tamaa ya fedha;'),
(2020305,69,54,3,9,'wanapaswa kuzingatia kwa dhamiri njema ukweli wa ndani wa imani.'),
(2020306,69,54,3,10,'Ni lazima kwanza wathibitishwe, na wakionekana kuwa wanafaa, basi, watoe huduma yao.'),
(2020307,69,54,3,11,'Wake zao wanapaswa pia kuwa na tabia njema, wasiowasengenya watu, wenye kiasi na waaminifu katika mambo yote.'),
(2020308,69,54,3,12,'Msaidizi katika kanisa lazima awe na mke moja tu, na awezaye kuongoza vema watoto wake na nyumba yake.'),
(2020309,69,54,3,13,'Maana wasaidizi wanaofanya kazi yao vizuri hujipatia msimamo mzuri, na wanaweza kusema bila hofu juu ya imani yao katika Kristo Yesu.'),
(2020310,69,54,3,14,'Ninakuandikia barua hii nikiwa na matumaini ya kuja kwako hivi karibuni.'),
(2020311,69,54,3,15,'Lakini kama nikicheleweshwa, basi, barua hii itakufahamisha mwenendo tunaopaswa kuwa nao katika nyumba ya Mungu, ambayo ni kanisa la Mungu aliye hai, na ambalo ni nguzo na msingi wa ukweli.'),
(2020312,69,54,3,16,'Hakuna mashaka yoyote juu ya ukuu wa siri ya dini yetu: Alionekana katika umbo la kibinadamu alithibitishwa na Roho kuwa ni mwadilifu, akaonekana na malaika. Alihubiriwa kati ya mataifa, aliaminiwa popote ulimwenguni, akachukuliwa juu mbinguni katika utukufu.'),
(2020313,69,54,4,1,'Roho asema waziwazi kwamba siku za baadaye watu wengine wataitupilia mbali imani; watazitii roho danganyifu na kufuata mafundisho ya pepo.'),
(2020314,69,54,4,2,'Mafundisho ya namna hiyo yanaenezwa na watu waongo wadanganyifu, ambao dhamiri zao ziko kama zimechomwa kwa chuma cha moto.'),
(2020315,69,54,4,3,'Watu hao hufundisha kwamba ni makosa kuona na pia kula vyakula fulani. Lakini Mungu aliviumba vyakula hivyo, ili wale walio waumini na ambao wanapata kuujua ukweli, wavitumie kwa shukrani.'),
(2020316,69,54,4,4,'Kila kitu alichoumba Mungu ni chema, wala hakuna kinachohitaji kukataliwa, bali vyote vipokelewe kwa sala ya shukrani,'),
(2020317,69,54,4,5,'kwa sababu neno la Mungu na sala hukifanya kitu hicho kikubalike kwa Mungu.'),
(2020318,69,54,4,6,'Kama ukiwapa ndugu wote maagizo haya, utakuwa mtumishi mwema wa Kristo Yesu, ukijiendeleza kiroho kwa maneno ya imani na mafundisho ya kweli, ambayo wewe umeyafuata.'),
(2020319,69,54,4,7,'Lakini achana na hadithi zile zisizo za kidini na ambazo hazina maana. Jizoeshe kuishi maisha ya uchaji wa Mungu.'),
(2020320,69,54,4,8,'Mazoezi ya mwili yana faida yake, lakini mazoezi ya kiroho yana faida za kila namna, maana yanatuahidia uzima katika maisha ya sasa, na pia hayo yanayokuja.'),
(2020321,69,54,4,9,'Usemi huo ni wa kusadikika kabisa na unastahili kukubaliwa.'),
(2020322,69,54,4,10,'Sisi tunajitahidi na kufanya kazi kwa bidii kwani tumemwekea tumaini letu Mungu aliye hai ambaye ni Mwokozi wa watu wote, na hasa wale wanaoamini.'),
(2020323,69,54,4,11,'Wape maagizo hayo na mafundisho hayo.'),
(2020324,69,54,4,12,'Usikubali mtu yeyote akudharau kwa sababu wewe ni kijana, lakini jitahidi uwe mfano kwa wanaoamini: katika usemi wako, mwenendo wako, upendo, imani na maisha safi.'),
(2020325,69,54,4,13,'Tumia wakati wako na juhudi yako katika kusoma hadharani Maandiko Matakatifu, kuhubiri na kufundisha, mpaka nitakapokuja.'),
(2020326,69,54,4,14,'Usiache kukitumia kile kipaji cha Kristo ndani yako ulichopewa kwa maneno ya manabii na kwa kuwekewa mikono na wazee.'),
(2020327,69,54,4,15,'Fikiri kwa makini juu ya hayo yote na kuyatekeleza kusudi maendeleo yako yaonekane na wote.'),
(2020328,69,54,4,16,'Angalia sana mambo yako mwenyewe, na mafundisho yako. Endelea kufanya hayo maana ukifanya hivyo utajiokoa mwenyewe na wale wanaokusikiliza.'),
(2020329,69,54,5,1,'Usimkemee mtu mzee, bali msihi kama vile angekuwa baba yako. Watendee vijana kama ndugu zako,'),
(2020330,69,54,5,2,'wanawake wazee kama mama yako, na wasichana kama dada zako, kwa usafi wote.'),
(2020331,69,54,5,3,'Waheshimu wanawake wajane walio wajane kweli.'),
(2020332,69,54,5,4,'Lakini mjane aliye na watoto au wajukuu, hao wanapaswa kujifunza kutimiza wajibu wao wa kidini kwa jamaa zao wenyewe na hivyo kuwalipa wazazi wao na wazee wao, kwani hilo ni jambo la kupendeza mbele ya Mungu.'),
(2020333,69,54,5,5,'Mwanamke mjane kweli, asiye na mtu wa kumsaidia, amemwekea Mungu tumaini lake na huendelea kusali na kumwomba msaada usiku na mchana.'),
(2020334,69,54,5,6,'Lakini mwanamke ambaye huishi maisha ya anasa, huyo amekufa, ingawa yu hai.'),
(2020335,69,54,5,7,'Wape maagizo haya, wasije wakawa na lawama.'),
(2020336,69,54,5,8,'Lakini kama mtu hawatunzi watu wa jamaa yake, hasa wale wa nyumbani kwake, basi, mtu huyo ameikana imani, na ni mbaya zaidi kuliko mtu asiyeamini.'),
(2020337,69,54,5,9,'Usimtie katika orodha ya wajane, mjane yeyote ambaye hajatimiza miaka sitini. Tena awe amepata kuolewa mara moja tu,'),
(2020338,69,54,5,10,'na awe mwenye sifa nzuri: aliyewalea watoto wake vizuri, aliyewakaribisha wageni nyumbani kwake, aliyewaosha miguu watu wa Mungu, aliyewasaidia watu wenye taabu, na aliyejitolea kufanya mambo mema.'),
(2020339,69,54,5,11,'Usiwaandikishe wajane vijana, kwani kama tamaa zao za maumbile zikizidi kuwa na nguvu zaidi kuliko kujitolea kwao kwa Kristo watataka kuolewa tena,'),
(2020340,69,54,5,12,'na wataonekana kukosa uaminifu kuhusu ahadi yao ya pale awali.'),
(2020341,69,54,5,13,'Wajane kama hao huanza kupoteza wakati wao wakizurura nyumba hata nyumba; tena ubaya zaidi ni kwamba huanza kuwasengenya watu, na kujitia katika mambo ya watu wengine, huku wakisema mambo ambayo hawangepaswa kusema.'),
(2020342,69,54,5,14,'Kwa hiyo ningependelea wajane vijana waolewe, wapate watoto na kutunza nyumba zao ili adui zetu wasipewe nafasi ya kusema mambo maovu juu yetu.'),
(2020343,69,54,5,15,'Kwa maana wajane wengine wamekwisha potoka na kumfuata Shetani.'),
(2020344,69,54,5,16,'Lakini kama mama Mkristo anao wajane katika jamaa yake, yeye anapaswa kuwatunza na si kuliachilia kanisa mzigo huo, ili kanisa liweze kuwatunza wajane wale waliobaki peke yao kabisa.'),
(2020345,69,54,5,17,'Wazee wanaowaongoza watu vizuri wanastahili kupata riziki maradufu, hasa wale wanaofanya bidii katika kuhubiri na kufundisha.'),
(2020346,69,54,5,18,'Maana Maandiko Matakatifu yasema: "Usimfunge ng`ombe kinywa anapopura nafaka." na tena "Mfanyakazi astahili malipo yake."'),
(2020347,69,54,5,19,'Usikubali kupokea mashtaka dhidi ya mzee yasipowakilishwa na mashahidi wawili au watatu.'),
(2020348,69,54,5,20,'Wale wanaotenda dhambi waonye hadharani, ili wengine wapate kuogopa.'),
(2020349,69,54,5,21,'Nakuamuru mbele ya Mungu, mbele ya Kristo Yesu, na mbele ya malaika watakatifu uyazingatie maagizo haya bila kuacha hata moja, wala kumpendelea mtu yeyote katika kila unachotenda.'),
(2020350,69,54,5,22,'Usiharakishe kumwekea mtu yeyote mikono kwa ajili ya kumtumikia Bwana. Usishiriki dhambi za wengine; jiweke katika hali safi.'),
(2020351,69,54,5,23,'Usinywe maji tu, bali unywe divai kidogo kwa ajili ya tumbo lako, kwani unaugua mara kwa mara.'),
(2020352,69,54,5,24,'Dhambi za watu wengine huonekana waziwazi, nazo zawatangulia kwenye hukumu; lakini dhambi za wengine huonekana tu baadaye.'),
(2020353,69,54,5,25,'Vivyo hivyo, matendo mema huonekana waziwazi, na hata yale ambayo si dhahiri hayawezi kufichika.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020354,69,54,6,1,'Watumwa wote wanapaswa kuwaheshimu wakuu wao ili kusiwe na sababu ya watu kulitukana jina la Mungu na mafundisho yetu.'),
(2020355,69,54,6,2,'Watumwa ambao wakuu wao ni Wakristo wasiwadharau kwani ni ndugu zao. Badala yake, wanapaswa kuwatumikia hata vizuri zaidi, maana hao wanaopata faida kutokana na kazi yao ni waumini ambao wanawapenda. Unapaswa kufundisha na kuhubiri mambo haya.'),
(2020356,69,54,6,3,'Mtu yeyote anayefundisha kinyume cha mambo haya, na ambaye hakubaliani na maneno ya kweli ya Bwana wetu Yesu Kristo na mafundisho ya dini,'),
(2020357,69,54,6,4,'huyo amejaa majivuno na wala hajui chochote. Ni mtu wa kupenda ubishi na magombano juu ya maneno matupu, na hiyo husababisha wivu, ugomvi, matusi, shuku mbaya,'),
(2020358,69,54,6,5,'na ubishi usio na kikomo kutoka kwa watu ambao akili zao zimeharibika, na ambao hawana tena ukweli. Wanadhani dini ni njia ya kujipatia utajiri.'),
(2020359,69,54,6,6,'Kweli dini humfanya mtu awe tajiri sana, ikiwa anatosheka na vitu alivyo navyo.'),
(2020360,69,54,6,7,'Maana hatukuleta kitu chochote hapa duniani, wala hatutachukua chochote.'),
(2020361,69,54,6,8,'Kwa hiyo basi, kama tunacho chakula na mavazi, tunapaswa kuridhika navyo.'),
(2020362,69,54,6,9,'Lakini wale wanaotaka kutajirika huanguka katika majaribu, na kunaswa katika mtego wa tamaa nyingi mbaya za kipumbavu, ambazo huwavuta mpaka kwenye uharibifu na maangamizi.'),
(2020363,69,54,6,10,'Kwa maana kupenda sana fedha ni chanzo cha uovu wote. Watu wengine wametamani sana kupata fedha hata wakatangatanga mbali na imani, na wameivunja mioyo yao kwa huzuni nyingi.'),
(2020364,69,54,6,11,'Lakini wewe, mtu wa Mungu, jiepushe na mambo hayo. Zingatia uadilifu, uchaji wa Mungu, imani, mapendo, subira na unyenyekevu.'),
(2020365,69,54,6,12,'Piga mbio kadiri uwezavyo katika shindano la mbio za imani, ukajipatie tuzo la uzima wa milele, uliloitiwa wakati ulipokiri imani yako mbele ya mashahidi wengi.'),
(2020366,69,54,6,13,'Mbele ya Mungu anayevipa vitu vyote uhai, na mbele ya Yesu Kristo aliyetoa ushahidi na kukiri ukweli mbele ya Pontio Pilato,'),
(2020367,69,54,6,14,'nakuamuru ushike maagizo yako na kuyatii kwa uaminifu mpaka Siku ile atakapotokea Bwana wetu Yesu Kristo.'),
(2020368,69,54,6,15,'Kutokea kwake kutafanyika wakati ufaao uliopangwa na Mungu mwenye heri na aliye Mtawala pekee, Mfalme wa wafalme, na Bwana wa mabwana.'),
(2020369,69,54,6,16,'Yeye peke yake anaishi milele, katika mwanga usioweza kukaribiwa na mtu. Hakuna mtu aliyepata kumwona au awezaye kumwona. Kwake iwe heshima na uwezo wa milele! Amina.'),
(2020370,69,54,6,17,'Waamuru watu walio matajiri katika mambo ya maisha ya sasa, wasijivune, wasiweke tumaini lao katika mali isiyoweza kutegemewa; bali wamtegemee Mungu, ambaye kwa ukarimu hutupatia vitu vyote tuvifurahie.'),
(2020371,69,54,6,18,'Waamuru watende mema, wawe matajiri katika matendo mema, na wawe wakarimu na walio tayari kuwashirikisha wengine mali zao.'),
(2020372,69,54,6,19,'Kwa namna hiyo watajiwekea hazina ambayo itakuwa kwao msingi imara kwa wakati ujao. Hapo wataweza kujipatia uzima ambao ni uzima wa kweli.'),
(2020373,69,54,6,20,'Timotheo, tunza salama yote yale uliyokabidhiwa. Jiepushe na majadiliano ya kidunia na ubishi wa kipumbavu juu ya kile wanachokiita watu wengine: "Elimu".'),
(2020374,69,54,6,21,'Maana wengine wamejidai kuwa na hiyo elimu, na matokeo yake wamepoteza imani. Nawatakieni nyote neema!'),
(2020375,69,55,1,1,'Mimi Paulo, ambaye Mungu alitaka niwe mtume wa Kristo Yesu ili niutangaze ule uzima tulioahidiwa katika kuungana na Kristo Yesu,'),
(2020376,69,55,1,2,'nakuandikia wewe mwanangu mpenzi Timotheo. Nakutakia neema, huruma na amani kutoka kwa Mungu Baba na Kristo Yesu Bwana wetu.'),
(2020377,69,55,1,3,'Ninamshukuru Mungu ambaye ninamtumikia kwa dhamiri safi kama walivyofanya wazee wangu; namshukuru kila ninapokukumbuka daima katika sala zangu.'),
(2020378,69,55,1,4,'Nakumbuka machozi yako na ninatamani usiku na mchana kukuona, ili nijazwe furaha.'),
(2020379,69,55,1,5,'Naikumbuka imani yako ya kweli, imani aliyokuwa nayo nyanya yako Loisi, na pia mama yako Eunike. Nina hakika kwamba wewe pia unayo.'),
(2020380,69,55,1,6,'Ndio maana nakukumbusha ukiweke motomoto kile kipaji ulichopewa na Mungu wakati nilipokuwekea mikono yangu.'),
(2020381,69,55,1,7,'Kwa maana Mungu hakutupa Roho wa kutufanya tuwe waoga, bali alitupa Roho wa kutujalia nguvu, upendo na nidhamu.'),
(2020382,69,55,1,8,'Basi, usione haya kumshuhudia Bwana wetu, wala usione haya kwa sababu yangu mimi niliye mfungwa kwa ajili yake. Lakini shiriki katika mateso kwa ajili ya Habari Njema, kadiri ya nguvu unazopewa na Mungu.'),
(2020383,69,55,1,9,'Yeye alituokoa, akatuita tuwe watu wake yeye mwenyewe, si kwa sababu ya matendo yetu wenyewe bali kwa sababu ya kusudi lake na neema yake. Alitujalia neema hiyo katika Kristo Yesu kabla mwanzo wa nyakati;'),
(2020384,69,55,1,10,'lakini sasa imefunuliwa kwetu kwa kuja kwake Mwokozi wetu Yesu Kristo. Yeye amekomesha nguvu za kifo, na kwa njia ya Habari Njema akadhihirisha uzima usio kufa.'),
(2020385,69,55,1,11,'Mungu amenichagua mimi niwe mtume na mwalimu kwa ajili ya kuhubiri Habari Njema,'),
(2020386,69,55,1,12,'nami nateseka mambo haya kwa sababu hiyo. Lakini niko bado timamu kabisa kwani namjua yule niliyemwamini, tena nina hakika kwamba yeye aweza kukilinda salama kile alichonikabidhi, mpaka Siku ile.'),
(2020387,69,55,1,13,'Shika kwa makini mafundisho yale ya kweli niliyokufundisha, na kubaki katika hiyo imani na huo upendo wetu katika kuungana na Kristo Yesu.'),
(2020388,69,55,1,14,'Jambo lile bora ulilokabidhiwa lilinde kwa nguvu ya Roho Mtakatifu anayeishi ndani yetu.'),
(2020389,69,55,1,15,'Kama unavyojua, watu wote mkoani Asia wameniacha, miongoni mwao wakiwa Fugelo na Hermogene.'),
(2020390,69,55,1,16,'Bwana aihurumie jamaa ya Onesiforo, kwa sababu aliniburudisha rohoni mara nyingi, wala hakuona haya kwa kuwa nilikuwa kifungoni,'),
(2020391,69,55,1,17,'ila mara tu alipofika Roma, alianza kunitafuta kwa bidii mpaka akanipata.'),
(2020392,69,55,1,18,'Bwana amjalie huruma katika Siku ile! Nawe wajua vizuri mengi aliyonifanyia huko Efeso.'),
(2020393,69,55,2,1,'Basi, wewe mwanangu, uwe na nguvu katika neema tunayopata katika kuungana na Kristo Yesu.'),
(2020394,69,55,2,2,'Chukua yale mafundisho uliyonisikia nikitangaza mbele ya mashahidi wengi, uyakabidhi kwa watu wanaoaminika, ambao wataweza kuwafundisha wengine pia.'),
(2020395,69,55,2,3,'Shiriki katika mateso kama askari mwaminifu wa Kristo yesu.'),
(2020396,69,55,2,4,'Mwanajeshi vitani hujiepusha na shughuli za maisha ya kawaida ili aweze kumpendeza mkuu wa jeshi.'),
(2020397,69,55,2,5,'Mwanariadha yeyote hawezi kushinda na kupata zawadi ya ushindi kama asipozitii sheria za michezo.'),
(2020398,69,55,2,6,'Mkulima ambaye amefanya kazi ngumu anastahili kupata sehemu ya kwanza ya mavuno.'),
(2020399,69,55,2,7,'Fikiria hayo ninayosema, kwani Bwana atakuwezesha uyaelewe yote.'),
(2020400,69,55,2,8,'Mkumbuke Yesu Kristo aliyefufuliwa kutoka wafu, aliyekuwa wa ukoo wa Daudi, kama isemavyo Habari Njema ninayoihubiri.'),
(2020401,69,55,2,9,'Kwa sababu ya kuihubiri Habari Njema mimi nateseka na nimefungwa minyororo kama mhalifu. Lakini neno la Mungu haliwezi kufungwa minyororo,'),
(2020402,69,55,2,10,'na hivyo navumilia kila kitu kwa ajili ya wateule wa Mungu, ili wao pia wapate ukombozi upatikanao kwa njia ya Yesu Kristo, na ambao huleta utukufu wa milele.'),
(2020403,69,55,2,11,'Usemi huu ni wa kweli: "Ikiwa tulikufa pamoja naye, tutaishi pia pamoja naye.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020404,69,55,2,12,'Tukiendelea kuvumilia, tutatawala pia pamoja naye. Tukimkana, naye pia atatukana.'),
(2020405,69,55,2,13,'Tukikosa kuwa waaminifu, yeye hubaki mwaminifu daima, maana yeye hawezi kujikana mwenyewe."'),
(2020406,69,55,2,14,'Basi, wakumbushe watu wako mambo haya, na kuwaonya mbele ya Mungu waache ubishi juu ya maneno. Ubishi huo haufai, ila huleta tu uharibifu mkuu kwa wale wanaousikia.'),
(2020407,69,55,2,15,'Jitahidi kupata kibali kamili mbele ya Mungu kama mfanyakazi ambaye haoni haya juu ya kazi yake, na ambaye hufundisha sawa ule ujumbe wa kweli.'),
(2020408,69,55,2,16,'Jiepushe na majadiliano ya kidunia na ya kipumbavu; kwani hayo huzidi kuwatenga watu mbali na Mungu.'),
(2020409,69,55,2,17,'Mafundisho ya aina hiyo ni kama donda linalokula mwili. Miongoni mwa hao waliofundisha hayo ni Humenayo na Fileto.'),
(2020410,69,55,2,18,'Hawa wamepotoka kabisa mbali na ukweli, na wanatia imani ya watu wengine katika wasiwasi kwa kusema ati ufufuo wetu umekwisha fanyika.'),
(2020411,69,55,2,19,'Lakini msingi thabiti uliowekwa na Mungu uko imara, na juu yake yameandikwa maneno haya: "Bwana anawafahamu wale walio wake," na "Kila asemaye yeye ni wa Bwana, ni lazima aachane na uovu."'),
(2020412,69,55,2,20,'Katika nyumba kubwa kuna mabakuli na vyombo vya kila namna: vingine ni vya fedha na dhahabu, vingine vya mbao na udongo, vingine ni vya matumizi ya pekee na vingine kwa ajili ya matumizi ya kawaida.'),
(2020413,69,55,2,21,'Basi, kama mtu atajitakasa kwa kujitenga mbali na mambo hayo yote maovu, atakuwa chombo cha matumizi ya pekee, kwa sababu amewekwa wakfu, anamfaa Bwana wake na yupo tayari kwa kila kazi njema.'),
(2020414,69,55,2,22,'Jiepushe na tamaa za ujana, fuata uadilifu, imani, upendo, amani, pamoja na watu wote ambao wanamwomba Bwana kwa moyo safi.'),
(2020415,69,55,2,23,'Epuka ubishi wa kijinga na kipumbavu; wajua kwamba hayo huleta magomvi.'),
(2020416,69,55,2,24,'Mtumishi wa Bwana asigombane. Anapaswa kuwa mpole kwa watu wote, mwalimu mwema na mvumilivu,'),
(2020417,69,55,2,25,'ambaye ni mpole anapowaonya wapinzani wake, kwani huenda Mungu akawajalia nafasi ya kutubu, wakapata kuujua ukweli.'),
(2020418,69,55,2,26,'Hapo fahamu zao zitawarudia tena, wakaponyoka katika mtego wa Ibilisi aliyewanasa na kuwafanya wayatii matakwa yake.'),
(2020419,69,55,3,1,'Kumbuka kwamba, katika siku za mwisho kutakuwa na nyakati za taabu.'),
(2020420,69,55,3,2,'watu watakuwa na ubinafsi, wenye tamaa ya fedha, wenye majivuno, wenye kujiona, wenye kumtukana Mungu, wasiowatii wazazi wao, wasio na shukrani na waovu;'),
(2020421,69,55,3,3,'watatokea watu wasio na upendo moyoni, wasio na huruma, wachongezi, walafi na wakali; watachukia chochote kilicho chema;'),
(2020422,69,55,3,4,'watakuwa wahaini, wakaidi na waliojaa kiburi; watapenda anasa kuliko kumpenda Mungu.'),
(2020423,69,55,3,5,'Kwa nje wataonekana kama watu wenye kumcha Mungu, lakini wataikana nguvu yake. Jiepushe kabisa na watu wa namna hiyo.'),
(2020424,69,55,3,6,'Baadhi yao huenda katika nyumba za watu na huwateka wanawake dhaifu waliolemewa mizigo ya dhambi na ambao wanaongozwa na tamaa za kila aina;'),
(2020425,69,55,3,7,'wanawake ambao wanajaribu daima kujifunza lakini hawawezi kuufikia ujuzi wa huo ukweli.'),
(2020426,69,55,3,8,'Watu hao huupinga ukweli kama vile Yane na Yambre walivyompinga Mose.'),
(2020427,69,55,3,9,'Lakini hawataweza kuendelea zaidi kwa maana upumbavu wao utaonekana wazi kwa wote. Ndivyo ilivyokuwa kwa akina Yane na Yambre.'),
(2020428,69,55,3,10,'Wewe lakini, umeyafuata mafundisho yangu, mwenendo wangu, makusudi yangu katika maisha, imani yangu, uvumilivu wangu, upendo wangu, subira yangu,'),
(2020429,69,55,3,11,'udhalimu na mateso yangu. Unayajua mambo yaliyonipata huko Antiokia, Ikonio na Lustra. Nilivumilia udhalimu mkubwa mno! Lakini Bwana aliniokoa katika mambo hayo yote.'),
(2020430,69,55,3,12,'Kila mtu anayetaka kuishi maisha ya kumcha Mungu katika kuungana na Kristo Yesu lazima adhulumiwe.'),
(2020431,69,55,3,13,'Watu waovu na wadanyanyifu watazidi kuwa waovu zaidi na zaidi kwa kuwadanganya wengine na kudanganyika wao wenyewe.'),
(2020432,69,55,3,14,'Lakini wewe dumu katika ukweli ule uliofundishwa, ukaukubali kabisa. Unawajua wale waliokuwa walimu wako.'),
(2020433,69,55,3,15,'Unakumbuka kwamba tangu utoto wako umeyajua Maandiko Matakatifu ambayo yaweza kukupatia hekima iletayo wokovu kwa njia ya imani kwa Kristo Yesu.'),
(2020434,69,55,3,16,'Maandiko yote Matakatifu yameandikwa kwa uongozi wa Mungu, na yanafaa katika kufundishia ukweli, kuonya, kusahihisha makosa, na kuwaongoza watu waishi maisha adili,'),
(2020435,69,55,3,17,'ili mtu anayemtumikia Mungu awe mkamilifu, na tayari kabisa kufanya kila tendo jema.'),
(2020436,69,55,4,1,'Nakuamuru mbele ya Mungu, na mbele ya Kristo Yesu atakayewahukumu watu walio hai na wafu, na kwa sababu anakuja kutawala akiwa Mfalme:'),
(2020437,69,55,4,2,'hubiri huo ujumbe, sisitiza kuutangaza (iwe ni wakati wa kufaa au wakati usiofaa), karipia, onya na himiza watu ukiwafundisha kwa uvumilivu wote.'),
(2020438,69,55,4,3,'Utakuja wakati ambapo watu hawatasikiliza mafundisho ya kweli, ila watafuata tamaa zao wenyewe na kujikusanyia walimu tele watakaowaambia mambo yale tu ambayo masikio yao yako tayari kusikia.'),
(2020439,69,55,4,4,'Watakataa kuusikia ukweli, watageukia hadithi za uongo.'),
(2020440,69,55,4,5,'Wewe, lakini, uwe macho katika kila hali; vumilia mateso, fanya kazi ya mhubiri wa Habari Njema, timiza kikamilifu utumishi wako.'),
(2020441,69,55,4,6,'Kwa upande wangu mimi, niko karibu kabisa kutolewa dhabihu na wakati wa kufariki kwangu umefika.'),
(2020442,69,55,4,7,'Nimefanya bidii katika mashindano, nimemaliza safari yote na imani nimeitunza.'),
(2020443,69,55,4,8,'Na sasa imebakia tu kupewa tuzo la ushindi kwa maisha ya uadilifu, tuzo ambalo Bwana Hakimu wa haki, atanipa mimi Siku ile na wala si mimi tu, ila na wale wote wanaotazamia kwa upendo kutokea kwake.'),
(2020444,69,55,4,9,'Fanya bidii kuja kwangu karibuni.'),
(2020445,69,55,4,10,'Dema ameupenda ulimwengu huu akaniacha na kwenda zake Thesalonike. Kreske amekwenda Galatia, na Tito amekwenda Dalmatia.'),
(2020446,69,55,4,11,'Luka peke yake ndiye aliye hapa pamoja nami. Mpate Marko uje naye, kwa maana ataweza kunisaidia katika kazi yangu.'),
(2020447,69,55,4,12,'Nilimtuma Tukiko kule Efeso.'),
(2020448,69,55,4,13,'Utakapokuja niletee koti langu nililoacha kwa Karpo kule Troa; niletee pia vile vitabu, na hasa vile vilivyotengenezwa kwa ngozi. ic'),
(2020449,69,55,4,14,'Yule sonara aitwaye Aleksanda amenitendea maovu mengi; Bwana atamlipa kufuatana na hayo matendo yake.'),
(2020450,69,55,4,15,'Jihadhari naye kwa sababu aliupinga ujumbe wetu kwa ukali.'),
(2020451,69,55,4,16,'Wakati nilipojitetea kwa mara ya kwanza hakuna mtu aliyesimama upande wangu; wote waliniacha. Mungu asiwahesabie kosa hilo!'),
(2020452,69,55,4,17,'Lakini, Bwana alikaa pamoja nami, akanipa nguvu, hata nikaweza kuutangaza ujumbe wote, watu wa mataifa wausikie; tena nikaokolewa katika hukumu ya kifo kama kinywani mwa simba.'),
(2020453,69,55,4,18,'Bwana ataniokoa na mambo yote maovu, na kunichukua salama mpaka katika Utawala wake wa mbinguni. Kwake uwe utukufu milele na milele! Amina.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020454,69,55,4,19,'Wasalimu Priska na Akula, pamoja na jamaa ya Onesiforo.'),
(2020455,69,55,4,20,'Erasto alibaki Korintho, naye Trofimo nilimwacha Mileto kwa sababu alikuwa mgonjwa.'),
(2020456,69,55,4,21,'Fanya bidii kuja kabla ya majira ya baridi. Ebulo, Pude, Lino na Klaudia wanakusalimu; vilevile ndugu wengine wote.'),
(2020457,69,55,4,22,'Bwana awe nawe rohoni mwako. Nawatakieni nyote neema.'),
(2020458,69,56,1,1,'Mimi Paulo, mtumishi wa Mungu na mtume wa Yesu Kristo naandika. Mimi nimechaguliwa kuijenga imani ya wateule wa Mungu na kuwaongoza waufahamu ukweli wa dini yetu,'),
(2020459,69,56,1,2,'ambayo msingi wake ni tumaini la kupata uzima wa milele. Mungu ambaye hasemi uongo, alituahidia uzima huo kabla ya mwanzo wa nyakati,'),
(2020460,69,56,1,3,'na wakati ufaao ulipowadia, akaudhihirisha katika ujumbe wake. Mimi nilikabidhiwa ujumbe huo nuutangaze kufuatana na amri ya Mungu, Mwokozi wetu.'),
(2020461,69,56,1,4,'Ninakuandikia wewe Tito, mwanangu wa kweli katika imani tunayoshiriki. Nakutakia neema na amani kutoka kwa Mungu Baba, na kutoka kwa Kristo Yesu, Mkombozi wetu.'),
(2020462,69,56,1,5,'Nilikuacha Krete ili urekebishe yale mambo ambayo hayakuwa yamekamilika bado, na kuwateua wazee wa kanisa katika kila mji. Kumbuka maagizo yangu:'),
(2020463,69,56,1,6,'mzee wa kanisa anapaswa kuwa mtu asiye na hatia; aliye na mke mmoja tu, na watoto wake wanapaswa kuwa waumini, wasiojulikana kuwa wakorofi au wakaidi.'),
(2020464,69,56,1,7,'Maana kwa vile kiongozi wa kanisa ni mkurugenzi wa kazi ya Mungu, anapaswa kuwa mtu asiye na hatia. Asiwe mwenye majivuno, mwepesi wa hasira, mlevi, mkorofi au mchoyo.'),
(2020465,69,56,1,8,'Anapaswa kuwa mkarimu na anayependa mambo mema. Anapaswa kuwa mtu mtaratibu, mwadilifu, mtakatifu na mwenye nidhamu.'),
(2020466,69,56,1,9,'Ni lazima ashike kikamilifu ujumbe ule wa kuaminika kama unavyofundishwa. Ndivyo atakavyoweza kuwatia wengine moyo kwa mafundisho ya kweli na kuyafichua makosa ya wale wanaoyapinga mafundisho hayo.'),
(2020467,69,56,1,10,'Maana, wako watu wengi, hasa wale walioongoka kutoka dini ya Kiyahudi, ambao ni wakaidi, wanaowapotosha wengine kwa upumbavu wao.'),
(2020468,69,56,1,11,'Lazima kukomesha maneno yao, kwani wanavuruga jumuiya nzima kwa kufundisha mambo ambayo hawapaswi kufundisha; wanafanya hivyo kwa nia mbaya ya kupata faida ya fedha.'),
(2020469,69,56,1,12,'Hata mmoja wa manabii wao, ambaye naye pia ni Mkrete, alisema: "Wakrete, husema uongo daima; ni kama wanyama wabaya, walafi na wavivu!"'),
(2020470,69,56,1,13,'Naye alitoboa ukweli kwa sababu hiyo, unapaswa kuwakaripia vikali, ili wawe na imani kamilifu.'),
(2020471,69,56,1,14,'Wasiendelee kushikilia hadithi tupu za Kiyahudi na maagizo ya kibinadamu yanayozuka kwa watu walioukataa ukweli.'),
(2020472,69,56,1,15,'Kila kitu ni safi kwa watu walio safi; lakini hakuna chochote kilicho safi kwa wale waliochafuliwa na wasioamini, maana dhamiri na akili zao zimechafuliwa.'),
(2020473,69,56,1,16,'Watu kama hao hujidai kwamba wanamjua Mungu, lakini kwa matendo yao humkana. Ni watu wa kuchukiza mno na wakaidi, hawafai kwa jambo lolote jema.'),
(2020474,69,56,2,1,'Lakini wewe unapaswa kuhubiri mafundisho safi.'),
(2020475,69,56,2,2,'Waambie wazee kwamba wanapaswa kuwa na kiasi, wawe na busara na wataratibu; wanapaswa kuwa timamu katika imani yao, upendo na uvumilivu.'),
(2020476,69,56,2,3,'Hali kadhalika waambie wanawake wazee wawe na mwenendo wa uchaji wa Mungu; wasiwe wachongezi, au watumwa wa pombe. Wanapaswa kufundisha mambo mema,'),
(2020477,69,56,2,4,'ili wawazoeze kina mama vijana kuwapenda waume zao na watoto,'),
(2020478,69,56,2,5,'wawe na kiasi na safi, waangalie vizuri mambo ya nyumbani, na wawatii waume zao, ili ujumbe wa Mungu usije ukadharauliwa.'),
(2020479,69,56,2,6,'Kadhalika, wahimize vijana wawe na kiasi.'),
(2020480,69,56,2,7,'Katika mambo yote wewe mwenyewe unapaswa kuwa mfano wa matendo mema. Uwe mnyofu na uwe na uzito katika mafundisho yako.'),
(2020481,69,56,2,8,'Maneno yako yasiwe na hitilafu yoyote ili adui zako waaibike wasipopata chochote kibaya cha kusema juu yetu.'),
(2020482,69,56,2,9,'Watumwa wanapaswa kuwatii wakuu wao na kuwapendeza katika mambo yote. Wasibishane nao,'),
(2020483,69,56,2,10,'au kuiba vitu vyao. Badala yake wanapaswa kuonyesha kwamba wao ni wema na waaminifu daima, ili, kwa matendo yao yote, wayapatie sifa njema mafundisho juu ya Mungu, Mwokozi wetu.'),
(2020484,69,56,2,11,'Maana neema ya Mungu imedhihirishwa kwa ajili ya wokovu wa watu wote.'),
(2020485,69,56,2,12,'Neema hiyo yatufunza kuachana na uovu wote na tamaa za kidunia; tuwe na kiasi, tuishi maisha adili na ya kumcha Mungu katika ulimwengu huu wa sasa,'),
(2020486,69,56,2,13,'tukiwa tunangojea siku ile ya heri tunayoitumainia, wakati utakapotokea utukufu wa Mungu Mkuu na Mwokozi wetu Yesu Kristo.'),
(2020487,69,56,2,14,'Yeye alijitoa mwenyewe kwa ajili yetu ili atukomboe kutoka katika uovu wote na kutufanya watu safi walio wake yeye mwenyewe, watu walio na hamu ya kutenda mema.'),
(2020488,69,56,2,15,'Basi, fundisha mambo hayo na tumia mamlaka yako yote ukiwahimiza na kuwaonya wasikilizaji wako. Mtu yeyote na asikudharau.'),
(2020489,69,56,3,1,'Wakumbushe watu kuwastahi watawala na wenye mamlaka, kuwatii na kuwa tayari kwa kila namna kutenda mambo yote mema.'),
(2020490,69,56,3,2,'Waambie wasimtukane mtu yeyote; bali waishi kwa amani na masikizano, wawe daima wapole kwa kila mtu.'),
(2020491,69,56,3,3,'Maana, wakati mmoja sisi tulikuwa wapumbavu, wakaidi na wapotovu. Tulikuwa watumwa wa tamaa na anasa za kila aina. Tuliishi maisha ya uovu na wivu; watu walituchukia nasi tukawachukia.'),
(2020492,69,56,3,4,'Lakini wakati wema na upendo wa Mungu, Mwokozi wetu, ulipofunuliwa,'),
(2020493,69,56,3,5,'alituokoa. alituokoa si kwa sababu ya jambo lolote jema tulilotenda sisi, bali alituokoa kwa sababu ya huruma yake, kwa njia ya Roho Mtakatifu anayetujalia tuzaliwe upya na kuwa na maisha mapya kwa kutuosha kwa maji.'),
(2020494,69,56,3,6,'Mungu alitumiminia Roho Mtakatifu bila kipimo kwa njia ya Yesu Kristo, Mwokozi wetu,'),
(2020495,69,56,3,7,'ili kwa neema yake tupate kukubaliwa kuwa waadilifu na kuupokea uzima wa milele tunaoutumainia.'),
(2020496,69,56,3,8,'Jambo hili ni kweli. Ninakutaka uyatilie mkazo mambo haya, ili wale wanaomwamini Mungu, wawe na hamu ya kuutumia wakati wao katika kutenda mema, ambayo ni mambo mazuri na ya manufaa kwa watu.'),
(2020497,69,56,3,9,'Lakini jiepushe na ubishi wa kipumbavu, ugomvi na mabishano juu ya Sheria. Mambo hayo hayana faida yoyote na ni ya bure tu.'),
(2020498,69,56,3,10,'Mtu anayesababisha mafarakano mpe onyo la kwanza na la pili, kisha achana naye.'),
(2020499,69,56,3,11,'Wajua kwamba mtu wa namna hiyo amepotoka kabisa, na dhambi zake zathibitisha kwamba amekosea.'),
(2020500,69,56,3,12,'Baada ya kumtuma kwako Artema au Tukiko, fanya bidii kuja Nikopoli unione, maana nimeamua kukaa huko wakati wa majira ya baridi.'),
(2020501,69,56,3,13,'Jitahidi kumsaidia mwana sheria Zena na Apolo ili waweze kuanza ziara zao na uhakikishe kwamba wana kila kitu wanachohitaji.'),
(2020502,69,56,3,14,'Ni lazima watu wetu wajifunze kuutumia wakati wao katika kutenda mema ili wasaidie katika mahitaji ya kweli, na maisha yao yawe ya kufaa.'),
(2020503,69,56,3,15,'Watu wote walio pamoja nami wanakusalimu. Wasalimu rafiki zetu katika imani. Nawatakieni nyote neema ya Mungu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020504,69,57,1,1,'Mimi Paulo, mfungwa kwa ajili ya Kristo Yesu, na ndugu Timotheo, ninakuandikia wewe Filemoni mpendwa, mfanyakazi mwenzetu'),
(2020505,69,57,1,2,'na kanisa linalokutana nyumbani kwako, na wewe dada Afia, na askari mwenzetu Arkupo.'),
(2020506,69,57,1,3,'Tunawatakieni neema na amani kutoka kwa Mungu Baba yetu, na kwa Bwana yesu Kristo.'),
(2020507,69,57,1,4,'Kila wakati ninaposali nakukumbuka wewe Filemoni, na kumshukuru Mungu'),
(2020508,69,57,1,5,'maana nasikia habari za imani yako kwa Bwana wetu Yesu na upendo wako kwa watu wote wa Mungu.'),
(2020509,69,57,1,6,'Naomba ili imani hiyo unayoshiriki pamoja nasi ikuwezeshe kuwa na ujuzi mkamilifu zaidi wa baraka zote tunazopata katika kuungana kwetu na Kristo.'),
(2020510,69,57,1,7,'Ndugu, upendo wako yameniletea furaha kubwa na kunipa moyo sana! Nawe umeichangamsha mioyo ya watu wa Mungu.'),
(2020511,69,57,1,8,'Kwa sababu hiyo, ningeweza, kwa uhodari kabisa, nikiwa ndugu yako katika Kristo, kukuamuru ufanye unachopaswa kufanya.'),
(2020512,69,57,1,9,'Lakini kwa sababu ya upendo, ni afadhali zaidi nikuombe. Nafanya hivi ingawa mimi ni Paulo, balozi wa Kristo Yesu, na sasa pia mfungwa kwa ajili yake.'),
(2020513,69,57,1,10,'Basi, ninalo ombi moja kwako kuhusu mwanangu Onesimo, ambaye ni mwanangu katika Kristo kwani nimekuwa baba yake nikiwa kifungoni.'),
(2020514,69,57,1,11,'Ni Onesimo yuleyule ambaye wakati mmoja alikuwa hakufai kitu, lakini sasa ananifaa mimi na wewe pia.'),
(2020515,69,57,1,12,'Sasa namrudisha kwako, naye ni kama moyo wangu mimi mwenyewe.'),
(2020516,69,57,1,13,'Ningependa akae nami hapa anisaidie badala yako wakati niwapo kifungoni kwa sababu ya Habari Njema.'),
(2020517,69,57,1,14,'Lakini sitafanya chochote bila kibali chako. Sipendi kukulazimisha unisaidie, kwani wema wako unapaswa kutokana na hiari yako wewe mwenyewe na si kwa kulazimika.'),
(2020518,69,57,1,15,'Labda Onesimo aliondoka kwako kwa kitambo tu, kusudi uweze tena kuwa naye daima.'),
(2020519,69,57,1,16,'Na sasa yeye si mtumwa tu, ila ni bora zaidi ya mtumwa: yeye ni ndugu yetu mpenzi. Na wa maana sana kwangu mimi, na kwako atakuwa wa maana zaidi kama mtumwa na kama ndugu katika Bwana.'),
(2020520,69,57,1,17,'Basi, ikiwa wanitambua mimi kuwa mwenzako, mpokee tena kama vile ungenipokea mimi mwenyewe.'),
(2020521,69,57,1,18,'Kama alikuwa amekukosea kitu, au alikuwa na deni lako, basi, unidai mimi.'),
(2020522,69,57,1,19,'Naandika jambo hili kwa mkono wangu mwenyewe: yako.)'),
(2020523,69,57,1,20,'Haya, basi, ndugu yangu, nifanyie jambo hilo kwa ajili ya jina la Bwana; burudisha moyo wangu kama ndugu katika Kristo.'),
(2020524,69,57,1,21,'Naandika nikitumaini kwamba utanikubalia ombi langu; tena najua kwamba utafanya hata zaidi ya haya ninayokuomba.'),
(2020525,69,57,1,22,'Pamoja na hayo, nitayarishie chumba kwani natumaini kwamba kwa sala zenu, Mungu atanijalia niwatembeleeni.'),
(2020526,69,57,1,23,'Epafra, mfungwa mwenzangu kwa ajili ya Kristo Yesu, anakusalimu.'),
(2020527,69,57,1,24,'Nao akina Marko, Aristarko, Dema na Luka, wafanyakazi wenzangu, wanakusalimu.'),
(2020528,69,57,1,25,'Nawatakieni ninyi nyote neema ya Bwana wetu Yesu Kristo.'),
(2020529,69,58,1,1,'Hapo zamani, Mungu alisema na babu zetu mara nyingi kwa namna nyingi kwa njia ya manabii,'),
(2020530,69,58,1,2,'lakini siku hizi za mwisho, amesema nasi kwa njia ya Mwanae. Yeye ndiye ambaye kwa njia yake Mungu aliumba ulimwengu na akamteua avimiliki vitu vyote.'),
(2020531,69,58,1,3,'Yeye ni mng`ao wa utukufu wa Mungu, na mfano kamili wa hali ya Mungu mwenyewe, akiutegemeza ulimwengu kwa neno lake lenye nguvu. Baada ya kuwapatia binadamu msamaha wa dhambi zao, aliketi huko juu mbinguni, upande wa kulia wa Mungu Mkuu.'),
(2020532,69,58,1,4,'Mwana ni mkuu zaidi kuliko malaika, kama vile jina alilopewa na Mungu ni kuu zaidi kuliko jina lao.'),
(2020533,69,58,1,5,'Maana Mungu hakumwambia kamwe hata mmoja wa malaika wake: "Wewe ni Mwanangu; Mimi leo nimekuwa Baba yako." Wala hakusema juu ya malaika yeyote: "Mimi nitakuwa Baba yake, naye atakuwa Mwanangu."'),
(2020534,69,58,1,6,'Lakini Mungu alipokuwa anamtuma Mwanae mzaliwa wa kwanza ulimwenguni, alisema: "Malaika wote wa Mungu wanapaswa kumwabudu."'),
(2020535,69,58,1,7,'Lakini kuhusu malaika, Mungu alisema: "Mungu awafanya malaika wake kuwa pepo, na watumishi wake kuwa ndimi za moto."'),
(2020536,69,58,1,8,'Lakini kumhusu Mwana, Mungu alisema: "Utawala wako ee Mungu, wadumu milele na milele! Wewe wawatawala watu wako kwa haki.'),
(2020537,69,58,1,9,'Wewe wapenda uadilifu na kuchukia uovu. Ndiyo maana Mungu, Mungu wako amekuweka wakfu na kukumiminia furaha kubwa zaidi kuliko wenzako."'),
(2020538,69,58,1,10,'Pia alisema: "Bwana, wewe uliumba dunia hapo mwanzo, mbingu ni kazi ya mikono yako.'),
(2020539,69,58,1,11,'Hizo zitatoweka, lakini wewe wabaki daima, zote zitachakaa kama vazi.'),
(2020540,69,58,1,12,'Utazikunjakunja kama koti, nazo zitabadilishwa kama vazi. Lakini wewe ni yuleyule daima, na maisha yako hayatakoma."'),
(2020541,69,58,1,13,'Mungu hakumwambia kamwe hata mmoja wa malaika wake: "Keti upande wangu wa kulia, mpaka niwaweke adui zako chini ya miguu yako."'),
(2020542,69,58,1,14,'Malaika ni roho tu wanaomtumikia Mungu, na Mungu huwatuma wawasaidie wale watakaopokea wokovu.'),
(2020543,69,58,2,1,'Kwa sababu hiyo tunapaswa kuzingatia kwa makini zaidi yote tuliyosikia, ili tusije tukapotoshwa.'),
(2020544,69,58,2,2,'Ujumbe ule waliopewa wazee wetu na malaika ulionyeshwa kuwa kweli, hata mtu yeyote ambaye hakuufuata au hakuutii aliadhibiwa kama alivyostahili.'),
(2020545,69,58,2,3,'Basi, sisi tutaokokaje kama hatuujali wokovu mkuu kama huu? Kwanza Bwana mwenyewe aliutangaza wokovu huu, na wale waliomsikia walituthibitishia kwamba ni kweli.'),
(2020546,69,58,2,4,'Mungu pia aliongeza hapo ushahidi wake kwa kufanya kila namna ya miujiza na maajabu, na kwa kuwagawia watu vipaji vya Roho Mtakatifu kadiri ya mapenzi yake.'),
(2020547,69,58,2,5,'Mungu hakuwaweka malaika wautawale ulimwengu ujao, yaani ulimwengu ule tunaoongea habari zake.'),
(2020548,69,58,2,6,'Tena yasemwa mahali fulani katika Maandiko: "Mtu ni nini ee Mungu, hata umfikirie; mwanaadamu ni nini hata umjali?'),
(2020549,69,58,2,7,'Ulimfanya kwa kitambo kidogo kuwa chini zaidi kuliko malaika; ukamvika taji ya utukufu na heshima,'),
(2020550,69,58,2,8,'ukaweka kila kitu chini ya miguu yake, avitawale." Yasemwa kwamba Mungu alimweka mtu kuwa mtawala wa vitu vyote yaani bila kuacha hata kimoja. Hata hivyo, hatuoni bado mtu akivitawala vitu vyote sasa.'),
(2020551,69,58,2,9,'Lakini twamwona Yesu ambaye alifanywa kwa kitambo kidogo kuwa chini zaidi kuliko malaika, ili kwa neema ya Mungu afe kwa ajili ya watu wote. Sasa tunamwona ametawazwa kwa utukufu na heshima kwa sababu ya kifo alichoteseka.'),
(2020552,69,58,2,10,'Ilikuwa haki tupu kwamba Mungu, ambaye huumba na kutegemeza vitu vyote, alimfanya Yesu kuwa mkamilifu kabisa kwa njia ya mateso, ili awalete watoto wengi waushiriki utukufu wake. Maana Yesu ndiye anayewaongoza kwenye wokovu.'),
(2020553,69,58,2,11,'Yeye anawatakasa watu dhambi zao, naye pamoja na wale waliotakaswa, wote wanaye Baba mmoja. Ndiyo maana Yesu haoni aibu kuwaita hao ndugu zake;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020554,69,58,2,12,'kama asemavyo: "Ee Mungu, nitawatangazia ndugu zangu matendo yako. Nitakusifu katika kusanyiko lao."'),
(2020555,69,58,2,13,'Tena asema: "Nitamwekea Mungu tumaini langu." Na tena: "Mimi niko hapa pamoja na watoto alionipa Mungu."'),
(2020556,69,58,2,14,'Basi, kwa vile watoto hao, kama awaitavyo, ni watu wenye mwili na damu, Yesu mwenyewe akawa kama wao na kushiriki ubinadamu wao. Alifanya hivyo ili kwa njia ya kifo chake amwangamize Ibilisi, ambaye ana mamlaka juu ya kifo,'),
(2020557,69,58,2,15,'na hivyo awaokoe wale waliokuwa watumwa maisha yao yote kwa sababu ya hofu yao ya kifo.'),
(2020558,69,58,2,16,'Maana ni wazi kwamba yeye hakuja kwa ajili ya kuwasaidia malaika, bali kama yasemavyo Maandiko; "Anawasaidia wazawa wa Abrahamu."'),
(2020559,69,58,2,17,'Ndiyo maana ilimbidi awe kama ndugu zake kwa kila namna, ili awe Kuhani Mkuu wao aliye mwaminifu na mwenye huruma katika kumtumikia Mungu, ili dhambi za watu ziondolewe.'),
(2020560,69,58,2,18,'Na, anaweza sasa kuwasaidia wale wanaojaribiwa na kuteswa.'),
(2020561,69,58,3,1,'Ndugu zangu watu wa Mungu ambao mmeitwa na Mungu, fikirini juu ya Yesu ambaye Mungu alimtuma awe Kuhani Mkuu wa imani tunayoiungama.'),
(2020562,69,58,3,2,'Yeye alikuwa mwaminifu kwa Mungu aliyemteua kufanya kazi yake kama vile Mose alivyokuwa mwaminifu katika nyumba yote ya Mungu.'),
(2020563,69,58,3,3,'Mjenzi wa nyumba hupata heshima zaidi kuliko hiyo nyumba yenyewe. Hali kadhalika naye Yesu anastahili heshima kubwa zaidi kuliko Mose.'),
(2020564,69,58,3,4,'Kila nyumba hujengwa na mjenzi fulani--na Mungu ndiye mjenzi wa vitu vyote.'),
(2020565,69,58,3,5,'Mose alikuwa mwaminifu katika nyumba yote ya Bwana kama mtumishi, na alinena juu ya mambo ambayo Mungu atayasema hapo baadaye.'),
(2020566,69,58,3,6,'Lakini Kristo ni mwaminifu kama Mwana mwenye mamlaka juu ya nyumba ya Mungu. Sisi ni nyumba yake kama tukizingatia uhodari wetu na uthabiti wetu katika kile tunachotumainia.'),
(2020567,69,58,3,7,'Kwa hiyo, basi, kama asemavyo Roho Mtakatifu: "Kama mkisikia sauti ya Mungu leo,'),
(2020568,69,58,3,8,'msiifanye mioyo yenu kuwa migumu kama wazee wenu walivyokuwa wakati walipomwasi Mungu; kama walivyokuwa siku ile kule jangwani,'),
(2020569,69,58,3,9,'Huko wazee wenu walinijaribu na kunichunguza, asema Bwana, ingawa walikuwa wameyaona matendo yangu kwa miaka arobaini.'),
(2020570,69,58,3,10,'Kwa sababu hiyo niliwakasirikia watu hao nikasema, `Fikira za watu hawa zimepotoka, hawajapata kamwe kuzijua njia zangu.`'),
(2020571,69,58,3,11,'Basi, nilikasirika, nikaapa: `Hawataingia huko ambako ningewapa pumziko."`'),
(2020572,69,58,3,12,'Basi ndugu, jihadharini asije akawako yeyote miongoni mwenu aliye na moyo mbaya hivyo na asiyeamini hata kujitenga na Mungu aliye hai.'),
(2020573,69,58,3,13,'Maadamu hiyo "Leo" inayosemwa katika Maandiko bado inatuhusu sisi, mnapaswa kusaidiana daima, ili mtu yeyote miongoni mwenu asidanganywe na dhambi na kuwa mkaidi.'),
(2020574,69,58,3,14,'Maana sisi tunashirikiana na Kristo ikiwa tutazingatia kwa uthabiti tumaini tulilokuwa nalo mwanzoni.'),
(2020575,69,58,3,15,'Maandiko yasema hivi: "Kama mkisikia sauti ya Mungu leo, msiifanye mioyo yenu kuwa migumu kama wazee wenu walivyokuwa wakati walipomwasi Mungu."'),
(2020576,69,58,3,16,'Ni akina nani basi, waliosikia sauti ya Mungu wakamwasi? Ni wale wote walioongozwa na Mose kutoka Misri.'),
(2020577,69,58,3,17,'Mungu aliwakasirikia akina nani kwa miaka arobaini? Aliwakasirikia wale waliotenda dhambi, maiti zao zikatapakaa kule jangwani.'),
(2020578,69,58,3,18,'Mungu alipoapa: "Hawataingia huko ambako ningewapa pumziko," alikuwa anawasema akina nani? Alikuwa anasema juu ya hao walioasi.'),
(2020579,69,58,3,19,'Basi, twaona kwamba hawakuingia huko kwa sababu hawakuamini.'),
(2020580,69,58,4,1,'Mungu alituahidia kwamba tutaweza kupata pumziko hilo alilosema. Basi, na tuogope ili yeyote kati yenu asije akashindwa kupata pumziko hilo.'),
(2020581,69,58,4,2,'Maana Habari Njema imehubiriwa kwetu kama vile ilivyohubiriwa kwa hao watu wa kale. Lakini ujumbe huo haukuwafaa chochote, maana waliusikia lakini hawakuupokea kwa imani.'),
(2020582,69,58,4,3,'Basi, sisi tunaoamini tunapata pumziko hilo aliloahidi Mungu. Kama alivyosema: "Nilikasirika, nikaapa: `Hawataingia huko ambako ningewapa pumziko."` Mungu alisema hayo ingawa kazi yake ilikuwa imekwisha malizika tangu alipoumba ulimwengu.'),
(2020583,69,58,4,4,'Maana Maandiko yasema mahali fulani kuhusu siku ya saba: "Mungu alipumzika siku ya saba, akaacha kazi zake zote."'),
(2020584,69,58,4,5,'Tena jambo hili lasemwa pia: "Hawataingia huko ambako ningewapa pumziko."'),
(2020585,69,58,4,6,'Wale waliotangulia kuhubiriwa Habari Njema hawakupata pumziko hilo kwa sababu hawakuamini. Wapo, basi, wengine ambao wangejaliwa kulipata.'),
(2020586,69,58,4,7,'Jambo hili ni wazi, kwani Mungu aliweka siku nyingine ambayo inaitwa "Leo". Miaka mingi baadaye Mungu alisema juu ya hiyo siku kwa maneno ya Daudi katika Maandiko yaliyokwisha tajwa: "Kama mkisikia sauti ya Mungu leo, msiifanye mioyo yenu kuwa migumu."'),
(2020587,69,58,4,8,'Kama Yoshua angaliwapa watu hao hilo pumziko, Mungu hangalisema baadaye juu ya siku nyingine.'),
(2020588,69,58,4,9,'Kwa hiyo, basi, bado lipo pumziko kwa watu wa Mungu kama kule kupumzika kwake Mungu siku ya saba.'),
(2020589,69,58,4,10,'Maana, kila anayepata pumziko aliloahidi Mungu atapumzika baada ya kazi yake kama vile pia Mungu alivyopumzika baada ya yake.'),
(2020590,69,58,4,11,'Basi, tujitahidi kupata pumziko hilo, ili asiwepo yeyote miongoni mwenu atakayeshindwa, kama walivyofanya wao kwa sababu ya ukosefu wao wa imani.'),
(2020591,69,58,4,12,'Neno la Mungu ni hai na lina nguvu; ni kali zaidi kuliko upanga wenye makali kuwili. Hukata kabisa mpaka mahali ambapo moyo na roho hukutana, mpaka pale vikutanapo viungo vya mwili na mafuta. Neno hilo huchambua nia na fikira za mioyo ya watu.'),
(2020592,69,58,4,13,'Hakuna kiumbe chochote kilichofichika mbele ya Mungu; kila kitu kimefunuliwa wazi mbele ya macho yake. Kwake, sisi sote tutapaswa kutoa hoja ya matendo yetu.'),
(2020593,69,58,4,14,'Basi, tunapaswa kuzingatia kwa uthabiti imani tunayoiungama. Maana tunaye Kuhani Mkuu aliyeingia mpaka kwa Mungu mwenyewe--Yesu, Mwana wa Mungu.'),
(2020594,69,58,4,15,'Huyu Kuhani Mkuu wetu si mmoja ambaye hawezi kutuunga mkono katika unyonge wetu, ila ni Kuhani Mkuu ambaye alijaribiwa kama sisi kwa kila namna lakini hakutenda dhambi.'),
(2020595,69,58,4,16,'Basi, na tukikaribie bila hofu kiti cha enzi cha Mungu, palipo na neema, ili tukajipatie huruma na neema ya kutusaidia wakati wa lazima.'),
(2020596,69,58,5,1,'Kila kuhani mkuu huchaguliwa kutoka miongoni mwa watu kwa ajili ya kumtumikia Mungu kwa niaba yao, kutolea zawadi na tambiko kwa ajili ya dhambi zao.'),
(2020597,69,58,5,2,'Maadamu yeye mwenyewe yu dhaifu anaweza kuwaonea huruma wale wasiojua kitu na wanaofanya makosa.'),
(2020598,69,58,5,3,'Na kwa vile yeye mwenyewe ni dhaifu, anapaswa kutolea dhabihu si tu kwa ajili ya watu, bali pia kwa ajili ya dhambi zake.'),
(2020599,69,58,5,4,'Hakuna mtu awezaye kujitwalia mwenyewe heshima ya kuwa kuhani mkuu. Kila mmoja huteuliwa na Mungu kuwa kuhani mkuu kama alivyokuwa Aroni.'),
(2020600,69,58,5,5,'Hali kadhalika naye Kristo hakujitwalia mwenyewe heshima ya kuwa kuhani mkuu, bali Mungu alimwambia: "Wewe ni Mwanangu; mimi leo nimekuwa baba yako."'),
(2020601,69,58,5,6,'Alisema pia mahali pengine: "Wewe ni kuhani milele, kufuatana na utaratibu wa ukuhani wa Melkisedeki."'),
(2020602,69,58,5,7,'Yesu alipokuwa anaishi hapa duniani, kwa kilio kikuu na machozi, alisali na kumwomba Mungu ambaye alikuwa na uwezo wa kumwokoa kutoka kifo; naye alisikilizwa kwa sababu ya kumcha Mungu.'),
(2020603,69,58,5,8,'Lakini, ingawa alikuwa Mwana wa Mungu, alijifunza kutii kwa njia ya mateso.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020604,69,58,5,9,'Na alipofanywa mkamilifu, akawa chanzo cha wokovu wa milele kwa wale wote wanaomtii,'),
(2020605,69,58,5,10,'naye Mungu akamteua kuwa kuhani mkuu kufuatana na utaratibu wa ukuhani wa Melkisedeki.'),
(2020606,69,58,5,11,'Tunayo Mengi ya kusema juu ya jambo hili, lakini ni vigumu kuwaelezeni, kwa sababu ninyi si wepesi wa kuelewa.'),
(2020607,69,58,5,12,'Sasa mngalipaswa kuwa tayari walimu, lakini mnahitaji bado mtu wa kuwafundisheni mafundisho ya mwanzo ya ujumbe wa Mungu. Badala ya kula chakula kigumu, mnapaswa bado kunywa maziwa.'),
(2020608,69,58,5,13,'Kila anayepaswa kunywa maziwa huyo ni mtoto bado, hajui uadilifu ni nini.'),
(2020609,69,58,5,14,'Lakini chakula kigumu ni kwa ajili ya watu waliokomaa, ambao wanaweza kubainisha mema na mabaya.'),
(2020610,69,58,6,1,'Basi, tusonge mbele kwa yale yaliyokomaa na kuyaacha nyuma yale mafundisho ya mwanzo ya Kikristo. Hatuhitaji kuweka msingi tena kwa kurudia yale mafundisho ya mwanzo kama vile kuachana na matendo ya kifo, kumwamini Mungu;'),
(2020611,69,58,6,2,'mafundisho juu ya ubatizo na kuwekewa mikono; ufufuo wa wafu na hukumu ya milele.'),
(2020612,69,58,6,3,'tusonge mbele! Hayo tutayafanya, Mungu akitujalia.'),
(2020613,69,58,6,4,'Maana watu wanaoiasi imani yao inawezekanaje kuwarudisha watubu tena? Watu hao walikwisha kuwa katika mwanga wa Mungu, walikwisha onja zawadi ya mbinguni na kushirikishwa Roho Mtakatifu;'),
(2020614,69,58,6,5,'walikwisha onja wema wa neno la Mungu na nguvu za ulimwengu ujao,'),
(2020615,69,58,6,6,'kisha wakaiasi imani yao! Haiwezekani kuwarudisha watubu tena, kwa sababu wanamsulubisha tena Mwana wa Mungu na kumwaibisha hadharani.'),
(2020616,69,58,6,7,'Mungu huibariki ardhi ambayo huipokea mvua inayoinyeshea mara kwa mara, na kuotesha mimea ya faida kwa mkulima.'),
(2020617,69,58,6,8,'Lakini kama ardhi hiyo ikiota miti ya miiba na magugu, haina faida; karibu italaaniwa na Mungu na mwisho wake ni kuchomwa moto.'),
(2020618,69,58,6,9,'Lakini, ingawa twasema namna hii, wapenzi wetu, tunalo tumaini kubwa juu ya hali yenu. Tunajua kwamba mmepokea baraka zile bora za wokovu wenu.'),
(2020619,69,58,6,10,'Mungu hakosi haki; yeye hataisahau kazi mliyoifanya au upendo mlioonyesha kwa ajili ya jina lake katika huduma mliyowapa na mnayowapa sasa watu wake.'),
(2020620,69,58,6,11,'Hamu yetu ni kwamba kila mmoja wenu aonyeshe bidii hiyohiyo mpaka mwisho, ili yale mnayotumainia yapate kutimia.'),
(2020621,69,58,6,12,'Msiwe wavivu, bali muwe kama wale wanaoamini na wenye uvumilivu na hivyo wanapokea yake aliyoahidi Mungu.'),
(2020622,69,58,6,13,'Mungu alipompa Abrahamu ahadi, aliapa kwa jina lake mwenyewe, maana hakuna aliye mkuu kuliko Mungu ambaye kwa huyo angeweza kuapa.'),
(2020623,69,58,6,14,'Mungu alisema: "Hakika nitakubariki na nitakupa wazawa wengi."'),
(2020624,69,58,6,15,'Abrahamu alisubiri kwa uvumilivu na hivyo alipokea kile alichoahidiwa na Mungu.'),
(2020625,69,58,6,16,'Watu wanapoapa, huapa kwa mmoja aliye mkuu zaidi kuliko wao, na kiapo hicho husuluhisha ubishi wote.'),
(2020626,69,58,6,17,'Naye Mungu aliimarisha ahadi yake kwa kiapo; na kwa namna hiyo akawaonyesha wazi wale aliowaahidia kwamba hatabadili nia yake.'),
(2020627,69,58,6,18,'Basi, kuna vitu hivi viwili: ahadi na kiapo, ambavyo haviwezi kubadilika na wala juu ya hivyo Mungu hawezi kusema uongo. Kwa hiyo sisi tuliokimbilia usalama kwake, tunapewa moyo wa kushikilia imara tumaini lililowekwa mbele yetu.'),
(2020628,69,58,6,19,'Tunalo tumaini hilo kama nanga ya maisha yetu. Tumaini hilo ni imara na thabiti, nalo lapenya lile pazia la hekalu la mbinguni mpaka patakatifu ndani.'),
(2020629,69,58,6,20,'Yesu ametangulia kuingia humo kwa niaba yetu, na amekuwa kuhani mkuu milele, kufuatana na utaratibu wa ukuhani wa Melkisedeki.'),
(2020630,69,58,7,1,'Melkisedeki alikuwa mfalme wa Salemu, na kuhani wa Mungu Mkuu. Abrahamu alipokuwa anarudi kutoka vitani ambako aliwaua wafalme, Melkisedeki alikutana naye akambariki,'),
(2020631,69,58,7,2,'naye Abrahamu akampa sehemu ya kumi ya vitu vyote alivyokuwa navyo. (Maana ya kwanza ya jina hili Melkisedeki ni "Mfalme wa Uadilifu"; na, kwa vile yeye alikuwa mfalme wa Salemu, jina lake pia lina maana ya "Mfalme wa Amani.")'),
(2020632,69,58,7,3,'Baba yake na mama yake hawatajwi, wala ukoo wake hautajwi; haisemwi alizaliwa lini au alikufa lini. Anafanana na Mwana wa Mungu, na anaendelea kuwa kuhani daima.'),
(2020633,69,58,7,4,'Basi, mwaona jinsi mtu huyu alivyokuwa maarufu. Baba Abrahamu alimpa sehemu moja ya kumi ya vitu vyote alivyoteka vitani.'),
(2020634,69,58,7,5,'Tunajua vilevile kwamba kufuatana na Sheria, wana wa Lawi ambao ni makuhani, wanayo haki ya kuchukua sehemu ya kumi kutoka kwa watu, yaani ndugu zao, ingawaje nao ni watoto wa Abrahamu.'),
(2020635,69,58,7,6,'Lakini huyo Melkisedeki hakuwa wa ukoo wa Lawi, hata hivyo alipokea sehemu ya kumi kutoka kwa Abrahamu; tena akambariki yeye ambaye alikuwa amepewa ahadi ya Mungu.'),
(2020636,69,58,7,7,'Hakuna mashaka hata kidogo kwamba anayebariki ni mkuu zaidi kuliko yule anayebarikiwa.'),
(2020637,69,58,7,8,'Tena, hao makuhani wanaopokea sehemu ya kumi, ni watu ambao hufa; lakini hapa anayepokea sehemu ya kumi, yaani Melkisedeki, anasemekana kwamba hafi.'),
(2020638,69,58,7,9,'Twaweza, basi, kusema kwamba Abrahamu alipotoa sehemu moja ya kumi, Lawi (ambaye watoto wake hupokea sehemu moja ya kumi) alitoa sehemu moja ya kumi pia.'),
(2020639,69,58,7,10,'Maana Lawi hakuwa amezaliwa bado, bali ni kama alikuwa katika mwili wa baba yake, Abrahamu, wakati Melkisedeki alipokutana naye.'),
(2020640,69,58,7,11,'Kutokana na ukuhani wa Walawi, watu wa Israeli walipewa Sheria. Sasa, kama huduma ya Walawi ingalikuwa kamilifu hapangekuwa tena na haja ya kutokea ukuhani mwingine tofauti, ukuhani ambao umefuata utaratibu wa ukuhani wa Melkisedeki, na si ule wa Aroni.'),
(2020641,69,58,7,12,'Maana ukuhani ukibadilika ni lazima Sheria nayo ibadilike.'),
(2020642,69,58,7,13,'Naye Bwana wetu ambaye mambo hayo yote yanasemwa juu yake, alikuwa wa kabila lingine, na wala hakuna hata mmoja wa kabila lake aliyepata kutumikia madhabahuni akiwa kuhani.'),
(2020643,69,58,7,14,'Inafahamika wazi kwamba yeye alizaliwa katika kabila la Yuda ambalo Mose hakulitaja alipokuwa anasema juu ya makuhani.'),
(2020644,69,58,7,15,'Tena jambo hili ni dhahiri zaidi: kuhani mwingine anayefanana na Melkisedeki amekwisha tokea.'),
(2020645,69,58,7,16,'Yeye hakufanywa kuwa kuhani kwa sheria na maagizo ya kibinadamu, bali kwa nguvu ya uhai ambao hauna mwisho.'),
(2020646,69,58,7,17,'Maana Maandiko yasema: "Wewe ni kuhani milele, kufuatana na utaratibu wa ukuhani wa Melkisedeki."'),
(2020647,69,58,7,18,'Basi, ile amri ya zamani ilifutwa kwa sababu ilikuwa hafifu na isiyofaa kitu.'),
(2020648,69,58,7,19,'Maana Sheria ya Mose haikuweza kukamilisha jambo lolote. Lakini sasa, mahali pake pamewekwa tumaini lililo bora zaidi ambalo kwalo tunaweza kumkaribia Mungu.'),
(2020649,69,58,7,20,'Zaidi ya hayo hapa pana kiapo cha Mungu. Wakati wale wengine walipofanywa makuhani hapakuwako kiapo.'),
(2020650,69,58,7,21,'Lakini Yesu alifanywa kuhani kwa kiapo wakati Mungu alipomwambia: "Bwana ameapa, wala hataigeuza nia yake: `Wewe ni kuhani milele."`'),
(2020651,69,58,7,22,'Basi, kutokana na tofauti hii, Yesu amekuwa mdhamini wa agano lililo bora zaidi.'),
(2020652,69,58,7,23,'Kuna tofauti nyingine pia: hao makuhani wengine walikuwa wengi kwa sababu walikufa na hawakuweza kuendelea na kazi yao.'),
(2020653,69,58,7,24,'Lakini Yesu si kama wao, yeye anaishi milele; ukuhani wake hauondoki kwake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020654,69,58,7,25,'Hivyo, yeye anaweza daima kuwaokoa kabisa wote wanaomwendea Mungu kwa njia yake, maana yeye anaishi milele kuwaombea kwa Mungu.'),
(2020655,69,58,7,26,'Basi, Yesu ndiye Kuhani Mkuu ambaye anatufaa sana katika mahitaji yetu. Yeye ni mtakatifu, hana hatia wala dhambi ndani yake; hayumo katika kundi la wenye dhambi na ameinuliwa mpaka juu mbinguni.'),
(2020656,69,58,7,27,'Yeye si kama wale makuhani wakuu wengine; hana haja ya kutoa dhabihu kila siku, kwanza kwa ajili ya dhambi zake mwenyewe, kisha kwa ajili ya dhambi za watu. Yeye alifanya hivyo mara moja tu wakati alipojitoa yeye mwenyewe, na hiyo yatosha kwa nyakati zote.'),
(2020657,69,58,7,28,'Sheria ya Mose huwateua watu waliokuwa dhaifu kuwa makuhani wakuu; lakini ahadi ya Mungu aliyoifanya kwa kiapo na ambayo imefika baada ya sheria imemteua Mwana ambaye amefanywa mkamilifu milele.'),
(2020658,69,58,8,1,'Basi, jambo muhimu katika hayo tunayosema ni hili: sisi tunaye Kuhani Mkuu wa namna hiyo, ambaye anaketi upande wa kulia wa kiti cha enzi cha Mwenyezi Mungu mbinguni.'),
(2020659,69,58,8,2,'Yeye hutoa huduma ya Kuhani Mkuu katika Mahali Patakatifu sana, yaani ndani ya ile hema ya kweli iliyojengwa na Bwana, siyo na binadamu. ic'),
(2020660,69,58,8,3,'Kila Kuhani Mkuu ameteuliwa kumtolea Mungu vipawa na dhabihu, na hivyo Kuhani Mkuu wetu lazima pia awe na kitu cha kutolea.'),
(2020661,69,58,8,4,'Kama yeye angekuwa wa hapa duninani, asingekuwa kamwe kuhani, kwani wako makuhani wengine wanaotoa sadaka kufuatana na Sheria.'),
(2020662,69,58,8,5,'Huduma zao za kikuhani ni mfano tu na kivuli cha yale yaliyoko mbinguni. Ndivyo pia ilivyokuwa kwa Mose. Wakati alipokuwa karibu kuitengeneza ile hema, Mungu alimwambia: "Tengeneza kila kitu kufuatana na ule mfano ulioonyeshwa kule mlimani."'),
(2020663,69,58,8,6,'Lakini sasa Yesu amepewa huduma ya kikuhani iliyo bora zaidi kuliko yao, kama vile agano alilothibitisha kati ya watu na Mungu ni bora zaidi, kwani lina msingi wake katika ahadi za mambo yaliyo bora zaidi.'),
(2020664,69,58,8,7,'Maana kama lile agano la kwanza halingalikuwa na dosari, hakungalikuwa na haja ya agano la pili.'),
(2020665,69,58,8,8,'Lakini Mungu aliwalaumu watu wake aliposema: "Siku zinakuja, asema Bwana, ambapo nitafanya agano jipya na watu wa Israeli na kabila la Yuda.'),
(2020666,69,58,8,9,'Agano hili halitakuwa kama lile nililofanya na babu zao siku ile nilipowaongoza kwa mkono kutoka nchi ya Misri. Hawakuwa waaminifu kwa agano langu; na hivyo mimi sikuwajali, asema Bwana.'),
(2020667,69,58,8,10,'Na hili ndilo agano nitakalofanya na watu wa Israeli siku zijazo, asema Bwana: Nitaweka sheria zangu akilini mwao, na kuziandika mioyoni mwao. Mimi nitakuwa Mungu wao, nao watakuwa watu wangu.'),
(2020668,69,58,8,11,'Hakuna mtu atakayemfundisha mwananchi mwenzake, wala atakayemwambia ndugu yake: `Mjue Bwana.` Maana watu wote, wadogo na wakubwa, watanijua mimi.'),
(2020669,69,58,8,12,'Nitawasamehe makosa yao, wala sitakumbuka tena dhambi zao."'),
(2020670,69,58,8,13,'Kwa kusema juu ya agano jipya, Mungu alilichakaza lile la kwanza; na chochote kinachochakaa na kuwa kikuukuu kitatoweka karibuni.'),
(2020671,69,58,9,1,'Agano la kwanza lilikuwa na taratibu zake za ibada na pia mahali patakatifu pa ibada palipojengwa na watu.'),
(2020672,69,58,9,2,'Palitengenezwa hema ambayo sehemu yake ya nje iliitwa Mahali Patakatifu. Humo mlikuwa na kinara cha taa, meza na mikate iliyotolewa kwa Mungu.'),
(2020673,69,58,9,3,'Nyuma ya pazia la pili, kulikuwa na hema iliyoitwa Mahali Patakatifu Kupita Pote.'),
(2020674,69,58,9,4,'Humo mlikuwa na madhabahu ya dhahabu kwa ajili ya kufukizia ubani, na Sanduku la Agano, ambalo lilikuwa limepakwa dhahabu pande zote, na ndani yake mlikuwa na chungu cha dhahabu kilichokuwa na mana; fimbo ya Aroni iliyokuwa imechanua majani, na vile vibao viwili vilivyoandikwa agano.'),
(2020675,69,58,9,5,'Juu ya hilo Sanduku kulikuwa na viumbe vilivyodhihirisha kuweko kwa Mungu, na mabawa yao yalitanda juu ya mahali ambapo dhambi huondolewa. Lakini sasa, hatuwezi kusema kinaganaga juu ya mambo hayo.'),
(2020676,69,58,9,6,'Mipango hiyo ilitekelezwa kisha ikawa desturi kwa makuhani kuingia kila siku katika hema ya nje kutoa huduma zao.'),
(2020677,69,58,9,7,'Lakini kuhani Mkuu peke yake ndiye anayeingia katika lile hema la pili; naye hufanya hivyo mara moja tu kwa mwaka. Anapoingia ndani huwa amechukua damu ambayo anamtolea Mungu kwa ajili yake mwenyewe na kwa ajili ya dhambi ambazo watu wamezitenda bila wao wenyewe kujua.'),
(2020678,69,58,9,8,'Kutokana na taratibu hizo Roho Mtakatifu anafundisha wazi kwamba wakati ile hema ya nje ingali ipo imesimama, njia ya kuingia Mahali Patakatifu haijafunguliwa.'),
(2020679,69,58,9,9,'Jambo hili ni mfano wa nyakati za sasa. Linaonyesha kwamba zawadi na dhabihu zinazotolewa kwa Mungu haziwezi kuifanya mioyo ya wale wanaoabudu kuwa mikamilifu,'),
(2020680,69,58,9,10,'kwani haya yote yanahusika na vyakula, vinywaji na taratibu mbalimbali za kutawadha. Yote hayo ni maagizo ya njenje tu; na nguvu yake hukoma wakati Mungu atakaporekebisha vitu vyote.'),
(2020681,69,58,9,11,'Lakini Kristo amekwisha fika, akiwa Kuhani Mkuu wa mambo yaliyo mema, ambayo sasa yamekwisha fika. Yeye anatoa huduma zake katika hema iliyo bora na kamilifu zaidi, isiyofanywa kwa mikono ya watu, yaani isiyo ya ulimwengu huu ulioumbwa.'),
(2020682,69,58,9,12,'Yeye aliingia Mahali Patakatifu mara moja tu, tena hakuwa amechukua damu ya mbuzi wala ng`ombe, bali aliingia kwa damu yake yeye mwenyewe, akatupatia ukombozi wa milele.'),
(2020683,69,58,9,13,'Watu waliokuwa najisi kidini waliweza kutakasika na kuwa safi waliponyunyiziwa damu ya mbuzi na ya ng`ombe pamoja na majivu ya ndama.'),
(2020684,69,58,9,14,'Lakini, kwa damu ya Kristo, mambo makuu zaidi hufanyika! Kwa nguvu za Roho wa milele, Kristo alijitolea mwenyewe dhabihu kamilifu kwa Mungu. Damu yake itatutakasa dhamiri zetu kutokana na matendo yaletayo kifo, ili tupate kumtumikia Mungu aliye hai.'),
(2020685,69,58,9,15,'Kwa hiyo, Kristo ndiye aliyeratibisha agano jipya ili wale walioitwa na Mungu wazipokee baraka za milele walizoahidiwa. Watazipata, kwani kifo kimetokea ambacho huwakomboa watu kutoka yale makosa waliyofanya wakati wa lile agano la kale.'),
(2020686,69,58,9,16,'Kwa kawaida wosia hutambuliwa tu kama kifo cha yule aliyeufanya huo wosia kimethibitishwa.'),
(2020687,69,58,9,17,'Wosia hauwezi kutekelezwa mpaka kumetokea kifo, kwani wosia hauna maana ikiwa mwenye kuufanya bado anaishi.'),
(2020688,69,58,9,18,'Ndiyo maana hata lile agano la kwanza halikuwekwa bila damu kumwagwa.'),
(2020689,69,58,9,19,'Kwanza Mose aliwatangazia watu wote amri zote kama ilivyokuwa katika Sheria; kisha akachukua damu ya ndama pamoja na maji, na kwa kutumia majani ya mti uitwao husopo na pamba nyekundu, akakinyunyizia kile kitabu cha Sheria na hao watu wote.'),
(2020690,69,58,9,20,'Mose alisema: "Hii ni damu inayothibitisha agano mliloamriwa na Mungu mlitii."'),
(2020691,69,58,9,21,'Vilevile Mose aliinyunyizia damu ile hema na vyombo vya ibada.'),
(2020692,69,58,9,22,'Naam, kadiri ya Sheria karibu kila kitu chaweza kutakaswa kwa damu, na dhambi nazo zaondolewa tu ikiwa damu imemwagwa.'),
(2020693,69,58,9,23,'Vitu hivi ambavyo ni mfano tu wa mambo halisi ya mbinguni, vililazimika kutakaswa kwa namna hiyo. Lakini vitu vya mbinguni huhitaji dhabihu iliyo bora zaidi.'),
(2020694,69,58,9,24,'Maana Kristo hakuingia Mahali Patakatifu palipojengwa kwa mikono ya watu, ambapo ni mfano tu wa kile kilicho halisi. yeye aliingia mbinguni kwenyewe ambako sasa anasimama mbele ya Mungu kwa ajili yetu.'),
(2020695,69,58,9,25,'Kuhani Mkuu wa Wayahudi huingia Mahali Patakatifu kila mwaka akiwa amechukua damu ya mnyama; lakini Kristo hakuingia humo ili ajitoe mwenyewe mara nyingi,'),
(2020696,69,58,9,26,'maana ingalikuwa hivyo, Kristo angalipaswa kuteswa mara nyingi tangu kuumbwa ulimwengu. Lakini sasa nyakati hizi zinapokaribia mwisho wake, yeye ametokea mara moja tu, kuondoa dhambi kwa kujitoa yeye mwenyewe dhabihu.'),
(2020697,69,58,9,27,'Basi, kama vile kila mtu hufa mara moja tu, kisha husimama mbele ya hukumu ya Mungu,'),
(2020698,69,58,9,28,'vivyo hivyo Kristo naye alijitoa dhabihu mara moja tu kwa ajili ya kuziondoa dhambi za wengi. Atakapotokea mara ya pili si kwa ajili ya kupambana na dhambi, bali ni kwa ajili ya kuwaokoa wale wanaomngojea.'),
(2020699,69,58,10,1,'Sheria ya Wayahudi si picha kamili ya mambo yale halisi: ni kivuli tu cha mema yanayokuja. Dhabihu zilezile hutolewa daima, mwaka baada ya mwaka. Sheria yawezaje, basi, kwa njia ya dhabihu hizo, kuwafanya wale wanaoabudu wawe wakamilifu?'),
(2020700,69,58,10,2,'Kama hao watu wanaomwabudu Mungu wangekuwa wametakaswa dhambi zao kweli, hawangejisikia tena kuwa na dhambi, na dhabihu hizo zote zingekoma.'),
(2020701,69,58,10,3,'Lakini dhabihu hizo hufanyika kila mwaka kuwakumbusha watu dhambi zao.'),
(2020702,69,58,10,4,'Maana damu ya fahali na mbuzi haiwezi kamwe kuondoa dhambi.'),
(2020703,69,58,10,5,'Ndiyo maana Kristo alipokuwa anakuja ulimwenguni, alimwambia Mungu: "Hukutaka dhabihu wala sadaka, lakini umenitayarishia mwili.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020704,69,58,10,6,'Sadaka za kuteketezwa au za kuondoa dhambi hazikupendezi.'),
(2020705,69,58,10,7,'Hapo nikasema: `Niko hapa ee Mungu, tayari kufanya mapenzi yako kama ilivyoandikwa juu yangu katika kitabu cha Sheria."`'),
(2020706,69,58,10,8,'Kwanza alisema: "Hutaki, wala hupendezwi na dhabihu na sadaka, sadaka za kuteketezwa na za kuondoa dhambi." Alisema hivyo ingawa sadaka hizi zote hutolewa kufuatana na Sheria.'),
(2020707,69,58,10,9,'Kisha akasema: "Niko hapa, ee Mungu, tayari kufanya mapenzi yako." Hivyo Mungu alibatilisha dhabihu za zamani na mahali pake akaweka dhabihu nyingine moja.'),
(2020708,69,58,10,10,'Kwa kuwa Yesu Kristo alitimiza mapenzi ya Mungu, sisi tunatakaswa dhambi zetu kwa ile dhabihu ya mwili wake aliyotoa mara moja tu, ikatosha.'),
(2020709,69,58,10,11,'Kila kuhani Myahudi humhudumia Mungu kila siku, akitoa dhabibu zilezile mara nyingi, dhabibu ambazo haziwezi kuondoa dhambi.'),
(2020710,69,58,10,12,'Lakini Kristo alitoa dhabihu moja tu kwa ajili ya dhambi, dhabihu ifaayo milele, kisha akaketi upande wa kulia wa Mungu.'),
(2020711,69,58,10,13,'Huko anangoja mpaka adui zake watakapowekwa kama kibao chini ya miguu yake.'),
(2020712,69,58,10,14,'Basi, kwa dhabihu yake moja tu, amewafanya kuwa wakamilifu milele wale wanaotakaswa dhambi zao.'),
(2020713,69,58,10,15,'Naye Roho Mtakatifu anatupa ushahidi wake. Kwanza anasema:'),
(2020714,69,58,10,16,'"Hili ndilo agano nitakalofanya nao, katika siku zijazo, asema Bwana: Nitaweka sheria zangu mioyoni mwao, na kuziandika akilini mwao."'),
(2020715,69,58,10,17,'Kisha akaongeza kusema: "Sitakumbuka tena dhambi zao, wala vitendo vyao vya uhalifu."'),
(2020716,69,58,10,18,'Basi, dhambi zikisha ondolewa, hakutakuwa na haja tena ya kutoa dhabihu za kuondoa dhambi.'),
(2020717,69,58,10,19,'Basi, ndugu, kwa damu ya Yesu tunapewa moyo thabiti wa kuingia Mahali Patakatifu.'),
(2020718,69,58,10,20,'Yeye ametufungulia njia mpya na yenye uzima kupitia lile pazia, yaani kwa njia ya mwili wake mwenyewe.'),
(2020719,69,58,10,21,'Basi, tunaye kuhani maarufu aliye na mamlaka juu ya nyumba ya Mungu.'),
(2020720,69,58,10,22,'Kwa hiyo tumkaribie Mungu kwa moyo mnyofu na imani timilifu, kwa mioyo iliyotakaswa dhamiri mbaya, na kwa miili iliyosafishwa kwa maji safi.'),
(2020721,69,58,10,23,'Tushikilie imara tumaini lile tunalokiri, maana Mungu aliyefanya ahadi zake ni mwaminifu.'),
(2020722,69,58,10,24,'Tujitahidi kushughulikiana kwa ajili ya kuongezeana bidii ya kupendana na kutenda mema.'),
(2020723,69,58,10,25,'Tusiache ile desturi ya kukutana pamoja, kama vile wengine wanavyofanya. Bali tunapaswa kusaidiana kwani, kama mwonavyo, Siku ile ya Bwana inakaribia.'),
(2020724,69,58,10,26,'Maana, tukiendelea kutenda dhambi makusudi baada ya kufahamu ukweli, hakuna dhabihu iwezayo kutolewa tena kwa ajili ya kuondoa dhambi.'),
(2020725,69,58,10,27,'Linalobaki ni kungojea tu kwa hofu hukumu ya Mungu na moto mkali utakaowaangamiza wote wanaompinga.'),
(2020726,69,58,10,28,'Mtu yeyote asiyeitii Sheria ya Mose, huuawa bila ya huruma kukiwa na ushahidi wa watu wawili au watatu.'),
(2020727,69,58,10,29,'Je, mtu yule anayempuuza Mwana wa Mungu na kuidharau damu ya agano la Mungu iliyomtakasa, mtu anayemtukana Roho wa Mungu, anastahili kupata adhabu kali ya namna gani?'),
(2020728,69,58,10,30,'Maana tunamfahamu yule aliyesema, "Mimi nitalipiza kisasi, mimi nitalipiza," na ambaye alisema pia, "Bwana atawahukumu watu wake."'),
(2020729,69,58,10,31,'Kuanguka mikononi mwa Mungu aliye hai ni jambo la kutisha mno!'),
(2020730,69,58,10,32,'Kumbukeni yaliyotokea siku zile za kwanza mlipoangaziwa mwanga wa Mungu. Ingawa siku zile mlipatwa na mateso mengi, ninyi mlistahimili.'),
(2020731,69,58,10,33,'Mara nyingine mlitukanwa na kufedheheshwa hadharani; mara nyingine mlikuwa radhi kuungana na wale walioteswa namna hiyohiyo.'),
(2020732,69,58,10,34,'Mlishiriki mateso ya wafungwa, na mliponyang`anywa mali yenu mlistahimili kwa furaha, maana mlijua kwamba mnayo mali bora zaidi na ya kudumu milele.'),
(2020733,69,58,10,35,'Basi, msipoteze uhodari wenu, maana utawapatieni tuzo kubwa.'),
(2020734,69,58,10,36,'Mnahitaji kuwa na uvumilivu, ili mweze kufanya anayotaka Mungu na kupokea kile alichoahidi.'),
(2020735,69,58,10,37,'Maana kama yasemavyo Maandiko: "Bado kidogo tu, na yule anayekuja, atakuja, wala hatakawia.'),
(2020736,69,58,10,38,'Lakini mtu wangu aliye mwadilifu ataamini na kuishi; walakini akirudi nyuma, mimi sitapendezwa naye."'),
(2020737,69,58,10,39,'Basi, sisi hatumo miongoni mwa wale wanaorudi nyuma na kupotea, ila sisi tunaamini na tunaokolewa.'),
(2020738,69,58,11,1,'Kuwa na imani ni kuwa na hakika ya mambo tunayotumainia; kusadiki kabisa mambo tusiyoyaona.'),
(2020739,69,58,11,2,'Maana wazee wa kale walipata kibali cha Mungu kwa sababu ya imani yao.'),
(2020740,69,58,11,3,'Kwa imani sisi tunafahamu kwamba ulimwengu uliumbwa kwa neno la Mungu; vitu vinavyoonekana kutoka vitu visivyoonekana.'),
(2020741,69,58,11,4,'Kwa imani Abeli alimtolea Mungu dhabihu iliyokuwa bora zaidi kuliko ile ya Kaini. Kwa imani yake alikubaliwa na Mungu kuwa mwadilifu; Mungu mwenyewe alizikubali sadaka zake. Kwa imani yake ingawa amekufa, bado ananena.'),
(2020742,69,58,11,5,'Kwa imani Henoki alichukuliwa na Mungu, asipate kufa. Hakuonekana tena kwa sababu Mungu alikuwa amemchukua. Maandiko yasema kwamba kabla ya kuchukuliwa kwake, yeye alikuwa amempendeza Mungu.'),
(2020743,69,58,11,6,'Basi, pasipo imani haiwezekani kumpendeza Mungu. Kwa maana kila mtu anayemwendea Mungu ni lazima aamini kwamba Mungu yuko, na kwamba huwatuza wale wanaomtafuta.'),
(2020744,69,58,11,7,'Kwa imani Noa alionywa na Mungu juu ya mambo ya baadaye ambayo hakuweza kuyaona bado. Alimtii Mungu, akajenga ile safina ambamo aliokolewa yeye pamoja na jamaa yake. Kutokana na hayo ulimwengu ulihukumiwa, naye Noa akapokea uadilifu unaotokana na imani.'),
(2020745,69,58,11,8,'Kwa imani Abrahamu alimtii Mungu alipoitwa aende katika nchi ambayo Mungu angempa iwe yake. Ingawa hakujua alikokuwa anakwenda, Abrahamu alihama.'),
(2020746,69,58,11,9,'Kwa imani aliishi kama mgeni katika nchi aliyoahidiwa na Mungu. Aliishi huko katika hema kama walivyoishi Isaka na Yakobo, ambao pia walishiriki ahadi ileile.'),
(2020747,69,58,11,10,'Maana Abrahamu alikuwa akingojea mji wenye misingi imara, mji ambao Mungu mwenyewe ndiye fundi aliyeubuni na kuujenga.'),
(2020748,69,58,11,11,'Kwa imani hata Sara aliamini kwamba Mungu hutimiza ahadi zake, kwa hiyo akajaliwa kuchukua mimba ingawaje alikuwa amepita umri.'),
(2020749,69,58,11,12,'Kwa hiyo, kutoka katika mtu huyo mmoja, Abrahamu, ambaye alikuwa kama amekufa, walitokea watu wengi wasiohesabika kama vile nyota za mbinguni na mchanga wa pwani.'),
(2020750,69,58,11,13,'Watu hawa wote walikufa wakiwa na imani. Walikufa kabla ya kupokea mambo ambayo Mungu alikuwa ameahidi, lakini kwa mbali waliyaona, wakashangilia, na kukiri wazi kwamba wao walikuwa wageni na wakimbizi duniani.'),
(2020751,69,58,11,14,'Watu wanaosema mambo kama hayo, huonyesha wazi kwamba wanaitafuta nchi yao wenyewe.'),
(2020752,69,58,11,15,'Kama wangalikuwa wanaifikiria nchi walikotoka zamani, wangalipata nafasi ya kurudi huko.'),
(2020753,69,58,11,16,'Lakini sasa wanataka nchi iliyo bora zaidi, yaani nchi ya mbinguni. Ndiyo maana Mungu haoni haya wakimwita yeye Mungu wao, kwa sababu yeye mwenyewe amekwisha watayarishia mji.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020754,69,58,11,17,'Kwa imani, Abrahamu alimtoa mwanae Isaka sadaka wakati Mungu alipomjaribu. Huyo Abrahamu ndiye aliyekuwa amepokea ahadi ya Mungu, lakini, hata hivyo, alikubali kumtoa dhabihu mwanae wa pekee,'),
(2020755,69,58,11,18,'ingawa Mungu alikuwa amemwambia: "Wazawa wako watatokana na Isaka."'),
(2020756,69,58,11,19,'Abrahamu aliamini kwamba Mungu anaweza kuwafufua wafu: na kwa namna fulani kweli Abrahamu alimpata tena mwanae kutoka wafu.'),
(2020757,69,58,11,20,'Kwa imani Isaka aliwabariki Yakobo na Esau, wapate baraka zitakazokuja baadaye.'),
(2020758,69,58,11,21,'Kwa imani Yakobo alipokuwa karibu kufa, aliwabariki kila mmoja wa wana wa Yosefu, akamwabudu Mungu akiegemea ile fimbo yake.'),
(2020759,69,58,11,22,'Kwa imani Yosefu alipokuwa karibu kufa, alinena juu ya kutoka kwa Waisraeli katika nchi ya Misri, na pia akawaachia maagizo kuhusu mifupa yake.'),
(2020760,69,58,11,23,'Kwa imani wazazi wa Mose walimficha huyo mtoto kwa muda wa miezi mitatu baada ya kuzaliwa kwake. Walimwona kuwa ni mtoto mzuri, wala hawakuiogopa amri ya mfalme.'),
(2020761,69,58,11,24,'Kwa imani Mose alipokuwa mtu mzima, alikataa kuitwa mwana wa binti Farao.'),
(2020762,69,58,11,25,'Aliona ni afadhali kuteseka pamoja na watu wa Mungu kuliko kufurahia raha ya dhambi kwa kitambo kidogo.'),
(2020763,69,58,11,26,'Alitambua kwamba kuteseka kwa ajili ya Masiha kuna faida kubwa zaidi kuliko utajiri wote wa nchi ya Misri, maana alikuwa anatazamia tuzo la baadaye.'),
(2020764,69,58,11,27,'Kwa imani Mose alihama kutoka nchi ya Misri bila kuogopa hasira ya mfalme; na wala hakurudi nyuma, kwani alikuwa kama mtu aliyemwona yule Mungu asiyeonekana.'),
(2020765,69,58,11,28,'Kwa imani aliadhimisha siku ya Pasaka, akaamuru damu inyunyizwe juu ya milango, ili yule Malaika Mwangamizi asiwaue wazaliwa wa kwanza wa Israeli.'),
(2020766,69,58,11,29,'Kwa imani watu wa Israeli walivuka bahari ya Shamu, kana kwamba ilikuwa nchi kavu; lakini Wamisri walipojaribu kufanya hivyo walikufa maji.'),
(2020767,69,58,11,30,'Kwa imani kuta za mji wa Yeriko zilianguka watu wa Israeli walipokwisha zunguka kwa muda wa siku saba.'),
(2020768,69,58,11,31,'Kwa imani Rahabu aliyekuwa malaya hakuangamia pamoja na wale waliomwasi Mungu, kwa sababu aliwakaribisha wale wapelelezi.'),
(2020769,69,58,11,32,'Basi, niseme nini zaidi? Wakati hauniruhusu kueleza juu ya Gedeoni, Baraki, Samsoni, Yeftha, Daudi, Samweli na manabii.'),
(2020770,69,58,11,33,'Kwa imani hawa wote walipigana vita na wafalme, wakashinda. Walitenda mambo adili, wakapokea yale aliyoahidi Mungu. Walifunga vinywa vya simba,'),
(2020771,69,58,11,34,'Walizima mioto mikali, waliepuka kuuawa kwa upanga. Walikuwa dhaifu lakini walipata nguvu. Walikuwa hodari katika vita wakashinda majeshi ya kigeni.'),
(2020772,69,58,11,35,'Na, wanawake walioamini walirudishiwa wafu wao wakiwa wamefufuliwa. Baadhi yao walikataa kufunguliwa, wakateswa mpaka kufa ili wapate kufufuliwa na kuingia katika maisha bora zaidi.'),
(2020773,69,58,11,36,'Wengine walidhihakiwa na kupigwa mijeledi, na wengine walifungwa minyororo na kutupwa gerezani.'),
(2020774,69,58,11,37,'Walipigwa mawe, walipasuliwa vipandevipande, waliuawa kwa upanga. Walizungukazunguka wakiwa wamevaa ngozi za kondoo na ngozi za mbuzi, walikuwa watu maskini, walioteswa na kudhulumiwa.'),
(2020775,69,58,11,38,'Ulimwengu haukustahili kuwa na watu hao. Walitangatanga jangwani na mlimani, wakaishi katika mashimo na mapango ya ardhi.'),
(2020776,69,58,11,39,'Watu hawa wote walionekana kuwa mashujaa kwa sababu ya imani yao. Hata hivyo, hawakupokea yale ambayo Mungu aliwaahidia,'),
(2020777,69,58,11,40,'maana Mungu alikuwa ameazimia mpango ulio bora zaidi kwa ajili yetu; yaani wao wangeufikia ukamilifu wakiwa pamoja nasi.'),
(2020778,69,58,12,1,'Sisi tunalo kundi hili kubwa la mashahidi mbele yetu. Kwa hiyo tuondoe kila kizuizi kinachotuzuia, na dhambi ile inayotung`ang`ania. Tupige mbio kwa uvumilivu katika mashindano yaliyowekwa mbele yetu.'),
(2020779,69,58,12,2,'Tumwelekee Yesu ambaye ndiye aliyeianzisha imani yetu na ambaye ataikamilisha. Kwa ajili ya furaha iliyokuwa inamngojea, yeye alivumilia kifo msalabani, bila kujali juu ya aibu yake, na sasa anaketi upande wa kulia wa kiti cha enzi cha Mungu.'),
(2020780,69,58,12,3,'Fikirini juu ya mambo yaliyompata Yesu, jinsi alivyostahimili upinzani mkubwa kwa watu wenye dhambi. Basi, msife moyo, wala msikate tamaa.'),
(2020781,69,58,12,4,'Maana katika kupambana na dhambi, ninyi hamjapigana mpaka kiasi cha kumwaga damu yenu.'),
(2020782,69,58,12,5,'Je, mmesahau yale maneno ya kutia moyo ambayo Mungu anawataja ninyi kuwa wanawe? "Mwanangu, usidharau adhabu ya Bwana, wala usife moyo anapokukanya.'),
(2020783,69,58,12,6,'Maana Bwana humwadhibu kila anayempenda, humpinga kila anayekubali kuwa mwanae."'),
(2020784,69,58,12,7,'Vumilieni adhabu kwani ni mafundisho; Mungu huwatendea ninyi kama wanawe. Maana ni mwana gani asiyeadhibiwa na baba yake?'),
(2020785,69,58,12,8,'Lakini msipoadhibiwa kama wana wengine, basi, ninyi si wanawe, bali ni wana haramu.'),
(2020786,69,58,12,9,'Zaidi ya hayo sisi tunawaheshimu wazazi wetu waliotuzaa hata wanapotuadhibu. Basi, tunapaswa kumtii zaidi Baba yetu wa kiroho ili tupate kuishi.'),
(2020787,69,58,12,10,'Wazazi wetu hapa duniani walituadhibu kwa muda, kama wao wenyewe walivyoona kuwa vema; lakini Mungu anatuadhibu kwa ajili ya faida yetu wenyewe, tupate kuushiriki utakatifu wake.'),
(2020788,69,58,12,11,'Kuadhibiwa si jambo la kufurahisha bali la kuhuzunisha. Lakini wale waliofunzwa kuwa na nidhamu mwishowe watavuna tuzo la amani kutoka katika maisha adili!'),
(2020789,69,58,12,12,'Basi, inueni mikono yenu inayolegea na kuimarisha magoti yenu yaliyo dhaifu.'),
(2020790,69,58,12,13,'Endeleeni kutembea katika njia iliyonyoka, ili kile kilicholemaa kisiumizwe, bali kiponywe.'),
(2020791,69,58,12,14,'Jitahidini kuishi kwa amani na watu wote. Ishini maisha ya utakatifu, kwa sababu hakuna mtu atakayemwona Bwana bila ya maisha kama hayo.'),
(2020792,69,58,12,15,'Jitahidini sana mtu yeyote asije akapoteza neema ya Mungu. Muwe waangalifu ili mti mchungu usizuke kati yenu na kuwaua wengi kwa sumu yake.'),
(2020793,69,58,12,16,'Jihadharini ili miongoni mwenu pasiwe na mtu mwasherati au mtu asiyemcha Mungu kama Esau, aliyeuza haki yake ya mzaliwa wa kwanza kwa mlo mmoja.'),
(2020794,69,58,12,17,'Ninyi mnafahamu kwamba hata alipotaka kuipata tena ile baraka iliyokuwa yake, alikataliwa, maana hakupata tena nafasi ya kutubu, ingawa aliitafuta kwa machozi.'),
(2020795,69,58,12,18,'Ninyi hamkuwasili mlimani Sinai, ambao unaweza kushikika kama walivyofanya watu wa Israeli, hamkufika kwenye moto uwakao, penye giza, tufani,'),
(2020796,69,58,12,19,'mvumo wa tarumbeta na sauti ya maneno. Wale waliosikia sauti hiyo waliomba wasisikie tena neno jingine,'),
(2020797,69,58,12,20,'kwani hawakuweza kustahimili amri iliyotolewa: "Atakayegusa mlima huu, hata kama ni mnyama, atapigwa mawe."'),
(2020798,69,58,12,21,'Hayo yote yalionekana ya kutisha mno, hata Mose akasema, "Naogopa na kutetemeka."'),
(2020799,69,58,12,22,'Lakini ninyi mmefika katika mlima wa Sioni, kwenye mji wa Mungu aliye hai. Mmefika Yerusalemu, mji wa mbinguni, ambapo wamekusanyika malaika elfu nyingi wasiohesabika.'),
(2020800,69,58,12,23,'Mmefika kwenye kusanyiko kubwa la wazaliwa wa kwanza wa Mungu, ambao majina yao yameandikwa mbinguni. Mnasimama mbele ya Mungu aliye hakimu wa wote, na mbele ya roho za watu waadilifu waliofanywa kuwa wakamilifu.'),
(2020801,69,58,12,24,'Mmefika kwa Yesu ambaye ameratibisha agano jipya, na ambaye damu yake iliyomwagika inasema mambo mema zaidi kuliko ile ya Abeli.'),
(2020802,69,58,12,25,'Basi, jihadharini msije mkakataa kumsikiliza yeye ambaye anasema nanyi. Kama wale walikataa kumsikiliza yule aliyewaonya hapa duniani hawakuokoka, sisi tutawezaje kuokoka kama tukikataa kumsikiliza yule anayetuonya kutoka mbinguni?'),
(2020803,69,58,12,26,'Wakati ule sauti ilitetemesha nchi, lakini sasa ameahidi: "Nitatetemesha nchi tena, lakini si nchi tu bali pia mbingu."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020804,69,58,12,27,'Neno hili: "tena" linatuonyesha kwamba vitu vyote vilivyoumbwa vitatetemeshwa na kutoweka ili vibaki vile visivyotetemeshwa.'),
(2020805,69,58,12,28,'Sisi basi, na tushukuru kwani tunapokea utawala usiotikisika. Tuwe na shukrani na kumwabudu Mungu kwa namna itakayompendeza, kwa ibada na hofu;'),
(2020806,69,58,12,29,'maana Mungu wetu kweli ni moto mkali unaoteketeza.'),
(2020807,69,58,13,1,'Endeleeni kupendana kidugu.'),
(2020808,69,58,13,2,'Msisahau kuwakaribisha wageni; maana kwa kufanya hivyo watu wengine walipata kuwakaribisha malaika bila kujua.'),
(2020809,69,58,13,3,'Wakumbukeni wale waliofungwa kana kwamba mmefungwa pamoja nao. Wakumbukeni wale wanaoteseka kana kwamba nanyi mnateseka kama wao.'),
(2020810,69,58,13,4,'Ndoa inapaswa kuheshimiwa na watu wote, na haki zake zitekelezwe kwa uaminifu. Mungu atawahukumu waasherati na wazinzi.'),
(2020811,69,58,13,5,'Msiwe watu wa kupenda fedha; toshekeni na vile vitu mlivyo navyo. Mungu mwenyewe amesema: "Sitakuacha kamwe, wala sitakutupa."'),
(2020812,69,58,13,6,'Ndiyo maana tunathubutu kusema: "Bwana ndiye msaada wangu, sitaogopa. Binadamu atanifanya nini?"'),
(2020813,69,58,13,7,'wakumbukeni viongozi wenu waliowatangazieni ujumbe wa Mungu. Fikirieni juu ya mwenendo wao, mkaige imani yao.'),
(2020814,69,58,13,8,'Yesu Kristo ni yuleyule, jana, leo na milele.'),
(2020815,69,58,13,9,'Msipeperushwe huku na huku kwa mafundisho tofauti ya kigeni. Neema ya Mungu ndiyo inayoimarisha roho zetu na wala si masharti juu ya chakula; masharti hayo hayakumsaidia kamwe mtu yeyote aliyeyafuata.'),
(2020816,69,58,13,10,'Sisi tunayo madhabahu ambayo wale wanaotumikia bado katika hema la Wayahudi, hawana haki ya kula vitu vyake.'),
(2020817,69,58,13,11,'Kuhani Mkuu wa Kiyahudi huleta damu ya wanyama katika Mahali Patakatifu na kuitoa dhabihu kwa ajili ya dhambi; lakini nyama za hao wanyama huteketezwa nje ya kambi.'),
(2020818,69,58,13,12,'Ndiyo maana Yesu pia, kusudi apate kuwatakasa watu kwa damu yake mwenyewe, aliteswa na kufa nje ya mji.'),
(2020819,69,58,13,13,'Basi, tumwendee huko nje ya kambi tukajitwike laana yake.'),
(2020820,69,58,13,14,'Maana hapa duniani hatuna mji wa kudumu; lakini tunautafuta ule unaokuja.'),
(2020821,69,58,13,15,'Basi, kwa njia ya Yesu, tumtolee Mungu dhabihu ya sifa daima, yaani sifa zinazotolewa na midomo inayoliungama jina lake.'),
(2020822,69,58,13,16,'Msisahau kutenda mema na kusaidiana, maana hizi ndizo dhabihu zinazompendeza Mungu.'),
(2020823,69,58,13,17,'Watiini viongozi wenu na kushika amri zao; wao huchunga roho zenu usiku na mchana, na watatoa ripoti ya utumishi wao mbele ya Mungu. Kama mkiwatii watafanya kazi zao kwa furaha, la sivyo, watazifanya kwa huzuni, na hiyo haitakuwa na faida kwenu.'),
(2020824,69,58,13,18,'Tuombeeni na sisi. Tuna hakika kwamba tunayo dhamiri safi, maana twataka kufanya lililo sawa daima.'),
(2020825,69,58,13,19,'Nawasihi sana mniombee ili Mungu anirudishe kwenu upesi iwezekanavyo.'),
(2020826,69,58,13,20,'Mungu amemfufua Bwana wetu Yesu Kristo ambaye ni Mchungaji Mkuu wa kondoo kwa sababu ya kumwaga damu yake iliyothibitisha agano la milele.'),
(2020827,69,58,13,21,'Mungu wa amani awakamilishe katika kila tendo jema ili mtekeleze mapenzi yake; yeye na afanye ndani yetu kwa njia ya Kristo yale yanayompendeza mwenyewe. Utukufu uwe kwake, milele na milele! Amina.'),
(2020828,69,58,13,22,'Basi, ndugu, nawasihi mpokee kwa utulivu ujumbe huu wa kuwatieni moyo. Hii ni barua fupi tu ambayo nimewaandikieni.'),
(2020829,69,58,13,23,'Napenda kuwajulisheni kwamba ndugu yetu Timotheo amekwisha funguliwa gerezani. Kama akifika hapa mapema, nitakuja naye nitakapokuja kwenu.'),
(2020830,69,58,13,24,'Wasalimieni viongozi wenu wote pamoja na watu wa Mungu! Ndugu wa Italia wanawasalimuni.'),
(2020831,69,58,13,25,'Tunawatakieni nyote neema ya Mungu.'),
(2020832,69,59,1,1,'Mimi Yakobo, mtumishi wa Mungu na wa Bwana Yesu Kristo, nawaandikia ninyi, makabila kumi na mawili, yaliyotawanyika ulimwenguni! Salaam!'),
(2020833,69,59,1,2,'Ndugu zangu, muwe na furaha mnapopatwa na majaribu mbalimbali,'),
(2020834,69,59,1,3,'kwani mwajua kwamba imani yenu ikisha stahimili, itawapatieni uvumilivu.'),
(2020835,69,59,1,4,'Muwe na hakika kwamba uvumilivu wenu utawategemeza mpaka mwisho, mpate kuwa wakamilifu na watimilifu, bila kupungukiwa chochote.'),
(2020836,69,59,1,5,'Lakini kama mmoja wenu ametindikiwa hekima, basi, anapaswa kumwomba Mungu ambaye atampatia; kwani Mungu huwapa wote kwa wingi na kwa ukarimu.'),
(2020837,69,59,1,6,'Lakini anapaswa kuomba kwa imani bila mashaka yoyote. Mtu aliye na mashaka ni kama mawimbi ya bahari ambayo husukumwa na kutupwatupwa na upepo.'),
(2020838,69,59,1,7,'Mtu wa namna hiyo, mwenye nia mbili na asiye na msimamo katika mwenendo wake wote, asidhani ya kwamba atapata chochote kile kutoka kwa Bwana.'),
(2020839,69,59,1,8,'[]'),
(2020840,69,59,1,9,'Ndugu aliye maskini anapaswa kufurahi wakati Mungu anapomkweza,'),
(2020841,69,59,1,10,'naye tajiri anapaswa kufurahi anaposhushwa na Mungu. Maana tajiri atatoweka kama ua la porini.'),
(2020842,69,59,1,11,'Jua huchomoza na kwa joto lake kali hukausha mimea, nayo maua yake huanguka, na uzuri wake wote huharibika. Vivyo hivyo, tajiri ataangamizwa katika shughuli zake.'),
(2020843,69,59,1,12,'Heri mtu anayebaki mwaminifu katika majaribu, kwani akisha stahimili atapewa tuzo la uzima ambalo Mungu aliwaahidia wale wanaompenda.'),
(2020844,69,59,1,13,'Kama mtu akijaribiwa, asiseme: "Ninajaribiwa na Mungu." Maana Mungu hawezi kujaribiwa na uovu, wala yeye hamjaribu mtu yeyote.'),
(2020845,69,59,1,14,'Lakini mtu hujaribiwa anapovutwa na kunaswa na tamaa zake mbaya.'),
(2020846,69,59,1,15,'Tamaa ikiiva huzaa dhambi; nayo dhambi ikikomaa huzaa kifo.'),
(2020847,69,59,1,16,'Ndugu zangu wapenzi, msidanganyike!'),
(2020848,69,59,1,17,'Kila kipaji chema na kila zawadi kamilifu hutoka mbinguni; hutoka kwa Baba, Muumba wa mianga, ambaye habadiliki wala hana alama yoyote ya ugeugeu.'),
(2020849,69,59,1,18,'Kwa kupenda kwake mwenyewe alituzaa kwa neno lake la ukweli, ili tuwe namna ya matunda ya kwanza miongoni mwa viumbe vyake.'),
(2020850,69,59,1,19,'Ndugu zangu wapenzi, kumbukeni jambo hili! Kila mtu na awe mwepesi wa kusikia lakini asiwe mwepesi wa kusema wala mwepesi wa kukasirika.'),
(2020851,69,59,1,20,'Mwenye hasira hawezi kutimiza matakwa ya Mungu yaliyo ya haki.'),
(2020852,69,59,1,21,'Kwa hiyo, tupilieni mbali mwenendo mchafu na tabia zote mbovu; jiwekeni chini ya Mungu na kupokea ule ujumbe uliopandwa mioyoni mwenu, ambao waweza kuziokoa nafsi zenu.'),
(2020853,69,59,1,22,'Msijidanganye wenyewe kwa kusikiliza tu neno lake, bali litekelezeni kwa vitendo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020854,69,59,1,23,'Yeyote anayesikiliza hilo neno lakini halitekelezi, huyo ni kama mtu anayejiangalia sura yake mwenyewe katika kioo.'),
(2020855,69,59,1,24,'Hujiangalia mwenyewe, kisha huenda zake, na mara husahau jinsi alivyo.'),
(2020856,69,59,1,25,'Lakini mtu anayeangalia kwa makini sheria kamilifu ambayo huwapa watu uhuru, mtu anayeendelea kuizingatia, na si kuisikia tu na kuisahau baadaye, bali anaitekeleza, mtu huyo atabarikiwa katika kila kitu anachofanya.'),
(2020857,69,59,1,26,'Kama mtu akijiona kuwa ni mtu mwenye dini, lakini hawezi kuutawala ulimi wake, dini yake haifai kitu, na anajidanganya mwenyewe.'),
(2020858,69,59,1,27,'Dini iliyo safi na isiyo na hitilafu mbele ya Mungu Baba ni hii: Kuwasaidia yatima na wajane katika shida zao, na kujilinda mwenyewe usichafuliwe na ulimwengu huu.'),
(2020859,69,59,2,1,'Ndugu zangu, mkiwa mnamwamini Bwana Yesu Kristo, Bwana wa utukufu, msiwabague watu kamwe.'),
(2020860,69,59,2,2,'Tuseme mtu mmoja ambaye amevaa pete ya dhahabu na mavazi nadhifu anaingia katika mkutano wenu, na papo hapo akaingia mtu maskini aliyevaa mavazi machafu.'),
(2020861,69,59,2,3,'Ikiwa mtamstahi zaidi yule aliyevaa mavazi ya kuvutia na kumwambia: "Keti hapa mahali pazuri," na kumwambia yule maskini: "Wewe, simama huko," au "Keti hapa sakafuni miguuni pangu,"'),
(2020862,69,59,2,4,'je, huo si ubaguzi kati yenu? Je, na huo uamuzi wenu haujatokana na fikira mbaya?'),
(2020863,69,59,2,5,'Ndugu zangu wapenzi, sikilizeni! Mungu amechagua watu ambao ni maskini katika ulimwengu huu ili wapate kuwa matajiri katika imani na kupokea Utawala aliowaahidia wale wanaompenda.'),
(2020864,69,59,2,6,'Lakini ninyi mnawadharau watu maskini! Je, matajiri si ndio wanaowakandamizeni na kuwapeleka mahakamani?'),
(2020865,69,59,2,7,'Je, si haohao wanaolitukana hilo jina lenu zuri mlilopewa?'),
(2020866,69,59,2,8,'Kama mnaitimiza ile sheria ya Utawala kama ilivyoandikwa katika Maandiko Matakatifu: "Mpende binadamu mwenzako kama unavyojipenda wewe mwenyewe", mtakuwa mnafanya vema kabisa.'),
(2020867,69,59,2,9,'Lakini mkiwabagua watu, basi, mwatenda dhambi, nayo Sheria inawahukumu ninyi kuwa mna hatia.'),
(2020868,69,59,2,10,'Anayevunja amri mojawapo ya Sheria, atakuwa na hatia ya kuivunja Sheria yote.'),
(2020869,69,59,2,11,'Maana yuleyule aliyesema: "Usizini," alisema pia "Usiue". Kwa hiyo, hata ikiwa hukuzini lakini umeua, wewe umeivunja Sheria.'),
(2020870,69,59,2,12,'Basi, semeni na kutenda kama watu watakaohukumiwa kwa sheria iletayo uhuru.'),
(2020871,69,59,2,13,'Maana, Mungu hatakuwa na huruma atakapomhukumu mtu asiyekuwa na huruma. Lakini huruma hushinda hukumu.'),
(2020872,69,59,2,14,'Ndugu zangu, kuna faida gani mtu kusema ana imani, lakini haonyeshi kwa vitendo? Je, hiyo imani yawezaje kumwokoa?'),
(2020873,69,59,2,15,'Tuseme kaka au dada hana nguo au chakula.'),
(2020874,69,59,2,16,'Yafaa kitu gani ninyi kuwaambia hao: "Nendeni salama mkaote moto na kushiba," bila kuwapatia mahitaji yao ya maisha?'),
(2020875,69,59,2,17,'Vivyo hivyo, imani peke yake bila matendo imekufa.'),
(2020876,69,59,2,18,'Lakini mtu anaweza kusema: "Wewe unayo imani, mimi ninayo matendo!" Haya! Nionyeshe jinsi mtu anavyoweza kuwa na imani bila matendo, nami nitakuonyesha imani yangu kwa matendo yangu.'),
(2020877,69,59,2,19,'Je, wewe unaamini kwamba yuko Mungu mmoja? Sawa! Lakini hata pepo huamini hilo, na hutetemeka kwa hofu.'),
(2020878,69,59,2,20,'Mpumbavu wee! Je, wataka kuonyeshwa kwamba imani bila matendo imekufa?'),
(2020879,69,59,2,21,'Je, Abrahamu baba yetu alipataje kukubalika mbele yake Mungu? Kwa matendo yake, wakati alipomtoa mwanae Isaka sadaka juu ya madhabahu.'),
(2020880,69,59,2,22,'Waona basi, kwamba imani yake iliandamana na matendo yake; imani yake ilikamilishwa kwa matendo yake.'),
(2020881,69,59,2,23,'Hivyo yakatimia yale Maandiko Matakatifu yasemayo: "Abrahamu alimwamini Mungu na kwa imani yake akakubaliwa kuwa mtu mwadilifu; na hivyo Abrahamu akaitwa rafiki wa Mungu."'),
(2020882,69,59,2,24,'Mnaona basi, kwamba mtu hukubaliwa kuwa mwadilifu kwa matendo yake na si kwa imani peke yake.'),
(2020883,69,59,2,25,'Ilikuwa vivyo hivyo kuhusu yule malaya Rahabu; yeye alikubaliwa kuwa mwadilifu kwa sababu aliwapokea wale wapelelezi na kuwasaidia waende zao kwa kupitia njia nyingine.'),
(2020884,69,59,2,26,'Basi, kama vile mwili bila roho umekufa, vivyo hivyo imani bila matendo imekufa.'),
(2020885,69,59,3,1,'Ndugu zangu, wengi wenu msiwe walimu. Kama mjuavyo, sisi walimu tutapata hukumu kubwa zaidi kuliko wengine.'),
(2020886,69,59,3,2,'Lakini kama mtu hakosi katika usemi wake, basi, huyo ni mkamilifu, na anaweza kutawala nafsi yake yote.'),
(2020887,69,59,3,3,'Sisi huwatia farasi lijamu kinywani mwao ili watutii; na kwa njia hiyo twaweza kuwaongoza kokote tunakotaka.'),
(2020888,69,59,3,4,'Meli nazo pia, ingawa ni kubwa sana, na husukumwa na upepo mkali, huweza kugeuzwa kwa usukani mdogo sana, zikaelekea kokote nahodha anakotaka.'),
(2020889,69,59,3,5,'Vivyo hivyo, ulimi, ingawa ni kiungo kidogo cha mwili, hujisifia makuu sana. ic Moto mdogo waweza kuteketeza msitu mkubwa.'),
(2020890,69,59,3,6,'Hali kadhalika ulimi ni kama moto. Umejaa maovu chungu nzima, unayo nafasi yake katika miili yetu na hueneza ubaya katika nafsi zetu zote. Huteketeza maisha yetu yote kwa moto utokao Jehanamu kwenyewe.'),
(2020891,69,59,3,7,'Binadamu anaweza kuwafuga wanyama, na amefaulu kufuga viumbe vyote--wanyama wa mwituni, ndege, nyoka na viumbe vya baharini.'),
(2020892,69,59,3,8,'Lakini hakuna mtu aliyeweza kuufuga ulimi. Ulimi ni kitu kiovu, hakitawaliki, na kimejaa sumu inayoua.'),
(2020893,69,59,3,9,'Kwa ulimi sisi twamshukuru Bwana na Baba yetu. Kwa ulimi huohuo twawalaani watu, watu ambao wameumbwa kwa mfano wa Mungu.'),
(2020894,69,59,3,10,'Maneno ya laana na ya kusifia hutoka katika kinywa kimoja. Ndugu zangu, mambo haya hayapaswi kuwa hivyo.'),
(2020895,69,59,3,11,'Je, chemchemi moja yaweza kutoa maji matamu na maji machungu pamoja?'),
(2020896,69,59,3,12,'Ndugu zangu, je, mti wa mtini waweza kuzaa zeituni? Au, mzabibu waweza kuzaa tini? Chemchemi ya maji ya chumvi haiwezi kutoa maji matamu.'),
(2020897,69,59,3,13,'Je, ni nani mwenye hekima na akili miongoni mwenu? Basi, aonyeshe jambo hilo kwa mwenendo wake mzuri na kwa matendo yake mema yanayofanyika kwa unyenyekevu na hekima.'),
(2020898,69,59,3,14,'Lakini ikiwa mioyo yenu imejaa wivu, chuki na ubinafsi, basi, msijisifu na kusema uongo dhidi ya ukweli.'),
(2020899,69,59,3,15,'Hekima ya namna hiyo haitoki juu mbinguni; hekima hiyo ni ya ulimwengu, na ya kidunia, tena ni ya kishetani.'),
(2020900,69,59,3,16,'Maana popote palipo na wivu na ubinafsi hapo pana fujo na kila aina ya uovu.'),
(2020901,69,59,3,17,'Lakini hekima itokayo juu mbinguni, kwanza ni safi; inapenda amani, upole na huwajali watu; imejaa huruma na huzaa matunda ya matendo mema; haina ubaguzi wala unafiki.'),
(2020902,69,59,3,18,'Uadilifu ni mazao ya mbegu ambazo wapenda amani hupanda katika amani.'),
(2020903,69,59,4,1,'Mapigano na magombano yote kati yenu yanatoka wapi? Hutoka katika tamaa zenu mbaya ambazo hupigana daima ndani yenu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020904,69,59,4,2,'Mnatamani vitu na kwa vile hamvipati mko tayari kuua; mwatamani sana kupata vitu, lakini hamvipati, hivyo mnagombana na kupigana. Hampati kile mnachotaka kwa sababu hamkiombi kwa Mungu.'),
(2020905,69,59,4,3,'Tena, mnapoomba hampati kwa sababu mnaomba kwa nia mbaya; mnaomba ili mpate kutosheleza tamaa zenu.'),
(2020906,69,59,4,4,'Ninyi ni watu msio na uaminifu kama wazinzi. Je, hamjui kwamba kuwa rafiki wa ulimwengu ni kuwa adui wa Mungu? Yeyote anayetaka kuwa rafiki wa ulimwengu anajifanya adui wa Mungu.'),
(2020907,69,59,4,5,'Msifikiri kwamba Maandiko Matakatifu yamesema maneno ya bure, yanaposema: "Roho ambaye Mungu amemweka ndani yetu ana wivu mkubwa."'),
(2020908,69,59,4,6,'Lakini, neema tunayopewa na Mungu ina nguvu zaidi; kama yasemavyo Maandiko: "Mungu huwapinga wenye majivuno lakini huwapa neema wanyenyekevu."'),
(2020909,69,59,4,7,'Basi, jiwekeni chini ya Mungu; mpingeni Ibilisi naye atawakimbieni.'),
(2020910,69,59,4,8,'Mkaribieni Mungu, naye atakuja karibu nanyi. Osheni mikono yenu enyi wakosefu! Safisheni mioyo yenu enyi wanafiki!'),
(2020911,69,59,4,9,'Oneni huzuni, lieni na kuomboleza; kicheko chenu na kiwe kilio; na furaha yenu iwe huzuni kubwa.'),
(2020912,69,59,4,10,'Nyenyekeeni mbele ya Bwana, naye atawainueni.'),
(2020913,69,59,4,11,'Ndugu, msilaumiane ninyi kwa ninyi. Anayemlaumu ndugu yake na kumhukumu, huyo huilaumu na kuihukumu Sheria. Kama ukiihukumu Sheria, basi, wewe huitii Sheria, bali waihukumu.'),
(2020914,69,59,4,12,'Mungu peke yake ndiye mwenye kuweka Sheria na kuhukumu. Ni yeye peke yake anayeweza kuokoa na kuangamiza. Basi, wewe ni nani hata umhukumu binadamu mwenzako?'),
(2020915,69,59,4,13,'Basi, sasa sikilizeni ninyi mnaosema: "Leo au kesho tutakwenda katika mji fulani na kukaa huko mwaka mzima tukifanya biashara na kupata faida."'),
(2020916,69,59,4,14,'Ninyi hamjui hata maisha yenu yatakavyokuwa kesho! Ninyi ni kama ukungu unaotokea kwa muda mfupi tu na kutoweka tena.'),
(2020917,69,59,4,15,'Mngalipaswa kusema: "Bwana akitujalia tutaishi na tutafanya hiki au kile."'),
(2020918,69,59,4,16,'Lakini sasa mwajivuna na kujigamba; majivuno ya namna hiyo ni mabaya.'),
(2020919,69,59,4,17,'Basi, mtu ambaye hafanyi lile jambo jema analojua kwamba anapaswa kulifanya, anatenda dhambi.'),
(2020920,69,59,5,1,'Na sasa sikilizeni enyi matajiri! Lieni na kuomboleza kwa sababu ya taabu zitakazowajieni.'),
(2020921,69,59,5,2,'Mali zenu zimeoza, na nguo zenu zimeliwa na nondo.'),
(2020922,69,59,5,3,'Dhahabu yenu na fedha vimeota kutu, na kutu hiyo itakuwa ushahidi dhidi yenu, nayo itakula miili yenu kama vile moto. Ninyi mmejilundikia mali katika siku hizi za mwisho!'),
(2020923,69,59,5,4,'Hamkuwalipa mishahara watumishi waliofanya kazi katika mashamba yenu. Sikilizeni malalamiko yao! Kilio cha hao wanaovuna mashamba yenu kimefika masikioni mwa Bwana, Mwenye Nguvu.'),
(2020924,69,59,5,5,'Mmeishi duniani maisha ya kujifurahisha na ya anasa. Mmejinenepesha tayari kwa siku ya kuchinjwa.'),
(2020925,69,59,5,6,'Mmemhukumu na kumwua mtu asiye na hatia, naye hakuwapigeni.'),
(2020926,69,59,5,7,'Basi, ndugu zangu, muwe na subira mpaka Bwana atakapokuja. Tazameni mkulima anavyongoja kwa subira mimea yake itoe mavuno mazuri. Yeye hungojea kwa subira mvua za masika na za vuli.'),
(2020927,69,59,5,8,'Nanyi pia mnapaswa kuwa na subira; imarisheni mioyo yenu, maana siku ya kuja kwake Bwana inakaribia.'),
(2020928,69,59,5,9,'Ndugu zangu, msinung`unikiane ninyi kwa ninyi msije mkahukumiwa na Mungu. Hakimu yu karibu, tayari kuingia.'),
(2020929,69,59,5,10,'Ndugu, mkitaka kuona mfano wa subira na uvumilivu katika mateso, fikirini juu ya manabii ambao walinena kwa jina la Bwana.'),
(2020930,69,59,5,11,'Tunawaita hao wenye heri kwa sababu walivumilia. Mmesikia habari za uvumilivu wa Yobu, na mnajua jinsi Bwana alivyomtendea mwishoni. Maana Bwana amejaa huruma na rehema.'),
(2020931,69,59,5,12,'Zaidi ya hayo yote, ndugu zangu, msiape kwa mbingu, wala kwa dunia, wala kwa kitu kingine chochote. Semeni "Ndiyo" kama maana yenu ni ndiyo, na "La" kama maana yenu ni la, na hapo hamtahukumiwa na Mungu.'),
(2020932,69,59,5,13,'Je, pana mtu yeyote miongoni mwenu aliye na shida? Anapaswa kusali. Je, yuko mwenye furaha? Anapaswa kuimba nyimbo za sifa.'),
(2020933,69,59,5,14,'Je, yuko mgonjwa kati yenu? Anapaswa kuwaita wazee wa kanisa, nao watamwombea na kumpaka mafuta kwa jina la Bwana.'),
(2020934,69,59,5,15,'Wakiomba kwa imani mgonjwa ataponyeshwa; Bwana atampatia nafuu, na dhambi alizotenda zitaondolewa.'),
(2020935,69,59,5,16,'Basi, ungamanianeni dhambi zenu, na ombeaneni, ili mpate kuponywa. Sala ya mtu mwema ina nguvu ya kutenda mengi.'),
(2020936,69,59,5,17,'Eliya alikuwa binadamu kama sisi. Aliomba kwa moyo mvua isinyeshe, nayo haikunyesha nchini kwa muda wa miaka mitatu na miezi sita.'),
(2020937,69,59,5,18,'Kisha akaomba tena, mvua ikanyesha kutoka angani na nchi ikatoa mazao yake.'),
(2020938,69,59,5,19,'Ndugu zangu, mmoja wenu akipotoka kuhusu ukweli, na mwingine akamrudisha,'),
(2020939,69,59,5,20,'fahamuni kwamba, huyo anayemrudisha mwenye dhambi kutoka njia yake ya upotovu, ataiokoa roho yake kutoka kifo, na dhambi nyingi zitaondolewa.'),
(2020940,69,60,1,1,'Mimi Petro, mtume wa Yesu Kristo nawaandikia ninyi wateule wa Mungu Baba, ambao mmetawanyika na mnaishi kama wakimbizi huko Ponto, Galatia, Kapadokia, Asia na Bithunia.'),
(2020941,69,60,1,2,'Mungu Baba aliwateua ninyi kufuatana na kusudi lake, na mmefanywa watakatifu na Roho, mpate kumtii Yesu Kristo na kusafishwa kwa damu yake. Nawatakieni neema na amani tele.'),
(2020942,69,60,1,3,'Asifiwe Mungu na Baba wa Bwana wetu Yesu Kristo! Kwa huruma yake kuu alitufanya tuzaliwe upya kwa kumfufua Yesu kutoka wafu. Ametujalia tumaini lenye uzima,'),
(2020943,69,60,1,4,'na hivyo tunatazamia kupata baraka zile ambazo Mungu aliwawekea watu wake. Mungu amewawekeeni baraka hizo mbinguni ambako haziwezi kuoza au kuharibika au kufifia.'),
(2020944,69,60,1,5,'Hizo zitakuwa zenu ninyi ambao kwa imani mnalindwa salama kwa nguvu ya Mungu kwa ajili ya wokovu ambao uko tayari kufunuliwa mwishoni mwa nyakati.'),
(2020945,69,60,1,6,'Furahini kuhusu jambo hilo, ijapokuwa sasa, kwa kitambo kidogo, itawabidi kuhuzunika kwa sababu ya majaribio mbalimbali mnayoteseka.'),
(2020946,69,60,1,7,'Shabaha yake ni kuthibitisha imani yenu. Hata dhahabu yenyewe ambayo huharibika, hujaribiwa kwa moto; hali kadhalika na imani yenu ambayo ni ya thamani zaidi kuliko dhahabu, ni lazima ijaribiwe ipate kuwa thabiti. Hapo mtapokea sifa na utukufu na heshima Siku ile Yesu Kristo atakapofunuliwa.'),
(2020947,69,60,1,8,'Ninyi mnampenda ingawaje hamjamwona, na mnamwamini ingawa hamumwoni sasa. Hivyo, mnafurahi kwa furaha tukufu isiyoelezeka,'),
(2020948,69,60,1,9,'kwa sababu mnapokea wokovu wa roho zenu ambao ni lengo la imani yenu.'),
(2020949,69,60,1,10,'Manabii walipeleleza kwa makini na kufanya uchunguzi juu ya wokovu huo, wakabashiri juu ya neema hiyo ambayo ninyi mngepewa.'),
(2020950,69,60,1,11,'Walijaribu kujua nyakati na mazingira ya tukio hilo, yaani wakati alioudokezea Roho wa Kristo aliyekuwa ndani yao, akibashiri juu ya mateso yatakayompata Kristo na utukufu utakaofuata.'),
(2020951,69,60,1,12,'Mungu aliwafunulia kwamba wakati walipokuwa wanasema juu ya hayo mambo ambayo ninyi mmekwisha sikia sasa kutoka kwa wale wajumbe waliowatangazieni Habari Njema kwa nguvu ya Roho Mtakatifu aliyetumwa kutoka mbinguni, hiyo kazi yao haikuwa kwa faida yao wenyewe, bali kwa ajili yenu. Hayo ndiyo mambo ambayo hata malaika wangependa kuyafahamu.'),
(2020952,69,60,1,13,'Kwa hiyo, basi, muwe tayari kabisa kwa nia, na kukesha. Wekeni tumaini lenu lote katika baraka ile mtakayopewa wakati Yesu Kristo atakapoonekana!'),
(2020953,69,60,1,14,'Kama watoto wa Mungu wenye utii, msikubali kamwe kufuata tena tamaa mbaya mlizokuwa nazo wakati mlipokuwa wajinga.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2020954,69,60,1,15,'Bali mnapaswa kuwa watakatifu katika mwenendo wenu wote, kama vile yule aliyewaiteni ni mtakatifu.'),
(2020955,69,60,1,16,'Maandiko yasema: "Muwe watakatifu, kwa kuwa mimi ni mtakatifu."'),
(2020956,69,60,1,17,'Mnapomtaja Mungu ninyi humwita Baba. Basi, jueni kwamba yeye humhukumu kila mmoja kadiri ya matendo yake, bila ubaguzi. Hivyo tumieni wakati wenu uliowabakia hapa ugenini katika kumcha Mungu.'),
(2020957,69,60,1,18,'Maana mnajua kwamba ninyi mlikombolewa katika mwenendo wenu usiofaa ambao mliupokea kutoka kwa wazee wenu, si kwa vitu vyenye kuharibika: kwa fedha na dhahabu;'),
(2020958,69,60,1,19,'bali mlikombolewa kwa damu tukufu ya Kristo, ambaye alikuwa kama mwana kondoo asiye na dosari wala doa.'),
(2020959,69,60,1,20,'Yeye alikuwa ameteuliwa na Mungu kabla ya ulimwengu kuumbwa, akafunuliwa siku hizi za mwisho kwa ajili yenu.'),
(2020960,69,60,1,21,'Kwa njia yake, ninyi mnamwamini Mungu aliyemfufua kutoka wafu na kumpa utukufu; na hivyo imani na matumaini yenu yako kwa Mungu.'),
(2020961,69,60,1,22,'Maadamu sasa, kwa kuutii ukweli, ninyi mmezitakasa roho zenu na kuwapenda wenzenu bila unafiki, basi, pendaneni kwa moyo wote.'),
(2020962,69,60,1,23,'Maana kwa njia ya neno hai la Mungu, ninyi mmezaliwa upya, si kama watoto wa baba awezaye kufa, bali baba asiyekufa milele.'),
(2020963,69,60,1,24,'Kama Maandiko yasemavyo: "Kila binadamu ni kama nyasi, na utukufu wake wote ni kama maua ya porini. Nyasi hunyauka na maua huanguka.'),
(2020964,69,60,1,25,'Lakini neno la Bwana hudumu milele." Neno hilo ni hiyo Habari Njema iliyohubiriwa kwenu.'),
(2020965,69,60,2,1,'Basi, acheni uovu wote; uongo, unafiki, wivu na maneno ya kashfa visiweko tena.'),
(2020966,69,60,2,2,'Kama vile watoto wachanga wanavyotamani maziwa, nanyi pia mnapaswa kuwa na hamu ya maziwa halisi ya kiroho, ili kwa nguvu yake mpate kukua na kukombolewa.'),
(2020967,69,60,2,3,'Kama yasemavyo Maandiko Matakatifu: "Mmegundua kwamba Bwana ni mwema."'),
(2020968,69,60,2,4,'Basi, mwendeeni Bwana! Yeye ndiye jiwe hai lililokataliwa na watu; lakini mbele ya Mungu ni jiwe teule, na la thamani kubwa.'),
(2020969,69,60,2,5,'Mwendeeni yeye kama mawe hai mkajengeke na kuwa nyumba ya kiroho, ambamo mtatumikia kama makuhani watakatifu, kutolea dhabihu za kiroho zenye kumpendeza Mungu kwa njia ya Yesu Kristo.'),
(2020970,69,60,2,6,'Maana Maandiko Matakatifu yasema: "Tazama! Naweka huko sioni jiwe kuu la msingi, jiwe la thamani kubwa nililoliteua. Mtu atakayemwamini yeye aliye hilo jiwe, hataaibishwa."'),
(2020971,69,60,2,7,'Kwenu ninyi mnaoamini, jiwe hilo ni la thamani kubwa; lakini kwa wale wasioamini, "Jiwe walilokataa waashi, sasa limekuwa jiwe kuu la msingi."'),
(2020972,69,60,2,8,'Tena Maandiko yasema: "Jiwe hilo ni jiwe la kujikwaa, mwamba wa kuwaangusha watu." Watu hujikwaa kwa sababu hawauamini ule ujumbe; na ndivyo walivyopangiwa tangu mwanzo.'),
(2020973,69,60,2,9,'Lakini ninyi ni ukoo mteule, makuhani wa Mfalme, taifa takatifu; watu wake Mungu mwenyewe, mlioteuliwa kutangaza matendo makuu ya Mungu aliyewaiteni kutoka gizani akawaingizeni katika mwanga wake mkuu.'),
(2020974,69,60,2,10,'Wakati mmoja ninyi hamkuwa watu wa Mungu, lakini sasa ninyi ni watu wake; wakati mmoja hamkupewa huruma ya Mungu, lakini sasa mmeipokea.'),
(2020975,69,60,2,11,'Wapenzi wangu, nawasihi ninyi kama wageni na wakimbizi hapa duniani! Achaneni na tamaa za mwili ambazo hupingana na roho.'),
(2020976,69,60,2,12,'Mwenendo wenu kati ya watu wasiomjua Mungu unapaswa kuwa mwema kabisa, ili hata watakapowasingizieni kwamba mnatenda mabaya, waweze kutambua matendo yenu mema na hivyo wamtukuze Mungu Siku ya kuja kwake.'),
(2020977,69,60,2,13,'Basi, jiwekeni chini ya mamlaka yote ya kibinadamu, kwa ajili ya Bwana: utii kwa mfalme aliye mtawala mkuu,'),
(2020978,69,60,2,14,'utii kwa wakuu wa mikoa ambao wameteuliwa naye kuwaadhibu wahalifu na kuwasifu watendao mema.'),
(2020979,69,60,2,15,'Maana Mungu anataka mweze kuyakomesha maneno ya kijinga ya watu wasio na akili kwa matendo mema mnayofanya.'),
(2020980,69,60,2,16,'Ishini kama watu huru; lakini msiutumie uhuru wenu kuuficha ubaya, bali ishini kama watumishi wa Mungu.'),
(2020981,69,60,2,17,'Waheshimuni watu wote, wapendeni ndugu zenu waumini, mcheni Mungu, mheshimuni mfalme.'),
(2020982,69,60,2,18,'Enyi watumishi wa nyumbani, watiini wakuu wenu kwa heshima yote, wawe wema na wapole au wenye kuchukiza.'),
(2020983,69,60,2,19,'Maana kama mnavumilia maumivu ya mateso msiyostahili kwa sababu mwajua kwamba Mungu anataka hivyo, basi Mungu atawafadhili.'),
(2020984,69,60,2,20,'Maana, mtapata tuzo gani mkivumilia mapigo mnayostahili kwa sababu ya makosa yenu? Lakini kama mnavumilia mateso hata ingawa mmetenda mema, Mungu atawapeni baraka kwa ajili hiyo.'),
(2020985,69,60,2,21,'Hayo ndiyo mliyoitiwa; maana Kristo mwenyewe aliteseka kwa ajili yenu, akawaachieni mfano, ili muufuate mwenendo wake.'),
(2020986,69,60,2,22,'Yeye hakutenda dhambi, wala neno la udanganyifu halikusikika mdomoni mwake.'),
(2020987,69,60,2,23,'Alipotukanwa yeye hakujibu kwa tukano; alipoteseka yeye hakutoa vitisho, bali aliyaweka matumaini yake kwa Mungu, hakimu mwenye haki.'),
(2020988,69,60,2,24,'Yeye mwenyewe alizibeba dhambi zetu katika mwili wake juu ya msalaba, tupate kufa kuhusu dhambi, na kuishi kwa ajili ya uadilifu. Kwa majeraha yake, ninyi mmeponywa.'),
(2020989,69,60,2,25,'Ninyi mlikuwa kama kondoo waliokuwa wamepotea; lakini sasa mmemrudia Mchungaji na Mlinzi wa roho zenu.'),
(2020990,69,60,3,1,'Nanyi wake, jiwekeni chini ya mamlaka ya waume zenu, ili kama wako waume wowote wasioamini neno la Mungu, wapate kuamini kwa kuuona mwenendo wenu. Haitakuwa lazima kwenu kusema neno,'),
(2020991,69,60,3,2,'kwani wataona jinsi mwenendo wenu ulivyo safi na wa kumcha Mungu.'),
(2020992,69,60,3,3,'Katika kujipamba kwenu msitegemee mambo ya njenje, kama vile mitindo ya kusuka nywele, kujivalia vitu vya dhahabu na nguo maridadi.'),
(2020993,69,60,3,4,'Bali, uzuri wenu unapaswa kutokana na hali ya ndani ya utu wa kweli, uzuri usioharibika wa wema na utulivu wa roho, ambao ni wa thamani kubwa mbele ya Mungu.'),
(2020994,69,60,3,5,'Ndivyo walivyojipamba hapo kale wanawake waadilifu waliomtumainia Mungu; walijiweka chini ya mamlaka ya waume zao.'),
(2020995,69,60,3,6,'Sara kwa mfano alimtii Abrahamu na kumwita yeye bwana. Ninyi mmekuwa sasa binti zake kama mkitenda mema bila kuogopa tisho lolote.'),
(2020996,69,60,3,7,'Kadhalika nanyi waume, katika kuishi na wake zenu mnapaswa kutambua kwamba wao ni dhaifu na hivyo muwatendee kwa heshima; maana nao pia watapokea pamoja nanyi zawadi ya uzima anayowapeni Mungu. Hapo ndipo sala zenu hazitakataliwa.'),
(2020997,69,60,3,8,'Mwisho nasema hivi: mnapaswa kuwa na moyo mmoja, na fikira moja; mnapaswa kupendana kidugu, kuwa wapole na wanyenyekevu ninyi kwa ninyi.'),
(2020998,69,60,3,9,'Msiwalipe watu ovu kwa ovu, au tusi kwa tusi; bali watakieni baraka, maana ninyi mliitwa na Mungu mpate kupokea baraka.'),
(2020999,69,60,3,10,'Kama yasemavyo Maandiko Matakatifu: "Anayetaka kufurahia maisha, na kuona siku za fanaka, anapaswa kuacha kusema mabaya na kuacha kusema uongo.'),
(2021000,69,60,3,11,'Na ajiepushe na uovu, atende mema, atafute amani na kuizingatia.'),
(2021001,69,60,3,12,'Maana Bwana huwatazama kwa wema waadilifu na kuzisikiliza sala zao. Lakini huwapa kisogo watu watendao maovu."'),
(2021002,69,60,3,13,'Ni nani atakayeweza kuwadhuru ninyi kama mkizingatia kutenda mema?'),
(2021003,69,60,3,14,'Lakini, hata kama itawapasa kuteseka kwa sababu ya kutenda mema, basi, mna heri. Msimwogope mtu yeyote, wala msikubali kutiwa katika wasiwasi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021004,69,60,3,15,'Lakini mtukuzeni Kristo kama Bwana mioyoni mwenu. Muwe tayari kumjibu yeyote atakayewaulizeni juu ya matumaini yaliyo ndani yenu,'),
(2021005,69,60,3,16,'lakini fanyeni hivyo kwa upole na heshima. Muwe na dhamiri njema, kusudi mnapotukanwa, wale wanaosema ubaya juu ya mwenendo wenu mwema kama Wakristo, waone aibu.'),
(2021006,69,60,3,17,'Maana ni afadhali kuteseka kwa sababu ya kutenda mema, kama Mungu akipenda, kuliko kuteseka kwa sababu ya kutenda uovu.'),
(2021007,69,60,3,18,'Kwa maana Kristo mwenyewe alikufa kwa ajili ya dhambi zenu; alikufa mara moja tu na ikatosha, mtu mwema kwa ajili ya waovu, ili awapeleke ninyi kwa Mungu. Aliuawa kimwili lakini akafanywa hai kiroho;'),
(2021008,69,60,3,19,'na kwa maisha yake ya kiroho alikwenda kuwahubiria wale roho waliokuwa kifungoni.'),
(2021009,69,60,3,20,'Hao ndio wale waliokataa kumtii Mungu alipowangoja kwa saburi wakati Noa alipokuwa anatayarisha ile safina. Ndani ya chombo hicho ni watu wachache tu, yaani watu wanane, waliookolewa majini,'),
(2021010,69,60,3,21,'ambayo yalikuwa mfano wa ubatizo unaowaokoa ninyi sasa. Ubatizo si shauri la kuondoa uchafu mwilini, bali ni ahadi kwa Mungu inayofanyika katika dhamiri njema. Huwaokoeni kwa njia ya ufufuo wa Yesu Kristo,'),
(2021011,69,60,3,22,'ambaye alikwenda mbinguni na sasa amekaa upande wa kulia wa Mungu, anatawala juu ya malaika, wakuu na wenye enzi.'),
(2021012,69,60,4,1,'Maadamu Kristo aliteseka kimwili, nanyi pia mnapaswa kujiimarisha kwa nia hiyo yake; maana mtu akisha teseka kimwili hahusiki tena na dhambi.'),
(2021013,69,60,4,2,'Tangu sasa, basi, maisha yaliowabakia kuishi hapa duniani yanapaswa kuongozwa na matakwa ya Mungu, si na tamaa za kibinadamu.'),
(2021014,69,60,4,3,'Wakati uliopita mlikuwa na muda mrefu wa kufanya mambo wanayofanya watu wasiomjua Mungu. Mliishi maisha ya anasa, ubinafsi, ulevi, ugomvi, kunywa mno na ya ibada haramu za sanamu.'),
(2021015,69,60,4,4,'Sasa, watu hao wasiomjua Mungu wanashangaa wanapoona kwamba hamwandamani nao tena katika hali ya kuishi vibaya, na hivyo wanawatukaneni.'),
(2021016,69,60,4,5,'Lakini watapaswa kutoa hoja juu ya jambo hilo mbele yake Mungu aliye tayari kuwahukumu wazima na wafu!'),
(2021017,69,60,4,6,'Kwa sababu hiyo, hao waliokufa ambao walikuwa wamehukumiwa katika maisha yao ya kimwili kama anavyohukumiwa kila mmoja, walihubiriwa Habari Njema kusudi katika maisha yao ya kiroho waishi kama aishivyo Mungu.'),
(2021018,69,60,4,7,'Mwisho wa vitu vyote umekaribia. Kwa hiyo mnapaswa kuwa na utaratibu na nidhamu, ili mweze kusali.'),
(2021019,69,60,4,8,'Zaidi ya yote pendaneni kwa moyo wote, maana upendo hufunika dhambi nyingi.'),
(2021020,69,60,4,9,'Muwe na ukarimu ninyi kwa ninyi bila kunung`unika.'),
(2021021,69,60,4,10,'Kila mmoja anapaswa kutumia kipaji alichojaliwa na Mungu kwa faida ya wengine, kama vile uwakili mwema wa zawadi mbalimbali za Mungu.'),
(2021022,69,60,4,11,'Anayesema kitu, maneno yake na yawe kama maneno ya Mungu; anayetumika anapaswa kutumikia kwa nguvu anayojaliwa na Mungu, ili katika mambo yote, Mungu atukuzwe kwa njia ya Yesu Kristo, ambaye utukufu na nguvu ni vyake milele na milele! Amina.'),
(2021023,69,60,4,12,'Wapenzi wangu, msishangae kuhusu majaribio makali mnayopata kana kwamba mnapatwa na kitu kisicho cha kawaida.'),
(2021024,69,60,4,13,'Ila furahini kwamba mnashiriki mateso ya Kristo ili mweze kuwa na furaha tele wakati utukufu wake utakapofunuliwa.'),
(2021025,69,60,4,14,'Heri yenu ikiwa mnatukanwa kwa sababu ya jina la Kristo; jambo hilo lamaanisha kwamba Roho mtukufu, yaani Roho wa Mungu, anakaa juu yetu.'),
(2021026,69,60,4,15,'Asiwepo mtu yeyote miongoni mwenu ambaye anapaswa kuteseka kwa sababu ni muuaji, mwizi, mhalifu au mwovu.'),
(2021027,69,60,4,16,'Lakini kama mtu akiteseka kwa sababu ni Mkristo, basi asione aibu, bali amtukuze Mungu, kwa sababu mtu huyo anaitwa kwa jina la Kristo.'),
(2021028,69,60,4,17,'Wakati wa hukumu umefika, na hukumu hiyo inaanza na watu wake Mungu mwenyewe. Ikiwa hukumu hiyo inaanzia kwetu sisi, basi mwisho wake utakuwa namna gani kwa wale wasioamini Habari Njema ya Mungu?'),
(2021029,69,60,4,18,'Kama yasemavyo Maandiko Matakatifu: "Ni vigumu kwa watu waadilifu kuokolewa; itakuwaje basi kwa wasiomcha Mungu na wenye dhambi?"'),
(2021030,69,60,4,19,'Kwa hiyo, wale wanaoteseka kufuatana na matakwa ya Mungu, wanapaswa, kwa matendo yao mema, kujiweka chini ya Muumba wao ambaye ni wa kuaminika kabisa.'),
(2021031,69,60,5,1,'wazee! Mimi niliye mzee ninalo ombi moja kwenu wazee wenzangu. Mimi mwenyewe nilishuhudia kwa macho yangu mateso ya Kristo na natumaini kuushiriki ule utukufu utakaofunuliwa. Mimi nawaombeni'),
(2021032,69,60,5,2,'mlichunge lile kundi la Mungu mlilokabidhiwa, mlitunze si kwa kulazimika, bali kwa hiari kama atakavyo Mungu. Fanyeni kazi hiyo si kwa tamaa ya fedha, bali kwa moyo wenu wote.'),
(2021033,69,60,5,3,'Msiwatawale kwa mabavu hao waliowekwa chini ya ulinzi wenu, bali muwe mfano kwa hilo kundi.'),
(2021034,69,60,5,4,'Na wakati Mchungaji Mkuu atakapotokea, ninyi mtapokea taji ya utukufu isiyofifia.'),
(2021035,69,60,5,5,'Kadhalika nanyi vijana mnapaswa kujiweka chini ya mamlaka ya wazee. Ninyi nyote mnapaswa kuwa na unyenyekevu mpate kutumikiana; maana Maandiko Matakatifu yasema: "Mungu huwapinga wenye majivuno, lakini huwajalia neema wanyenyekevu."'),
(2021036,69,60,5,6,'Basi, nyenyekeeni chini ya mkono wa enzi wa Mungu, ili awainue wakati ufaao.'),
(2021037,69,60,5,7,'Mwekeeni matatizo yenu yote, maana yeye anawatunzeni.'),
(2021038,69,60,5,8,'Muwe macho; kesheni! Maana adui yenu, Ibilisi, huzungukazunguka kama simba angurumaye akitafuta mawindo.'),
(2021039,69,60,5,9,'Muwe imara katika imani na kumpinga, mkijua kwamba ndugu zenu pote duniani wanapatwa na mateso hayohayo.'),
(2021040,69,60,5,10,'Lakini mkisha teseka muda mfupi, Mungu aliye asili ya neema yote na ambaye anawaiteni muushiriki utukufu wake wa milele katika kuungana na Kristo, yeye mwenyewe atawakamilisheni na kuwapeni uthabiti, nguvu na msingi imara.'),
(2021041,69,60,5,11,'Kwake uwe uwezo milele! Amina.'),
(2021042,69,60,5,12,'Nimewaandikieni barua hii fupi kwa msaada wa Silwano, ndugu ambaye namjua na kumwamini. Nataka kuwapeni moyo na kushuhudia kwamba jambo hili ni neema ya Mungu kweli. Kaeni imara katika neema hiyo.'),
(2021043,69,60,5,13,'Jumuiya ya wenzenu walioteuliwa na Mungu hapa Babuloni wanawasalimuni. Vilevile mwanangu Marko anawasalimuni.'),
(2021044,69,60,5,14,'Salimianeni kwa ishara ya upendo wa Kikristo. Nawatakieni amani ninyi mlio wake Kristo.'),
(2021045,69,61,1,1,'Mimi Simoni Petro, mtumishi na mtume wa Yesu Kristo, nawaandikia ninyi ambao, kwa wema wake Mungu wetu, na Mwokozi Yesu Kristo, mmejaliwa imani ileile ya thamani kuu tuliyojaliwa sisi.'),
(2021046,69,61,1,2,'Nawatakieni neema na amani tele katika kumjua Mungu na Yesu Bwana wetu.'),
(2021047,69,61,1,3,'Kwa uwezo wake wa kimungu, Mungu ametujalia mambo yote tunayohitaji, ili tuishi maisha ya kumcha Mungu kwa kumjua yeye aliyetuita tuushiriki utukufu na wema wake yeye mwenyewe.'),
(2021048,69,61,1,4,'Kwa namna hiyo ametujalia zawadi kuu na za thamani ambazo alituahidia, ili kwa zawadi hizo mpate kuziepa kabisa tamaa mbaya zilizomo duniani, na mpate kuishiriki hali yake ya kimungu.'),
(2021049,69,61,1,5,'Kwa sababu hiyo, fanyeni bidii ya kuongeza fadhila katika imani yenu: ongezeni elimu katika fadhila yenu,'),
(2021050,69,61,1,6,'kuwa na kiasi katika elimu yenu, uvumilivu katika kuwa na kiasi, uchaji wa Mungu katika uvumilivu wenu,'),
(2021051,69,61,1,7,'udugu katika uchaji wenu, na mapendo katika udugu wenu.'),
(2021052,69,61,1,8,'Mkiwa na sifa hizo zote kwa wingi, zitawawezesheni kuwa watendaji na kupata faida katika kumjua Bwana wetu Yesu Kristo.'),
(2021053,69,61,1,9,'Lakini mtu asiye na sifa hizo ni kipofu, hawezi kuona na amesahau kwamba alikwisha takaswa dhambi zake za zamani.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021054,69,61,1,10,'Kwa hiyo basi, ndugu zangu, fanyeni bidii zaidi kuufanya huo wito wenu mlioitiwa na Mungu uwe jambo la kudumu katika maisha yenu; kama mkiishi namna hiyo hamtaanguka kamwe.'),
(2021055,69,61,1,11,'Kwa namna hiyo mtafaulu kupewa haki kamili ya kuingia katika Utawala wa milele wa Bwana na Mwokozi wetu Yesu Kristo.'),
(2021056,69,61,1,12,'Kwa hiyo nitaendelea kuwakumbusheni daima mambo haya, ingawa mmekwisha yafahamu, na mko imara katika ukweli mlioupokea.'),
(2021057,69,61,1,13,'Nadhani ni jambo jema kwangu, muda wote niishio hapa duniani, kuwapeni moyo na kuwakumbusheni juu ya mambo haya.'),
(2021058,69,61,1,14,'Najua kwamba karibu nitauweka kando mwili huu wenye kufa, kama Bwana alivyoniambia waziwazi.'),
(2021059,69,61,1,15,'Basi, nitajitahidi kuwapatieni njia ya kuyakumbuka mambo haya kila wakati, baada ya kufariki kwangu.'),
(2021060,69,61,1,16,'Wakati tulipowafundisheni juu ya ukuu wa kuja kwake Bwana wetu Yesu Kristo, hatukutegemea hadithi tupu zisizo na msingi. Sisi tuliuona utukufu wake kwa macho yetu wenyewe.'),
(2021061,69,61,1,17,'Sisi tulikuwapo wakati alipopewa heshima na kutukuzwa na Mungu Baba, wakati sauti ilipomjia kutoka kwake yeye aliye Utukufu Mkuu, ikisema: "Huyu ni Mwanangu mpenzi, nimependezwa naye."'),
(2021062,69,61,1,18,'Tena, sisi wenyewe tulisikia sauti hiyo kutoka mbinguni wakati tulipokuwa pamoja naye juu ya ule mlima mtakatifu.'),
(2021063,69,61,1,19,'Tena, ujumbe wa manabii watuthibitishia jambo hilo; nanyi mwafanya vema kama mkiuzingatia, maana ni kama taa inayoangaza mahali penye giza mpaka Siku ile itakapopambazuka na mwanga wa nyota ya asubuhi utakapong`ara mioyoni mwenu.'),
(2021064,69,61,1,20,'Zaidi ya hayo, lakini, kumbukeni kwamba hakuna mtu yeyote awezaye kufafanua mwenyewe unabii ulio katika Maandiko Matakatifu.'),
(2021065,69,61,1,21,'Maana hakuna ujumbe wa kinabii unaotokana na matakwa ya binadamu, bali watu walinena ujumbe wa Mungu wakiongozwa na Roho Mtakatifu.'),
(2021066,69,61,2,1,'Palitokea manabii wa uongo kati ya watu, na vivyo hivyo walimu wa uongo watatokea kati yenu. Watu hao wataingiza mafundisho maharibifu na kumkana Bwana aliyewakomboa, na kwa njia hiyo watasababisha ghafla maangamizi yao wenyewe.'),
(2021067,69,61,2,2,'Tena watu wengi watazifuata hizo njia zao mbaya, kwa sababu yao, wengine wataipuuza Njia ya ukweli.'),
(2021068,69,61,2,3,'Kwa tamaa yao mbaya watajipatia faida kwa kuwaambieni hadithi za uongo. Lakini kwa muda mrefu sasa Hakimu wao yu tayari, na Mwangamizi wao yu macho!'),
(2021069,69,61,2,4,'Malaika walipotenda dhambi, Mungu hakuwahurumia, bali aliwatupa katika moto wa Jehanamu ambako wamefungwa wakingojea Siku ile ya Hukumu.'),
(2021070,69,61,2,5,'Mungu hakuihurumia dunia ya hapo kale, bali alileta gharika kuu juu ya nchi ile ya watu wasiomcha Mungu; lakini Noa ambaye alihubiri uadilifu, Mungu alimwokoa pamoja na watu wengine saba.'),
(2021071,69,61,2,6,'Mungu aliadhibu miji ya Sodoma na Gomora, akaiteketeza kwa moto, akaifanya iwe mfano wa mambo yatakayowapata watu wasiomcha Mungu.'),
(2021072,69,61,2,7,'Alimwokoa Loti, mtu mwema, ambaye alisikitishwa sana na mwenendo mbaya wa watu hao waasi.'),
(2021073,69,61,2,8,'Loti aliishi miongoni mwa watu hao, na kwa siku nyingi moyo wake ulikuwa katika wasiwasi mkuu aliposikia matendo yao maovu.'),
(2021074,69,61,2,9,'Kwa hiyo, basi, Bwana anajua jinsi ya kuwaokoa katika majaribu watu wanaomcha Mungu, na jinsi ya kuwaweka waovu katika adhabu hadi Siku ile ya hukumu,'),
(2021075,69,61,2,10,'hasa wale wanaofuata tamaa mbaya za mwili na kupuuza mamlaka. Watu hao ni washupavu na wenye majivuno, huvitukana na hawaviheshimu viumbe vitukufu vya juu.'),
(2021076,69,61,2,11,'Lakini malaika, ambao wana uwezo na nguvu zaidi kuliko hao walimu wa uongo, hawawashtaki na kuwatukana hao mbele ya Bwana.'),
(2021077,69,61,2,12,'Watu hao ambao hutukana chochote kile wasichoelewa, ni sawa na wanyama wasio na akili, ambao huzaliwa na baadaye hukamatwa na kuchinjwa! Wataangamizwa kutokana na uharibifu wao wenyewe,'),
(2021078,69,61,2,13,'na watalipwa mateso kwa mateso ambayo wameyasababisha. Furaha yao ni kufanya, tena mchana kabisa, chochote kinachotosheleza anasa zao za mwili. Hao ni fedheha na aibu tupu kwa jumuiya yenu wakati wanapojiunga nanyi katika karamu zenu, bali wakifurahia njia zao za udanganyifu.'),
(2021079,69,61,2,14,'Macho yao yamejaa uzinzi na uwezo wao wa kutenda dhambi hauna kikomo. Huwaongoza watu walio dhaifu mpaka mitegoni. Mioyo yao imezoea kuwa na tamaa ya mali. Wapo chini ya laana ya Mungu!'),
(2021080,69,61,2,15,'Wameiacha njia iliyonyoka, wakapotoka na kuifuata njia aliyofuata Balaamu, mwana wa Beori, ambaye alipendelea kupata faida kwa kufanya udanganyifu,'),
(2021081,69,61,2,16,'akakaripiwa kwa ajili ya uovu wake. Punda ambaye hasemi alinena kwa sauti ya binadamu, akaukomesha wazimu wa huyo nabii.'),
(2021082,69,61,2,17,'Watu hao ni kama chemchemi zilizokauka, kama mawingu yanayopeperushwa na tufani; makao yao waliyowekewa ni mahali pa giza kuu.'),
(2021083,69,61,2,18,'Husema maneno ya majivuno na yasiyo na maana, na kutumia tamaa zao mbaya za kimwili kuwatega wale ambao wamejitenga hivi karibuni na watu waishio katika udanganyifu.'),
(2021084,69,61,2,19,'Huwaahidi watu wengine eti watakuwa huru, kumbe wao wenyewe ni watumwa wa upotovu--maana mtu ni mtumwa wa chochote kile kinachomtawala.'),
(2021085,69,61,2,20,'Watu waliokwisha ponyoka katika upotovu wa ulimwengu kwa kupata kumjua Bwana na Mwokozi wetu Yesu Kristo, kisha wakakubali kunaswa na kutawaliwa tena na upotovu huo, hali yao itakuwa mbaya zaidi kuliko awali.'),
(2021086,69,61,2,21,'Ingalikuwa afadhali kwao kama wasingalijua kamwe njia hiyo ya uadilifu kuliko kujua na kisha kuiacha na kupoteza amri takatifu waliyopokea.'),
(2021087,69,61,2,22,'Ipo mithali isemayo: "Mbwa huyarudia matapishi yake mwenyewe," na nyingine isemayo: "Nguruwe aliyekwisha oshwa hugaagaa tena katika matope!" Ndivyo ilivyo kwao sasa.'),
(2021088,69,61,3,1,'Wapenzi wangu, hii ni barua ya pili ninayowaandikia. Katika barua hizo mbili nimejaribu kufufua fikira safi akilini mwenu kwa kuwakumbusheni mambo haya.'),
(2021089,69,61,3,2,'Napenda mkumbuke maneno yaliyosemwa na manabii watakatifu, na ile amri ya Bwana na Mwokozi mliyopewa na mitume wenu.'),
(2021090,69,61,3,3,'Awali ya yote jueni kwamba siku za mwisho watakuja watu ambao mienendo yao inatawaliwa na tamaa zao mbaya. Watawadhihaki ninyi'),
(2021091,69,61,3,4,'na kusema: "Aliahidi kwamba atakuja! Je, sasa yuko wapi? Mambo ni yaleyale tangu babu zetu walipokufa; hali ya vitu ni ileile kama ilivyokuwa mwanzo wa ulimwengu!"'),
(2021092,69,61,3,5,'Watu hao, kwa makusudi, husahau kwamba zamani Mungu alinena, nazo mbingu na nchi zikaumbwa. Dunia iliumbwa kutoka katika maji na kwa maji;'),
(2021093,69,61,3,6,'na kwa maji hayo, yaani yale maji ya gharika kuu, dunia ya wakati ule iliangamizwa.'),
(2021094,69,61,3,7,'Lakini mbingu na nchi za sasa zahifadhiwa kwa neno la Mungu kwa ajili ya kuharibiwa kwa moto. Zimewekwa kwa ajili ya Siku ile ambapo watu wasiomcha Mungu watahukumiwa na kuangamizwa.'),
(2021095,69,61,3,8,'Lakini, wapenzi wangu, msisahau kitu kimoja! Mbele ya Bwana, hakuna tofauti kati ya siku moja na miaka elfu; kwake yote ni mamoja.'),
(2021096,69,61,3,9,'Bwana hakawii kutimiza yale aliyoahidi kama watu wengine wanavyofikiri kuwa atakawia. Yeye ana saburi kwa ajili yenu, maana hapendi hata mmoja wenu apotee, bali huwavuta wote wapate kutubu.'),
(2021097,69,61,3,10,'Siku ya Bwana itakuja kama mwizi. Siku hiyo, mbingu zitatoweka kwa kishindo kikuu; vitu vyake vya asili vitateketezwa kwa moto, nayo dunia itatoweka pamoja na kila kitu kilichomo ndani yake.'),
(2021098,69,61,3,11,'Maadamu kila kitu kitaharibiwa namna hiyo, je, ninyi mnapaswa kuwa watu wa namna gani? Mnapaswa kuishi kitakatifu na kumcha Mungu,'),
(2021099,69,61,3,12,'mkiingojea Siku ile ya Mungu na kuifanya ije upesi--Siku ambayo mbingu zitateketezwa kwa moto na kuharibiwa, na vitu vyake vya asili vitayeyushwa kwa joto.'),
(2021100,69,61,3,13,'Lakini sisi, kufuatana na ahadi yake, twangojea mbingu mpya na dunia mpya ambayo imejaa uadilifu.'),
(2021101,69,61,3,14,'Kwa hiyo wapenzi wangu, mkiwa mnangojea Siku ile, fanyeni bidii kuwa safi kabisa bila hatia mbele ya Mungu, na kuwa na amani naye.'),
(2021102,69,61,3,15,'Mnapaswa kuuona uvumilivu wa Bwana kuwa ni nafasi anayowapeni mpate kuokolewa, kama Paulo ndugu yetu mpenzi alivyowaandikia akitumia hekima aliyopewa na Mungu.'),
(2021103,69,61,3,16,'Hayo ndiyo asemayo katika barua zake zote anapozungumzia suala hilo. Yapo mambo kadhaa katika barua zake yaliyo magumu kuyaelewa, mambo ambayo watu wajinga, wasio na msimamo, huyapotosha kama wanavyopotosha sehemu nyingine za Maandiko Matakatifu. Hivyo wanasababisha maangamizi yao wenyewe.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021104,69,61,3,17,'Lakini ninyi, wapenzi wangu, mmekwisha jua jambo hili. Basi, muwe na tahadhari msije mkapotoshwa na makosa ya waasi, mkaanguka kutoka katika msimamo wenu imara.'),
(2021105,69,61,3,18,'Lakini endeleeni kukua katika neema na katika kumjua Bwana wetu na Mwokozi Yesu Kristo. Utukufu uwe kwake, sasa na hata milele! Amina.'),
(2021106,69,62,1,1,'Habari hii ya yahusu Neno la uzima lililokuwako tangu mwanzo. Sisi tumepata kulisikia na kuliona kwa macho yetu wenyewe; tulilitazama na kulishika kwa mikono yetu wenyewe.'),
(2021107,69,62,1,2,'Uzima huo ulipotokea sisi tuliuona na sasa tunasema habari zake na kuwaambieni juu ya uzima huo wa milele uliokuwa kwa Baba na uliodhihirishwa kwetu.'),
(2021108,69,62,1,3,'Tulichokiona na kukisikia ndicho tunachowatangazieni ninyi pia ili nanyi mpate kushirikiana nasi katika umoja tulio nao na Baba na Mwanae Yesu Kristo.'),
(2021109,69,62,1,4,'Tunawaandikia ninyi mambo haya kusudi furaha yetu ikamilike.'),
(2021110,69,62,1,5,'Basi, habari tuliyoisikia kwake Yesu na tunayowahubirieni ndiyo hii: Mungu ni mwanga na hamna giza lolote ndani yake.'),
(2021111,69,62,1,6,'Tukisema kwamba tuna umoja naye,na papo hapo twaishi gizani, tutakuwa tumesema uongo kwa maneno na matendo.'),
(2021112,69,62,1,7,'Lakini tukiishi katika mwanga, kama naye alivyo katika mwanga, basi tutakuwa na umoja sisi kwa sisi, na damu yake Yesu Kristo, Mwanae, inatutakasa dhambi zote.'),
(2021113,69,62,1,8,'Tukisema kwamba hatuna dhambi, tunajidanganya wenyewe na ukweli haumo ndani yetu.'),
(2021114,69,62,1,9,'Lakini tukiziungama dhambi zetu, basi Mungu ni mwaminifu na mwadilifu, naye atatusamehe dhambi zetu na kututakasa na uovu wote.'),
(2021115,69,62,1,10,'Tukisema kwamba hatujatenda dhambi, tutakuwa tumemfanya Mungu mwongo, na neno lake halimo ndani yetu.'),
(2021116,69,62,2,1,'Watoto wangu, ninawaandikieni mambo haya, kusudi msitende dhambi. Lakini, ikijatokea mtu akatenda dhambi, tunaye mmoja ambaye hutuombea kwa Baba, ndiye Yesu Kristo aliye mwadilifu kabisa.'),
(2021117,69,62,2,2,'Kristo ndiye sadaka iondoayo dhambi zetu; wala si dhambi zetu sisi tu, bali pia dhambi za ulimwengu wote.'),
(2021118,69,62,2,3,'Tukizitii amri za Mungu, basi, tunaweza kuwa na hakika kwamba tunamjua.'),
(2021119,69,62,2,4,'Mtu akisema kwamba anamjua, lakini hazitii amri zake, basi mtu huyo ni mwongo, na ukweli haumo ndani yake.'),
(2021120,69,62,2,5,'Lakini mtu yeyote anayeshika neno la Mungu, huyo ndiye aliye na upendo kamili wa Mungu ndani yake. Hivi ndivyo tunavyoweza kuwa na hakika kwamba tunaungana naye:'),
(2021121,69,62,2,6,'mtu yeyote anayesema kwamba ameungana na Mungu, anapaswa kuishi kama alivyoishi Yesu Kristo.'),
(2021122,69,62,2,7,'Wapenzi wangu, amri hii ninayowaandikieni si amri mpya; ni amri ileile ya zamani mliyokuwa nayo tangu mwanzo. Amri hiyo ya zamani ni ule ujumbe mliousikia.'),
(2021123,69,62,2,8,'Hata hivyo, amri hii ninayowaandikieni ni amri mpya, na ukweli wake unaonekana ndani ya Kristo na ndani yenu pia. Maana giza linatoweka, na mwanga wa ukweli umekwisha anza kuangaza.'),
(2021124,69,62,2,9,'Yeyote asemaye kwamba yumo katika mwanga, lakini anamchukia ndugu yake, mtu huyo bado yumo gizani.'),
(2021125,69,62,2,10,'Yeyote ampendaye ndugu yake, yuko katika mwanga, na hamna chochote ndani yake kiwezacho kumkwaza mtu mwingine.'),
(2021126,69,62,2,11,'Lakini anayemchukia ndugu yake, yumo gizani; anatembea gizani, na hajui anakokwenda, maana giza limempofusha.'),
(2021127,69,62,2,12,'Ninawaandikieni ninyi watoto, kwa kuwa dhambi zenu zimeondolewa kwa jina la Kristo.'),
(2021128,69,62,2,13,'Nawaandikieni ninyi kina baba kwani mnamjua yeye ambaye amekuwako tangu mwanzo, Nawaandikieni ninyi vijana kwa sababu mmemshinda yule Mwovu.'),
(2021129,69,62,2,14,'Nawaandikieni ninyi watoto, kwa sababu mnamjua Baba. Nawaandikieni ninyi kina baba, kwa kuwa mnamjua yeye ambaye amekuwako tangu mwanzo. Nawaandikieni ninyi vijana kwa sababu mna nguvu; neno la Mungu limo ndani yenu na mmemshinda yule Mwovu.'),
(2021130,69,62,2,15,'Msiupende ulimwengu, wala chochote kilicho cha ulimwengu. Mtu anayeupenda ulimwengu, upendo wa Baba hauwezi kuwamo ndani yake.'),
(2021131,69,62,2,16,'Vitu vyote vya ulimwengu-tamaa mbaya za mwili, vitu wanavyoviona watu na kuvitamani, majivuno yasababishwayo na mali-vyote hivyo havitoki kwa Baba, bali vyatoka kwa ulimwengu.'),
(2021132,69,62,2,17,'Ulimwengu pamoja na vitu vyake vyote vyenye kutamanika unapita; lakini mtu atendaye atakalo Mungu, anaishi milele.'),
(2021133,69,62,2,18,'Watoto, mwisho u karibu! Mlikwisha sikia kwamba adui wa Kristo anakuja, na sasa adui wengi wa Kristo wamekwisha fika, na hivyo twajua kwamba mwisho u karibu.'),
(2021134,69,62,2,19,'Watu hao wametokea kati yetu lakini hawakuwa kweli wa kwetu na ndiyo maana walituacha; Kama wangalikuwa wa kwetu, wangalibaki nasi. Lakini waliondoka, wakaenda zao, kusudi ionekane wazi kwamba hawakuwa kamwe wa kwetu.'),
(2021135,69,62,2,20,'Ninyi, lakini, mlipata kumiminiwa Roho Mtakatifu na Kristo, na hivyo mnaujua ukweli.'),
(2021136,69,62,2,21,'Basi, nawaandikieni, si kwa kuwa hamuujui ukweli, bali kwa sababu mnaujua; na pia mnajua kwamba uongo wowote haupatikani katika ukweli.'),
(2021137,69,62,2,22,'Mwongo ni nani? Ni yule anayekana kwamba Yesu ni Masiha. Mtu wa namna hiyo ni adui wa Kristo--anamkana Baba na Mwana.'),
(2021138,69,62,2,23,'Maana yeyote anayemkana Mwana, anamkana pia Baba; na yeyote anayemkubali Mwana, anampata Baba pia.'),
(2021139,69,62,2,24,'Basi, ujumbe ule mliousikia tangu mwanzo na ukae mioyoni mwenu. Kama ujumbe huo mliousikia tangu mwanzo ukikaa ndani yenu, basi, mtaishi daima katika umoja na Mwana na Baba.'),
(2021140,69,62,2,25,'Na ahadi aliyotuahidia sisi ndiyo hii: uzima wa milele.'),
(2021141,69,62,2,26,'Nimewaandikieni mambo haya kuhusu wale wanaotaka kuwapotosha ninyi.'),
(2021142,69,62,2,27,'Lakini, kwa upande wenu ninyi, Kristo aliwamiminieni Roho wake. Na kama akiendelea kukaa ndani yenu, hamhitaji kufundishwa na mtu yeyote. Maana Roho wake anawafundisheni kila kitu na mafundisho yake ni ya kweli, si ya uongo. Basi shikeni mafundisho ya huyo Roho na kubaki katika muungano na Kristo.'),
(2021143,69,62,2,28,'Naam, watoto, kaeni ndani yake kusudi wakati atakapotokea tuwe hodari bila kuwa na sababu ya kujificha kwa aibu Siku ya kuja kwake.'),
(2021144,69,62,2,29,'Mnajua kwamba Kristo ni mwadilifu kabisa; basi, mnapaswa kujua pia kwamba kila mtu atendaye mambo adili ni mtoto wa Mungu.'),
(2021145,69,62,3,1,'Oneni basi, jinsi Baba alivyotupenda mno hata tunaitwa watoto wa Mungu! Na kweli, ndivyo tulivyo. Ndiyo maana ulimwengu haututambui sisi, kwani haumjui Mungu.'),
(2021146,69,62,3,2,'Wapenzi wangu, sisi ni watoto wa Mungu sasa, lakini bado haijaonekana wazi jinsi tutakavyokuwa. Lakini tunajua kwamba wakati Kristo atakapotokea, tutafanana naye kwani tutamwona vile alivyo.'),
(2021147,69,62,3,3,'Basi, kila mtu aliye na tumaini hili katika Kristo, hujiweka safi kama vile Kristo alivyo safi kabisa.'),
(2021148,69,62,3,4,'Kila mtu atendaye dhambi anavunja sheria ya Mungu, maana dhambi ni uvunjaji wa sheria.'),
(2021149,69,62,3,5,'Mnajua kwamba Kristo alikuja kuziondoa dhambi zetu, na kwamba kwake hamna dhambi yoyote.'),
(2021150,69,62,3,6,'Basi, kila aishiye katika muungano na Kristo hatendi dhambi; lakini kila mtu atendaye dhambi hakupata kamwe kumwona, wala kumjua Kristo.'),
(2021151,69,62,3,7,'Basi, watoto wangu, msikubali kupotoshwa na mtu yeyote. Mtu atendaye matendo maadilifu ni mwadilifu kama vile Kristo alivyo mwadilifu kabisa.'),
(2021152,69,62,3,8,'Lakini atendaye dhambi ni wa Ibilisi, maana Ibilisi ametenda dhambi tangu mwanzo. Lakini Mwana wa Mungu alikuja duniani kuiharibu kazi ya Ibilisi.'),
(2021153,69,62,3,9,'Kila aliye mtoto wa Mungu hatendi dhambi, maana anayo hali ya kimungu ndani yake; hawezi kutenda dhambi kwa sababu yeye ni mtoto wa Mungu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021154,69,62,3,10,'Lakini yeyote asiyetenda mambo maadilifu, au asiyempenda ndugu yake, huyo si mtoto wa Mungu. Hiyo ndiyo tofauti iliyoko kati ya watoto wa Mungu na watoto wa Ibilisi.'),
(2021155,69,62,3,11,'Na, ujumbe mliousikia tangu mwanzo ndio huu: Tunapaswa kupendana!'),
(2021156,69,62,3,12,'Tusiwe kama Kaini ambaye, kwa kuongozwa na yule Mwovu, alimuua ndugu yake. Na, kwa nini alimuua? Kwa sababu matendo yake yalikuwa maovu, lakini yale ya ndugu yake yalikuwa mema!'),
(2021157,69,62,3,13,'Basi, ndugu zangu, msishangae kama ulimwengu unawachukia ninyi.'),
(2021158,69,62,3,14,'Sisi tunajua kwamba tumekwisha pita kutoka katika kifo na kuingia katika uzima kwa sababu tunawapenda ndugu zetu. Mtu asiye na upendo hubaki katika kifo.'),
(2021159,69,62,3,15,'Kila anayemchukia ndugu yake ni muuaji; nanyi mnajua kwamba muuaji yeyote yule hana uzima wa milele ndani yake.'),
(2021160,69,62,3,16,'Sisi tumepata kujua upendo ni nini, kwani Kristo aliyatoa maisha yake kwa ajili yetu. Nasi vilevile tunapaswa kuyatoa maisha yetu kwa ajili ya ndugu zetu.'),
(2021161,69,62,3,17,'Basi, mtu akiwa na mali za hapa duniani, halafu akamwona ndugu yake ana shida, lakini akawa na moyo mgumu bila kumwonea huruma, anawezaje kusema kwamba anampenda Mungu?'),
(2021162,69,62,3,18,'Watoto wangu, upendo wetu usiwe maneno matupu, bali uwe upendo wa kweli na wa vitendo.'),
(2021163,69,62,3,19,'Hivyo ndivyo tuwezavyo kuwa na hakika kwamba sisi ni watu wa ukweli; na hatutakuwa na wasiwasi mbele ya Mungu.'),
(2021164,69,62,3,20,'Kwa maana, hata kama dhamiri yetu yatuhukumu, twajua kwamba Mungu ni mkuu zaidi kuliko dhamiri, na kwamba yeye ajua kila kitu.'),
(2021165,69,62,3,21,'Wapenzi wangu, kama dhamiri yetu haina lawama juu yetu, basi, twaweza kuwa na uthabiti mbele ya Mungu,'),
(2021166,69,62,3,22,'na twaweza kupokea kwake chochote tunachoomba, maana tunazitii amri zake na kufanya yale yanayompendeza.'),
(2021167,69,62,3,23,'Na, amri yake ndiyo hii: Kumwamini Mwanae Kristo, na kupendana kama alivyotuamuru.'),
(2021168,69,62,3,24,'Anayezitii amri za Mungu anaishi katika muungano na Mungu na Mungu anaishi katika muungano naye. Kwa njia ya Roho ambaye Mungu ametujalia, sisi twajua kwamba Mungu anaishi katika muungano nasi.'),
(2021169,69,62,4,1,'Wapenzi wangu, msimsadiki kila mtu asemaye kwamba ana Roho wa Mungu, bali chunguzeni kwa makini kama huyo mtu anaongozwa na Roho wa Mungu au la, Maana manabii wengi wa uongo wamezuka ulimwenguni.'),
(2021170,69,62,4,2,'Hii ndiyo njia ya kujua kama mtu anaongozwa na Roho wa Mungu: Kila anayekiri kwamba Kristo alikuja, akawa binadamu, mtu huyo anaye Roho wa Mungu.'),
(2021171,69,62,4,3,'Lakini mtu yeyote asiyemkiri Kristo hivyo, hana huyo Roho atokaye kwa Mungu. Mtu huyo ana roho ambaye ni wa Adui wa Kristo; nanyi mlikwisha sikia kwamba anakuja, na sasa tayari amekwisha wasili ulimwenguni!'),
(2021172,69,62,4,4,'Lakini ninyi, watoto, ni wake Mungu na mmekwisha washinda hao manabii wa uongo; maana Roho aliye ndani yenu ana nguvu zaidi kuliko roho aliye ndani ya hao walio wa ulimwengu.'),
(2021173,69,62,4,5,'Wao husema mambo ya ulimwengu, nao ulimwengu huwasikiliza kwani wao ni wa ulimwengu.'),
(2021174,69,62,4,6,'Lakini sisi ni wake Mungu. Mtu anayemjua Mungu hutusikiliza, mtu asiye wa Mungu hatusikilizi. Basi, kwa njia hiyo tunaweza kutambua tofauti kati ya Roho wa ukweli na roho wa uongo.'),
(2021175,69,62,4,7,'Wapenzi wangu, tupendane, maana upendo hutoka kwa Mungu. Kila mtu aliye na upendo ni mtoto wa Mungu, na anamjua Mungu.'),
(2021176,69,62,4,8,'Mtu asiye na upendo hamjui Mungu, maana Mungu ni upendo.'),
(2021177,69,62,4,9,'Na Mungu alionyesha upendo wake kwetu kwa kumtuma Mwanae wa pekee ulimwenguni, ili tuwe na uzima kwa njia yake.'),
(2021178,69,62,4,10,'Hivi ndivyo upendo ulivyo: si kwamba sisi tulikuwa tumempenda Mungu kwanza, bali kwamba yeye alitupenda hata akamtuma Mwanae awe sadaka ya kutuondolea dhambi zetu.'),
(2021179,69,62,4,11,'Wapenzi wangu, ikiwa Mungu alitupenda hivyo, basi, nasi tunapaswa kupendana.'),
(2021180,69,62,4,12,'Hakuna mtu aliyekwisha mwona Mungu kamwe; lakini kama tukipendana Mungu anaishi katika muungano nasi, na upendo wake unakamilika ndani yetu.'),
(2021181,69,62,4,13,'Tunajua kwamba tunaishi katika umoja na Mungu, naye Mungu anaishi katika umoja nasi, kwani yeye ametupa Roho wake.'),
(2021182,69,62,4,14,'Sisi tumeona na kuwaambia wengine kwamba Baba alimtuma Mwanae awe Mwokozi wa ulimwengu.'),
(2021183,69,62,4,15,'Kila mtu anayekiri kwamba Yesu ni Mwana wa Mungu, Mungu anaishi katika muungano na mtu huyo, naye anaishi katika muungano na Mungu.'),
(2021184,69,62,4,16,'Basi, sisi tunajua na tunaamini upendo alio nao Mungu kwetu sisi. Mungu ni upendo, na kila mtu aishiye katika upendo, anaishi katika muungano na Mungu, na Mungu anaishi katika muungano naye.'),
(2021185,69,62,4,17,'Upendo umekamilika ndani yetu kusudi tuweze kuwa na ujasiri Siku ile ya Hukumu; kwani maisha yetu hapa duniani ni kama yale ya Kristo.'),
(2021186,69,62,4,18,'Palipo na upendo hapana uoga; naam, upendo kamili hufukuza uoga wote. Basi, mtu mwenye uoga hajakamilika bado katika upendo, kwani uoga huhusikana na adhabu.'),
(2021187,69,62,4,19,'Sisi tuna upendo kwa sababu Mungu alitupenda kwanza.'),
(2021188,69,62,4,20,'Mtu akisema kwamba anampenda Mungu, hali anamchukia ndugu yake, huyo ni mwongo. Maana mtu asiyempenda ndugu yake ambaye anamwona, hawezi kumpenda Mungu ambaye hamwoni.'),
(2021189,69,62,4,21,'Basi, hii ndiyo amri aliyotupa Kristo: Anayempenda Mungu anapaswa pia kumpenda ndugu yake.'),
(2021190,69,62,5,1,'Kila mtu anayeamini kwamba Yesu ni Kristo, huyo ni mtoto wa Mungu; na, anayempenda mzazi humpenda pia mtoto wa huyo mzazi.'),
(2021191,69,62,5,2,'Hivi ndivyo tunavyojua kwamba tunawapenda watoto wa Mungu: Kwa kumpenda Mungu na kuzitii amri zake;'),
(2021192,69,62,5,3,'maana kumpenda Mungu ni kuzitii amri zake. Na, amri zake si ngumu,'),
(2021193,69,62,5,4,'maana kila aliye mtoto wa Mungu anaweza kuushinda ulimwengu. Hivi ndivyo tunavyoushinda ulimwengu: kwa imani yetu.'),
(2021194,69,62,5,5,'Nani, basi, awezaye kuushinda ulimwengu? Ni yule anayeamini kwamba Yesu ni Mwana wa Mungu.'),
(2021195,69,62,5,6,'Yesu Kristo ndiye aliyekuja kwa maji ya ubatizo wake na kwa damu ya kifo chake. Hakuja kwa maji tu, bali kwa maji na kwa damu. Naye Roho anashuhudia kwamba ni kweli, kwani Roho ni ukweli.'),
(2021196,69,62,5,7,'Basi, wako mashahidi watatu:'),
(2021197,69,62,5,8,'Roho, maji na damu; na ushahidi wa hawa watatu waafikiana.'),
(2021198,69,62,5,9,'Ikiwa twaukubali ushahidi wa binadamu, ushahidi wa Mungu una uzito zaidi; na huu ndio ushahidi alioutoa Mungu mwenyewe juu ya Mwanae.'),
(2021199,69,62,5,10,'Anayemwamini mwana wa Mungu anao ushahidi huo ndani yake; lakini asiyemwamini Mungu, anamfanya yeye kuwa mwongo, maana hakuamini ushahidi alioutoa Mungu juu ya Mwanae.'),
(2021200,69,62,5,11,'Na, ushahidi wenyewe ndio huu: Mungu alitupatia uzima wa milele, na uzima huo uko kwa Bwana.'),
(2021201,69,62,5,12,'Yeyote, aliye na Mwana wa Mungu anao uzima huo; asiye na Mwana wa Mungu, hana uzima.'),
(2021202,69,62,5,13,'Nawaandikieni mpate kujua kwamba mnao uzima wa milele ninyi mnaoamini kwa jina la Mwana wa Mungu.'),
(2021203,69,62,5,14,'Na sisi tuko thabiti mbele ya Mungu kwani tuna hakika kwamba tukimwomba chochote kadiri ya mapenzi yake, yeye hutusikiliza.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021204,69,62,5,15,'Yeye hutusikiliza kila tunapomwomba; na kwa vile tunajua kwamba yeye hutusikiliza kila tunapomwomba, twajua pia kwamba atupatia yote tunayomwomba.'),
(2021205,69,62,5,16,'Mtu akimwona ndugu yake ametenda dhambi isiyompeleka kwenye kifo anapaswa kumwombea kwa Mungu, naye Mungu atampatia uzima. Nasema jambo hili kuhusu wale waliotenda dhambi ambazo si za kifo. Lakini ipo dhambi yenye kumpeleka mtu kwenye kifo nami sisemi kwamba mnapaswa kumwomba Mungu kwa ajili ya hiyo.'),
(2021206,69,62,5,17,'Kila tendo lisilo adilifu ni dhambi, lakini kuna dhambi isiyompeleka mtu kwenye kifo.'),
(2021207,69,62,5,18,'Tunajua kwamba kila aliye mtoto wa Mungu hatendi dhambi, kwa sababu Mwana wa Mungu humlinda salama, na yule Mwovu hawezi kumdhuru.'),
(2021208,69,62,5,19,'Tunajua kwamba sisi ni wake Mungu ingawa ulimwengu wote unatawaliwa na yule Mwovu.'),
(2021209,69,62,5,20,'Twajua pia kwamba Mwana wa Mungu amekuja, akatupa elimu ili tumjue Mungu wa kweli; tuishi katika muungano na Mungu wa kweli--katika muungano na Mwanae, Yesu Kristo. Huyu ndiye Mungu wa kweli, na huu ndio uzima wa milele.'),
(2021210,69,62,5,21,'Watoto wangu, epukaneni na sanamu za miungu.'),
(2021211,69,63,1,1,'Mimi Mzee nakuandikia wewe Bimkubwa mteule, pamoja na watoto wako ninaowapenda kweli. Wala si mimi tu ninayewapenda, bali pia wote wanaoujua ule ukweli wanawapenda ninyi,'),
(2021212,69,63,1,2,'kwa sababu ukweli unakaa nasi milele.'),
(2021213,69,63,1,3,'Neema na huruma na amani zitokazo kwa Mungu Baba na kwa Yesu Kristo, Mwana wa Baba, zitakuwa pamoja nasi katika ukweli na upendo.'),
(2021214,69,63,1,4,'Nilifurahi sana kuona kwamba baadhi ya watoto wako wanaishi katika ukweli kama Baba alivyotuamuru.'),
(2021215,69,63,1,5,'Basi, Bimkubwa, ninalo ombi moja kwako: tupendane. Ombi hili si amri mpya, bali ni amri ileile tuliyokuwa nayo tangu mwanzo.'),
(2021216,69,63,1,6,'Upendo maana yake ni kuishi kwa kuzitii amri zake Mungu. Amri niliyoisikia tangu mwanzo ndiyo hii: mnapaswa nyote kuishi katika upendo.'),
(2021217,69,63,1,7,'Wadanganyifu wengi wamezuka duniani, watu ambao hawakiri kwamba Yesu Kristo amekuja kwetu akawa binadamu. Mtu asemaye hivyo ni mdanganyifu na ni Adui wa Kristo.'),
(2021218,69,63,1,8,'Basi, jihadharini ninyi wenyewe ili msije mkapoteza kile mlichokishugulikia, bali mpate tuzo lenu kamili.'),
(2021219,69,63,1,9,'Asiyezingatia na kudumu katika mafundisho ya Kristo, bali anayakiuka, hana Mungu. Lakini anayedumu katika mafundisho hayo anaye Baba na Mwana.'),
(2021220,69,63,1,10,'Basi, kama mtu akija kwenu bila kuwaleteeni mafundisho hayo, msimkaribishe nyumbani kwenu, wala msimsalimu.'),
(2021221,69,63,1,11,'Maana anayemsalimu mtu huyo, anashirikiana naye katika matendo yake maovu.'),
(2021222,69,63,1,12,'Ninayo mengi ya kuwaambieni lakini sipendi kufanya hivyo kwa karatasi na wino; badala yake, natumaini kuwatembeleeni na kuzungumza nanyi ana kwa ana, ili furaha yetu ikamilike.'),
(2021223,69,63,1,13,'Watoto wa dada yako mteule wanakusalimu.'),
(2021224,69,64,1,1,'Mimi mzee nakuandikia wewe Gayo, rafiki yangu, ninayekupenda kweli.'),
(2021225,69,64,1,2,'Mpenzi wangu, nakutakia mafanikio mema ya kila aina; nakutakia afya njema ya mwili kama ulivyo nayo rohoni.'),
(2021226,69,64,1,3,'Nimefurahi sana ndugu kadhaa walipofika hapa, wakaiambia juu ya uaminifu wako kuhusu ukweli; naam, wewe unaishi daima katika ukweli.'),
(2021227,69,64,1,4,'Hakuna kitu kinachonifurahisha zaidi kuliko kusikia kwamba watoto wangu wanaishi katika ukweli.'),
(2021228,69,64,1,5,'Mpenzi wangu, wewe ni mwaminifu kila mara unapowahudumia ndugu, hata kama ni wageni.'),
(2021229,69,64,1,6,'Ndugu hao wamelieleza kanisa hapa habari za upendo wako. Tafadhali uwasaidie waendelee na safari yao kwa namna itakayompendeza Mungu,'),
(2021230,69,64,1,7,'Maana wanaanza safari yao katika utumishi wa Kristo bila kupokea msaada wowote kutoka kwa watu wasioamini.'),
(2021231,69,64,1,8,'Basi, sisi tunapaswa kuwasaidia watu hawa, ili nasi tupate kushiriki katika kazi yao kwa ajili ya ukweli.'),
(2021232,69,64,1,9,'Niliandika barua fupi kwa hilo kanisa; lakini Diotrefe, ambaye hupenda kuwa kiongozi wao, hataki kabisa kunisikiliza.'),
(2021233,69,64,1,10,'Basi, nitakapokuja nitayafichua mambo yote anayofanya, maneno mabaya anayotutolea na uongo anaosema juu yetu. Isitoshe, yeye hukataa kuwakaribisha hao ndugu walio safarini, na hata huwazuia watu wengine wanaotaka kuwakaribisha, na hujaribu kuwafukuzia nje ya kanisa.'),
(2021234,69,64,1,11,'Mpenzi wangu, usifuate mfano mbaya, bali mfano mwema. Kila atendaye mema ni wa Mungu; lakini anayetenda mabaya hajapata kumwona Mungu.'),
(2021235,69,64,1,12,'Kila mtu anamsifu Demetrio; naam, ukweli wenyewe unamsifu. Nasi pia tunatoa ushahidi wetu juu yake, nawe wajua kwamba tunachosema ni kweli.'),
(2021236,69,64,1,13,'Ninayo bado mengi ya kukwambia, lakini sipendi kuyaandika kwa kalamu na wino.'),
(2021237,69,64,1,14,'Natumaini kukuona karibuni na hapo tutazungumza ana kwa ana.'),
(2021238,69,64,1,15,'Nakutakia amani. Rafiki zako wanakusalimu. Wasalimu rafiki zetu wote kila mmoja binafsi.'),
(2021239,69,65,1,1,'Mimi Yuda, mtumishi wa Yesu Kristo, ndugu yake Yakobo, nawaandikia ninyi mlioitwa na Mungu na ambao mnaishi katika upendo wa Mungu Baba, na katika ulinzi wa Yesu Kristo.'),
(2021240,69,65,1,2,'Nawatakieni huruma, amani na upendo kwa wingi.'),
(2021241,69,65,1,3,'Ndugu wapenzi, wakati nimo katika jitihada ya kuwaandikieni juu ya ule wokovu tunaoshiriki sote, nimeona lazima ya kuwaandikieni na kuwahimizeni mwendelee kupigana kwa ajili ya imani ambayo Mungu amewajalia watu wake mara moja tu kwa wakati wote.'),
(2021242,69,65,1,4,'Maana watu wasiomcha Mungu wamepata kujiingiza kwa siri miongoni mwetu, watu ambao, kwa faida ya maisha yao mabaya, wanaupotosha ujumbe wa neema ya Mungu wetu na kumkana Yesu Kristo aliye peke yake kiongozi na Bwana wetu. Maandiko Matakatifu yalikwisha bashiri tangu awali hukumu inayowangojea watu hao.'),
(2021243,69,65,1,5,'Nataka kuwakumbusheni mambo fulani ambayo mmekwisha yajua: kumbukeni jinsi Bwana alivyowaokoa watu wa Israeli na kuwatoa katika nchi ya Misri, lakini baadaye aliwaangamiza wale ambao hawakuamini.'),
(2021244,69,65,1,6,'Na, malaika ambao hawakuridhika na cheo chao, wakayaacha makao yao ya asili, Mungu amewafunga gizani kwa minyororo ya milele wahukumiwe Siku ile kuu.'),
(2021245,69,65,1,7,'Kumbukeni pia Sodoma na Gomora, na miji ya kandokando yake; wenyeji wake walifanya kama wale malaika; walifanya uzinzi na mambo yaliyo kinyume cha maumbile, wakapewa hukumu ya moto wa milele, iwe onyo kwa watu wote.'),
(2021246,69,65,1,8,'Hivyo ndivyo pia walivyo watu hawa. ndoto zao huwaongoza katika kuichafua miili yao wenyewe, kuyadharau mamlaka ya Mungu na kuvitukana viumbe vitukufu vya huko juu.'),
(2021247,69,65,1,9,'Hata Mikaeli, malaika mkuu, hakufanya hivyo. Katika ule ubishi kati yake na Ibilisi waliobishana juu ya mwili wa Mose, Mikaeli hakuthubutu kumhukumu Ibilisi kwa matusi; ila alisema: "Bwana mwenyewe na akukaripie."'),
(2021248,69,65,1,10,'Lakini watu hawa hutukana chochote wasichokielewa; mambo yaleyale wanayoyajua kwa silika kama vile wanyama wanayoyajua ndiyo yanayowaangamiza.'),
(2021249,69,65,1,11,'Ole wao! Watu hao wamefuata mwenendo uleule wa Kaini. Kwa ajili ya fedha, wamejiingiza katika mkosi uleule wa Baalamu. Wameasi kama Kora alivyoasi na wameangamizwa kama yeye alivyoangamizwa.'),
(2021250,69,65,1,12,'Kwa makelele yao yasiyo na adabu, watu hao ni kama madoa machafu katika mikutano yenu ya karamu ya Bwana. Hujipendelea wao wenyewe tu, na wako kama mawingu yanayopeperushwa huko na huko na upepo bila ya kuleta mvua. Wao ni kama miti isiyozaa matunda hata wakati wa majira yake, wamekufa kabisa.'),
(2021251,69,65,1,13,'Watu hao ni kama mawimbi makali ya bahari, na matendo yao ya aibu yanaonekana dhahiri kama vile mapovu ya mawimbi. Wao ni kama nyota zinazotangatanga, ambao Mungu amewawekea mahali pao milele katika giza kuu.'),
(2021252,69,65,1,14,'Henoki, ambaye ni babu wa saba tangu Adamu, alibashiri hivi juu ya watu hawa: "Sikilizeni! Bwana atakuja pamoja na maelfu ya malaika wake watakatifu'),
(2021253,69,65,1,15,'kutoa hukumu juu ya binadamu wote, kuwahukumu wote kwa ajili ya matendo yao yote maovu waliyotenda na kwa ajili ya maneno yote mabaya ambayo watu waovu walimkashifu nayo."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021254,69,65,1,16,'Watu hawa wananung`unika daima na kuwalaumu watu wengine. Hufuata tamaa zao mbaya, hujigamba na kuwasifu watu wengine mno kusudi wafaulu katika mipango yao.'),
(2021255,69,65,1,17,'Lakini ninyi wapenzi wangu, kumbukeni yale mliyoambiwa hapo awali ni mitume wa Bwana wetu Yesu Kristo.'),
(2021256,69,65,1,18,'Waliwaambieni: "Siku za mwisho zitakapofika, watatokea watu watakaowadhihaki ninyi, watu wafuatao tamaa zao mbaya."'),
(2021257,69,65,1,19,'Hao ndio watu wanaosababisha mafarakano, watu wanaotawaliwa na tamaa zao za kidunia, watu wasio na Roho wa Mungu.'),
(2021258,69,65,1,20,'Lakini ninyi, wapenzi wangu, endeleeni kujijenga kikamilifu katika imani yenu takatifu. Salini kwa nguvu ya Roho Mtakatifu,'),
(2021259,69,65,1,21,'na kubaki katika upendo wa Mungu, mkiwa mnamngojea Bwana wetu Yesu Kristo awapeni uzima wa milele kwa huruma yake.'),
(2021260,69,65,1,22,'Muwe na huruma kwa watu walio na mashaka;'),
(2021261,69,65,1,23,'waokoeni kwa kuwanyakua kutoka motoni; na kwa wengine muwe na huruma pamoja na hofu, lakini chukieni hata mavazi yao ambayo yamechafuliwa na tamaa zao mbaya.'),
(2021262,69,65,1,24,'Kwake yeye awezaye kuwalinda msije mkaanguka, na kuwaleta ninyi bila hatia mpaka mbele ya utukufu wake,'),
(2021263,69,65,1,25,'kwake yeye aliye peke yake Mungu, Mkombozi wetu, uwe utukufu, ukuu, nguvu na mamlaka kwa njia ya Kristo Bwana wetu, tangu zama zote, sasa na hata milele! Amina.'),
(2021264,69,66,1,1,'Hizi ni habari za mambo ambayo yalifunuliwa na Yesu Kristo. Mungu alimpa Kristo ufunuo huu ili awaonyeshe watumishi wake mambo ambayo yanapaswa kutukia karibuni. Kristo alimtuma malaika wake amjulishe Yohane, mtumishi wake, mambo hayo,'),
(2021265,69,66,1,2,'naye Yohane, ameyasema yote aliyoyaona. Na hii ndio taarifa yake kuhusu ujumbe wa Mungu na ukweli uliofunuliwa na Yesu Kristo.'),
(2021266,69,66,1,3,'Heri yake mtu anayesoma kitabu hiki; heri yao wale wanaosikiliza maneno ya ujumbe huu wa kinabii na kushika yaliyoandikwa humu, maana wakati umekaribia ambapo mambo haya yatatukia.'),
(2021267,69,66,1,4,'Mimi Yohane nayaandikia makanisa yaliyoko mkoani Asia. Nawatakieni neema na amani kutoka kwake yeye aliyeko, aliyekuwako na anayekuja; na kutoka kwa roho saba walio mbele ya kiti chake cha enzi,'),
(2021268,69,66,1,5,'na kutoka kwa Yesu Kristo, shahidi mwaminifu, wa kwanza kufufuliwa kutoka wafu, na ambaye ni mtawala wa wafalme wa dunia. Yeye anatupenda, na kwa damu yake ametufungua kutoka vifungo vya dhambi zetu,'),
(2021269,69,66,1,6,'akatufanya sisi kuwa ufalme wa makuhani, tumtumikie Mungu, Baba yake. Kwake Yesu Kristo uwe utukufu na nguvu, milele na milele! Amina.'),
(2021270,69,66,1,7,'Tazama! Anakuja katika mawingu! Kila mtu atamwona, hata wale waliomchoma. Makabila yote duniani yataomboleza juu yake. Naam! Amina.'),
(2021271,69,66,1,8,'"Mimi ni Alfa na Omega," asema Bwana Mungu Mwenye Uwezo, aliyeko, aliyekuwako na anayekuja.'),
(2021272,69,66,1,9,'Mimi ni Yohane, ndugu yenu; na kwa kuungana na Kristo nashiriki pamoja nanyi katika kustahimili mateso yanayowapata wale walio wa Utawala wake. Mimi nilikuwa kisiwani Patmo kwa sababu ya kuhubiri ujumbe wa Mungu na ukweli wa Yesu.'),
(2021273,69,66,1,10,'Basi, wakati mmoja, siku ya Bwana, nilikumbwa na Roho, nikasikia nyuma yangu sauti kubwa kama sauti ya tarumbeta.'),
(2021274,69,66,1,11,'Nayo ilisema, "Andika katika kitabu yote unayoyaona, ukipeleke kwa makanisa haya saba: Efeso, Smurna, Pergamoni, Thuatira, Sarde, Filadelfia na Laodikea."'),
(2021275,69,66,1,12,'Basi, nikageuka nimwone huyo aliyesema nami, nikaona vinara vya taa saba vya dhahabu,'),
(2021276,69,66,1,13,'na katikati yake kulikuwa na kitu kama mtu, naye alikuwa amevaa kanzu ndefu na ukanda wa dhahabu kifuani.'),
(2021277,69,66,1,14,'Nywele zake zilikuwa nyeupe kama pamba safi, kama theluji; macho yake yalimetameta kama moto;'),
(2021278,69,66,1,15,'miguu yake iling`aa kama shaba iliyosafishwa katika tanuru ya moto na kusuguliwa, na sauti yake ilikuwa, kama sauti ya poromoko la maji.'),
(2021279,69,66,1,16,'Katika mkono wake wa kulia, alikuwa na nyota saba, na kinywani mwake mlitoka upanga wenye makali kuwili. Uso wake uling`aa kama jua kali.'),
(2021280,69,66,1,17,'Basi, nilipomwona tu, nilianguka mbele ya miguu yake kama maiti. Lakini yeye akaweka mkono wake wa kulia juu yangu, akasema, "Usiogope! Mimi ni wa kwanza na wa mwisho.'),
(2021281,69,66,1,18,'Mimi ni yeye aliye hai! Nilikuwa nimekufa, lakini, tazama, sasa ni mzima milele na milele. Ninazo funguo za kifo na Kuzimu.'),
(2021282,69,66,1,19,'Basi, sasa andika mambo haya unayoyaona, mambo yanayotukia sasa na yale yatakayotukia baadaye.'),
(2021283,69,66,1,20,'Siri ya nyota zile saba ulizoziona katika mkono wangu wa kulia, na siri ya vile vinara saba vya taa hii: zile nyota saba ni malaika wa makanisa; na vile vinara saba vya taa ni makanisa saba.'),
(2021284,69,66,2,1,'"Kwa malaika wa kanisa la Efeso andika hivi: "Huu ndio ujumbe kutoka kwake yeye ashikaye nyota saba katika mkono wake wa kulia, na ambaye hutembea katikati ya vinara saba vya taa vya dhahabu.'),
(2021285,69,66,2,2,'Najua mambo yako yote; najua bidii yako na uvumilivu wako. Najua kwamba huwezi kuwavumilia watu waovu, na kwamba umewapima wale wanaojisemea kuwa mitume na kumbe sio, ukagundua kwamba ni waongo.'),
(2021286,69,66,2,3,'Wewe unayo saburi, umestahimili taabu nyingi kwa ajili ya jina langu, wala hukuvunjika moyo.'),
(2021287,69,66,2,4,'Lakini ninayo hoja moja juu yako: wewe hunipendi tena sasa kama pale awali.'),
(2021288,69,66,2,5,'Basi, pakumbuke pale ulipokuwa kabla ya kuanguka, ukayaache madhambi yako, na kufanya kama ulivyofanya pale awali. La sivyo, naja kwako na kukiondoa kinara chako mahali pake.'),
(2021289,69,66,2,6,'Lakini nakusifu juu ya kitu kimoja: wewe unayachukia wanayoyatenda Wanikolai kama ninavyoyachukia mimi.'),
(2021290,69,66,2,7,'"Aliye na masikio, basi, na asikie yale Roho anayoyaambia makanisa! "Wale wanaoshinda nitawapa haki ya kula matunda ya mti wa uzima ulioko ndani ya bustani ya Mungu.'),
(2021291,69,66,2,8,'"Kwa malaika wa kanisa la Smurna andika hivi: "Huu ndio ujumbe kutoka kwake yeye wa kwanza na wa mwisho, ambaye alikufa na akaishi tena.'),
(2021292,69,66,2,9,'Najua taabu zako; najua pia umaskini wako, ingawaje kwa kweli wewe ni tajiri; najua kashfa walizokufanyia wale wanaojiita Wayahudi lakini si Wayahudi wa kweli, bali ni kundi lake Shetani.'),
(2021293,69,66,2,10,'Usiogope hata kidogo yale ambayo itakulazimu kuteseka. Sikiliza! Ibilisi anataka kuwajaribu kwa kuwatia baadhi yenu gerezani; nanyi mtapata dhiki kwa muda wa siku kumi. Muwe waaminifu hata mpaka kufa, nami nitawapeni taji ya uzima.'),
(2021294,69,66,2,11,'"Aliye na masikio, basi, na asikie yale Roho anayoyaambia makanisa! "Wale wanaoshinda hawataumizwa na kifo cha pili.'),
(2021295,69,66,2,12,'"Kwa malaika wa kanisa la Pergamoni andika hivi: "Huu ndio ujumbe wake yeye aliye na upanga mkali wenye kuwili.'),
(2021296,69,66,2,13,'Najua unakoishi: Wewe unaishi kwenye makao makuu ya Shetani! Lakini bado unashikilia jina langu; hukuikana imani yako kwangu hata siku zile Antipa shahidi wangu mwaminifu, alipouawa pale mahali anapoishi Shetani.'),
(2021297,69,66,2,14,'Lakini ninayo machache dhidi yako: baadhi yenu ni wafuasi wa Balaamu aliyemfundisha Balaki kuwatega wana wa Israeli wale vyakula vilivyotambikiwa sanamu za kufanya uzinzi.'),
(2021298,69,66,2,15,'Vivyo hivyo, wako pia miongoni mwenu watu wanaofuata mafundisho ya Wanikolai.'),
(2021299,69,66,2,16,'Basi, achana na madhambi yako. La sivyo, nitakuja kwako upesi na kupigana na watu hao kwa upanga utokao kinywani mwangu.'),
(2021300,69,66,2,17,'"Aliye na masikio, basi, na asikie yale Roho anayoyaambia makanisa! "Wale wanaoshinda nitawapa ile mana iliyofichika. Nitawapa pia jiwe jeupe lililoandikwa jina jipya ambalo hakuna mtu aliyelijua isipokuwa tu wale wanaolipokea.'),
(2021301,69,66,2,18,'"Kwa malaika wa kanisa la Thuatira andika hivi: "Huu ndio ujumbe wa Mwana wa Mungu, ambaye macho yake yametameta kama moto, na miguu yake inang`aa kama shaba iliyosuguliwa.'),
(2021302,69,66,2,19,'Najua mambo yako yote. Najua upendo wako, imani yako, utumishi wako na uvumilivu wako. Wewe unafanya vizuri zaidi sasa kuliko pale awali.'),
(2021303,69,66,2,20,'Lakini nina hoja moja juu yako: wewe unamvumilia yule mwanamke Yezabeli anayejiita nabii wa Mungu. Yeye huwafundisha na kuwapotosha watumishi wangu wafanye uzinzi na kula vyakula vilivyotambikiwa sanamu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021304,69,66,2,21,'Nimempa muda wa kutubu dhambi zake, lakini hataki kuachana na uzinzi wake.'),
(2021305,69,66,2,22,'Sikiliza! Sasa namtupa kitandani ambapo yeye pamoja na wote waliofanya uzinzi naye watapatwa na mateso makali. Naam, nitafanya hivyo, kama wasipotubu matendo yao mabaya waliyotenda naye.'),
(2021306,69,66,2,23,'Tena nitawaua wafuasi wake, ili makanisa yote yatambue kwamba mimi ndiye ninayechunguza mioyo na fikira za watu.'),
(2021307,69,66,2,24,'"Lakini ninyi wengine mlioko huko Thuatira ambao hamfuati mafundisho yake Yezabeli, na ambao hamkujifunza kile wanachokiita `Siri ya Shetani`, nawaambieni kwamba sitawapeni mzigo mwingine.'),
(2021308,69,66,2,25,'Lazima mzingatie yale mliyo nayo sasa mpaka nitakapokuja.'),
(2021309,69,66,2,26,'"Wanaoshinda, na wale watakaozingatia mpaka mwisho kutenda ninayotaka, nitawapa mamlaka juu ya mataifa. Naam, nitawapa uwezo uleule nilioupokea kwa Baba: yaani, watayatawala mataifa kwa fimbo ya chuma na kuyavunjavunja kama chombo cha udongo. Tena nitawapa nyota ya asubuhi.'),
(2021310,69,66,2,27,'[]'),
(2021311,69,66,2,28,'[]'),
(2021312,69,66,2,29,'"Aliye na masikio, basi, na ayasikie yale Roho anayoyaambia makanisa!'),
(2021313,69,66,3,1,'"Kwa malaika wa kanisa la Sarde andika hivi: "Huu ndio ujumbe kutoka kwake yeye aliye na roho saba za Mungu na nyota saba. Nayajua mambo yako yote; najua unajulikana kuwa na uhai kumbe umekufa!'),
(2021314,69,66,3,2,'Amka! Imarisha chochote chema kilichokubakia kabla nacho hakijatoweka kabisa. Maana, mpaka sasa, sijayaona matendo yako kuwa ni makamilifu mbele ya Mungu wangu.'),
(2021315,69,66,3,3,'Kumbuka, basi, yale uliyofundishwa na jinsi ulivyoyasikia, uyatii na ubadili nia yako mbaya. Usipokesha nitakujia ghafla kama mwizi, na wala hutaijua saa nitakapokujia.'),
(2021316,69,66,3,4,'Lakini wako wachache huko Sarde ambao hawakuyachafua mavazi yao. Hao wanastahili kutembea pamoja nami wakiwa wamevaa mavazi meupe.'),
(2021317,69,66,3,5,'"Wale wanaoshinda, watavikwa mavazi meupe kama hao. Nami sitayafuta majina yao kutoka katika kitabu cha uzima; tena nitawakiri kwamba ni wangu mbele ya Baba yangu na mbele ya malaika wake.'),
(2021318,69,66,3,6,'"Aliye na masikio, basi, na ayasikie yale Roho anayoyaambia makanisa!'),
(2021319,69,66,3,7,'"Kwa malaika wa kanisa la Filadelfia andika hivi: "Huu ndio ujumbe kutoka kwake yeye aliye mtakatifu na wa kweli, ambaye anao ule ufunguo wa Daudi, na ambaye hufungua na hakuna mtu awezaye kufungua.'),
(2021320,69,66,3,8,'Nayajua mambo yako yote! Sasa, nimefungua mbele yako mlango ambao hakuna mtu awezaye kuufunga; najua kwamba ingawa huna nguvu sana, hata hivyo, umezishika amri zangu, umelitii neno langu wala hukulikana jina langu.'),
(2021321,69,66,3,9,'Sikiliza! Nitawapeleka kwako watu wa kundi lake Shetani, watu ambao hujisema kuwa ni Wayahudi, kumbe ni wadanganyifu. Naam, nitawapeleka kwako na kuwafanya wapige magoti mbele yako wapate kujua kwamba kweli nakupenda wewe.'),
(2021322,69,66,3,10,'Kwa kuwa wewe umezingatia agizo langu la kuwa na uvumilivu, nami pia nitakutegemeza salama wakati ule wa dhiki inayoujia ulimwengu mzima kuwajaribu wote wanaoishi duniani.'),
(2021323,69,66,3,11,'Naja kwako upesi! Linda, basi, ulicho nacho sasa, ili usije ukanyang`anywa na mtu yeyote taji yako ya ushindi.'),
(2021324,69,66,3,12,'"Wale wanaoshinda nitawafanya wawe minara katika Hekalu la Mungu wangu, na hawatatoka humo kamwe. Pia nitaandika juu yao jina la Mungu wangu na jina la mji wa Mungu wangu, yaani Yerusalemu mpya, mji ambao utashuka kutoka juu mbinguni kwa Mungu wangu. Tena nitaandika juu yao jina langu jipya.'),
(2021325,69,66,3,13,'"Aliye na masikio, basi, na ayasikie yale Roho anayoyaambia makanisa!'),
(2021326,69,66,3,14,'"Kwa malaika wa kanisa la Laodikea andika hivi: "Huu ndio ujumbe kutoka kwake yeye aitwaye `Amina`. Yeye ni shahidi mwaminifu na wa kweli, ambaye ni chanzo cha viumbe vyote alivyoumba Mungu.'),
(2021327,69,66,3,15,'Nayajua mambo yako yote! Najua kwamba wewe si baridi wala si moto. Afadhali ungekuwa kimojawapo: baridi au moto.'),
(2021328,69,66,3,16,'Basi, kwa kuwa hali yako ni vuguvugu, si baridi wala si moto, nitakutapika!'),
(2021329,69,66,3,17,'Wewe unajisema, `Mimi ni tajiri; ninajitosheleza, sina haja ya kitu chochote.` Kumbe, hujui kwamba wewe ni mnyonge, unahitaji kuhurumiwa, maskini, kipofu tena uko uchi!'),
(2021330,69,66,3,18,'Nakushauri ununue kwangu dhahabu iliyosafishwa kwa moto upate kuwa tajiri kweli. Tena afadhali ununue pia vazi jeupe, uvae na kufunika aibu ya uchi wako. Nunua pia mafuta ukapake machoni pako upate kuona.'),
(2021331,69,66,3,19,'Mimi ndiye mwenye kumwonya na kumrudi yeyote ninayempenda. Kwa hiyo kaza moyo, achana na dhambi zako.'),
(2021332,69,66,3,20,'Sikiliza! Mimi nasimama mlangoni na kubisha hodi. Mtu akisikia sauti yangu na kufungua mlango, nitaingia nyumbani kwake na kula chakula pamoja naye, naye atakula pamoja nami.'),
(2021333,69,66,3,21,'"Wale wanaoshinda nitawaketisha pamoja nami juu ya kiti changu cha enzi, kama vile mimi mwenyewe nilivyoshinda nikaketi pamoja na Baba yangu juu ya kiti chake cha enzi.'),
(2021334,69,66,3,22,'"Aliye na masikio, basi, na ayasikie yale Roho anayoyaambia makanisa!"'),
(2021335,69,66,4,1,'Baada ya hayo nilitazama nikaona mlango umefunguliwa mbinguni. Na ile sauti niliyoisikia pale awali ambayo ilikuwa kama sauti ya tarumbeta, ikasema, "Njoo hapa juu nami nitakuonyesha mambo yatakayotukia baadaye."'),
(2021336,69,66,4,2,'Mara nikachukuliwa na Roho. Kumbe, huko mbinguni kuna kiti cha enzi na juu yake ameketi mmoja.'),
(2021337,69,66,4,3,'Huyo aliyeketi juu yake alikuwa kama almasi na jiwe zuri jekundu. Upinde wa mvua ulikuwa unang`aa kama zumaridi na ulikizunguka kiti cha enzi pande zote.'),
(2021338,69,66,4,4,'Kulikuwa na duara la viti ishirini na vinne kukizunguka kiti cha enzi, na juu ya viti hivyo wazee ishirini na wanne walikuwa wameketi wamevaa mavazi meupe na taji za dhahabu vichwani.'),
(2021339,69,66,4,5,'Umeme, sauti na ngurumo, vilikuwa vinatoka kwenye hicho kiti cha enzi. Taa saba za moto zilikuwa zinawaka mbele ya hicho kiti cha enzi. Taa hizo ni roho saba za Mungu.'),
(2021340,69,66,4,6,'Mbele ya kiti cha enzi kulikuwa na kitu kama bahari ya kioo, angavu kama jiwe linga`aalo sana. Katika pande zote za hicho kiti cha enzi na kukizunguka, kilikuwa na viumbe hai vinne. Viumbe hivyo vilikuwa vimejaa macho mbele na nyuma.'),
(2021341,69,66,4,7,'Kiumbe cha kwanza kulikuwa kama simba, cha pili kama ng`ombe, cha tatu kilikuwa na sura kama mtu, na cha nne kilikuwa kama tai anayeruka.'),
(2021342,69,66,4,8,'Viumbe hivyo vinne vilikuwa na mabawa sita kila kimoja, na vilikuwa vimejaa macho, ndani na nje. Usiku na mchana, bila kupumzika huimba: "Mtakatifu, mtakatifu, mtakatifu ni Bwana, Mungu Mwenye Uwezo, aliyekuwako, aliyeko na anayekuja!"'),
(2021343,69,66,4,9,'Kila mara viumbe vinne vilipoimba nyimbo za kumtukuza, kumheshimu na kumshukuru huyo aliyeketi juu ya kiti cha enzi, ambaye anaishi milele na milele,'),
(2021344,69,66,4,10,'wale wazee ishirini na wanne hujiangusha mbele ya huyo aliyeketi juu ya kiti cha enzi na kumwabudu huyo ambaye anaishi milele na milele; na huziweka taji zao mbele ya kiti cha enzi wakisema:'),
(2021345,69,66,4,11,'"Wewe ni Bwana na Mungu wetu, unastahili utukufu na heshima na nguvu; maana wewe uliumba vitu vyote, na kwa matakwa yako kila kitu kimepewa uhai na uzima."'),
(2021346,69,66,5,1,'Kisha katika mkono wa kulia wa huyo aliyeketi juu ya kiti cha enzi, nikaona kitabu; nacho kilikuwa kimeandikwa ndani na nje na kufungwa na mihuri saba.'),
(2021347,69,66,5,2,'Tena nikamwona malaika mwenye nguvu akitangaza kwa sauti kubwa: "Nani anayestahili kuvunja hiyo mihuri na kukifungua kitabu hicho?"'),
(2021348,69,66,5,3,'Lakini hakupatikana mtu yeyote mbinguni, wala duniani, wala chini Kuzimu, aliyeweza kukifungua hicho kitabu au kukitazama ndani.'),
(2021349,69,66,5,4,'Basi, mimi nikalia sana kwa sababu hakupatikana mtu aliyestahili kukifungua, au kukitazama ndani.'),
(2021350,69,66,5,5,'Kisha mmoja wa wale wazee akaniambia, "Usilie! Tazama! Simba wa kabila la Yuda, mjukuu maarufu wa Daudi, ameshinda. Yeye anaweza kuivunja mihuri yake saba na kukifungua hicho kitabu."'),
(2021351,69,66,5,6,'Kisha nikaona pale katikati ya kiti cha enzi Mwana kondoo amesimama, akizungukwa kila upande na vile viumbe hai vinne, na wale wazee. Huyo Mwanakondoo alionekana kana kwamba amechinjwa. Alikuwa na pembe saba na macho saba ambayo ni roho saba za Mungu zilizokuwa zimepelekwa kila mahali duniani.'),
(2021352,69,66,5,7,'Mwanakondoo akaenda, akakitwaa hicho kitabu kutoka mkono wa kulia wa yule aliyeketi juu ya kiti cha enzi.'),
(2021353,69,66,5,8,'Mara tu alipokwisha twaa hicho kitabu, vile viumbe hai vinne pamoja na wale wazee ishirini na wanne walianguka kifudifudi mbele ya Mwanakondoo. Kila mmoja, alikuwa na kinubi na bakuli za dhahabu zilizojaa ubani, ambao ni sala za watu wa Mungu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021354,69,66,5,9,'Basi, wakaimba wimbo huu mpya: "Wewe unastahili kukitwaa hicho kitabu na kuivunja mihuri yake. Kwa sababu wewe umechinjwa, na kwa damu yako umemnunulia Mungu watu kutoka katika kila kabila, lugha, jamaa na taifa.'),
(2021355,69,66,5,10,'Wewe umewafanya wawe ufalme wa makuhani wamtumikie Mungu wetu nao watatawala duniani."'),
(2021356,69,66,5,11,'Kisha nikatazama, nikasikia sauti ya malaika wengi sana, idadi isiyohesabika, maelfu na maelfu. Walikuwa wamekaa kuzunguka kiti cha enzi, vile viumbe hai vinne na wale wazee;'),
(2021357,69,66,5,12,'wakasema kwa sauti kuu: "Mwanakondoo aliyechinjwa anastahili kupokea uwezo, utajiri, hekima, nguvu, utukufu na sifa."'),
(2021358,69,66,5,13,'Nikasikia viumbe vyote mbinguni, duniani, chini kuzimuni na baharini--viumbe vyote ulimwenguni--vikisema: "Kwake yeye aketiye katika kiti cha enzi, na kwa Mwanakondoo, iwe sifa na heshima na utukufu na enzi milele na milele."'),
(2021359,69,66,5,14,'Na vile viumbe vinne hai vikasema, "Amina!" Na wale wazee wakaanguka kifudifudi, wakaabudu.'),
(2021360,69,66,6,1,'Kisha nikamwona Mwanakondoo anavunja mhuri mmojawapo wa ile mihuri saba. Nikasikia kimoja cha vile viumbe hai vinne kikisema kwa sauti kama ya ngurumo, "Njoo!"'),
(2021361,69,66,6,2,'Mimi nikatazama, na kumbe palikuwa na farasi mmoja mweupe hapo. Na mpanda farasi wake alikuwa na upinde, akapewa na taji. Basi, akatoka kama mshindi aendelee kushinda.'),
(2021362,69,66,6,3,'Kisha, Mwanakondoo akavunja mhuri wa pili. Nikamsikia yule kiumbe hai wa pili akisema, "Njoo!"'),
(2021363,69,66,6,4,'Nami nikatazama na kumbe palikuwapo farasi mwingine hapo, mwekundu. Mpanda farasi wake alikabidhiwa jukumu la kuondoa amani duniani, watu wauane, akapewa upanga mkubwa.'),
(2021364,69,66,6,5,'Kisha Mwanakondoo akavunja mhuri wa tatu. Nikamsikia yule kiumbe hai wa tatu akisema, "Njoo!" Nikatazama na kumbe palikuwapo farasi mmoja hapo, mweusi. Mpanda farasi wake alikuwa na vipimo viwili vya kupimia uzito mkononi mwake.'),
(2021365,69,66,6,6,'Nikasikia kitu kama sauti itokayo kwa vile viumbe hai vinne. Nayo ilisema, "Kibaba kimoja cha unga wa ngano wa kiasi cha fedha dinari moja, na vibaba vitatu vya shayiri kwa dinari moja. Lakini usiharibu mafuta wala divai!"'),
(2021366,69,66,6,7,'Kisha Mwanakondoo akavunja mhuri wa nne. Nikamsikia yule kiumbe hai wa nne akisema, "Njoo!"'),
(2021367,69,66,6,8,'Nami nikatazama, na kumbe alikuwapo farasi mmoja hapo, rangi yake kijivu. Na jina la mpanda farasi wake lilikuwa kifo, na Kuzimu alimfuata nyuma. Hao walipewa mamlaka juu ya robo moja ya dunia, wawaue watu kwa upanga, njaa, tauni na kwa wanyama wakali wa dunia.'),
(2021368,69,66,6,9,'Kisha Mwanakondoo akavunja mhuri wa tano. Nikaona pale chini ya madhabahu ya kufukizia ubani roho za wale waliouawa kwa sababu ya ujumbe wa Mungu, na kwa sababu ya ushuhuda waliotoa.'),
(2021369,69,66,6,10,'Basi, wakalia kwa sauti kubwa: "Ee Bwana, uliye mtakatifu na mwaminifu, mpaka lini utakawia kulipiza kisasi kwa wakazi wote wa dunia kwa ajili ya kuuawa kwetu?"'),
(2021370,69,66,6,11,'Wakapewa kila mmoja vazi refu jeupe, wakaambiwa wazidi kusubiri kwa muda mfupi, mpaka itakapotimia idadi ya watumishi wenzao na ndugu ambao watawaua kama wao wenyewe walivyouawa.'),
(2021371,69,66,6,12,'Kisha nikatazama, na wakati Mwanakondoo alipouvunja mhuri wa sita, kukawa na tetemeko kubwa la ardhi; jua likawa jeusi kama gunia; mwezi wote ukawa mwekundu kama damu;'),
(2021372,69,66,6,13,'nazo nyota za mbingu zikaanguka juu ya ardhi kama matunda ya mtini yasiyokomaa yaangukavyo wakati mti wake unapotikiswa na upepo mkali.'),
(2021373,69,66,6,14,'Anga likatoweka kama vile karatasi inavyokunjwakunjwa; milima yote na visima vyote vikaondolewa mahali pake.'),
(2021374,69,66,6,15,'Kisha wafalme wa duniani, wakuu, majemadari, matajiri, wenye nguvu, kila mtumwa na mtu huru, wakajificha mapangoni na kwenye majabali milimani.'),
(2021375,69,66,6,16,'Wakaiambia hiyo milima na hayo majabali, "Tuangukieni, mkatufiche mbali na yeye aketiye juu ya kiti cha enzi, na mbali na ghadhabu ya Mwanakondoo!'),
(2021376,69,66,6,17,'Maana siku maalum ya ghadhabu yao imefika. Nani awezaye kuikabili?"'),
(2021377,69,66,7,1,'Baada ya hayo nikawaona malaika wanne wamesimama katika pembe nne za dunia wakishika pepo nne za dunia ili upepo usivume hata kidogo: wala katika nchi, wala baharini, wala kwenye miti.'),
(2021378,69,66,7,2,'Kisha nikamwona malaika mwingine akipanda juu kutoka mashariki akiwa na mhuri wa Mungu aliye hai. Akapaaza sauti na kuwaambia hao malaika wanne waliokabidhiwa jukumu la kuiharibu nchi na bahari,'),
(2021379,69,66,7,3,'"Msiharibu nchi, wala bahari, wala miti, mpaka tutakapokwisha wapiga mhuri watumishi wa Mungu wetu katika paji la uso."'),
(2021380,69,66,7,4,'Kisha nikasikia idadi ya hao waliopigwa mhuri: Watu mia moja arobaini na nne elfu wa makabila yote ya watu wa Israeli.'),
(2021381,69,66,7,5,'Kabila la Yuda walikuwa watu kumi na mbili elfu; kabila la Reubeni, kumi na mbili elfu, kabila la Gadi, kumi na mbili elfu;'),
(2021382,69,66,7,6,'Kabila la Asheri, kumi na mbili elfu; kabila la Naftali, kumi na mbili elfu; kabila la Manase, kumi na mbili elfu;'),
(2021383,69,66,7,7,'kabila la Simeoni, kumi na mbili elfu, kabila la Lawi, kumi na mbili elfu, kabila la Isakari, kumi na mbili elfu;'),
(2021384,69,66,7,8,'kabila la Zabuloni, kumi na mbili elfu; kabila la Yosefu, kumi na mbili elfu, na kabila la Benyamini, kumi na mbili elfu.'),
(2021385,69,66,7,9,'Kisha nikatazama, nikaona umati mkubwa wa watu wasiohesabika: watu wa kila taifa, ukoo, jamaa na lugha. Nao walikuwa wamesimama mbele ya kiti cha enzi na mbele ya Mwanakondoo, wakiwa wamevaa mavazi meupe na kushika matawi ya mitende mikononi mwao.'),
(2021386,69,66,7,10,'Wakapaaza sauti: "Ukombozi wetu watoka kwa Mungu wetu aketiye juu ya kiti cha enzi, na kutoka kwa Mwanakondoo!"'),
(2021387,69,66,7,11,'Malaika wote wakasimama kukizunguka kiti cha enzi, wazee na vile viumbe hai vinne. Wakaanguka kifudifudi mbele ya kiti cha enzi, wakamwabudu Mungu,'),
(2021388,69,66,7,12,'wakisema, "Amina! Sifa, utukufu, hekima, shukrani, heshima, uwezo na nguvu viwe kwa Mungu wetu, milele na milele! Amina!"'),
(2021389,69,66,7,13,'Mmoja wa hao wazee akaniuliza, "Hawa waliovaa mavazi meupe ni watu gani? Na wametoka wapi?"'),
(2021390,69,66,7,14,'Nami nikamjibu, "Mheshimiwa, wewe wajua!" Naye akaniambia, "Hawa ni wale waliopita salama katika ule udhalimu mkuu. Waliyaosha mavazi yao katika damu ya Mwanakondoo, yakawa meupe kabisa.'),
(2021391,69,66,7,15,'Ndiyo maana wako mbele ya kiti cha enzi cha Mungu. Humtumikia Mungu mchana na usiku katika Hekalu lake; naye aketiye juu ya kiti cha enzi atatandaza hema lake juu yao kuwalinda.'),
(2021392,69,66,7,16,'Hawataona tena njaa wala kiu; jua wala joto kali halitawachoma tena,'),
(2021393,69,66,7,17,'kwa sababu Mwanakondoo aliye katikati ya kiti cha enzi atakuwa mchungaji wao, naye atawaongoza kwenye chemchemi za maji ya uzima. Naye Mungu atayafuta machozi yote machoni mwao."'),
(2021394,69,66,8,1,'Na Mwanakondoo alipouvunja mhuri wa saba, kukawa kimya mbinguni kwa muda wa nusu saa.'),
(2021395,69,66,8,2,'Kisha nikawaona wale malaika saba wanaosimama mbele ya Mungu wamepewa tarumbeta saba.'),
(2021396,69,66,8,3,'Malaika mwingine akafika, akiwa anachukua chetezo cha dhahabu, akasimama mbele ya madhabahu ya kufukizia ubani. Naye akapewa ubani mwingi autoe sadaka pamoja na sala za watu wote wa Mungu, juu ya madhabahu ya dhahabu iliyo mbele ya kiti cha enzi.'),
(2021397,69,66,8,4,'Moshi wa ubani ukapanda juu, pamoja na sala za watu wa Mungu, kutoka mikononi mwake huyo malaika aliyekuwa mbele ya Mungu.'),
(2021398,69,66,8,5,'Kisha malaika akakichukua hicho chetezo, akakijaza moto wa madhabahuni akakitupa duniani. Kukawa na ngurumo, sauti, umeme na tetemeko la ardhi.'),
(2021399,69,66,8,6,'Kisha wale malaika saba wenye tarumbeta saba wakajiweka tayari kupiga mbiu ya mgambo. ic'),
(2021400,69,66,8,7,'Malaika wa kwanza akapiga tarumbeta yake. Mchanganyiko wa mvua ya mawe na moto, pamoja na damu, ukamwagwa juu ya nchi. Theluthi moja ya nchi ikaungua, theluthi moja ya miti ikaungua, na majani yote mabichi yakaungua.'),
(2021401,69,66,8,8,'Malaika wa pili akapiga tarumbeta yake. Na kitu kama mlima mkubwa unaowaka moto ukatupwa baharini. Theluthi moja ya bahari ikawa damu,'),
(2021402,69,66,8,9,'theluthi moja ya viumbe vya baharini vikafa na theluthi moja ya meli zikaharibiwa.'),
(2021403,69,66,8,10,'Kisha malaika wa tatu akapiga tarumbeta yake. Na nyota kubwa ikiwaka kama bonge la moto, ikaanguka kutoka mbinguni, na kutua juu ya theluthi moja ya mito na chemchemi za maji.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021404,69,66,8,11,'(Nyota hiyo inaitwa "Uchungu.") Basi, theluthi moja ya maji yakawa machungu; watu wengi wakafa kutokana na maji hayo, kwa sababu yaligeuka kuwa machungu.'),
(2021405,69,66,8,12,'Kisha malaika wa nne akapiga tarumbeta yake. Ndipo theluthi moja ya jua, ya mwezi na ya nyota ikapata pigo; hata mwangaza ukapoteza theluthi moja ya mng`ao wake. Theluthi moja ya mchana ikakosa mwanga, hali kadhalika na theluthi moja ya usiku.'),
(2021406,69,66,8,13,'Kisha nikatazama, nikasikia tai akiruka juu kabisa angani anasema kwa sauti kubwa, "Ole, ole, ole kwa wanaoishi duniani wakati malaika watatu waliobaki watakapopiga tarumbeta zao!"'),
(2021407,69,66,9,1,'Kisha malaika wa tano akapiga tarumbeta yake. Nami nikaona nyota iliyokuwa imeanguka juu ya nchi kutoka mbinguni. Nayo ikapewa ufunguo wa shimo la Kuzimu.'),
(2021408,69,66,9,2,'Basi, nyota hiyo ikafungua shimo la Kuzimu, kukatoka moshi wa tanuru kubwa. Jua na anga vikatiwa giza kwa moshi huo wa Kuzimu.'),
(2021409,69,66,9,3,'Nzige wakatoka katika moshi huo, wakaingia duniani wakapewa nguvu kama ya ng`e.'),
(2021410,69,66,9,4,'Wakaamrishwa wasiharibu nyasi za nchi wala majani wala miti yoyote, bali wawaharibu wale tu ambao hawakupigwa mhuri wa Mungu katika paji la uso.'),
(2021411,69,66,9,5,'Nzige hao hawakuruhusiwa kuwaua watu, ila kuwatesa tu kwa muda wa miezi mitano. Maumivu watakayosababisha ni kama maumivu yanayompata mtu wakati anapoumwa na ng`e.'),
(2021412,69,66,9,6,'Muda huo watu watatafuta kifo lakini hawatakipata; watatamani kufa lakini kifo kitawakimbia.'),
(2021413,69,66,9,7,'Kwa kuonekana, nzige hao walikuwa kama farasi waliowekwa tayari kwa vita. Juu ya vichwa vyao walikuwa na taji zilizo kama za dhahabu, na nyuso zao zilikuwa kama za binadamu.'),
(2021414,69,66,9,8,'Nywele zao zilikuwa kama nywele za wanawake, na meno yao yalikuwa kama meno ya simba.'),
(2021415,69,66,9,9,'Vifua vyao vilikuwa vimefunikwa kitu kama ngao ya chuma. Sauti ya mabawa yao ilikuwa kama sauti ya msafara wa magari ya farasi wengi wanaokimbilia vitani.'),
(2021416,69,66,9,10,'Walikuwa na mikia na miiba kama ng`e, na kwa mikia hiyo, walikuwa na nguvu ya kuwadhuru watu kwa muda wa miezi mitano.'),
(2021417,69,66,9,11,'Tena wanaye mfalme anayewatawala, naye ndiye malaika wa kuzimu; jina lake kwa Kiebrania ni Abadoni, na kwa Kigiriki ni Apolioni, yaani mwangamizi.'),
(2021418,69,66,9,12,'Maafa ya kwanza yamepita; bado mengine mawili yanafuata.'),
(2021419,69,66,9,13,'Kisha malaika wa sita akapiga tarumbeta yake. Nami nikasikia sauti moja kutoka katika pembe nne za madhabahu ya dhahabu iliyokuwa mbele ya Mungu.'),
(2021420,69,66,9,14,'Sauti hiyo ikamwambia huyo malaika wa sita mwenye tarumbeta, "Wafungulie malaika wanne waliofungwa kwenye mto mkubwa `Eufrate!"`'),
(2021421,69,66,9,15,'Naye akawafungulia malaika hao wanne ambao walikuwa wametayarishwa kwa ajili ya saa hiyo ya siku ya mwezi huo, wa mwaka huohuo, kuua theluthi moja ya wanaadamu.'),
(2021422,69,66,9,16,'Nilisikia idadi ya majeshi wapanda farasi ilikuwa milioni mia mbili.'),
(2021423,69,66,9,17,'Hivi ndivyo nilivyowaona hao farasi na wapanda farasi katika hiyo njozi: Walikuwa na ngao vifuani zilizokuwa moto mtupu, zenye rangi ya samawati na njano kama kiberiti. Vichwa vya hao farasi vilikuwa kama vya simba; na moto, moshi, na kiberiti vilikuwa vinatoka kinywani mwao.'),
(2021424,69,66,9,18,'Theluthi moja ya wanaadamu waliuawa kwa mabaa hayo matatu yaani, moto, moshi na kiberiti, yaliyokuwa yanatoka katika vinywa vyao;'),
(2021425,69,66,9,19,'maana nguvu ya farasi hao ilikuwa vinywani mwao na katika mikia yao. Mikia yao ilikuwa na vichwa kama nyoka, na waliitumia hiyo kuwadhuru watu.'),
(2021426,69,66,9,20,'Wanaadamu wengine waliobaki ambao hawakuuawa na mabaa hayo, hawakugeuka na kuviacha vitu walivyokuwa wametengeneza kwa mikono yao wenyewe; bali wakaendelea kuabudu pepo, sanamu za dhahabu, fedha, shaba, mawe na miti, vitu ambavyo haviwezi kuona, kusikia wala kutembea.'),
(2021427,69,66,9,21,'Wala hawakutubu na kuacha kufanya mauaji, uchawi, uzinzi, na wizi.'),
(2021428,69,66,10,1,'Kisha nikamwona malaika mwingine mwenye nguvu akishuka kutoka mbinguni. Alikuwa amevikwa wingu, na upinde wa mvua kichwani mwake. Uso wake ulikuwa kama jua, na miguu yake ilikuwa kama moto.'),
(2021429,69,66,10,2,'Mikononi mwake alishika kitabu kidogo kimefunguliwa. Aliweka mguu wake wa kulia juu ya bahari, na wa kushoto juu ya nchi kavu,'),
(2021430,69,66,10,3,'na kuita kwa sauti kubwa kama ya mngurumo wa simba. Alipopaaza sauti, ngurumo saba ziliitikia kwa kishindo.'),
(2021431,69,66,10,4,'Na hizo ngurumo saba ziliposema, mimi nikataka kuandika. Lakini nikasikia sauti kutoka mbinguni: "Maneno ya ngurumo hizo saba ni siri; usiyaandike!"'),
(2021432,69,66,10,5,'Kisha yule malaika niliyemwona akisimama juu ya bahari na juu ya nchi kavu akainua mkono wake wa kulia juu mbinguni,'),
(2021433,69,66,10,6,'akaapa kwa jina la Mungu aishiye milele na milele, Mungu aliyeumba mbingu na vyote vilivyomo, bahari na vyote vilivyomo, dunia na vyote vilivyomo. Akasema, "Wakati wa kusubiri zaidi umekwisha!'),
(2021434,69,66,10,7,'Lakini wakati ule malaika wa saba atakapotoa sauti yake, wakati atakapopiga tarumbeta yake, Mungu atakamilisha mpango wake wa siri kama alivyowatangazia watumishi wake manabii."'),
(2021435,69,66,10,8,'Kisha ile sauti niliyokuwa nimeisikia kutoka mbinguni pale awali ikasema nami tena: "Nenda ukakichukue kile kitabu kilichofunguliwa, kilicho mkononi mwa malaika asimamaye juu ya bahari na juu ya nchi kavu."'),
(2021436,69,66,10,9,'Basi, nikamwendea huyo malaika, nikamwambia anipe hicho kitabu kidogo. Naye akaniambia, "Kichukue, ukile; kinywani mwako kitakuwa kitamu kama asali, lakini tumboni kitakuwa kichungu!"'),
(2021437,69,66,10,10,'Basi, nikakichukua kitabu hicho kidogo kutoka mkononi mwa huyo malaika, nikakila; nacho kilikuwa kitamu kinywani mwangu kama asali, lakini nilipokimeza kikawa kichungu tumboni mwangu.'),
(2021438,69,66,10,11,'Kisha nikaambiwa, "Inakubidi tena kutangaza ujumbe wa Mungu kuhusu watu wengi, mataifa, watu wa lugha nyingi na wafalme!"'),
(2021439,69,66,11,1,'Kisha nikapewa mwanzi uliokuwa kama kijiti cha kupimia, nikaambiwa, "Inuka, ukalipime Hekalu la Mungu, madhabahu ya kufukizia ubani, na ukawahesabu watu wanaoabudu ndani ya Hekalu.'),
(2021440,69,66,11,2,'Lakini uache ukumbi ulio nje ya Hekalu; usiupime, maana huo umekabidhiwa watu wa mataifa mengine, ambao wataukanyanga mji Mtakatifu kwa muda wa miezi arobaini na miwili.'),
(2021441,69,66,11,3,'Nami nitawatuma mashahidi wangu wawili ili watangaze ujumbe wa Mungu kwa muda huo wa siku elfu moja mia mbili na sitini wakiwa wamevaa mavazi ya magunia."'),
(2021442,69,66,11,4,'Hao mashahidi wawili ni miti miwili ya Mizeituni na taa mbili zinazosimama mbele ya Bwana wa dunia.'),
(2021443,69,66,11,5,'Kama mtu akijaribu kuwadhuru, moto hutoka kinywani mwao na kuwaangamiza adui zao; na kila mtu atakayejaribu kuwadhuru atakufa namna hiyo.'),
(2021444,69,66,11,6,'Hao wanayo mamlaka ya kufunga anga, mvua isinyeshe wakati wanapotangaza ujumbe wa Mungu. Tena wanayo mamlaka ya kuzigeuza chemchemi zote za maji ziwe damu, na ya kusababisha maafa ya kila namna duniani kila mara wapendavyo.'),
(2021445,69,66,11,7,'Lakini wakisha maliza kutangaza ujumbe huo, mnyama atokaye shimoni kuzimu atapigana nao, atawashinda na kuwaua.'),
(2021446,69,66,11,8,'Maiti zao zitabaki katika barabara za mji mkuu ambapo Bwana wao alisulubiwa; jina la kupanga la mji huo ni Sodoma au Misri.'),
(2021447,69,66,11,9,'Watu wa kila kabila, lugha, taifa na rangi wataziangalia maiti hizo kwa muda wa siku tatu na nusu, na hawataruhusu zizikwe.'),
(2021448,69,66,11,10,'Watu waishio duniani watafurahia kifo cha hao wawili. Watafanya sherehe na kupelekeana zawadi maana manabii hawa wawili walikuwa wamewasumbua mno watu wa dunia.'),
(2021449,69,66,11,11,'Lakini baada ya zile siku tatu na nusu pumzi ya uhai kutoka kwa Mungu iliwaingia, nao wakasimama; wote waliowaona wakaingiwa na hofu kuu.'),
(2021450,69,66,11,12,'Kisha hao manabii wawili wakasikia sauti kubwa kutoka mbinguni ikiwaambia, "Njoni hapa juu!" Nao wakapanda juu mbinguni katika wingu, maadui wao wakiwa wanawatazama.'),
(2021451,69,66,11,13,'Wakati huohuo, kukatokea tetemeko kubwa la ardhi, sehemu moja ya kumi ya ardhi ikaharibiwa. Watu elfu saba wakauawa kwa tetemeko hilo la ardhi. Watu waliosalia wakaogopa sana, wakamtukuza Mungu wa mbinguni.'),
(2021452,69,66,11,14,'Maafa ya pili yamepita; lakini tazama! Maafa ya tatu yanafuata hima.'),
(2021453,69,66,11,15,'Kisha malaika wa saba akapiga tarumbeta yake. Na sauti kuu zikasikika mbinguni zikisema, "Sasa utawala juu ya ulimwengu ni wa Bwana wetu na Kristo wake. Naye atatawala milele na milele!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021454,69,66,11,16,'Kisha wale wazee ishirini na wanne walioketi mbele ya Mungu katika viti vyao vya enzi, wakaanguka kifudifudi, wakamwabudu Mungu,'),
(2021455,69,66,11,17,'wakisema: "Bwana Mungu Mwenye uwezo, uliyeko na uliyekuwako! Tunakushukuru, maana umetumia nguvu yako kuu ukaanza kutawala!'),
(2021456,69,66,11,18,'Watu wa mataifa waliwaka hasira, maana wakati wa ghadhabu yako umefika, wakati wa kuwahukumu wafu. Ndio wakati wa kuwatuza watumishi wako manabii, watu wako na wote wanaolitukuza jina lako, wakubwa kwa wadogo. Ni wakati wa kuwaangamiza wale wanaoangamiza dunia."'),
(2021457,69,66,11,19,'Hekalu la Mungu mbinguni likafunguliwa, na Sanduku la Agano lake likaonekana Hekaluni mwake. Kisha kukatokea umeme, sauti, ngurumo, tetemeko la ardhi, na mvua kubwa ya mawe.'),
(2021458,69,66,12,1,'Kisha ishara kubwa ikaonekana mbinguni. Palikuwa hapo mwanamke aliyevikwa jua, na mwezi chini ya miguu yake, na taji ya nyota kumi na mbili juu ya kichwa chake!'),
(2021459,69,66,12,2,'Alikuwa mja mzito, na akapaaza sauti kwa maumivu na uchungu wa kujifungua mtoto.'),
(2021460,69,66,12,3,'Ishara nyingine ikatokea mbinguni: joka kubwa jekundu na lenye pembe kumi na vichwa saba; na kila kichwa kilikuwa na taji.'),
(2021461,69,66,12,4,'Joka hilo liliburuta kwa mkia wake theluthi moja ya nyota za anga na kuzitupa duniani. Nalo lilisimama mbele ya huyo mama aliyekuwa karibu kujifungua mtoto, tayari kabisa kummeza mtoto, mara tu atakapozaliwa.'),
(2021462,69,66,12,5,'Kisha mama huyo akajifungua mtoto wa kiume, ambaye atayatawala mataifa yote kwa fimbo ya chuma. Lakini mtoto akanyakuliwa na kupelekwa kwa Mungu na kwenye kiti chake cha enzi.'),
(2021463,69,66,12,6,'Huyo mama akakimbilia jangwani, ambako Mungu alikuwa amemtayarishia mahali pa usalama ambapo angehifadhiwa kwa muda wa siku elfu moja mia mbili na sitini.'),
(2021464,69,66,12,7,'Kisha kukazuka vita mbinguni: Mikaeli na malaika wake walipigana na hilo joka, nalo likawashambulia pamoja na malaika wake.'),
(2021465,69,66,12,8,'Lakini joka hilo halikuweza kuwashinda, na hatimaye hapakuwa tena na nafasi mbinguni kwa ajili yake na malaika wake.'),
(2021466,69,66,12,9,'Basi, joka hilo kuu likatupwa nje. Joka hilo ndiye yule nyoka wa kale ambaye huitwa pia Ibilisi au Shetani. Ndiye anayeudanganya ulimwengu wote. Naam, alitupwa duniani, na malaika wake wote pamoja naye.'),
(2021467,69,66,12,10,'Kisha nikasikia sauti kubwa kutoka mbinguni ikisema: "Sasa ukombozi utokao kwa Mungu umefika! Nguvu na Utawala wa Mungu wetu umedhihirika. Na Kristo wake ameonyesha mamlaka yake! Maana yule mdhalimu wa ndugu zetu, aliyesimama mbele ya Mungu akiwashtaki usiku na mchana, sasa ametupwa nje.'),
(2021468,69,66,12,11,'Ndugu zetu wameshinda kwa damu ya Mwanakondoo na kwa nguvu ya ukweli walioutangaza; maana hawakuyathamini maisha yao kuwa kitu sana, wakawa tayari kufa.'),
(2021469,69,66,12,12,'Kwa sababu hiyo, furahini enyi mbingu na vyote vilivyomo ndani yenu. Lakini, ole wenu nchi na bahari, maana Ibilisi amewajieni akiwa na ghadhabu kuu, kwa sababu anajua kwamba siku zake zilizobakia ni chache."'),
(2021470,69,66,12,13,'Joka lilipotambua kwamba limetupwa chini duniani, likaanza kumwinda yule mama aliyekuwa amejifungua mtoto wa kiume.'),
(2021471,69,66,12,14,'Lakini mama huyo akapewa mabawa mawili ya tai apate kuruka mbali sana na hilo joka, mpaka mahali, pake jangwani ambapo angehifadhiwa salama kwa muda wa miaka mitatu na nusu.'),
(2021472,69,66,12,15,'Basi, joka likatapika maji mengi kama mto, yakamfuata huyo mama nyuma ili yamchukue.'),
(2021473,69,66,12,16,'Lakini nchi ikamsaidia huyo mama: ikajifunua kama mdomo na kuyameza maji hayo yaliyotoka kinywani mwa hilo joka.'),
(2021474,69,66,12,17,'Basi, joka hilo likamkasirikia huyo mama, likajiondokea, likaenda kupigana na wazawa wengine wa huyo mama, yaani wote wanaotii amri za Mungu na kuuzingatia ukweli wa Yesu.'),
(2021475,69,66,12,18,'Na likajisimamia ukingoni mwa bahari.'),
(2021476,69,66,13,1,'Kisha nikaona mnyama mmoja akitoka baharini. Alikuwa na vichwa saba na pembe kumi, na kila pembe ilikuwa na taji. Jina la kashfa lilikuwa limeandikwa juu ya vichwa hivyo.'),
(2021477,69,66,13,2,'Mnyama huyo niliyemwona alikuwa kama chui; miguu yake ilikuwa kama ya dubu, na kinywa chake kama cha simba. Lile joka likampa huyo mnyama nguvu yake, kiti chake cha enzi na uwezo mkuu.'),
(2021478,69,66,13,3,'Kichwa kimojawapo cha huyo mnyama kilionekana kama kilikwisha jeruhiwa vibaya sana, lakini jeraha hilo lilikuwa limepona. Dunia nzima ilishangazwa na huyo mnyama na kumfuata.'),
(2021479,69,66,13,4,'Watu wote wakaliabudu lile joka kwa sababu lilimpa huyo mnyama uwezo wake. Wakamwabudu pia huyo mnyama wakisema, "Nani aliye kama huyu mnyama? Ni nani awezaye kupigana naye?"'),
(2021480,69,66,13,5,'Kisha huyo mnyama akaruhusiwa kusema maneno ya kujigamba na kumkufuru Mungu; akaruhusiwa kuwa na mamlaka kwa muda wa miezi arobaini na miwili.'),
(2021481,69,66,13,6,'Basi, akaanza kumtukana Mungu, kulitukana jina lake, makao yake, na wote wakaao mbinguni.'),
(2021482,69,66,13,7,'Aliruhusiwa kuwapiga vita na kuwashinda watu wa Mungu. Alipewa mamlaka juu ya watu wa kila kabila, ukoo, lugha na taifa.'),
(2021483,69,66,13,8,'Wote waishio duniani watamwabudu isipokuwa tu wale ambao majina yao yameandikwa tangu mwanzo wa ulimwengu katika kitabu cha uzima cha Mwanakondoo aliyechinjwa.'),
(2021484,69,66,13,9,'"Aliye na masikio, na asikie!'),
(2021485,69,66,13,10,'Waliokusudiwa kuchukuliwa mateka lazima watatekwa; waliokusudiwa kuuawa kwa upanga lazima watauawa kwa upanga. Kutokana na hayo ni lazima watu wa Mungu wawe na uvumilivu na imani."'),
(2021486,69,66,13,11,'Kisha nikamwona mnyama mwingine anatoka ardhini. Alikuwa na pembe mbili kama pembe za kondoo, na aliongea kama joka.'),
(2021487,69,66,13,12,'Alikuwa na mamlaka kamili kutoka kwa yule mnyama wa kwanza, na akautumia uwezo huo mbele ya huyo mnyama. Akailazimisha dunia yote na wote waliomo humo kumwabudu huyo mnyama wa kwanza ambaye alikuwa na jeraha la kifo lililokuwa limepona.'),
(2021488,69,66,13,13,'Basi, huyu mnyama wa pili akafanya miujiza mikubwa hata akasababisha moto kutoka mbinguni ushuke duniani mbele ya watu.'),
(2021489,69,66,13,14,'Aliwapotosha wakazi wa dunia kwa miujiza hiyo aliyojaliwa kutenda mbele ya mnyama wa kwanza. Aliwaambia wakazi wa dunia watengeneze sanamu kwa heshima ya yule mnyama aliyekuwa amejeruhiwa kwa upanga lakini akaishi tena.'),
(2021490,69,66,13,15,'Kisha alijaliwa kuipulizia uhai hiyo sanamu ya yule mnyama wa kwanza, hata ikaweza kuongea na kuwaua watu wote ambao hawakuiabudu.'),
(2021491,69,66,13,16,'Aliwalazimisha wote, wadogo na wakubwa, matajiri na maskini, watu huru na watumwa, watiwe alama juu ya mikono yao ya kulia au juu ya paji za nyuso zao.'),
(2021492,69,66,13,17,'Akapiga marufuku mtu yeyote kununua au kuuza kitu isipokuwa tu mtu aliyetiwa alama hiyo, yaani jina la yule mnyama au tarakimu ya jina hilo.'),
(2021493,69,66,13,18,'Hapa ni lazima kutumia ujasiri! Mwenye akili anaweza kufafanua maana ya tarakimu ya mnyama huyo, maana ni tarakimu yenye maana ya mtu fulani. Tarakimu hiyo ni mia sita sitini na sita.'),
(2021494,69,66,14,1,'Kisha nikaona mlima Sioni, na Mwanakondoo amesimama juu yake; pamoja naye walikuwa watu mia moja arobaini na nne elfu ambao juu ya paji za nyuso zao walikuwa wameandikwa jina la Mwanakondoo na jina la Baba yake.'),
(2021495,69,66,14,2,'Basi, nikasikia sauti kutoka mbinguni, sauti iliyokuwa kama sauti ya maji mengi na kama sauti ya ngurumo kubwa. Sauti niliyosikia ilikuwa kama sauti ya wachezaji muziki wakipiga vinubi vyao.'),
(2021496,69,66,14,3,'Walikuwa wanaimba wimbo mpya mbele ya kiti cha enzi na mbele ya wale viumbe hai wanne na wale wazee. Hakuna mtu aliyeweza kujifunza wimbo huo isipokuwa hao watu mia moja arobaini na nne elfu waliokombolewa duniani.'),
(2021497,69,66,14,4,'Watu hao ndio wale waliojiweka safi kwa kutoonana kimwili na wanawake, nao ni mabikira. Wao humfuata Mwanakondoo kokote aendako. Wamekombolewa kutoka miongoni mwa binadamu wengine, wakawa wa kwanza kutolewa kwa Mungu na kwa Mwanakondoo.'),
(2021498,69,66,14,5,'Hawakupata kamwe kuwa waongo; hawana hatia yoyote.'),
(2021499,69,66,14,6,'Kisha nikamwona malaika mwingine anaruka juu angani akiwa na Habari Njema ya milele ya Mungu, aitangaze kwa watu wote waishio duniani, kwa mataifa yote, makabila yote, watu wa lugha zote na rangi zote.'),
(2021500,69,66,14,7,'Akasema kwa sauti kubwa, "Mcheni Mungu na kumtukuza! Maana saa imefika ya kutoa hukumu yake. Mwabuduni yeye aliyeumba mbingu na nchi, bahari na chemchemi za maji."'),
(2021501,69,66,14,8,'Malaika wa pili alimfuata huyo wa kwanza akisema, "Ameanguka! Naam, Babuloni mkuu ameanguka! Babuloni ambaye aliwapa mataifa yote wainywe divai yake--divai kali ya uzinzi wake!"'),
(2021502,69,66,14,9,'Na malaika wa tatu aliwafuata hao wawili akisema kwa sauti kubwa, "Yeyote anayemwabudu yule mnyama na sanamu yake na kukubali kutiwa alama yake juu ya paji la uso wake au juu ya mkono wake,'),
(2021503,69,66,14,10,'yeye mwenyewe atakunywa divai ya ghadhabu ya Mungu, ambayo imemiminwa katika kikombe cha ghadhabu yake bila kuchanganywa na maji. Mtu huyo atateseka ndani ya moto na kiberiti mbele ya malaika watakatifu na mbele ya Mwanakondoo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021504,69,66,14,11,'Moshi wa moto unaowatesa kupanda juu milele na milele. Watu hao waliomwabudu huyo mnyama na sanamu yake, na kutiwa alama ya jina lake, hawatakuwa na nafuu yoyote usiku na mchana."'),
(2021505,69,66,14,12,'Kutokana na hayo, ni lazima watu wa Mungu, yaani watu wanaotii amri ya Mungu na kumwamini Yesu, wawe na uvumilivu.'),
(2021506,69,66,14,13,'Kisha nikasikia sauti kutoka mbinguni ikisema, "Andika! Heri watu ambao tangu sasa wanakufa wakiwa wameungana na Bwana." Naye Roho asema, "Naam! Watapumzika kutoka taabu zao; maana matunda ya jasho lao yatawafuata."'),
(2021507,69,66,14,14,'Kisha nikatazama, na kumbe palikuwapo wingu jeupe hapo. Na juu ya wingu hilo kulikuwa na kiumbe kama mtu. Alikuwa amevaa taji ya dhahabu kichwani, na kushika mundu mkononi mwake.'),
(2021508,69,66,14,15,'Kisha malaika mwingine akatoka Hekaluni, na kwa sauti kubwa akamwambia yule aliyekuwa amekaa juu ya wingu, "Tafadhali, tumia mundu wako ukavune mavuno, maana wakati wa mavuno umefika; mavuno ya dunia yameiva."'),
(2021509,69,66,14,16,'Basi, yule aliyekuwa amekaa juu ya wingu akautupa mundu wake duniani, na mavuno ya dunia yakavunwa.'),
(2021510,69,66,14,17,'Kisha malaika mwingine akatoka katika Hekalu mbinguni akiwa na mundu wenye makali.'),
(2021511,69,66,14,18,'Kisha malaika mwingine msimamizi wa moto, akatoka madhabahuni akamwambia kwa sauti kubwa yule malaika mwenye mundu wenye makali, "Nawe tia huo mundu wako mkali, ukakate vichala vya mizabibu ya dunia, maana zabibu zake zimeiva!"'),
(2021512,69,66,14,19,'Basi, malaika huyo akautupa mundu wake duniani, akakata zabibu za dunia, akazitia ndani ya chombo kikubwa cha kukamulia zabibu, chombo cha ghadhabu ya Mungu.'),
(2021513,69,66,14,20,'Zabibu zikakamuliwa ndani ya hilo shinikizo lililoko nje ya mji, na damu ikatoka katika shinikizo hilo mtiririko mrefu kiasi cha mita mia tatu na kina chake kiasi cha mita mia mbili.'),
(2021514,69,66,15,1,'Kisha nikaona ishara nyingine mbinguni, kubwa na ya kushangaza. Palikuwa hapo malaika saba wenye mabaa makubwa saba ya mwisho. Kwa mabaa hayo makubwa saba, ghadhabu ya Mungu imekamilishwa.'),
(2021515,69,66,15,2,'Kisha nikaona kitu kama bahari ya kioo, imechanganywa na moto. Nikawaona pia wale watu waliomshinda yule mnyama na sanamu yake na ambaye jina lake lilitajwa kwa ile tarakimu. Watu hao walikuwa wamesimama kando ya hiyo bahari ya kioo, wakiwa na vinubi walivyopewa na Mungu.'),
(2021516,69,66,15,3,'Walikuwa wakiimba wimbo wa Mose, mtumishi wa Mungu, na wimbo wa Mwanakondoo: "Bwana Mungu Mwenye Uwezo, matendo yako ni makuu mno! Ewe Mfalme wa mataifa, njia zako ni za haki na za kweli!'),
(2021517,69,66,15,4,'Bwana, ni nani asiyekucha wewe? Nani asiyelitukuza jina lako? Wewe peke yako ni Mtakatifu. Mataifa yote yatakujia na kukuabudu maana matendo yako ya haki yameonekana na wote."'),
(2021518,69,66,15,5,'Baada ya hayo nikaona Hekalu limefunguliwa mbinguni, na ndani yake hema ionyeshayo kuwapo kwa Mungu.'),
(2021519,69,66,15,6,'Basi, wale malaika saba wenye mabaa saba wakatoka humo Hekaluni, wakiwa wamevaa nguo za kitani safi zenye kung`aa, na kanda za dhahabu vifuani mwao.'),
(2021520,69,66,15,7,'Kisha, mmojawapo wa vile viumbe vinne akawapa hao malaika saba mabakuli ya dhahabu yaliyojaa ghadhabu ya Mungu, aishiye milele na milele.'),
(2021521,69,66,15,8,'Hekalu likajaa moshi uliosababishwa na utukufu na nguvu ya Mungu, na hakuna mtu aliyeweza kuingia Hekaluni mpaka mwisho wa mabaa makubwa saba ya wale malaika saba.'),
(2021522,69,66,16,1,'Kisha nikasikia sauti kubwa kutoka Hekaluni ikiwaambia wale malaika saba, "Nendeni mkamwage mabakuli hayo saba ya ghadhabu ya Mungu duniani."'),
(2021523,69,66,16,2,'Basi, malaika wa kwanza akaenda akamwaga bakuli lake juu ya nchi. Mara madonda mabaya na ya kuumiza sana yakawapata wote waliokuwa na alama ya yule mnyama, na wale walioiabudu sanamu yake.'),
(2021524,69,66,16,3,'Kisha malaika wa pili akamwaga bakuli lake baharini. Nayo bahari ikawa damu tupu kama damu ya mtu aliyekufa, na viumbe vyote hai baharini vikafa.'),
(2021525,69,66,16,4,'Malaika wa tatu akamwaga bakuli lake katika mito na chemchemi za maji, navyo vikageuka damu.'),
(2021526,69,66,16,5,'Nikamsikia malaika msimamizi wa maji akisema, "Ewe mtakatifu, Uliyeko na uliyekuwako! Wewe ni mwenye haki katika hukumu hii uliyotoa.'),
(2021527,69,66,16,6,'Maana waliimwaga damu ya watu wako na ya manabii, nawe umewapa damu wainywe; wamestahili hivyo!"'),
(2021528,69,66,16,7,'Kisha nikasikia sauti madhabahuni ikisema, "Naam, Bwana Mungu Mwenye Uwezo! Hukumu zako ni za kweli na haki!"'),
(2021529,69,66,16,8,'Kisha malaika wa nne akamwaga bakuli lake juu ya jua. Jua likapewa nguvu ya kuwachoma watu kwa moto wake.'),
(2021530,69,66,16,9,'Basi, watu wakaunguzwa vibaya sana; wakamtukana Mungu aliye na uwezo juu ya mabaa hayo makubwa. Lakini hawakuziacha dhambi zao na kumtukuza Mungu.'),
(2021531,69,66,16,10,'Kisha malaika wa tano akamwaga bakuli lake juu ya makao makuu ya yule mnyama. Giza likauvamia utawala wake, watu wakauma ndimi zao kwa sababu za maumivu,'),
(2021532,69,66,16,11,'wakamtukana Mungu wa mbinguni kwa sababu ya maumivu yao na madonda yao. Lakini hawakuyaacha matendo yao mabaya.'),
(2021533,69,66,16,12,'Kisha malaika wa sita akamwaga bakuli lake juu ya mto mkubwa uitwao Eufrate. Maji yake yakakauka, na hivyo njia ilitengenezwa kwa ajili ya wafalme wa mashariki.'),
(2021534,69,66,16,13,'Kisha nikaona pepo wabaya watatu walio kama vyura, wakitoka kinywani mwa yule joka, kinywani mwa yule mnyama, na kinywani mwa yule nabii wa uongo.'),
(2021535,69,66,16,14,'Hawa ndio roho za pepo wafanyao miujiza. Ndio wanaokwenda kwa wafalme wa ulimwengu wote na kuwakusanya pamoja kwa ajili ya vita kuu Siku ile ya Mungu Mwenye Uwezo.'),
(2021536,69,66,16,15,'"Sikiliza! Mimi naja kama mwizi! Heri mtu akeshaye na kuvaa nguo zake ili asije akaenda uchi huko na huko mbele ya watu."'),
(2021537,69,66,16,16,'Basi, roho hao wakawakusanya hao wafalme mahali paitwapo kwa Kiebrania Harmagedoni.'),
(2021538,69,66,16,17,'Kisha malaika wa saba akamwaga bakuli lake hewani. Sauti kubwa ikasikika kutoka kwenye kiti cha enzi, Hekaluni, ikisema, "Mwisho umefika!"'),
(2021539,69,66,16,18,'Kukatokea umeme, kelele, ngurumo na tetemeko kubwa la ardhi ambalo halijapata kutokea tangu Mungu alipomuumba mtu.'),
(2021540,69,66,16,19,'Mji ule mkuu ukapasuliwa sehemu tatu, nayo miji ya mataifa ikateketea. Babuloni, mji mkuu, haukusahauliwa na Mungu. Aliunywesha kikombe cha divai ya ghadhabu yake kuu.'),
(2021541,69,66,16,20,'Visiwa vyote vikatoweka, nayo milima haikuonekena tena.'),
(2021542,69,66,16,21,'Mvua ya mawe makubwa yenye uzito wa kama kilo hamsini kila moja, ikawanyeshea watu. Nao wakamtukana Mungu kwa sababu ya mapigo ya mvua hiyo ya mawe. Naam, pigo la mvua hiyo ya mawe lilikuwa kubwa mno.'),
(2021543,69,66,17,1,'Mmoja wa wale malaika saba waliokuwa na bakuli akaja, akaniambia, "Njoo, mimi nitakuonyesha adhabu aliyopewa yule mzinzi mkuu, mji ule uliojengwa juu ya maji mengi.'),
(2021544,69,66,17,2,'Wafalme wa dunia wamefanya uzinzi pamoja naye; na wakazi wa dunia wamelewa divai ya uzinzi wake."'),
(2021545,69,66,17,3,'Kisha, Roho akanikumba, akaniongoza mpaka jangwani. Huko nikamwona mwanamke ameketi juu ya mnyama mwekundu. Mnyama huyo alikuwa ameandikwa kila mahali majina ya makufuru; alikuwa na vichwa saba na pembe kumi.'),
(2021546,69,66,17,4,'Mwanamke huyo alikuwa amevaa vazi la rangi ya zambarau na nyekundu; alikuwa amejipamba kwa dhahabu, mawe ya thamani na lulu. Mkononi mwake alishika kikombe cha dhahabu ambacho kilikuwa kimejaa machukizo na mambo machafu yanayoonyesha uzinzi wake.'),
(2021547,69,66,17,5,'Alikuwa ameandikwa juu ya paji la uso wake jina la fumbo "Babuloni mkuu, mama wa wazinzi na wa mambo yote ya kuchukiza sana duniani."'),
(2021548,69,66,17,6,'Nikamwona huyo mwanamke amelewa damu ya watu wa Mungu, na damu ya watu waliouawa kwa sababu ya kumtangaza Yesu. Nilipomwona nilishangaa mno.'),
(2021549,69,66,17,7,'Lakini malaika akaniambia, "Kwa nini unashangaa? Mimi nitakuambia maana iliyofichika ya mwanamke huyu na mnyama huyo amchukuaye ambaye ana vichwa saba na pembe kumi.'),
(2021550,69,66,17,8,'Huyo mnyama uliyemwona alikuwa hai hapo awali, lakini sasa amekufa. Hata hivyo, karibu sana atapanda kutoka shimoni kuzimu, lakini ataangamizwa. Wanaoishi duniani watashangaa; naam, watu wote ambao majina yao hayakupata kuandikwa katika kitabu cha uzima tangu mwanzo wa ulimwengu, watashangaa kumwona huyo mnyama ambaye hapo awali, aliishi, kisha akafa na sasa anatokea tena!'),
(2021551,69,66,17,9,'"Hapa panahitaji akili na hekima! Hivyo vichwa saba ni vilima saba, na huyo mwanamke anaketi juu yake. Vichwa hivyo pia ni wafalme saba.'),
(2021552,69,66,17,10,'Kati ya hao wafalme saba, watano wamekwisha angamia, mmoja anatawala bado, na yule mwingine bado hajafika; na atakapofika atabaki kwa muda mfupi.'),
(2021553,69,66,17,11,'Huyo mnyama ambaye alikuwa anaishi hapo awali lakini sasa haishi tena ni mfalme wa nane, naye pia ni miongoni mwa hao saba, na anakwenda zake kuharibiwa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021554,69,66,17,12,'"Zile pembe kumi ulizoziona ni wafalme ambao bado hawajaanza kutawala. Lakini watapewa mamlaka ya kutawala kwa muda wa saa moja pamoja na yule mnyama.'),
(2021555,69,66,17,13,'Shabaha ya hawa kumi ni moja, na watampa yule mnyama nguvu na mamlaka yao yote.'),
(2021556,69,66,17,14,'Watapigana na Mwanakondoo, lakini Mwanakondoo pamoja na wale aliowaita na kuwachagua, ambao ni waaminifu, atawashinda kwa sababu yeye ni Bwana wa mabwana na Mfalme wa wafalme."'),
(2021557,69,66,17,15,'Malaika akaniambia pia, "Yale maji uliyoyaona pale alipokaa yule mzinzi, ni mataifa, watu wa kila rangi na lugha.'),
(2021558,69,66,17,16,'Pembe zile kumi ulizoziona na yule mnyama watamchukia huyo mzinzi. Watachukua kila kitu alicho nacho na kumwacha uchi; watakula nyama yake na kumteketeza kwa moto.'),
(2021559,69,66,17,17,'Maana Mungu ametia mioyoni mwao nia ya kutekeleza shabaha yake, yaani kwa kukubaliana wao kwa wao na kumpa huyo mnyama mamlaka yao ya kutawala, mpaka hapo neno la Mungu litakapotimia.'),
(2021560,69,66,17,18,'"Na yule mwanamke uliyemwona ndio ule mji mkuu unaowatawala wafalme wa dunia."'),
(2021561,69,66,18,1,'Baada ya hayo, nilimwona malaika mwingine akishuka kutoka mbinguni. Alikuwa na uwezo mkuu, na dunia ikamulikwa na mng`ao wake.'),
(2021562,69,66,18,2,'Basi, akapaaza sauti kwa nguvu akisema, "Umeanguka; Babuloni mkuu umeanguka! Sasa umekuwa makao ya mashetani na pepo wachafu; umekuwa makao ya ndege wachafu na wa kuchukiza mno.'),
(2021563,69,66,18,3,'Maana mataifa yote yalileweshwa kwa divai kali ya uzinzi wake, nao wafalme wa dunia wamefanya uzinzi naye. Nao wafanyabiashara wa dunia wametajirika kutokana na anasa zake zisizo na kipimo."'),
(2021564,69,66,18,4,'Kisha nikasikia sauti nyingine kutoka mbinguni ikisema, "Watu wangu, ondokeni kwake, ili msishirikiane naye katika dhambi zake, msije mkaipata adhabu yake.'),
(2021565,69,66,18,5,'Kwa maana dhambi zake zimekuwa nyingi mno, zimelundikana mpaka mbinguni, na Mungu ameyakumbuka maovu yake.'),
(2021566,69,66,18,6,'Mtendeeni kama alivyowatendea ninyi; mlipeni mara mbili kwa yale aliyoyatenda. Jazeni kikombe chake kwa kinywaji kikali mara mbili zaidi ya kile alichowapeni.'),
(2021567,69,66,18,7,'Mpeni mateso na uchungu kadiri ya kujigamba kwake, na kuishi kwake kwa anasa. Maana anajisemea moyoni: `Ninaketi hapa; mimi ni malkia. Mimi si mjane, wala sitapatwa na uchungu!`'),
(2021568,69,66,18,8,'Kwa sababu hiyo mabaa yake yatampata kwa siku moja: ugonjwa, huzuni na njaa. Atachomwa moto, maana Bwana Mungu mwenye kumhukumu ni Mwenye Uwezo."'),
(2021569,69,66,18,9,'Wafalme wa Dunia waliofanya uzinzi naye na kuishi naye maisha ya anasa wataomboleza na kulia wakati watakapoona moshi wa mji huo unaoteketea.'),
(2021570,69,66,18,10,'Wanasimama kwa mbali kwa sababu ya kuogopa mateso yake, na kusema, "Ole! Ole kwako Babuloni, mji maarufu na wenye nguvu! Kwa muda wa saa moja tu adhabu yako imekupata."'),
(2021571,69,66,18,11,'Wafanyabiashara wa dunia watalia na kumfanyia matanga, maana hakuna mtu anayenunua tena bidhaa zao;'),
(2021572,69,66,18,12,'hakuna tena wa kununua dhahabu yao, fedha, mawe ya thamani na lulu, kitani na nguo za rangi ya zambarau, hariri na nguo nyekundu; vyombo vya kila aina ya miti ya pekee, vyombo vya pembe za ndovu, vya miti ya thamani kubwa, vya shaba, chuma na marmari;'),
(2021573,69,66,18,13,'mdalasini, viungo, ubani, manemane, udi, divai, mafuta, unga na ngano, ng`ombe na kondoo, farasi na magari ya kukokotwa, watumwa wao na hata maisha ya watu.'),
(2021574,69,66,18,14,'Wafanyabiashara wanamwambia: "Faida yote uliyotazamia imetoweka, na utajiri na fahari vimekuponyoka; hutaweza kuvipata tena!"'),
(2021575,69,66,18,15,'Wafanya biashara waliotajirika kutokana na mji huo, watasimama mbali kwa sababu ya hofu ya mateso yake, watalalamika na kuomboleza,'),
(2021576,69,66,18,16,'wakisema, "Ole! Ole kwa mji huu mkuu. Ulizoea kuvalia nguo za kitani, za rangi ya zambarau na nyekundu, na kujipamba kwa dhahabu, mawe ya thamani na lulu!'),
(2021577,69,66,18,17,'Kwa saa moja tu utajiri wako umetoweka!" Halafu manahodha wote na wasafiri wao, wanamaji na wote wanaofanya kazi baharini, walisimama kwa mbali,'),
(2021578,69,66,18,18,'na walipouona moshi wa moto ule uliouteketeza, wakalia kwa sauti: "Hakujapata kuwako mji kama mji huu mkuu!"'),
(2021579,69,66,18,19,'Wakajimwagia vumbi juu ya vichwa vyao wakilia kwa sauti na kuomboleza: "Ole! Ole kwako mji mkuu! Ni mji ambamo wote wenye meli zisafirizo baharini walitajirika kutokana na utajiri wake. Kwa muda wa saa moja tu umepoteza kila kitu!"'),
(2021580,69,66,18,20,'Furahi ee mbingu, kwa sababu ya uharibifu wake. Furahini watu wa Mungu, mitume na manabii! Kwa maana Mungu ameuhukumu kwa sababu ya mambo uliyowatenda ninyi!'),
(2021581,69,66,18,21,'Kisha malaika mmoja mwenye nguvu sana akainua jiwe mfano wa jiwe kubwa la kusagia, akalitupa baharini akisema, "Ndivyo, Babuloni atakavyotupwa na kupotea kabisa.'),
(2021582,69,66,18,22,'Sauti za vinubi za muziki, sauti za wapiga filimbi na tarumbeta hazitasikika tena ndani yako. Hakuna fundi wa namna yoyote ile atakayepatikana tena ndani yako; wala sauti ya jiwe la kusagia haitasikika tena ndani yako.'),
(2021583,69,66,18,23,'Mwanga wa taa hautaonekana tena ndani yako; sauti za bwana arusi na bibi arusi hazitasikika tena ndani yako. Wafanyabiashara wako walikuwa wakuu duniani, na kwa uchawi wako mataifa yote yalipotoshwa!"'),
(2021584,69,66,18,24,'Mji huo uliadhibiwa kwani humo mlipatikana damu ya manabii, damu ya watu wa Mungu na damu ya watu wote waliouawa duniani.'),
(2021585,69,66,19,1,'Baada ya hayo nikasikia kitu kama sauti kubwa ya umati wa watu wengi mbinguni ikisema, "Haleluya! Ukombozi, utukufu na nguvu ni mali yake Mungu wetu!'),
(2021586,69,66,19,2,'Maana hukumu yake ni ya kweli na ya haki. Amemhukumu yule mzinzi mkuu ambaye alikuwa ameipotosha dunia kwa uzinzi wake. Amemwadhibu kwa sababu ya kumwaga damu ya watumishi wake!"'),
(2021587,69,66,19,3,'Wakasema, "Asifiwe Mungu! Moshi wa moto unaoteketeza mji huo utapanda juu milele na milele!"'),
(2021588,69,66,19,4,'Na wale wazee ishirini na wanne, na vile viumbe hai vinne, wakajitupa chini, wakamwabudu Mungu aliyeketi juu ya kiti cha enzi wakisema, "Amina! Asifiwe Mungu!"'),
(2021589,69,66,19,5,'Kisha kukatokea sauti kwenye kiti cha enzi: "Msifuni Mungu enyi watumishi wake wote, nyote mnaomcha, wadogo kwa wakubwa."'),
(2021590,69,66,19,6,'Kisha nikasikia kitu kama sauti ya umati mkubwa wa watu na sauti ya maji mengi na ya ngurumo kubwa, ikisema, "Haleluya! Maana Bwana Mungu wetu Mwenye Uwezo ni Mfalme!'),
(2021591,69,66,19,7,'Tufurahi na kushangilia; tumtukuze, kwani wakati wa arusi ya Mwanakondoo umefika, na bibi arusi yuko tayari.'),
(2021592,69,66,19,8,'Amepewa uwezo wa kujivalia nguo ya kitani safi, iliyotakata na yenye kung`aa!" (Nguo hiyo ya kitani safi ni matendo mema ya watu wa Mungu.)'),
(2021593,69,66,19,9,'Kisha malaika akaniambia, "Andika haya: Heri wale walioalikwa kwenye karamu ya arusi ya Mwanakondoo!" Tena akaniambia, "Hayo ni maneno ya kweli ya Mungu."'),
(2021594,69,66,19,10,'Basi, mimi nikaanguka kifudifudi mbele ya miguu yake nikataka kumwabudu. Lakini yeye akaniambia, "Acha! Mimi ni mtumishi tu kama wewe na ndugu zako; sote tunauzingatia ukweli ule alioufunua Yesu. Mwabudu Mungu! Maana ukweli alioufunua Yesu ndio unaowaangazia manabii."'),
(2021595,69,66,19,11,'Kisha nikaona mbingu zimefunguliwa; na huko alikuwako farasi mmoja mweupe, na mpanda farasi wake aliitwa "Mwaminifu" na "Kweli". Huyo huhukumu na kupigana kwa ajili ya haki.'),
(2021596,69,66,19,12,'Macho yake ni kama mwali wa moto, na alikuwa amevaa taji nyingi kichwani. Alikuwa ameandikwa jina ambalo hakuna mtu alijuaye isipokuwa tu yeye mwenyewe.'),
(2021597,69,66,19,13,'Alikuwa amevaa vazi lililokuwa limelowekwa katika damu. Na jina lake huyo ni "Neno la Mungu."'),
(2021598,69,66,19,14,'Majeshi ya mbinguni yalimfuata yakiwa yamepanda farasi weupe na walikuwa wamevaa mavazi ya kitani, meupe na safi.'),
(2021599,69,66,19,15,'Upanga mkali hutoka kinywani mwake, na kwa upanga huo atawashinda mataifa. Yeye ndiye atakayetawala kwa fimbo ya chuma na kuikamua divai katika chombo cha kukamulia zabibu za ghadhabu kuu ya Mungu Mwenye Uwezo.'),
(2021600,69,66,19,16,'Juu ya vazi lake, na juu ya mguu wake, alikuwa ameandikwa jina: "Mfalme wa wafalme na Bwana wa mabwana."'),
(2021601,69,66,19,17,'Kisha nikamwona malaika mmoja amesimama katika jua. Akapaaza sauti na kuwaambia ndege wote waliokuwa wanaruka juu angani, "Njoni! Kusanyikeni pamoja kwa karamu kuu ya Mungu.'),
(2021602,69,66,19,18,'Njoni mkaitafune miili ya wafalme, ya majemadari, ya watu wenye nguvu, ya farasi na wapanda farasi wao; njoni mkaitafune miili ya watu wote: walio huru na watumwa, wadogo na wakubwa."'),
(2021603,69,66,19,19,'Kisha nikaona yule mnyama pamoja na mfalme wa dunia na askari wao wamekusanyika pamoja kusudi wapigane na yule aliyekuwa ameketi juu ya farasi, pamoja na jeshi lake.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021604,69,66,19,20,'Lakini huyo mnyama akachukuliwa mateka, pamoja na nabii wa uongo aliyekuwa akifanya miujiza mbele yake. (Kwa miujiza hiyo, alikuwa amewapotosha wale waliokuwa na chapa ya huyo mnyama, na ambao walikuwa wameiabudu sanamu yake.) Huyo mnyama pamoja na huyo nabii walitupwa wote wawili, wakiwa wazimawazima, ndani ya ziwa linalowaka moto wa kiberiti.'),
(2021605,69,66,19,21,'Majeshi yao yaliuawa kwa upanga uliotoka kinywani mwa yule anayepanda farasi. Ndege wote wakajishibisha kwa nyama zao.'),
(2021606,69,66,20,1,'Kisha nikamwona malaika mmoja anashuka kutoka mbinguni akiwa na ufunguo wa kuzimu na mnyororo mkubwa mkononi mwake.'),
(2021607,69,66,20,2,'Akalikamata lile joka--nyoka wa kale, yaani Ibilisi au Shetani--akalifunga kwa muda wa miaka elfu moja.'),
(2021608,69,66,20,3,'Malaika akalitupa Kuzimu, akaufunga mlango wa kuingilia huko na kuutia mhuri ili lisiweze tena kuyapotosha mataifa mpaka hapo miaka elfu moja itakapotimia. Lakini baada ya miaka hiyo ni lazima lifunguliwe tena, lakini kwa muda mfupi tu.'),
(2021609,69,66,20,4,'Kisha nikaona viti vya enzi na watu walioketi juu yake; watu hao walipewa mamlaka ya hukumu. Niliona pia roho za wale waliokuwa wamenyongwa kwa sababu ya kumtangaza Yesu na kwa sababu ya neno la Mungu. Hawa hawakumwabudu yule mnyama na sanamu yake, wala hawakupigwa alama yake juu ya paji za nyuso zao, au juu ya mikono yao. Walipata tena uhai, wakatawala pamoja na Kristo kwa muda wa miaka elfu moja.'),
(2021610,69,66,20,5,'(Wale wengine waliokufa hawakupata uhai mpaka miaka elfu moja itimie.) Huu ndio ufufuo wa kwanza.'),
(2021611,69,66,20,6,'Wameneemeka sana, tena heri yao wote wanaoshiriki ufufuo huu wa kwanza. Kifo cha pili hakitakuwa na nguvu juu yao; watakuwa makuhani wa Mungu na wa Kristo, na watatawala pamoja naye kwa miaka elfu moja.'),
(2021612,69,66,20,7,'Wakati miaka elfu mia moja itakapotimia, Shetani atafunguliwa kutoka gerezani mwake.'),
(2021613,69,66,20,8,'Basi, atatoka nje, ataanza kuyapotosha mataifa yote yaliyotawanyika kila mahali duniani, yaani Gogu na Magogu. Shetani atawakusanya pamoja kwa ajili ya vita; nao watakuwa wengi kama mchanga wa pwani.'),
(2021614,69,66,20,9,'Walitawanyika katika nchi yote, wakaizunguka kambi ya watu wa Mungu na mji wa Mungu aupendao. Lakini moto ulishuka kutoka mbinguni, ukawaangamiza.'),
(2021615,69,66,20,10,'Ibilisi, aliyekuwa anawapotosha, akatupwa ndani ya ziwa linalowaka moto wa kiberiti, walimo yule mnyama na yule nabii wa uongo, nao watateswa mchana na usiku, milele na milele.'),
(2021616,69,66,20,11,'Kisha nikaona kiti cha enzi kikubwa cheupe, na yule aketiye juu yake. Dunia na mbingu vikatoweka mbele ya macho yake, na havikuonekana tena.'),
(2021617,69,66,20,12,'Kisha nikawaona watu wakubwa na wadogo, wamesimama mbele ya kiti cha enzi, na vitabu vikafunguliwa. Halafu kitabu kingine, yaani kitabu cha uzima, kikafunguliwa pia. Wafu wakahukumiwa kadiri ya matendo yao, kama ilivyoandikwa ndani ya vitabu hivyo.'),
(2021618,69,66,20,13,'Bahari ikawatoa nje wafu waliokuwa ndani yake; kifo na kuzimu vikawatoa nje wafu waliokuwa ndani yao. Kila mmoja akahukumiwa kufuatana na matendo yake.'),
(2021619,69,66,20,14,'Kisha kifo na kuzimu vikatupwa ndani ya ziwa la moto. Ziwa hili la moto ndicho kifo cha pili.'),
(2021620,69,66,20,15,'Mtu yeyote ambaye jina lake halikupatikana limeandikwa katika kitabu cha uzima, alitupwa katika ziwa la moto.'),
(2021621,69,66,21,1,'Kisha nikaona mbingu mpya na dunia mpya. Mbingu ile ya kwanza na dunia ile ya kwanza vilikuwa vimetoweka, nayo bahari pia haikuweko tena.'),
(2021622,69,66,21,2,'Nikaona mji mtakatifu, Yerusalemu mpya, ukishuka kutoka kwa Mungu mbinguni. Ulikuwa umetayarishwa vizuri kama bibi arusi aliyepambwa tayari kukutana na mumewe.'),
(2021623,69,66,21,3,'Kisha nikasikia sauti kubwa kutoka katika kiti cha enzi ikisema, "Tazama! Mungu amefanya makao yake kati ya watu. Atakaa kati yao, nao watakuwa watu wake, naye atakuwa Mungu wao.'),
(2021624,69,66,21,4,'Yeye atayafuta machozi yao yote; maana hakutakuwako tena na kifo, wala uchungu, wala kilio, wala maumivu; maana ile hali ya kale imepita!"'),
(2021625,69,66,21,5,'Kisha yule aliyeketi juu ya kiti cha enzi akasema, "Tazama, nafanya yote mapya." Tena akaniambia, "Andika hili, maana maneno haya ni ya kuaminika na ya kweli!"'),
(2021626,69,66,21,6,'Kisha akaniambia, "Yametimia! Mimi ni Alfa na Omega, Mwanzo na Mwisho. Aliye na kiu nitampa kinywaji cha bure kutoka katika chemchemi ya maji ya uzima.'),
(2021627,69,66,21,7,'Yeyote atakayeshinda atapokea hiki, nami nitakuwa Mungu wake, naye atakuwa mwanangu.'),
(2021628,69,66,21,8,'Lakini watu waoga, wasioamini, wapotovu, wauaji, wazinzi, wachawi, waabudu sanamu, na waongo wote, mahali pao patakuwa ndani ya lile ziwa linalowaka moto na kiberiti; hicho ndicho kifo cha pili."'),
(2021629,69,66,21,9,'Kisha mmoja wa wale malaika saba waliokuwa na yale mabakuli saba yaliyokuwa yamejaa mabaa saba ya mwisho, akaja na kuniambia, "Njoo! Mimi nitakuonyesha bibi arusi, mkewe Mwanakondoo!"'),
(2021630,69,66,21,10,'Basi, Roho akanikumba, naye malaika akanipeleka juu ya mlima mrefu sana. Akanionyesha mji mtakatifu, ukishuka kutoka kwa Mungu mbinguni,'),
(2021631,69,66,21,11,'uking`aa kwa utukufu wa Mungu. Mwangaza wake ulikuwa kama wa jiwe la thamani kubwa kama yaspi, angavu kama kioo.'),
(2021632,69,66,21,12,'Ulikuwa na ukuta mrefu na mkubwa, wenye milango kumi na miwili, na malaika wanangojea kumi na wawili. Majina ya wangoja milango kumi na mawili ya Israeli yalikuwa yameandikwa juu ya milango hiyo.'),
(2021633,69,66,21,13,'Kila upande ulikuwa na milango mitatu: upande wa mashariki, milango mitatu, kaskazini milango mitatu, kusini milango mitatu na magharibi milango mitatu.'),
(2021634,69,66,21,14,'Kuta za mji huo zilikuwa zimejengwa juu ya mawe ya msingi kumi na mawili, na juu ya mawe hayo yalikuwa yameandikwa majina na mitume kumi na wawili wa Mwanakondoo.'),
(2021635,69,66,21,15,'Basi, yule malaika aliyekuwa anasema nami alikuwa na kijiti cha dhahabu cha kupimia, kwa ajili ya kuupima huo mji, milango yake na kuta zake.'),
(2021636,69,66,21,16,'Mji wenyewe ulikuwa wa mraba, upana na urefu wake sawa. Basi, malaika akaupima mji huo kwa kijiti chake: ulikuwa na urefu, upana na urefu wa kwenda juu, kama kilomita elfu mbili na mia nne.'),
(2021637,69,66,21,17,'Kisha akaupima ukuta wake pia; nao ulikuwa mita sitini kwa kipimo cha macho cha kibinadamu ambacho malaika alitumia.'),
(2021638,69,66,21,18,'Ukuta huo ulikuwa umejengwa kwa mawe mekundu ya thamani, na mji wenyewe ulikuwa umejengwa kwa dhahabu safi, angavu kama kioo.'),
(2021639,69,66,21,19,'Mawe ya msingi wa ukuta huo yalikuwa yamepambwa kwa kila aina ya mawe ya thamani. Jiwe la kwanza la msingi lilikuwa jiwe la thamani jekundu, la pili yakuti samawati, la tatu kalkedoni, la nne zamaradi,'),
(2021640,69,66,21,20,'la tano sardoniki, la sita akiki, la saba krisolito, la nane zabarijadi, la tisa topazi, la kumi krisopraso, la kumi na moja yasinto, na la kumi na mbili amethisto.'),
(2021641,69,66,21,21,'Na ile milango kumi na miwili ilikuwa lulu kumi na mbili; kila mlango ulikuwa umetengenezwa kwa lulu moja. Barabara kuu ya mji ilikuwa imetengenezwa kwa dhahabu safi, angavu kama kioo.'),
(2021642,69,66,21,22,'Sikuona hekalu katika mji huo, maana Bwana Mungu Mwenye Uwezo na yule Mwanakondoo ndio Hekalu lake.'),
(2021643,69,66,21,23,'Mji huo hauhitaji jua wala mwezi kuangazia, maana utukufu wa Mungu huuangazia, na taa yake ni yule Mwanakondoo.'),
(2021644,69,66,21,24,'Watu wa mataifa watatembea katika mwanga wake, na wafalme wa dunia watauletea utajiri wao.'),
(2021645,69,66,21,25,'Milango ya mji huo itakuwa wazi mchana wote; maana hakutakuwa na usiku humo.'),
(2021646,69,66,21,26,'Fahari na utajiri wa watu wa mataifa utaletwa humo ndani.'),
(2021647,69,66,21,27,'Lakini hakuna chochote kilicho najisi kitakachoingia humo; wala mtu yeyote atendaye mambo ya kuchukiza au ya uongo hataingia humo. Ni wale tu walioandikwa katika kitabu cha uzima cha Mwanakondoo ndio watakaoingia ndani.'),
(2021648,69,66,22,1,'Kisha malaika akanionyesha mto wa maji ya uzima maangavu kama kioo yakitoka kwenye kiti cha enzi cha Mungu na Mwanakondoo.'),
(2021649,69,66,22,2,'Mto huo ulitiririka kupitia katikati ya barabara kuu ya mji. Kandokando ya mto huo kulikuwa na mti wa uzima unaozaa matunda mara kumi na mbili kwa mwaka, yaani kila mwezi; na majani yake ni dawa ya kuwaponya watu wa mataifa.'),
(2021650,69,66,22,3,'Hapana kitu chochote kilicholaaniwa kitakachokuwa katika mji huo. Kiti cha enzi cha Mungu na cha Mwanakondoo kitakuwa katika mji huo, na watumishi wake watamwabudu.'),
(2021651,69,66,22,4,'Watauona uso wake, na jina lake litaandikwa juu ya paji za nyuso zao.'),
(2021652,69,66,22,5,'Usiku hautakuwako tena, wala hawatahitaji mwanga wa taa au wa jua, maana Bwana Mungu atawaangazia, nao watatawala milele na milele.'),
(2021653,69,66,22,6,'Kisha malaika akaniambia, "Maneno haya ni ya kweli na ya kuaminika. Bwana Mungu ambaye huwapa manabii Roho wake, alimtuma malaika wake awaonyeshe watumishi wake mambo ambayo lazima yatukie punde.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2021654,69,66,22,7,'"Sikiliza! Naja upesi. Heri yake anayeyazingatia maneno ya unabii yaliyo katika kitabu hiki."'),
(2021655,69,66,22,8,'Mimi Yohane, niliyaona na kusikia mambo haya. Nilipokwisha sikia na kuona nikajitupa chini mbele ya miguu ya huyo malaika aliyenionyesha mambo hayo, nikataka kumwabudu.'),
(2021656,69,66,22,9,'Lakini yeye akaniambia, "Acha! Mimi ni mtumishi tu kama wewe na ndugu zako manabii na wote wanaoyatii maagizo yaliyomo katika kitabu hiki. Mwabudu Mungu!"'),
(2021657,69,66,22,10,'Tena akaniambia, "Usiyafiche kama siri maneno ya unabii yaliyomo katika kitabu hiki, maana wakati wa kutimizwa kwake umekaribia.'),
(2021658,69,66,22,11,'Kwa sasa anayetenda mabaya na aendelee kutenda mabaya, na aliye mchafu aendelee kuwa mchafu. Mwenye kutenda mema na azidi kutenda mema, na aliye mtakatifu na azidi kuwa mtakatifu."'),
(2021659,69,66,22,12,'"Sikiliza!" Asema Yesu, "Naja upesi, pamoja na tuzo nitakalompa kila mmoja kufuatana na matendo yake.'),
(2021660,69,66,22,13,'Mimi ni Alfa na Omega, Mwanzo na Mwisho, wa kwanza na wa mwisho."'),
(2021661,69,66,22,14,'Heri yao wale wanaoosha mavazi yao, kwani watakuwa na haki ya kula tunda la mti wa uzima, na haki ya kuingia mjini kwa kupitia milango yake.'),
(2021662,69,66,22,15,'Lakini mbwa, wachawi, wazinzi, wauaji, waabudu sanamu na wote wanaopenda kusema uongo, watakaa nje ya mji.'),
(2021663,69,66,22,16,'"Mimi, Yesu, nimemtuma malaika wangu awathibitishieni mambo haya katika makanisa. Mimi ni mzawa wa ukoo wa Daudi. Mimi ni nyota angavu ya asubuhi!"'),
(2021664,69,66,22,17,'Roho na Bibiarusi waseme, "Njoo!" Kila mtu asikiaye hili, na aseme,"Njoo!" Kisha, yeyote aliye na kiu na aje; anayetaka maji ya uzima na apokee bila malipo yoyote.'),
(2021665,69,66,22,18,'Mimi Yohane nawapa onyo wote wanaosikia maneno ya unabii yaliyomo katika kitabu hiki: mtu yeyote akiongeza chochote katika mambo haya, Mungu atamwongezea mabaa yaliyoandikwa katika kitabu hiki.'),
(2021666,69,66,22,19,'Na mtu yeyote akipunguza chochote katika maneno ya unabii yaliyomo katika kitabu hiki, Mungu atamnyang`anya sehemu yake katika ule mti wa uzima, na sehemu yake katika mji mtakatifu, ambavyo vimeelezwa katika kitabu hiki.'),
(2021667,69,66,22,20,'Naye anayetoa ushahidi wake juu ya mambo haya asema: "Naam! Naja upesi." Amina. Na iwe hivyo! Njoo Bwana Yesu!'),
(2021668,69,66,22,21,'Nawatakieni nyote neema ya Bwana Yesu. Amen.');
